#include <stdlib.h>
#include <stdio.h>

typedef struct DataPacket {
    int packet_id;
    long timestamp;
    size_t payload_size;
} DataPacket;

typedef struct DynamicArray {
    DataPacket* data;
    size_t size;
    size_t capacity;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    free(array->data);
    free(array);
}

void add_packet(DynamicArray* array, DataPacket packet) {
    if (array->size == array->capacity) {
        array->capacity = (array->capacity == 0) ? 1 : array->capacity * 2;
        array->data = realloc(array->data, array->capacity * sizeof(DataPacket));
    }
    array->data[array->size++] = packet;
}

void remove_packet(DynamicArray* array, int packet_id) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].packet_id == packet_id) {
            for (size_t j = i; j < array->size - 1; ++j) {
                array->data[j] = array->data[j + 1];
            }
            --array->size;
            break;
        }
    }
}

int get_packet_count(DynamicArray* array) {
    return array->size;
}

void sort_packets_by_timestamp(DynamicArray* array) {
    qsort(array->data, array->size, sizeof(DataPacket), 
          (int (*)(const void *, const void *))compare_timestamps);
}

int compare_timestamps(const void *a, const void *b) {
    return ((DataPacket*)a)->timestamp - ((DataPacket*)b)->timestamp;
}
