#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

void initializeArrays(long** offsets, int** keys, Record** records, size_t count) {
    *offsets = (long*)malloc(count * sizeof(long));
    *keys = (int*)malloc(count * sizeof(int));
    *records = (Record*)calloc(count, sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        (*offsets)[i] = i * 10;
        (*keys)[i] = i % 100;
    }
}

void populateRecords(Record* records, size_t count, int minVal, int maxVal) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (maxVal - minVal + 1) + minVal;
    }
}

void persistRecordsToFile(const char* filename, Record* records, size_t count) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    size_t written = fwrite(records, sizeof(Record), count, file);
    if (written != count) {
        perror("Error writing records to file");
    } else {
        printf("Records written successfully\n");
    }

    fclose(file);
}

int main() {
    const size_t MAX_RECORDS = 100000;
    long* offsets;
    int* keys;
    Record* records;

    initializeArrays(&offsets, &keys, &records, MAX_RECORDS);
    populateRecords(records, MAX_RECORDS, 10, 1000);

    persistRecordsToFile("data.bin", records, MAX_RECORDS);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
