#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024

void print_usage_info() {
    printf("Usage: program_name --manpage | -cs delimiter [-o output_file] input_files...\n");
}

int process_file(const char* filename, const char* delimiter, const char* output_filename) {
    FILE* infile = fopen(filename, "r");
    if (!infile) {
        perror("Error opening file");
        return 1;
    }

    FILE* outfile = NULL;
    if (output_filename) {
        outfile = fopen(output_filename, "a");
        if (!outfile) {
            perror("Error opening output file");
            fclose(infile);
            return 1;
        }
    }

    char line[MAX_LINE_LENGTH];
    size_t num_lines = 0;

    while (fgets(line, sizeof(line), infile)) {
        // Check for comment lines
        if (strncmp(line, delimiter, strlen(delimiter)) != 0) {
            num_lines++;
            if (outfile) {
                fprintf(outfile, "Line %zu: %s", num_lines, line);
            } else {
                printf("Line %zu: %s", num_lines, line);
            }
        }
    }

    fclose(infile);
    if (outfile) {
        fclose(outfile);
    }

    return 0;
}

int main(int argc, char* argv[]) {
    const char* delimiter = "#"; // Default delimiter for comments
    const char* output_filename = NULL;
    int process_manpage = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            print_usage_info();
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0 && i + 1 < argc) {
            delimiter = argv[++i];
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_filename = argv[++i];
        } else if (argv[i][0] != '-') {
            // Process the input file
            process_file(argv[i], delimiter, output_filename);
        }
    }

    return 0;
}
