void process_log_file(const char *input_file, const char *output_file, const char *filter_criteria, int top_events) {
    FILE *log_file = fopen(input_file, "r");
    if (!log_file) {
        perror("Failed to open input file");
        return;
    }

    // Read and parse events from log_file
    Event **events = NULL;
    size_t event_count = 0;

    // Dummy parsing loop (replace with actual logic)
    for (;;) {
        char *line = NULL;
        size_t len = 0;
        ssize_t read = getline(&line, &len, log_file);
        if (read == -1) break;

        // Filter and store events based on criteria
        if (strstr(line, filter_criteria)) {
            Event *new_event = malloc(sizeof(Event));
            new_event->timestamp = strdup(strtok(line, " "));
            new_event->event_type = strdup(strtok(NULL, " "));
            new_event->severity = atoi(strtok(NULL, " "));
            events = realloc(events, (event_count + 1) * sizeof(Event *));
            events[event_count++] = new_event;
        }
    }

    fclose(log_file);

    // Sort events by severity
    qsort(events, event_count, sizeof(Event *), compare_events);

    // Write top 'top_events' to output_file
    FILE *summary_file = fopen(output_file, "w");
    if (!summary_file) {
        perror("Failed to open output file");
        return;
    }

    for (int i = 0; i < event_count && i < top_events; i++) {
        fprintf(summary_file, "%s %s %d\n", events[i]->timestamp, events[i]->event_type, events[i]->severity);
        free(events[i]->timestamp);
        free(events[i]->event_type);
        free(events[i]);
    }

    fclose(summary_file);
    free(events);
}
