typedef struct {
    char hostname[MAX_IP_LEN];
    u_char ip[4];
} DNSRequest;

DNSRequest queue[QUEUE_SIZE];
int front = -1, rear = -1;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void enqueue(DNSRequest request) {
    if (rear == QUEUE_SIZE - 1)
        printf("Queue is full\n");
    else {
        if (front == -1)
            front = 0;
        queue[++rear] = request;
    }
}

DNSRequest dequeue() {
    DNSRequest request;
    if (front == -1)
        printf("Queue is empty\n");
    else {
        request = queue[front++];
        if (front > rear) {
            front = -1;
            rear = -1;
        }
    }
    return request;
}

int resolve_hostname(const char *hostname, u_char ip[]) {
    struct hostent *h;
    int i;

    h = gethostbyname(hostname);
    if (h == NULL) {
        perror("gethostbyname");
        return -1;
    }

    for (i = 0; h->h_addr_list[i] != NULL; i++) {
        memcpy(ip, h->h_addr_list[i], 4);
        return 0;
    }
    return -1;
}

int is_ip_allowed(const u_char ip[]) {
    // Implement IP range whitelisting logic here
    return 1; // Placeholder for allowed IPs
}

void *dns_worker(void *arg) {
    while (1) {
        DNSRequest request = dequeue();
        if (request.hostname[0] == '\0')
            break;

        u_char ip[4];
        int result = resolve_hostname(request.hostname, ip);
        if (result != 0) {
            FILE *log = fopen(LOG_FILE, "a");
            fprintf(log, "Failed resolution for %s\n", request.hostname);
            fclose(log);
        } else if (is_ip_allowed(ip)) {
            // Return the resolved IP address to the caller
            printf("Resolved IP: %d.%d.%d.%d for %s\n",
                   ip[0], ip[1], ip[2], ip[3], request.hostname);

            FILE *log = fopen(LOG_FILE, "a");
            fprintf(log, "Successful resolution for %s: %d.%d.%d.%d\n",
                    request.hostname, ip[0], ip[1], ip[2], ip[3]);
            fclose(log);
        } else {
            printf("IP address not allowed: %d.%d.%d.%d for %s\n",
                   ip[0], ip[1], ip[2], ip[3], request.hostname);

            FILE *log = fopen(LOG_FILE, "a");
            fprintf(log, "Blocked resolution for %s: %d.%d.%d.%d\n",
                    request.hostname, ip[0], ip[1], ip[2], ip[3]);
            fclose(log);
        }
    }
    return NULL;
}

int main() {
    pthread_t threads[5];
    int i;

    // Initialize DNS workers
    for (i = 0; i < 5; i++)
        pthread_create(&threads[i], NULL, dns_worker, NULL);

    // Enqueue DNS resolution requests
    enqueue((DNSRequest){"google.com", {0}});
    enqueue((DNSRequest){"example.com", {0}});
    enqueue((DNSRequest){"notallowedip.com", {0}});

    // Wait for all workers to finish
    for (i = 0; i < 5; i++)
        pthread_join(threads[i], NULL);

    return 0;
}
