#include <stdio.h>
#include <stdlib.h>

int findLargest(int *arr, int size) {
    if (size <= 0) return -1; // Assuming no valid integer for an empty array
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if ((max > INT_MAX - arr[i]) || (arr[i] > INT_MAX - max)) { // Check for potential overflow
            printf("Integer overflow detected.\n");
            return -1;
        }
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

int main() {
    int size, *arr;

    printf("Enter the number of integers: ");
    if (scanf("%d", &size) != 1 || size < 0) {
        printf("Invalid input detected.\n");
        return -1;
    }

    arr = (int *)malloc(size * sizeof(int));
    if (!arr) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    printf("Enter the integers: ");
    for (int i = 0; i < size; i++) {
        if (scanf("%d", &arr[i]) != 1) {
            printf("Invalid input detected.\n");
            free(arr);
            return -1;
        }
    }

    int largest = findLargest(arr, size);
    if (largest == -1 && arr[0] == 0) { // Check for "No integers provided" condition
        printf("No integers provided.\n");
    } else {
        printf("The largest integer is: %d\n", largest);
    }

    free(arr);
    return 0;
}
