#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>

#define MAX_LOG_SIZE 1024

typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef struct {
    int file_fd;
    char *network_address;
    int network_port;
} LogConfig;

void log_message_with_conditions(LogConfig *config, LogLevel level, const char *format, ...) {
    va_list args;
    char message[MAX_LOG_SIZE];
    va_start(args, format);
    vsnprintf(message, sizeof(message), format, args);
    va_end(args);

    if (level >= config->log_level) {
        if (config->file_fd != -1) {
            write(config->file_fd, message, strlen(message));
        }
        if (config->network_address != NULL && config->network_port > 0) {
            int sock = socket(AF_INET, SOCK_DGRAM, 0);
            struct sockaddr_in server_addr;
            server_addr.sin_family = AF_INET;
            server_addr.sin_port = htons(config->network_port);
            inet_pton(AF_INET, config->network_address, &server_addr.sin_addr);
            sendto(sock, message, strlen(message), 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
            close(sock);
        }
    }
}

int main() {
    LogConfig config = { -1, "127.0.0.1", 5000, LOG_INFO };
    log_message_with_conditions(&config, LOG_INFO, "This is an info message");
    return 0;
}
