bool validate_oauth2_token(const char *json_str) {
    json_object *root = json_tokener_parse(json_str);
    if (!root || !json_is_object(root)) {
        return false;
    }

    json_object *access_token, *expires_in, *token_type, *refresh_token;
    if (json_object_object_get_ex(root, "access_token", &access_token) &&
        json_object_object_get_ex(root, "expires_in", &expires_in) &&
        json_object_object_get_ex(root, "token_type", &token_type)) {

        int expires_val = 0;
        const char *type_str = NULL;

        if (json_is_string(access_token) &&
            json_is_int(expires_in) &&
            json_is_string(token_type) &&
            (refresh_token = json_object_object_get_ex(root, "refresh_token", &refresh_token)) &&
            json_is_string(refresh_token)) {

            expires_val = json_object_get_int(expires_in);
            type_str = json_object_get_string(token_type);

            if (!strcmp(type_str, "Bearer") && expires_val > 0) {
                return true;
            }
        }
    }

    json_object_put(root);
    return false;
}

CipherConfig* get_cipher_config(const char *cipher_name) {
    CipherConfig *config = malloc(sizeof(CipherConfig));
    config->cipher = NULL;

    if (strcmp(cipher_name, "NULL") == 0) {
        config->cipher = EVP_enc_null();
    } else if (strcmp(cipher_name, "DES-ECB") == 0) {
        config->cipher = EVP_des_ecb();
    } else if (strcmp(cipher_name, "3DES-EDE") == 0) {
        config->cipher = EVP_3des_ede();
    } else if (strcmp(cipher_name, "3DES-EDE3") == 0) {
        config->cipher = EVP_3des_ede3();
    } else if (strcmp(cipher_name, "DES-CFB") == 0) {
        config->cipher = EVP_des_cfb();
    }

    return config;
}
