import java.util.List;
import java.util.Set;
import java.util.Map;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.stream.Collectors;

public class PokemonReportGenerator {
    private static final Map<String, Set<String>> typeWeaknesses = loadTypeWeaknessesFromConfig();

    public static String generateDetailedReport(Pokemon pokemon) {
        StringBuilder reportBuilder = new StringBuilder();
        reportBuilder.append("Pokemon Name: ").append(pokemon.getName()).append("\n");
        reportBuilder.append("Types: ").append(String.join(", ", pokemon.getTypes())).append("\n");

        Set<String> allWeaknesses = pokemon.getTypes().stream()
            .flatMap(type -> typeWeaknesses.getOrDefault(type, Set.of()).stream())
            .collect(Collectors.toSet());

        reportBuilder.append("Weaknesses: ").append(String.join(", ", allWeaknesses)).append("\n");

        return reportBuilder.toString();
    }

    private static Map<String, Set<String>> loadTypeWeaknessesFromConfig() {
        try {
            File config = new File("path/to/config/file.txt");
            List<String> lines = Files.readAllLines(config.toPath());
            Map<String, Set<String>> weaknessesMap = lines.stream()
                .map(line -> line.split("="))
                .collect(Collectors.toMap(
                    parts -> parts[0].trim(),
                    parts -> Set.of(parts[1].split(",\\s*"))
                ));
            return weaknessesMap;
        } catch (IOException e) {
            throw new RuntimeException("Failed to load type weaknesses from config file", e);
        }
    }

    public static void main(String[] args) {
        // Example usage
        Pokemon examplePokemon = new Pokemon("Pikachu", List.of("Electric"));
        String report = generateDetailedReport(examplePokemon);
        System.out.println(report);
    }
}

class Pokemon {
    private String name;
    private List<String> types;

    public Pokemon(String name, List<String> types) {
        this.name = name;
        this.types = types;
    }

    public String getName() {
        return name;
    }

    public List<String> getTypes() {
        return types;
    }
}
```

