#include <pthread.h>
#include <stdlib.h>

typedef struct {
    int* items;
    size_t head;
    size_t tail;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} ThreadSafeQueue;

ThreadSafeQueue* tsqueue_init(size_t capacity) {
    ThreadSafeQueue* queue = (ThreadSafeQueue*)malloc(sizeof(ThreadSafeQueue));
    if (!queue) return NULL;

    queue->items = (int*)malloc(capacity * sizeof(int));
    if (!queue->items) {
        free(queue);
        return NULL;
    }

    queue->head = 0;
    queue->tail = 0;
    queue->capacity = capacity;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);

    return queue;
}

void tsqueue_destroy(ThreadSafeQueue* queue) {
    free(queue->items);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->not_full);
    pthread_cond_destroy(&queue->not_empty);
    free(queue);
}

void enqueue(ThreadSafeQueue* queue, int item) {
    pthread_mutex_lock(&queue->mutex);
    while ((queue->tail + 1) % queue->capacity == queue->head)
        pthread_cond_wait(&queue->not_full, &queue->mutex);

    queue->items[queue->tail] = item;
    queue->tail = (queue->tail + 1) % queue->capacity;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->mutex);
}

int dequeue(ThreadSafeQueue* queue) {
    int item;
    pthread_mutex_lock(&queue->mutex);
    while (queue->head == queue->tail)
        pthread_cond_wait(&queue->not_empty, &queue->mutex);

    item = queue->items[queue->head];
    queue->head = (queue->head + 1) % queue->capacity;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->mutex);
    return item;
}
