fn process_file(file_path: &str, thread_pool_size: usize) -> Option<String> {
    let parsed_nodes = match lexer_and_parser(file_path) {
        Ok(nodes) => nodes,
        Err(_) => return None,
    };

    let mut llvm_ir_code = String::new();
    for node in parsed_nodes {
        llvm_ir_code.push_str(&generate_llvm_ir(node.as_str()));
    }

    Some(llvm_ir_code)
}

fn file_queue_processor(file_paths: Vec<&str>, thread_pool_size: usize) -> Vec<String> {
    let queue = Arc::new(Mutex::new(VecDeque::new()));
    let results = Arc::new(Mutex::new(vec![]));
    let error_handling_strategy = "graceful"; // Placeholder strategy

    for file_path in file_paths {
        queue.lock().unwrap().push_back(file_path);
    }

    let num_threads = thread_pool_size;
    let mut handles = vec![];

    for _ in 0..num_threads {
        let queue = Arc::clone(&queue);
        let results = Arc::clone(&results);

        let handle = thread::spawn(move || loop {
            let file_path = {
                let mut guard = queue.lock().unwrap();
                if let Some(path) = guard.pop_front() {
                    path
                } else {
                    break;
                }
            };

            if let Some(llvm_ir) = process_file(file_path, num_threads) {
                results.lock().unwrap().push(llvm_ir);
            } else {
                eprintln!("Error processing file: {}", file_path);
            }
        });

        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    let mut final_results = vec![];
    while let Some(result) = results.lock().unwrap().pop() {
        final_results.push(result);
    }

    final_results
}

fn main() {
    let file_paths = vec![
        "path/to/file1.txt",
        "path/to/file2.txt",
        // Add more file paths as needed
    ];

    let thread_pool_size = 4;
    let start_time = Instant::now();

    let results = file_queue_processor(file_paths, thread_pool_size);

    for llvm_ir in results {
        println!("Generated LLVM IR:\n{}", llvm_ir);
    }

    let elapsed_time = start_time.elapsed();
    println!("Total processing time: {:?}", elapsed_time);
}
