#include <forward_list>
#include <iostream>

void insertAfterOrAtEnd(std::forward_list<int>& flist, int target, int toInsert) {
    auto it = flist.begin();
    bool found = false;

    while (it != flist.end()) {
        if (*it == target) {
            flist.insert_after(it, toInsert);
            found = true;
            break;
        }
        ++it;
    }

    if (!found) {
        flist.push_back(toInsert);
    }
}

int main() {
    std::forward_list<int> mylist = {10, 20, 30};
    insertAfterOrAtEnd(mylist, 20, 25);
    for (const auto& elem : mylist) {
        std::cout << elem << " ";
    }
    return 0;
}
