            logging::core::get()->add_global_attribute("TimeStamp", logging::attributes::local_clock());
            logging::register_simple_formatter_factory<logging::trivial::severity_level, char>("Severity");
            logging::core::get()->set_filter(
                logging::trivial::severity >= logging::trivial::info
            );
        }

        ~Logger() {}

        static void setVerbosity(logging::trivial::severity_level level) {
            logging::core::get()->set_filter(
                logging::trivial::severity >= level
            );
        }

        static void logInfo(const std::string& message) {
            BOOST_LOG_TRIVIAL(info) << message;
        }

        static void logWarning(const std::string& message) {
            BOOST_LOG_TRIVIAL(warning) << message;
        }

        static void logError(const std::string& message) {
            BOOST_LOG_TRIVIAL(error) << message;
        }
    };
}

int main() {
    logger_ns::Logger logger;

    std::cout << "Choose logging level (info, warning, error): ";
    std::string levelStr;
    std::cin >> levelStr;

    logger_ns::logging::trivial::severity_level level;
    if (levelStr == "info") {
        level = logger_ns::logging::trivial::info;
    } else if (levelStr == "warning") {
        level = logger_ns::logging::trivial::warning;
    } else if (levelStr == "error") {
        level = logger_ns::logging::trivial::error;
    } else {
        std::cerr << "Invalid logging level" << std::endl;
        return 1;
    }

    logger_ns::Logger::setVerbosity(level);

    logger_ns::Logger::logInfo("This is an info message");
    logger_ns::Logger::logWarning("This is a warning message");
