['```csharp
using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class SqlBatchExecutor
{
    public static async Task<ExecutionSummary> ExecuteSqlCommandsAsync(
        List<string> sqlCommands, 
        SqlConnection connection, 
        bool executeTransactionsAtomically = false)
    {
        var summary = new ExecutionSummary();
        using (var transaction = executeTransactionsAtomically ? connection.BeginTransaction() : null)
        {
            try
            {
                foreach (var command in sqlCommands)
                {
                    int retries = 0;
                    while (retries < 4) // Retry up to 3 times, plus the initial attempt
                    {
                        SqlCommand sqlCommand = new SqlCommand(command, connection);
                        if (executeTransactionsAtomically)
                        {
                            sqlCommand.Transaction = transaction;
                        }

                        try
                        {
                            await sqlCommand.ExecuteNonQueryAsync();
                            summary.SuccessCount++;
                            break; // Break on successful execution
                        }
                        catch (SqlException ex)
                        {
                            retries++;
                            if (retries >= 4)
                            {
                                summary.FailedCommands.Add(new CommandExecutionResult(command, false, ex.Message));
                                break;
                            }
                            else
                            {
                                await Task.Delay(100 * retries); // Simple exponential backoff
                            }
                        }
                    }
                }

                if (executeTransactionsAtomically)
                {
                    transaction.Commit();
                }
            }
            catch (Exception ex)
            {
                summary.FailedCommands.Add(new CommandExecutionResult("", false, ex.Message));
                if (executeTransactionsAtomically && transaction != null)
                {
                    transaction.Rollback();
                }
            }
        }

        return summary;
    }
}

public class ExecutionSummary
{
    public int SuccessCount { get; set; } = 0;
    public List<CommandExecutionResult> FailedCommands { get; set; } = new List<CommandExecutionResult>();
}

public class CommandExecutionResult
{
    public string Command { get; set; }
    public bool Success { get; set; }
    public string ErrorMessage { get; set; }

    public CommandExecutionResult(string command, bool success, string errorMessage)
    {
        Command = command;
        Success = success;
        ErrorMessage = errorMessage;
    }
}
```

This code defines a `SqlBatchExecutor` class with a static method `ExecuteSqlCommandsAsync` that executes a batch of SQL commands asynchronously. The method handles transactions, retries for failed commands, and provides execution summaries. It also includes logging for each command's status and supports concurrent processing through async/await.']

