using Microsoft.AspNetCore.Mvc;
using System.Collections.Generic;
using System.Linq;

[Route("api/[controller]")]
[ApiController]
public class UserProfileController : ControllerBase
{
    private static Dictionary<string, UserProfile> _profiles = new Dictionary<string, UserProfile>();
    private static readonly object _lock = new object();

    [HttpPut("{id}")]
    public IActionResult UpdateProfile(string id, [FromBody] UserProfile profile)
    {
        lock (_lock)
        {
            if (!_profiles.ContainsKey(id))
                return NotFound();

            var existingProfile = _profiles[id];
            existingProfile.Name = profile.Name;
            existingProfile.Email = profile.Email;

            _profiles[id] = existingProfile;

            return NoContent();
        }
    }

    [HttpPatch("{id}/archive")]
    public IActionResult ArchiveProfile(string id)
    {
        lock (_lock)
        {
            if (!_profiles.ContainsKey(id))
                return NotFound();

            var profileToArchive = _profiles[id];
            profileToArchive.IsActive = false;

            var archivedProfilesSummary = new
            {
                Id = id,
                Name = profileToArchive.Name,
                Email = profileToArchive.Email,
                IsActive = profileToArchive.IsActive
            };

            return Ok(archivedProfilesSummary);
        }
    }

    public class UserProfile
    {
        public string Id { get; set; }
        public string Name { get; set; }
        public string Email { get; set; }
        public bool IsActive { get; set; } = true;
    }
}
