using System;
using System.Collections.Generic;
using System.Xml.XPath;

public class XmlParser
{
    public List<XPathNavigator> GetElementsByXPath(string xml, string xPathExpression)
    {
        List<XPathNavigator> matchingElements = new List<XPathNavigator>();
        try
        {
            XPathDocument document = new XPathDocument(xml);
            XPathNavigator navigator = document.CreateNavigator();

            XPathNodeIterator iterator = navigator.Select(xPathExpression);
            while (iterator.MoveNext())
            {
                if (matchingElements.Count > 0)
                {
                    throw new InvalidOperationException("More than one element matches the criteria.");
                }
                matchingElements.Add(iterator.Current.Clone());
            }
        }
        catch (XPathException ex)
        {
            throw new ArgumentException("Invalid XPath expression.", nameof(xPathExpression), ex);
        }
        catch (XmlException ex)
        {
            throw new ArgumentException("Malformed XML.", nameof(xml), ex);
        }

        return matchingElements;
    }
}
```

