import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.logging.Logger;

public class StringConcatenator {
    private static final Logger logger = Logger.getLogger(StringConcatenator.class.getName());

    public static void main(String[] args) {
        // Example usage:
        var result = concatenateAndHash("Hello", "World", null, "Java");
        System.out.println(result);
    }

    /**
     * Concatenates a variable number of strings and returns the concatenated string along with its MD5 hash.
     * Handles null inputs gracefully and logs each operation.
     *
     * @param strings The strings to concatenate.
     * @return A string containing the concatenated value and its MD5 hash.
     */
    public static String concatenateAndHash(String... strings) {
        StringBuilder sb = new StringBuilder();
        for (String str : strings) {
            if (str != null) {
                sb.append(str);
            } else {
                logger.warning("Null input encountered while concatenating.");
            }
        }

        String concatenated = sb.toString();
        String md5Hash = getMD5Hash(concatenated);

        long operationTime = System.currentTimeMillis();
        int length = concatenated.length();

        logger.info(String.format("Operation performed at %d. Concatenated string length: %d", operationTime, length));

        return concatenated + "|" + md5Hash;
    }

    /**
     * Computes the MD5 hash of a given string.
     *
     * @param input The string to hash.
     * @return The MD5 hash as a hexadecimal string.
     */
    private static String getMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
}
