const fs = require('fs').promises;
const path = require('path');
const cache = new Map();
const logger = require('./logger'); // Assuming a logging system is already implemented

async function readFile(filePath) {
    try {
        if (cache.has(filePath)) {
            const cachedFile = cache.get(filePath);
            if (!cachedFile.expired) {
                return cachedFile.contents;
            }
        }

        let contents = await fs.readFile(filePath, 'utf8');
        let lastModified = (await fs.stat(filePath)).mtimeMs;

        cache.set(filePath, {
            contents,
            lastModified,
            expired: false
        });

        logger.log('readFile', filePath);

        return contents;
    } catch (error) {
        logger.error('readFileError', error);
        throw error;
    }
}

function invalidateCache(filePath) {
    if (cache.has(filePath)) {
        cache.get(filePath).expired = true;
    }
}
