function runTests(modulePath, testCases, maxConcurrency) {
    const results = [];
    let currentConcurrency = 0;

    function executeTest(testCase) {
        return new Promise((resolve, reject) => {
            blueslip.reset(); // Reset blueslip before each test
            console.log(`Starting test ${testCase.label} at ${new Date()}`);
            testCase.f().then(() => {
                results.push({ label: testCase.label, passed: true });
                resolve();
            }).catch(error => {
                results.push({ label: testCase.label, passed: false, error: error.message });
                resolve();
            });
        });
    }

    async function runTestsConcurrently(testCases) {
        for (const testCase of testCases) {
            if (currentConcurrency < maxConcurrency) {
                currentConcurrency++;
                const result = await executeTest(testCase);
                currentConcurrency--;
            } else {
                await new Promise(resolve => setTimeout(resolve, 100)); // Wait a bit and try again
                runTestsConcurrently([testCase]);
            }
        }
    }

    return runTestsConcurrently(testCases).then(() => results);
}

// Example usage:
const testModulePath = './path/to/tests';
const testCases = [
    { label: 'test1', f: () => Promise.resolve('Test 1 passed') },
    { label: 'test2', f: () => Promise.reject('Test 2 failed') }
];
const maxConcurrency = 2;

runTests(testModulePath, testCases, maxConcurrency).then(results => {
    console.log('Test results:', results);
});
