// Load configuration file for valid Old Testament books
const config = require('./bibleConfig.json');

function countBookReferences(text) {
    const bookRegex = new RegExp(`\\b(${Object.keys(config.oldTestament).join('|')})\\b`, 'gi');
    let matches = text.match(bookRegex);
    if (!matches) return {};

    let counts = {};
    matches.forEach(match => {
        match = match.toLowerCase();
        counts[match] = (counts[match] || 0) + 1;
    });

    return counts;
}

