function generateSidebarMenu(configs) {
  const sidebarHtml = configs.map(config => `
    <div class="sidebar-section" data-section-id="${config.sectionId}">
      <i class="icon ${config.icon}"></i>
      <h3>${config.title}</h3>
      <ul>
        ${config.links.map(link => `
          <li><a href="${link.url}" target="_blank">${link.text}</a></li>
        `).join('')}
      </ul>
    </div>
  `).join('');

  return `
    <nav class="sidebar">
      ${sidebarHtml}
    </nav>
    <script>
      document.addEventListener('DOMContentLoaded', function() {
        const sidebarSections = document.querySelectorAll('.sidebar-section');
        sidebarSections.forEach(section => {
          section.addEventListener('click', function() {
            if (section.classList.contains('active')) {
              section.classList.remove('active');
            } else {
              sidebarSections.forEach(s => s.classList.remove('active'));
              section.classList.add('active');
            }
          });
        });
      });
    </script>
  `;
}
