class DataCollector {
  constructor() {
    this.data = [];
    this.paused = false;
    this.vertexCount = 0;
    this.edgeCount = 0;
  }

  collect(data) {
    if (!this.paused) {
      this.data.push(data);
    }
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
  }

  addRandomVertices(count) {
    for (let i = 0; i < count; i++) {
      const vertexId = `v${this.vertexCount++}`;
      this.data.push({ type: 'vertex', id: vertexId, properties: this.generateRandomProperties() });
    }
  }

  addRandomEdges(count) {
    for (let i = 0; i < count; i++) {
      const sourceId = `v${Math.floor(Math.random() * this.vertexCount)}`;
      const targetId = `v${Math.floor(Math.random() * this.vertexCount)}`;
      while (sourceId === targetId) {
        targetId = `v${Math.floor(Math.random() * this.vertexCount)}`;
      }
      const edgeId = `${sourceId}-${targetId}`;
      this.data.push({ type: 'edge', id: edgeId, source: sourceId, target: targetId, properties: this.generateRandomProperties() });
    }
  }

  generateRandomProperties() {
    return Object.fromEntries(
      Array.from({ length: Math.floor(Math.random() * 5) + 1 }, () => [
        `prop${Math.random().toString(36).substr(2, 5)}`,
        Math.random()
      ])
    );
  }
}

const collector = new DataCollector();
collector.collect('Initial data');
collector.pause();
collector.addRandomVertices(3);
collector.resume();
collector.addRandomEdges(2);
console.log(collector.data);
