["```javascript
function copyBufferedData(inputChunks, startOffset, numBytes) {
  if (typeof inputChunks !== 'object' || !Array.isArray(inputChunks)) {
    throw new Error('Input chunks must be an array of buffers');
  }

  if (startOffset < 0 || numBytes < 0) {
    throw new Error('Start offset and number of bytes must be non-negative integers');
  }

  const targetBuffer = Buffer.alloc(numBytes);
  let bytesRead = 0;

  for (let i = 0; i < inputChunks.length && bytesRead < numBytes; i++) {
    const chunk = inputChunks[i];
    if (chunk instanceof Buffer) {
      const availableBytes = Math.min(chunk.length - startOffset, numBytes - bytesRead);
      chunk.copy(targetBuffer, bytesRead, startOffset, startOffset + availableBytes);
      bytesRead += availableBytes;
      startOffset = 0; // Reset offset for the next chunk
    } else {
      throw new Error('Input chunks must contain only Buffer objects');
    }
  }

  if (bytesRead < numBytes) {
    throw new Error('Insufficient data in input chunks to fulfill request');
  }

  return targetBuffer;
}
