function traverseAndSelectElements(rootNode, criteria) {
    const result = [];

    function dfs(node) {
        if (!node) return;

        try {
            for (const key in criteria) {
                const value = criteria[key];
                let match = false;
                switch (key) {
                    case 'attribute':
                        match = node.getAttribute(value[0]) === value[1];
                        break;
                    case 'dataAttribute':
                        match = node.getAttribute(`data-${value[0]}`) === value[1];
                        break;
                    // Add more cases for additional criteria
                }
                if (!match) return; // Early exit if any criterion does not match
            }

            result.push(node);
        } catch (e) {
            console.error('Error during traversal:', e);
        }

        node.childNodes.forEach(dfs);
    }

    dfs(rootNode);
    return result;
}

