["```javascript
class ScriptLoader {
    constructor(fileDependencies) {
        this.fileDependencies = fileDependencies;
        this.loadedScripts = new Set();
        this.scriptQueue = [];
    }

    loadScript(url, callback) {
        const script = document.createElement('script');
        script.src = url;
        script.onload = () => {
            callback(null);
        };
        script.onerror = (error) => {
            callback(error);
        };
        document.head.appendChild(script);
    }

    resolveDependencies() {
        for (const [file, dependencies] of Object.entries(this.fileDependencies)) {
            if (!dependencies.some(dep => !this.loadedScripts.has(dep))) {
                this.scriptQueue.push(file);
            }
        }
    }

    executeScripts() {
        if (this.scriptQueue.length === 0) {
            console.log('All scripts executed successfully.');
            return;
        }

        const file = this.scriptQueue.shift();
        this.loadScript(file, (error) => {
            if (error) {
                console.error(`Failed to load script: ${file}`, error);
            } else {
                this.loadedScripts.add(file);
                console.log(`Executed script: ${file}`);
            }
            this.executeScripts();
        });
    }

    startLoading() {
        this.resolveDependencies();
        this.executeScripts();
    }
}

// Example usage:
const fileDependencies = {
    'script1.js': [],
    'script2.js': ['script1.js'],
    'script3.js': ['script1.js', 'script2.js'],
    'script4.js': []
};

const loader = new ScriptLoader(fileDependencies);
loader.startLoading();
```

This code defines a `ScriptLoader` class that manages the loading and execution of JavaScript files in a web application. It handles dependencies between files, loads scripts asynchronously, and executes them in the correct order while managing errors gracefully. The example usage demonstrates how to set up file dependencies and start the loading process."]

['```java
import java.util.List;
import java.util.HashSet;
import java.util.Set;
import java.util.Timer;
import java.util.TimerTask;

class TrieNode {
    boolean isEndOfWord;
    TrieNode[] children;

    public TrieNode() {
        this.isEndOfWord = false;
        this.children = new TrieNode[26];
    }
}

public class SubstringPairs {

    private static TrieNode root;

    public static int countUniquePairs(List<String> strings) {
        root = new TrieNode();
        Timer timer = new Timer();

        // Build Trie
        timer.schedule(new TimerTask() {
            @Override
            public void run() {
                System.out.println("Building Trie...");
            }
        }, 0);

        for (String str : strings) {
            insert(str);
        }

        long trieBuildTime = System.currentTimeMillis();
        timer.cancel();

        // Count unique pairs
        int count = 0;
        Set<String> checkedPairs = new HashSet<>();
        for (int i = 0; i < strings.size(); i++) {
            for (int j = i + 1; j < strings.size(); j++) {
                String str1 = strings.get(i);
                String str2 = strings.get(j);
                if (!checkedPairs.contains(str1 + ":" + str2) && !isSubstring(str2, str1) && !isSubstring(str1, str2)) {
                    count++;
                    checkedPairs.add(str1 + ":" + str2);
                }
            }
        }

        return count;
    }

    private static void insert(String word) {
        TrieNode node = root;
        for (char ch : word.toCharArray()) {
            int index = ch - 'a';
            if (node.children[index] == null) {
                node.children[index] = new TrieNode();
            }
            node = node.children[index];
        }
        node.isEndOfWord = true;
    }

    private static boolean isSubstring(String str1, String str2) {
        return str2.contains(str1);
    }

    public static void main(String[] args) {
        List<String> strings = List.of("abc", "abcd", "def", "efg");
        int result = countUniquePairs(strings);
        System.out.println("Number of unique pairs: " + result);
    }
}
```

This code defines a `TrieNode` class and a `SubstringPairs` class that includes methods for inserting strings into the Trie, checking if one string is a substring of another, and counting unique pairs based on the Trie. The main method demonstrates how to use these methods with a sample list of strings.']

['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class ConnectionPool {

    private Selector selector;
    private long connectionTimeout;
    private long idleTimeout;

    public ConnectionPool(long connectionTimeout, long idleTimeout) throws IOException {
        this.selector = Selector.open();
        this.connectionTimeout = connectionTimeout;
        this.idleTimeout = idleTimeout;
    }

    public void addConnection(String address, int port) throws IOException {
        SocketChannel channel = SocketChannel.open();
        channel.configureBlocking(false);
        channel.connect(new InetSocketAddress(address, port));
        channel.register(selector, SelectionKey.OP_CONNECT);
    }

    public void validateConnections() throws IOException {
        selector.selectNow();
        Set<SelectionKey> selectedKeys = selector.selectedKeys();
        Iterator<SelectionKey> iter = selectedKeys.iterator();

        while (iter.hasNext()) {
            SelectionKey key = iter.next();
            if (key.isConnectable()) {
                SocketChannel channel = (SocketChannel) key.channel();
                if (channel.isConnectionPending()) {
                    try {
                        channel.finishConnect();
                        // Register for read/write interest
                        channel.register(selector, SelectionKey.OP_READ | SelectionKey.OP_WRITE);
                    } catch (IOException e) {
                        channel.close();
                    }
                }
            }
            iter.remove();
        }
    }

    public void evictConnections() throws IOException {
        long now = System.currentTimeMillis();
        selector.selectedKeys().stream()
            .filter(key -> key.attachment() instanceof ConnectionInfo)
            .filter(key -> ((ConnectionInfo) key.attachment()).getLastActivity() + idleTimeout < now)
            .forEach(key -> {
                try {
                    SocketChannel channel = (SocketChannel) key.channel();
                    channel.close();
                } catch (IOException e) {
                    // Handle exception
                }
                key.cancel();
            });
    }

    public void close() throws IOException {
        selector.close();
    }

    private static class ConnectionInfo {
        private long lastActivity;

        public ConnectionInfo() {
            this.lastActivity = System.currentTimeMillis();
        }

        public void updateActivity() {
            this.lastActivity = System.currentTimeMillis();
        }

        public long getLastActivity() {
            return lastActivity;
        }
    }
}
```']

