import java.util.Random;

public class ServiceManager {
    private static final int QUEUE_SIZE = 10;
    private ThreadSafeQueue queue;
    private boolean serviceRunning;
    private Random random;

    public ServiceManager() {
        this.queue = createCThreadSafeQueue(QUEUE_SIZE);
        this.serviceRunning = false;
        this.random = new Random();
    }

    public void startService() {
        if (!serviceRunning) {
            serviceRunning = true;
            int delay = random.nextInt(5001); // 0 to 5000 milliseconds
            try {
                Thread.sleep(delay);
                enqueue(queue, 1); // Enqueue a message to indicate service start
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public void stopService() {
        if (serviceRunning) {
            serviceRunning = false;
            try {
                Thread.sleep(random.nextInt(5001)); // 0 to 5000 milliseconds
                enqueue(queue, 2); // Enqueue a message to indicate service stop
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private native ThreadSafeQueue createCThreadSafeQueue(int size);
    private native void destroyCThreadSafeQueue(ThreadSafeQueue queue);

    static {
        System.loadLibrary("thread_safe_queue"); // Load the C library
    }

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager();
        while (true) {
            manager.startService();
            manager.stopService();
        }
    }
}
