['```php
<?php

class ConfigManager {
    private $config = [];
    private $fallbackConfig = [];

    public function __construct($paths) {
        foreach ($paths as $path) {
            if (file_exists($path)) {
                $this->config = array_merge_recursive($this->config, require $path);
            } else {
                $this->fallbackConfig[] = $path;
            }
        }
    }

    public function get($key) {
        return $this->resolve($this->config, $key);
    }

    private function resolve(array $array, $key, $default = null) {
        if (is_array($key)) {
            $result = [];
            foreach ($key as $_key) {
                $result[] = $this->resolve($array, $_key, $default);
            }
            return $result;
        }

        if (!empty($array) && array_key_exists($key, $array)) {
            return $array[$key];
        } elseif (!empty($this->fallbackConfig)) {
            foreach ($this->fallbackConfig as $path) {
                if (file_exists($path)) {
                    $newArray = require $path;
                    if (!empty($newArray) && array_key_exists($key, $newArray)) {
                        return $newArray[$key];
                    }
                }
            }
        }

        return $default;
    }
}

// Usage
$configManager = new ConfigManager([
    'config/default.php',
    'config/production.php'
]);

$databaseHost = $configManager->get('database.host');
$databaseUser = $configManager->get('database.user');
$databasePassword = $configManager->get('database.password', 'default_password');

// Error handling
if (!$databaseHost || !$databaseUser) {
    die("Configuration error: Missing database host or user.");
}

echo "Connecting to database with host: $databaseHost, user: $databaseUser";
?>
