```java
// Java code using JDBC with connection pooling and caching
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.sql.DataSource;
import org.apache.commons.dbcp2.BasicDataSource;

public class EmployeeQuery {

    private static DataSource dataSource;

    public static void init(String url, String username, String password) {
        BasicDataSource bds = new BasicDataSource();
        bds.setUrl(url);
        bds.setUsername(username);
        bds.setPassword(password);
        bds.setMaxTotal(100); // Maximum number of connections
        bds.setMaxIdle(30);  // Maximum idle time for a connection
        dataSource = bds;
    }

    public static ResultSet getEmployeeDetails(int supervisorID) throws Exception {
        String sql = "SELECT e.EmployeeName, e.City, e.Address FROM Employees e WHERE e.SupervisorID = ?";

        try (Connection conn = dataSource.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setInt(1, supervisorID);
            return pstmt.executeQuery();
        }
    }

    // Use caching strategies to reduce database hits
    private static Map<Integer, ResultSet> cache = new ConcurrentHashMap<>();

    public static ResultSet getEmployeeDetailsFromCache(int supervisorID) throws Exception {
        if (cache.containsKey(supervisorID)) {
            return cache.get(supervisorID);
        } else {
            ResultSet rs = getEmployeeDetails(supervisorID);
            cache.put(supervisorID, rs);
            return rs;
        }
    }
}
```

