    struct State* next;
} State;

typedef struct FSA {
    // Define the structure of your FSA here
} FSA;

State* manageDynamicList(int* states, int numStates, FSA* fsa, State* lastState) {
    if (states == NULL || numStates <= 0 || fsa == NULL || lastState == NULL) {
        return NULL;
    }

    State* newList = NULL;
    State** current = &newList;

    for (int i = 0; i < numStates; i++) {
        State* newState = (State*)malloc(sizeof(State));
        if (newState == NULL) {
            // Handle memory allocation failure
            return NULL;
        }

        newState->id = states[i];
        newState->next = NULL;

        *current = newState;
        current = &(*current)->next;
    }

    lastState->next = newList;

    return newList;
}
