['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000

typedef struct {
    int id;
    float weight;
    time_t timestamp;
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int count;
    float total_weight_last_second;
} TransactionQueue;

void init_transaction_queue(TransactionQueue *queue) {
    queue->count = 0;
    queue->total_weight_last_second = 0.0f;
}

int add_transaction(TransactionQueue *queue, Transaction transaction) {
    if (queue->count >= MAX_TRANSACTIONS) {
        return -1; // Queue is full
    }
    queue->transactions[queue->count++] = transaction;
    return 0;
}

void update_queue(TransactionQueue *queue) {
    time_t current_time = time(NULL);
    for (int i = 0; i < queue->count; i++) {
        if (current_time - queue->transactions[i].timestamp > 5) {
            // Remove transactions older than 5 seconds
            for (int j = i; j < queue->count - 1; j++) {
                queue->transactions[j] = queue->transactions[j + 1];
            }
            queue->count--;
            i--; // Adjust index after removal
        } else if (current_time - queue->transactions[i].timestamp > 4) {
            // Update total weight for transactions older than 1 second
            queue->total_weight_last_second -= queue->transactions[i].weight;
        }
    }
}

int process_transactions(TransactionQueue *queue, int *transaction_id) {
    float max_weight_sum = -1.0f;
    int max_index = -1;

    update_queue(queue);

    for (int i = 0; i < queue->count; i++) {
        if (current_time - queue->transactions[i].timestamp > 5) {
            continue; // Skip transactions older than 5 seconds
        }

        float weight_sum = queue->total_weight_last_second;
        for (int j = 0; j <= i; j++) {
            weight_sum += queue->transactions[j].weight;
        }

        if (weight_sum > max_weight_sum) {
            max_weight_sum = weight_sum;
            max_index = i;
        }
    }

    if (max_index != -1) {
        *transaction_id = queue->transactions[max_index].id;
        return 0; // Success
    } else {
        return -1; // No valid transaction found
    }
}

int main() {
    TransactionQueue queue;
    init_transaction_queue(&queue);

    // Simulate adding transactions
    for (int i = 0; i < 200; i++) {
        Transaction t = {i, rand() / (float)RAND_MAX * 100, time(NULL)};
        add_transaction(&queue, t);
    }

    int transaction_id;
    if (process_transactions(&queue, &transaction_id) == 0) {
        printf("Transaction ID with highest weighted sum: %d\n", transaction_id);
    } else {
        printf("No valid transaction found.\n");
    }

    return 0;
}
