class AttackManager {
public:
    void initialize() {
        lastAttackTimeA = std::chrono::high_resolution_clock::now();
        lastAttackTimeB = std::chrono::high_resolution_clock::now();
        cooldownA = 12000; // 12 seconds in milliseconds
        cooldownB = 8000;  // 8 seconds in milliseconds

        // Simulate external data update (in practice, use real HTTP request)
        std::thread([this]() {
            while (true) {
                updateCooldowns();
                std::this_thread::sleep_for(std::chrono::minutes(1));
            }
        }).detach();
    }

    void selectAttack() {
        auto now = std::chrono::high_resolution_clock::now();

        if (canAttackA(now)) {
            lastAttackTimeA = now;
            std::cout << "Selected Attack A" << std::endl;
        } else if (canAttackB(now)) {
            lastAttackTimeB = now;
            std::cout << "Selected Attack B" << std::endl;
        }
    }

private:
    std::chrono::time_point<std::chrono::high_resolution_clock> lastAttackTimeA, lastAttackTimeB;
    int cooldownA, cooldownB;

    bool canAttackA(const std::chrono::time_point<std::chrono::high_resolution_clock>& now) {
        return (now - lastAttackTimeA >= std::chrono::milliseconds(cooldownA));
    }

    bool canAttackB(const std::chrono::time_point<std::chrono::high_resolution_clock>& now) {
        return (now - lastAttackTimeB >= std::chrono::milliseconds(cooldownB));
    }

    void updateCooldowns() {
        // Simulate cooldown adjustment based on external data
        cooldownA = 12000; // Example: reset to original value
        cooldownB = 8000;
    }
};

int main() {
    AttackManager manager;
    manager.initialize();

    while (true) {
        manager.selectAttack();
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    return 0;
}
