using UnityEngine;

public class CustomRandom
{
    private float minValue;
    private float maxValue;

    public CustomRandom()
    {
        minValue = 0f;
        maxValue = 1f;
    }

    public CustomRandom(float min, float max)
    {
        if (min > max)
        {
            Debug.LogWarning("Invalid range. Min value should be less than or equal to Max value.");
            minValue = 0f;
            maxValue = 1f;
        }
        else
        {
            minValue = min;
            maxValue = max;
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int GetRandomInt()
    {
        return Mathf.RoundToInt(GetRandomFloat());
    }

    public int GetExclusiveRandomInt()
    {
        if (maxValue - minValue <= 1)
        {
            Debug.LogWarning("Range too small for exclusive random integer.");
            return Mathf.RoundToInt(minValue);
        }
        return Mathf.RoundToInt(UnityEngine.Random.Range(minValue + 1, maxValue));
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}

