#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h> // For JSON support
#include "xmlrpc-c/parser.h" // For XML support

typedef struct {
    int itemCount;
    void **items; // Array of pointers to item data
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char *filePath, int *error) {
    FILE *file = fopen(filePath, "r");
    if (!file) {
        *error = 1; // Error opening file
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *fileContent = (char *)malloc(fileSize + 1);
    if (!fileContent) {
        fclose(file);
        *error = 2; // Error allocating memory
        return NULL;
    }

    fread(fileContent, fileSize, 1, file);
    fclose(file);

    ResourceBundle *bundle = (ResourceBundle *)malloc(sizeof(ResourceBundle));
    if (!bundle) {
        free(fileContent);
        *error = 2; // Error allocating memory
        return NULL;
    }

    bundle->itemCount = 0;
    bundle->items = NULL;

    // Parse the file content based on its extension
    if (strcmp(filePath + strlen(filePath) - 5, ".json") == 0) {
        json_object *root = json_tokener_parse(fileContent);
        if (!root) {
            free(bundle);
            free(fileContent);
            *error = 3; // Error parsing JSON
            return NULL;
        }

        bundle->itemCount = json_object_array_length(root);
        bundle->items = (void **)malloc(bundle->itemCount * sizeof(void *));
        for (int i = 0; i < bundle->itemCount; i++) {
            bundle->items[i] = json_object_array_get_idx(root, i);
        }

        json_object_put(root);
    } else if (strcmp(filePath + strlen(filePath) - 4, ".xml") == 0) {
        // Implement XML parsing here
    } else {
        free(bundle);
        free(fileContent);
        *error = 4; // Unsupported file format
        return NULL;
    }

    free(fileContent);
    *error = 0; // Success
    return bundle;
}

void releaseResourceBundle(ResourceBundle *bundle) {
    for (int i = 0; i < bundle->itemCount; i++) {
        // Free each item based on its type
        json_object_put(bundle->items[i]);
    }
    free(bundle->items);
    free(bundle);
}
