char* appendSlashToBuffer(const char* input, size_t limit, char* buffer, size_t bufferSize) {
    if (strlen(input) >= limit) {
        return NULL;
    }

    size_t newLength = strlen(input) + 2; // +1 for '/', +1 for null terminator
    if (buffer == NULL || bufferSize < newLength) {
        buffer = realloc(buffer, newLength * sizeof(char));
        if (buffer == NULL) {
            return NULL; // Memory allocation failed
        }
    }

    strcpy(buffer, input);
    buffer[strlen(input)] = '/';
    buffer[newLength - 1] = '\0';

    return buffer;
}

void freeBuffer(char* buffer) {
    free(buffer);
}
