EVP_CIPHER_CTX* parseTiffAndEncrypt(const char* tiffPath, const char* operation) {
    TIFF* tif = TIFFOpen(tiffPath, "r");
    if (!tif) {
        return (EVP_CIPHER_CTX*)TIFF_ERRCODE_NO_IMAGE;
    }

    uint32_t bitsPerSample[4];
    uint16_t samplePerPixel;
    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, bitsPerSample) != 1 ||
        TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplePerPixel) != 1) {
        TIFFClose(tif);
        return (EVP_CIPHER_CTX*)TIFF_ERRCODE_NO_IMAGE;
    }

    if (bitsPerSample[0] != 8 && bitsPerSample[0] != 16 && samplePerPixel > 1) {
        TIFFClose(tif);
        return (EVP_CIPHER_CTX*)TIFF_ERRCODE_UNSUPPORTED_FORMAT;
    }

    EVP_CIPHER_CTX* ctx = NULL;
    if (strcmp(operation, "encrypt") == 0) {
        ctx = EVP_CIPHER_CTX_new();
        if (!ctx || !EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
            TIFFClose(tif);
            return (EVP_CIPHER_CTX*)TIFF_ERRCODE_ENCRYPTION_FAILED;
        }
    } else if (strcmp(operation, "decrypt") == 0) {
        ctx = EVP_CIPHER_CTX_new();
        if (!ctx || !EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
            TIFFClose(tif);
            return (EVP_CIPHER_CTX*)TIFF_ERRCODE_DECRYPTION_FAILED;
        }
    } else {
        TIFFClose(tif);
        return (EVP_CIPHER_CTX*)TIFF_ERRCODE_INVALID_OPERATION;
    }

    TIFFClose(tif);
    return ctx;
}
