void generate_new_filename(const char* input_filename, char* output_filename) {
    const int MAX_FILENAME_LENGTH = 256;
    const int MAX_DIGITS = 10;
    srand(time(NULL));

    if (strlen(input_filename) > MAX_FILENAME_LENGTH - MAX_DIGITS - 8) { // Allow space for digits, timestamp, and extension
        strncpy(output_filename, input_filename, MAX_FILENAME_LENGTH - 1);
        output_filename[MAX_FILENAME_LENGTH - 1] = '\0';
        return;
    }

    char temp_filename[MAX_FILENAME_LENGTH];
    strcpy(temp_filename, input_filename);

    int extension_length = strlen(input_filename) >= 3 ? 4 : 7; // +1 for null terminator
    strncpy(output_filename, temp_filename, MAX_FILENAME_LENGTH - extension_length - MAX_DIGITS);
    output_filename[MAX_FILENAME_LENGTH - extension_length - MAX_DIGITS] = '\0';

    char digits[MAX_DIGITS];
    for (int i = 0; i < MAX_DIGITS; ++i) {
        digits[i] = '0' + rand() % 10;
    }
    digits[MAX_DIGITS] = '\0';

    time_t now = time(NULL);
    struct tm* timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", timeinfo);

    if (strlen(temp_filename) >= 3) {
        strncat(output_filename, digits, MAX_DIGITS);
        strcat(output_filename, ".");
        strncat(output_filename, &temp_filename[strlen(temp_filename) - 3], extension_length - 4);
    } else {
        strncat(output_filename, "XXX", MAX_DIGITS + 1);
        strcat(output_filename, ".");
        strncat(output_filename, temp_filename, extension_length - 4);
    }
}
