import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Properties;

public class CommandExecutor {

    private static final String LOG_FILE = "execution_log.txt";
    private static final int MAX_RETRIES = 3;
    private static final Properties properties = loadProperties("config.properties");

    public static void main(String[] args) {
        String command = properties.getProperty("command");
        String filePath = properties.getProperty("filePath");

        executeCommand(command, filePath);
    }

    private static Properties loadProperties(String fileName) {
        Properties prop = new Properties();
        try (InputStream input = new FileInputStream(fileName)) {
            prop.load(input);
        } catch (IOException e) {
            System.err.println("Failed to load properties: " + e.getMessage());
        }
        return prop;
    }

    public static void executeCommand(String command, String filePath) {
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            try {
                Path file = Paths.get(filePath);
                if (Files.exists(file)) {
                    Files.delete(file);
                    System.out.println("File deleted: " + filePath);
                }

                Process process = Runtime.getRuntime().exec(command.split("\\s+"), null, new File("."));
                BufferedReader stdoutReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                BufferedReader stderrReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

                String line;
                while ((line = stdoutReader.readLine()) != null) {
                    System.out.println(line);
                    logToFile("STDOUT: " + line);
                }
                while ((line = stderrReader.readLine()) != null) {
                    System.err.println(line);
                    logToFile("STDERR: " + line);
                }

                int exitCode = process.waitFor();
                if (exitCode == 0) {
                    logToFile("Command executed successfully with code: " + exitCode);
                    break;
                } else {
                    logToFile("Command failed with code: " + exitCode);
                }
            } catch (IOException | InterruptedException e) {
                System.err.println("Error during command execution: " + e.getMessage());
                if (attempt == MAX_RETRIES - 1) {
                    handleResourceExhaustion(e);
                }
            }
        }
    }

    private static void logToFile(String message) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(LOG_FILE, true))) {
            SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
            String timestamp = sdf.format(new Date());
            writer.write(timestamp + " - " + message);
            writer.newLine();
        } catch (IOException e) {
            System.err.println("Error writing to log file: " + e.getMessage());
        }
    }

    private static void handleResourceExhaustion(Exception e) {
        System.err.println("Maximum retries reached. Resource exhaustion or memory leak detected.");
        // Implement cleanup procedures and error handling
    }
}
