public class AesCryption
{
    public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv, byte[] macTag, CipherMode mode)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = mode;

            switch (mode)
            {
                case CipherMode.GCM:
                    ICryptoTransform decryptor = aes.CreateDecryptor(key, iv);
                    byte[] decryptedData = new byte[ciphertext.Length - macTag.Length];
                    using (MemoryStream ms = new MemoryStream(ciphertext))
                    {
                        using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                        {
                            cs.Read(decryptedData, 0, decryptedData.Length);
                        }
                    }

                    // Verify MAC tag
                    byte[] calculatedMacTag = GenerateMacTag(decryptedData, key, iv);
                    if (!macTag.SequenceEqual(calculatedMacTag))
                    {
                        throw new CryptographicException("MAC verification failed.");
                    }

                    return decryptedData;
                case CipherMode.CCM:
                    // Implement CCM decryption logic here
                    throw new NotImplementedException("CCM mode is not implemented.");
                default:
                    throw new ArgumentException("Unsupported cipher mode.");
            }
        }
    }

    private static byte[] GenerateMacTag(byte[] data, byte[] key, byte[] iv)
    {
        using (HMACSHA256 hmac = new HMACSHA256(key))
        {
            return hmac.ComputeHash(iv.Concat(data).ToArray());
        }
    }
}
```

