import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.security.SecureRandom;
import org.bouncycastle.jce.provider.BouncyCastleProvider;

public class SecureObjectDeserializer {

    public static Object deserialize(byte[] encryptedPayload, String password) {
        try {
            // Add Bouncy Castle provider for additional cryptographic operations
            Security.addProvider(new BouncyCastleProvider());

            // Generate a secure random IV
            byte[] iv = new byte[16];
            SecureRandom.getInstanceStrong().nextBytes(iv);

            // Derive the encryption key from the password using PKCS5_PBKDF2
            byte[] salt = new byte[32];
            SecureRandom.getInstanceStrong().nextBytes(salt);
            int iterationCount = 10000; // High iteration count for security
            SecretKeySpec keySpec = deriveKey(password, salt, iterationCount);

            // Initialize the cipher for decryption
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS7Padding", "BC");
            IvParameterSpec ivSpec = new IvParameterSpec(iv);
            cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);

            // Decrypt and deserialize the payload
            byte[] decryptedPayload = cipher.doFinal(encryptedPayload);
            ByteArrayInputStream bis = new ByteArrayInputStream(decryptedPayload);
            ObjectInputStream ois = new ObjectInputStream(bis);
            Object obj = ois.readObject();
            ois.close();

            return obj;
        } catch (Exception e) {
            throw new RuntimeException("Failed to deserialize encrypted payload", e);
        }
    }

    private static SecretKeySpec deriveKey(String password, byte[] salt, int iterationCount) throws Exception {
        PBEKeySpec keySpec = new PBEKeySpec(password.toCharArray(), salt, iterationCount, 256);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        byte[] derivedKey = factory.generateSecret(keySpec).getEncoded();
        return new SecretKeySpec(derivedKey, "AES");
    }

    private static void destroyCipherContext(Cipher cipher) {
        // Destroy the cipher context to ensure sensitive data is cleared from memory
        cipher.clearParameters();
    }
}
