const axios = require('axios');
const fs = require('fs');
const path = require('path');

function uploadResource(url, config = {}) {
  const { chunkSize = 1024 * 1024, retryAttempts = 3, timeout = 5000 } = config;
  const filePath = path.resolve(__dirname, 'file.txt'); // Example file path
  const fileSize = fs.statSync(filePath).size;

  return new Promise((resolve, reject) => {
    let uploadedBytes = 0;
    let attempts = 0;

    function uploadChunk(start, end) {
      if (start >= fileSize) {
        resolve(url);
        return;
      }

      attempts++;
      const chunk = fs.createReadStream(filePath, { start, end });
      axios.post(url, chunk, {
        headers: {
          'Content-Type': 'application/octet-stream',
          'Range': `bytes=${start}-${end}`
        },
        timeout
      })
      .then(response => {
        console.log(`Chunk ${start}-${end} uploaded successfully at ${new Date()}`);
        uploadedBytes += response.headers['content-length'];
        uploadChunk(start + chunkSize, end + chunkSize);
      })
      .catch(error => {
        if (attempts <= retryAttempts) {
          console.error(`Attempt ${attempts}: Error uploading chunk ${start}-${end} - Retrying...`);
          setTimeout(() => uploadChunk(start, end), 1000); // Retry after a delay
        } else {
          const errorMessage = `Failed to upload resource: ${error.message}`;
          console.error(errorMessage);
          reject(new Error(errorMessage));
        }
      });
    }

    if (fileSize > chunkSize) {
      uploadChunk(0, chunkSize - 1);
    } else {
      axios.post(url, fs.createReadStream(filePath), {
        headers: {
          'Content-Type': 'application/octet-stream'
        },
        timeout
      })
      .then(response => {
        console.log('File uploaded successfully at', new Date());
        resolve(url);
      })
      .catch(error => {
        const errorMessage = `Failed to upload resource: ${error.message}`;
        console.error(errorMessage);
        reject(new Error(errorMessage));
      });
    }
  });
}

// Usage
uploadResource('http://example.com/upload')
  .then(url => console.log('File uploaded successfully:', url))
  .catch(error => console.error('Error uploading file:', error));
```

This code snippet defines a `uploadResource` function that uses Axios for HTTP requests and Node.js's built-in `fs` module for file handling. It demonstrates how to upload a file in chunks, handle retries, and manage timeouts. The function logs detailed information about each upload attempt and returns a promise that resolves with the URL of the uploaded file upon successful completion."]

