#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include "resource_bundle.h"

int execute_shell_command_and_process(const char* command, const char* file_path, resource_bundle** bundle) {
    int pipefd[2];
    pid_t pid;
    FILE* write_fd;
    char buffer[1024];

    if (pipe(pipefd) == -1) {
        perror("pipe");
        return -1;
    }

    pid = fork();
    if (pid == -1) {
        perror("fork");
        close(pipefd[0]);
        close(pipefd[1]);
        return -1;
    } else if (pid == 0) {
        close(pipefd[0]);
        write_fd = fdopen(pipefd[1], "w");
        dup2(write_fd->_fileno, STDOUT_FILENO);
        execl("/bin/sh", "sh", "-c", command, NULL);
        perror("execl");
        exit(EXIT_FAILURE);
    } else {
        close(pipefd[1]);
        waitpid(pid, NULL, 0);
        while (read(pipefd[0], buffer, sizeof(buffer) - 1) > 0) {
            buffer[strcspn(buffer, "\n")] = '\0';
            resource_bundle* temp_bundle = load_resource_bundle(file_path, buffer);
            if (temp_bundle == NULL) {
                perror("load_resource_bundle");
                free(*bundle);
                *bundle = NULL;
                close(pipefd[0]);
                return -1;
            }
            append_resource_bundle(bundle, temp_bundle);
        }
        close(pipefd[0]);
        int item_count = count_resource_bundle_items(*bundle);
        free_resource_bundle(temp_bundle);
        return item_count;
    }
}
