const { exec } = require('child_process');
const neo4j = require('neo4j-driver');

async function addRandomGraphData() {
  try {
    const driver = neo4j.driver('bolt://localhost:7687', neo4j.auth.basic('neo4j', 'password'));
    const session = driver.session();

    // Generate random number of vertices
    const numVertices = Math.floor(Math.random() * 10) + 1;
    for (let i = 0; i < numVertices; i++) {
      await session.run(`CREATE (:Node {id: ${i}, name: 'Node${i}', value: randInt(1, 100)})`);
    }

    // Generate random number of edges
    const numEdges = Math.floor(Math.random() * (numVertices * (numVertices - 1))) + 1;
    for (let i = 0; i < numEdges; i++) {
      const fromNode = Math.floor(Math.random() * numVertices);
      const toNode = Math.floor(Math.random() * numVertices);
      await session.run(`MATCH (a:Node {id: ${fromNode}}), (b:Node {id: ${toNode}})
                          CREATE (a)-[:RELATIONSHIP]->(b)`);
    }

    // Execute shell command
    exec('echo "Graph data added successfully"', (error, stdout, stderr) => {
      if (error) {
        console.error(`Error executing shell command: ${error.message}`);
        return;
      }
      if (stderr) {
        console.error(`Shell command produced errors: ${stderr}`);
        return;
      }

      // Output results to browser
      const response = {
        graphData: 'Graph data added successfully',
        shellCommandOutput: stdout
      };

      session.close();
      driver.close();
      return response;
    });
  } catch (error) {
    console.error(`Error in addRandomGraphData function: ${error.message}`);
    return { error: `Failed to add random graph data and execute shell command` };
  }
}

// Helper function to generate random integer between min and max
function randInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}
