}

async fn index() -> impl Responder {
    HttpResponse::Ok().body("Hello, world!")
}

async fn custom_middleware<B>(req: actix_web::HttpRequest<B>, next: web::next::Next<B>) -> Result<HttpResponse, actix_web::Error> {
    println!("Request path: {:?}", req.path());
    next.run(req).await
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let opt = Opt::from_args();

    HttpServer::new(|| {
        App::new()
            .wrap(custom_middleware)
            .route("/{path:.*}", web::get().to(index))
    })
    .bind(opt.addr)?
    .run()
    .await
}
