use std::fs;
use std::env;
use std::os::unix::fs::PermissionsExt;
use std::path::Path;

fn setup_directory_and_env_var(
    dir_name: &str,
    env_var_name: &str,
    password_or_token: Option<&str>,
) -> Result<(), Box<dyn std::error::Error>> {
    let dir_path = Path::new(dir_name);

    if !dir_path.exists() {
        fs::create_dir(&dir_path)?;
    }

    let mut permissions = fs::metadata(&dir_path)?.permissions();
    permissions.set_mode(0o755); // Set write permissions for the owner and read permissions for others
    fs::set_permissions(&dir_path, permissions)?;

    if env_var_name.is_empty() {
        return Err("Environment variable name cannot be empty".into());
    }

    let mut env_var_value = match env::var(env_var_name) {
        Ok(value) => value,
        Err(_) => dir_path.to_str().unwrap_or("").to_string(),
    };

    if env_var_value != dir_path.to_str().unwrap_or("") {
        env::set_var(env_var_name, &env_var_value)?;
    }

    println!("Directory '{}' and environment variable '{}' are set up successfully.", dir_name, env_var_name);

    Ok(())
}
