import json

class JSONHandler:
    _registry = {}

    @staticmethod
    def register_factory(cls):
        if cls.TYPE_ID in JSONHandler._registry:
            raise ValueError(f"Type ID '{cls.TYPE_ID}' already registered.")
        JSONHandler._registry[cls.TYPE_ID] = lambda data: cls.from_json(data)

    @staticmethod
    def parse(json_str):
        data = json.loads(json_str)
        factory = JSONHandler._registry.get(data['type_id'])
        if not factory:
            raise ValueError(f"Unknown type ID '{data['type_id']}'")
        return factory(data)

    def to_json(self):
        raise NotImplementedError("Subclasses must implement this method")

class SubClassA(JSONHandler):
    TYPE_ID = 'A'

    def __init__(self, value):
        self.value = value

    @classmethod
    def from_json(cls, data):
        return cls(value=data['value'])

    def to_json(self):
        return json.dumps({'type_id': self.TYPE_ID, 'value': self.value})

class SubClassB(JSONHandler):
    TYPE_ID = 'B'

    def __init__(self, value1, value2):
        self.value1 = value1
        self.value2 = value2

    @classmethod
    def from_json(cls, data):
        return cls(value1=data['value1'], value2=data['value2'])

    def to_json(self):
        return json.dumps({'type_id': self.TYPE_ID, 'value1': self.value1, 'value2': self.value2})

# Example usage:
JSONHandler.register_factory(SubClassA)
JSONHandler.register_factory(SubClassB)

json_a = '{"type_id": "A", "value": 42}'
instance_a = JSONHandler.parse(json_a)
print(instance_a.to_json())  # Output: {"type_id": "A", "value": 42}

json_b = '{"type_id": "B", "value1": "foo", "value2": "bar"}'
instance_b = JSONHandler.parse(json_b)
print(instance_b.to_json())  # Output: {"type_id": "B", "value1": "foo", "value2": "bar"}
