public class ReportTitleGenerator {
    private static final Logger logger = LoggerFactory.getLogger(ReportTitleGenerator.class);
    private static final ExecutorService executorService = Executors.newFixedThreadPool(10);

    public String generateReportTitle(List<String> inputStrings, ApiClient apiClient) {
        long startTime = System.currentTimeMillis();
        try {
            String title = constructTitle(inputStrings);
            Metadata metadata = fetchMetadata(apiClient);
            String result = title + " - Dept: " + metadata.getDepartmentCode() + ", Ver: " + metadata.getVersion();
            logger.info("Report Title Generation - Time taken: {}ms, Input count: {}, Title length: {}", 
                         System.currentTimeMillis() - startTime, inputStrings.size(), result.length());
            return result;
        } catch (Exception e) {
            logger.error("Error generating report title", e);
            return "Report Title Generation Error";
        }
    }

    private String constructTitle(List<String> inputStrings) {
        return inputStrings.stream()
                           .filter(s -> s != null && !s.trim().isEmpty())
                           .reduce((a, b) -> a + " - " + b)
                           .orElse("Default Report Title");
    }

    private Metadata fetchMetadata(ApiClient apiClient) {
        CompletableFuture<Metadata> future = CompletableFuture.supplyAsync(() -> apiClient.fetchMetadata(), executorService);
        try {
            return future.orTimeout(5, TimeUnit.SECONDS).get();
        } catch (Exception e) {
            logger.warn("Failed to fetch metadata from API, using default values", e);
            return new Metadata("UnknownDept", "1.0");
        }
    }

    public static void main(String[] args) {
        ReportTitleGenerator generator = new ReportTitleGenerator();
        ApiClient apiClient = new ApiClient(); // Assume this is a mock implementation
        List<String> inputStrings = List.of("Input1", "Input2", null, "Input3");
