#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_QUEUE_LENGTH 1000

typedef struct {
    int id;
    int weight;
    time_t timestamp;
} Transaction;

Transaction queue[MAX_QUEUE_LENGTH];
int front = 0, rear = -1;
int total_transactions_last_10s = 0;
int total_weight_last_second = 0;
time_t current_time;
pthread_mutex_t lock;
pthread_cond_t cond_var;

void* transaction_processor(void* arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        if ((rear + 1) % MAX_QUEUE_LENGTH == front || total_transactions_last_10s >= 100) {
            pthread_cond_wait(&cond_var, &lock);
        }
        pthread_mutex_unlock(&lock);

        pthread_mutex_lock(&lock);
        time_t current_time = time(NULL);
        for (int i = front; i != rear + 1; i = (i + 1) % MAX_QUEUE_LENGTH) {
            if (difftime(current_time, queue[i].timestamp) >= 5) {
                front = (front + 1) % MAX_QUEUE_LENGTH;
                total_transactions_last_10s--;
                total_weight_last_second -= queue[i].weight;
            } else {
                break;
            }
        }

        int highest_weight_id = -1;
        int max_weight_sum = 0;
        for (int i = front; i != rear + 1; i = (i + 1) % MAX_QUEUE_LENGTH) {
            if (queue[i].timestamp < current_time - 2 && queue[i].weight > max_weight_sum) {
                highest_weight_id = queue[i].id;
                max_weight_sum = queue[i].weight;
            }
        }

        int transactions_last_5s = (rear - front + MAX_QUEUE_LENGTH) % MAX_QUEUE_LENGTH;

        printf("Highest Weighted Transaction ID: %d\n", highest_weight_id);
        printf("Total Transactions Last 5 seconds: %d\n", transactions_last_5s);

        pthread_mutex_unlock(&lock);
    }
}

void enqueue_transaction(Transaction transaction) {
    pthread_mutex_lock(&lock);
    if ((rear + 1) % MAX_QUEUE_LENGTH == front && total_transactions_last_10s < 100) {
        pthread_cond_signal(&cond_var);
    }
    rear = (rear + 1) % MAX_QUEUE_LENGTH;
    queue[rear] = transaction;
    total_transactions_last_10s++;
    if ((time(NULL) - current_time) >= 2) {
        total_weight_last_second += transaction.weight;
    }
    pthread_mutex_unlock(&lock);
}

void* health_check(void* arg) {
    while (1) {
        sleep(0.1); // Every 100 milliseconds
        printf("Transaction Rate: %d transactions per second\n", total_transactions_last_10s / 10);
        printf("Queue Length: %d\n", (rear - front + MAX_QUEUE_LENGTH) % MAX_QUEUE_LENGTH);
        printf("System Load Percentage: %.2f%%\n", ((double)(rear - front + MAX_QUEUE_LENGTH) % MAX_QUEUE_LENGTH) / MAX_QUEUE_LENGTH * 100);
    }
}

int main() {
    pthread_t processor_thread, health_thread;
    pthread_create(&processor_thread, NULL, transaction_processor, NULL);
    pthread_create(&health_thread, NULL, health_check, NULL);

    // Simulate transaction processing
    for (int i = 0; i < 1500; i++) {
        Transaction tx = {i, rand() % 10 + 1, time(NULL)};
        enqueue_transaction(tx);
        sleep(0.001); // Simulate arrival of transactions every millisecond
    }

    pthread_join(processor_thread, NULL);
    pthread_join(health_thread, NULL);

    return 0;
}
