using UnityEngine;

public class CustomRandom
{
    private float minValue = 0;
    private float maxValue = 1;

    public CustomRandom(float min = 0, float max = 1)
    {
        if (min > max)
        {
            Debug.LogWarning("Invalid range. Using default values.");
            minValue = 0;
            maxValue = 1;
        }
        else
        {
            minValue = min;
            maxValue = max;
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1f);
    }

    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int GetExclusiveRandomInt()
    {
        if (minValue + 1 > maxValue)
        {
            Debug.LogWarning("Invalid range for exclusive random integer. Using default values.");
            minValue = 0;
            maxValue = 1;
        }
        return (int)UnityEngine.Random.Range(minValue + 1, maxValue + 1);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}

