<?php

function initializeAesCipher($password, $salt = null, $iterationCount = 10000, $keyLength = 32, $ivLength = 16) {
    if ($salt === null) {
        $salt = openssl_random_pseudo_bytes(openssl_cipher_iv_length('aes-256-cbc'));
    }

    $key = password_hash($password . $salt, PASSWORD_ARGON2I);

    $cipherContext = openssl_cipher_iv_length('aes-256-cbc') > 0 ? openssl_get_cipher_methods(true) : null;

    if ($cipherContext === null || !openssl_cipher_iv_length('aes-256-cbc')) {
        throw new Exception("OpenSSL cipher initialization failed");
    }

    $iv = openssl_random_pseudo_bytes($ivLength, $strong);
    if (!$strong) {
        throw new Exception("Random IV generation failed");
    }

    return [
        'cipherContext' => $cipherContext,
        'key' => $key,
        'iv' => $iv
    ];
}

function destroyCipherContext(&$cipherContext) {
    if (is_resource($cipherContext)) {
        openssl_free_key($cipherContext);
        unset($cipherContext);
    }
}

// Example usage:
try {
    $password = "user_password";
    $salt = openssl_random_pseudo_bytes(openssl_cipher_iv_length('aes-256-cbc'));
    $iterationCount = 10000;
    $keyLength = 32;
    $ivLength = 16;

    $cipherParams = initializeAesCipher($password, $salt, $iterationCount, $keyLength, $ivLength);

    // Use the cipher parameters for encryption and decryption
    // ...

    destroyCipherContext($cipherParams['cipherContext']);
} catch (Exception $e) {
