    memset(manager->transaction_queue, 0, sizeof(TransactionQueue));
    pthread_mutex_init(&manager->transaction_queue->lock, NULL);
    pthread_cond_init(&manager->transaction_queue->not_full, NULL);
    pthread_cond_init(&manager->transaction_queue->not_empty, NULL);
