}

void enqueue_transaction(TransactionManager* manager, Transaction transaction) {
    pthread_mutex_lock(&manager->transaction_queue->lock);
    while (is_queue_full(manager->transaction_queue)) {
        pthread_cond_wait(&manager->transaction_queue->not_full, &manager->transaction_queue->lock);
    }
    add_transaction_to_queue(manager->transaction_queue, transaction);
    pthread_cond_signal(&manager->transaction_queue->not_empty);
    pthread_mutex_unlock(&manager->transaction_queue->lock);
}

Transaction dequeue_transaction(TransactionManager* manager) {
