    {
        return UnityEngine.Random.Range((int)minValue, (int)(maxValue + 1));
    }

    public int GetExclusiveRandomInt()
    {
        if (minValue >= maxValue)
        {
            return GetRandomInt();
        }
        return UnityEngine.Random.Range((int)(minValue + 1), (int)(maxValue + 1));
    }

    public Vector3 GetRandomVector3()
    {
        return new Vector3(
            UnityEngine.Random.Range(minValue, maxValue + 1),
            UnityEngine.Random.Range(minValue, maxValue + 1),
            UnityEngine.Random.Range(minValue, maxValue + 1)
        );
    }

    public int[] GenerateRandomArray(int size)
    {
        if (size <= 0)
        {
            throw new ArgumentException("Size must be greater than zero.");
        }
        int[] randomArray = new int[size];
        for (int i = 0; i < size; i++)
        {
            randomArray[i] = GetRandomInt();
        }
        return randomArray;
    }

