char* extend_crypto_library(const char* input, size_t limit, char* buffer) {
    // Check if the input string length exceeds the specified size limit
    if (strlen(input) > limit) {
        return NULL;
    }

    // Append a slash to the end of the string
    char modified_input[MAX_BUFFER_SIZE];
    snprintf(modified_input, sizeof(modified_input), "%s/", input);

    // Allocate or reuse buffer with the size of the modified string
    if (buffer == NULL || strlen(modified_input) > limit) {
        buffer = (char*)malloc(strlen(modified_input));
        if (buffer == NULL) {
            return NULL;
        }
    }

    // Copy the modified string into the allocated or reused buffer
    strcpy(buffer, modified_input);

    return buffer;
}
