#define THRESHOLD 200
#define YOUNGER_THAN_5_SECONDS 5
#define OLDER_THAN_1_SECOND 1
#define HEALTH_CHECK_INTERVAL 50

typedef struct {
    int weight;
    time_t timestamp;
} Transaction;

typedef struct {
    Transaction queue[TRANSACTION_QUEUE_SIZE];
    int front, rear, count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} TransactionQueue;

void initQueue(TransactionQueue *queue) {
    queue->front = queue->rear = -1;
    queue->count = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
}

int isFull(TransactionQueue *queue) {
    return (queue->count == TRANSACTION_QUEUE_SIZE);
}

int isEmpty(TransactionQueue *queue) {
    return (queue->count == 0);
}

void enqueue(TransactionQueue *queue, Transaction transaction) {
    pthread_mutex_lock(&queue->mutex);
    while (isFull(queue)) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    if (isEmpty(queue)) {
        queue->front = 0;
    }
    queue->rear = (queue->rear + 1) % TRANSACTION_QUEUE_SIZE;
    queue->queue[queue->rear] = transaction;
    queue->count++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

Transaction dequeue(TransactionQueue *queue) {
    pthread_mutex_lock(&queue->mutex);
    while (isEmpty(queue)) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    Transaction transaction = queue->queue[queue->front];
    if (queue->front == queue->rear) {
        queue->front = queue->rear = -1;
    } else {
        queue->front = (queue->front + 1) % TRANSACTION_QUEUE_SIZE;
    }
    queue->count--;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
    return transaction;
}

int processTransactions(TransactionQueue *queue, int currentWeight) {
    if (currentWeight > THRESHOLD) {
        // Throttle incoming transactions
        return 0;
    }

    while (!isEmpty(queue)) {
        Transaction transaction = dequeue(queue);
        if ((time(NULL) - transaction.timestamp) < YOUNGER_THAN_5_SECONDS && 
            currentWeight + transaction.weight <= THRESHOLD) {
            // Process the transaction
            currentWeight += transaction.weight;
        } else {
            enqueue(queue, transaction); // Re-enqueue if not processed
            break; // Only process one transaction at a time to avoid blocking
        }
    }

    return currentWeight;
}

void* healthCheck(void *arg) {
    TransactionQueue *queue = (TransactionQueue *)arg;
    while (1) {
        pthread_mutex_lock(&queue->mutex);
        int count = queue->count;
        double loadPercentage = ((double)count / TRANSACTION_QUEUE_SIZE) * 100;
        time_t now = time(NULL);
        int transactionRate = 0;
        for (int i = 0; i < queue->count; i++) {
            if ((now - queue->queue[(queue->front + i) % TRANSACTION_QUEUE_SIZE].timestamp) <= OLDER_THAN_1_SECOND) {
                transactionRate++;
            }
        }
        pthread_mutex_unlock(&queue->mutex);
        printf("Queue Depth: %d, Transaction Rate: %d, Load Percentage: %.2f%%\n", count, transactionRate, loadPercentage);
        usleep(HEALTH_CHECK_INTERVAL * 1000); // Sleep for 50 milliseconds
    }
}

void renameFile(char *filename) {
    char *dot = strrchr(filename, '.');
    if (dot != NULL) {
        int sum = 0;
        for (char *p = filename; p < dot; p++) {
            sum += (*p - '0');
        }
        char newExt[12];
        sprintf(newExt, "_%d_%s", sum, dot + 1);
        dot[0] = '\0';
        strcat(filename, newExt);
    }
}

int main() {
    TransactionQueue queue;
    initQueue(&queue);

    pthread_t healthCheckThread;
    pthread_create(&healthCheckThread, NULL, healthCheck, &queue);

    // Simulate transaction processing
    int currentWeight = 0;
    for (int i = 0; i < 1000; i++) {
        Transaction transaction = {i % 50, time(NULL)};
        enqueue(&queue, transaction);
        currentWeight = processTransactions(&queue, currentWeight);
        usleep(1000); // Simulate processing every millisecond
    }

    pthread_join(healthCheckThread, NULL);

    return 0;
}
```

This code provides a basic implementation of the required functionality. It includes a `TransactionQueue` structure to manage transactions with thread-safe operations, a `processTransactions` function to filter and process transactions based on the given criteria, a `healthCheck` function to periodically report system metrics, and a `renameFile` function to rename files based on their characteristics.

Note that this code is for educational purposes and may require further refinement for production use.']

