class DataGenerator {
private:
    int minValue;
    int maxValue;
    std::uniform_int_distribution<> distribution;
    std::random_device rd;
    std::mt19937 gen;
    std::mutex mtx;

public:
    DataGenerator(int min = 0, int max = 100) : minValue(min), maxValue(max), gen(rd()) {
        if (minValue > maxValue) {
            std::cerr << "Warning: minValue is greater than maxValue. Adjusting maxValue to match minValue." << std::endl;
            maxValue = minValue;
        }
        distribution = std::uniform_int_distribution<>(minValue, maxValue);
    }

    int GetRandomValue() {
        return distribution(gen);
    }

    int GetExclusiveRandomValue() {
        if (maxValue - minValue <= 1) {
            throw std::invalid_argument("Max value is too close to min value for exclusive random generation.");
        }
        return distribution(gen) + 1;
    }

    glm::vec3 GetRandomVector3() {
        return glm::vec3(distribution(gen), distribution(gen), distribution(gen));
    }

    std::vector<int> GenerateRandomArray(int size) {
        std::vector<int> array(size);
        std::generate(array.begin(), array.end(), [this]() { return this->GetRandomValue(); });
        return array;
    }

    int GetRandomWeightedValue(const std::vector<int>& weights) {
        if (std::accumulate(weights.begin(), weights.end(), 0) != 100) {
            throw std::invalid_argument("Sum of weights must be equal to 100.");
        }
        std::random_device rd;
        std::mt19937 gen(rd());
        std::discrete_distribution<> dist(weights.begin(), weights.end());
        return dist(gen);
    }

    int GetRandomTimestamp(int epoch) {
        auto now = std::chrono::system_clock::now();
        auto now_c = std::chrono::system_clock::to_time_t(now);
        auto min_timestamp = now_c - 31536000; // One year in seconds
        auto max_timestamp = now_c + 31536000; // One year in seconds
        std::uniform_int_distribution<> ts_dist(min_timestamp, max_timestamp);
        return ts_dist(gen) + epoch;
    }
};

int main() {
    DataGenerator dg(1, 100);
    std::cout << "Random Value: " << dg.GetRandomValue() << std::endl;
    std::cout << "Exclusive Random Value: " << dg.GetExclusiveRandomValue() << std::endl;
    glm::vec3 vec = dg.GetRandomVector3();
    std::cout << "Random Vector3: (" << vec.x << ", " << vec.y << ", " << vec.z << ")" << std::endl;

    std::vector<int> array = dg.GenerateRandomArray(10);
    for (int val : array) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    std::vector<int> weights = {30, 20, 50};
    int weighted_value = dg.GetRandomWeightedValue(weights);
    std::cout << "Random Weighted Value: " << weighted_value << std::endl;

    int timestamp = dg.GetRandomTimestamp(1672531200); // Example epoch
    std::cout << "Random Timestamp: " << timestamp << std::endl;

    return 0;
}
