// Function prototypes
double calculate_average(double *array, int count);
int get_user_choice();
double *read_numbers(int *count);

int main() {
    int choice;
    double *numbers = NULL;
    int count = 0;

    numbers = read_numbers(&count);

    if (count == 0) {
        printf("No numbers provided.\n");
    } else {
        choice = get_user_choice();
        if (choice == 1) {
            // Single precision
            float avg = (float)calculate_average(numbers, count);
            printf("Average in single precision: %f\n", avg);
        } else if (choice == 2) {
            // Double precision
            double avg = calculate_average(numbers, count);
            printf("Average in double precision: %f\n", avg);
        }
    }

    free(numbers);
    return 0;
}

double *read_numbers(int *count) {
    int size = 10; // Initial capacity
    *count = 0;
    double *array = (double *)malloc(size * sizeof(double));

    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }

    printf("Enter floating-point numbers. Type 'exit' to finish:\n");

    while (1) {
        char input[256];
        printf("> ");
        fgets(input, sizeof(input), stdin);

        if (strcmp(input, "exit\n") == 0) {
            break;
        }

        char *endptr = NULL;
        double value = strtod(input, &endptr);

        if (*endptr != '\n' || endptr == input) {
            printf("Invalid input detected.\n");
            free(array);
            exit(1);
        }

        array[*count] = value;

        (*count)++;
        if (*count >= size) {
            size *= 2;
            double *new_array = (double *)realloc(array, size * sizeof(double));
            if (!new_array) {
                fprintf(stderr, "Memory reallocation failed.\n");
                free(array);
                exit(1);
            }
            array = new_array;
        }
    }

    return array;
}

int get_user_choice() {
    int choice;

    printf("Choose precision:\n");
    printf("1. Single precision\n");
    printf("2. Double precision\n");

    while (1) {
        scanf("%d", &choice);
        if (choice == 1 || choice == 2) {
            break;
        }
        printf("Invalid choice. Please enter 1 or 2.\n");
        while (getchar() != '\n'); // Clear input buffer
    }

    return choice;
}

double calculate_average(double *array, int count) {
    if (count == 0) {
        fprintf(stderr, "Division by zero avoided.\n");
        return 0.0;
    }
    double sum = 0;
    for (int i = 0; i < count; i++) {
        sum += array[i];
    }
    return sum / count;
}
