#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int *items;
    size_t capacity;
    size_t front;
    size_t rear;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} PriorityQueue;

PriorityQueue* create_priority_queue(size_t capacity) {
    PriorityQueue *queue = malloc(sizeof(PriorityQueue));
    if (queue == NULL) return NULL;

    queue->items = malloc(capacity * sizeof(int));
    if (queue->items == NULL) {
        free(queue);
        return NULL;
    }

    queue->capacity = capacity;
    queue->front = 0;
    queue->rear = -1;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    pthread_cond_init(&queue->not_full, NULL);

    return queue;
}

void destroy_priority_queue(PriorityQueue *queue) {
    free(queue->items);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_empty);
    pthread_cond_destroy(&queue->not_full);
    free(queue);
}

int enqueue(PriorityQueue *queue, int item, int priority) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == queue->capacity) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }

    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->items[queue->rear] = item;
    queue->size++;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue(PriorityQueue *queue, int *item, int timeout_ms) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1000000;

    pthread_mutex_lock(&queue->lock);
    while (queue->size == 0 && pthread_cond_timedwait(&queue->not_empty, &queue->lock, &ts) == 0) {
        // Wait until there is an item or timeout
    }

    if (queue->size == 0) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Timeout
    }

    *item = queue->items[queue->front];
    queue->front = (queue->front + 1) % queue->capacity;
    queue->size--;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

void adjust_capacity(PriorityQueue *queue, size_t new_capacity) {
    int *new_items = malloc(new_capacity * sizeof(int));
    if (new_items == NULL) return;

    for (size_t i = 0; i < queue->size; ++i) {
        new_items[i] = queue->items[(queue->front + i) % queue->capacity];
    }

    free(queue->items);
    queue->items = new_items;
    queue->front = 0;
    queue->rear = queue->size - 1;
    queue->capacity = new_capacity;
}
