#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TRANSACTIONS 100
#define TRANSACTION_AGE_LIMIT 5000 // 5 seconds in milliseconds
#define TRANSACTION_COUNT_WINDOW 10000 // 10 seconds in milliseconds

typedef struct {
    int id;
    long weight;
} Transaction;

Transaction transactionQueue[MAX_TRANSACTIONS];
int transactionCount = 0;
int transactionQueueIndex = 0;
time_t lastResetTime;

// C function to manage high-frequency transactions
void processTransactions() {
    time_t currentTime = time(NULL);
    if (difftime(currentTime, lastResetTime) >= TRANSACTION_COUNT_WINDOW / 1000.0) {
        // Reset transaction count and weights older than 1 second
        for (int i = 0; i < transactionCount; i++) {
            if ((currentTime - transactionQueue[i].id) * 1000 > 1000) {
                transactionQueue[i].weight = 0;
            }
        }
        lastResetTime = currentTime;
    }

    // Queue transactions meeting criteria
    int highestWeightSum = 0;
    int totalTransactionsLast5Seconds = 0;
    for (int i = 0; i < transactionCount; i++) {
        if ((currentTime - transactionQueue[i].id) * 1000 > TRANSACTION_AGE_LIMIT) {
            totalTransactionsLast5Seconds++;
            highestWeightSum += transactionQueue[i].weight;
        }
    }

    printf("Transaction ID with highest weighted sum: %d\n", highestWeightSum);
    printf("Total transactions processed in last 5 seconds: %d\n", totalTransactionsLast5Seconds);
}
