#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INVALID_CHARS 10
const char* invalidChars[MAX_INVALID_CHARS] = {"/", "\\", "*", "?", "\"", "<", ">", "|", "\0"};

char* modifyFilePath(const char* filePath, size_t maxPathLength, char* buffer) {
    if (filePath == NULL || maxPathLength == 0) return NULL;

    // Check for invalid characters
    for (int i = 0; i < MAX_INVALID_CHARS; i++) {
        if (strstr(filePath, invalidChars[i]) != NULL) {
            return NULL;
        }
    }

    size_t pathLen = strlen(filePath);
    bool isDirectory = (filePath[pathLen - 1] == '/' || filePath[pathLen - 1] == '\\');

    size_t requiredSize = pathLen + 2; // Additional space for the slash and null terminator

    if (buffer != NULL && buffer[0] != '\0' && strlen(buffer) >= requiredSize) {
        strncpy(buffer, filePath, maxPathLength);
        buffer[pathLen] = isDirectory ? '/' : '\0';
        return buffer;
    }

    char* newBuffer = realloc(buffer, requiredSize * sizeof(char));
    if (newBuffer == NULL) return NULL;

    strncpy(newBuffer, filePath, maxPathLength);
    newBuffer[pathLen] = isDirectory ? '/' : '\0';

    return newBuffer;
}

void freeBuffer(char* buffer) {
    if (buffer != NULL && buffer[0] != '\0') {
        free(buffer);
    }
}
