#define MAX_QUEUE_SIZE 1000

typedef struct Transaction {
    int id;
    double weight;
    time_t timestamp;
} Transaction;

typedef struct {
    Transaction transactions[MAX_QUEUE_SIZE];
    int front, rear;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
    int count;
} TransactionQueue;

void initQueue(TransactionQueue *queue) {
    queue->front = 0;
    queue->rear = -1;
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
}

void enqueue(TransactionQueue *queue, Transaction transaction) {
    pthread_mutex_lock(&queue->lock);
    while (queue->count == MAX_QUEUE_SIZE) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    queue->rear = (queue->rear + 1) % MAX_QUEUE_SIZE;
    queue->transactions[queue->rear] = transaction;
    queue->count++;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
}

Transaction dequeue(TransactionQueue *queue) {
    Transaction transaction;
    pthread_mutex_lock(&queue->lock);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    transaction = queue->transactions[queue->front];
    queue->front = (queue->front + 1) % MAX_QUEUE_SIZE;
    queue->count--;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return transaction;
}

