#define MAX_FILENAME_LENGTH 256
#define MAX_DIGITS 10
#define TIMESTAMP_FORMAT "%Y%m%d%H%M%S"
#define LOG_FILE "filename_log.txt"

typedef struct {
    char filename[MAX_FILENAME_LENGTH];
    time_t timestamp;
} RecentFilename;

RecentFilename recentFiles[1000]; // Array to store recently generated filenames
int fileCount = 0; // Counter for the number of files in the array

void logError(const char *original, const char *timestamp, const char *error) {
    FILE *logFile = fopen(LOG_FILE, "a");
    if (logFile != NULL) {
        fprintf(logFile, "Failed to generate unique filename: Original=%s, Timestamp=%s, Error=%s\n", original, timestamp, error);
        fclose(logFile);
    }
}

int isFilenameRecent(const char *filename) {
    time_t currentTime = time(NULL);
    for (int i = 0; i < fileCount; i++) {
        if (strcmp(recentFiles[i].filename, filename) == 0 && difftime(currentTime, recentFiles[i].timestamp) <= 3600) {
            return 1;
        }
    }
    return 0;
}

void addRecentFilename(const char *filename) {
    if (fileCount < 1000) {
        strcpy(recentFiles[fileCount].filename, filename);
        recentFiles[fileCount++].timestamp = time(NULL);
    }
}

char* generateNewFilename(const char *original) {
    static char newFilename[MAX_FILENAME_LENGTH];
    char tempFilename[MAX_FILENAME_LENGTH];
    int digitCount = 0;
    time_t timestamp;
    char digits[11] = "0000000000";

    // Sanitize the original filename
    for (int i = 0; i < strlen(original); i++) {
        if ((original[i] >= 'a' && original[i] <= 'z') ||
            (original[i] >= 'A' && original[i] <= 'Z') ||
            (original[i] >= '0' && original[i] <= '9')) {
            tempFilename[digitCount++] = original[i];
        }
    }
    tempFilename[digitCount] = '\0';

    // Append file type extension or "XXX"
    if (digitCount > 3) {
        strcpy(newFilename, tempFilename);
        strncat(newFilename, &tempFilename[2], 1);
    } else {
        snprintf(newFilename, MAX_FILENAME_LENGTH, "%sXXX", tempFilename);
    }

    // Append random digits
    srand(time(NULL));
    for (int i = 0; i < MAX_DIGITS; i++) {
        int digit = rand() % 10;
        digits[i] = '0' + digit;
    }
    strcat(newFilename, digits);

    // Add timestamp
    time(&timestamp);
    char timestampStr[20];
    strftime(timestampStr, sizeof(timestampStr), TIMESTAMP_FORMAT, localtime(&timestamp));
    strcat(newFilename, "_");
    strncat(newFilename, timestampStr, 14);

    // Ensure filename does not exceed MAX_FILENAME_LENGTH
    if (strlen(newFilename) > MAX_FILENAME_LENGTH - 1) {
        newFilename[MAX_FILENAME_LENGTH - 1] = '\0';
    }

    // Check for uniqueness and add to recent files list
    while (isFilenameRecent(newFilename)) {
        logError(original, timestampStr, "Duplicate filename detected");
        srand(time(NULL));
        for (int i = 0; i < MAX_DIGITS; i++) {
            int digit = rand() % 10;
            digits[i] = '0' + digit;
        }
        strcat(newFilename, digits);
    }
    addRecentFilename(newFilename);

    return newFilename;
}

// Example usage
int main() {
    const char *originalFilename = "example_filename.txt";
    char *newFilename = generateNewFilename(originalFilename);
    printf("Generated filename: %s\n", newFilename);
    free(newFilename); // Assuming the caller will manage memory for dynamic strings
    return 0;
}
```

