class LogEntry:
    def __init__(self, timestamp, user_id, message):
        self.timestamp = timestamp
        self.user_id = user_id
        self.message = message

class Logger:
    MAX_SESSION_SIZE = 1 * 1024 * 1024  # 1 MB
    MAX_EVENT_SIZE = 10 * 1024  # 10 KB
    BACKPRESSURE_QUEUE_LIMIT = 500

    def __init__(self):
        self.sessions = defaultdict(lambda: {'queue': deque(), 'size': 0, 'last_entry_time': None})
        self.log_rate_tracker = LogRateTracker()
        self.lock = threading.Lock()

    def log(self, timestamp, user_id, message):
        if not self.validate_log_entry(timestamp, user_id, message):
            return False

        with self.lock:
            session = self.sessions[user_id]
            event_size = len(message.encode('utf-8'))
            if event_size > Logger.MAX_EVENT_SIZE or session['size'] + event_size > Logger.MAX_SESSION_SIZE:
                return False

            session['queue'].append(LogEntry(timestamp, user_id, message))
            session['size'] += event_size
            session['last_entry_time'] = timestamp

            if len(session['queue']) >= Logger.BACKPRESSURE_QUEUE_LIMIT:
                self.log_rate_tracker.pause_log_entries()

        return True

    def validate_log_entry(self, timestamp, user_id, message):
