    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    record *records = (record *)malloc(sizeof(record) * MAX_RECORDS);
    if (!records) {
        perror("malloc");
        free(*ip_address);
        return -3;
    }

    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; ++i) {
        offsets[i] = rand() % sizeof(long);
        keys[i] = rand();
        records[i].value = rand() % (MAX_RANDOM - MIN_RANDOM + 1) + MIN_RANDOM;
    }

    return 0;
}

