    HTTP_INTERNAL_ERROR = 500
} status_code;

typedef struct {
    time_t timestamp;
    status_code code;
} request_record;

u_char* process_urls(char** urls, size_t url_count, size_t* request_times, time_t* timestamps, request_record** records) {
    u_char* response_body = NULL;
    *request_times = (size_t*)malloc(url_count * sizeof(size_t));
    *timestamps = (time_t*)malloc(url_count * sizeof(time_t));
    *records = (request_record*)malloc(url_count * sizeof(request_record));

    if (!*request_times || !*timestamps || !*records) {
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < url_count; ++i) {
        struct timeval start, end;
        gettimeofday(&start, NULL);

        // Simulate HTTP request
        int status = rand() % 3 + 200; // Random HTTP status code between 200 and 202

        if (status == HTTP_OK) {
            response_body = (u_char*)malloc(1024 * sizeof(u_char));
            strcpy((char*)response_body, "OK");
        }

        gettimeofday(&end, NULL);
        (*request_times)[i] = end.tv_sec - start.tv_sec;
        (*timestamps)[i] = time(NULL);
        (*records)[i].timestamp = time(NULL);
        (*records)[i].code = (status_code)status;

        if (status != HTTP_OK) {
            return NULL;
        }
    }

    return response_body;
}
