    *query_times = malloc(num_ips * sizeof(int));
    *timestamps = malloc(num_ips * sizeof(time_t));
    **addr_infos = malloc(num_ips * sizeof(struct addrinfo *));

    if (!*hostnames || !*query_times || !*timestamps || !**addr_infos) {
        return -2; // Error: Memory allocation failed
    }

    int i;
    for (i = 0; i < num_ips; i++) {
        struct addrinfo hints, *res;
        int status;

        memset(&hints, 0, sizeof hints);
        hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
