using UnityEngine;

public class CustomRandom
{
    private float minValue;
    private float maxValue;

    public CustomRandom(float minValue = 0, float maxValue = 1)
    {
        if (minValue > maxValue)
        {
            Debug.LogWarning("Invalid range. Setting default values.");
            this.minValue = 0;
            this.maxValue = 1;
        }
        else
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int GetExclusiveRandomInt()
    {
        if (minValue >= maxValue - 1)
        {
            Debug.LogWarning("Cannot generate exclusive random integers with this range.");
            return (int)GetRandomInt();
        }
        return (int)UnityEngine.Random.Range(minValue + 1, maxValue);
    }

    public Vector3 GetRandomVector3()
    {
        return new Vector3(GetRandomFloat(), GetRandomFloat(), GetRandomFloat());
    }

    public int[] GenerateRandomArray(int size)
    {
        if (size <= 0)
        {
            Debug.LogWarning("Invalid array size. Returning an empty array.");
            return new int[0];
        }

        int[] randomArray = new int[size];
        for (int i = 0; i < size; i++)
        {
            randomArray[i] = GetRandomInt();
        }
        return randomArray;
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}
