using System;
using System.Security.Cryptography;
using System.Text;

public class SecureRandom
{
    private float minValue;
    private float maxValue;
    private string characterSet;

    public SecureRandom(float minValue = 0.0f, float maxValue = 1.0f, string characterSet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789")
    {
        if (minValue > maxValue)
        {
            Console.WriteLine("Warning: minValue is greater than maxValue. Setting defaults.");
            this.minValue = 0.0f;
            this.maxValue = 1.0f;
        }
        else
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }

        this.characterSet = characterSet;
    }

    public float GetRandomFloat()
    {
        using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
        {
            byte[] bytes = new byte[4];
            rng.GetBytes(bytes);
            return BitConverter.ToSingle(bytes, 0) * (maxValue - minValue) + minValue;
        }
    }

    public int GetRandomInt()
    {
        return (int)(GetRandomFloat() * (maxValue - minValue + 1)) + (int)minValue;
    }

    public int GetExclusiveRandomInt()
    {
        return (int)(GetRandomFloat() * (maxValue - minValue)) + (int)(minValue + 1);
    }

    public string GetRandomString(int length, string characterSet)
    {
        using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
        {
            byte[] bytes = new byte[length];
            rng.GetBytes(bytes);
            StringBuilder sb = new StringBuilder(length);
            for (int i = 0; i < length; i++)
            {
                int index = BitConverter.ToUInt16(bytes, i * 2) % characterSet.Length;
                sb.Append(characterSet[index]);
            }
            return sb.ToString();
        }
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public Vector3 GetRandomVector3()
    {
        return new Vector3(GetRandomFloat(), GetRandomFloat(), GetRandomFloat());
    }

    public int[] GenerateRandomArray(int size)
    {
        int[] array = new int[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GetRandomInt();
        }
        return array;
    }

    public string HashPassword(string password)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] inputBytes = Encoding.UTF8.GetBytes(password);
            byte[] hashBytes = sha256.ComputeHash(inputBytes);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++)
            {
                sb.Append(hashBytes[i].ToString("x2"));
            }
            return sb.ToString();
        }
    }
}
