// Function prototypes
double calculate_average(float *numbers, int count);
int read_numbers(float **numbers, int *count);
void log_event(int success);
void export_to_csv(float *numbers, int count);

int main() {
    float *numbers = NULL;
    int count = 0;
    char precision[10];
    int retries = 3;

    while (retries > 0) {
        printf("Enter 'single' for single precision or 'double' for double precision: ");
        scanf("%s", precision);

        if (strcmp(precision, "single") == 0) {
            // Single precision logic
            break;
        } else if (strcmp(precision, "double") == 0) {
            // Double precision logic
            break;
        } else {
            retries--;
            printf("Invalid input. %d attempts remaining.\n", retries);
        }
    }

    if (retries == 0) {
        printf("Max retries reached. Exiting program.\n");
        return EXIT_FAILURE;
    }

    int success = read_numbers(&numbers, &count);

    if (success) {
        log_event(1);
        double average = calculate_average(numbers, count);
        printf("Average: %f\n", average);
        export_to_csv(numbers, count);
    } else {
        log_event(0);
        printf("Invalid input detected.\n");
    }

    free(numbers); // Free allocated memory
    return EXIT_SUCCESS;
}

double calculate_average(float *numbers, int count) {
    if (count == 0) {
        printf("No numbers provided.\n");
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += numbers[i];
    }
    return sum / count;
}

int read_numbers(float **numbers, int *count) {
    char line[128];
    printf("Enter floating-point numbers separated by spaces: ");
    fgets(line, sizeof(line), stdin);

    *count = 0;
    *numbers = (float *)malloc(100 * sizeof(float)); // Initial allocation
    if (*numbers == NULL) {
        return 0;
    }

    char *token = strtok(line, " ");
    while (token != NULL && *count < 100) { // Limit to 100 numbers for simplicity
        float num;
        int result = sscanf(token, "%f", &num);
        if (result == 1) {
            (*numbers)[(*count)++] = num;
        } else {
            free(*numbers);
            return 0;
        }
        token = strtok(NULL, " ");
    }

    return *count > 0;
}

void log_event(int success) {
    // Logging logic here
    if (success) {
        printf("Calculation successful.\n");
    } else {
        printf("Invalid input detected. Attempt logged.\n");
    }
}

void export_to_csv(float *numbers, int count) {
    FILE *file = fopen("output.csv", "w");
    if (file == NULL) {
        printf("Error opening file for writing.\n");
        return;
    }

    fprintf(file, "Numbers:\n");
    for (int i = 0; i < count; i++) {
        fprintf(file, "%f\n", numbers[i]);
    }
    fclose(file);
}
