#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int *items;
    size_t head;
    size_t tail;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} ThreadSafeQueue;

ThreadSafeQueue* queue_create(size_t initial_capacity) {
    ThreadSafeQueue* q = (ThreadSafeQueue*)malloc(sizeof(ThreadSafeQueue));
    q->items = (int*)calloc(initial_capacity, sizeof(int));
    q->head = 0;
    q->tail = 0;
    q->capacity = initial_capacity;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    pthread_cond_init(&q->not_full, NULL);
    return q;
}

void queue_destroy(ThreadSafeQueue* q) {
    free(q->items);
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->not_empty);
    pthread_cond_destroy(&q->not_full);
    free(q);
}

int queue_enqueue(ThreadSafeQueue* q, int item) {
    pthread_mutex_lock(&q->lock);
    while (q->tail == (q->head + 1) % q->capacity) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }
    q->items[q->tail] = item;
    q->tail = (q->tail + 1) % q->capacity;
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->lock);
    return 0;
}

int queue_dequeue(ThreadSafeQueue* q, int *item) {
    pthread_mutex_lock(&q->lock);
    while (q->head == q->tail) {
        pthread_cond_wait(&q->not_empty, &q->lock);
    }
    *item = q->items[q->head];
    q->head = (q->head + 1) % q->capacity;
    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->lock);
    return 0;
}

void queue_adjust_capacity(ThreadSafeQueue* q, size_t new_capacity) {
    int *new_items = (int*)calloc(new_capacity, sizeof(int));
    for (size_t i = 0; i < q->capacity; ++i) {
        new_items[i] = q->items[(q->head + i) % q->capacity];
    }
    pthread_mutex_lock(&q->lock);
    free(q->items);
    q->items = new_items;
    q->head = 0;
    q->tail = q->capacity;
    q->capacity = new_capacity;
    pthread_cond_broadcast(&q->not_empty);
    pthread_cond_broadcast(&q->not_full);
    pthread_mutex_unlock(&q->lock);
}
