<?php

class PasswordManager {
    private $db;

    public function __construct($dsn, $username, $password) {
        try {
            $this->db = new PDO($dsn, $username, $password);
            $this->db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        } catch (PDOException $e) {
            die("Database connection failed: " . $e->getMessage());
        }
    }

    public function generateSecureString($length, $charSet) {
        $bytes = random_bytes($length);
        return substr(str_shuffle(bin2hex($bytes)), 0, $length);
    }

    public function hashPassword($password) {
        return password_hash($password, PASSWORD_DEFAULT);
    }

    public function validatePassword($password, $hashedPassword) {
        return password_verify($password, $hashedPassword);
    }

    public function generateSecureToken($length = 32) {
        return $this->generateSecureString($length, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789');
    }

    public function storeToken($tokenId, $userId, $expiryTime) {
        $stmt = $this->db->prepare("INSERT INTO tokens (token_id, user_id, expiry_time) VALUES (:token_id, :user_id, :expiry_time)");
        $stmt->bindParam(':token_id', $tokenId);
        $stmt->bindParam(':user_id', $userId);
        $stmt->bindParam(':expiry_time', $expiryTime);
        return $stmt->execute();
    }

    public function retrieveToken($tokenId) {
        static $cache = [];
        if (isset($cache[$tokenId])) {
            return $cache[$tokenId];
        }
        $stmt = $this->db->prepare("SELECT * FROM tokens WHERE token_id = :token_id");
        $stmt->bindParam(':token_id', $tokenId);
        $stmt->execute();
        $result = $stmt->fetch(PDO::FETCH_ASSOC);
        if ($result) {
            $cache[$tokenId] = $result;
        }
        return $result;
    }

    public function deleteExpiredTokens() {
        $currentTime = time();
        $stmt = $this->db->prepare("DELETE FROM tokens WHERE expiry_time < :current_time");
        $stmt->bindParam(':current_time', $currentTime);
        return $stmt->execute();
    }
}
?>
