import java.io.*;
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;
import org.json.JSONObject;

public class MoSTStateDeserializer {

    public static MoSTState deserializeAndDecryptMoSTState(byte[] encryptedPayload, String password) {
        try {
            // Generate secure random IV using OpenSSL's cryptographically secure random number generator
            byte[] iv = generateSecureRandomIV();

            // Derive encryption key from password
            SecretKey secretKey = deriveEncryptionKey(password);

            // Initialize AES-256-CBC cipher for decryption
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            cipher.init(Cipher.DECRYPT_MODE, secretKey, new IvParameterSpec(iv));

            // Decrypt the payload
            byte[] decryptedPayload = cipher.doFinal(encryptedPayload);

            // Load state object from decrypted payload
            ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(decryptedPayload));
            try {
                Object obj = ois.readObject();
                if (obj instanceof MoSTState) {
                    return (MoSTState) obj;
                } else {
                    return null;
                }
            } catch (ClassNotFoundException e) {
                throw new RuntimeException("Failed to load state object", e);
            } finally {
                ois.close();
            }

        } catch (Exception e) {
            throw new RuntimeException("Failed to deserialize and decrypt payload", e);
        }
    }

    private static byte[] generateSecureRandomIV() throws NoSuchAlgorithmException {
        SecureRandom random = SecureRandom.getInstanceStrong();
        byte[] iv = new byte[16];
        random.nextBytes(iv);
        return iv;
    }

    private static SecretKey deriveEncryptionKey(String password) throws Exception {
        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(256, SecureRandom.getInstanceStrong());
        SecretKey secretKey = keyGen.generateKey();
        PBEKeySpec pbeKeySpec = new PBEKeySpec(password.toCharArray(), generateSalt(), 100000);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        byte[] derivedKey = factory.generateSecret(pbeKeySpec).getEncoded();
        return new SecretKeySpec(derivedKey, "AES");
    }

    private static byte[] generateSalt() throws NoSuchAlgorithmException {
        SecureRandom random = SecureRandom.getInstanceStrong();
        byte[] salt = new byte[16];
        random.nextBytes(salt);
        return salt;
    }
}
