#include <mqueue.h>

#define MAX_FILE_SIZE 10737418240 // 10 GB
#define DEFAULT_COMMENT_DELIMITER ";"
#define LOG_FILE "pipeline.log"

void log_entry(const char* message) {
    FILE* log = fopen(LOG_FILE, "a");
    if (log != NULL) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

int process_file(int mq_output, const char* input_path, const char* delimiter) {
    int file_handle = open(input_path, O_RDONLY);
    if (file_handle == -1) {
        log_entry("Error opening file: ");
        return -1;
    }

    char buffer[MAX_FILE_SIZE];
    ssize_t bytes_read;

    while ((bytes_read = read(file_handle, buffer, sizeof(buffer))) > 0) {
        char* line_start = buffer;
        for (char* p = buffer; p < buffer + bytes_read; ++p) {
            if (*p == '\n' || *p == delimiter[0]) {
                size_t line_length = p - line_start;
                if (*p != delimiter[0] || *(p+1) == '\n') {
                    mq_send(mq_output, line_start, line_length, 0);
                }
                line_start = p + 1;
            }
        }
    }

    close(file_handle);
    return 0;
}

int main(int argc, char* argv[]) {
    const char* delimiter = DEFAULT_COMMENT_DELIMITER;
    mqd_t mq_input, mq_output;

    // Parse command-line arguments
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-delimiter") == 0 && i + 1 < argc) {
            delimiter = argv[++i];
        }
    }

    // Initialize message queues
    mq_input = mq_open("/pipeline_input", O_RDONLY | O_CREAT, 0644, NULL);
    mq_output = mq_open("/pipeline_output", O_WRONLY | O_CREAT, 0644, NULL);

    if (mq_input == -1 || mq_output == -1) {
        log_entry("Error opening message queues");
        return -1;
    }

    // Process files from the input queue
    char input_path[256];
    while (mq_receive(mq_input, input_path, sizeof(input_path), NULL) > 0) {
        if (process_file(mq_output, input_path, delimiter) != 0) {
            log_entry("Error processing file");
        }
    }

    mq_close(mq_input);
    mq_close(mq_output);
    return 0;
}
