EVP_CIPHER_CTX* init_aes_256_cbc(const char *password, size_t password_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    unsigned char iv[EVP_MAX_IV_LENGTH];
    if (RAND_bytes(iv, sizeof(iv)) != 1) {
        fprintf(stderr, "Error generating IV\n");
        EVP_CIPHER_CTX_free(ctx);
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    unsigned char key[32]; // 256-bit key
    const int iterations = 10000; // High iteration count for secure KDF
    unsigned char salt[16];
    if (RAND_bytes(salt, sizeof(salt)) != 1) {
        fprintf(stderr, "Error generating salt\n");
        EVP_CIPHER_CTX_free(ctx);
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    // Derive the key using a robust KDF
    if (!PKCS5_PBKDF2_HMAC(password, password_len, salt, sizeof(salt), iterations, EVP_sha256(), 32, key)) {
        fprintf(stderr, "Error deriving encryption key\n");
        EVP_CIPHER_CTX_free(ctx);
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    // Initialize the cipher
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Error initializing AES-256-CBC\n");
        EVP_CIPHER_CTX_free(ctx);
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    return ctx;
}

void destroy_cipher_context(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
