#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LOG_ENTRIES 50000000
#define LOG_ENTRY_SIZE (sizeof(time_t) + sizeof(char) * 5 + sizeof(int) + sizeof(char) * 256)

typedef struct {
    time_t timestamp;
    char severity[5];
    int id;
    char message[256];
} LogEntry;

LogEntry logBuffer[MAX_LOG_ENTRIES];
int logCount = 0;

void serializeLog(LogEntry *entry, char *buffer) {
    memcpy(buffer, &entry->timestamp, sizeof(time_t));
    buffer += sizeof(time_t);
    strncpy(buffer, entry->severity, sizeof(char) * 5);
    buffer += sizeof(char) * 5;
    memcpy(buffer, &entry->id, sizeof(int));
    buffer += sizeof(int);
    strncpy(buffer, entry->message, sizeof(char) * 256);
}

void deserializeLog(LogEntry *entry, char *buffer) {
    memcpy(&entry->timestamp, buffer, sizeof(time_t));
    buffer += sizeof(time_t);
    strncpy(entry->severity, buffer, sizeof(char) * 5);
    buffer += sizeof(char) * 5;
    memcpy(&entry->id, buffer, sizeof(int));
    buffer += sizeof(int);
    strncpy(entry->message, buffer, sizeof(char) * 256);
}

void logMessage(const char *severity, int id, const char *message) {
    if (logCount < MAX_LOG_ENTRIES) {
        LogEntry entry;
        time_t now = time(NULL);
        strcpy(entry.severity, severity);
        entry.id = id;
        strcpy(entry.message, message);
        serializeLog(&entry, logBuffer[logCount]);
        logCount++;
    }
}

void retrieveLogs(char *outputBuffer, size_t bufferSize) {
