        std::lock_guard<std::mutex> lock(mtx);
        if (taskMap.find(id) != taskMap.end()) return; // Duplicate task_id
        if (priority < 1 || priority > 5) return; // Invalid priority level
        TaskNode* newNode = new TaskNode(id, priority, estTime, actStartTime, stat);
        taskMap[id] = newNode;
        taskSet.insert(newNode);
    }

    bool removeTask(int id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = taskMap.find(id);
        if (it == taskMap.end()) return false; // Task not found
        taskSet.erase(it->second);
        delete it->second;
        taskMap.erase(it);
        return true;
    }

    int getTaskCount() const {
        std::lock_guard<std::mutex> lock(mtx);
        return taskMap.size();
    }

