        if (sortByPriority) {
            for (auto& node : taskSet) {
                // Process tasks by priority
            }
        } else {
            for (auto& node : taskMap) {
                // Process tasks by estimated_completion_time
            }
        }
    }

    std::vector<TaskNode*> getOverdueTasks(long threshold) {
        std::lock_guard<std::mutex> lock(mtx);
        std::vector<TaskNode*> overdue;
        for (auto& pair : taskMap) {
            if (pair.second->actual_start_time > pair.second->estimated_completion_time + threshold) {
                overdue.push_back(pair.second);
            }
        }
        return overdue;
    }

    void cleanUpCompletedTasks() {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& pair : taskMap) {
            if (pair.second->status == "completed") {
                taskSet.erase(pair.second);
                delete pair.second;
                taskMap.erase(pair.first);
            }
        }
    }

private:
    struct Comparator {
        bool operator()(const TaskNode* a, const TaskNode* b) const {
            if (a->estimated_completion_time != b->estimated_completion_time)
                return a->estimated_completion_time < b->estimated_completion_time;
            return a->priority_level > b->priority_level; // Descending priority
        }
    };
