typedef enum ConflictResolutionStrategy {
    APPEND_TIMESTAMP,
    OVERWRITE_ENTRY
} ConflictResolutionStrategy;

typedef struct PacketStore {
    DataPacket packets[MAX_PACKETS];
    int count;
    ConflictResolutionStrategy conflict_strategy;
} PacketStore;

void initialize_packet_store(PacketStore *store, ConflictResolutionStrategy strategy) {
    store->count = 0;
    store->conflict_strategy = strategy;
}

int add_packet(PacketStore *store, DataPacket packet) {
    for (int i = 0; i < store->count; i++) {
        if (store->packets[i].packet_id == packet.packet_id) {
            switch (store->conflict_strategy) {
                case APPEND_TIMESTAMP:
                    packet.timestamp += store->packets[i].timestamp;
                    break;
                case OVERWRITE_ENTRY:
                    // Overwrite existing entry
                    break;
                default:
                    return -1; // Invalid conflict strategy
            }
        }
    }

    if (store->count < MAX_PACKETS) {
        store->packets[store->count++] = packet;
        return 0;
    } else {
        return -1; // Packet store is full
    }
}

int remove_packet(PacketStore *store, int packet_id) {
    for (int i = 0; i < store->count; i++) {
        if (store->packets[i].packet_id == packet_id) {
            for (int j = i; j < store->count - 1; j++) {
                store->packets[j] = store->packets[j + 1];
            }
            store->count--;
            return 0;
        }
