class TaskNode {
public:
    int task_id;
    int priority_level;
    double estimated_completion_time;
    std::chrono::time_point<std::chrono::system_clock> actual_start_time;
    std::string status;
    std::vector<int> dependencies;

    TaskNode(int id, int priority, double estCompTime)
        : task_id(id), priority_level(priority), estimated_completion_time(estCompTime) {}
};

class TaskManager {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::set<TaskNode*, std::function<bool(const TaskNode*, const TaskNode*)>> tasks;
    std::atomic<int> log_count;
    std::ofstream log_file;

public:
    TaskManager() : log_count(0) {
        // Open log file
        log_file.open("task_log.txt", std::ios::app);
    }

    ~TaskManager() {
        // Close log file
        if (log_file.is_open()) {
            log_file.close();
        }
    }

    void addNode(TaskNode* node) {
        std::lock_guard<std::mutex> lock(mtx);
        tasks.insert(node, [](const TaskNode* a, const TaskNode* b) {
            return a->estimated_completion_time < b->estimated_completion_time ||
                   (a->estimated_completion_time == b->estimated_completion_time && a->priority_level > b->priority_level);
        });
        log_count++;
        if (log_count % 100000 == 0) {
            cleanupCompletedTasks();
        }
    }

    void removeNode(int task_id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = tasks.find(nullptr);
        while (it != tasks.end()) {
            if ((*it)->task_id == task_id) {
                tasks.erase(it);
                break;
            }
            ++it;
        }
    }

    void scheduleTasks() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]() { return !tasks.empty(); });
        TaskNode* nextTask = *tasks.begin();
        // Schedule the task
        log_task(nextTask->task_id, "Scheduled");
        tasks.erase(tasks.begin());
    }

    void cleanupCompletedTasks() {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = tasks.begin();
        while (it != tasks.end()) {
            if ((*it)->status == "completed") {
                tasks.erase(it++);
            } else {
                ++it;
            }
        }
    }

    void log_task(int task_id, std::string action) {
        if (log_file.is_open()) {
            log_file << "Task " << task_id << " - " << action << "\n";
        }
    }
};
