#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <algorithm>
#include <fstream>
#include <memory>

class TaskNode {
public:
    int task_id;
    int priority_level;
    int estimated_completion_time;
    int actual_start_time;
    std::string status;
    std::vector<int> dependencies;

    TaskNode(int id, int priority, int estCompletionTime, std::string status)
        : task_id(id), priority_level(priority), estimated_completion_time(estCompletionTime), status(status) {}
};

class TaskManager {
private:
    std::unordered_map<int, std::shared_ptr<TaskNode>> tasks;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void addTask(int id, int priority, int estCompletionTime, std::string status) {
        std::lock_guard<std::mutex> lock(mtx);
        if (tasks.find(id) != tasks.end()) throw std::runtime_error("Task ID already exists");
        tasks[id] = std::make_shared<TaskNode>(id, priority, estCompletionTime, status);
    }

    void removeTask(int id) {
        std::lock_guard<std::mutex> lock(mtx);
        if (tasks.find(id) == tasks.end()) throw std::runtime_error("Task ID does not exist");
        tasks.erase(id);
    }

    void verifyPriorityLevel(int priority) {
        if (priority < 1 || priority > 10) throw std::runtime_error("Invalid priority level");
    }

    void scheduleTasks() {
        std::vector<std::shared_ptr<TaskNode>> readyTasks;
        {
            std::lock_guard<std::mutex> lock(mtx);
            for (auto& [id, task] : tasks) {
                if (task->status == "ready") readyTasks.push_back(task);
            }
        }

        std::sort(readyTasks.begin(), readyTasks.end(), [](const auto& a, const auto& b) {
            return a->priority_level > b->priority_level || 
                   (a->priority_level == b->priority_level && a->estimated_completion_time < b->estimated_completion_time);
        });

        for (auto& task : readyTasks) {
            std::lock_guard<std::mutex> lock(mtx);
            if (task->status != "ready") continue;
            task->actual_start_time = get_current_time();
            task->status = "in_progress";
        }
    }

    void serializeData(const std::string& filename) {
        std::ofstream ofs(filename, std::ios::binary);
        for (auto& [id, task] : tasks) {
            ofs.write(reinterpret_cast<const char*>(&task->task_id), sizeof(int));
            ofs.write(reinterpret_cast<const char*>(&task->priority_level), sizeof(int));
            ofs.write(reinterpret_cast<const char*>(&task->estimated_completion_time), sizeof(int));
            ofs.write(reinterpret_cast<const char*>(&task->actual_start_time), sizeof(int));
            ofs.write(task->status.c_str(), task->status.size() + 1);
            ofs.write(reinterpret_cast<const char*>(task->dependencies.data()), task->dependencies.size() * sizeof(int));
        }
    }

    void deserializeData(const std::string& filename) {
        std::ifstream ifs(filename, std::ios::binary);
        while (!ifs.eof()) {
            int id, priority, estCompletionTime, actualStartTime;
            std::string status;
            std::vector<int> dependencies;

            ifs.read(reinterpret_cast<char*>(&id), sizeof(int));
            ifs.read(reinterpret_cast<char*>(&priority), sizeof(int));
            ifs.read(reinterpret_cast<char*>(&estCompletionTime), sizeof(int));
            ifs.read(reinterpret_cast<char*>(&actualStartTime), sizeof(int));

            char buffer[256];
            ifs.getline(buffer, 256);
            status = std::string(buffer);

            int depCount;
            ifs.read(reinterpret_cast<char*>(&depCount), sizeof(int));
            dependencies.resize(depCount);
            ifs.read(reinterpret_cast<char*>(dependencies.data()), depCount * sizeof(int));

            addTask(id, priority, estCompletionTime, status);
        }
    }

private:
    int get_current_time() {
        // Implement logic to return current time
        return 0;
    }
};
