<?php

function secureCipherInitialization($password, $mode = 'AES-256-CBC') {
    if (!in_array($mode, ['AES-256-CBC', 'AES-256-GCM'])) {
        throw new InvalidArgumentException('Unsupported encryption mode');
    }

    // Generate a random salt
    $salt = bin2hex(random_bytes(16));

    // Derive the key using PBKDF2 with a high iteration count
    $iterations = 100000;
    $keyLength = 32; // For AES-256
    $digest = 'sha256';
    $derivedKey = hash_pbkdf2($digest, $password, $salt, $iterations, $keyLength, true);

    // Generate a random IV for CBC mode
    if ($mode === 'AES-256-CBC') {
        $ivLength = openssl_cipher_iv_length('aes-256-cbc');
        $iv = bin2hex(random_bytes($ivLength));
    } else {
        $iv = null; // GCM does not require an IV
    }

    // Initialize the cipher context
    $cipherContext = openssl_get_cipher_methods();
    if (!in_array($mode, $cipherContext)) {
        throw new RuntimeException('Cipher mode is not supported');
    }

    $context = openssl_cipher_iv_length($mode) ? openssl_open_ssl_context($mode, $derivedKey, OPENSSL_RAW_DATA, $iv) : null;

    // Check for errors
    if (openssl_error_string()) {
        throw new RuntimeException(openssl_error_string());
    }

    return [
        'derived_key' => $derivedKey,
        'iv' => $iv,
        'context' => $context,
        'mode' => $mode,
        'salt' => $salt,
        'iterations' => $iterations
    ];
}

// Example usage:
try {
    $cipherParams = secureCipherInitialization('mySecretPassword', 'AES-256-GCM');
    print_r($cipherParams);
} catch (Exception $e) {
    echo 'Error: ' . $e->getMessage();
}
