#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_TRANSACTIONS 1000

typedef struct {
    int id;
    int weight;
    time_t timestamp;
} Transaction;

typedef struct {
    int count[5];
    int cumulative_count;
    int total_weight;
    int oldest_timestamp;
    int last_processed_time;
    Transaction queue[MAX_TRANSACTIONS];
    int queue_size;
} TransactionProcessor;

void init_processor(TransactionProcessor *processor) {
    for (int i = 0; i < 5; ++i) processor->count[i] = 0;
    processor->cumulative_count = 0;
    processor->total_weight = 0;
    processor->oldest_timestamp = time(NULL);
    processor->last_processed_time = time(NULL);
    processor->queue_size = 0;
}

int process_transaction(TransactionProcessor *processor, Transaction transaction) {
    if (time(NULL) - transaction.timestamp > 5) return -1; // Too old
    if (processor->cumulative_count >= 100) return -2; // Exceeded limit

    processor->count[(time(NULL) - transaction.timestamp)]++;
    processor->cumulative_count++;
    processor->total_weight += transaction.weight;

    if (transaction.timestamp < processor->oldest_timestamp) {
        processor->oldest_timestamp = transaction.timestamp;
    }

    while (processor->queue_size > 0 && time(NULL) - processor->queue[0].timestamp >= 1) {
        Transaction removed_transaction = processor->queue[0];
        processor->queue_size--;
        for (int i = 0; i < 5; ++i) {
            if (removed_transaction.timestamp <= processor->oldest_timestamp + i)
                processor->count[i]--;
        }
        processor->cumulative_count--;
        processor->total_weight -= removed_transaction.weight;
    }

    processor->queue[processor->queue_size++] = transaction;

    return processor->queue[0].id; // Return highest weighted transaction ID
}

int main() {
    TransactionProcessor processor;
    init_processor(&processor);

    // Simulate transactions
    for (int i = 1; i <= 150; ++i) {
        Transaction tx = {i, rand() % 10 + 1, time(NULL)};
        int result = process_transaction(&processor, tx);
        printf("Processed transaction %d, ID: %d\n", i, result);
    }

    return 0;
}
