    transactionQueue[rear] = newTransaction;
    totalWeight += newTransaction->weight;
    time_t now = time(NULL);
    int age = difftime(now, newTransaction->timestamp);
    transactionCount[0]++;
    if (age > 5) {
        transactionCount[(age / 5) + 1]++;
    }
    return rear;
}

// Function to remove transactions based on criteria and update metrics
void removeTransactions() {
    time_t now = time(NULL);
    while ((rear >= front) && difftime(now, transactionQueue[front]->timestamp) > 5) {
        totalWeight -= transactionQueue[front]->weight;
        front++;
        transactionCount[0]--;
    }
    for (int i = 1; i < 6; i++) {
