    }

    public String updateCacheAndProcessTasks(String key, Object value, long expirationTime) {
        cacheService.update(key, value, expirationTime);

        Task task = new Task(value, System.currentTimeMillis());
        String taskId = UUID.randomUUID().toString();
        taskQueue.put(taskId, task);
        taskCounter.incrementAndGet();

        updateAveragePriority();
        updateTasksPerMinute();

        List<Task> eligibleTasks = filterEligibleTasks();
        if (!eligibleTasks.isEmpty()) {
            Collections.sort(eligibleTasks, Comparator.comparingLong(Task::getPriority).reversed());
            Task highestPriorityTask = eligibleTasks.get(0);
            System.out.println("Highest Priority Task ID: " + highestPriorityTask.getId());
        }

        return taskId;
    }

    private List<Task> filterEligibleTasks() {
        long currentTime = System.currentTimeMillis();
        List<Task> eligibleTasks = taskQueue.values().stream()
                .filter(task -> currentTime - task.getSubmissionTime() <= 600000) // 10 minutes
                .filter(task -> tasksPerMinute[(int)((currentTime / 1000) % 60)].get() <= 1000)
                .collect(Collectors.toList());

        int recentTaskCount = taskQueue.values().stream()
                .filter(task -> currentTime - task.getSubmissionTime() <= 300000) // 5 minutes
                .mapToInt(task -> (int)task.getPriority())
                .sum();

        averagePriority.set((averagePriority.get() * (taskCounter.get() - recentTaskCount) + recentTaskCount) / taskCounter.get());

        if (recentTaskCount == 1000 && averagePriority.get() >= 75) {
            // Adjust submission rate limit
        }

        return eligibleTasks;
    }

    private void updateMetrics() {
        int currentMinute = (int)((System.currentTimeMillis() / 1000) % 60);
        tasksPerMinute[currentMinute].set(0); // Reset for new minute
    }

    private void updateAveragePriority() {
        int recentTaskCount = taskQueue.values().stream()
                .filter(task -> System.currentTimeMillis() - task.getSubmissionTime() <= 300000) // 5 minutes
                .mapToInt(task -> (int)task.getPriority())
                .sum();

        averagePriority.set((averagePriority.get() * (taskCounter.get() - recentTaskCount) + recentTaskCount) / taskCounter.get());
    }

    private void updateTasksPerMinute() {
        int currentMinute = (int)((System.currentTimeMillis() / 1000) % 60);
        tasksPerMinute[currentMinute].incrementAndGet();
    }

