#define MAX_LINE_LENGTH 1024

void process_file_and_find_max(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    int *integers = NULL;
    size_t array_size = 0;
    size_t line_number = 1;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        long number;
        if (sscanf(line, "%ld", &number) == 1) {
            // Resize the array to accommodate new integer
            integers = realloc(integers, (array_size + 1) * sizeof(int));
            if (integers == NULL) {
                perror("Memory allocation failed");
                fclose(file);
                return;
            }
            integers[array_size++] = number;
        } else {
            printf("Invalid input detected at line %zu\n", line_number);
        }
        line_number++;
    }

    fclose(file);

    if (array_size == 0) {
        printf("No integers provided.\n");
        free(integers);
        return;
    }

    // Find the maximum value
    long max_value = integers[0];
    for (size_t i = 1; i < array_size; i++) {
        if (integers[i] > max_value) {
            max_value = integers[i];
        }
    }

    printf("Maximum integer: %ld\n", max_value);

    // Find and print all occurrences of the maximum value
    for (size_t i = 0; i < array_size; i++) {
        if (integers[i] == max_value) {
            printf("Found at line %zu\n", i + 1);
        }
    }

    free(integers);
}
