import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.security.spec.InvalidKeySpecException;

public class MoSTStateDeserializer {

    public static MoSTState deserializeAndDecryptMoSTState(byte[] encryptedPayload, String password, Configuration config) {
        try {
            Cipher cipher = initializeCipher(config);
            IvParameterSpec iv = generateIV();
            byte[] keyBytes = deriveKey(password, config.getSalt(), config.getIterationCount());
            SecretKeySpec secretKeySpec = new SecretKeySpec(keyBytes, "AES");

            cipher.init(Cipher.DECRYPT_MODE, secretKeySpec, iv);

            ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(encryptedPayload);
            ObjectInputStream objectInputStream = new ObjectInputStream(byteArrayInputStream);

            try {
                return (MoSTState) objectInputStream.readObject();
            } catch (ClassNotFoundException e) {
                return null;
            } finally {
                objectInputStream.close();
            }
        } catch (IOException | NoSuchAlgorithmException | InvalidKeySpecException | BadPaddingException | IllegalBlockSizeException e) {
            throw new RuntimeException("Failed to deserialize and decrypt payload", e);
        } finally {
            // Securely destroy the cipher context
            if (cipher != null) {
                try {
                    cipher.doFinal();
                } catch (BadPaddingException | IllegalBlockSizeException e) {
                    // Ignore or log this exception as it should not occur after initialization
                }
            }
        }
    }

    private static Cipher initializeCipher(Configuration config) throws NoSuchAlgorithmException, InvalidKeySpecException {
        return Cipher.getInstance("AES/CBC/PKCS5Padding");
    }

    private static IvParameterSpec generateIV() {
        byte[] iv = new byte[16];
        SecureRandom secureRandom = new SecureRandom();
        secureRandom.nextBytes(iv);
        return new IvParameterSpec(iv);
    }

    private static byte[] deriveKey(String password, byte[] salt, int iterationCount) throws NoSuchAlgorithmException, InvalidKeySpecException {
        PBEKeySpec pbeKeySpec = new PBEKeySpec(password.toCharArray(), salt, iterationCount, 256);
        SecretKeyFactory secretKeyFactory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        return secretKeyFactory.generateSecret(pbeKeySpec).getEncoded();
    }

    public static class Configuration {
        private byte[] salt;
        private int iterationCount;

        public Configuration(byte[] salt, int iterationCount) {
            this.salt = salt;
            this.iterationCount = iterationCount;
        }

        public byte[] getSalt() {
            return salt != null ? salt : new byte[0];
        }

        public int getIterationCount() {
            return iterationCount > 10000 ? iterationCount : 10000; // Default to a high iteration count
        }
    }
}
