#include <memory>

class Element {
public:
    virtual ~Element() = default;
    virtual bool matches(const std::string& selector) const = 0;
};

class DOMNode : public Element {
public:
    DOMNode(Element* parent, const std::string& className = "", const std::string& id = "")
        : parent_(parent), className_(className), id_(id) {}

    void addChild(std::unique_ptr<Element> child) {
        children_.push_back(std::move(child));
    }

    bool matches(const std::string& selector) const override {
        if (!selector.empty()) {
            if (selector[0] == '#') {
                return id_ == selector.substr(1);
            } else if (selector[0] == '.') {
                return className_ == selector.substr(1);
            }
        }
        return false;
    }

private:
    Element* parent_;
    std::string className_;
    std::string id_;
    std::vector<std::unique_ptr<Element>> children_;
};

class DOMTreeTraverser {
public:
    using SelectorFunction = std::function<bool(const Element&)>;

    DOMTreeTraverser(Element& rootElement, SelectorFunction selectorFunction)
        : rootElement_(rootElement), selectorFunction_(selectorFunction) {}

    std::vector<Element*> GetMatchingElements(const std::string& selector) {
        std::vector<Element*> matchingElements;
        TraverseDOM(&rootElement_, selector, matchingElements);
        return matchingElements;
    }

    void ModifyElementAttributes(std::vector<Element*> elements, const std::string& attributeName, const std::string& attributeValue) {
        for (auto& element : elements) {
            ModifyAttribute(element.get(), attributeName, attributeValue);
        }
    }

    int GenerateRandomValueInRange(int minValue, int maxValue) {
        std::random_device rd;
        std::uniform_int_distribution<> dist(minValue, maxValue);
        return dist(rd);
    }

private:
    Element& rootElement_;
    SelectorFunction selectorFunction_;

    void TraverseDOM(Element* node, const std::string& selector, std::vector<Element*>& matchingElements) {
        if (node->matches(selector)) {
            matchingElements.push_back(node);
        }
        for (auto& child : node->children_) {
            TraverseDOM(child.get(), selector, matchingElements);
        }
    }

    void ModifyAttribute(Element* element, const std::string& attributeName, const std::string& attributeValue) {
        // Assuming Element has a method to set attributes
        element->setAttribute(attributeName, attributeValue);
    }
};
