#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 1000000
#define MAX_LOG_ENTRIES 50000000

typedef struct {
    int packet_id;
    long timestamp;
    size_t payload_size;
    int priority_level;
} DataPacket;

typedef struct {
    pthread_mutex_t lock;
    DataPacket packets[MAX_PACKETS];
    int count;
    int (*conflict_resolution)(int, int);
} PacketManager;

typedef struct {
    pthread_mutex_t lock;
    char entries[MAX_LOG_ENTRIES][1024];
    long timestamps[MAX_LOG_ENTRIES];
    int severity_levels[MAX_LOG_ENTRIES];
    char unique_ids[MAX_LOG_ENTRIES][64];
    int count;
} LogManager;

PacketManager pm;
LogManager lm;

int add_packet(PacketManager *pm, DataPacket packet) {
    pthread_mutex_lock(&pm->lock);
    for (int i = 0; i < pm->count; i++) {
        if (pm->packets[i].packet_id == packet.packet_id) {
            if (pm->conflict_resolution != NULL) {
                int result = pm->conflict_resolution(packet.packet_id, i);
                if (result == -1) {
                    pthread_mutex_unlock(&pm->lock);
                    return -1;
                }
            } else {
                pthread_mutex_unlock(&pm->lock);
                return -1;
            }
        }
    }
    pm->packets[pm->count++] = packet;
    pthread_mutex_unlock(&pm->lock);
    return 0;
}

int remove_packet(PacketManager *pm, int packet_id) {
    pthread_mutex_lock(&pm->lock);
    for (int i = 0; i < pm->count; i++) {
        if (pm->packets[i].packet_id == packet_id) {
            for (int j = i; j < pm->count - 1; j++) {
                pm->packets[j] = pm->packets[j + 1];
            }
            pm->count--;
            pthread_mutex_unlock(&pm->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&pm->lock);
    return -1;
}

int query_packet(PacketManager *pm, int packet_id) {
    pthread_mutex_lock(&pm->lock);
    for (int i = 0; i < pm->count; i++) {
        if (pm->packets[i].packet_id == packet_id) {
            pthread_mutex_unlock(&pm->lock);
            return i;
        }
    }
    pthread_mutex_unlock(&pm->lock);
    return -1;
}

int log_message(LogManager *lm, char *message, int severity_level, char *unique_id) {
    pthread_mutex_lock(&lm->lock);
    if (lm->count >= MAX_LOG_ENTRIES) {
        pthread_mutex_unlock(&lm->lock);
        return -1;
    }
    strcpy(lm->entries[lm->count], message);
    lm->timestamps[lm->count] = time(NULL);
    lm->severity_levels[lm->count] = severity_level;
    strcpy(lm->unique_ids[lm->count++], unique_id);
    pthread_mutex_unlock(&lm->lock);
    return 0;
}

int get_log_message(LogManager *lm, int index, char **message, int *severity_level, char **unique_id) {
    pthread_mutex_lock(&lm->lock);
    if (index < 0 || index >= lm->count) {
        pthread_mutex_unlock(&lm->lock);
        return -1;
    }
    *message = lm->entries[index];
    *severity_level = lm->severity_levels[index];
    *unique_id = lm->unique_ids[index];
    pthread_mutex_unlock(&lm->lock);
    return 0;
}

int main() {
    pm.count = 0;
    lm.count = 0;

    // Example usage
    DataPacket packet = {1, time(NULL), 1024, 5};
    add_packet(&pm, packet);

    char message[] = "Example log message";
    int severity_level = 3;
    char unique_id[] = "unique123";
    log_message(&lm, message, severity_level, unique_id);

    return 0;
}
