import subprocess
import datetime
import os

def modify_kickstart_file(template_path, substitutions, output_path):
    for placeholder, value in substitutions.items():
        command = f"sed -i 's|{placeholder}|{value}|" f"{template_path} > {output_path}"
        subprocess.run(command, shell=True, check=True)

def process_pokemon(pokemons, type_weaknesses, log_file):
    with open(log_file, 'a') as log:
        for pokemon in pokemons:
            try:
                weaknesses = [type_weaknesses[p.type] for p.type in pokemon.types]
                if not weaknesses:
                    raise ValueError(f"Unknown or inconsistent weaknesses for {pokemon.name}")
                weakness_str = ", ".join(weaknesses)
                print(f"Weaknesses of {pokemon.name}: {weakness_str}")
            except KeyError as e:
                log_entry = f"{datetime.datetime.now()}: Error - Missing type in weaknesses dictionary: {e}"
                log.write(log_entry + '\n')
                raise ValueError("Critical Pokemon type missing from weaknesses dictionary") from e

def rotate_log_files(log_directory, max_files):
    files = sorted(os.listdir(log_directory), key=lambda x: os.path.getmtime(os.path.join(log_directory, x)))
    while len(files) > max_files:
        os.remove(os.path.join(log_directory, files.pop(0)))

