#include <iostream>
#include <forward_list>
#include <stdexcept>

// Function to insert a new element after the first occurrence of a target in a forward list, or append if not found.
void insertAfterOrAppend(std::forward_list<std::string>& myList, const std::string& target, const std::string& insertion) {
    try {
        auto it = myList.begin();
        while (it != myList.end()) {
            if (*it == target) {
                // Insert after the current element
                it = myList.insert_after(it, insertion);
                // Move iterator past the inserted element to continue searching for additional targets
                it++;
                break;
            }
            ++it;
        }

        // If we reach here, the target was not found, append the item.
        if (it == myList.end()) {
            myList.push_back(insertion);
        }
    } catch (const std::exception& e) {
        std::cerr << "Exception occurred: " << e.what() << std::endl;
        // Handle or log exception as necessary
    }
}

// Function to demonstrate the usage of insertAfterOrAppend.
void demonstrateFunction() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    std::string target = "banana";
    std::string insertion = "grape";

    insertAfterOrAppend(myList, target, insertion);

    // Output the modified list
    for (const auto& item : myList) {
        std::cout << item << " ";
    }
    std::cout << std::endl;
}

int main() {
    demonstrateFunction();
    return 0;
}
```

