#include <boost/log/sources/record_ostream.hpp>

// Define severity levels
enum LogLevel {
    Trace,
    Debug,
    Info,
    Warning,
    Error,
    Fatal
};

typedef boost::log::sources::severity_logger<LogLevel> Logger;

void init_logging() {
    // Setup logging to file and console
    auto core = boost::log::core::get();

    boost::log::add_file_log(
        boost::log::keywords::file_name = "application_%N.log",
        boost::log::keywords::rotation_size = 10 * 1024 * 1024,
        boost::log::keywords::time_based_rotation = boost::log::sinks::file::rotation_at_time_point(0, 0, 0),
        boost::log::keywords::auto_flush = true
    );

    boost::log::add_console_log(
        std::cout,
        boost::log::keywords::format = "%TimeStamp% [%Severity%] %Message%"
    );

    core->set_filter(boost::log::trivial::severity >= boost::log::trivial::info);
}

Logger& get_logger(const std::string& category) {
    static Logger loggers[1024];
    static std::mutex mtx;
    std::lock_guard<std::mutex> lock(mtx);

    // Simple hash function for demonstration purposes
    size_t index = std::hash<std::string>()(category);
    if (!loggers[index].get()) {
        loggers[index] = Logger(boost::log::keywords::severity = boost::log::trivial::info);
    }
    return loggers[index];
}

void set_log_level(const std::string& category, LogLevel level) {
    auto& logger = get_logger(category);
    logger.set_filter(boost::log::trivial::severity >= level);
}
```

