using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Diagnostics;
using System.Linq;
using System.Threading.Tasks;

public class SqlBatchExecutor
{
    private const int MaxConcurrentConnections = 50;
    private readonly TimeSpan DefaultCommandTimeout = TimeSpan.FromSeconds(60);
    private readonly int MaxRetries = 3;

    public async Task<ExecutionSummary> ExecuteBatchAsync(List<string> sqlCommands, SqlConnection connection, bool atomicTransaction)
    {
        var summary = new ExecutionSummary();
        using (var transaction = atomicTransaction ? connection.BeginTransaction() : null)
        {
            var tasks = sqlCommands.Select((sqlCommand, index) => ExecuteCommandAsync(sqlCommand, connection, transaction, index)).ToList();
            await Task.WhenAll(tasks);

            if (atomicTransaction && transaction != null)
            {
                try
                {
                    transaction.Commit();
                }
                catch (Exception ex)
                {
                    summary.FailedCommands++;
                    summary.TotalFailed += 1;
                    summary.Log($"Transaction failed: {ex.Message}");
                }
            }

            foreach (var task in tasks)
            {
                summary.Merge(task.Result);
            }
        }

        return summary;
    }

    private async Task<CommandExecutionResult> ExecuteCommandAsync(string sqlCommand, SqlConnection connection, SqlTransaction transaction, int index)
    {
        var stopwatch = new Stopwatch();
        stopwatch.Start();

        var result = new CommandExecutionResult { Index = index };
        for (int attempt = 0; attempt <= MaxRetries; attempt++)
        {
            try
            {
                using (var command = new SqlCommand(sqlCommand, connection) { Transaction = transaction })
                {
                    command.CommandTimeout = DefaultCommandTimeout.TotalSeconds;

                    await command.ExecuteNonQueryAsync();
                    result.Success = true;
                    break;
                }
            }
            catch (Exception ex)
            {
                if (attempt == MaxRetries)
                {
                    result.Success = false;
                    result.ErrorMessage = $"Attempt {attempt + 1} failed: {ex.Message}";
                }
                else
                {
                    result.RetryCount++;
                    await Task.Delay(100 * attempt); // Exponential backoff
                }
            }
        }

        stopwatch.Stop();
        result.Duration = stopwatch.Elapsed;
        return result;
    }

    public class ExecutionSummary
    {
        public int SuccessfulCommands { get; private set; }
        public int FailedCommands { get; private set; }
        public int TotalFailed { get; private set; }
        public long TotalDurationTicks { get; private set; }

        public void Merge(CommandExecutionResult result)
        {
            if (result.Success)
                SuccessfulCommands++;
            else
            {
                FailedCommands++;
                TotalFailed += 1;
            }
            TotalDurationTicks += result.Duration.Ticks;
        }

        public override string ToString()
        {
            return $"Successful: {SuccessfulCommands}, Failed: {FailedCommands}, Retry Count: {TotalFailed}, Duration: {TotalDurationTicks} ticks";
        }
    }

    public class CommandExecutionResult
    {
        public int Index { get; private set; }
        public bool Success { get; private set; }
        public string ErrorMessage { get; private set; }
        public int RetryCount { get; private set; }
        public TimeSpan Duration { get; private set; }

        public override string ToString()
        {
            return $"Index: {Index}, Success: {Success}, ErrorMessage: {ErrorMessage}, Retry Count: {RetryCount}, Duration: {Duration}";
        }
    }
}
