public class OAuthAuthentication
{
    public static List<AuthToken> AuthenticateUserWithOAuth(string xmlContent, string xpathExpression)
    {
        try
        {
            XPathDocument document = new XPathDocument(xmlContent);
            XPathNavigator navigator = document.CreateNavigator();

            XPathNodeIterator iterator = navigator.Select(xpathExpression);

            if (!iterator.MoveNext())
            {
                throw new ArgumentException("No elements match the provided XPath expression.");
            }

            List<AuthToken> tokens = new List<AuthToken>();
            while (iterator.MoveNext())
            {
                string accessToken = iterator.Current.Value;

                // Validate and store the access token securely
                AuthToken token = ValidateAndStoreAccessToken(accessToken);
                tokens.Add(token);
            }

            return tokens;
        }
        catch (XPathException ex)
        {
            throw new XPathExpressionException("Invalid XPath expression.", ex);
        }
        catch (XmlReaderException ex)
        {
            throw new XmlSyntaxException("Malformed XML.", ex);
        }
