import java.io.*;
import java.util.zip.CRC32;

public class StateLoader {

    public static MoSTState loadState(String filePath) {
        MoSTState state = null;
        FileInputStream fileInputStream = null;
        ObjectInputStream objectInputStream = null;

        try {
            // Open the file input stream and object input stream
            fileInputStream = new FileInputStream(filePath);
            objectInputStream = new ObjectInputStream(fileInputStream);

            // Read the object from the file
            Object obj = objectInputStream.readObject();

            // Check if the object is an instance of MoSTState
            if (obj instanceof MoSTState) {
                state = (MoSTState) obj;

                // Verify checksum
                byte[] data = ((ByteArrayOutputStream) objectInputStream).toByteArray();
                long expectedChecksum = ExternalConfigService.getChecksum(filePath);
                CRC32 crc = new CRC32();
                crc.update(data, 0, data.length);
                if (crc.getValue() != expectedChecksum) {
                    logError("Checksum verification failed for file: " + filePath);
                    state = null;
                }
            }

        } catch (FileNotFoundException e) {
            logError("File not found: " + filePath, e);

        } catch (IOException e) {
            logError("IO error occurred while reading file: " + filePath, e);

        } catch (ClassNotFoundException e) {
            logError("Class not found for deserialized object", e);

        } finally {
            // Close the object input stream and file input stream
            try {
                if (objectInputStream != null) {
                    objectInputStream.close();
                }
                if (fileInputStream != null) {
                    fileInputStream.close();
                }
            } catch (IOException e) {
                logError("Error closing streams for file: " + filePath, e);
            }
        }

        return state;
    }

    private static void logError(String message) {
        System.err.println(message);
    }

    private static void logError(String message, Exception e) {
        System.err.println(message + ": " + e.getMessage());
        e.printStackTrace();
    }
}

