    // Database context for the application
}

public class ApplicationUserManager : UserManager<ApplicationUser, string>
{
    public ApplicationUserManager(IUserStore<ApplicationUser> store)
        : base(store)
    {
    }

    public static ApplicationUserManager Create(IdentityFactoryOptions<ApplicationUserManager> options, IOwinContext context)
    {
        var manager = new ApplicationUserManager(new UserStore<ApplicationUser>(context.Get<ApplicationDbContext>()));
        // Configure validation logic for passwords
        manager.PasswordValidator = new PasswordValidator
        {
            RequiredLength = int.Parse(ConfigurationManager.AppSettings["MinPasswordLength"]),
            RequireNonLetterOrDigit = bool.Parse(ConfigurationManager.AppSettings["RequireNonLetterOrDigit"]),
            RequireDigit = bool.Parse(ConfigurationManager.AppSettings["RequireDigit"]),
            RequireLowercase = bool.Parse(ConfigurationManager.AppSettings["RequireLowercase"]),
            RequireUppercase = bool.Parse(ConfigurationManager.AppSettings["RequireUppercase"])
        };
        // Configure lockout defaults
        manager.UserLockoutEnabledByDefault = true;
        manager.DefaultAccountLockoutTimeSpan = TimeSpan.FromMinutes(int.Parse(ConfigurationManager.AppSettings["DefaultAccountLockoutTimeSpan"]));
        manager.MaxFailedAccessAttemptsBeforeLockout = int.Parse(ConfigurationManager.AppSettings["MaxFailedAccessAttemptsBeforeLockout"]);
        return manager;
    }
}

public class AccountController : Controller
{
    private ApplicationUserManager _userManager;

    public AccountController()
    {
        _userManager = new ApplicationUserManager(new UserStore<ApplicationUser>(new ApplicationDbContext()));
    }

    [HttpPost]
    public async Task<ActionResult> Register(RegisterViewModel model)
    {
        if (ModelState.IsValid)
        {
            var user = new ApplicationUser { UserName = model.Email, Email = model.Email };
            // Validate username and password
            if (!await _userManager.CheckUsernameAsync(model.Username))
            {
                ModelState.AddModelError("", "Username is already taken.");
            }
            else if (!await _userManager.CheckPasswordAsync(user, model.Password))
            {
                ModelState.AddModelError("", "Invalid password format.");
            }

            if (ModelState.IsValid)
            {
                var result = await _userManager.CreateAsync(user, model.Password);
                if (result.Succeeded)
                {
                    return RedirectToAction("Index", "Home");
                }
                AddErrors(result);
            }
        }

        // If we got this far, something failed, redisplay form
        return View(model);
    }

    private bool CheckUsername(string username)
    {
        var regex = new Regex(ConfigurationManager.AppSettings["UsernamePattern"]);
        return regex.IsMatch(username);
    }

    private async Task<bool> CheckPasswordAsync(ApplicationUser user, string password)
    {
        var options = ApplicationUserManager.Create(null, null).PasswordValidator;
        if (!options.RequireNonLetterOrDigit && !options.RequireDigit && !options.RequireLowercase && !options.RequireUppercase)
            return true;

        var hashProvider = new Rfc2898DeriveBytes();
        var salt = Convert.FromBase64String(user.PasswordHash.Split('$')[1]);
        var hash = hashProvider.GetBytes(password, salt, 10000);

        var providedHash = Convert.ToBase64String(hash);
        return providedHash == user.PasswordHash.Split('$')[2];
    }

    private void AddErrors(IdentityResult result)
    {
        foreach (var error in result.Errors)
        {
            ModelState.AddModelError("", error);
        }
    }
}

public static class ValidationExtensions
{
    public static async Task<bool> CheckUsernameAsync(this ApplicationUserManager userManager, string username)
    {
        var user = await userManager.FindByNameAsync(username);
        return user == null;
    }

    public static async Task<bool> CheckPasswordAsync(this ApplicationUserManager userManager, ApplicationUser user, string password)
    {
        return await userManager.CheckPasswordAsync(user, password);
    }
}
