class ResourceUsageMetrics {
public:
    int metric_id;
    long timestamp;
    double cpu_usage;
    double memory_usage;
    int disk_iops;

    ResourceUsageMetrics(int id, long ts, double cpu, double mem, int iops)
        : metric_id(id), timestamp(ts), cpu_usage(cpu), memory_usage(mem), disk_iops(iops) {}
};

class MetricManager {
public:
    enum ConflictResolutionStrategy { APPEND_VERSION, DISCARD_NEW };

    void addMetric(const ResourceUsageMetrics& metric, ConflictResolutionStrategy strategy = APPEND_VERSION) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (metrics_.find(metric.metric_id) != metrics_.end()) {
            switch (strategy) {
                case APPEND_VERSION:
                    // Append version logic here
                    break;
                case DISCARD_NEW:
                    return; // Discard the new metric
            }
        }
        metrics_[metric.metric_id] = metric;
    }

    bool updateMetric(int id, const ResourceUsageMetrics& new_metric) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (metrics_.find(id) != metrics_.end()) {
            metrics_[id] = new_metric;
            return true;
        }
        return false;
    }

    ResourceUsageMetrics* queryMetric(int id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = metrics_.find(id);
        if (it != metrics_.end()) {
            return &it->second;
        }
        return nullptr;
    }

private:
    std::unordered_map<int, ResourceUsageMetrics> metrics_;
    std::mutex mutex_;
};

int main() {
    MetricManager manager;
    manager.addMetric({1, 1633072800, 5.5, 2.0, 10});
    auto* metric = manager.queryMetric(1);
    if (metric) {
        std::cout << "CPU Usage: " << metric->cpu_usage << std::endl;
    }
    return 0;
}
