const fs = require('fs');
const path = require('path');

// Load configuration file
const configPath = path.join(__dirname, 'config.json');
const bibleBooksConfig = JSON.parse(fs.readFileSync(configPath, 'utf8'));

function parseBibleReferences(text) {
    const { oldTestament, newTestament } = bibleBooksConfig;
    const bookRegex = new RegExp(`\\b(${oldTestament.join('|')}|${newTestament.join('|')})\\b`, 'gi');
    const verseRegex = /(\d+:\d+)/g;

    let bookCounts = {};
    let match;

    // Extract books and verses
    while ((match = bookRegex.exec(text)) !== null) {
        const book = match[0];
        bookCounts[book] = (bookCounts[book] || 0) + 1;
    }

    // Handle verse references
    while ((match = verseRegex.exec(text)) !== null) {
        const [_, chapter, verse] = match[0].split(':');
        const book = `Chapter ${chapter}, Verse ${verse}`;
        bookCounts[book] = (bookCounts[book] || 0) + 1;
    }

    return bookCounts;
}

module.exports = parseBibleReferences;
