function generateSidebar(configurations) {
    const sidebarHtml = `<nav class="sidebar">
                            <ul>
                                ${configurations.map(section => `
                                    <li>
                                        <h3 class="section-title">${section.title}</h3>
                                        <ul class="links" data-lazy-load>
                                            ${section.links.map(link => `
                                                <li><a href="${link.url}" aria-label="${link.alt}"><i class="icon-${section.icon}"></i>${link.text}</a></li>
                                            `).join('')}
                                        </ul>
                                    </li>
                                `).join('')}
                            </ul>
                        </nav>`;

    return sidebarHtml;
}

// Example usage:
const configurations = [
    {
        title: 'Dashboard',
        icon: 'home',
        links: [
            { url: '/dashboard/overview', text: 'Overview', alt: 'Overview of the dashboard' },
            // Add more links as needed
        ]
    },
    // Add more sections as needed
];

const sidebarHtml = generateSidebar(configurations);
document.getElementById('sidebar-container').innerHTML = sidebarHtml;

// Lazy loading for sections
document.addEventListener('DOMContentLoaded', () => {
    const lazyLoadSections = document.querySelectorAll('.links[data-lazy-load]');
    lazyLoadSections.forEach(section => {
        section.style.display = 'none';
        section.innerHTML = `
            <li>Loading...</li>
        `;
        fetch('/api/section-data')
            .then(response => response.json())
            .then(data => {
                if (data && data[section.parentElement.querySelector('.section-title').innerText]) {
                    const linksHtml = data[section.parentElement.querySelector('.section-title').innerText].map(link => `
                        <li><a href="${link.url}" aria-label="${link.alt}"><i class="icon-${section.closest('nav.sidebar').querySelector(`.section-title[aria-label='${section.parentElement.querySelector('.section-title').innerText}']`).closest('li').querySelector('.icon').className.split('-')[1]}"></i>${link.text}</a></li>
                    `).join('');
                    section.innerHTML = linksHtml;
                } else {
                    section.innerHTML = '<li>Error loading data</li>';
                }
            })
            .catch(error => {
                section.innerHTML = '<li>Error fetching data</li>';
            });
    });
});
