import threading
from collections import defaultdict

class LogAggregator:
    def __init__(self):
        self.logs = defaultdict(list)
        self.pause_event = threading.Event()
        self.lock = threading.Lock()

    def log_event(self, event):
        with self.lock:
            if not self.pause_event.is_set():
                self.logs[event['type']].append(event)

    def pause(self):
        self.pause_event.set()

    def resume(self):
        self.pause_event.clear()

    def filter_logs(self, type=None, error_code=None, start_time=None, end_time=None):
        with self.lock:
            filtered_logs = []
            for log_type, events in self.logs.items():
                if type is not None and log_type != type:
                    continue
                for event in events:
                    if (error_code is None or event['error_code'] == error_code) and \
                       (start_time is None or start_time <= event['timestamp'] <= end_time):
                        filtered_logs.append(event)
            return filtered_logs

    def generate_report(self, type=None, error_code=None, start_time=None, end_time=None):
        filtered_logs = self.filter_logs(type, error_code, start_time, end_time)
        report = {}
        for event in filtered_logs:
            if event['type'] not in report:
                report[event['type']] = {'count': 0}
            report[event['type']]['count'] += 1
        return report

# Example usage
log_aggregator = LogAggregator()
log_aggregator.log_event({'type': 'INFO', 'timestamp': 1633072800, 'error_code': None})
log_aggregator.log_event({'type': 'ERROR', 'timestamp': 1633072805, 'error_code': 404})
log_aggregator.pause()
# Add more log events
log_aggregator.resume()
report = log_aggregator.generate_report(type='ERROR')
print(report)
