class DOMElementSelector {
  constructor(maxBatchSize = 10, apiBackoffBase = 2, maxRetries = 5) {
    this.maxBatchSize = maxBatchSize;
    this.apiBackoffBase = apiBackoffBase;
    this.maxRetries = maxRetries;
    this.logEnabled = true;
  }

  enableLogging() {
    this.logEnabled = true;
  }

  disableLogging() {
    this.logEnabled = false;
  }

  async selectElements(criteria, parentNode = document) {
    try {
      const elements = Array.from(parentNode.querySelectorAll('*'));
      let selectedElements = [];
      for (let i = 0; i < elements.length; i += this.maxBatchSize) {
        const batch = elements.slice(i, i + this.maxBatchSize);
        if (this.logEnabled) console.log(`Processing batch of ${batch.length} elements`);
        const filteredBatch = batch.filter(element => this.matchesCriteria(element, criteria));
        selectedElements = selectedElements.concat(filteredBatch);
      }
      return await this.fetchMetadata(selectedElements);
    } catch (error) {
      if (this.logEnabled) console.error('Error during DOM traversal:', error);
      throw error;
    }
  }

  matchesCriteria(element, criteria) {
    return Object.keys(criteria).every(key => 
      key.startsWith('data-') ? element.getAttribute(key) === criteria[key] : element.getAttribute(key) === criteria[key]
    );
  }

  async fetchMetadata(elements) {
    const metadataPromises = [];
    for (let i = 0; i < elements.length; i += this.maxBatchSize) {
      const batch = elements.slice(i, i + this.maxBatchSize);
      const promise = this.fetchBatchMetadata(batch);
      metadataPromises.push(promise);
    }
    return Promise.all(metadataPromises);
  }

  async fetchBatchMetadata(elements) {
    let retries = 0;
    while (retries < this.maxRetries) {
      try {
        if (this.logEnabled) console.log(`Fetching metadata for ${elements.length} elements`);
        const response = await fetch('/api/metadata', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(elements.map(el => el.getAttribute('data-id')))
        });
        if (!response.ok) throw new Error('Network response was not ok');
        const data = await response.json();
        return elements.map(el => ({ ...el, metadata: data[el.getAttribute('data-id')] }));
      } catch (error) {
        retries++;
        const backoffTime = this.apiBackoffBase ** retries * 100;
        if (this.logEnabled) console.warn(`API request failed, retrying in ${backoffTime}ms`);
        await new Promise(resolve => setTimeout(resolve, backoffTime));
      }
    }
    throw new Error('Max API request retries exceeded');
  }

  logInfo(message) {
    if (this.logEnabled) console.info(message);
  }
}

// Example usage:
const selector = new DOMElementSelector();
selector.enableLogging();
selector.selectElements({ 'data-type': 'example', id: '123' }).then(elements => {
  elements.forEach(element => console.log(element.metadata));
}).catch(error => console.error('Error:', error));
```

This code defines a `DOMElementSelector` class with methods to traverse the DOM, filter elements based on criteria, and fetch metadata from an external API. It includes error handling, batch processing, logging, and a backoff strategy for API requests."]

["```javascript
// Load and execute JavaScript files dynamically with dependencies

class ScriptLoader {
  constructor(apiUrl, cache) {
    this.apiUrl = apiUrl;
    this.cache = cache || {};
    this.loadingScripts = new Set();
  }

  async loadScript(url) {
    if (this.loadingScripts.has(url)) return;

    try {
      const response = await fetch(url);
      if (!response.ok) throw new Error('Failed to fetch script');
      const scriptText = await response.text();

      const script = document.createElement('script');
      script.textContent = scriptText;
      document.head.appendChild(script);

      this.loadingScripts.delete(url);
      console.log(`Script loaded and executed: ${url}`);
    } catch (error) {
      console.error(`Error loading or executing script: ${url}`, error);
    }
  }

  async loadDependencies(dependencies, baseDir) {
    for (const dependency of dependencies) {
      const filePath = `${baseDir}/${dependency}`;
      if (!this.cache[filePath] || !this.cache[filePath].isUpToDate) {
        await this.fetchScriptMetadata(filePath);
      }

      if (this.cache[filePath].isAvailable) {
        await this.loadScript(filePath);
      } else {
        console.warn(`Skipping unavailable script: ${filePath}`);
      }
    }
  }

  async fetchScriptMetadata(filePath) {
    try {
      const response = await fetch(`${this.apiUrl}/metadata?file=${filePath}`);
      if (!response.ok) throw new Error('Failed to fetch metadata');
      const metadata = await response.json();
      this.cache[filePath] = metadata;
      console.log(`Metadata fetched for script: ${filePath}`, metadata);
    } catch (error) {
      console.error(`Error fetching metadata for script: ${filePath}`, error);
    }
  }

  async loadFile(fileId, role, deviceCapabilities) {
    try {
      const response = await fetch(`${this.apiUrl}/file?id=${fileId}`);
      if (!response.ok) throw new Error('Failed to fetch file');
      const fileData = await response.json();

      if (role !== fileData.requiredRole) {
        console.warn(`Skipping script for role: ${fileData.id} - Insufficient role`);
        return;
      }

      if (!deviceCapabilities.includes(fileData.requiredCapability)) {
        console.warn(`Skipping script for device: ${fileData.id} - Insufficient capabilities`);
        return;
      }

      await this.loadDependencies(fileData.dependencies, fileData.baseDir);
    } catch (error) {
      console.error(`Error loading file: ${fileId}`, error);
    }
  }
}

// Usage example
const apiUrl = 'https://api.example.com';
const cache = {};
const scriptLoader = new ScriptLoader(apiUrl, cache);

scriptLoader.loadFile('script1', 'admin', ['desktop']).then(() => {
  console.log('All files loaded successfully');
}).catch((error) => {
  console.error('Failed to load one or more files', error);
});
