import org.apache.kafka.clients.admin.*;
import java.util.*;
import java.util.concurrent.*;

public class KafkaMessageBrokerManager {

    private AdminClient adminClient;

    public KafkaMessageBrokerManager(String bootstrapServers) {
        Properties props = new Properties();
        props.put(AdminClientConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers);
        this.adminClient = AdminClient.create(props);
    }

    public void createTopic(String topicName, int numPartitions, short replicationFactor, Map<String, Object> configs) throws Exception {
        NewTopic newTopic = new NewTopic(topicName, numPartitions, replicationFactor)
                .configs(configs);
        CreateTopicsResult result = adminClient.createTopics(Collections.singletonList(newTopic));
        result.all().get();
    }

    public void deleteTopic(String topicName) throws Exception {
        DeleteTopicsResult result = adminClient.deleteTopics(Collections.singletonList(topicName));
        result.all().get();
    }

    public Map<String, Integer> getPartitionCountPerTopic() throws Exception {
        DescribeTopicsResult describeTopicsResult = adminClient.describeTopics(adminClient.listTopics().names().get());
        return describeTopicsResult.all().get().entrySet().stream()
                .collect(Collectors.toMap(Map.Entry::getKey, entry -> entry.getValue().partitions().size()));
    }

    public void addPartition(String topicName, int numAdditionalPartitions) throws Exception {
        AlterTopicResult alterTopicResult = adminClient.alterTopics(Collections.singletonList(
                new AlterTopicItem(topicName,
                        Collections.singleton(new AlterConfigOp("max.partitions.per.broker", ConfigOperationType.SET, Integer.toString(numAdditionalPartitions))))
        ));
        alterTopicResult.all().get();
    }

    public void close() {
        adminClient.close();
    }
}
```

This code snippet provides a basic implementation for managing a Kafka message broker system. It includes methods for creating and deleting topics, as well as adding partitions to existing topics. The `AdminClient` from the Kafka client library is used to interact with the Kafka cluster, performing administrative operations like topic creation and partition management. This example focuses on essential functionality and does not include advanced features such as leader election or detailed message handling optimizations.']

