public class ConfigurationManager
{
    private readonly ConcurrentDictionary<string, object> _cache = new ConcurrentDictionary<string, object>();
    private readonly HttpClient _httpClient = new HttpClient();
    private string _defaultConfigDir = "config";

    public ConfigurationManager(string defaultConfigDir = null)
    {
        if (!string.IsNullOrEmpty(defaultConfigDir))
            _defaultConfigDir = defaultConfigDir;
    }

    public async Task<T> GetConfigurationAsync<T>(string configKey, string url)
    {
        if (!_cache.TryGetValue(configKey, out var cachedValue) || cachedValue == null)
        {
            await UpdateAndCacheConfigurationAsync(configKey, url);
        }

        return (T)_cache[configKey];
    }

    private async Task UpdateAndCacheConfigurationAsync(string configKey, string url)
    {
        try
        {
            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();
            var jsonConfig = await response.Content.ReadAsStringAsync();

            // Parse and validate the JSON configuration
            var configObject = DeserializeJsonToConfig(jsonConfig);

            _cache.TryAdd(configKey, configObject);
        }
        catch (HttpRequestException)
        {
            Console.WriteLine($"Failed to fetch configuration for {configKey}");
        }
    }

    private object DeserializeJsonToConfig(string json)
    {
        // Implement JSON deserialization logic here
        return JsonConvert.DeserializeObject(json);
    }

    public void InitializeDefaultConfigDir()
    {
        if (!System.IO.Directory.Exists(_defaultConfigDir))
        {
            System.IO.Directory.CreateDirectory(_defaultConfigDir);
        }
    }
}

// Example usage:
public class Program
{
    public static async Task Main(string[] args)
    {
        var configManager = new ConfigurationManager("custom_config");
        configManager.InitializeDefaultConfigDir();

        var configValue = await configManager.GetConfigurationAsync<string>("appSetting", "https://example.com/config/app.json");
        Console.WriteLine(configValue);
    }
}
