#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int *items;
    size_t head;
    size_t tail;
    size_t capacity;
    sem_t mutex;
    sem_t slots;
    sem_t items_in_queue;
} ThreadSafeQueue;

ThreadSafeQueue* create_queue(size_t capacity) {
    ThreadSafeQueue *queue = (ThreadSafeQueue*) malloc(sizeof(ThreadSafeQueue));
    queue->items = (int*) malloc(capacity * sizeof(int));
    queue->head = 0;
    queue->tail = 0;
    queue->capacity = capacity;
    sem_init(&queue->mutex, 0, 1);
    sem_init(&queue->slots, 0, capacity);
    sem_init(&queue->items_in_queue, 0, 0);
    return queue;
}

void destroy_queue(ThreadSafeQueue *queue) {
    free(queue->items);
    sem_destroy(&queue->mutex);
    sem_destroy(&queue->slots);
    sem_destroy(&queue->items_in_queue);
    free(queue);
}

int enqueue(ThreadSafeQueue *queue, int item) {
    sem_wait(&queue->slots);
    sem_wait(&queue->mutex);
    queue->items[queue->tail] = item;
    queue->tail = (queue->tail + 1) % queue->capacity;
    sem_post(&queue->mutex);
    sem_post(&queue->items_in_queue);
    return 0;
}

int dequeue(ThreadSafeQueue *queue, int *item) {
    sem_wait(&queue->items_in_queue);
    sem_wait(&queue->mutex);
    *item = queue->items[queue->head];
    queue->head = (queue->head + 1) % queue->capacity;
    sem_post(&queue->mutex);
    sem_post(&queue->slots);
    return 0;
}
