import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;

public class ServiceManager {
    private ThreadSafeQueue queue;
    private boolean running = false;
    private final int maxLatency = 10; // in seconds

    public ServiceManager(ThreadSafeQueue queue) {
        this.queue = queue;
    }

    public void startService() throws InterruptedException {
        running = true;
        while (running) {
            Thread.sleep((long) Math.random() * maxLatency * 1000);
            if (!queue.isFull()) {
                int data = produceData();
                queue.enqueue(data);
                reportStatus("Service started");
            } else {
                reportStatus("Queue is full, service cannot start");
            }
        }
    }

    public void stopService() {
        running = false;
    }

    private int produceData() {
        // Generate or retrieve data to be enqueued
        return (int) (Math.random() * 100);
    }

    private void reportStatus(String status) {
        try {
            URL url = new URL("http://monitoring-system/api/status");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("POST");
            conn.setDoOutput(true);

            String input = "{\"status\": \"" + status + "\"}";
            try (OutputStream os = conn.getOutputStream()) {
                byte[] inputBytes = input.getBytes("utf-8");
                os.write(inputBytes, 0, inputBytes.length);           
            }

            if (conn.getResponseCode() != HttpURLConnection.HTTP_OK) {
                throw new RuntimeException("Failed : HTTP error code : " + conn.getResponseCode());
            }
        } catch (Exception e) {
            System.err.println("Error reporting status: " + e.getMessage());
        }
    }

    public boolean isFull() {
        // Implement logic to check if the queue is full
        return false;
    }
}
