#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} PacketList;

void addPacket(PacketList* list, DataPacket packet) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    newNode->data = packet;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
}

void removePacket(PacketList* list, int packet_id) {
    Node** current = &list->head;
    while (*current != NULL) {
        if ((*current)->data.packet_id == packet_id) {
            Node* temp = *current;
            *current = (*current)->next;
            free(temp);
            list->count--;
            return;
        }
        current = &(*current)->next;
    }
}

size_t getPacketCount(PacketList* list) {
    return list->count;
}

void sortPacketsByTimestamp(PacketList* list) {
    Node** arr = (Node**)malloc(list->count * sizeof(Node*));
    if (arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    size_t i = 0;
    for (Node* current = list->head; current != NULL; current = current->next) {
        arr[i++] = current;
    }

    qsort(arr, list->count, sizeof(Node*), [](const void* a, const void* b) {
        return ((Node*)a)->data.timestamp - ((Node*)b)->data.timestamp;
    });

    Node* newHead = NULL;
    for (size_t j = 0; j < list->count; j++) {
        arr[j]->next = newHead;
        newHead = arr[j];
    }

    free(arr);
    list->head = newHead;
}

void displayPackets(PacketList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("Packet ID: %d, Timestamp: %ld, Payload Size: %zu\n",
               current->data.packet_id, current->data.timestamp, current->data.payload_size);
        current = current->next;
    }
}

int main() {
    PacketList packetList = {NULL, 0};

    DataPacket packet1 = {1, time(NULL), 1024};
    DataPacket packet2 = {2, time(NULL) + 60, 512};
    DataPacket packet3 = {3, time(NULL) + 120, 2048};

    addPacket(&packetList, packet1);
    addPacket(&packetList, packet2);
    addPacket(&packetList, packet3);

    printf("Number of packets: %zu\n", getPacketCount(&packetList));

    sortPacketsByTimestamp(&packetList);
    displayPackets(&packetList);

    removePacket(&packetList, 1);
    printf("\nAfter removing Packet ID 1:\n");
    displayPackets(&packetList);

    return 0;
}
