#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
} PacketCollection;

void init_packet_collection(PacketCollection *collection) {
    collection->packets = malloc(INITIAL_CAPACITY * sizeof(DataPacket));
    if (collection->packets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection->count = 0;
    collection->capacity = INITIAL_CAPACITY;
}

void add_packet(PacketCollection *collection, DataPacket packet) {
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        DataPacket *new_packets = realloc(collection->packets, new_capacity * sizeof(DataPacket));
        if (new_packets == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        collection->packets = new_packets;
        collection->capacity = new_capacity;
    }
    collection->packets[collection->count++] = packet;
}

int remove_packet(PacketCollection *collection, int packet_id) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->packets[i].packet_id == packet_id) {
            for (size_t j = i; j < collection->count - 1; ++j) {
                collection->packets[j] = collection->packets[j + 1];
            }
            --collection->count;
            return 0;
        }
    }
    return -1;
}

size_t get_packet_count(const PacketCollection *collection) {
    return collection->count;
}

void sort_packets_by_timestamp(PacketCollection *collection) {
    for (size_t i = 0; i < collection->count - 1; ++i) {
        for (size_t j = 0; j < collection->count - i - 1; ++j) {
            if (collection->packets[j].timestamp > collection->packets[j + 1].timestamp) {
                DataPacket temp = collection->packets[j];
                collection->packets[j] = collection->packets[j + 1];
                collection->packets[j + 1] = temp;
            }
        }
    }
}

void free_packet_collection(PacketCollection *collection) {
    free(collection->packets);
}
