#include <iostream>
#include <vector>
#include <unordered_map>
#include <algorithm>

class LogEntry {
public:
    int entry_id;
    std::string timestamp;
    std::string log_level;
    std::string message;

    LogEntry(int id, const std::string& ts, const std::string& level, const std::string& msg)
        : entry_id(id), timestamp(ts), log_level(level), message(msg) {}
};

class LogEntryManager {
private:
    std::unordered_map<int, LogEntry*> entries;
    std::vector<LogEntry*> sortedEntries;

public:
    void addEntry(LogEntry* entry) {
        if (entries.find(entry->entry_id) != entries.end()) {
            throw std::runtime_error("Entry ID already exists");
        }
        entries[entry->entry_id] = entry;
        sortedEntries.push_back(entry);
    }

    void removeEntry(int id) {
        auto it = entries.find(id);
        if (it == entries.end()) return;

        for (auto& se : sortedEntries) {
            if (se->entry_id == id) {
                sortedEntries.erase(std::remove(sortedEntries.begin(), sortedEntries.end(), se), sortedEntries.end());
                break;
            }
        }

        delete it->second;
        entries.erase(it);
    }

    int getTotalEntries() const {
        return entries.size();
    }

    std::vector<LogEntry*> getByLogLevel(const std::string& level) const {
        std::vector<LogEntry*> result;
        for (const auto& se : sortedEntries) {
            if (se->log_level == level) {
                result.push_back(se);
            }
        }
        return result;
    }

    std::vector<LogEntry*> getByTimestampRange(const std::string& startTs, const std::string& endTs) const {
        std::vector<LogEntry*> result;
        for (const auto& se : sortedEntries) {
            if (se->timestamp >= startTs && se->timestamp <= endTs) {
                result.push_back(se);
            }
        }
        return result;
    }
};

int main() {
    LogEntryManager manager;
    manager.addEntry(new LogEntry(1, "2023-04-01 10:00", "INFO", "System started"));
    manager.addEntry(new LogEntry(2, "2023-04-01 10:05", "ERROR", "Disk space low"));

    auto entriesByLevel = manager.getByLogLevel("ERROR");
