#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct State {
    int id;
    float transition_probabilities[26];
    time_t timestamp;
    struct State* next;
} State;

typedef struct FSA {
    // Define the structure of your FSA here
} FSA;

State* merge_state_lists(State** states, int num_states, FSA* fsa, pthread_mutex_t* mutex) {
    pthread_mutex_lock(mutex);
    State* head = NULL;
    State** tail_ptr = &head;

    for (int i = 0; i < num_states; i++) {
        State* current = states[i];
        while (current != NULL) {
            if (*tail_ptr == NULL) {
                *tail_ptr = malloc(sizeof(State));
                if (*tail_ptr == NULL) {
                    pthread_mutex_unlock(mutex);
                    return NULL;
                }
                (*tail_ptr)->id = current->id;
                for (int j = 0; j < 26; j++) {
                    (*tail_ptr)->transition_probabilities[j] = current->transition_probabilities[j];
                }
                (*tail_ptr)->timestamp = current->timestamp;
                (*tail_ptr)->next = NULL;
            } else {
                State* new_state = malloc(sizeof(State));
                if (new_state == NULL) {
                    pthread_mutex_unlock(mutex);
                    return NULL;
                }
                new_state->id = current->id;
                for (int j = 0; j < 26; j++) {
                    new_state->transition_probabilities[j] = current->transition_probabilities[j];
                }
                new_state->timestamp = current->timestamp;
                new_state->next = NULL;
                (*tail_ptr)->next = new_state;
                *tail_ptr = new_state;
            }
            State* temp = current;
            current = current->next;
            free(temp);
        }
    }

    // Update the 'next' pointer of the last state in each input stream
    for (int i = 0; i < num_states - 1; i++) {
        State* prev_tail = *tail_ptr;
        while (prev_tail->next != NULL) {
            prev_tail = prev_tail->next;
        }
        prev_tail->next = head;
    }

    pthread_mutex_unlock(mutex);
    return head;
}
