#include <unordered_map>

class AttackManager {
private:
    std::unordered_map<std::string, double> cooldowns;
    double lastCooldownUpdate;
    std::mutex mtx;
    std::condition_variable cv;

public:
    AttackManager() : cooldowns({{"A", 12}, {"B", 8}, {"C", 10}}), lastCooldownUpdate(0) {}

    void updateCooldowns(const std::unordered_map<std::string, double>& newCooldowns) {
        std::lock_guard<std::mutex> lock(mtx);
        cooldowns = newCooldowns;
        cv.notify_all();
    }

    void selectAttack() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            if (cv.wait_until(lock, std::chrono::system_clock::now() + std::chrono::seconds(1), [this] { return true; })) {
                double currentTime = std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count();
                if (currentTime - lastCooldownUpdate > 60) {
                    fetchCooldownsFromServer(); // Simulate fetching new cooldowns
                    lastCooldownUpdate = currentTime;
                }

                std::string selectedAttack = "C"; // Fallback to Attack C initially
                double minCooldown = 0;

                for (const auto& attack : cooldowns) {
                    if (attack.second <= 0 && (minCooldown == 0 || attack.second < minCooldown)) {
                        selectedAttack = attack.first;
                        minCooldown = attack.second;
                    }
                }

                if (selectedAttack != "C") {
                    std::cout << "Selected Attack: " << selectedAttack << ", Cooldown: " << cooldowns[selectedAttack] << " seconds" << std::endl;
                    cooldowns[selectedAttack] -= 1; // Decrease the cooldown for the selected attack
                    cv.notify_all(); // Notify other threads about the change in cooldown
                } else {
                    useFallbackStrategy();
                }
            }
        }
    }

private:
    void fetchCooldownsFromServer() {
        // Simulate fetching new cooldowns from an external server
        std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate network delay
        std::unordered_map<std::string, double> newCooldowns = {{"A", 12}, {"B", 8}, {"C", 10}};
        updateCooldowns(newCooldowns);
    }

    void useFallbackStrategy() {
        static int cycleCount = 0;
        if (cycleCount == 0) {
            std::cout << "Using Fallback Strategy - Attack C for 5 seconds" << std::endl;
            cooldowns["A"] -= 5;
            cycleCount++;
        } else if (cycleCount == 1) {
            std::cout << "Using Fallback Strategy - Attack B for 10 seconds" << std::endl;
            cooldowns["B"] -= 10;
            cycleCount++;
        } else if (cycleCount == 2) {
            std::cout << "Using Fallback Strategy - Attack A for 15 seconds" << std::endl;
            cooldowns["C"] -= 15;
            cycleCount = 0; // Reset the cycle
        }
    }
};

int main() {
    AttackManager attackManager;
    std::thread t(&AttackManager::selectAttack, &attackManager);
    t.join();
    return 0;
}
