namespace randomNumberGenerator {
    class MersenneTwister {
    public:
        MersenneTwister() : mt_(std::random_device{}()) {}
        ~MersenneTwister() = default;

        static MersenneTwister& getInstance() {
            static MersenneTwister instance;
            return instance;
        }

        void reduceArray(const int* array, int size, int initialValue, const std::function<void(int, int)>& callback) {
            int accumulatedValue = initialValue;
            for (int i = 0; i < size; ++i) {
                accumulatedValue = callback(accumulatedValue, array[i]);
                std::uniform_int_distribution<int> dis(0, 100);
                mt_.seed(dis(mt_));
            }
        }

    private:
        std::mt19937 mt_;
    };
}

int main() {
    int sampleArray[] = {1, 2, 3, 4, 5};
    const size_t arraySize = sizeof(sampleArray) / sizeof(sampleArray[0]);
    int initialValue = 0;

    auto callback = [](int accumulated, int current) -> int {
        return accumulated + current;
    };

    randomNumberGenerator::MersenneTwister& mt = randomNumberGenerator::MersenneTwister::getInstance();
    mt.reduceArray(sampleArray, arraySize, initialValue, callback);

    return 0;
}
