class ServiceManager {
public:
    bool runServiceInBackground(const std::string& command) {
        pid_t pid = fork();
        if (pid == -1) {
            return false;
        } else if (pid == 0) {
            execlp(command.c_str(), nullptr);
            exit(EXIT_FAILURE);
        }
        int status;
        waitpid(pid, &status, 0);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0;
    }

    void startAndStopRandomly(const std::string& serviceName, const std::function<void()>& callback, unsigned int minDelay, unsigned int maxDelay) {
        srand(time(nullptr));
        while (true) {
            if (runServiceInBackground(serviceName)) {
                std::cout << "Service started: " << serviceName << std::endl;
                callback();
                std::cout << "Service stopped: " << serviceName << std::endl;
            }
            unsigned int delay = minDelay + rand() % (maxDelay - minDelay);
            sleep(delay);
        }
    }
};

int main() {
    ServiceManager manager;
    auto callback = []() {
        std::cout << "Message sent to messaging system" << std::endl;
    };
    manager.startAndStopRandomly("my_service", callback, 5, 10);
    return 0;
}
