using System;
using System.Diagnostics;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;

public class SiteManager
{
    private static readonly HttpClient httpClient = new HttpClient();

    public async Task<(bool, string)> AddAndStartSite(string directoryPath, string siteName)
    {
        try
        {
            // Check if web.config exists in the directory
            string configPath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(configPath))
            {
                // Attempt to retrieve web.config from a predefined configuration repository
                configPath = await DownloadWebConfigAsync(siteName);
                if (string.IsNullOrEmpty(configPath))
                {
                    return (false, "Failed to retrieve web.config.");
                }
            }

            // Start the site using Process class
            string processPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), "dotnet", $"dotnet.exe");
            var startInfo = new ProcessStartInfo(processPath)
            {
                Arguments = $"{directoryPath}",
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false
            };

            using (var process = new Process { StartInfo = startInfo })
            {
                process.Start();

                string output = await process.StandardOutput.ReadToEndAsync();
                string error = await process.StandardError.ReadToEndAsync();

                process.WaitForExit();

                if (!string.IsNullOrEmpty(error))
                {
                    return (false, $"Failed to start site: {error}");
                }

                return (true, $"Site started successfully. Output: {output}");
            }
        }
        catch (Exception ex)
        {
            return (false, $"An error occurred: {ex.Message}");
        }
    }

    private static async Task<string> DownloadWebConfigAsync(string siteName)
    {
        // Implement retry logic with exponential backoff
        int maxRetries = 5;
        int delayMilliseconds = 100;

        for (int attempt = 0; attempt <= maxRetries; attempt++)
        {
            try
            {
                string configUrl = $"https://configrepo.com/{siteName}/web.config";
                HttpResponseMessage response = await httpClient.GetAsync(configUrl);
                if (response.IsSuccessStatusCode)
                {
                    string configPath = Path.Combine(Path.GetTempPath(), "web.config");
                    using (var fileStream = new FileStream(configPath, FileMode.Create))
                    {
                        await response.Content.CopyToAsync(fileStream);
                    }
                    return configPath;
                }
            }
            catch
            {
                // Log exception and retry after delay
                if (attempt == maxRetries)
                {
                    return null;
                }
                await Task.Delay(delayMilliseconds);
                delayMilliseconds *= 2; // Exponential backoff
            }
        }

        return null;
    }
}
