import java.io.InputStreamReader;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Properties;

public class CommandExecutor {

    private static final int MAX_RETRIES = 3;
    private static final String LOG_FILE = "command_execution.log";

    public void executeCommand(String command, File workingDir) {
        for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
            try {
                Runtime.getRuntime().exec(command, null, workingDir);
                log("Command executed successfully: " + command);
                break;
            } catch (IOException e) {
                if (attempt == MAX_RETRIES) {
                    log("Failed to execute command after " + MAX_RETRIES + " attempts: " + command);
                    handleFailure(e);
                } else {
                    log("Attempt " + attempt + " failed. Retrying in 5 seconds...");
                    Thread.sleep(5000);
                }
            }
        }
    }

    public void deleteFile(File file) {
        int retries = 0;
        while (file.exists() && retries < MAX_RETRIES) {
            try {
                if (!file.delete()) {
                    throw new IOException("Failed to delete file: " + file.getAbsolutePath());
                }
                log("File deleted successfully: " + file.getAbsolutePath());
                break;
            } catch (IOException e) {
                retries++;
                if (retries == MAX_RETRIES) {
                    log("Failed to delete file after " + MAX_RETRIES + " attempts: " + file.getAbsolutePath());
                    handleFailure(e);
                } else {
                    log("Attempt " + retries + " failed. Retrying in 5 seconds...");
                    try {
                        Thread.sleep(5000);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        }
    }

    private void log(String message) {
        // Implement logging to a file using LOG_FILE
    }

    private void handleFailure(Exception e) {
        // Handle failure gracefully, e.g., by sending an alert or logging the error
    }

    public static String calculateMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            BigInteger no = new BigInteger(1, messageDigest);
            StringBuilder hashtext = new StringBuilder(no.toString(16));
            while (hashtext.length() < 32) {
                hashtext.insert(0, "0");
            }
            return hashtext.toString();
        } catch (NoSuchAlgorithmException e) {
            // Handle exception gracefully
            return null;
        }
    }

    public static void main(String[] args) {
        Properties properties = new Properties();
        try (InputStream input = CommandExecutor.class.getClassLoader().getResourceAsStream("config.properties")) {
            if (input == null) {
                System.out.println("Sorry, unable to find config.properties");
                return;
            }
            properties.load(input);
            String command = properties.getProperty("command");
            File workingDir = new File(properties.getProperty("workingDirectory"));
            CommandExecutor executor = new CommandExecutor();
            executor.deleteFile(new File(properties.getProperty("fileToDelete")));
            executor.executeCommand(command, workingDir);
        } catch (IOException ex) {
            ex.printStackTrace();
        }
    }
}
