#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int packet_id;
    long timestamp;
    size_t payload_size;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} PacketList;

void init_packet_list(PacketList* list) {
    list->head = NULL;
    list->count = 0;
}

Node* create_node(DataPacket packet) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->data = packet;
    newNode->next = NULL;
    return newNode;
}

void add_packet(PacketList* list, DataPacket packet) {
    Node* newNode = create_node(packet);
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
}

Node* find_packet_by_id(PacketList* list, int packet_id) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.packet_id == packet_id) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void remove_packet_by_id(PacketList* list, int packet_id) {
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.packet_id == packet_id) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->count--;
            return;
        }
        prev = current;
        current = current->next;
    }
}

size_t get_packet_count(PacketList* list) {
    return list->count;
}

void sort_packets_by_timestamp(PacketList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        while (next != NULL && next->data.timestamp < current->data.timestamp) {
            DataPacket temp = current->data;
            current->data = next->data;
            next->data = temp;
            next = next->next;
        }
        current = next;
    }
}

void free_packet_list(PacketList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->count = 0;
}

int main() {
    PacketList packetList;
    init_packet_list(&packetList);

    DataPacket packet1 = {1, 1633072800, 512};
    DataPacket packet2 = {2, 1633072810, 1024};

    add_packet(&packetList, packet1);
    add_packet(&packetList, packet2);

    sort_packets_by_timestamp(&packetList);

    remove_packet_by_id(&packetList, 1);

    printf("Packet count: %zu\n", get_packet_count(&packetList));

    free_packet_list(&packetList);

    return 0;
}
