    private readonly ConcurrentDictionary<string, byte[]> _keyCache = new ConcurrentDictionary<string, byte[]>();
    private readonly ConcurrentDictionary<string, byte[]> _ivCache = new ConcurrentDictionary<string, byte[]>();

    public async Task DecryptBatch(string configFilePath)
    {
        try
        {
            var config = LoadConfig(configFilePath);
            var messages = LoadMessagesFromDataSource();
            var tasks = new List<Task>();

            foreach (var message in messages)
            {
                tasks.Add(DecryptAsync(message, config));
            }

            await Task.WhenAll(tasks);
        }
        catch (Exception ex)
        {
            LogError($"An error occurred during batch decryption: {ex.Message}");
        }
    }

    private async Task DecryptAsync(string base64Message, Config config)
    {
        try
        {
            var messageBytes = Convert.FromBase64String(base64Message);
            byte[] key;
            byte[] iv;

            if (!_keyCache.TryGetValue(config.KeyId, out key))
            {
                key = await LoadKeyAsync(config.KeyId, config.KeyFilePath);
                _keyCache.TryAdd(config.KeyId, key);
            }

            if (!_ivCache.TryGetValue(config.IvId, out iv))
            {
                iv = await LoadIvAsync(config.IvId, config.IvFilePath);
                _ivCache.TryAdd(config.IvId, iv);
