using System;
using System.Collections.Generic;

public enum PacketFormatVersion { Version1, Version2 }
public enum LogLevel { None, Error, Warning, Info }

public class NetworkPacket
{
    public string SourceIP { get; set; }
    public string DestinationIP { get; set; }
    public int ProtocolType { get; set; }
    public byte[] Payload { get; set; }
    public DateTime Timestamp { get; set; }
    public Dictionary<string, object> Metadata { get; set; } = new Dictionary<string, object>();
}

public class PacketValidator
{
    private readonly string expectedSourceIP;
    private readonly string expectedDestinationIP;
    private readonly int expectedProtocolType;
    private readonly ChecksumAlgorithm checksumAlgorithm;
    private readonly PacketFormatVersion formatVersion;
    private readonly LogLevel logLevel;
    private readonly int discardThreshold;

    public PacketValidator(string expectedSourceIP, string expectedDestinationIP, int expectedProtocolType, ChecksumAlgorithm checksumAlgorithm, PacketFormatVersion formatVersion, LogLevel logLevel, int discardThreshold)
    {
        this.expectedSourceIP = expectedSourceIP;
        this.expectedDestinationIP = expectedDestinationIP;
        this.expectedProtocolType = expectedProtocolType;
        this.checksumAlgorithm = checksumAlgorithm;
        this.formatVersion = formatVersion;
        this.logLevel = logLevel;
        this.discardThreshold = discardThreshold;
    }

    public List<NetworkPacket> ValidatePackets(List<NetworkPacket> packets)
    {
        var validatedPackets = new List<NetworkPacket>();
        int errorCount = 0;

        foreach (var packet in packets)
        {
            if (!ValidatePacketHeader(packet))
            {
                LogError($"Invalid header: {packet}");
                errorCount++;
                continue;
            }

            if (!checksumAlgorithm.ValidateChecksum(packet.Payload))
            {
                LogError($"Checksum validation failed for packet.");
                errorCount++;
                continue;
            }

            validatedPackets.Add(packet);

            if (errorCount >= discardThreshold)
            {
                LogWarning("Discard threshold reached. Further packets may be discarded.");
                break; // Early exit to optimize for high-throughput
            }
        }

        return validatedPackets;
    }

    private bool ValidatePacketHeader(NetworkPacket packet)
    {
        return packet.SourceIP == expectedSourceIP &&
               packet.DestinationIP == expectedDestinationIP &&
               packet.ProtocolType == expectedProtocolType;
    }

    private void LogError(string message)
    {
        if (logLevel >= LogLevel.Error)
            Console.WriteLine($"ERROR: {message}");
    }

    private void LogWarning(string message)
    {
        if (logLevel >= LogLevel.Warning)
            Console.WriteLine($"WARNING: {message}");
    }
}

public abstract class ChecksumAlgorithm
{
    public abstract bool ValidateChecksum(byte[] data);
}
