using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

public interface IConfiguration
{
    string ConnectionString { get; set; }
    int MaxConnections { get; set; }
    bool UseEncryption { get; set; }
}

[Serializable]
public class Config : IConfiguration
{
    public string ConnectionString { get; set; } = "DefaultConnectionString";
    public int MaxConnections { get; set; } = 10;
    public bool UseEncryption { get; set; } = false;
}

public static class ConfigManager
{
    private static readonly object _lockObject = new object();
    private static IConfiguration _config;

    public static async Task<IConfiguration> LoadConfigAsync(string xmlFilePath, string[] commandLineArgs)
    {
        if (_config == null)
        {
            lock (_lockObject)
            {
                if (_config == null)
                {
                    var configXml = await File.ReadAllTextAsync(xmlFilePath);
                    _config = DeserializeConfig(configXml);

                    OverrideWithCommandLineArgs(commandLineArgs);
                    OverrideWithEnvironmentVariables();
                }
            }
        }

        return _config;
    }

    private static IConfiguration DeserializeConfig(string xml)
    {
        try
        {
            var settings = new XmlSerializer(typeof(Config));
            using (var reader = new StringReader(xml))
            {
                return (Config)settings.Deserialize(reader);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error deserializing config: {ex.Message}");
            return new Config();
        }
    }

    private static void OverrideWithCommandLineArgs(string[] args)
    {
        foreach (var arg in args)
        {
            var parts = arg.Split('=');
            if (parts.Length == 2 && Enum.IsDefined(typeof(ConfigElement), parts[0]))
            {
                switch ((ConfigElement)Enum.Parse(typeof(ConfigElement), parts[0], true))
                {
                    case ConfigElement.ConnectionString:
                        _config.ConnectionString = parts[1];
                        break;
                    case ConfigElement.MaxConnections:
                        if (int.TryParse(parts[1], out int maxConnections))
                        {
                            _config.MaxConnections = maxConnections;
                        }
                        break;
                    case ConfigElement.UseEncryption:
                        _config.UseEncryption = bool.Parse(parts[1]);
                        break;
                }
            }
        }
    }

    private static void OverrideWithEnvironmentVariables()
    {
        foreach (var field in typeof(Config).GetFields(BindingFlags.Instance | BindingFlags.Public))
        {
            var envVarName = $"CONFIG_{field.Name.ToUpper()}";
            if (Environment.GetEnvironmentVariable(envVarName) != null)
            {
                switch (field.FieldType)
                {
                    case Type t when t == typeof(string):
                        field.SetValue(_config, Environment.GetEnvironmentVariable(envVarName));
                        break;
                    case Type t when t == typeof(int):
                        if (int.TryParse(Environment.GetEnvironmentVariable(envVarName), out int intValue))
                        {
                            field.SetValue(_config, intValue);
                        }
                        break;
                    case Type t when t == typeof(bool):
                        field.SetValue(_config, bool.Parse(Environment.GetEnvironmentVariable(envVarName)));
                        break;
                }
            }
        }
    }
}

public enum ConfigElement
{
    ConnectionString,
    MaxConnections,
    UseEncryption
}
