const axios = require('axios');
const fs = require('fs');
const path = require('path');
const { createLogger, format, transports } = require('winston');

// Setup logger
const logger = createLogger({
  level: 'info',
  format: format.json(),
  transports: [
    new transports.File({ filename: 'upload.log' }),
    new transports.Console()
  ]
});

function uploadResource(url, options = {}) {
  const { chunkSize = 1024 * 1024, maxRetries = 3, timeout = 5000 } = options;
  const filePath = path.resolve(__dirname, 'path_to_your_file'); // Replace with actual file path
  let retryCount = 0;

  return new Promise(async (resolve, reject) => {
    try {
      const fileSize = fs.statSync(filePath).size;
      let startTimestamp;

      if (fileSize <= chunkSize) {
        await uploadFile(url, filePath, {}, timeout);
      } else {
        const totalChunks = Math.ceil(fileSize / chunkSize);
        for (let i = 0; i < totalChunks; i++) {
          const start = i * chunkSize;
          const end = Math.min(start + chunkSize - 1, fileSize - 1);
          const rangeHeader = `bytes=${start}-${end}`;

          startTimestamp = new Date().toISOString();
          logger.info(`Starting upload of chunk ${i + 1} of ${totalChunks}`);

          await uploadFile(url, filePath, { headers: { 'Range': rangeHeader } }, timeout);

          const endTimestamp = new Date().toISOString();
          logger.info(`Finished uploading chunk ${i + 1} of ${totalChunks}`, {
            startTimestamp,
            endTimestamp,
            status: 'Success'
          });
        }
      }

      resolve(url);
    } catch (error) {
      if (retryCount < maxRetries) {
        retryCount++;
        logger.warn(`Upload attempt failed, retrying (${retryCount}/${maxRetries})`, error);
        setTimeout(() => uploadResource(url, options).then(resolve).catch(reject), timeout);
      } else {
        const endTimestamp = new Date().toISOString();
        logger.error('Final upload attempt failed', {
          startTimestamp: 'N/A',
          endTimestamp,
          status: 'Failed',
          error
        });
        reject(error);
      }
    }
  });

  async function uploadFile(uploadUrl, filePath, headers = {}, timeout) {
    return new Promise((resolve, reject) => {
      const fileStream = fs.createReadStream(filePath, { start: headers['Range'] ? parseInt(headers['Range'].split('=')[1].split('-')[0]) : 0 });
      axios.post(uploadUrl, fileStream, {
        headers,
        maxContentLength: Infinity,
        timeout
      })
      .then(response => {
        logger.info('File uploaded successfully', response.data);
        resolve(response.data);
      })
      .catch(error => {
        if (error.response) {
          const errorData = error.response.data;
          logger.error('Upload failed with server response', { status: error.response.status, data: errorData });
          reject(new Error(`Upload failed with status ${error.response.status}`));
        } else if (error.request) {
          logger.error('No response from the server');
          reject(new Error('No response from the server'));
        } else {
          logger.error('Error setting up the request', error.message);
          reject(new Error('Error setting up the request'));
        }
      });
    });
  }
}
```

### Explanation:
1. **Logger Setup**: Uses Winston for logging to both a file and console.
2. **Function `uploadResource`**:
   - Handles both single and chunked uploads based on file size.
   - Supports retries with exponential backoff.
3. **Upload Functionality**:
   - Uses Axios for making HTTP requests.
   - Handles file streaming for large files.
   - Manages timeouts and logs detailed upload attempts.

This code provides a robust foundation for handling file uploads with retries, logging, and chunking. Adjust the `filePath` and other parameters as needed for your specific use case."]

