#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

int execute_shell_command(const char *command) {
    int pipefd[2];
    pid_t pid;
    char buffer[1024];

    if (pipe(pipefd) == -1) {
        perror("pipe");
        return 1;
    }

    pid = fork();
    if (pid == -1) {
        perror("fork");
        close(pipefd[0]);
        close(pipefd[1]);
        return 1;
    } else if (pid == 0) {
        // Child process
        dup2(pipefd[1], STDOUT_FILENO);
        close(pipefd[0]);
        close(pipefd[1]);

        execl("/bin/sh", "sh", "-c", command, NULL);
        perror("execl");
        exit(1);
    } else {
        // Parent process
        close(pipefd[1]);

        while (read(pipefd[0], buffer, sizeof(buffer) - 1) > 0) {
            buffer[sizeof(buffer) - 1] = '\0';
            printf("%s", buffer);
        }

        close(pipefd[0]);
        waitpid(pid, NULL, 0);
    }

    return 0;
}
