    HttpServer::new(move || {
        App::new()
            .app_data(routes.clone())
            .wrap(middleware::Logger::default()) // Middleware to log requests
            .service(
                web::scope("/api")
                    .configure(|config| {
                        config.route("/{id}", web::get().to(handle_request));
                    })
                    .route("/", web::get().to(handle_request)),
            )
    })
    .bind("0.0.0.0:8080")?
    .tcp_keepalive(Some(Duration::from_secs(30))) // Enable TCP keepalive
    .run()
    .await
}

