use std::collections::{HashMap, BinaryHeap};
use std::env;
use std::fs::{self, Permissions};
use std::io::{Error, ErrorKind};
use std::os::unix::fs::PermissionsExt;
use std::path::Path;

#[derive(Debug)]
struct DataPacket {
    packet_id: u32,
    timestamp: u64,
    payload_size: usize,
    priority_level: u8,
}

fn manage_packets(operation: &str, args: &[&str]) -> Result<(), Error> {
    match operation {
        "create_dir" => create_directory(args[0]),
        "set_env_var" => set_environment_variable(args[0], args[1]),
        "ensure_write_permissions" => ensure_write_permissions(args[0]),
        "add_packet" => add_packet(&mut packets, args),
        "remove_packet" => remove_packet(&mut packets, args[0].parse::<u32>()?),
        "get_packet_count" => get_packet_count(),
        "sort_packets_by_timestamp" => sort_packets_by_timestamp(),
        "sort_packets_by_priority" => sort_packets_by_priority(),
        "filter_packets_by_payload_size" => filter_packets_by_payload_size(args[0].parse::<usize>()?),
        _ => Err(Error::new(ErrorKind::InvalidInput, "Unsupported operation")),
    }
}

fn create_directory(name: &str) -> Result<(), Error> {
    if !Path::new(&name).exists() {
        fs::create_dir(name)?;
        println!("Directory created successfully.");
    } else {
        println!("Directory already exists.");
    }
    Ok(())
}

fn set_environment_variable(name: &str, value: &str) -> Result<(), Error> {
    env::set_var(name, value);
    println!("Environment variable set successfully.");
    Ok(())
}

fn ensure_write_permissions(path: &str) -> Result<(), Error> {
    let mut perms = fs::metadata(path)?.permissions();
    if !perms.is_writeable() {
        perms.set_mode(perms.mode() | 0o200); // Add write permission
        fs::set_permissions(path, perms)?;
        println!("Write permissions granted.");
    } else {
        println!("Write permissions already exist.");
    }
    Ok(())
}

fn add_packet(packets: &mut Vec<DataPacket>, args: &[&str]) -> Result<(), Error> {
    let packet_id = args[0].parse::<u32>()?;
    let timestamp = args[1].parse::<u64>()?;
    let payload_size = args[2].parse::<usize>()?;
    let priority_level = args[3].parse::<u8>()?;

    if packets.iter().any(|p| p.packet_id == packet_id) {
        return Err(Error::new(ErrorKind::AlreadyExists, "Packet ID already exists."));
    }

    if ![1, 2, 3].contains(&priority_level) {
        return Err(Error::new(ErrorKind::InvalidData, "Invalid priority level."));
    }

    packets.push(DataPacket {
        packet_id,
        timestamp,
        payload_size,
        priority_level,
    });
    println!("Packet added successfully.");
    Ok(())
}

fn remove_packet(packets: &mut Vec<DataPacket>, packet_id: u32) -> Result<(), Error> {
    if let Some(index) = packets.iter().position(|p| p.packet_id == packet_id) {
        packets.remove(index);
        println!("Packet removed successfully.");
    } else {
        return Err(Error::new(ErrorKind::NotFound, "Packet not found."));
    }
    Ok(())
}

fn get_packet_count() -> Result<(), Error> {
    let count = packets.len();
    println!("Total number of packets: {}", count);
    Ok(())
}

fn sort_packets_by_timestamp() -> Result<(), Error> {
    packets.sort_by_key(|p| p.timestamp);
    println!("Packets sorted by timestamp.");
    Ok(())
}

fn sort_packets_by_priority() -> Result<(), Error> {
    packets.sort_unstable_by_key(|p| -(p.priority_level as isize));
    println!("Packets sorted by priority in descending order.");
    Ok(())
}

fn filter_packets_by_payload_size(threshold: usize) -> Result<(), Error> {
    let filtered_packets: Vec<_> = packets.iter().filter(|p| p.payload_size > threshold).collect();
    for packet in filtered_packets {
        println!("{:?}", packet);
    }
    Ok(())
}

fn main() {
    // Example usage
    manage_packets("create_dir", &["/path/to/directory"]).unwrap();
    manage_packets("set_env_var", &["MY_VAR", "/path/to/directory"]).unwrap();
    manage_packets("ensure_write_permissions", &["/path/to/directory"]).unwrap();
    manage_packets("add_packet", &["1", "1633072800", "1024", "2"]).unwrap();
    manage_packets("get_packet_count", &[]).unwrap();
    manage_packets("sort_packets_by_timestamp", &[]).unwrap();
    manage_packets("sort_packets_by_priority", &[]).unwrap();
    manage_packets("filter_packets_by_payload_size", &["512"]).unwrap();
}
```']

