#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int packet_id;
    long timestamp;
    size_t payload_size;
} DataPacket;

typedef struct Node {
    DataPacket *data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t count;
    Node **id_map;
    size_t map_capacity;
} PacketManager;

PacketManager* create_packet_manager() {
    PacketManager *manager = (PacketManager*)malloc(sizeof(PacketManager));
    manager->head = NULL;
    manager->count = 0;
    manager->id_map = NULL;
    manager->map_capacity = 0;
    return manager;
}

void destroy_packet_manager(PacketManager *manager) {
    Node *current = manager->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    if (manager->id_map != NULL) {
        free(manager->id_map);
    }
    free(manager);
}

int add_packet(PacketManager *manager, DataPacket *packet) {
    // Check for duplicate ID
    if (manager->id_map[packet->packet_id] != NULL) {
        return -1; // Duplicate packet ID
    }

    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->data = packet;
    new_node->next = manager->head;
    manager->head = new_node;

    if (manager->count >= manager->map_capacity) {
        // Resize the map to double its size
        manager->map_capacity *= 2;
        manager->id_map = (Node**)realloc(manager->id_map, manager->map_capacity * sizeof(Node*));
        memset(&manager->id_map[manager->count], 0, (manager->map_capacity - manager->count) * sizeof(Node*));
    }
    manager->id_map[packet->packet_id] = new_node;
    manager->count++;
    return 0; // Success
}

int remove_packet(PacketManager *manager, int packet_id) {
    Node *current = manager->head;
    Node *prev = NULL;

    while (current != NULL) {
        if (current->data->packet_id == packet_id) {
            if (prev == NULL) {
                manager->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->data);
            free(current);

            // Update the map
            for (size_t i = 0; i < manager->map_capacity; i++) {
                if (manager->id_map[i] == current) {
                    manager->id_map[i] = NULL;
                    break;
                }
            }

            manager->count--;
            return 0; // Success
        }
        prev = current;
        current = current->next;
    }
    return -1; // Packet not found
}

size_t get_packet_count(PacketManager *manager) {
    return manager->count;
}

void sort_packets_by_timestamp(PacketManager *manager) {
    Node *current = manager->head;
    while (current != NULL) {
        Node *min_node = current;
        Node *inner_current = current->next;

        while (inner_current != NULL) {
            if (inner_current->data->timestamp < min_node->data->timestamp) {
                min_node = inner_current;
            }
            inner_current = inner_current->next;
        }

        // Swap the found minimum node with the first node
        DataPacket *temp_data = current->data;
        current->data = min_node->data;
        min_node->data = temp_data;

        current = current->next;
    }
}

void mark_packet_for_deletion(PacketManager *manager, int packet_id) {
    // Placeholder for marking logic
}

int is_packet_marked_for_deletion(PacketManager *manager, int packet_id) {
    // Placeholder for check logic
    return 0; // Not marked for deletion by default
}
