#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct DataPacket {
    int packet_id;
    long timestamp;
    int payload_size;
} DataPacket;

typedef struct PacketArray {
    DataPacket* packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PacketArray;

void init_packet_array(PacketArray* array, size_t initial_capacity) {
    array->packets = (DataPacket*)malloc(initial_capacity * sizeof(DataPacket));
    if (!array->packets) {
        fprintf(stderr, "Failed to allocate memory for packet array\n");
        exit(EXIT_FAILURE);
    }
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void free_packet_array(PacketArray* array) {
    pthread_mutex_lock(&array->lock);
    free(array->packets);
    array->packets = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

void add_packet(PacketArray* array, DataPacket packet) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity == 0 ? 1 : array->capacity * 2;
        DataPacket* new_packets = (DataPacket*)realloc(array->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) {
            fprintf(stderr, "Failed to allocate memory for packet expansion\n");
            pthread_mutex_unlock(&array->lock);
            return;
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
    array->packets[array->size++] = packet;
    pthread_mutex_unlock(&array->lock);
}

int remove_packet(PacketArray* array, int packet_id) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->packets[i].packet_id == packet_id) {
            memmove(&array->packets[i], &array->packets[i + 1], (array->size - i - 1) * sizeof(DataPacket));
            --array->size;
            pthread_mutex_unlock(&array->lock);
            return 0; // Packet removed successfully
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // Packet not found
}

size_t get_packet_count(PacketArray* array) {
    return array->size;
}

void sort_packets_by_timestamp(PacketArray* array) {
    pthread_mutex_lock(&array->lock);
    qsort(array->packets, array->size, sizeof(DataPacket), compare_packets);
    pthread_mutex_unlock(&array->lock);
}

int compare_packets(const void* a, const void* b) {
    return ((DataPacket*)a)->timestamp - ((DataPacket*)b)->timestamp;
}

void log_event(const char* event) {
    // Implement logging mechanism here
}
