#include <stdlib.h>
#include <string.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->packets = NULL;
    manager->count = 0;
    manager->capacity = 0;
}

void free_packet_manager(PacketManager *manager) {
    if (manager->packets != NULL) {
        free(manager->packets);
        manager->packets = NULL;
    }
    manager->count = 0;
    manager->capacity = 0;
}

int add_packet(PacketManager *manager, const DataPacket *packet) {
    // Resize the array if necessary
    if (manager->count >= manager->capacity) {
        size_t new_capacity = (manager->capacity == 0) ? 1 : manager->capacity * 2;
        DataPacket *new_packets = realloc(manager->packets, new_capacity * sizeof(DataPacket));
        if (new_packets == NULL) return -1; // Memory allocation failed
        manager->packets = new_packets;
        manager->capacity = new_capacity;
    }

    // Find the correct position to insert the packet based on timestamp
    size_t i;
    for (i = 0; i < manager->count; ++i) {
        if (manager->packets[i].timestamp > packet->timestamp) break;
    }
    memmove(&manager->packets[i + 1], &manager->packets[i], (manager->count - i) * sizeof(DataPacket));
    memcpy(&manager->packets[i], packet, sizeof(DataPacket));
    ++manager->count;

    return 0; // Success
}

int remove_packet(PacketManager *manager, int packet_id) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i].packet_id == packet_id) {
            memmove(&manager->packets[i], &manager->packets[i + 1], (manager->count - i - 1) * sizeof(DataPacket));
            --manager->count;
            return 0; // Success
        }
    }
    return -1; // Packet not found
}

size_t get_packet_count(const PacketManager *manager) {
    return manager->count;
}
