#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <chrono>

class Transaction {
public:
    int transaction_id;
    std::string account_number;
    double transaction_amount;
    std::time_t transaction_date;

    Transaction(int id, const std::string& acc_num, double amount, std::time_t date)
        : transaction_id(id), account_number(acc_num), transaction_amount(amount), transaction_date(date) {}
};

class TransactionManager {
private:
    std::unordered_map<int, Transaction> transactions;
    std::mutex mutex;

public:
    void addTransaction(const Transaction& new_transaction) {
        std::lock_guard<std::mutex> lock(mutex);
        if (transactions.find(new_transaction.transaction_id) != transactions.end()) {
            throw std::runtime_error("Duplicate transaction ID");
        }
        transactions[new_transaction.transaction_id] = new_transaction;
    }

    bool removeTransaction(int id) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = transactions.find(id);
        if (it != transactions.end()) {
            transactions.erase(it);
            return true;
        }
        return false;
    }

    size_t getNumberOfTransactions() const {
        std::lock_guard<std::mutex> lock(mutex);
        return transactions.size();
    }

    std::vector<Transaction> filterTransactions(double min_amount, double max_amount) const {
        std::vector<Transaction> filtered_transactions;
        for (const auto& pair : transactions) {
            if (pair.second.transaction_amount >= min_amount && pair.second.transaction_amount <= max_amount) {
                filtered_transactions.push_back(pair.second);
            }
        }
        return filtered_transactions;
    }

    double aggregateTransactionsByAccount(const std::string& account_number) const {
        double total = 0.0;
        for (const auto& pair : transactions) {
            if (pair.second.account_number == account_number) {
                total += pair.second.transaction_amount;
            }
        }
        return total;
    }

    void simulateLargeDataSetOperation() {
        std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate a delay
    }
};

int main() {
    TransactionManager manager;
    manager.addTransaction(Transaction(1, "A123", 100.50, time(nullptr)));
    manager.addTransaction(Transaction(2, "B456", 200.75, time(nullptr)));

    try {
        manager.addTransaction(Transaction(1, "A123", 150.00, time(nullptr))); // Should throw an exception
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    manager.removeTransaction(1);
    std::cout << "Number of transactions after removal: " << manager.getNumberOfTransactions() << std::endl;

    auto filtered = manager.filterTransactions(100.0, 250.0);
    for (const auto& t : filtered) {
        std::cout << "Transaction ID: " << t.transaction_id << ", Amount: " << t.transaction_amount << std::endl;
    }

    double aggregate = manager.aggregateTransactionsByAccount("B456");
    std::cout << "Total for account B456: " << aggregate << std::endl;

    manager.simulateLargeDataSetOperation();

    return 0;
}
