#include <time.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *manager, size_t initial_capacity) {
    manager->packets = malloc(initial_capacity * sizeof(DataPacket));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_packet_manager(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->packets);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

void add_packet(PacketManager *manager, DataPacket packet) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        manager->packets = realloc(manager->packets, 2 * manager->capacity * sizeof(DataPacket));
        manager->capacity *= 2;
    }
    manager->packets[manager->count++] = packet;
    pthread_mutex_unlock(&manager->lock);
}

void remove_packet_by_id(PacketManager *manager, int packet_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i].packet_id == packet_id) {
            memmove(&manager->packets[i], &manager->packets[i + 1], (manager->count - i - 1) * sizeof(DataPacket));
            --manager->count;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

size_t get_packet_count(const PacketManager *manager) {
    return manager->count;
}

void sort_packets_by_timestamp(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    qsort(manager->packets, manager->count, sizeof(DataPacket), 
          [](const void *a, const void *b) { 
              return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp; 
          });
    pthread_mutex_unlock(&manager->lock);
}

