#define MAX_PRIORITY_LEVELS 10

typedef struct {
    int transaction_id;
    time_t timestamp;
    double weight;
    int priority;
} Transaction;

typedef struct {
    Transaction transactions[1000];
    int head, tail, count;
    int total_processed_last_5s;
} TransactionQueue;

void init_queue(TransactionQueue *queue) {
    queue->head = queue->tail = queue->count = 0;
    queue->total_processed_last_5s = 0;
}

int enqueue(TransactionQueue *queue, Transaction transaction) {
    if (queue->count >= 1000) return -1; // Queue overflow
    queue->transactions[queue->tail] = transaction;
    queue->tail = (queue->tail + 1) % 1000;
    queue->count++;
    return 0;
}

Transaction dequeue(TransactionQueue *queue) {
    if (queue->count == 0) Transaction empty = {0, time(NULL), 0.0, 0};
    return queue->transactions[queue->head++];
    queue->count--;
}

int main() {
    srand(time(NULL));
    TransactionQueue transaction_queue;
    init_queue(&transaction_queue);

    // Simulate transaction processing
    for (int i = 0; i < 1500; i++) {
        time_t now = time(NULL);
        Transaction transaction = {i, now - rand() % 6, 1.0 + rand() % 100 / 100.0, rand() % MAX_PRIORITY_LEVELS};
        enqueue(&transaction_queue, transaction);

        if (queue->count > 100) {
            dequeue(&transaction_queue);
        }
    }

    // Calculate metrics
    for (int i = queue->head; i != queue->tail; i = (i + 1) % 1000) {
        if (difftime(now, transaction_queue.transactions[i].timestamp) < 5) {
            transaction_queue.total_processed_last_5s++;
        }
    }

    // Find transaction with highest weighted sum
    int max_weighted_id = -1;
    double max_weight_sum = 0.0;
    for (int i = queue->head; i != queue->tail; i = (i + 1) % 1000) {
        if (transaction_queue.transactions[i].weight > max_weight_sum) {
            max_weighted_id = transaction_queue.transactions[i].transaction_id;
            max_weight_sum = transaction_queue.transactions[i].weight;
        }
    }

    printf("Transaction ID with highest weighted sum: %d\n", max_weighted_id);
    printf("Total transactions processed in last 5 seconds: %d\n", transaction_queue.total_processed_last_5s);

    return 0;
}
