    public void start() throws Exception {
        int delay = (int) (Math.random() * 9 + 1); // Random delay between 1 to 10 seconds
        scheduler.scheduleAtFixedRate(this::runService, delay, delay, TimeUnit.SECONDS);
    }

    private void runService() {
        HttpGet request = new HttpGet("http://monitoring-service/status");
        try (CloseableHttpResponse response = httpClient.execute(request)) {
            // Report service status to monitoring system
        } catch (Exception e) {
            // Handle exceptions and ensure graceful recovery
        }
    }

    public void stop() throws Exception {
        scheduler.shutdown();
        httpClient.close();
    }
}

// Example usage
public class Main {
    public static void main(String[] args) throws Exception {
        ServiceManager manager = new ServiceManager();
        manager.start();
    }
}
