    for (int i = 0; i < n; ++i) {
        array[i].rx_ue_info.RX_UE_INFORMATION_TAG = i;
        array[i].rx_ue_info.RNTI = rand() % 65535; // Generate a random RNTI
        array[i].crc_ind_rel8.CRCFLAG = (rand() % 2) == 0 ? true : false; // Randomly set CRCFLAG
    }

    return array;
}

void free_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T* array, int n) {
