    private static NFAPI_CRC_INDICATION_PDU_T createNFAPICRCIndicationPDU() {
        NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
        pdu.RX_UE_INFORMATION_TAG = generateRXUEInformationTag();
        pdu.RNTI = (short) Math.random(); // Simplified for example
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = (byte) (Math.random() > 0.5 ? 1 : 0);
        return pdu;
    }

    private static RX_UE_INFORMATION_TAG generateRXUEInformationTag() {
        RX_UE_INFORMATION_TAG tag = new RX_UE_INFORMATION_TAG();
        // Populate the tag with valid values
        return tag;
    }

    public static void deleteFile(String filePath) {
        File file = new File(filePath);
        int attempts = 0;
        while (attempts < RETRY_COUNT && !file.delete()) {
            attempts++;
            try {
                Thread.sleep(100); // Wait before retrying
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public static String executeCommand(String command) throws IOException, InterruptedException {
        Process process = Runtime.getRuntime().exec(command);
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new IOException("Command execution failed with exit code: " + exitCode);
        }
        return process.getInputStream().toString();
    }

    public static String calculateMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

    public static void logExecution(String command, String result, boolean success) {
        try (FileWriter writer = new FileWriter(LOG_FILE_PATH, true)) {
            writer.write(new java.util.Date().toString() + " - Command: " + command + "\n");
            writer.write("Result: " + result + "\n");
            writer.write("Success: " + success + "\n\n");
        } catch (IOException e) {
            System.err.println("Failed to log execution: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // Example usage
        try {
            NFAPI_CRC_INDICATION_PDU_T[] pdus = createNFAPICRCIndicationPDUs(100);
            deleteFile("path/to/file.txt");
            String result = executeCommand("ls -l");
            logExecution("ls -l", result, true);
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }
    }
}

