#include <iostream>
#include <vector>
#include <unordered_map>
#include <algorithm>
#include <ctime>

class Transaction {
public:
    int transaction_id;
    std::string account_number;
    double transaction_amount;
    std::time_t transaction_date;

    Transaction(int id, const std::string& acc_num, double amount, std::time_t date)
        : transaction_id(id), account_number(acc_num), transaction_amount(amount), transaction_date(date) {}
};

class TransactionManager {
private:
    std::unordered_map<int, Transaction> transactions;
    std::vector<Transaction*> all_transactions;

public:
    void addTransaction(const Transaction& tx) {
        auto it = transactions.find(tx.transaction_id);
        if (it != transactions.end()) {
            throw std::runtime_error("Duplicate transaction ID");
        }
        transactions[tx.transaction_id] = tx;
        all_transactions.push_back(&transactions[tx.transaction_id]);
    }

    void removeTransaction(int id) {
        auto it = transactions.find(id);
        if (it == transactions.end()) {
            throw std::runtime_error("Transaction not found");
        }
        all_transactions.erase(std::remove(all_transactions.begin(), all_transactions.end(), &it->second), all_transactions.end());
        transactions.erase(it);
    }

    int getNumberOfTransactions() const {
        return transactions.size();
    }

    std::vector<Transaction*> filterByAmount(double min_amount, double max_amount) const {
        std::vector<Transaction*> filtered;
        for (auto& tx : all_transactions) {
            if (tx->transaction_amount >= min_amount && tx->transaction_amount <= max_amount) {
                filtered.push_back(tx);
            }
        }
        return filtered;
    }

    std::unordered_map<std::string, double> aggregateByAccount() const {
        std::unordered_map<std::string, double> aggregates;
        for (auto& tx : all_transactions) {
            aggregates[tx->account_number] += tx->transaction_amount;
        }
        return aggregates;
    }
};

int main() {
    TransactionManager manager;
    try {
        manager.addTransaction(Transaction(1, "12345", 100.0, std::time(nullptr)));
        manager.addTransaction(Transaction(2, "67890", 200.0, std::time(nullptr)));
        manager.removeTransaction(1);
        std::cout << "Number of transactions: " << manager.getNumberOfTransactions() << std::endl;
        auto filtered = manager.filterByAmount(50.0, 300.0);
        for (auto& tx : filtered) {
            std::cout << "Filtered transaction ID: " << tx->transaction_id << ", Amount: " << tx->transaction_amount << std::endl;
        }
        auto aggregates = manager.aggregateByAccount();
        for (const auto& pair : aggregates) {
            std::cout << "Account: " << pair.first << ", Total Amount: " << pair.second << std::endl;
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
