<?php
function authenticateUser($client_id, $client_secret, $code) {
    $url = 'https://example.com/oauth/token';
    $data = [
        'grant_type' => 'authorization_code',
        'code' => $code,
        'redirect_uri' => 'http://example.com/callback',
        'client_id' => $client_id,
        'client_secret' => $client_secret
    ];

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_POST, 1);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($data));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    $response = curl_exec($ch);

    if ($response === false) {
        echo 'cURL Error: ' . curl_error($ch);
        return;
    }

    $result = json_decode($response, true);
    if (isset($result['access_token'])) {
        $_SESSION['access_token'] = $result['access_token'];
        // Retrieve user information using the access token
        $user_info_url = 'https://example.com/api/user';
        curl_setopt($ch, CURLOPT_URL, $user_info_url);
        curl_setopt($ch, CURLOPT_HTTPHEADER, [
            'Authorization: Bearer ' . $_SESSION['access_token']
        ]);
        $user_info_response = curl_exec($ch);
        if ($user_info_response === false) {
            echo 'cURL Error: ' . curl_error($ch);
            return;
        }
        $user_info = json_decode($user_info_response, true);
        // Process user information as needed
    } else {
        echo 'Authentication failed: ' . (isset($result['error_description']) ? $result['error_description'] : 'Unknown error');
    }

    curl_close($ch);
}
