#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    uint16_t bits_per_sample;
    uint16_t samples_per_pixel;
} tiff_info;

tiff_info parse_tiff(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open TIFF file");
        exit(EXIT_FAILURE);
    }

    tiff_info info;
    uint32_t offset_to_ifd = 0;
    fread(&offset_to_ifd, sizeof(uint32_t), 1, file);

    fseek(file, offset_to_ifd + 4 * 2, SEEK_SET); // Skip tags for software and image description
    fread(&info.bits_per_sample, sizeof(uint16_t), 1, file);
    fread(&info.samples_per_pixel, sizeof(uint16_t), 1, file);

    fclose(file);

    return info;
}

int main() {
    tiff_info info = parse_tiff("example.tiff");
    printf("Bits per sample: %hu\n", info.bits_per_sample);
    printf("Samples per pixel: %hu\n", info.samples_per_pixel);
    return 0;
}
