#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 256

typedef struct {
    char date[MAX_LINE_LENGTH];
    float amount;
    char type[MAX_LINE_LENGTH];
} Transaction;

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <csv_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    char line[MAX_LINE_LENGTH];
    Transaction *transactions = NULL;
    size_t transaction_count = 0;

    while (fgets(line, sizeof(line), file)) {
        transactions = realloc(transactions, (transaction_count + 1) * sizeof(Transaction));
        if (!transactions) {
            perror("Failed to allocate memory");
            fclose(file);
            return EXIT_FAILURE;
        }

        Transaction *new_transaction = &transactions[transaction_count++];
        char *token = strtok(line, ",");
        if (token == NULL || strlen(token) >= MAX_LINE_LENGTH - 1) {
            fprintf(stderr, "Malformed CSV entry\n");
            free(transactions);
            fclose(file);
            return EXIT_FAILURE;
        }
        strncpy(new_transaction->date, token, MAX_LINE_LENGTH - 1);

        token = strtok(NULL, ",");
        if (token == NULL || sscanf(token, "%f", &new_transaction->amount) != 1) {
            fprintf(stderr, "Malformed CSV entry\n");
            free(transactions);
            fclose(file);
            return EXIT_FAILURE;
        }

        token = strtok(NULL, ",");
        if (token == NULL || strlen(token) >= MAX_LINE_LENGTH - 1) {
            fprintf(stderr, "Malformed CSV entry\n");
            free(transactions);
            fclose(file);
            return EXIT_FAILURE;
        }
        strncpy(new_transaction->type, token, MAX_LINE_LENGTH - 1);
    }

    fclose(file);

    float total_amounts[10] = {0};
    for (size_t i = 0; i < transaction_count; ++i) {
        int type_index = 0;
        while (strcmp(transactions[i].type, "Type%d") != 0 && type_index < 10) {
            ++type_index;
        }
        if (type_index == 10) {
            fprintf(stderr, "Unknown transaction type\n");
            free(transactions);
            return EXIT_FAILURE;
        }
        total_amounts[type_index] += transactions[i].amount;
    }

    for (int i = 0; i < 10; ++i) {
        printf("Total amount for Type%d: %.2f\n", i, total_amounts[i]);
    }

    free(transactions);
    return EXIT_SUCCESS;
}
