    EVP_CIPHER *cipher;
    if (strcmp(cipher_name, "aes_128_ecb") == 0) {
        cipher = EVP_aes_128_ecb();
    } else if (strcmp(cipher_name, "camellia_192_ofb") == 0) {
        cipher = EVP_camellia_192_ofb();
    } else {
        fprintf(stderr, "Unknown cipher: %s\n", cipher_name);
        exit(EXIT_FAILURE);
    }
    return cipher;
}

EVP_MD *get_digest_from_env() {
    const char *digest_name = getenv("DIGEST");
    if (digest_name == NULL) {
        return EVP_sha256();
    }
    EVP_MD *digest;
    if (strcmp(digest_name, "md5") == 0) {
        digest = EVP_md5();
    } else if (strcmp(digest_name, "sha1") == 0) {
        digest = EVP_sha1();
    } else {
        fprintf(stderr, "Unknown digest: %s\n", digest_name);
        exit(EXIT_FAILURE);
