#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <limits.h>

#define MAX_ARGS 64
#define MAX_ENV_SIZE 1024

typedef struct {
    char *command[MAX_ARGS];
    char **env;
    int timeout;
} CommandTask;

void handle_sigchld(int sig) {
    while (waitpid(-1, NULL, WNOHANG) > 0);
}

int execute_command(CommandTask *task) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("Fork failed");
        return 0;
    } else if (pid == 0) {
        struct timespec start_time, end_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        if (task->env != NULL) {
            execve(task->command[0], task->command, task->env);
        } else {
            execvp(task->command[0], task->command);
        }

        perror("Exec failed");
        exit(EXIT_FAILURE);
    } else {
        int status;
        struct timespec end_time;
        clock_gettime(CLOCK_MONOTONIC, &end_time);

        if (waitpid(pid, &status, 0) == -1) {
            perror("Wait failed");
            return 0;
        }

        if (WIFEXITED(status)) {
            printf("Command exited with status %d\n", WEXITSTATUS(status));
        } else if (WIFSIGNALED(status)) {
            printf("Command terminated by signal %d\n", WTERMSIG(status));
        }

        double elapsed_time = end_time.tv_sec - start_time.tv_sec + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;
        printf("Elapsed time: %.3f seconds\n", elapsed_time);

        return 1;
    }
}

int main() {
    CommandTask task = {
        .command = {"ls", "-l", NULL},
        .env = {NULL},
        .timeout = 5
    };

    if (!execute_command(&task)) {
        printf("Command execution failed\n");
    }

    return 0;
}
