        File file = new File(filePath);
        if (file.exists()) {
            for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
                try {
                    Process process = Runtime.getRuntime().exec("cmd /c del " + filePath, null, file.getParentFile());
                    int exitCode = process.waitFor();
                    if (exitCode == 0) {
                        log(String.format("File deleted successfully: %s", filePath));
                        return;
                    } else {
                        log(String.format("Failed to delete file: %s. Attempt %d failed with exit code %d", filePath, attempt, exitCode));
                    }
                } catch (IOException | InterruptedException e) {
                    log(String.format("Exception occurred while deleting file: %s. Attempt %d", filePath, attempt), e);
                }
            }
        } else {
            log(String.format("File does not exist: %s", filePath));
        }
    }

    public void executeCommand(String command, String[] envp, File dir) {
        for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
            try {
                Process process = Runtime.getRuntime().exec(command, envp, dir);
                readOutput(process.getInputStream(), "stdout");
                readOutput(process.getErrorStream(), "stderr");
                int exitCode = process.waitFor();
                if (exitCode == 0) {
                    log(String.format("Command executed successfully: %s", command));
                } else {
                    log(String.format("Failed to execute command: %s. Attempt %d failed with exit code %d", command, attempt, exitCode));
                }
            } catch (IOException | InterruptedException e) {
                log(String.format("Exception occurred while executing command: %s. Attempt %d", command, attempt), e);
            }
        }
    }

    private void readOutput(InputStream inputStream, String streamType) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                log(String.format("%s: %s", streamType, line));
            }
        } catch (IOException e) {
            log(String.format("Error reading %s", streamType), e);
        }
    }

    public String getMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            log("Error calculating MD5 hash", e);
            return null;
        }
    }

    private void log(String message, Exception e) {
        // Log the message with timestamp and exception details
        System.out.println(message + " - " + new java.util.Date() + " - " + e.getMessage());
    }

    private void log(String message) {
        log(message, null);
    }
}
