import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;
import java.io.*;
import java.security.*;
import java.security.spec.InvalidKeySpecException;

public class CryptoUtil {

    public static MoSTState deserializeAndDecryptMoSTState(byte[] encryptedPayload, String password) {
        try {
            // Initialize the cipher
            SecretKey secretKey = generateSecretKey(password);
            IvParameterSpec ivParameterSpec = generateIV();
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            cipher.init(Cipher.DECRYPT_MODE, secretKey, ivParameterSpec);

            // Decrypt the payload
            byte[] decryptedPayload = cipher.doFinal(encryptedPayload);

            // Deserialize the object
            ByteArrayInputStream bis = new ByteArrayInputStream(decryptedPayload);
            ObjectInputStream ois = new ObjectInputStream(bis);
            MoSTState stateObject = (MoSTState) ois.readObject();
            ois.close();

            return stateObject;
        } catch (Exception e) {
            throw new RuntimeException("Failed to deserialize and decrypt payload", e);
        }
    }

    private static SecretKey generateSecretKey(String password) throws NoSuchAlgorithmException, InvalidKeySpecException {
        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(256);
        SecretKey secretKey = keyGen.generateKey();
        PBEKeySpec spec = new PBEKeySpec(password.toCharArray(), getSalt(), 10000, 256);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        return new SecretKeySpec(factory.generateSecret(spec).getEncoded(), "AES");
    }

    private static IvParameterSpec generateIV() throws NoSuchAlgorithmException {
        SecureRandom secureRandom = SecureRandom.getInstanceStrong();
        byte[] ivBytes = new byte[16];
        secureRandom.nextBytes(ivBytes);
        return new IvParameterSpec(ivBytes);
    }

    private static byte[] getSalt() throws IOException {
        try (FileInputStream fis = new FileInputStream("/dev/urandom");
             ByteArrayOutputStream bos = new ByteArrayOutputStream()) {
            byte[] buffer = new byte[32];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                bos.write(buffer, 0, bytesRead);
                if (bos.size() >= 32) break;
            }
            return bos.toByteArray();
        }
    }
}
