// Define the OctreeNode structure
struct OctreeNode {
    int prefix;
    std::vector<int> data;
    OctreeNode* children[8];
};

// Initialize an octree with a given feature size and number of leaf nodes
OctreeNode* initializeOctree(int featureSize, int numLeafNodes) {
    // Allocate memory for the root node
    OctreeNode* root = new OctreeNode();
    memset(root, 0, sizeof(OctreeNode));

    // Calculate the number of levels in the octree
    int levels = static_cast<int>(std::log2(featureSize)) + 1;

    // Initialize the prefix leafs and data arrays
    for (int i = 0; i < numLeafNodes; ++i) {
        int prefix = i << (featureSize - levels);
        OctreeNode* node = root;
        for (int j = 0; j < levels; ++j) {
            int index = (prefix >> (featureSize - levels + j)) & 1;
            if (node->children[index] == nullptr) {
                node->children[index] = new OctreeNode();
                memset(node->children[index], 0, sizeof(OctreeNode));
            }
            node = node->children[index];
        }
        node->prefix = prefix;
        // Allocate memory for the data array
        node->data.resize(featureSize);
    }

    return root;
}

// Clean up the octree and release allocated resources
void cleanupOctree(OctreeNode* root) {
    if (root != nullptr) {
        for (int i = 0; i < 8; ++i) {
            cleanupOctree(root->children[i]);
        }
        delete root;
    }
}

// Example usage of the initializeOctree function
int main() {
    int featureSize = 16;
    int numLeafNodes = 32;

    OctreeNode* octree = initializeOctree(featureSize, numLeafNodes);

    // Perform operations on the octree...

    cleanupOctree(octree);

    return 0;
}
