    public DistributedCacheManager(DistributedCacheService cacheService, TaskQueue taskQueue, LoadBalancer loadBalancer, MetricsTracker metricsTracker) {
        this.cacheService = cacheService;
        this.taskQueue = taskQueue;
        this.loadBalancer = loadBalancer;
        this.metricsTracker = metricsTracker;
