    public CacheUpdateResponse updateCacheAndProcessTask(String key, String value, int expirationTime, Task task) {
        // Update cache entry
        cacheService.updateEntry(key, value, expirationTime);

        // Process task submission
        if (isTaskSubmissionAllowed(task)) {
            taskQueue.enqueueTask(task);
            metricsTracker.updateMetrics(task);
        } else {
            loadBalancer.handleBackpressure();
        }

        // Return response
        return new CacheUpdateResponse(taskQueue.getHighestPriorityTaskId(), metricsTracker.getTotalTasksInLast5Minutes());
    }

    private boolean isTaskSubmissionAllowed(Task task) {
        if (!isWithin10MinutesOfNow(task.getSubmissionTime())) {
            return false;
        }

        int tasksInLastMinute = metricsTracker.getTasksInLastMinute();
        if (tasksInLastMinute >= 1000 && !loadBalancer.isSystemUnderHeavyLoad()) {
            return false;
        }

        double averagePriority = metricsTracker.getAveragePriorityOfLast5Minutes();
        if (averagePriority < 75) {
            adjustPriorityThresholds(metricsTracker);
        }

        return true;
    }

