int encrypt(const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext, CryptoContext *ctx) {
    int len = 0;
    if (EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len) != 1) return -1;
    int ciphertext_len = len;
    if (EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len) != 1) return -1;
    ciphertext_len += len;
    return ciphertext_len;
