    if (EVP_DecryptUpdate(ctx->ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) return -1;
    int plaintext_len = len;
    if (EVP_DecryptFinal_ex(ctx->ctx, plaintext + len, &len) != 1) return -1;
