use std::collections::{HashMap, HashSet};
use tokio::sync::{mpsc, RwLock};
use chrono::NaiveDateTime;

#[derive(Debug)]
struct Transaction {
    transaction_id: u64,
    account_number: String,
    transaction_amount: f32,
    transaction_date: NaiveDateTime,
}

struct TransactionManager {
    transactions: RwLock<HashMap<u64, Transaction>>,
    next_transaction_id: u64,
}

impl TransactionManager {
    fn new() -> Self {
        Self {
            transactions: RwLock::new(HashMap::new()),
            next_transaction_id: 1,
        }
    }

    async fn add_transaction(&self, transaction: Transaction) -> Result<(), String> {
        let mut tx = self.transactions.write().await;
        if tx.contains_key(&transaction.transaction_id) {
            return Err("Transaction ID already exists".to_string());
        }
        tx.insert(transaction.transaction_id, transaction);
        Ok(())
    }

    async fn remove_transaction(&self, transaction_id: u64) -> Result<(), String> {
        let mut tx = self.transactions.write().await;
        if !tx.contains_key(&transaction_id) {
            return Err("Transaction ID not found".to_string());
        }
        tx.remove(&transaction_id);
        Ok(())
    }

    async fn get_transaction_count(&self) -> usize {
        self.transactions.read().await.len()
    }

    async fn filter_transactions(
        &self,
        min_amount: Option<f32>,
        max_amount: Option<f32>,
    ) -> Vec<Transaction> {
        let tx = self.transactions.read().await;
        tx.values()
            .filter(|t| match (min_amount, max_amount) {
                (Some(min), Some(max)) => t.transaction_amount >= min && t.transaction_amount <= max,
                (Some(min), None) => t.transaction_amount >= min,
                (None, Some(max)) => t.transaction_amount <= max,
                (None, None) => true,
            })
            .cloned()
            .collect()
    }

    async fn aggregate_transactions_by_account(&self) -> HashMap<String, f32> {
        let tx = self.transactions.read().await;
        let mut result = HashMap::new();
        for transaction in tx.values() {
            *result.entry(transaction.account_number.clone()).or_insert(0.0) += transaction.transaction_amount;
        }
        result
    }

    async fn process_transactions(&self, transactions: Vec<Transaction>) -> Result<(), String> {
        for transaction in transactions {
            self.add_transaction(transaction).await?;
        }
        Ok(())
    }
}

#[tokio::main]
async fn main() {
    let manager = TransactionManager::new();
    // Example usage
    let new_transactions = vec![
        Transaction {
            transaction_id: 1,
            account_number: "A123".to_string(),
            transaction_amount: 100.0,
            transaction_date: NaiveDateTime::now(),
        },
        Transaction {
            transaction_id: 2,
            account_number: "B456".to_string(),
            transaction_amount: 200.0,
            transaction_date: NaiveDateTime::now(),
        },
    ];
    manager.process_transactions(new_transactions).await.unwrap();
    println!("Transaction count: {}", manager.get_transaction_count().await);
}
