typedef struct {
    NR_UES_INFO_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynamicList;

void dynamic_list_init(DynamicList *list, size_t initial_capacity) {
    list->data = (NR_UES_INFO_T *)malloc(initial_capacity * sizeof(NR_UES_INFO_T));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void dynamic_list_destroy(DynamicList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
}

int dynamic_list_add(DynamicList *list, NR_UES_INFO_T user_info) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        list->data = realloc(list->data, list->capacity * 2 * sizeof(NR_UES_INFO_T));
        list->capacity *= 2;
    }
    list->data[list->count++] = user_info;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void dynamic_list_remove(DynamicList *list, int UE_ID) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].UE_ID == UE_ID) {
            for (size_t j = i; j < list->count - 1; ++j) {
                list->data[j] = list->data[j + 1];
            }
            --list->count;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

NR_UES_INFO_T *dynamic_list_get(DynamicList *list, int UE_ID) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].UE_ID == UE_ID) {
            NR_UES_INFO_T *user_info = (NR_UES_INFO_T *)malloc(sizeof(NR_UES_INFO_T));
            *user_info = list->data[i];
            pthread_mutex_unlock(&list->mutex);
            return user_info;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

