import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class ServiceManager {
    private static final int MIN_DELAY = 1000; // 1 second
    private static final int MAX_DELAY = 10000; // 10 seconds
    private boolean running = false;
    private thread_safe_queue queue;

    public void startService() {
        if (!running) {
            running = true;
            Thread serviceThread = new Thread(() -> {
                try {
                    while (running) {
                        int delay = MIN_DELAY + (int)(Math.random() * (MAX_DELAY - MIN_DELAY));
                        Thread.sleep(delay);
                        int item = queue.dequeue();
                        sendServiceStatus(item);
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
            serviceThread.start();
        }
    }

    public void stopService() {
        running = false;
    }

    private void sendServiceStatus(int status) {
        try {
            URL url = new URL("http://monitoring.system/status");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("POST");
            conn.setDoOutput(true);
            String input = "status=" + status;
            conn.getOutputStream().write(input.getBytes());
            int responseCode = conn.getResponseCode();
            System.out.println("Response Code: " + responseCode);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public String md5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hash = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hash) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public void setQueue(thread_safe_queue queue) {
        this.queue = queue;
    }
}
