    std::string message;

    LogEntry(int id, const std::string& level, const std::string& msg)
        : entry_id(id), timestamp(std::chrono::system_clock::now()), log_level(level), message(msg) {}
};

class LogManager {
private:
    static const size_t MAX_SIZE = 512 * 1024 * 1024; // 512 MB
    std::unordered_map<int, LogEntry> entries;
    std::mutex mutex;

public:
    void addLogEntry(const LogEntry& entry) {
        std::lock_guard<std::mutex> lock(mutex);
        if (entries.size() >= MAX_SIZE / sizeof(LogEntry)) {
            // Handle memory limit exceeded
        }
        entries[entry.entry_id] = entry;
    }

    bool removeLogEntry(int id) {
        std::lock_guard<std::mutex> lock(mutex);
        return entries.erase(id) > 0;
    }

    size_t getEntryCount() const {
        std::lock_guard<std::mutex> lock(mutex);
        return entries.size();
    }

    void filterLogsByLevel(const std::string& level, std::vector<LogEntry>& filteredEntries) const {
        std::lock_guard<std::mutex> lock(mutex);
        for (const auto& entry : entries) {
            if (entry.second.log_level == level) {
                filteredEntries.push_back(entry.second);
            }
        }
    }

