#define MAX_PATH_LENGTH 4096

char* expand_and_validate_path(const char *path, int max_length, char *buffer, int buffer_size) {
    // Validate input parameters
    if (path == NULL || max_length <= 0) {
        return NULL;
    }

    // Check for absolute path and valid directory separators
    if (!path[0] == '/' && !path[1] == ':') {
        return NULL;
    }

    // Calculate the length of the expanded path
    size_t len = strlen(path);
    bool needs_slash = (len > 0 && path[len - 1] != '/');
    size_t total_len = len + (needs_slash ? 1 : 0);

    // Check if buffer is provided and sufficient
    char *expanded_path;
    if (buffer != NULL && buffer_size >= total_len) {
        expanded_path = buffer;
    } else {
        expanded_path = malloc(total_len);
        if (expanded_path == NULL) {
            return NULL; // Memory allocation failed
        }
    }

    // Copy the path and append a slash if needed
    strcpy(expanded_path, path);
    if (needs_slash) {
        strcat(expanded_path, "/");
    }

    // Check for too long file paths
    if (strlen(expanded_path) > max_length) {
        free(expanded_path); // Free allocated buffer
        return NULL;
    }

    // Handle Unicode characters robustly
    wchar_t *wpath = malloc((len + 1) * sizeof(wchar_t));
    if (wpath == NULL) {
        free(expanded_path);
        return NULL; // Memory allocation failed
    }
    mbstowcs(wpath, path, len + 1);

    // Check for invalid Unicode sequences
    for (size_t i = 0; wpath[i] != L'\0'; ++i) {
        if ((wpath[i] & 0xFFFE) == 0xFFFE || (wpath[i] & 0xFFFE) == 0xFFFD) {
            free(expanded_path);
            free(wpath);
            return NULL;
        }
    }

    // Free the temporary wide character string
    free(wpath);

    return expanded_path;
}
