use std::sync::{Arc, Mutex};
use tokio::task;
use chrono::{DateTime, Utc};

struct CustomerOrder {
    order_id: String,
    customer_id: String,
    order_date: DateTime<Utc>,
    total_amount: f64,
    shipping_address: String,
}

struct OrderManager {
    orders: Arc<Mutex<HashMap<String, CustomerOrder>>>,
    min_retry_delay: u64,
    max_retry_delay: u64,
    max_retries: usize,
}

impl OrderManager {
    fn new(min_retry_delay: u64, max_retry_delay: u64, max_retries: usize) -> Self {
        OrderManager {
            orders: Arc::new(Mutex::new(HashMap::new())),
            min_retry_delay,
            max_retry_delay,
            max_retries,
        }
    }

    async fn add_order(&self, order: CustomerOrder) -> Result<(), String> {
        let mut orders = self.orders.lock().unwrap();
        if orders.contains_key(&order.order_id) {
            return Err("Duplicate order ID".to_string());
        }
        orders.insert(order.order_id.clone(), order);
        Ok(())
    }

    async fn remove_order(&self, order_id: &str) -> Result<(), String> {
        let mut orders = self.orders.lock().unwrap();
        if !orders.contains_key(order_id) {
            return Err("Order not found".to_string());
        }
        orders.remove(order_id);
        Ok(())
    }

    async fn get_order_count(&self) -> usize {
        self.orders.lock().unwrap().len()
    }

    async fn filter_orders_by_date_range(
        &self,
        min_date: DateTime<Utc>,
        max_date: DateTime<Utc>,
    ) -> Vec<CustomerOrder> {
        let orders = self.orders.lock().unwrap();
        orders
            .values()
            .filter(|order| order.order_date >= min_date && order.order_date <= max_date)
            .cloned()
            .collect()
    }

    async fn aggregate_order_amounts_by_customer_id(&self) -> HashMap<String, f64> {
        let orders = self.orders.lock().unwrap();
        orders
            .values()
            .fold(HashMap::new(), |mut acc, order| {
                *acc.entry(order.customer_id.clone()).or_insert(0.0) += order.total_amount;
                acc
            })
    }

    async fn retry_with_exponential_backoff<F, R>(&self, mut operation: F)
    -> Result<R, String>
    where
        F: FnMut() -> Result<R, String>,
    {
        let mut delay = self.min_retry_delay;
        for _ in 0..self.max_retries {
            match operation() {
                Ok(result) => return Ok(result),
                Err(_) if delay < self.max_retry_delay => {
                    tokio::time::sleep(tokio::time::Duration::from_secs(delay)).await;
                    delay *= 2;
                }
                Err(e) => return Err(e),
            }
        }
        Err("Operation failed after retries".to_string())
    }
}

#[tokio::main]
async fn main() {
    let order_manager = OrderManager::new(1, 60, 5);

    // Example usage
    let order1 = CustomerOrder {
        order_id: "123".to_string(),
        customer_id: "CUST001".to_string(),
        order_date: Utc::now(),
        total_amount: 100.0,
        shipping_address: "123 Main St".to_string(),
    };

    let order2 = CustomerOrder {
        order_id: "456".to_string(),
        customer_id: "CUST002".to_string(),
        order_date: Utc::now() + chrono::Duration::days(1),
        total_amount: 200.0,
        shipping_address: "456 Elm St".to_string(),
    };

    if let Err(e) = order_manager.retry_with_exponential_backoff(|| order_manager.add_order(order1.clone())).await {
        println!("Failed to add order: {}", e);
    }

    if let Err(e) = order_manager.retry_with_exponential_backoff(|| order_manager.add_order(order2.clone())).await {
        println!("Failed to add order: {}", e);
    }

    if let Err(e) = order_manager.retry_with_exponential_backoff(|| order_manager.remove_order("123")).await {
        println!("Failed to remove order: {}", e);
    }

    match order_manager.get_order_count().await {
        count => println!("Total orders: {}", count),
    }

    let filtered_orders = order_manager.filter_orders_by_date_range(Utc::now() - chrono::Duration::days(1), Utc::now()).await;
    for order in filtered_orders {
        println!("{:?}", order);
    }

    match order_manager.aggregate_order_amounts_by_customer_id().await {
        amounts => println!("Order totals by customer: {:?}", amounts),
    }
}
```']

