#include <stdlib.h>
#include <string.h>

typedef struct {
    int SRB_ID;
    int DRB_ID;
} MAC_SRB_PDU;

typedef struct {
    int SRB_ID;
    int DRB_ID;
} MAC_DRB_PDU;

typedef struct {
    MAC_SRB_PDU srb_pdu;
    MAC_DRB_PDU drb_pdu;
} NR_MAC_PDU_T;

int compare_ids(const void *a, const void *b) {
    NR_MAC_PDU_T *pdu_a = (NR_MAC_PDU_T *)a;
    NR_MAC_PDU_T *pdu_b = (NR_MAC_PDU_T *)b;
    if (pdu_a->srb_pdu.SRB_ID != pdu_b->srb_pdu.SRB_ID) {
        return pdu_a->srb_pdu.SRB_ID - pdu_b->srb_pdu.SRB_ID;
    }
    return pdu_a->drb_pdu.DRB_ID - pdu_b->drb_pdu.DRB_ID;
}

int populate_mac_pdus(NR_MAC_PDU_T **mac_pdus, int *srb_ids, int *drb_ids, int srb_count, int drb_count) {
    int max_elements = 10000;
    *mac_pdus = (NR_MAC_PDU_T *)malloc(max_elements * sizeof(NR_MAC_PDU_T));
    if (*mac_pdus == NULL) {
        return -1; // Memory allocation failed
    }

    int index = 0;
    for (int i = 0; i < srb_count && index < max_elements; i++) {
        for (int j = 0; j < drb_count && index < max_elements; j++) {
            (*mac_pdus)[index].srb_pdu.SRB_ID = srb_ids[i];
            (*mac_pdus)[index].drb_pdu.DRB_ID = drb_ids[j];
            index++;
        }
    }

    qsort(*mac_pdus, index, sizeof(NR_MAC_PDU_T), compare_ids);

    int unique_count = 1;
    for (int i = 1; i < index && unique_count < max_elements; i++) {
        if ((*mac_pdus)[i].srb_pdu.SRB_ID != (*mac_pdus)[unique_count - 1].srb_pdu.SRB_ID ||
            (*mac_pdus)[i].drb_pdu.DRB_ID != (*mac_pdus)[unique_count - 1].drb_pdu.DRB_ID) {
            memcpy(&(*mac_pdus)[unique_count], &(*mac_pdus)[i], sizeof(NR_MAC_PDU_T));
            unique_count++;
        }
    }

    *mac_pdus = (NR_MAC_PDU_T *)realloc(*mac_pdus, unique_count * sizeof(NR_MAC_PDU_T));
    if (*mac_pdus == NULL) {
        return -1; // Memory reallocation failed
    }

    return unique_count;
}
