#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKET_SIZE 1024
#define MAX_NUM_PACKETS 1000000
#define MAX_MEMORY_LIMIT (256 * 1024 * 1024)

typedef struct {
    int packet_id;
    time_t timestamp;
    char payload[MAX_PACKET_SIZE];
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t size;
    size_t capacity;
} PacketManager;

PacketManager* manage_and_validate_data_packets(int action, int id, time_t ts, const char* payload, size_t payload_size) {
    static PacketManager manager = { NULL, 0, 0 };
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    static time_t last_cleanup_time = 0;

    if (action == INIT) {
        // Initialize the packet manager
        return &manager;
    }

    pthread_mutex_lock(&lock);

    switch (action) {
        case ADD_PACKET:
            if (manager.size >= MAX_NUM_PACKETS || manager.capacity < manager.size + 1) {
                pthread_mutex_unlock(&lock);
                return NULL; // Reached maximum number of packets
            }
            if (payload_size > MAX_PACKET_SIZE) {
                pthread_mutex_unlock(&lock);
                return NULL; // Payload too large
            }

            DataPacket* new_packet = &manager.packets[manager.size];
            new_packet->packet_id = id;
            new_packet->timestamp = ts;
            memcpy(new_packet->payload, payload, payload_size);

            if (manager.capacity == manager.size) {
                manager.capacity *= 2;
                manager.packets = realloc(manager.packets, manager.capacity * sizeof(DataPacket));
            }

            manager.size++;
            break;

        case REMOVE_PACKET:
            for (size_t i = 0; i < manager.size; i++) {
                if (manager.packets[i].packet_id == id) {
                    memmove(&manager.packets[i], &manager.packets[i + 1], (manager.size - i - 1) * sizeof(DataPacket));
                    manager.size--;
                    break;
                }
            }
            break;

        case GET_COUNT:
            pthread_mutex_unlock(&lock);
            return &manager;

        default:
            pthread_mutex_unlock(&lock);
            return NULL; // Invalid action
    }

    time_t now = time(NULL);
    if (now - last_cleanup_time > 60) { // Clean up every minute
        for (size_t i = 0; i < manager.size;) {
            if (difftime(now, manager.packets[i].timestamp) > 30) { // Remove packets older than 30 seconds
                memmove(&manager.packets[i], &manager.packets[i + 1], (manager.size - i - 1) * sizeof(DataPacket));
                manager.size--;
            } else {
                i++;
            }
        }
        last_cleanup_time = now;
    }

    pthread_mutex_unlock(&lock);
    return &manager;
}
