        pub fn new() -> Self {
            CustomerOrderManager {
                orders: Mutex::new(HashMap::new()),
            }
        }

        pub async fn add_order(&self, order: CustomerOrder) -> Result<(), String> {
            let mut orders = self.orders.lock().await;
            if orders.contains_key(&order.order_id) {
                Err("Duplicate order ID".to_string())
            } else {
                orders.insert(order.order_id.clone(), order);
                Ok(())
            }
        }

        pub async fn remove_order(&self, order_id: &str) -> Result<(), String> {
            let mut orders = self.orders.lock().await;
            if orders.remove(order_id).is_some() {
                Ok(())
            } else {
                Err("Order not found".to_string())
            }
        }

        pub async fn get_order_count(&self) -> usize {
            let orders = self.orders.lock().await;
            orders.len()
        }

        pub async fn filter_orders_by_date(
            &self,
            min_date: NaiveDateTime,
            max_date: NaiveDateTime,
        ) -> Vec<CustomerOrder> {
            let orders = self.orders.lock().await;
            orders
                .values()
                .filter(|order| order.order_date >= min_date && order.order_date <= max_date)
                .cloned()
                .collect()
        }

        pub async fn aggregate_order_amounts_by_customer_id(
            &self,
        ) -> HashMap<String, f64> {
            let orders = self.orders.lock().await;
            let mut aggregated_amounts = HashMap::new();
            for order in orders.values() {
                *aggregated_amounts.entry(order.customer_id.clone()).or_insert(0.0) += order.total_amount;
            }
            aggregated_amounts
        }

        pub async fn process_orders(&self, orders: Vec<CustomerOrder>) -> Result<(), String> {
            let mut errors = HashSet::new();
            for order in orders {
                if let Err(e) = self.add_order(order).await {
                    errors.insert(e);
                }
            }
            if errors.is_empty() {
                Ok(())
            } else {
                Err(format!("Errors: {:?}", errors))
            }
        }
    }

    #[derive(Clone, Debug)]
    pub struct CustomerOrder {
        pub order_id: String,
        pub customer_id: String,
        pub order_date: NaiveDateTime,
        pub total_amount: f64,
        pub shipping_address: String,
    }
}
```

