#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char **items;
    int front, rear, size, capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_empty, not_full;
} PriorityQueue;

PriorityQueue* create_priority_queue(int capacity) {
    PriorityQueue *q = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    q->items = (char**)malloc(capacity * sizeof(char*));
    q->front = q->rear = -1;
    q->size = 0;
    q->capacity = capacity;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    pthread_cond_init(&q->not_full, NULL);
    return q;
}

void destroy_priority_queue(PriorityQueue *q) {
    for (int i = 0; i < q->size; i++) {
        free(q->items[i]);
    }
    free(q->items);
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->not_empty);
    pthread_cond_destroy(&q->not_full);
    free(q);
}

void enqueue(PriorityQueue *q, char *item, int priority) {
    pthread_mutex_lock(&q->lock);
    while (q->size == q->capacity) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }
    if (q->rear == -1) {
        q->front = q->rear = 0;
    } else if (q->rear + 1 == q->capacity) {
        q->rear = 0;
    } else {
        q->rear++;
    }
    q->items[q->rear] = strdup(item);
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->lock);
}

char* dequeue(PriorityQueue *q, int timeout_ms) {
    char *item = NULL;
    pthread_mutex_lock(&q->lock);
    if (timeout_ms > 0) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += timeout_ms / 1000;
        ts.tv_nsec += (timeout_ms % 1000) * 1000000;
        if (pthread_cond_timedwait(&q->not_empty, &q->lock, &ts) == ETIMEDOUT) {
            pthread_mutex_unlock(&q->lock);
            return NULL; // Timeout
        }
    } else {
        while (q->size == 0) {
            pthread_cond_wait(&q->not_empty, &q->lock);
        }
    }
    item = q->items[q->front];
    if (q->front + 1 == q->capacity) {
        q->front = 0;
    } else if (q->front + 1 == q->rear) {
        q->front = q->rear = -1;
    } else {
        q->front++;
    }
    q->size--;
    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->lock);
    return item;
}

void adjust_capacity(PriorityQueue *q, int new_capacity) {
    if (new_capacity < q->size) {
        fprintf(stderr, "Error: New capacity is smaller than the current size.\n");
        return;
    }
    char **new_items = (char**)realloc(q->items, new_capacity * sizeof(char*));
    if (!new_items) {
        fprintf(stderr, "Error: Memory allocation failed for queue adjustment.\n");
        return;
    }
    q->items = new_items;
    q->capacity = new_capacity;
}

void log_event(const char *event) {
    time_t now = time(NULL);
    printf("%s - %s\n", ctime(&now), event);
}
