public class ReportTitleGenerator {

    private static final String DEPARTMENT_API_URL = "https://department.api.com/code";
    private static final String VERSION_API_URL = "https://version.api.com/version";
    private static final int MAX_TITLE_LENGTH = 256;
    private static final long CACHE_EXPIRY_TIME = 3600000; // 1 hour in milliseconds

    private Map<String, String> departmentCache = new HashMap<>();
    private Map<String, String> versionCache = new HashMap<>();

    public String generateReportTitle(List<String> inputStrings, byte[] data) throws Exception {
        long startTime = System.currentTimeMillis();
        log("Starting report title generation with " + inputStrings.size() + " strings and a data length of " + data.length);

        if (inputStrings == null) {
            inputStrings = new ArrayList<>();
        }

        String departmentCode = fetchDepartmentCode();
        String versionNumber = fetchVersionNumber();

        StringBuilder titleBuilder = new StringBuilder("Report Title: ");
        for (String str : inputStrings) {
            if (str != null && !str.isEmpty()) {
                titleBuilder.append(str).append(" ");
            }
        }

        titleBuilder.append(departmentCode).append(" ").append(versionNumber);
        String title = titleBuilder.toString().trim();

        if (title.length() > MAX_TITLE_LENGTH) {
            log("Title exceeds maximum length. Truncating...");
            title = title.substring(0, MAX_TITLE_LENGTH - 1);
        }

        long endTime = System.currentTimeMillis();
        log("Report title generation completed in " + (endTime - startTime) + " ms");
        log("Final title length: " + title.length());

        sendToDatabase(data);

        return title;
    }

    private String fetchDepartmentCode() throws IOException {
        if (!departmentCache.isEmpty()) {
            long currentTime = System.currentTimeMillis();
            if ((currentTime - departmentCache.get("lastAccessed")) < CACHE_EXPIRY_TIME) {
                return departmentCache.get("code");
            }
        }

        URL url = new URL(DEPARTMENT_API_URL);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        try (DataInputStream in = new DataInputStream(connection.getInputStream())) {
            String code = in.readLine();
            departmentCache.put("code", code);
            departmentCache.put("lastAccessed", Long.toString(System.currentTimeMillis()));
            return code;
        } finally {
            connection.disconnect();
        }
    }

    private String fetchVersionNumber() throws IOException {
        if (!versionCache.isEmpty()) {
            long currentTime = System.currentTimeMillis();
            if ((currentTime - versionCache.get("lastAccessed")) < CACHE_EXPIRY_TIME) {
                return versionCache.get("number");
            }
        }

        URL url = new URL(VERSION_API_URL);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        try (DataInputStream in = new DataInputStream(connection.getInputStream())) {
            String number = in.readLine();
            versionCache.put("number", number);
            versionCache.put("lastAccessed", Long.toString(System.currentTimeMillis()));
            return number;
        } finally {
            connection.disconnect();
        }
    }

    private void sendToDatabase(byte[] data) throws Exception {
        log("Sending data to database");
        String jdbcUrl = "jdbc:mysql://database.server.com/db";
        String username = "user";
        String password = "password";

        try (Connection conn = DriverManager.getConnection(jdbcUrl, username, password);
             Statement stmt = conn.createStatement();
             ByteArrayOutputStream baos = new ByteArrayOutputStream()) {

            DataOutputStream dos = new DataOutputStream(baos);
            dos.write(data);

            byte[] bytesToDB = baos.toByteArray();
            String base64EncodedData = Base64.getEncoder().encodeToString(bytesToDB);

            stmt.executeUpdate("INSERT INTO data_table (data) VALUES ('" + base64EncodedData + "')");

