using UnityEngine;
using System.Collections.Generic;

public class CustomRandom
{
    private float minValue = 0f;
    private float maxValue = 1f;

    public CustomRandom(float min = 0f, float max = 1f)
    {
        if (min > max)
        {
            Debug.LogWarning("Invalid range. Min value should not be greater than max value.");
            minValue = 0f;
            maxValue = 1f;
        }
        else
        {
            minValue = min;
            maxValue = max;
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int GetExclusiveRandomInt()
    {
        if (maxValue - minValue < 2)
        {
            Debug.LogWarning("Invalid range for exclusive random integer. Range should be at least 2 units wide.");
            return GetRandomInt();
        }
        return (int)UnityEngine.Random.Range(minValue + 1, maxValue + 1);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public int[] GetRandomValues(int count)
    {
        if (count > (int)(maxValue - minValue + 1))
        {
            Debug.LogWarning("Cannot generate unique values within the given range.");
            return new int[0];
        }
        var result = new HashSet<int>();
        while (result.Count < count)
        {
            result.Add(GetRandomInt());
        }
        return result.ToArray();
    }

    public int FillArrayWithRandomValues(int[] array, int count)
    {
        if (array.Length < count || count > (int)(maxValue - minValue + 1))
        {
            Debug.LogError("Array is too small to hold all unique values.");
            return 0;
        }
        var result = new HashSet<int>();
        int filledCount = 0;
        while (filledCount < count)
        {
            int value = GetRandomInt();
            if (!result.Contains(value))
            {
                array[filledCount++] = value;
                result.Add(value);
            }
        }
        return filledCount;
    }

    public List<string> GenerateRandomStrings(int count, int length)
    {
        var characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
        var result = new List<string>();
        for (int i = 0; i < count; i++)
        {
            var randomString = new string(Enumerable.Repeat(characters, length)
              .Select(s => s[UnityEngine.Random.Range(0, s.Length)]).ToArray());
            result.Add(randomString);
        }
        return result;
    }

    public int GetRandomWeightedValue(double[] weights)
    {
        if (weights == null || weights.Length == 0)
        {
            Debug.LogError("Weights array is empty.");
            return -1;
        }
        double totalWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            totalWeight += weights[i];
        }
        double randomValue = UnityEngine.Random.value * totalWeight;
        double cumulativeWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue <= cumulativeWeight)
            {
                return i;
            }
        }
        return -1;
    }
}
