public class DataSampler
{
    private float minValue = 0.0f;
    private float maxValue = 1.0f;

    public DataSampler(float minValue = 0.0f, float maxValue = 1.0f)
    {
        if (minValue > maxValue)
        {
            Debug.LogWarning("Invalid range. Setting default values.");
            this.minValue = 0.0f;
            this.maxValue = 1.0f;
        }
        else
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int GetExclusiveRandomInt()
    {
        if (maxValue - minValue < 2)
        {
            Debug.LogWarning("Not enough range for exclusive random integer.");
            return GetRandomInt();
        }
        return (int)UnityEngine.Random.Range(minValue + 1, maxValue);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public int[] SampleUniqueValues(int count)
    {
        if (count > maxValue - minValue + 1)
        {
            Debug.LogError("Not enough unique values in the range.");
            return new int[0];
        }

        int[] sampledValues = new int[count];
        HashSet<int> usedValues = new HashSet<int>();

        for (int i = 0; i < count; i++)
        {
            int value;
            do
            {
                value = GetRandomInt();
            } while (!usedValues.Add(value));

            sampledValues[i] = value;
        }

        return sampledValues;
    }

    public int FillArrayWithUniqueValues(int[] array, int count)
    {
        if (array.Length < count)
        {
            Debug.LogError("Array is too small to hold all unique values.");
            return 0;
        }

        HashSet<int> usedValues = new HashSet<int>();
        int filledCount = 0;

        for (int i = 0; i < array.Length; i++)
        {
            if (usedValues.Count >= count)
                break;

            int value;
            do
            {
                value = GetRandomInt();
            } while (!usedValues.Add(value));

            array[i] = value;
            filledCount++;
        }

        return filledCount;
    }

    public List<string> GenerateRandomStrings(int count, int length)
    {
        List<string> strings = new List<string>();
        Random random = new Random();

        for (int i = 0; i < count; i++)
        {
            string randomString = "";
            for (int j = 0; j < length; j++)
            {
                char randomChar = (char)(random.Next(26) + 'a');
                if (random.Next(2) == 1)
                    randomChar = char.ToUpper(randomChar);
                randomString += randomChar;
            }
            strings.Add(randomString);
        }

        return strings;
    }

    public int GetRandomWeightedValue(double[] weights)
    {
        double sum = 0;
        foreach (double weight in weights)
        {
            sum += weight;
        }

        double randomValue = UnityEngine.Random.Range(0.0, sum);
        double cumulativeSum = 0;

        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeSum += weights[i];
            if (randomValue <= cumulativeSum)
                return i;
        }

        Debug.LogError("Failed to get a valid weighted value.");
        return -1;
    }
}
