public class DataGenerator
{
    private float minValue = 0;
    private float maxValue = 0;

    public DataGenerator(float minValue = 0, float maxValue = 0)
    {
        if (minValue > maxValue)
        {
            this.minValue = maxValue - 1;
            Debug.LogWarning("Invalid range: min > max. Adjusting to min = max - 1.");
        }
        else
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1f);
    }

    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue + 1f);
    }

    public int GetExclusiveRandomInt()
    {
        if (maxValue <= minValue + 1)
            throw new InvalidOperationException("Range too small for exclusive random integer generation.");

        float randomValue = UnityEngine.Random.Range(minValue + 1, maxValue + 1f);
        return (int)Math.Floor(randomValue);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public int[] SampleUniqueValues(int count)
    {
        if (count > (maxValue - minValue + 1))
        {
            Debug.LogError("Not enough unique values in the range.");
            return new int[0];
        }

        var result = new int[count];
        var usedValues = new HashSet<int>();

        while (usedValues.Count < count)
        {
            int value;
            do
            {
                value = GetRandomInt();
            } while (!usedValues.Add(value));
        }

        Array.Copy(usedValues.ToArray(), result, count);
        return result;
    }

    public int FillArrayWithUniqueValues(int[] array, int count)
    {
        if (array.Length < count)
        {
            Debug.LogError("Array too small to fill with unique values.");
            return 0;
        }

        var usedValues = new HashSet<int>();

        while (usedValues.Count < count)
        {
            int value;
            do
            {
                value = GetRandomInt();
            } while (!usedValues.Add(value));
        }

        Array.Copy(usedValues.ToArray(), array, count);
        return count;
    }

    public List<string> GenerateRandomStrings(int count, int length)
    {
        var result = new List<string>();
        const string characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

        for (int i = 0; i < count; i++)
        {
            var randomString = new char[length];
            for (int j = 0; j < length; j++)
            {
                randomString[j] = characters[UnityEngine.Random.Range(0, characters.Length)];
            }
            result.Add(new string(randomString));
        }

        return result;
    }

    public int GetRandomWeightedValue(double[] weights)
    {
        double totalWeight = 0;

        for (int i = 0; i < weights.Length; i++)
        {
            if (weights[i] <= 0)
                continue;

            totalWeight += weights[i];
        }

        double randomValue = UnityEngine.Random.Range(0, totalWeight);
        double cumulativeWeight = 0;

        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue <= cumulativeWeight)
                return i;
        }

        throw new InvalidOperationException("Invalid weights array.");
    }
}
