public class SimulationHelper
{
    private float minValue;
    private float maxValue;

    public SimulationHelper(float minValue = 0, float maxValue = 0)
    {
        if (minValue > maxValue)
        {
            Console.WriteLine("Warning: minValue is greater than maxValue. Adjusting minValue to maxValue - 1.");
            this.minValue = maxValue - 1;
        }
        else
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        return UnityEngine.Random.Range((int)minValue, (int)(maxValue + 1));
    }

    public int GetExclusiveRandomInt()
    {
        if (minValue >= maxValue - 1)
        {
            throw new InvalidOperationException("Range is too small for exclusive random integer.");
        }
        return UnityEngine.Random.Range((int)Math.Ceiling(minValue) + 1, (int)Math.Floor(maxValue));
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public int[] SampleUniqueValues(int count)
    {
        if (count > maxValue - minValue + 1)
        {
            Console.WriteLine("Error: Not enough unique values in the range.");
            count = (int)(maxValue - minValue + 1);
        }
        var sample = new HashSet<int>();
        while (sample.Count < count)
        {
            sample.Add(UnityEngine.Random.Range((int)minValue, (int)(maxValue + 1)));
        }
        return sample.ToArray();
    }

    public int FillArrayWithUniqueValues(int[] array, int count)
    {
        if (count > maxValue - minValue + 1 || count > array.Length)
        {
            Console.WriteLine("Error: Not enough unique values or array is too small.");
            count = Math.Min(maxValue - minValue + 1, array.Length);
        }
        var sample = new HashSet<int>();
        int filled = 0;
        while (sample.Count < count && filled < array.Length)
        {
            var value = UnityEngine.Random.Range((int)minValue, (int)(maxValue + 1));
            if (!sample.Contains(value))
            {
                array[filled++] = value;
                sample.Add(value);
            }
        }
        return filled;
    }

    public List<string> GenerateRandomStrings(int count, int length)
    {
        var random = new Random();
        var characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
        var result = new List<string>();
        for (int i = 0; i < count; i++)
        {
            var stringChars = new char[length];
            for (int j = 0; j < length; j++)
            {
                stringChars[j] = characters[random.Next(characters.Length)];
            }
            result.Add(new string(stringChars));
        }
        return result;
    }

    public int GetRandomWeightedValue(double[] weights)
    {
        if (weights == null || weights.Length == 0)
        {
            throw new ArgumentException("Weights array cannot be empty.");
        }
        double totalWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            totalWeight += weights[i];
        }
        double randomValue = UnityEngine.Random.value * totalWeight;
        double cumulativeWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue <= cumulativeWeight)
            {
                return i;
            }
        }
        throw new InvalidOperationException("Random value exceeds total weight.");
    }
}
