using System;
using UnityEngine;

public class CustomRandom
{
    private float minValue = 0f;
    private float maxValue = 1f;
    private static Random randomGenerator = new Random();

    public CustomRandom(float minValue = 0f, float maxValue = 1f)
    {
        if (minValue > maxValue)
        {
            Debug.LogWarning("Invalid range. Setting to default [0, 1].");
            this.minValue = 0f;
            this.maxValue = 1f;
        }
        else
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int GetRandomInt()
    {
        return UnityEngine.Random.Range((int)minValue, (int)(maxValue + 1));
    }

    public int GetExclusiveRandomInt()
    {
        if (minValue >= maxValue - 1)
        {
            Debug.LogWarning("Range too small for exclusive random int. Returning minValue.");
            return (int)minValue;
        }
        while (true)
        {
            int value = UnityEngine.Random.Range((int)minValue + 1, (int)(maxValue + 1));
            if (value != (int)minValue && value != (int)maxValue)
            {
                return value;
            }
        }
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public Vector3 GetRandomVector3()
    {
        return new Vector3(GetRandomFloat(), GetRandomFloat(), GetRandomFloat());
    }

    public static void InitializeSeeds(long seed)
    {
        randomGenerator = new Random(seed);
    }
}
