using UnityEngine;
using System.Collections.Generic;
using System.Linq;

public class CustomRandom
{
    private float minValue = 0f;
    private float maxValue = 1f;

    public CustomRandom(float minValue, float maxValue)
    {
        if (minValue > maxValue)
        {
            Debug.LogWarning("Invalid range. min must be less than max. Setting default values.");
            this.minValue = 0f;
            this.maxValue = 1f;
        }
        else
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }
    }

    public CustomRandom() : this(0f, 1f) { }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int GetRandomInt()
    {
        return Mathf.RoundToInt(GetRandomFloat());
    }

    public int GetExclusiveRandomInt()
    {
        return (int)(GetRandomFloat() * (maxValue - minValue)) + (int)minValue + 1;
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public static void InitializeSeeds(long seed)
    {
        UnityEngine.Random.InitState((int)(seed & int.MaxValue));
    }

    public Vector3 GetRandomVector3()
    {
        return new Vector3(GetRandomFloat(), GetRandomFloat(), GetRandomFloat());
    }

    public int GetWeightedRandomInt(int[] weights, int maxValue)
    {
        if (weights.Sum() > maxValue)
        {
            throw new ArgumentException("Sum of weights exceeds maxValue.");
        }

        int randomValue = UnityEngine.Random.Range(0, maxValue);
        int cumulativeWeight = 0;

        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue < cumulativeWeight)
            {
                return i;
            }
        }

        throw new InvalidOperationException("Invalid state reached.");
    }
}
