using System;
using UnityEngine;

public class CustomRandom
{
    private float minValue = 0f;
    private float maxValue = 1f;

    public CustomRandom(float minValue = 0f, float maxValue = 1f)
    {
        if (minValue > maxValue)
        {
            Debug.LogWarning("Invalid range. Min value is greater than max value. Setting defaults.");
            this.minValue = 0f;
            this.maxValue = 1f;
        }
        else
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1f);
    }

    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int GetExclusiveRandomInt()
    {
        if (minValue >= maxValue - 1)
        {
            Debug.LogWarning("Invalid range for exclusive random. Min value is too close to max value.");
            return (int)minValue;
        }
        float randomFloat = UnityEngine.Random.Range(minValue + 1, maxValue);
        return (int)Math.Floor(randomFloat);
    }

    public Vector3 GetRandomVector3()
    {
        if (maxValue == 0f)
        {
            maxValue = 1f;
        }
        return new Vector3(
            UnityEngine.Random.Range(0f, maxValue),
            UnityEngine.Random.Range(0f, maxValue),
            UnityEngine.Random.Range(0f, maxValue)
        );
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public int GetRandomInt(int[] weights, int maxValue)
    {
        if (weights == null || weights.Length == 0)
        {
            Debug.LogWarning("Invalid weights array. Using default random integer.");
            return UnityEngine.Random.Range(0, maxValue + 1);
        }

        int totalWeight = 0;
        foreach (int weight in weights)
        {
            totalWeight += weight;
        }

        if (totalWeight > maxValue)
        {
            Debug.LogWarning("Total weight exceeds maxValue. Adjusting weights or maxValue.");
            return GetRandomInt(weights, totalWeight);
        }

        int randomValue = UnityEngine.Random.Range(0, totalWeight);
        for (int i = 0; i < weights.Length; i++)
        {
            if (randomValue < weights[i])
            {
                return i;
            }
            randomValue -= weights[i];
        }

        return weights.Length - 1;
    }

    // Unit tests
    public static void Main()
    {
        CustomRandom customRandom = new CustomRandom(0, 10);

        Console.WriteLine(customRandom.ToString());
        Console.WriteLine($"Random Float: {customRandom.GetRandomFloat()}");
        Console.WriteLine($"Random Int: {customRandom.GetRandomInt()}");
        Console.WriteLine($"Exclusive Random Int: {customRandom.GetExclusiveRandomInt()}");
        Console.WriteLine($"Random Vector3: {customRandom.GetRandomVector3()}");

        int[] weights = { 1, 2, 3, 4, 5 };
        Console.WriteLine($"Weighted Random Int: {customRandom.GetRandomInt(weights, 10)}");
    }
}
