using System;
using System.Collections.Generic;

public class DataGenerator
{
    private int minValue;
    private int maxValue;

    public DataGenerator(int minValue = 0, int maxValue = 0)
    {
        if (minValue > maxValue)
        {
            Console.WriteLine("Warning: Min value greater than max value. Adjusting.");
            this.minValue = maxValue - 1;
        }
        else
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }
    }

    public float GenerateRandomFloat()
    {
        Random random = new Random();
        return (float)random.NextDouble() * (maxValue - minValue) + minValue;
    }

    public int GenerateRandomInt()
    {
        return random.Next(minValue, maxValue + 1);
    }

    public int GenerateExclusiveRandomInt()
    {
        if (minValue >= maxValue)
        {
            throw new InvalidOperationException("Min value must be less than max value for exclusive range.");
        }
        Random random = new Random();
        return random.Next(minValue + 1, maxValue);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public int[] SampleUniqueValues(int count)
    {
        if (count > maxValue - minValue)
        {
            Console.WriteLine("Error: Not enough unique values in range.");
            return new int[0];
        }
        Random random = new Random();
        HashSet<int> sampledValues = new HashSet<int>();
        while (sampledValues.Count < count)
        {
            sampledValues.Add(GenerateRandomInt());
        }
        return sampledValues.ToArray();
    }

    public int FillArrayWithUniqueValues(int[] array, int count)
    {
        if (array.Length < count || count > maxValue - minValue)
        {
            Console.WriteLine("Error: Not enough space in array or not enough unique values.");
            return 0;
        }
        Random random = new Random();
        HashSet<int> sampledValues = new HashSet<int>();
        for (int i = 0; i < count; i++)
        {
            int value;
            do
            {
                value = GenerateRandomInt();
            } while (!sampledValues.Add(value));
            array[i] = value;
        }
        return count;
    }

    public List<string> GenerateRandomStrings(int count, int length)
    {
        Random random = new Random();
        List<string> strings = new List<string>();
        for (int i = 0; i < count; i++)
        {
            char[] chars = new char[length];
            for (int j = 0; j < length; j++)
            {
                chars[j] = (char)random.Next('A', 'Z' + 1);
            }
            strings.Add(new string(chars));
        }
        return strings;
    }

    public int GetRandomWeightedValue(double[] weights)
    {
        double totalWeight = 0;
        foreach (double weight in weights)
        {
            totalWeight += weight;
        }
        Random random = new Random();
        double targetWeight = random.NextDouble() * totalWeight;
        double cumulativeWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (targetWeight <= cumulativeWeight)
            {
                return i;
            }
        }
        throw new InvalidOperationException("Invalid weights array.");
    }
}
