def modify_kickstart_file(config_file, replacements):
    timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
    output_file = f"config_modified_{timestamp}.ks"
    try:
        with open(config_file, 'r') as infile, open(output_file, 'w') as outfile:
            for line in infile:
                for old, new in replacements.items():
                    line = line.replace(old, new)
                outfile.write(line)
        logging.info(f"Modified file saved to {output_file}")
    except Exception as e:
        logging.error(f"Error modifying kickstart file: {e}")

def get_pokemon_weaknesses(pokemon_dict):
    weaknesses = defaultdict(list)
    for pokemon, type_ in pokemon_dict.items():
        if type_ not in weakness_map:
            logging.error(f"Unknown type for Pokemon {pokemon}: {type_}")
            continue
        for weak_type in weakness_map[type_]:
            weaknesses[pokemon].append(weak_type)
    return dict(weaknesses)

