function extractBooks(text) {
    const books = ['Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy'];
    const bookRegex = new RegExp(`\\b(${books.join('|')})\\b`, 'gi');
    const matches = text.match(bookRegex);
    const countMap = {};
    if (matches) {
        for (let match of matches) {
            match = match.trim();
            if (countMap[match]) {
                countMap[match]++;
            } else {
                countMap[match] = 1;
            }
        }
    }
    return countMap;
}

// Example usage
const text = "In the book of Genesis, God created Adam and Eve.";
console.log(extractBooks(text));
