function extractBookNames(text) {
  // Regular expression pattern for Old Testament book names
  const bookRegex = /(?:\b(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Ruth|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b)/gi;

