  const books = text.match(bookRegex);

  // Create a frequency count object for each unique book name found in the text
  const bookCounts = {};
  if (books) {
    books.forEach(book => {
      bookCounts[book] = (bookCounts[book] || 0) + 1;
    });
  }

  // Return the frequency count of book names
