import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class ServiceManager {
    private Queue queue;
    private Thread producerThread, consumerThread;

    public ServiceManager(int capacity) {
        this.queue = createQueue(capacity);
        startProducer();
        startConsumer();
    }

    public void stopService() {
        destroy_queue(queue);
        try {
            producerThread.join();
            consumerThread.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private void startProducer() {
        producerThread = new Thread(() -> {
            while (true) {
                // Simulate data production
                int data = produceData();
                synchronized (queue) {
                    if ((queue.rear + 1) % queue.capacity == queue.front) {
                        try {
                            wait();
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                        }
                    }
                    if (queue.front == -1)
                        queue.front = queue.rear = 0;
                    else
                        queue.rear = (queue.rear + 1) % queue.capacity;
                    queue.items[queue.rear] = data;
                    notifyAll();
                }
            }
        });
        producerThread.start();
    }

    private void startConsumer() {
        consumerThread = new Thread(() -> {
            while (true) {
                synchronized (queue) {
                    while (queue.front == -1) {
                        try {
                            wait();
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                        }
                    }
                    int data = queue.items[queue.front];
                    if (queue.front == queue.rear)
                        queue.front = queue.rear = -1;
                    else
                        queue.front = (queue.front + 1) % queue.capacity;
                    notifyAll();
                }
                // Simulate data consumption
                consumeData(data);
            }
        });
        consumerThread.start();
    }

    private int produceData() {
        try {
            Thread.sleep(1000); // Simulate time taken to produce data
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return (int)(Math.random() * 100);
    }

    private void consumeData(int data) {
        try {
            Thread.sleep(2000); // Simulate time taken to consume data
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        System.out.println("Consumed: " + data);
    }

    public String generateMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if(hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    // C function integration code goes here
}
