<?php

function initializeEncryptionCipher($password) {
    // Set default cipher mode
    $cipherMode = 'aes-256-cbc';

    // Check for hardware acceleration support (e.g., OpenSSL engine with AES-NI)
    if (openssl_cipher_iv_length('aes-256-gcm') > 0 && openssl_get_cipher_methods(true) === true) {
        $cipherMode = 'aes-256-gcm';
    }

    // Securely generate an initialization vector
    $iv = openssl_random_pseudo_bytes(openssl_cipher_iv_length($cipherMode));

    // Derive the encryption key from the user-provided password using PKCS5_PBKDF2
    $salt = random_bytes(16);
    $key = hash_pbkdf2('sha256', $password, $salt, 100000, 32);

    // Initialize the encryption cipher with the derived key and IV
    $cipherText = openssl_encrypt($password, $cipherMode, $key, OPENSSL_RAW_DATA, $iv);

    return [
        'cipherText' => base64_encode($cipherText),
        'iv' => base64_encode($iv),
        'salt' => base64_encode($salt)
    ];
}

// Example usage:
$result = initializeEncryptionCipher('userPassword123');
echo "Cipher Text: " . $result['cipherText'] . "\n";
echo "IV: " . $result['iv'] . "\n";
echo "Salt: " . $result['salt'] . "\n";

?>
