using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;

public class ConfigurationManager
{
    private string databaseConnectionString = "DefaultConnection";
    private string apiEndpoint = "https://api.example.com";
    private int loggingLevel = 2;

    public string DatabaseConnectionString { get; set; }
    public string ApiEndpoint { get; set; }
    public int LoggingLevel { get; set; }

    public ConfigurationManager()
    {
        // Default constructor
    }

    public void ValidateConfiguration()
    {
        if (string.IsNullOrEmpty(DatabaseConnectionString))
            Console.WriteLine("Warning: DatabaseConnectionString is not set.");
        if (string.IsNullOrEmpty(ApiEndpoint))
            Console.WriteLine("Warning: ApiEndpoint is not set.");
        if (LoggingLevel < 0 || LoggingLevel > 4)
            Console.WriteLine("Warning: LoggingLevel is out of range.");
    }

    public void ApplySettingsFromDictionary(IDictionary<string, object> settings)
    {
        foreach (var kvp in settings)
        {
            switch (kvp.Key)
            {
                case "DatabaseConnectionString":
                    DatabaseConnectionString = kvp.Value as string;
                    break;
                case "ApiEndpoint":
                    ApiEndpoint = kvp.Value as string;
                    break;
                case "LoggingLevel":
                    if (int.TryParse(kvp.Value.ToString(), out int level))
                        LoggingLevel = level;
                    break;
            }
        }
    }

    public void ApplySettingsFromString(string settingsJson)
    {
        try
        {
            var settings = JsonSerializer.Deserialize<Dictionary<string, object>>(settingsJson);
            ApplySettingsFromDictionary(settings);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing JSON: {ex.Message}");
        }
    }

    public void SaveToDisk()
    {
        string json = JsonSerializer.Serialize(this);
        File.WriteAllText("config.json", json);
    }
}
