// Define constants and structures for transaction management
#define MAX_TRANSACTIONS 1000
#define TRANSACTION_AGE_LIMIT 5000 // 5 seconds in milliseconds
#define TOTAL_TRANSACTION_LIMIT_10S 100

typedef struct {
    int id;
    time_t timestamp;
    int weight;
    int priority;
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int count;
    time_t last_update;
} TransactionQueue;

// Function prototypes
void initializeTransactionQueue(TransactionQueue *queue);
int enqueueTransaction(TransactionQueue *queue, Transaction transaction);
Transaction processTransactions(TransactionQueue *queue, int *highest_weighted_id);
int getTransactionCountLast5Seconds(TransactionQueue *queue);

int main() {
    // Example usage of the transaction processing function
    TransactionQueue queue;
    initializeTransactionQueue(&queue);

    // Simulate transactions
    for (int i = 0; i < 150; i++) {
        Transaction new_transaction = {i, time(NULL) * 1000, rand() % 10 + 1, rand() % 3};
        enqueueTransaction(&queue, new_transaction);
    }

    int highest_weighted_id;
    processTransactions(&queue, &highest_weighted_id);

    printf("Highest Weighted ID: %d\n", highest_weighted_id);

    return 0;
}

// Initialize the transaction queue
void initializeTransactionQueue(TransactionQueue *queue) {
    queue->count = 0;
    queue->last_update = time(NULL);
}

// Enqueue a new transaction
int enqueueTransaction(TransactionQueue *queue, Transaction transaction) {
    if (queue->count >= MAX_TRANSACTIONS) return -1; // Queue is full
    queue->transactions[queue->count++] = transaction;
    return 0; // Success
}

// Process transactions based on the given criteria
Transaction processTransactions(TransactionQueue *queue, int *highest_weighted_id) {
    time_t current_time = time(NULL);
    int total_transactions_last_5s = getTransactionCountLast5Seconds(queue);

    if (total_transactions_last_5s > 100) return (Transaction){-1, -1, -1, -1}; // Exceeds limit

    Transaction highest_weighted_transaction;
    int highest_weighted_sum = 0;

    for (int i = 0; i < queue->count; i++) {
        if ((current_time * 1000) - queue->transactions[i].timestamp < TRANSACTION_AGE_LIMIT) {
            if (queue->transactions[i].weight > highest_weighted_sum) {
                highest_weighted_transaction = queue->transactions[i];
                highest_weighted_sum = queue->transactions[i].weight;
            }
        }
    }

    *highest_weighted_id = highest_weighted_transaction.id;

    return highest_weighted_transaction;
}

// Get the number of transactions processed in the last 5 seconds
int getTransactionCountLast5Seconds(TransactionQueue *queue) {
    time_t current_time = time(NULL);
    int count = 0;

    for (int i = 0; i < queue->count; i++) {
        if ((current_time * 1000) - queue->transactions[i].timestamp <= 5000) {
            count++;
        }
    }

    return count;
}
```

This code snippet provides a basic implementation of the transaction processing function with the specified requirements. It includes initializing the transaction queue, enqueuing new transactions, and processing transactions based on age and weight criteria. The function also calculates the number of transactions processed in the last 5 seconds to enforce the total transaction limit.']

