#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Function to initialize cryptographic library
void init_crypto_library() {
    OpenSSL_add_cipher(EVP_aes_256_cbc());
    OpenSSL_add_cipher(EVP_camellia_256_ecb());
    OpenSSL_add_digest(EVP_md5());
    OpenSSL_add_digest(EVP_sha1());
    EVP_add_digest_alias(EVP_sha256(), "sha2");

    ENGINE_load_builtin_engines();
    ENGINE_init(ENGINE_get_default_rdrand());

    // Initialize mutex for thread safety
    pthread_mutex_t crypto_mutex = PTHREAD_MUTEX_INITIALIZER;
}

// Function to add custom cipher suites based on input parameters
void add_custom_cipher_suites(int aes, int camellia, int md5, int sha) {
    if (aes) OpenSSL_add_cipher(EVP_aes_128_ecb());
    if (camellia) OpenSSL_add_cipher(EVP_camellia_192_cbc());
    if (md5) OpenSSL_add_digest(EVP_md5());
    if (sha) EVP_add_digest_alias(EVP_sha512(), "sha5");
}

// Function for RSA with SHA1 encryption
void rsa_encrypt_with_sha1(const unsigned char *data, size_t data_len, unsigned char **out_encrypted, size_t *out_encrypted_len) {
    RSA *rsa = RSA_new();
    BIGNUM *n = BN_new(), *e = BN_new();

    // Set RSA parameters and generate keys
    BN_set_word(e, 65537);
    BN_hex2bn(&n, "1234567890abcdef");
    RSA_generate_key_ex(rsa, RSA_size(n), e, NULL);

    // Allocate memory for encrypted data
    *out_encrypted_len = RSA_size(rsa);
    *out_encrypted = (unsigned char *)malloc(*out_encrypted_len);

    // Encrypt data using RSA and SHA1
    int result = RSA_public_encrypt(data_len, data, *out_encrypted, rsa, RSA_PKCS1_PADDING);
    if (result == -1) {
        free(*out_encrypted);
        *out_encrypted = NULL;
        *out_encrypted_len = 0;
    }

    RSA_free(rsa);
    BN_free(n);
    BN_free(e);
}

// Function for performance optimization using caching
void optimize_performance() {
    EVP_MD_CTX *md_ctx = EVP_MD_CTX_new();
    unsigned char hash[SHA_DIGEST_LENGTH];

    // Cache frequently used digest operations
    EVP_DigestInit_ex(md_ctx, EVP_sha256(), NULL);
    EVP_DigestUpdate(md_ctx, "data", 4);
    EVP_DigestFinal_ex(md_ctx, hash, NULL);

    EVP_MD_CTX_free(md_ctx);
}

// Function for logging operation metrics
void log_metrics(const char *operation, double duration) {
    FILE *log_file = fopen("crypto_log.txt", "a");
    fprintf(log_file, "%s took %.6f seconds\n", operation, duration);
    fclose(log_file);
}

// Example usage of the cryptographic library functions
int main() {
    init_crypto_library();
    add_custom_cipher_suites(1, 0, 1, 1);

    unsigned char data[] = "Hello, OpenSSL!";
    unsigned char *encrypted;
    size_t encrypted_len;

    clock_t start_time = clock();
    rsa_encrypt_with_sha1(data, sizeof(data) - 1, &encrypted, &encrypted_len);
    double duration = ((double)(clock() - start_time)) / CLOCKS_PER_SEC;

    if (encrypted) {
        free(encrypted);
    }

    log_metrics("RSA Encryption", duration);

    return 0;
}
