#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>

typedef struct {
    EVP_CIPHER_CTX *aes_ctx;
    EVP_CIPHER_CTX *camellia_ctx;
    EVP_PKEY_CTX *rsa_ctx;
} CryptoContext;

CryptoContext* create_crypto_context() {
    CryptoContext *ctx = (CryptoContext*)malloc(sizeof(CryptoContext));
    ctx->aes_ctx = NULL;
    ctx->camellia_ctx = NULL;
    ctx->rsa_ctx = NULL;
    return ctx;
}

void destroy_crypto_context(CryptoContext *ctx) {
    if (ctx->aes_ctx) EVP_CIPHER_CTX_free(ctx->aes_ctx);
    if (ctx->camellia_ctx) EVP_CIPHER_CTX_free(ctx->camellia_ctx);
    if (ctx->rsa_ctx) EVP_PKEY_CTX_free(ctx->rsa_ctx);
    free(ctx);
}

int encrypt_aes(const unsigned char *plaintext, int plaintext_len,
                const unsigned char *key, const unsigned char *iv,
                unsigned char *ciphertext) {
    if (!(ctx->aes_ctx = EVP_CIPHER_CTX_new())) return -1;
    if (1 != EVP_EncryptInit_ex(ctx->aes_ctx, EVP_aes_256_cbc(), NULL, key, iv)) return -1;
    int len;
    if (1 != EVP_EncryptUpdate(ctx->aes_ctx, ciphertext, &len, plaintext, plaintext_len)) return -1;
    int ciphertext_len = len;
    if (1 != EVP_EncryptFinal_ex(ctx->aes_ctx, ciphertext + len, &len)) return -1;
    ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx->aes_ctx);
    ctx->aes_ctx = NULL;
    return ciphertext_len;
}

