            XmlNode configNode = xmlDoc.SelectSingleNode("/config");
            config.TileSize = int.Parse(configNode.SelectSingleNode("tileSize").InnerText);
            config.WorldWidth = int.Parse(configNode.SelectSingleNode("worldWidth").InnerText);
            config.WorldHeight = int.Parse(configNode.SelectSingleNode("worldHeight").InnerText);
            config.CameraSpeed = double.Parse(configNode.SelectSingleNode("cameraSpeed").InnerText);
        } catch (Exception ex) {
            Console.WriteLine("Error loading XML file: " + ex.Message);
        }
        return config;
    }
}

