    int maxValue;
} DataGenerator;

DataGenerator* CreateDataGenerator(int minValue, int maxValue) {
    DataGenerator* generator = (DataGenerator*)malloc(sizeof(DataGenerator));
    if (generator == NULL) {
        printf("Memory allocation failed for DataGenerator\n");
        return NULL;
    }
    generator->minValue = minValue < maxValue ? minValue : maxValue - 1;
    generator->maxValue = maxValue;
    generator->count = 0;
    generator->offsets = NULL;
    generator->keys = NULL;
    generator->records = NULL;
    printf("DataGenerator created with range %d to %d\n", generator->minValue, generator->maxValue);
    return generator;
}

void DestroyDataGenerator(DataGenerator* generator) {
    if (generator == NULL) {
        return;
    }
    free(generator->offsets);
    free(generator->keys);
    for (size_t i = 0; i < generator->count; ++i) {
        free(generator->records[i].value);
    }
    free(generator->records);
    free(generator);
    printf("DataGenerator destroyed\n");
}

