#include <iostream>
#include <vector>
#include <unordered_map>
#include <string>
#include <chrono>
#include <mutex>

enum class LogLevel {
    DEBUG,
    INFO,
    WARNING,
    ERROR
};

struct LogEntry {
    int entry_id;
    std::chrono::system_clock::time_point timestamp;
    LogLevel log_level;
    std::string message;

    LogEntry(int id, std::chrono::system_clock::time_point ts, LogLevel level, const std::string& msg)
        : entry_id(id), timestamp(ts), log_level(level), message(msg) {}
};

class LogEntryManager {
private:
    std::unordered_map<int, LogEntry> entries;
    std::vector<LogEntry> sorted_entries;
    std::mutex mutex;

public:
    void addEntry(const LogEntry& entry) {
        std::lock_guard<std::mutex> lock(mutex);
        if (entries.find(entry.entry_id) == entries.end()) {
            entries[entry.entry_id] = entry;
            sorted_entries.push_back(entry);
            std::sort(sorted_entries.begin(), sorted_entries.end(),
                      [](const LogEntry& a, const LogEntry& b) { return a.timestamp < b.timestamp; });
        }
    }

    bool removeEntry(int entry_id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (entries.find(entry_id) != entries.end()) {
            entries.erase(entry_id);
            sorted_entries.erase(std::remove_if(sorted_entries.begin(), sorted_entries.end(),
                                                [entry_id](const LogEntry& entry) { return entry.entry_id == entry_id; }),
                                sorted_entries.end());
            return true;
        }
        return false;
    }

    size_t getNumberOfEntries() const {
        std::lock_guard<std::mutex> lock(mutex);
        return entries.size();
    }

    std::vector<LogEntry> getEntriesByLevel(LogLevel level) const {
        std::lock_guard<std::mutex> lock(mutex);
        std::vector<LogEntry> result;
        for (const auto& entry : sorted_entries) {
            if (entry.log_level == level) {
                result.push_back(entry);
            }
        }
        return result;
    }

    std::vector<LogEntry> getEntriesByTimestamp(const std::chrono::system_clock::time_point& start, const std::chrono::system_clock::time_point& end) const {
        std::lock_guard<std::mutex> lock(mutex);
        std::vector<LogEntry> result;
        for (const auto& entry : sorted_entries) {
            if (entry.timestamp >= start && entry.timestamp <= end) {
                result.push_back(entry);
            }
        }
        return result;
    }
};

int main() {
    LogEntryManager manager;
    manager.addEntry(LogEntry(1, std::chrono::system_clock::now(), LogLevel::INFO, "System started"));
    manager.addEntry(LogEntry(2, std::chrono::system_clock::now() + std::chrono::seconds(1), LogLevel::WARNING, "Low disk space"));

    std::vector<LogEntry> entries = manager.getEntriesByLevel(LogLevel::WARNING);
    for (const auto& entry : entries) {
        std::cout << "ID: " << entry.entry_id << ", Time: " << entry.timestamp.time_since_epoch().count() << ", Level: " << static_cast<int>(entry.log_level) << ", Message: " << entry.message << std::endl;
    }

    return 0;
}
