#define MAX_PACKETS 10000000

typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

DataPacket *packet_array[MAX_PACKETS];
int packet_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_packet_event(const char *action, int packet_id) {
    // Simulated logging function
    printf("%s: Packet ID %d\n", action, packet_id);
}

int add_packet(int packet_id, time_t timestamp, size_t payload_size) {
    pthread_mutex_lock(&lock);
    if (packet_count >= MAX_PACKETS) {
        log_packet_event("Error", packet_id);
        pthread_mutex_unlock(&lock);
        return -1; // Array is full
    }

    for (int i = 0; i < packet_count; i++) {
        if (packet_array[i]->packet_id == packet_id) {
            log_packet_event("Duplicate ID Error", packet_id);
            pthread_mutex_unlock(&lock);
            return -2; // Duplicate ID
        }
    }

    DataPacket *new_packet = malloc(sizeof(DataPacket));
    new_packet->packet_id = packet_id;
    new_packet->timestamp = timestamp;
    new_packet->payload_size = payload_size;

    packet_array[packet_count++] = new_packet;
    log_packet_event("Added", packet_id);
    pthread_mutex_unlock(&lock);
    return 0; // Success
}

int remove_packet(int packet_id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < packet_count; i++) {
        if (packet_array[i]->packet_id == packet_id) {
            free(packet_array[i]);
            for (int j = i; j < packet_count - 1; j++) {
                packet_array[j] = packet_array[j + 1];
            }
            packet_count--;
            log_packet_event("Removed", packet_id);
            pthread_mutex_unlock(&lock);
            return 0; // Success
        }
    }
    log_packet_event("Error", packet_id);
    pthread_mutex_unlock(&lock);
    return -1; // Packet not found
}

int get_packet_count() {
    return packet_count;
}

void sort_packets_by_timestamp() {
    qsort(packet_array, packet_count, sizeof(DataPacket *), 
          (int (*)(const void *, const void *))compare_packets);

    int prev_id = -1;
    for (int i = 0; i < packet_count; i++) {
        if (packet_array[i]->packet_id == prev_id) {
            remove_packet(prev_id);
            i--;
        } else {
            prev_id = packet_array[i]->packet_id;
        }
    }
}

int compare_packets(const void *a, const void *b) {
    return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp;
}
