        fprintf(stderr, "Failed to open file: %s\n", filename);
        return -1;
    }

    // Create thread for reading
    pthread_t thread;
    pthread_create(&thread, NULL, read_file_chunk, &file_data);

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    // Find and print max integer
    int* max_int = file_data.integers[0];
    size_t max_index = 0;
    for (size_t i = 1; i < *file_data.count; ++i) {
        if (*file_data.integers[i] > *max_int) {
            max_int = file_data.integers[i];
            max_index = i;
        }
    }
    printf("Largest integer: %d at line(s): ", *max_int);
    for (size_t i = 0; i < *file_data.count; ++i) {
        if (*file_data.integers[i] == *max_int) {
            printf("%zu, ", i + 1);
        }
    }
    printf("\n");

    // Clean up
    for (size_t i = 0; i < *file_data.count; ++i) {
        free(file_data.integers[i]);
    }
    free(file_data.integers);
    fclose(file);
    return 0;
}
