#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_PACKETS 10000000

typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct DynamicArray {
    DataPacket *packets[MAX_PACKETS];
    int count;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void add_packet(DynamicArray *array, DataPacket *packet) {
    pthread_mutex_lock(&array->mutex);
    if (array->count < MAX_PACKETS) {
        array->packets[array->count] = packet;
        array->count++;
    }
    pthread_mutex_unlock(&array->mutex);
}

void remove_packet(DynamicArray *array, int packet_id) {
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->count; i++) {
        if (array->packets[i]->packet_id == packet_id) {
            free(array->packets[i]);
            for (int j = i; j < array->count - 1; j++) {
                array->packets[j] = array->packets[j + 1];
            }
            array->count--;
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

int get_packet_count(DynamicArray *array) {
    return array->count;
}

void sort_packets_by_timestamp(DynamicArray *array) {
    // Implement sorting logic here
}

void destroy_dynamic_array(DynamicArray *array) {
    for (int i = 0; i < array->count; i++) {
        free(array->packets[i]);
    }
    pthread_mutex_destroy(&array->mutex);
    free(array);
}
