using System;
using UnityEngine;

public class CustomRandom
{
    private float minValue;
    private float maxValue;
    private static readonly object lockObject = new object();

    public CustomRandom()
        : this(0, 1)
    {
    }

    public CustomRandom(float minValue, float maxValue)
    {
        if (minValue > maxValue)
        {
            Debug.LogWarning("Min value is greater than max value. Defaulting to [0, 1].");
            this.minValue = 0;
            this.maxValue = 1;
        }
        else
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }
    }

    public float GetRandomFloat()
    {
        lock (lockObject)
        {
            return UnityEngine.Random.Range(minValue, maxValue + 1);
        }
    }

    public int GetRandomInt()
    {
        lock (lockObject)
        {
            return UnityEngine.Random.Range((int)minValue, (int)(maxValue + 1));
        }
    }

    public int GetExclusiveRandomInt()
    {
        lock (lockObject)
        {
            if ((int)maxValue - (int)minValue <= 2)
            {
                return (int)Mathf.Floor(UnityEngine.Random.value * ((int)maxValue - (int)minValue + 1)) + (int)minValue + 1;
            }
            else
            {
                return UnityEngine.Random.Range((int)(minValue + 1), (int)maxValue);
            }
        }
    }

    public Vector3 GetRandomVector3()
    {
        lock (lockObject)
        {
            float x = UnityEngine.Random.Range(minValue, maxValue);
            float y = UnityEngine.Random.Range(minValue, maxValue);
            float z = UnityEngine.Random.Range(minValue, maxValue);

            if (minValue < 0 && maxValue > 0)
            {
                // Handle negative and positive ranges
                x = minValue + (maxValue - minValue) * UnityEngine.Random.value;
                y = minValue + (maxValue - minValue) * UnityEngine.Random.value;
                z = minValue + (maxValue - minValue) * UnityEngine.Random.value;
            }

            return new Vector3(x, y, z);
        }
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public static void InitializeSeeds(long seed)
    {
        lock (lockObject)
        {
            UnityEngine.Random.InitState((int)seed);
        }
    }

    public int GetRandomWeightedInt(int[] weights)
    {
        if (weights.Length == 0)
        {
            throw new ArgumentException("Weights array cannot be empty.");
        }

        float totalWeight = 0;
        foreach (int weight in weights)
        {
            if (weight <= 0)
            {
                throw new ArgumentException("Weights must be positive.");
            }
            totalWeight += weight;
        }

        float randomValue = UnityEngine.Random.value * totalWeight;
        float cumulativeWeight = 0;

        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue <= cumulativeWeight)
            {
                return i;
            }
        }

        throw new InvalidOperationException("Failed to select a weighted index.");
    }
}
