using System;
using UnityEngine;

public enum RandomType
{
    FloatType,
    IntType,
    ExclusiveIntType
}

public class CustomRandom
{
    private int minValue = 0;
    private int maxValue = 100;

    public CustomRandom(int minValue = 0, int maxValue = 100)
    {
        if (minValue > maxValue)
        {
            Debug.LogWarning("Invalid range. Setting min to 0 and max to 100.");
            this.minValue = 0;
            this.maxValue = 100;
        }
        else
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int GetRandomInt()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int GetExclusiveRandomInt()
    {
        if (minValue >= maxValue)
        {
            Debug.LogWarning("Invalid range for exclusive random. Using default range.");
            minValue = 0;
            maxValue = 100;
        }
        return UnityEngine.Random.Range(minValue + 1, maxValue);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public object GetRandomValueInRange(RandomType type)
    {
        switch (type)
        {
            case RandomType.FloatType:
                return GetRandomFloat();
            case RandomType.IntType:
                return GetRandomInt();
            case RandomType.ExclusiveIntType:
                return GetExclusiveRandomInt();
            default:
                throw new ArgumentException("Invalid random type.");
        }
    }
}
