        int exclusiveIntValue = (int)customRandom.GetRandomValueInRange(RandomType.ExclusiveIntType);
        Assert.GreaterOrEqual(floatValue, 0f);
        Assert.LessOrEqual(floatValue, 1f);
        Assert.GreaterOrEqual(intValue, 0);
        Assert.LessOrEqual(intValue, 100);
        Assert.Greater(exclusiveIntValue, 0);
        Assert.LessOrEqual(exclusiveIntValue, 99);
