using System;

public class ValueGenerator
{
    private Random _random;
    private int _minValue;
    private int _maxValue;

    public ValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("MinValue must be less than or equal to MaxValue");
        }
        _minValue = minValue;
        _maxValue = maxValue;
        _random = new Random();
    }

    public float GetRandomFloat()
    {
        return _random.NextFloat(_minValue, _maxValue);
    }

    public int GetRandomInt()
    {
        return _random.Next(_minValue, _maxValue + 1);
    }

    public double GetRandomDouble()
    {
        return _random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public Color GetRandomColor(int minR = 0, int maxR = 255, int minG = 0, int maxG = 255, int minB = 0, int maxB = 255)
    {
        if (minR > maxR || minG > maxG || minB > maxB)
        {
            throw new ArgumentException("Min values must be less than or equal to Max values for R, G, and B");
        }
        return Color.FromArgb(_random.Next(minR, maxR + 1), _random.Next(minG, maxG + 1), _random.Next(minB, maxB + 1));
    }

    public override string ToString()
    {
        return $"Range: {_minValue} to {_maxValue}, Seed: {_random.Seed}";
    }
}
