    public void ConfigureProcessingParameters(int interval, double threshold, bool compress)
    {
        samplingInterval = interval > 0 ? interval : throw new ArgumentException("Sampling interval must be positive.");
        noiseThreshold = threshold >= 0 ? threshold : throw new ArgumentException("Noise threshold must be non-negative.");
        isCompressed = compress;
    }

    public void ReadDataFromSource(string sourceType)
    {
        switch (sourceType.ToLower())
        {
            case "file":
                using (FileStream fileStream = File.OpenRead("data.txt"))
                {
                    dataStream = new MemoryStream(fileStream.ToArray());
                }
                break;
            case "network":
                // Implement network stream reading logic
                throw new NotImplementedException();
            case "database":
                // Implement database stream reading logic
                throw new NotImplementedException();
            default:
                throw new ArgumentException("Unsupported source type.");
        }
    }

    public void FilterNoise()
    {
        byte[] data = ((MemoryStream)dataStream).ToArray();
        byte[] filteredData = data.SkipWhile((value, index) => index % samplingInterval != 0 && value < noiseThreshold).ToArray();
        dataStream = new MemoryStream(filteredData);
    }

    public void ApplyTransformations(Func<byte[], byte[]> transformation)
    {
        if (transformation == null)
            throw new ArgumentNullException(nameof(transformation));

        byte[] data = ((MemoryStream)dataStream).ToArray();
        byte[] transformedData = transformation(data);
        dataStream = new MemoryStream(transformedData);
    }

    public void CompressData()
    {
        // Implement compression logic
