    }

    public void VisualizeData()
    {
        // Implement visualization logic
        throw new NotImplementedException();
    }

    public override string ToString()
    {
        return $"DataProcessor: Stream={dataStream.Length} bytes, Interval={samplingInterval}, Threshold={noiseThreshold}, Compressed={isCompressed}";
    }
