public class RandomValueGenerator : ISerializable
{
    private float minValue;
    private float maxValue;
    private int frequency;
    private DateTime lastTimeGenerated;
    private readonly object lockObject = new object();

    public RandomValueGenerator(float minValue, float maxValue, int frequency)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Min value must be less than or equal to max value.");
        }

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.frequency = frequency;
        lastTimeGenerated = DateTime.MinValue;
        UnityEngine.Random.InitState((int)DateTime.Now.Ticks);
    }

    public float GetRandomFloat()
    {
        lock (lockObject)
        {
            EnsureTimePassed();
            return UnityEngine.Random.Range(minValue, maxValue);
        }
    }

    public int GetRandomInt()
    {
        lock (lockObject)
        {
            EnsureTimePassed();
            return UnityEngine.Random.Range((int)minValue, (int)maxValue);
        }
    }

    private void EnsureTimePassed()
    {
        var currentTime = DateTime.Now;
        if ((currentTime - lastTimeGenerated).TotalMilliseconds >= 1000 / frequency)
        {
            lastTimeGenerated = currentTime;
        }
        else
        {
            System.Threading.Thread.Sleep((int)(1000 * (frequency - (int)(1000 / frequency)) / frequency));
        }
    }

    public override string ToString()
    {
        return $"Range: {minValue} to {maxValue}, Frequency: {frequency}";
    }

    public void ResetGenerator()
    {
        lock (lockObject)
        {
            lastTimeGenerated = DateTime.MinValue;
        }
    }

    public byte[] Serialize()
    {
        // Implement serialization logic here
        throw new NotImplementedException();
    }

    public static RandomValueGenerator Deserialize(byte[] data)
    {
        // Implement deserialization logic here
        throw new NotImplementedException();
    }
}
