    private int maxValue;
    private float lastTimeGenerated;
    private static readonly object lockObject = new object();

    public RandomValueGenerator(int min, int max)
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        }
        minValue = min;
        maxValue = max;
        lastTimeGenerated = Time.time;
    }

    public float GenerateRandomFloat()
    {
        lock (lockObject)
        {
            return UnityEngine.Random.Range(minValue, maxValue + 1);
        }
    }

    public int GenerateRandomInt()
    {
        lock (lockObject)
        {
            return UnityEngine.Random.Range(minValue, maxValue + 1);
        }
    }

    public void GenerateRandomAtInterval(float interval)
    {
        if (Time.time - lastTimeGenerated > interval)
        {
            lock (lockObject)
            {
                int randomValue = UnityEngine.Random.Range(minValue, maxValue + 1);
                Debug.Log("Generated Random Value: " + randomValue);
                lastTimeGenerated = Time.time;
            }
        }
    }

    public override string ToString()
    {
        return $"RandomRangeGenerator({minValue} - {maxValue})";
    }

    int IComparable<RandomValueGenerator>.CompareTo(RandomValueGenerator other)
    {
        if (other == null) return 1;
        return minValue.CompareTo(other.minValue);
