    }

    public void ResetSequence()
    {
        seed = random.Next();
        Initialize(minValue, maxValue, seed);
    }

    private void Initialize(float minValue, float maxValue, int seed)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Min value must be less than or equal to max value.");
        }

        this.minValue = minValue;
        this.maxValue = maxValue;
        minIntValue = Mathf.RoundToInt(minValue);
        maxIntValue = Mathf.RoundToInt(maxValue);
        this.seed = seed;
        random = new System.Random(seed);
        stopwatch = new Stopwatch();
        totalGeneratedNumbers = 0;
        startTime = Environment.TickCount;
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}], Seed: {seed}";
    }
}
