using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.IO;
using System.Net.Http;
using System.Threading;

public class HTTPRequestThrottler
{
    private int _minRequestsPerInterval = 10;
    private int _maxRequestsPerInterval = 100;
    private ConcurrentDictionary<string, DateTime> _requestCounts = new ConcurrentDictionary<string, DateTime>();
    private Random _random = new Random();
    private string _logFilePath = "request_log.txt";
    private bool _isBackupServerActive = false;

    public HTTPRequestThrottler()
    {
        InitializeSeeds(_random.Next());
    }

    public int GetAllowedRequestsPerInterval(DateTime currentTime)
    {
        return (int)(_maxRequestsPerInterval - (_minRequestsPerInterval * _random.NextDouble()));
    }

    public bool IsRequestAllowed(HttpRequest request)
    {
        string key = $"{request.RemoteIpAddress}-{request.SessionId}";
        if (!_requestCounts.TryGetValue(key, out DateTime lastRequestTime))
        {
            _requestCounts.TryAdd(key, currentTime);
            return true;
        }

        int allowedRequests = GetAllowedRequestsPerInterval(currentTime);
        int elapsedSeconds = (int)(currentTime - lastRequestTime).TotalSeconds;

        if (elapsedSeconds > 1)
        {
            _requestCounts[key] = currentTime;
            return true;
        }

        int remainingRequests = allowedRequests - elapsedSeconds * _minRequestsPerInterval;
        if (remainingRequests > 0)
        {
            _requestCounts[key] = currentTime;
            return true;
        }

        return false;
    }

    public void IncrementRequestCount(HttpRequest request)
    {
        string key = $"{request.RemoteIpAddress}-{request.SessionId}";
        _requestCounts.TryUpdate(key, DateTime.Now, key);
    }

    public void DecrementRequestCount(HttpRequest request)
    {
        string key = $"{request.RemoteIpAddress}-{request.SessionId}";
        _requestCounts.TryRemove(key, out _);
    }

    public static void InitializeSeeds(long seed)
    {
        new Random(seed).Next();
    }
}
