#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int *items;
    size_t head, tail, count, capacity;
    sem_t items_count, space_available;
    pthread_mutex_t mutex;
} thread_safe_queue;

void init_queue(thread_safe_queue *queue, size_t initial_capacity) {
    queue->items = (int *)malloc(initial_capacity * sizeof(int));
    if (!queue->items) {
        fprintf(stderr, "Failed to allocate memory for queue\n");
        exit(EXIT_FAILURE);
    }
    queue->head = queue->tail = queue->count = 0;
    queue->capacity = initial_capacity;
    sem_init(&queue->items_count, 0, 0);
    sem_init(&queue->space_available, 0, initial_capacity);
    pthread_mutex_init(&queue->mutex, NULL);
}

void destroy_queue(thread_safe_queue *queue) {
    free(queue->items);
    sem_destroy(&queue->items_count);
    sem_destroy(&queue->space_available);
    pthread_mutex_destroy(&queue->mutex);
}

void enqueue(thread_safe_queue *queue, int item) {
    sem_wait(&queue->space_available);
    pthread_mutex_lock(&queue->mutex);
    queue->items[queue->tail] = item;
    queue->tail = (queue->tail + 1) % queue->capacity;
    queue->count++;
    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->items_count);
}

int dequeue(thread_safe_queue *queue) {
    int item;
    sem_wait(&queue->items_count);
    pthread_mutex_lock(&queue->mutex);
    item = queue->items[queue->head];
    queue->head = (queue->head + 1) % queue->capacity;
    queue->count--;
    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->space_available);
    return item;
}

void resize_queue(thread_safe_queue *queue, size_t new_capacity) {
    sem_wait(&queue->space_available);
    pthread_mutex_lock(&queue->mutex);

    int *new_items = (int *)realloc(queue->items, new_capacity * sizeof(int));
    if (!new_items) {
        fprintf(stderr, "Failed to resize queue\n");
        exit(EXIT_FAILURE);
    }
    queue->items = new_items;
    size_t old_count = queue->count;
    for (size_t i = 0; i < old_count; ++i) {
        enqueue(queue, dequeue(queue));
    }

    queue->capacity = new_capacity;

    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->space_available);
}
