import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;

public class ServiceLifecycleManager {
    private static final Log log = LogFactory.getLog(ServiceLifecycleManager.class);
    private thread_safe_queue queue;
    private Thread serviceThread;

    public ServiceLifecycleManager(int initialCapacity) {
        this.queue = new thread_safe_queue();
        init_queue(this.queue, initial_capacity);
        startService();
    }

    public void startService() {
        if (serviceThread != null && serviceThread.isAlive()) return;
        serviceThread = new Thread(() -> {
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    Thread.sleep(1000 + (long) (Math.random() * 9000));
                    int item = queue.dequeue();
                    String md5Hash = generateMD5(item);
                    log.info("Service processed: " + item + ", MD5: " + md5Hash);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
        serviceThread.start();
    }

    public void stopService() {
        if (serviceThread != null && serviceThread.isAlive()) {
            serviceThread.interrupt();
            try {
                serviceThread.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private String generateMD5(int input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(String.valueOf(input).getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if(hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            log.error("Failed to generate MD5 hash", e);
            return null;
        }
    }

    public static void main(String[] args) {
        int initialCapacity = 10;
        ServiceLifecycleManager manager = new ServiceLifecycleManager(initialCapacity);

        // Simulate adding items to the queue
        for (int i = 0; i < 20; ++i) {
            enqueue(manager.queue, i);
        }

        try {
            Thread.sleep(60000); // Let the service run for a minute
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        manager.stopService();
    }
}
