#include <string.h>
#include <pthread.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *pm, size_t initial_capacity) {
    pm->packets = (DataPacket *)malloc(initial_capacity * sizeof(DataPacket));
    pm->capacity = initial_capacity;
    pm->size = 0;
    pthread_mutex_init(&pm->lock, NULL);
}

void destroy_packet_manager(PacketManager *pm) {
    free(pm->packets);
    pthread_mutex_destroy(&pm->lock);
}

int add_packet(PacketManager *pm, DataPacket packet) {
    pthread_mutex_lock(&pm->lock);
    if (pm->size >= pm->capacity) {
        size_t new_capacity = pm->capacity * 2;
        DataPacket *new_packets = (DataPacket *)realloc(pm->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) {
            pthread_mutex_unlock(&pm->lock);
            return -1; // Memory allocation failed
        }
        pm->packets = new_packets;
        pm->capacity = new_capacity;
    }
    for (size_t i = 0; i < pm->size; ++i) {
        if (pm->packets[i].packet_id == packet.packet_id) {
            pthread_mutex_unlock(&pm->lock);
            return -2; // Duplicate packet ID
        }
    }
    pm->packets[pm->size++] = packet;
    pthread_mutex_unlock(&pm->lock);
    return 0;
}

int remove_packet(PacketManager *pm, int packet_id) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->size; ++i) {
        if (pm->packets[i].packet_id == packet_id) {
            memmove(&pm->packets[i], &pm->packets[i + 1], (pm->size - i - 1) * sizeof(DataPacket));
            --pm->size;
            pthread_mutex_unlock(&pm->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&pm->lock);
    return -3; // Packet not found
}

size_t get_packet_count(PacketManager *pm) {
    pthread_mutex_lock(&pm->lock);
    size_t count = pm->size;
    pthread_mutex_unlock(&pm->lock);
    return count;
}

int sort_packets_by_timestamp(PacketManager *pm) {
    pthread_mutex_lock(&pm->lock);
    qsort(pm->packets, pm->size, sizeof(DataPacket), [](const void *a, const void *b) {
        return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp;
    });
    pthread_mutex_unlock(&pm->lock);
    return 0;
}
