#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int session_id;
    char client_ip[16];
    int port;
    double session_duration;
    long data_transferred;
} NetworkSession;

typedef struct {
    NetworkSession* sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

SessionManager* create_session_manager(size_t initial_capacity) {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    manager->sessions = (NetworkSession*)malloc(initial_capacity * sizeof(NetworkSession));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void add_session(SessionManager* manager, NetworkSession session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        manager->sessions = realloc(manager->sessions, 2 * manager->capacity * sizeof(NetworkSession));
        manager->capacity *= 2;
    }
    manager->sessions[manager->count++] = session;
    pthread_mutex_unlock(&manager->lock);
}

void remove_session(SessionManager* manager, int session_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].session_id == session_id) {
            for (size_t j = i; j < manager->count - 1; ++j) {
                manager->sessions[j] = manager->sessions[j + 1];
            }
            --manager->count;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

size_t get_active_sessions(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);
    size_t count = manager->count;
    pthread_mutex_unlock(&manager->lock);
    return count;
}

double calculate_average_data_transferred(SessionManager* manager, double time_window) {
    pthread_mutex_lock(&manager->lock);
    double total_data = 0.0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].session_duration > time_window) {
            total_data += manager->sessions[i].data_transferred;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return total_data / manager->count;
}

void destroy_session_manager(SessionManager* manager) {
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
