import hashlib

def calculate_md5_large_file(file_path):
    hasher = hashlib.md5()
    chunk_size = 4096  # Define a reasonable chunk size
    retries = 3  # Number of retry attempts for failed reads

    with open(file_path, 'rb') as file:
        while True:
            data = None
            try:
                data = file.read(chunk_size)
                if not data:
                    break  # End of file reached
                hasher.update(data)
            except IOError as e:
                print(f"IOError occurred: {e}")
                for _ in range(retries):
                    try:
                        data = file.read(chunk_size)
                        if not data:
                            break  # End of file reached
                        hasher.update(data)
                        break  # Successful read, exit retry loop
                    except IOError as e:
                        print(f"Retry failed: {e}")
                else:
                    raise  # Re-raise exception if all retries fail

    return hasher.hexdigest()
```

