        fprintf(stderr, "Failed to resolve DNS\n");
        exit(1);
    }
    memcpy(&dns_server.sin_addr, host_info->h_addr_list[0], host_info->h_length);
}

int add_packet(int packet_id, time_t timestamp, size_t payload_size) {
    pthread_mutex_lock(&lock);
    if (packet_count >= MAX_PACKETS) {
        pthread_mutex_unlock(&lock);
        return -1; // Packet array overflow
    }
    for (int i = 0; i < packet_count; i++) {
        if (packets[i].packet_id == packet_id) {
            pthread_mutex_unlock(&lock);
            return -2; // Duplicate packet ID
        }
    }
    packets[packet_count++] = (DataPacket){packet_id, timestamp, payload_size};
    pthread_mutex_unlock(&lock);
    return 0;
}

int remove_packet(int packet_id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < packet_count; i++) {
        if (packets[i].packet_id == packet_id) {
            memmove(&packets[i], &packets[i + 1], sizeof(DataPacket) * (packet_count - i - 1));
            packet_count--;
            pthread_mutex_unlock(&lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&lock);
    return -1; // Packet not found
}

int get_packet_count() {
    pthread_mutex_lock(&lock);
    int count = packet_count;
    pthread_mutex_unlock(&lock);
    return count;
}

void sort_packets_by_timestamp() {
    pthread_mutex_lock(&lock);
    qsort(packets, packet_count, sizeof(DataPacket), [](const void *a, const void *b) {
        return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp;
    });
    pthread_mutex_unlock(&lock);
}

int resolve_dns(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        if (inet_ntop(p->ai_family, &(ipv4->sin_addr), ip_address, INET_ADDRSTRLEN) == NULL) {
            perror("inet_ntop");
            return -1;
        }
    }

    freeaddrinfo(res);
    return 0;
}

void *dns_worker(void *arg) {
    const char *hostname = (const char *)arg;
    u_char ip_address[INET_ADDRSTRLEN];
    while (1) {
        if (resolve_dns(hostname, ip_address) == 0) {
            // Use the resolved IP address for further operations
            break;
        }
        sleep(5); // Retry after 5 seconds on failure
    }
    return NULL;
}

int main() {
    init_dns("example.com");

    pthread_t dns_thread;
    pthread_create(&dns_thread, NULL, dns_worker, "example.com");
    pthread_detach(dns_thread);

    add_packet(1, time(NULL), 1024);
    sort_packets_by_timestamp();
    printf("Packet count: %d\n", get_packet_count());

    return 0;
}
