#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int packet_id;
    int timestamp;
    int payload_size;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t capacity;
    size_t size;
    void (*log_packet_addition)(int);
    void (*log_packet_deletion)(int);
} PacketManager;

void init_packet_manager(PacketManager *manager, size_t initial_capacity, 
                         void (*log_packet_add)(int), void (*log_packet_del)(int)) {
    manager->packets = (DataPacket *)malloc(initial_capacity * sizeof(DataPacket));
    if (!manager->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->log_packet_addition = log_packet_add;
    manager->log_packet_deletion = log_packet_del;
}

void free_packet_manager(PacketManager *manager) {
    free(manager->packets);
}

int add_packet(PacketManager *manager, DataPacket packet) {
    if (manager->size >= manager->capacity) {
        manager->capacity *= 2;
        manager->packets = (DataPacket *)realloc(manager->packets, 
                                               manager->capacity * sizeof(DataPacket));
        if (!manager->packets) {
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }
    }

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->packets[i].packet_id == packet.packet_id) {
            // Handle duplicate packet ID
            printf("Duplicate packet ID detected, skipping addition\n");
            return -1;
        }
    }

    manager->packets[manager->size++] = packet;
    manager->log_packet_addition(packet.packet_id);
    return 0;
}

int remove_packet(PacketManager *manager, int packet_id) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->packets[i].packet_id == packet_id) {
            // Shift elements to fill the gap
            memmove(&manager->packets[i], &manager->packets[i + 1],
                    (manager->size - i - 1) * sizeof(DataPacket));
            manager->size--;
            manager->log_packet_deletion(packet_id);
            return 0;
        }
    }

    // Packet not found
    printf("Packet with ID %d not found for removal\n", packet_id);
    return -1;
}

size_t get_total_packets(const PacketManager *manager) {
    return manager->size;
}

void sort_packets_by_timestamp(PacketManager *manager) {
    qsort(manager->packets, manager->size, sizeof(DataPacket), 
          (int (*)(const void *, const void *))compare_packets);
}

int compare_packets(const void *a, const void *b) {
    DataPacket *packet_a = (DataPacket *)a;
    DataPacket *packet_b = (DataPacket *)b;
    return packet_a->timestamp - packet_b->timestamp;
}
