#define MAX_PACKETS 10000000
#define LOCAL_STORAGE_THRESHOLD 1000

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket *data[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
    u_char local_storage[LOCAL_STORAGE_THRESHOLD][INET_ADDRSTRLEN];
    int local_count;
    pthread_mutex_t local_lock;
} PacketManager;

void init_packet_manager(PacketManager *pm) {
    memset(pm, 0, sizeof(*pm));
    pthread_mutex_init(&pm->lock, NULL);
    pthread_mutex_init(&pm->local_lock, NULL);
}

int add_packet(PacketManager *pm, DataPacket packet) {
    pthread_mutex_lock(&pm->lock);
    if (pm->count >= MAX_PACKETS) {
        pthread_mutex_unlock(&pm->lock);
        return -1; // Error: Too many packets
    }
    pm->data[pm->count++] = &packet;
    pthread_mutex_unlock(&pm->lock);
    return 0;
}

int remove_packet(PacketManager *pm, int packet_id) {
    pthread_mutex_lock(&pm->lock);
    for (int i = 0; i < pm->count; i++) {
        if (pm->data[i]->packet_id == packet_id) {
            memmove(pm->data + i, pm->data + i + 1, sizeof(DataPacket*) * (pm->count - i - 1));
            pm->count--;
            pthread_mutex_unlock(&pm->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&pm->lock);
    return -1; // Error: Packet not found
}

int get_packet_count(PacketManager *pm) {
    int count;
    pthread_mutex_lock(&pm->lock);
    count = pm->count;
    pthread_mutex_unlock(&pm->lock);
    return count;
}

int sort_packets_by_timestamp(PacketManager *pm) {
    pthread_mutex_lock(&pm->lock);
    qsort(pm->data, pm->count, sizeof(DataPacket*), [](const void *a, const void *b) {
        return ((DataPacket*)a)->timestamp - ((DataPacket*)b)->timestamp;
    });
    pthread_mutex_unlock(&pm->lock);
    return 0;
}

int resolve_dns(const char *hostname, u_char *ip_addr) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        inet_ntop(AF_INET, &(ipv4->sin_addr), ip_addr, INET_ADDRSTRLEN);
        freeaddrinfo(res);
        return 0;
    }

    fprintf(stderr, "No valid IP address found for %s\n", hostname);
    freeaddrinfo(res);
    return -1;
}

