    for (int i = 0; i < lib->packet_count; i++) {
        if (lib->packets[i].packet_id == packet_id) {
            memmove(&lib->packets[i], &lib->packets[i + 1], sizeof(DataPacket) * (lib->packet_count - i - 1));
            lib->packet_count--;
            break;
        }
    }
    pthread_mutex_unlock(&lib->lock);
}

int get_packet_count(CryptoLibrary *lib) {
    int count;
    pthread_mutex_lock(&lib->lock);
    count = lib->packet_count;
    pthread_mutex_unlock(&lib->lock);
    return count;
