using System;
using System.Collections.Generic;

public class RandomNumberGeneratorUtility
{
    private Dictionary<string, Random> _generators;

    public RandomNumberGeneratorUtility()
    {
        _generators = new Dictionary<string, Random>();
    }

    // Create a new random generator with the specified name and seed
    public void AddGenerator(string name, int seed = 0)
    {
        if (!_generators.ContainsKey(name))
        {
            _generators[name] = new Random(seed);
        }
    }

    // Generate a random integer within the specified range [min, max]
    public int GetRandomInteger(string name, int min, int max)
    {
        if (_generators.TryGetValue(name, out var generator) && min <= max)
        {
            return generator.Next(min, max + 1);
        }
        throw new ArgumentException("Invalid range or generator not found.");
    }

    // Generate a random float within the specified range [min, max]
    public float GetRandomFloat(string name, float min, float max)
    {
        if (_generators.TryGetValue(name, out var generator) && min <= max)
        {
            return (float)(generator.NextDouble() * (max - min)) + min;
        }
        throw new ArgumentException("Invalid range or generator not found.");
    }

    // Reset the seed of a specific random generator
    public void ResetGenerator(string name, int seed = 0)
    {
        if (_generators.ContainsKey(name))
        {
            _generators[name] = new Random(seed);
        }
        else
        {
            throw new ArgumentException("Generator not found.");
        }
    }

    // Remove a specific random generator
    public void RemoveGenerator(string name)
    {
        if (_generators.ContainsKey(name))
        {
            _generators.Remove(name);
        }
    }
}
