    time_t timestamp;
    status_code status;
} request_record;

size_t* request_times = NULL;
time_t* timestamps = NULL;
request_record** records = NULL;

int process_urls(char** urls, int url_count) {
    size_t allocated_requests = 0;
    int concurrent_requests = 0;

    for (int i = 0; i < url_count; ++i) {
        // Implement HTTP request logic here
        // For demonstration, assume the following:
        time_t start_time = time(NULL);
        status_code status = STATUS_OK;

        if (concurrent_requests >= allocated_requests) {
            if (allocated_requests == MAX_REQUESTS) {
                fprintf(stderr, "Error: Maximum number of concurrent requests reached.\n");
                return -1;
            }
            size_t* new_request_times = realloc(request_times, (allocated_requests + 1) * sizeof(size_t));
            time_t* new_timestamps = realloc(timestamps, (allocated_requests + 1) * sizeof(time_t));
            request_record** new_records = realloc(records, (allocated_requests + 1) * sizeof(request_record*));

            if (!new_request_times || !new_timestamps || !new_records) {
                fprintf(stderr, "Error: Memory allocation failed.\n");
                return -1;
            }

            request_times = new_request_times;
            timestamps = new_timestamps;
            records = new_records;
            allocated_requests++;
        }

        concurrent_requests++;
        if (concurrent_requests > MAX_REQUESTS / 2) {
            // Implement heuristic to adjust maximum number of concurrent requests
            // For demonstration, assume the following:
            concurrent_requests = MAX_REQUESTS - concurrent_requests;
        }

        size_t elapsed_time = time(NULL) - start_time;
        request_times[allocated_requests - 1] = elapsed_time;

        time_t now = time(NULL);
        timestamps[allocated_requests - 1] = now;

        records[allocated_requests - 1] = malloc(sizeof(request_record));
        if (!records[allocated_requests - 1]) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return -1;
        }

        records[allocated_requests - 1]->timestamp = now;
        records[allocated_requests - 1]->status = status;

        // Log error to file
        if (status != STATUS_OK) {
            FILE* log_file = fopen("error_log.txt", "a");
            if (log_file) {
                fprintf(log_file, "Error at %s: %d\n", ctime(&now), status);
                fclose(log_file);
            }
        }

        // Simulate releasing a concurrent request
        concurrent_requests--;
    }

    return 0;
}
