typedef struct {
    LTEPHY_FDD_CONFIG_S *configs;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} ConfigManager;

ConfigManager* config_manager_init(size_t initial_capacity) {
    ConfigManager *manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    if (!manager) return NULL;

    manager->count = 0;
    manager->capacity = initial_capacity > 10000 ? initial_capacity : 10000;
    manager->configs = (LTEPHY_FDD_CONFIG_S*)malloc(manager->capacity * sizeof(LTEPHY_FDD_CONFIG_S));
    if (!manager->configs) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void config_manager_free(ConfigManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->mutex);
        free(manager->configs);
        free(manager);
    }
}

int config_manager_add(ConfigManager *manager, LTEPHY_FDD_CONFIG_S config) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        void *new_configs = realloc(manager->configs, new_capacity * sizeof(LTEPHY_FDD_CONFIG_S));
        if (!new_configs) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Allocation failed
        }
        manager->configs = (LTEPHY_FDD_CONFIG_S*)new_configs;
        manager->capacity = new_capacity;
    }
    manager->configs[manager->count++] = config;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

