#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LINE_LENGTH 1024

void print_usage() {
    printf("Usage: program_name [options] input_file\n");
    printf("Options:\n");
    printf("  --manpage   Print manual page and exit.\n");
    printf("  -cs        Skip comment lines.\n");
    printf("  -o output_file Specify output file.\n");
}

void parse_command_line(int argc, char *argv[], char **input_file, int *skip_comments, const char **output_file) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            print_usage();
            exit(0);
        } else if (strcmp(argv[i], "-cs") == 0) {
            *skip_comments = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            *output_file = argv[++i];
        } else if (*input_file == NULL) {
            *input_file = argv[i];
        }
    }
}

void process_file(const char *input_file, const char *output_file, int skip_comments) {
    FILE *in = fopen(input_file, "r");
    if (in == NULL) {
        perror("Error opening input file");
        return;
    }

    if (output_file != NULL) {
        FILE *out = fopen(output_file, "w");
        if (out == NULL) {
            perror("Error opening output file");
            fclose(in);
            return;
        }
    }

    char line[MAX_LINE_LENGTH];
    int line_count = 0;

    while (fgets(line, MAX_LINE_LENGTH, in)) {
        if (!skip_comments || !strchr(line, '#')) { // Assuming '#' as the comment delimiter
            printf("%s", line);
            line_count++;
            if (output_file != NULL) {
                fputs(line, out);
            }
        }
    }

    fclose(in);
    if (output_file != NULL) {
        fclose(out);
    }

    printf("Processed %d lines from file: %s\n", line_count, input_file);
}

int main(int argc, char *argv[]) {
    const char *input_file = NULL;
    int skip_comments = 0;
    const char *output_file = NULL;

    parse_command_line(argc, argv, &input_file, &skip_comments, &output_file);

    if (input_file == NULL) {
        print_usage();
        return 1;
    }

    process_file(input_file, output_file, skip_comments);
    return 0;
}
