typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct Node {
    DataPacket packet;
    struct Node* next;
} Node;

Node* head = NULL;
size_t packet_count = 0;

void add_packet(DataPacket packet) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->packet = packet;
    new_node->next = head;
    head = new_node;
    packet_count++;
}

void remove_packet(int packet_id) {
    Node* current = head;
    Node* previous = NULL;

    while (current != NULL && current->packet.packet_id != packet_id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return; // Packet not found

    if (previous == NULL) {
        head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    packet_count--;
}

size_t get_packet_count() {
    return packet_count;
}

void sort_packets_by_timestamp() {
    // Implement sorting algorithm, e.g., quicksort
}

