import subprocess
import os
import hashlib
import json

def execute_command(command):
    try:
        result = subprocess.run(command, shell=True, check=True, text=True)
        return result.stdout.strip()
    except subprocess.CalledProcessError as e:
        print(f"Command execution failed: {e}")
        raise

def calculate_checksum(file_path):
    with open(file_path, 'rb') as file:
        checksum = hashlib.md5(file.read()).hexdigest()
    return checksum

def validate_parameters(params):
    for key, value in params.items():
        if key == 'IP_ADDRESS':
            # Simple IP address validation
            if not re.match(r'^(\d{1,3}\.){3}\d{1,3}$', value):
                raise ValueError(f"Invalid IP address: {value}")
        elif key == 'PORT_NUMBER':
            # Port number validation
            port = int(value)
            if not (0 <= port <= 65535):
                raise ValueError(f"Invalid port number: {port}")

def backup_configuration(file_path, backup_dir='backups'):
    if not os.path.exists(backup_dir):
        os.makedirs(backup_dir)
    backup_path = os.path.join(backup_dir, f"{os.path.basename(file_path)}_{time.time()}")
    shutil.copy(file_path, backup_path)

def restore_configuration(file_path, backup_file):
    try:
        shutil.copy(backup_file, file_path)
    except Exception as e:
        print(f"Failed to restore configuration: {e}")

def configure_network(files, params):
    validate_parameters(params)
    for file_name in files:
        with open(file_name, 'r') as file:
            template_content = file.read()

        updated_content = template_content
        for key, value in params.items():
            updated_content = updated_content.replace(f"${{{key}}}", value)

        backup_configuration(file_name)
        with open(file_name, 'w') as file:
            file.write(updated_content)

        checksum_before = calculate_checksum(file_name)
        execute_command(f"sudo bash apply_config.sh {file_name}")
        checksum_after = calculate_checksum(file_name)

        if checksum_before != checksum_after:
            raise Exception("Checksum mismatch after applying configuration changes.")

    print("Configuration applied successfully.")

# Example usage
files = ['config1.txt', 'config2.conf']
params = {
    'IP_ADDRESS': '192.168.1.1',
    'PORT_NUMBER': '8080'
}
configure_network(files, params)
```

