using System;
using System.IO;
using System.Collections.Generic;

public class DataAndSecurityHandler
{
    private long minValue = 0;
    private long maxValue = 0;

    public DataAndSecurityHandler()
        : this(0, 0) { }

    public DataAndSecurityHandler(long minValue, long maxValue)
    {
        if (minValue > maxValue)
        {
            Console.WriteLine("Warning: minValue is greater than maxValue. Setting minValue to maxValue - 1.");
            minValue = maxValue - 1;
        }
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GetRandomFloat()
    {
        return (float)(minValue + Math.random() * (maxValue - minValue + 1));
    }

    public int GetRandomInt()
    {
        return (int)(minValue + Math.random() * (maxValue - minValue + 1));
    }

    public int GetRandomExclInt()
    {
        if (minValue == maxValue)
            return (int)minValue;
        return (int)(minValue + 1 + Math.random() * (maxValue - minValue - 1));
    }

    private HashSet<int> SampleUniqueValues(int count)
    {
        HashSet<int> uniqueValues = new HashSet<int>();
        Random rand = new Random();
        while (uniqueValues.Count < count && uniqueValues.Count < (int)(maxValue - minValue + 1))
        {
            int value = minValue + rand.Next((int)(maxValue - minValue + 1));
            uniqueValues.Add(value);
        }
        if (uniqueValues.Count < count)
        {
            Console.WriteLine("Error: Not enough unique values in the range.");
        }
        return uniqueValues;
    }

    public void FillArrayWithUniqueValues(int[] array, int count)
    {
        if (array.Length < count)
        {
            Console.WriteLine("Error: Array is too small to hold all unique values.");
            return;
        }
        HashSet<int> uniqueValues = SampleUniqueValues(count);
        uniqueValues.CopyTo(array);
    }

    public List<string> GenerateRandomStrings(int count, int length)
    {
        List<string> randomStrings = new List<string>();
        Random rand = new Random();
        for (int i = 0; i < count; i++)
        {
            string randomString = new string(Enumerable.Repeat("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ", length)
                .Select(s => s[rand.Next(s.Length)]).ToArray());
            randomStrings.Add(randomString);
        }
        return randomStrings;
    }

    public int GetRandomWeightedValue(double[] weights)
    {
        double totalWeight = 0.0;
        for (int i = 0; i < weights.Length; i++)
        {
            totalWeight += weights[i];
        }
        double randomValue = totalWeight * Math.random();
        double currentSum = 0.0;
        for (int i = 0; i < weights.Length; i++)
        {
            currentSum += weights[i];
            if (randomValue <= currentSum)
                return i;
        }
        Console.WriteLine("Error: Invalid input or random value generation error.");
        return -1;
    }

    public void PersistRecordsToDisk(string filePath, record[] records)
    {
        try
        {
            using (StreamWriter writer = new StreamWriter(filePath))
            {
                foreach (record rec in records)
                {
                    writer.WriteLine(rec.value);
                }
            }
        }
        catch (IOException ex)
        {
            Console.WriteLine("I/O Error: " + ex.Message);
        }
    }
}

public struct record
{
    public int value;
}
```

