using System;
using System.Collections.Generic;

public class DataAndSecurityHandler
{
    private long[] offsetValues;
    private int[] keyValues;
    private record MyRecord(int value);
    private Random random = new Random();
    private readonly int minValue;
    private readonly int maxValue;

    public DataAndSecurityHandler() : this(0, 1)
    {
    }

    public DataAndSecurityHandler(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            Console.WriteLine("Warning: minValue is greater than maxValue. Setting minValue to maxValue - 1.");
            minValue = maxValue - 1;
        }
        this.minValue = minValue;
        this.maxValue = maxValue;

        offsetValues = new long[100];
        keyValues = new int[100];

        for (int i = 0; i < offsetValues.Length; i++)
        {
            offsetValues[i] = GetRandomLongOffset();
        }

        for (int i = 0; i < keyValues.Length; i++)
        {
            keyValues[i] = GetRandomIntKey();
        }
    }

    public float GetRandomFloat()
    {
        return minValue + (float)(random.NextDouble() * (maxValue - minValue));
    }

    public int GetRandomInt()
    {
        return minValue + random.Next(maxValue - minValue + 1);
    }

    public int GetRandomIntExclusive()
    {
        if (minValue == maxValue)
            return maxValue;

        return minValue + random.Next(maxValue - minValue);
    }

    private long GetRandomLongOffset()
    {
        // Implement logic to generate a random long offset
        return (long)random.Next();
    }

    private int GetRandomIntKey()
    {
        // Implement logic to generate a random key value
        return random.Next();
    }

    public MyRecord[] PopulateRecords(int count)
    {
        if (count > 100000)
            throw new ArgumentException("Cannot populate more than 100,000 records.");

        MyRecord[] records = new MyRecord[count];
        for (int i = 0; i < count; i++)
        {
            records[i] = new MyRecord(GetRandomInt());
        }

        return records;
    }

    public void PersistRecordsToFile(MyRecord[] records, string filePath)
    {
        try
        {
            // Implement logic to persist records to disk in a specified file format
            using (var writer = new System.IO.StreamWriter(filePath))
            {
                foreach (var record in records)
                {
                    writer.WriteLine(record.value);
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }

    public int[] SampleUniqueValues(int count)
    {
        if (count > maxValue - minValue + 1)
        {
            Console.Error.WriteLine("Error: Not enough unique values in the range.");
            return new int[0];
        }

        HashSet<int> sampled = new HashSet<int>();
        while (sampled.Count < count)
        {
            int value = GetRandomInt();
            if (!sampled.Contains(value))
                sampled.Add(value);
        }

        return sampled.ToArray();
    }

    public void FillArrayWithUniqueValues(int[] array, int count)
    {
        if (count > array.Length)
        {
            Console.Error.WriteLine("Error: Array is too small to hold all unique values.");
            return;
        }

        HashSet<int> filled = new HashSet<int>();
        int index = 0;
        while (filled.Count < count)
        {
            int value = GetRandomInt();
            if (!filled.Contains(value))
            {
                array[index++] = value;
                filled.Add(value);
            }
        }
    }

    public List<string> GenerateRandomStrings(int count, int length)
    {
        List<string> strings = new List<string>();
        for (int i = 0; i < count; i++)
        {
            strings.Add(GenerateRandomString(length));
        }
        return strings;
    }

    private string GenerateRandomString(int length)
    {
        const string chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
        return new string(Enumerable.Repeat(chars, length)
                                  .Select(s => s[random.Next(s.Length)]).ToArray());
    }

    public int GetRandomWeightedValue(double[] weights)
    {
        if (weights == null || weights.Length == 0)
            throw new ArgumentException("Weights array cannot be empty.");

        double sum = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            sum += weights[i];
        }

        double rand = random.NextDouble() * sum;
        for (int i = 0; i < weights.Length; i++)
        {
            if (rand < weights[i])
                return i;
            rand -= weights[i];
        }

        throw new InvalidOperationException("Failed to select a weighted value.");
    }
}
