import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class StreamingDataProcessor {

    private ExecutorService ingestionExecutor;
    private ExecutorService transformationExecutor;
    private ExecutorService storageExecutor;
    private MetricsManager metricsManager;

    public StreamingDataProcessor() {
        this.ingestionExecutor = Executors.newFixedThreadPool(10);
        this.transformationExecutor = Executors.newCachedThreadPool();
        this.storageExecutor = Executors.newSingleThreadExecutor();
        this.metricsManager = new MetricsManager();
    }

    public void startProcessing() {
        // Start data ingestion threads
        for (int i = 0; i < 5; i++) {
            ingestionExecutor.submit(new DataIngestor(metricsManager));
        }

        // Start transformation threads
        for (int i = 0; i < 3; i++) {
            transformationExecutor.submit(new DataTransformer(metricsManager));
        }

        // Start storage thread
        storageExecutor.submit(new DataStorer(metricsManager));

        // Start metrics reporting thread
        new Thread(metricsManager).start();
    }

    public void stopProcessing() {
        ingestionExecutor.shutdown();
        transformationExecutor.shutdown();
        storageExecutor.shutdown();

        try {
            ingestionExecutor.awaitTermination(5, TimeUnit.SECONDS);
            transformationExecutor.awaitTermination(5, TimeUnit.SECONDS);
            storageExecutor.awaitTermination(5, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        metricsManager.stop();
    }

    public static void main(String[] args) {
        StreamingDataProcessor processor = new StreamingDataProcessor();
        processor.startProcessing();

        // Simulate running for 10 minutes
        try {
            TimeUnit.MINUTES.sleep(10);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        processor.stopProcessing();
    }
}

class DataIngestor implements Runnable {
    private MetricsManager metricsManager;

    public DataIngestor(MetricsManager metricsManager) {
        this.metricsManager = metricsManager;
    }

    @Override
    public void run() {
        while (true) {
            // Simulate data ingestion
            metricsManager.incrementMetric("ingestedDataSize", 1024 * 1024); // 1 MB

            try {
                Thread.sleep(10); // Simulate processing time
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}

class DataTransformer implements Runnable {
    private MetricsManager metricsManager;

    public DataTransformer(MetricsManager metricsManager) {
        this.metricsManager = metricsManager;
    }

    @Override
    public void run() {
        while (true) {
            // Simulate data transformation
            metricsManager.incrementMetric("transformedDataSize", 1024 * 512); // 512 KB

            try {
                Thread.sleep(10); // Simulate processing time
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}

class DataStorer implements Runnable {
    private MetricsManager metricsManager;

    public DataStorer(MetricsManager metricsManager) {
        this.metricsManager = metricsManager;
    }

    @Override
    public void run() {
        while (true) {
            // Simulate data storage
            metricsManager.incrementMetric("storedDataSize", 1024 * 512); // 512 KB

            try {
                Thread.sleep(10); // Simulate processing time
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}

class MetricsManager implements Runnable {
    private volatile boolean running = true;
    private long ingestedDataSize = 0;
    private long transformedDataSize = 0;
    private long storedDataSize = 0;

    @Override
    public void run() {
        while (running) {
            System.out.println("Metrics: Ingested - " + ingestedDataSize + " bytes, Transformed - " + transformedDataSize + " bytes, Stored - " + storedDataSize + " bytes");
            try {
                Thread.sleep(1000); // Report every second
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public void incrementMetric(String metricName, long value) {
        if ("ingestedDataSize".equals(metricName)) {
            ingestedDataSize += value;
        } else if ("transformedDataSize".equals(metricName)) {
            transformedDataSize += value;
        } else if ("storedDataSize".equals(metricName)) {
            storedDataSize += value;
        }
    }

    public void stop() {
        running = false;
    }
}
