using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json;

public class Record
{
    public int Value { get; set; }
}

public class DataHandler
{
    private List<Record> _records = new List<Record>();

    public void PopulateRecords(int count, int min, int max)
    {
        _records.Clear();
        for (int i = 0; i < count; i++)
        {
            var record = new Record { Value = RandomNumberGenerator.Next(min, max + 1) };
            _records.Add(record);
        }
    }

    public void SaveToDisk(string filePath, string format)
    {
        switch (format.ToLower())
        {
            case "json":
                File.WriteAllText(filePath, JsonConvert.SerializeObject(_records));
                break;
            case "csv":
                using (var writer = new StreamWriter(filePath))
                {
                    foreach (var record in _records)
                    {
                        writer.WriteLine(record.Value);
                    }
                }
                break;
            default:
                throw new ArgumentException("Unsupported file format");
        }
    }

    public void LoadFromDisk(string filePath, string format)
    {
        switch (format.ToLower())
        {
            case "json":
                var json = File.ReadAllText(filePath);
                _records = JsonConvert.DeserializeObject<List<Record>>(json);
                break;
            case "csv":
                using (var reader = new StreamReader(filePath))
                {
                    _records.Clear();
                    while (!reader.EndOfStream)
                    {
                        var line = reader.ReadLine();
                        if (int.TryParse(line, out int value))
                        {
                            _records.Add(new Record { Value = value });
                        }
                    }
                }
                break;
            default:
                throw new ArgumentException("Unsupported file format");
        }
    }

    // Additional methods as per the task requirements
}
