using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

public class FileProcessingManager
{
    private readonly string _filePath;
    private readonly object _lockObject = new object();

    public FileProcessingManager(string filePath)
    {
        if (string.IsNullOrEmpty(filePath))
        {
            throw new ArgumentException("File path cannot be null or empty.", nameof(filePath));
        }
        _filePath = filePath;
    }

    public async Task<List<string>> ReadLinesAsync()
    {
        List<string> lines = new List<string>();
        using (var reader = File.OpenText(_filePath))
        {
            string line;
            while ((line = await reader.ReadLineAsync()) != null)
            {
                lines.Add(line);
            }
        }
        return lines;
    }

    public async Task WriteLinesAsync(IEnumerable<string> lines)
    {
        try
        {
            lock (_lockObject)
            {
                using (var writer = File.CreateText(_filePath))
                {
                    foreach (var line in lines)
                    {
                        await writer.WriteLineAsync(line);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error writing to file: {ex.Message}");
        }
    }

    public async Task AppendLinesAsync(IEnumerable<string> lines)
    {
        try
        {
            lock (_lockObject)
            {
                using (var writer = File.AppendText(_filePath))
                {
                    foreach (var line in lines)
                    {
                        await writer.WriteLineAsync(line);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error appending to file: {ex.Message}");
        }
    }

    public async Task<int> GetLineCountAsync()
    {
        int count = 0;
        using (var reader = File.OpenText(_filePath))
        {
            while (!reader.EndOfStream)
            {
                await reader.ReadLineAsync();
                count++;
            }
        }
        return count;
    }

    public async Task<List<int>> SearchForPatternAsync(string pattern)
    {
        List<int> lineNumbers = new List<int>();
        using (var reader = File.OpenText(_filePath))
        {
            int lineNumber = 0;
            string line;
            while ((line = await reader.ReadLineAsync()) != null)
            {
                lineNumber++;
                if (line.Contains(pattern))
                {
                    lineNumbers.Add(lineNumber);
                }
            }
        }
        return lineNumbers;
    }

    public async Task ReplaceInFileAsync(string searchPattern, string replacePattern)
    {
        try
        {
            string tempFilePath = Path.GetTempFileName();
            using (var reader = File.OpenText(_filePath))
            using (var writer = File.CreateText(tempFilePath))
            {
                while (!reader.EndOfStream)
                {
                    string line = await reader.ReadLineAsync();
                    line = line.Replace(searchPattern, replacePattern);
                    await writer.WriteLineAsync(line);
                }
            }

            File.Delete(_filePath);
            File.Move(tempFilePath, _filePath);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error replacing in file: {ex.Message}");
        }
    }
}
