    public void CreateUser(string userId, string userData)
    {
        if (userAccounts.ContainsKey(userId))
        {
            throw new Exception("User account already exists.");
        }
        ValidateData(userData);
        userAccounts[userId] = ApplyTransformations(userData);
        Save();
    }

    public void UpdateUser(string userId, string userData)
    {
        if (!userAccounts.ContainsKey(userId))
        {
            throw new Exception("User account does not exist.");
        }
        ValidateData(userData);
        userAccounts[userId] = ApplyTransformations(userData);
        Save();
    }

    public void DeleteUser(string userId)
    {
        if (userAccounts.ContainsKey(userId))
        {
            userAccounts.Remove(userId);
            Save();
        }
        else
        {
            throw new Exception("User account does not exist.");
        }
    }

