#define MAX_RESOURCE_REQUIREMENTS 100

typedef struct {
    int task_id;
    int user_id;
    int priority;
    int deadline;
    char status[MAX_STATUS];
    char resource_requirements[MAX_RESOURCE_REQUIREMENTS];
} UserTask;

typedef struct {
    UserTask tasks[MAX_TASKS];
    int count;
    pthread_mutex_t lock;
} TaskManager;

void init_task_manager(TaskManager *tm) {
    memset(tm, 0, sizeof(*tm));
    pthread_mutex_init(&tm->lock, NULL);
}

void add_task(TaskManager *tm, int task_id, int user_id, int priority, int deadline, const char *status, const char *resource_requirements) {
    pthread_mutex_lock(&tm->lock);
    if (tm->count < MAX_TASKS) {
        tm->tasks[tm->count].task_id = task_id;
        tm->tasks[tm->count].user_id = user_id;
        tm->tasks[tm->count].priority = priority;
        tm->tasks[tm->count].deadline = deadline;
        strncpy(tm->tasks[tm->count].status, status, MAX_STATUS);
        strncpy(tm->tasks[tm->count].resource_requirements, resource_requirements, MAX_RESOURCE_REQUIREMENTS);
        tm->count++;
    }
    pthread_mutex_unlock(&tm->lock);
}

void update_task_status(TaskManager *tm, int task_id, const char *new_status) {
    pthread_mutex_lock(&tm->lock);
    for (int i = 0; i < tm->count; i++) {
        if (tm->tasks[i].task_id == task_id) {
            strncpy(tm->tasks[i].status, new_status, MAX_STATUS);
            break;
        }
    }
    pthread_mutex_unlock(&tm->lock);
}

int get_pending_task_count(TaskManager *tm) {
    int count = 0;
    pthread_mutex_lock(&tm->lock);
    for (int i = 0; i < tm->count; i++) {
        if (strcmp(tm->tasks[i].status, "pending") == 0) {
            count++;
        }
    }
    pthread_mutex_unlock(&tm->lock);
    return count;
}

// Implement additional features like average resource utilization, serialization,
// deserialization, logging with rotation, monitoring module, and thread safety as per requirements.
