// C module for thread-safe, fixed-capacity queue

#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int *items;
    size_t capacity;
    size_t front;
    size_t rear;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} FixedCapacityQueue;

FixedCapacityQueue* queue_create(size_t capacity) {
    FixedCapacityQueue *queue = (FixedCapacityQueue*)malloc(sizeof(FixedCapacityQueue));
    queue->items = (int*)calloc(capacity, sizeof(int));
    queue->capacity = capacity;
    queue->front = 0;
    queue->rear = -1;
    queue->count = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    return queue;
}

void enqueue(FixedCapacityQueue *queue, int item) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->count == queue->capacity) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }
    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->items[queue->rear] = item;
    queue->count++;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->mutex);
}

int dequeue(FixedCapacityQueue *queue) {
    int item;
    pthread_mutex_lock(&queue->mutex);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }
    item = queue->items[queue->front];
    queue->front = (queue->front + 1) % queue->capacity;
    queue->count--;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->mutex);
    return item;
}

void queue_destroy(FixedCapacityQueue *queue) {
    free(queue->items);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->not_empty);
    pthread_cond_destroy(&queue->not_full);
    free(queue);
}
