// Java class for service manager

import java.util.concurrent.atomic.AtomicBoolean;
import java.util.Random;

public class ServiceManager {
    private final FixedCapacityQueue<Integer> queue;
    private final AtomicBoolean running = new AtomicBoolean(false);
    private final Random random = new Random();

    public ServiceManager(FixedCapacityQueue<Integer> queue) {
        this.queue = queue;
    }

    public void startService() {
        if (running.compareAndSet(false, true)) {
            Thread serviceThread = new Thread(() -> {
                while (running.get()) {
                    try {
                        int delay = random.nextInt(1000); // Random delay between 0 and 999 ms
                        Thread.sleep(delay);
                        queue.enqueue(1); // Simulate resource-intensive task
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        break;
                    }
                }
            });
            serviceThread.start();
        }
    }

    public void stopService() {
        running.set(false);
    }

    public void monitorQueueState() {
        while (true) {
            try {
                System.out.println("Queue size: " + queue.count());
                Thread.sleep(1000); // Monitor every second
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    public static void main(String[] args) {
        FixedCapacityQueue<Integer> queue = new FixedCapacityQueue<>(10);
        ServiceManager manager = new ServiceManager(queue);

        Thread monitorThread = new Thread(() -> manager.monitorQueueState());
        monitorThread.start();

        manager.startService();
    }
}
