import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.io.*;
import java.security.*;
import java.security.spec.PKCS8EncodedKeySpec;

public class MoSTStateLoader {

    public static MoSTState deserializeAndDecryptMoSTState(byte[] encryptedPayload, String password) {
        try {
            // Generate a secure random IV
            SecureRandom sr = new SecureRandom();
            byte[] iv = new byte[16];
            sr.nextBytes(iv);
            IvParameterSpec ivspec = new IvParameterSpec(iv);

            // Derive the AES key from the password using PBKDF2
            byte[] salt = new byte[16]; // Generate a random salt
            sr.nextBytes(salt);
            SecretKeySpec secretKey = generateAESKeyFromPassword(password, salt, 100000);

            // Initialize the cipher for decryption
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            cipher.init(Cipher.DECRYPT_MODE, secretKey, ivspec);

            // Decrypt the payload
            byte[] decryptedPayload = cipher.doFinal(encryptedPayload);

            // Deserialize the object from the decrypted payload
            ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(decryptedPayload));
            try {
                return (MoSTState) ois.readObject();
            } catch (ClassNotFoundException e) {
                ois.close();
                return null;
            }
        } catch (IOException | NoSuchAlgorithmException | InvalidKeySpecException | InvalidAlgorithmParameterException | IllegalBlockSizeException | BadPaddingException e) {
            throw new RuntimeException("Failed to deserialize and decrypt payload", e);
        }
    }

    private static SecretKeySpec generateAESKeyFromPassword(String password, byte[] salt, int iterationCount) throws NoSuchAlgorithmException {
        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(256, SecureRandom.getInstanceStrong());
        SecretKey secretKey = keyGen.generateKey();
        return new SecretKeySpec(secretKey.getEncoded(), "AES");
    }
}
