typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t count;
    size_t capacity;
} DynamicDataManager;

DynamicDataManager* createManager() {
    DynamicDataManager* manager = (DynamicDataManager*)malloc(sizeof(DynamicDataManager));
    manager->packets = NULL;
    manager->count = 0;
    manager->capacity = 1024; // Initial capacity
    manager->packets = (DataPacket*)realloc(manager->packets, manager->capacity * sizeof(DataPacket));
    return manager;
}

void destroyManager(DynamicDataManager* manager) {
    free(manager->packets);
    free(manager);
}

int addPacket(DynamicDataManager* manager, DataPacket packet) {
    if (manager->count >= manager->capacity) {
        manager->capacity *= 2;
        manager->packets = (DataPacket*)realloc(manager->packets, manager->capacity * sizeof(DataPacket));
    }
    manager->packets[manager->count++] = packet;
    return 0;
}

int removePacket(DynamicDataManager* manager, int packet_id) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i].packet_id == packet_id) {
            memmove(&manager->packets[i], &manager->packets[i + 1], (manager->count - i - 1) * sizeof(DataPacket));
            --manager->count;
            return 0;
        }
    }
    return -1; // Packet not found
}

int getPacketCount(DynamicDataManager* manager) {
    return manager->count;
}

void sortPacketsByTimestamp(DynamicDataManager* manager) {
    qsort(manager->packets, manager->count, sizeof(DataPacket), (int (*)(const void *, const void *))compareTimestamp);
}

int compareTimestamp(const void *a, const void *b) {
    return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp;
}

int resolveDNS(const char* hostname, u_char* ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip_address, &(ipv4->sin_addr), sizeof(u_char));

    freeaddrinfo(res);
    return 0;
}

int generateRandomNumber(int minValue, int maxValue) {
    static bool seeded = false;
    if (!seeded) {
        srand(time(NULL));
        seeded = true;
    }
    return rand() % (maxValue - minValue + 1) + minValue;
}
