#define MAX_TRANSACTIONS 1000
#define THRESHOLD_5_SECONDS 5
#define THRESHOLD_10_SECONDS 100
#define WEIGHT_THRESHOLD_1_SECOND 50

typedef struct {
    int transaction_id;
    time_t timestamp;
    int rnti;
    int crc_flag;
    int weight;
    int priority;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T transactions[MAX_TRANSACTIONS];
int transaction_count = 0;
time_t last_5_seconds = time(NULL);
int total_transactions_last_10_seconds = 0;
int weighted_sum_transactions_old_1_second = 0;
int current_load = 0;

void process_transaction(NFAPI_CRC_INDICATION_PDU_T *transaction) {
    if (time(NULL) - transaction->timestamp < THRESHOLD_5_SECONDS) {
        total_transactions_last_10_seconds++;
        if (time(NULL) - transaction->timestamp > 1) {
            weighted_sum_transactions_old_1_second += transaction->weight;
        }
        // Process the transaction
        printf("Processing transaction ID: %d\n", transaction->transaction_id);
    } else {
        printf("Transaction too old, ignored.\n");
    }
}

void update_metrics() {
    time_t now = time(NULL);
    if (now - last_5_seconds >= THRESHOLD_5_SECONDS) {
        // Update cumulative metrics over 5-second intervals
        printf("Cumulative metrics for the last 5 seconds:\n");
        printf("Total transactions: %d\n", total_transactions_last_10_seconds);
        printf("Weighted sum of transactions old 1 second: %d\n", weighted_sum_transactions_old_1_second);
        last_5_seconds = now;
    }
}

int add_transaction(NFAPI_CRC_INDICATION_PDU_T *new_transaction) {
    if (transaction_count < MAX_TRANSACTIONS && total_transactions_last_10_seconds < THRESHOLD_10_SECONDS &&
        weighted_sum_transactions_old_1_second >= WEIGHT_THRESHOLD_1_SECOND) {
        transactions[transaction_count++] = *new_transaction;
        process_transaction(&transactions[transaction_count - 1]);
        update_metrics();
        return new_transaction->transaction_id;
    }
    return -1; // Transaction not added
}

int main() {
    srand(time(NULL));
    time_t current_time = time(NULL);

    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        NFAPI_CRC_INDICATION_PDU_T transaction = {
            .transaction_id = i,
            .timestamp = current_time - rand() % THRESHOLD_5_SECONDS,
            .rnti = rand() % 1024,
            .crc_flag = rand() % 2,
            .weight = rand() % 10 + 1,
            .priority = rand() % 3
        };
        add_transaction(&transaction);
    }

    return 0;
}
