#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKET_SIZE 1024
#define MAX_PACKETS 1000000
#define MAX_BUFFER_SIZE 1024 * 1024 * 256 // 256 MB

typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    char payload[MAX_PACKET_SIZE];
} DataPacket;

typedef struct PacketManager {
    DataPacket packets[MAX_PACKETS];
    int count;
    size_t memory_usage;
    pthread_mutex_t lock;
    time_t max_retention_time;
} PacketManager;

void init_packet_manager(PacketManager *manager, time_t initial_max_retention_time) {
    manager->count = 0;
    manager->memory_usage = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->max_retention_time = initial_max_retention_time;
}

int add_packet(PacketManager *manager, DataPacket packet) {
    if (manager->memory_usage + sizeof(DataPacket) > MAX_BUFFER_SIZE) {
        return -1; // Memory limit exceeded
    }
    pthread_mutex_lock(&manager->lock);
    manager->packets[manager->count++] = packet;
    manager->memory_usage += sizeof(DataPacket);
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_packet(PacketManager *manager, int packet_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; ++i) {
        if (manager->packets[i].packet_id == packet_id) {
            for (int j = i; j < manager->count - 1; ++j) {
                manager->packets[j] = manager->packets[j + 1];
            }
            manager->count--;
            manager->memory_usage -= sizeof(DataPacket);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Packet not found
}

int get_packet_count(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    int count = manager->count;
    pthread_mutex_unlock(&manager->lock);
    return count;
}

void sort_packets_by_timestamp(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    qsort(manager->packets, manager->count, sizeof(DataPacket), 
          (int (*)(const void *, const void *))compare_packets);
    pthread_mutex_unlock(&manager->lock);
}

int compare_packets(const void *a, const void *b) {
    return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp;
}

void clean_old_packets(PacketManager *manager) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&manager->lock);
    int i = 0;
    while (i < manager->count && 
           difftime(current_time, manager->packets[i].timestamp) > manager->max_retention_time) {
        for (int j = i; j < manager->count - 1; ++j) {
            manager->packets[j] = manager->packets[j + 1];
        }
        manager->count--;
        manager->memory_usage -= sizeof(DataPacket);
    }
    pthread_mutex_unlock(&manager->lock);
}

void set_max_retention_time(PacketManager *manager, time_t new_max_retention_time) {
    pthread_mutex_lock(&manager->lock);
    manager->max_retention_time = new_max_retention_time;
    pthread_mutex_unlock(&manager->lock);
}

size_t get_memory_usage(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    size_t usage = manager->memory_usage;
    pthread_mutex_unlock(&manager->lock);
    return usage;
}
