    public string Name { get; set; }
}

public class BinaryFileLoader
{
    public static DataStructure LoadData(string filePath)
    {
        try
        {
            using (FileStream fileStream = new FileStream(filePath, FileMode.Open))
            {
                BinaryFormatter binaryFormatter = new BinaryFormatter();
                return (DataStructure)binaryFormatter.Deserialize(fileStream);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error loading data: " + ex.Message);
            return null;
        }
    }

    public static void Main(string[] args)
    {
        DataStructure data = LoadData("data.bin");
        if (data != null)
        {
            Console.WriteLine($"Loaded data: ID={data.ID}, Name={data.Name}");
        }
    }
}
