#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (array) {
        array->head = NULL;
        array->count = 0;
    }
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(array);
}

int add_packet(DynamicArray* array, DataPacket packet) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1; // Memory allocation failed

    new_node->data = packet;
    new_node->next = array->head;
    array->head = new_node;
    array->count++;
    return 0;
}

int remove_packet(DynamicArray* array, int packet_id) {
    Node* current = array->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.packet_id == packet_id) {
            if (prev == NULL) {
                array->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            array->count--;
            return 0; // Packet removed successfully
        }
        prev = current;
        current = current->next;
    }

    return -1; // Packet not found
}

size_t get_packet_count(DynamicArray* array) {
    return array->count;
}

void sort_packets_by_timestamp(DynamicArray* array) {
    Node* current = array->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        while (next != NULL) {
            if (current->data.timestamp > next->data.timestamp) {
                DataPacket temp = current->data;
                current->data = next->data;
                next->data = temp;
            }
            next = next->next;
        }
        current = current->next;
    }
}

int resolve_dns(const char* hostname, u_char* ip_address) {
    struct hostent *he;
    int error;

    if ((he = gethostbyname(hostname)) == NULL) {
        herror("gethostbyname");
        return -1; // DNS resolution failed
    }

    memcpy(ip_address, he->h_addr_list[0], sizeof(u_char));
    return 0; // DNS resolution successful
}

