#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_FILENAME_LENGTH 256
#define MAX_DIGITS 10
#define HASH_SIZE 1024

typedef struct {
    char filename[MAX_FILENAME_LENGTH];
    time_t timestamp;
} FilenameRecord;

FilenameRecord recentFilenames[HASH_SIZE];

unsigned int hash(const char *key) {
    unsigned int hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash % HASH_SIZE;
}

int isFilenameUnique(const char *newFilename, time_t now) {
    unsigned int index = hash(newFilename);
    while (recentFilenames[index].filename[0] != '\0') {
        if (strcmp(recentFilenames[index].filename, newFilename) == 0 && difftime(now, recentFilenames[index].timestamp) < 3600) {
            return 0;
        }
        index = (index + 1) % HASH_SIZE;
    }
    return 1;
}

char* generateNewFilename(const char *originalFilename) {
    static time_t lastTimestampUpdate = 0;
    time_t now = time(NULL);
    if (lastTimestampUpdate == 0 || difftime(now, lastTimestampUpdate) >= 60) {
        lastTimestampUpdate = now;
        // Update timestamp
    }

    char sanitizedFilename[MAX_FILENAME_LENGTH];
    for (int i = 0; i < strlen(originalFilename); i++) {
        if (isalnum(originalFilename[i])) {
            sanitizedFilename[i] = originalFilename[i];
        } else {
            sanitizedFilename[i] = '_';
        }
    }
    sanitizedFilename[strlen(originalFilename)] = '\0';

    char *fileTypeExtension = strtok(sanitizedFilename, ".");
    if (fileTypeExtension == NULL || strlen(fileTypeExtension) < 3) {
        fileTypeExtension = "XXX";
    } else {
        fileTypeExtension += strlen(sanitizedFilename) - strlen(fileTypeExtension);
    }

    int digitCount = 0;
    char *newFilename = malloc(MAX_FILENAME_LENGTH);
    if (newFilename == NULL) {
        return NULL; // Handle memory allocation failure
    }
    snprintf(newFilename, MAX_FILENAME_LENGTH, "%.*s", (int)strlen(sanitizedFilename) - strlen(fileTypeExtension), sanitizedFilename);

    do {
        for (int i = 0; i < MAX_DIGITS; i++) {
            newFilename[strlen(newFilename)] = '0' + rand() % 10;
        }
        snprintf(newFilename, MAX_FILENAME_LENGTH, "%s.%s", newFilename, fileTypeExtension);
    } while (!isFilenameUnique(newFilename, now));

    // Log the successful generation of the unique filename
    printf("New unique filename: %s\n", newFilename);

    unsigned int index = hash(newFilename);
    strncpy(recentFilenames[index].filename, newFilename, MAX_FILENAME_LENGTH - 1);
    recentFilenames[index].filename[MAX_FILENAME_LENGTH - 1] = '\0';
    recentFilenames[index].timestamp = now;

    return newFilename;
}

int main() {
    srand(time(NULL));
    char *newFilename = generateNewFilename("example_file.txt");
    if (newFilename != NULL) {
        printf("Generated filename: %s\n", newFilename);
        free(newFilename);
    } else {
        printf("Failed to generate a unique filename.\n");
    }
    return 0;
}
