class LogSession:
    def __init__(self, session_id):
        self.session_id = session_id
        self.event_queue = deque()
        self.last_event_time = 0
        self.size = 0
        self.lock = threading.Lock()

    def add_event(self, event):
        if time.time() - self.last_event_time > 30:
            raise ValueError("Event timestamp is too old")
        if len(event) > 10240:
            raise ValueError("Event size exceeds limit")
        with self.lock:
            if self.size + len(event) > 1048576:
                raise ValueError("Session size exceeds limit")
            self.event_queue.append((time.time(), event))
            self.last_event_time = time.time()
            self.size += len(event)

    def get_events(self):
        with self.lock:
            return [event for _, event in sorted(self.event_queue)]

class LogSystem:
    def __init__(self):
        self.sessions = {}
        self.session_lock = threading.Lock()
        self.metrics = {
            'log_rate': 0,
            'queue_depth': 0,
            'memory_usage': 0
        }
        self.health_check_interval = 100

    def log_event(self, session_id, event):
        if session_id not in self.sessions:
            with self.session_lock:
                if session_id not in self.sessions:
                    self.sessions[session_id] = LogSession(session_id)
        session = self.sessions[session_id]
        try:
            session.add_event(event)
        except ValueError as e:
            print(f"Log error: {e}")
            return

    def get_log_rate(self):
        with self.session_lock:
            return self.metrics['log_rate']

    def get_queue_depth(self):
        with self.session_lock:
            return self.metrics['queue_depth']

    def get_memory_usage(self):
        with self.session_lock:
            return self.metrics['memory_usage']

    def run_health_check(self):
        while True:
            time.sleep(0.1)
            log_rate = sum(len(session.get_events()) for session in self.sessions.values())
            queue_depth = sum(len(session.event_queue) for session in self.sessions.values())
            memory_usage = sum(sys.getsizeof(session) for session in self.sessions.values())
            with self.session_lock:
                self.metrics['log_rate'] = log_rate
                self.metrics['queue_depth'] = queue_depth
                self.metrics['memory_usage'] = memory_usage

