    arr->size = 0;
    arr->capacity = initial_capacity;
    arr->array = (NFAPI_L1_RXUEINFO_T *)malloc(initial_capacity * sizeof(NFAPI_L1_RXUEINFO_T));
    pthread_mutex_init(&arr->mutex, NULL);
}

void nfapi_l1_rxueinfo_array_free(NFAPI_L1_RXUEINFO_ARRAY *arr) {
