        free(arr->array[i].received_data);
    }
    pthread_mutex_destroy(&arr->mutex);
    free(arr->array);
}

void nfapi_l1_rxueinfo_array_add(NFAPI_L1_RXUEINFO_ARRAY *arr, NFAPI_L1_RXUEINFO_T new_element) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity == 0 ? 1 : arr->capacity * 2;
        NFAPI_L1_RXUEINFO_T *new_array = (NFAPI_L1_RXUEINFO_T *)realloc(arr->array, new_capacity * sizeof(NFAPI_L1_RXUEINFO_T));
        if (new_array == NULL) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&arr->mutex);
            return;
        }
        arr->array = new_array;
        arr->capacity = new_capacity;
    }
    arr->array[arr->size++] = new_element;
    pthread_mutex_unlock(&arr->mutex);
}

void nfapi_l1_rxueinfo_array_update(NFAPI_L1_RXUEINFO_ARRAY *arr, size_t index, NFAPI_L1_RXUEINFO_T updated_element) {
    if (index >= arr->size) {
        fprintf(stderr, "Index out of bounds\n");
        return;
    }
    pthread_mutex_lock(&arr->mutex);
    free(arr->array[index].received_data);
    arr->array[index] = updated_element;
    pthread_mutex_unlock(&arr->mutex);
}

NFAPI_L1_RXUEINFO_T nfapi_l1_rxueinfo_array_get(NFAPI_L1_RXUEINFO_ARRAY *arr, size_t index) {
    if (index >= arr->size) {
        fprintf(stderr, "Index out of bounds\n");
        return (NFAPI_L1_RXUEINFO_T){};
    }
    pthread_mutex_lock(&arr->mutex);
    NFAPI_L1_RXUEINFO_T element = arr->array[index];
    pthread_mutex_unlock(&arr->mutex);
    return element;
