#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1024
#define IDLE_TIMEOUT 60 // in seconds

typedef enum {
    CONN_STATUS_ACTIVE,
    CONN_STATUS_CLOSED
} TCP_CONNECTION_STATUS;

typedef struct {
    int Connection_ID;
    time_t Last_Active_Time;
    TCP_CONNECTION_STATUS Connection_Status;
    unsigned char *Network_Packet_Data;
    size_t Data_Size;
    pthread_mutex_t mutex; // for thread safety
} TCP_CONNECTION_STATE;

TCP_CONNECTION_STATE connections[MAX_CONNECTIONS];
int connection_count = 0;
pthread_mutex_t global_lock;

void initialize_connections() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connections[i].Connection_ID = -1;
        pthread_mutex_init(&connections[i].mutex, NULL);
    }
    pthread_mutex_init(&global_lock, NULL);
}

int add_connection(int id, unsigned char *data, size_t size) {
    pthread_mutex_lock(&global_lock);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i].Connection_ID == -1) {
            connections[i].Connection_ID = id;
            connections[i].Last_Active_Time = time(NULL);
            connections[i].Connection_Status = CONN_STATUS_ACTIVE;
            connections[i].Network_Packet_Data = malloc(size);
            if (connections[i].Network_Packet_Data == NULL) {
                pthread_mutex_unlock(&global_lock);
                return -1; // Allocation failure
            }
            memcpy(connections[i].Network_Packet_Data, data, size);
            connections[i].Data_Size = size;
            connection_count++;
            pthread_mutex_unlock(&global_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&global_lock);
    return -2; // No space for new connection
}

// Add other functions as required (update_connection, close_connection, etc.)
