void add_monitor(int monitor_id, int device_id, char *status, float usage_rate, time_t last_update_time, float *alert_thresholds) {
    pthread_mutex_lock(&monitor_mutex);
    if (monitor_count < MAX_MONITORS) {
        ResourceMonitor new_monitor;
        new_monitor.monitor_id = monitor_id;
        new_monitor.device_id = device_id;
        strcpy(new_monitor.status, status);
        new_monitor.usage_rate = usage_rate;
        new_monitor.last_update_time = last_update_time;
        for (int i = 0; i < 3; i++) {
            new_monitor.alert_thresholds[i] = alert_thresholds[i];
        }
        monitors[monitor_count++] = new_monitor;
    } else {
        printf("Monitor limit reached\n");
    }
    pthread_mutex_unlock(&monitor_mutex);
}

void update_alert_thresholds(int monitor_id, float *new_thresholds) {
    pthread_mutex_lock(&monitor_mutex);
    for (int i = 0; i < monitor_count; i++) {
        if (monitors[i].monitor_id == monitor_id) {
            for (int j = 0; j < 3; j++) {
                monitors[i].alert_thresholds[j] = new_thresholds[j];
            }
            break;
        }
    }
    pthread_mutex_unlock(&monitor_mutex);
}

int count_exceeding_thresholds(float threshold) {
    int count = 0;
    pthread_mutex_lock(&monitor_mutex);
    for (int i = 0; i < monitor_count; i++) {
        if (monitors[i].usage_rate > threshold) {
            count++;
        }
    }
    pthread_mutex_unlock(&monitor_mutex);
    return count;
}

