#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <chrono>

class Transaction {
public:
    int transaction_id;
    std::string account_number;
    double transaction_amount;
    std::time_t transaction_date;

    Transaction(int id, std::string acc_num, double amount, std::time_t date)
        : transaction_id(id), account_number(acc_num), transaction_amount(amount), transaction_date(date) {}
};

class TransactionManager {
private:
    std::unordered_map<int, Transaction> transactions;
    std::mutex mutex;
    int total_transactions = 0;

public:
    void addTransaction(const Transaction& transaction) {
        std::lock_guard<std::mutex> lock(mutex);
        if (transactions.find(transaction.transaction_id) == transactions.end()) {
            transactions[transaction.transaction_id] = transaction;
            total_transactions++;
        } else {
            std::cerr << "Error: Duplicate transaction ID" << std::endl;
        }
    }

    bool removeTransaction(int id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (transactions.find(id) != transactions.end()) {
            transactions.erase(id);
            total_transactions--;
            return true;
        }
        return false;
    }

    int getTotalTransactions() const {
        return total_transactions;
    }

    std::vector<Transaction> filterTransactions(double min_amount, double max_amount) {
        std::lock_guard<std::mutex> lock(mutex);
        std::vector<Transaction> filtered;
        for (const auto& [id, transaction] : transactions) {
            if (transaction.transaction_amount >= min_amount && transaction.transaction_amount <= max_amount) {
                filtered.push_back(transaction);
            }
        }
        return filtered;
    }

    std::unordered_map<std::string, double> aggregateByAccountNumber() {
        std::lock_guard<std::mutex> lock(mutex);
        std::unordered_map<std::string, double> aggregated;
        for (const auto& [id, transaction] : transactions) {
            aggregated[transaction.account_number] += transaction.transaction_amount;
        }
        return aggregated;
    }
};

int main() {
    TransactionManager manager;
    manager.addTransaction(Transaction(1, "A001", 100.5, std::time(nullptr)));
    manager.addTransaction(Transaction(2, "A002", 200.75, std::time(nullptr)));
    // Add more transactions...

    std::vector<Transaction> filtered = manager.filterTransactions(100.0, 300.0);
    for (const auto& transaction : filtered) {
        std::cout << "Transaction ID: " << transaction.transaction_id << ", Account Number: " << transaction.account_number << ", Amount: " << transaction.transaction_amount << std::endl;
    }

    std::unordered_map<std::string, double> aggregated = manager.aggregateByAccountNumber();
    for (const auto& [account, amount] : aggregated) {
        std::cout << "Account Number: " << account << ", Total Amount: " << amount << std::endl;
    }

    return 0;
}
