#define MAX_USERS 100000

typedef struct {
    char *username;
    char *email;
    char **roles;
    size_t num_roles;
} user_account;

user_account* create_user(const char *username, const char *email) {
    user_account *new_user = (user_account*)malloc(sizeof(user_account));
    new_user->username = strdup(username);
    new_user->email = strdup(email);
    new_user->roles = NULL;
    new_user->num_roles = 0;
    return new_user;
}

void free_user(user_account *user) {
    free(user->username);
    free(user->email);
    if (user->roles != NULL) {
        for (size_t i = 0; i < user->num_roles; ++i) {
            free(user->roles[i]);
        }
        free(user->roles);
    }
    free(user);
}

void add_role(user_account *user, const char *role) {
    user->roles = realloc(user->roles, (user->num_roles + 1) * sizeof(char*));
    user->roles[user->num_roles] = strdup(role);
    ++(user->num_roles);
}

void remove_user(user_account **users, size_t *num_users, const char *username) {
    for (size_t i = 0; i < *num_users; ++i) {
        if (strcmp((*users)[i].username, username) == 0) {
            free_user(&(*users)[i]);
            memmove(&(*users)[i], &(*users)[i + 1], (*num_users - i - 1) * sizeof(user_account));
            --(*num_users);
            break;
        }
    }
}

user_account* get_user_by_role(user_account *users, size_t num_users, const char *role) {
    for (size_t i = 0; i < num_users; ++i) {
        for (size_t j = 0; j < users[i].num_roles; ++j) {
            if (strcmp(users[i].roles[j], role) == 0) {
                return &users[i];
            }
        }
    }
    return NULL;
}

int process_api_endpoints(user_account *users, size_t num_users, char ***json_responses, size_t **request_counts, time_t **timestamps, status_t **statuses) {
    srand(time(NULL));
    *json_responses = (char**)malloc(num_users * sizeof(char*));
    *request_counts = (size_t*)calloc(num_users, sizeof(size_t));
    *timestamps = (time_t*)malloc(num_users * sizeof(time_t));
    *statuses = (status_t*)malloc(num_users * sizeof(status_t));

    for (size_t i = 0; i < num_users; ++i) {
        (*request_counts)[i] = rand() % 10;
        (*timestamps)[i] = time(NULL);
        (*json_responses)[i] = (char*)malloc(1024 * sizeof(char));
        snprintf((*json_responses)[i], 1024, "{\"username\":\"%s\",\"email\":\"%s\",\"roles\":[", users[i].username, users[i].email);
        for (size_t j = 0; j < users[i].num_roles; ++j) {
            if (j > 0) snprintf((*json_responses)[i] + strlen(*json_responses), 1024 - strlen(*json_responses), ",\"");
            snprintf((*json_responses)[i] + strlen(*json_responses), 1024 - strlen(*json_responses), "%s\"", users[i].roles[j]);
        }
        snprintf((*json_responses)[i] + strlen(*json_responses), 1024 - strlen(*json_responses), "]}");
        (*statuses)[i] = rand() % 2 == 0 ? STATUS_SUCCESS : STATUS_FAILURE;
    }

    return 0;
}

int main() {
    user_account *users = (user_account*)malloc(MAX_USERS * sizeof(user_account));
    size_t num_users = 100;

    for (size_t i = 0; i < num_users; ++i) {
        users[i] = create_user("user", "email@example.com");
        add_role(&users[i], "admin");
    }

    char **json_responses;
    size_t *request_counts;
    time_t *timestamps;
    status_t *statuses;

