    }

    for (size_t i = 0; i < num_users; ++i) {
        free(json_responses[i]);
    }
    free(json_responses);
    free(request_counts);
    free(timestamps);
    free(statuses);

    for (size_t i = 0; i < num_users; ++i) {
        free_user(&users[i]);
    }
    free(users);

    return 0;
}
