@RestController
@RequestMapping("/api")
public class ApiGatewayController {

    private final String secretKey = "yourSecretKey";
    private final int maxRequestsPerMinute = 100;

    @GetMapping("/{service}")
    public Mono<ResponseEntity<String>> routeRequest(@PathVariable String service, @RequestHeader HttpHeaders headers) {
        return checkAuthentication(headers)
                .flatMap(authResult -> checkAuthorization(authResult))
                .flatMap(authorizationResult -> applyRateLimiting(service))
                .flatMap(rateLimitingResult -> forwardRequestToBackend(service, headers));
    }

    private Mono<AuthResult> checkAuthentication(HttpHeaders headers) {
