        if (token != null && token.startsWith("Bearer ")) {
            try {
                Claims claims = Jwts.parser().setSigningKey(secretKey).parseClaimsJws(token.replace("Bearer ", "")).getBody();
                return Mono.just(new AuthResult(claims.getSubject(), claims.getRole()));
            } catch (Exception e) {
                return Mono.error(e);
            }
        }
        return Mono.error(new UnauthorizedException());
    }

    private Mono<AuthResult> checkAuthorization(AuthResult authResult) {
        // Implement role-based authorization logic here
        if ("admin".equals(authResult.getRole())) {
            return Mono.just(authResult);
        } else {
            return Mono.error(new ForbiddenException());
        }
    }

