        return Mono.just("success");
    }

    private Mono<ResponseEntity<String>> forwardRequestToBackend(String service, HttpHeaders headers) {
        // Implement request forwarding logic to the appropriate backend service
        return Mono.just(ResponseEntity.ok("Request forwarded to " + service));
    }
}

class AuthResult {
    private String user;
    private String role;

    public AuthResult(String user, String role) {
        this.user = user;
        this.role = role;
    }

    public String getUser() {
