#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>

class Transaction {
public:
    int transaction_id;
    std::string account_number;
    double transaction_amount;
    std::string transaction_date;

    Transaction(int id, const std::string& acc_num, double amount, const std::string& date)
        : transaction_id(id), account_number(acc_num), transaction_amount(amount), transaction_date(date) {}
};

class TransactionManager {
private:
    std::unordered_map<int, Transaction> transactions;
    mutable std::mutex mtx;
    std::condition_variable cv;

public:
    void addTransaction(const Transaction& transaction) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = transactions.find(transaction.transaction_id);
        if (it != transactions.end()) {
            throw std::runtime_error("Duplicate transaction ID");
        }
        transactions[transaction.transaction_id] = transaction;
        cv.notify_one();
    }

    bool removeTransaction(int id) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = transactions.find(id);
        if (it != transactions.end()) {
            transactions.erase(it);
            return true;
        }
        return false;
    }

    int getTransactionCount() const {
        std::lock_guard<std::mutex> lock(mtx);
        return transactions.size();
    }

    std::vector<Transaction> filterTransactions(double min_amount, double max_amount) const {
        std::lock_guard<std::mutex> lock(mtx);
        std::vector<Transaction> filtered;
        for (const auto& entry : transactions) {
            if (entry.second.transaction_amount >= min_amount && entry.second.transaction_amount <= max_amount) {
                filtered.push_back(entry.second);
            }
        }
        return filtered;
    }

    std::unordered_map<std::string, double> aggregateByAccountNumber() const {
        std::lock_guard<std::mutex> lock(mtx);
        std::unordered_map<std::string, double> aggregated;
        for (const auto& entry : transactions) {
            aggregated[entry.second.account_number] += entry.second.transaction_amount;
        }
        return aggregated;
    }
};

int main() {
    TransactionManager manager;
    try {
        manager.addTransaction(Transaction(1, "ACC123", 100.0, "2023-04-01"));
        manager.addTransaction(Transaction(2, "ACC456", 200.0, "2023-04-02"));
        std::cout << "Total transactions: " << manager.getTransactionCount() << std::endl;

        auto filtered = manager.filterTransactions(150.0, 250.0);
        for (const auto& transaction : filtered) {
            std::cout << "Filtered transaction ID: " << transaction.transaction_id << std::endl;
        }

        auto aggregated = manager.aggregateByAccountNumber();
        for (const auto& entry : aggregated) {
            std::cout << "Account Number: " << entry.first << ", Total Amount: " << entry.second << std::endl;
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
