#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_PACKETS 10000000

typedef struct {
    uint32_t packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

DataPacket *packet_array[MAX_PACKETS];
int packet_count = 0;
pthread_mutex_t mutex;

int add_packet(DataPacket *packet) {
    pthread_mutex_lock(&mutex);
    if (packet_count >= MAX_PACKETS) {
        pthread_mutex_unlock(&mutex);
        return -1; // Error: Array is full
    }
    packet_array[packet_count++] = packet;
    pthread_mutex_unlock(&mutex);
    return 0;
}

int remove_packet(uint32_t packet_id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < packet_count; i++) {
        if (packet_array[i]->packet_id == packet_id) {
            free(packet_array[i]);
            for (; i + 1 < packet_count; i++) {
                packet_array[i] = packet_array[i + 1];
            }
            packet_count--;
            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&mutex);
    return -1; // Error: Packet not found
}

int get_packet_count() {
    pthread_mutex_lock(&mutex);
    int count = packet_count;
    pthread_mutex_unlock(&mutex);
    return count;
}

void sort_packets_by_timestamp() {
    pthread_mutex_lock(&mutex);
    qsort(packet_array, packet_count, sizeof(DataPacket *), 
          (int (*)(const void *, const void *))compare_packets);
    pthread_mutex_unlock(&mutex);
}

int compare_packets(const DataPacket **a, const DataPacket **b) {
    return (*a)->timestamp - (*b)->timestamp;
}

int resolve_dns(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip_address, &(ipv4->sin_addr), 4);
        freeaddrinfo(res); // clean up the linked list
        return 0;
    }

    freeaddrinfo(res); // clean up the linked list if no address was found
    return -1;
}

int main() {
    pthread_mutex_init(&mutex, NULL);

    DataPacket packet = {1, time(NULL), 1024};
    add_packet(&packet);
    sort_packets_by_timestamp();
    printf("Number of packets: %d\n", get_packet_count());

    u_char ip_address[4];
    resolve_dns("example.com", ip_address);
    printf("IP Address: %d.%d.%d.%d\n", 
           ip_address[0], ip_address[1], ip_address[2], ip_address[3]);

    pthread_mutex_destroy(&mutex);

    return 0;
}
