using System;
using System.Collections.Concurrent;
using System.Diagnostics;

public class RandomValueGenerator : IDisposable
{
    private readonly ConcurrentDictionary<(int min, int max), (long lastTime, long count)> _cache = new ConcurrentDictionary<(int min, int max), (long lastTime, long count)>();
    private readonly Stopwatch _stopwatch = new Stopwatch();
    private readonly Random _random;
    private readonly int _seed;

    public RandomValueGenerator()
    {
        _seed = Environment.TickCount; // Unique seed for each instance
        _random = new Random(_seed);
    }

    public float GetRandomFloat(int min, int max, int frequency = 1)
    {
        if (!_cache.TryGetValue((min, max), out var cacheEntry))
        {
            _cache.TryAdd((min, max), (0L, 0L));
            cacheEntry = _cache[(min, max)];
        }

        if (_stopwatch.ElapsedMilliseconds < cacheEntry.lastTime + frequency)
        {
            return cacheEntry.count % 2 == 0 ? min : max;
        }

        var value = _random.Next(min, max);
        _cache[(min, max)] = (DateTime.UtcNow.Ticks, cacheEntry.count + 1);

        _stopwatch.Restart();

        return value;
    }

    public int GetRandomInt(int min, int max, int frequency = 1)
    {
        if (!_cache.TryGetValue((min, max), out var cacheEntry))
        {
            _cache.TryAdd((min, max), (0L, 0L));
            cacheEntry = _cache[(min, max)];
        }

        if (_stopwatch.ElapsedMilliseconds < cacheEntry.lastTime + frequency)
        {
            return cacheEntry.count % 2 == 0 ? min : max;
        }

        var value = _random.Next(min, max);
        _cache[(min, max)] = (DateTime.UtcNow.Ticks, cacheEntry.count + 1);

        _stopwatch.Restart();

        return value;
    }

    public void Dispose()
    {
        _cache.Clear();
        _stopwatch.Stop();
    }
}
