using System;
using System.Collections.Concurrent;
using System.Threading;

public class RandomNumberManager
{
    private ConcurrentDictionary<int, RandomGenerator> generators = new ConcurrentDictionary<int, RandomGenerator>();
    private int nextId = 1;

    public int AddGenerator(int min, int max)
    {
        var generator = new RandomGenerator(min, max);
        generators.TryAdd(nextId, generator);
        return nextId++;
    }

    public double GetRandomDouble(int generatorId)
    {
        if (generators.TryGetValue(generatorId, out var generator))
            return generator.GetRandomDouble();
        throw new ArgumentException("Invalid generator ID");
    }

    public int GetRandomInt(int generatorId)
    {
        if (generators.TryGetValue(generatorId, out var generator))
            return generator.GetRandomInt();
        throw new ArgumentException("Invalid generator ID");
    }
}

public class RandomGenerator
{
    private readonly Random random;
    private int currentNumber;
    private int remainingNumbers;

    public RandomGenerator(int min, int max)
    {
        if (min > max) throw new ArgumentException("Min cannot be greater than max");
        random = new Random();
        Reset(min, max);
    }

    public void Reset(int min, int max)
    {
        currentNumber = random.Next(min, max + 1);
        remainingNumbers = currentNumber - min;
    }

    public double GetRandomDouble()
    {
        return (double)random.Next() / int.MaxValue;
    }

    public int GetRandomInt()
    {
        if (remainingNumbers <= 0)
            Reset(currentNumber, currentNumber);
        return currentNumber--;
    }
}
