using System;

public class RandomValueGenerator
{
    private readonly Random _random;
    private int _minValue;
    private int _maxValue;

    public RandomValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");

        _minValue = minValue;
        _maxValue = maxValue;
        _random = new Random();
    }

    public float GenerateRandomFloat()
    {
        return (float)_random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GenerateRandomInt()
    {
        return _random.Next(_minValue, _maxValue + 1);
    }

    public override string ToString()
    {
        return $"Range: {_minValue} to {_maxValue}";
    }
}
