using System;
using System.Collections.Generic;
using System.Linq;

public class ValueGenerator
{
    private Random _random;
    private Dictionary<string, (double min, double max)> _ranges;
    private double _lastGeneratedValue;
    private object _lockObject = new object();

    public ValueGenerator()
    {
        _random = new Random();
        _ranges = new Dictionary<string, (double min, double max)>();
    }

    public void AddRange(string name, double min, double max)
    {
        lock (_lockObject)
        {
            if (_ranges.ContainsKey(name))
                _ranges[name] = (min, max);
            else
                _ranges.Add(name, (min, max));
        }
    }

    public int GenerateIntValue(string rangeName, bool inclusive = true)
    {
        lock (_lockObject)
        {
            var range = _ranges[rangeName];
            double min = range.min;
            double max = range.max;

            if (!inclusive) { 
                min += 0.5; 
                max -= 0.5; 
            }

            int value = (int)_random.Next((int)Math.Floor(min), (int)Math.Ceiling(max)) + (inclusive ? 0 : _random.Next(0, 2));
            _lastGeneratedValue = value;
            return value;
        }
    }

    public float GenerateFloatValue(string rangeName, bool inclusive = true)
    {
        lock (_lockObject)
        {
            var range = _ranges[rangeName];
            double min = range.min;
            double max = range.max;

            if (!inclusive) 
            { 
                min += 0.5; 
                max -= 0.5; 
            }

            float value = (float)_random.NextDouble() * (max - min) + min;
            _lastGeneratedValue = value;
            return value;
        }
    }

    public override string ToString()
    {
        lock (_lockObject)
        {
            return $"Ranges: {string.Join(", ", _ranges.Select(kv => $"{kv.Key}: [{kv.Value.min}, {kv.Value.max}]"))}";
        }
    }
}
