using System;
using System.Collections.Generic;
using System.Linq;

public struct DataPacket
{
    public int PacketId { get; }
    public DateTime Timestamp { get; }
    public int PayloadSize { get; }

    public DataPacket(int packetId, DateTime timestamp, int payloadSize)
    {
        PacketId = packetId;
        Timestamp = timestamp;
        PayloadSize = payloadSize;
    }
}

public class DynamicArrayManager
{
    private List<DataPacket> _packets;
    private Dictionary<int, int> _packetIndexMap;
    private int _lastGeneratedValue;

    public DynamicArrayManager()
    {
        _packets = new List<DataPacket>();
        _packetIndexMap = new Dictionary<int, int>();
        _lastGeneratedValue = 0;
    }

    public void AddPacket(DataPacket packet)
    {
        if (_packetIndexMap.ContainsKey(packet.PacketId))
            throw new ArgumentException("Packet ID already exists");

        _packets.Add(packet);
        _packetIndexMap[packet.PacketId] = _packets.Count - 1;
        _lastGeneratedValue = packet.PacketId;
    }

    public bool RemovePacket(int packetId)
    {
        if (!_packetIndexMap.ContainsKey(packetId))
            return false;

        int index = _packetIndexMap[packetId];
        _packets.RemoveAt(index);
        _packetIndexMap.Remove(packetId);

        // Re-index remaining packets
        for (int i = index; i < _packets.Count; i++)
        {
            _packetIndexMap[_packets[i].PacketId] = i;
        }

        return true;
    }

    public int GetTotalPackets()
    {
        return _packets.Count;
    }

    public void SortByTimestamp()
    {
        _packets.Sort((a, b) => a.Timestamp.CompareTo(b.Timestamp));
    }

    public override string ToString()
    {
        var packetInfo = _packets.Select(packet => $"PacketId: {packet.PacketId}, Timestamp: {packet.Timestamp}, PayloadSize: {packet.PayloadSize}");
        return string.Join(", ", packetInfo);
    }
}
