using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;

public class DynamicValueGenerator
{
    private readonly Random _random;
    private readonly ConcurrentDictionary<(int, int), double> _valueFrequencyCache;
    private readonly SemaphoreSlim _cacheLock = new SemaphoreSlim(1, 1);
    private (int Min, int Max) _currentRange;

    public DynamicValueGenerator(int min, int max)
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");
        }

        _random = new Random();
        _valueFrequencyCache = new ConcurrentDictionary<(int, int), double>();
        UpdateRange(min, max);
    }

    public void UpdateRange(int min, int max)
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");
        }

        _currentRange = (min, max);

        // Reset cache on range update
        _valueFrequencyCache.Clear();
    }

    public float GenerateRandomFloat()
    {
        return (float)GenerateRandomInt() / int.MaxValue;
    }

    public int GenerateRandomInt()
    {
        lock (_cacheLock)
        {
            if (!_valueFrequencyCache.ContainsKey(_currentRange))
            {
                var count = new ConcurrentBag<int>();

                // Simulate generating values to populate the cache
                for (int i = 0; i < 10000; i++)
                {
                    int value = _random.Next(_currentRange.Min, _currentRange.Max + 1);
                    count.Add(value);
                }

                double frequency = count.Count() / (double)count.Distinct().Count();
                _valueFrequencyCache[_currentRange] = frequency;
            }

            return _random.Next(_currentRange.Min, _currentRange.Max + 1);
        }
    }

    public override string ToString()
    {
        if (_valueFrequencyCache.TryGetValue(_currentRange, out double frequency))
        {
            return $"Range: {_currentRange.Min}-{_currentRange.Max}, Value Frequency: {frequency}";
        }

        return $"Range: {_currentRange.Min}-{_currentRange.Max}, Value Frequency: Unknown";
    }
}
