public class DynamicValueGenerator
{
    private readonly ConcurrentDictionary<string, long> _valueFrequencyCache = new();
    private readonly Random _random = new Random();
    private float _minValue;
    private float _maxValue;

    public DynamicValueGenerator(float minValue, float maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

        MinValue = minValue;
        MaxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return _random.NextSingle() * (MaxValue - MinValue) + MinValue;
    }

    public int GenerateRandomInt()
    {
        return _random.Next((int)(MinValue), (int)(MaxValue + 1));
    }

    public void UpdateRange(float minValue, float maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

        Interlocked.Exchange(ref MinValue, minValue);
        Interlocked.Exchange(ref MaxValue, maxValue);
    }

    public override string ToString()
    {
        return $"DynamicValueGenerator: [{MinValue}, {MaxValue}]";
    }
}
