    public CustomMetricsAggregator(
        IEnumerable<Type> dataTypesToAggregate,
        Dictionary<string, double> thresholds,
        Dictionary<string, TimeSpan> retentionPolicies,
        IResourceManagementFramework resourceManager,
        IMonitoringExporter monitoringExporter)
    {
        _dataPoints = new ConcurrentDictionary<string, object>();
        _aggregationFunctions = InitializeAggregationFunctions(dataTypesToAggregate);
        _thresholds = thresholds;
        _retentionPolicies = retentionPolicies;
        _resourceManager = resourceManager;
        _monitoringExporter = monitoringExporter;

        // Start background task for adaptive sampling
        Task.Run(AdaptiveSamplingTask);
    }

    private Dictionary<Type, Func<object, double>> InitializeAggregationFunctions(IEnumerable<Type> dataTypes)
    {
        var functions = new Dictionary<Type, Func<object, double>>();
        foreach (var type in dataTypes)
        {
            switch (Type.GetTypeCode(type))
            {
                case TypeCode.Double:
                    functions[type] = dp => Convert.ToDouble(dp);
                    break;
                // Add other cases for different numeric types
