    public TextualTransactionProcessor(float minValue, float maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public override string ToString()
    {
        return $"Range: {minValue} to {maxValue}";
    }

    public static int GenerateRandomInt(int min, int max, bool exclusiveMax = false)
    {
        if (exclusiveMax)
        {
            return UnityEngine.Random.Range(min, max);
        }
        else
        {
            return UnityEngine.Random.Range(min, max + 1);
        }
    }

    public static float GenerateRandomFloat(float min, float max, bool exclusiveMax = false)
    {
        if (exclusiveMax)
        {
            return UnityEngine.Random.Range(min, max);
        }
        else
        {
            return UnityEngine.Random.Range(min, max);
        }
    }

    public static string[] GetOldTestamentBooks()
    {
        return new string[]
        {
            "Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy",
            "Joshua", "Judges", "Ruth", "1 Samuel", "2 Samuel",
            "1 Kings", "2 Kings", "1 Chronicles", "2 Chronicles", "Ezra",
            "Nehemiah", "Esther", "Job", "Psalms", "Proverbs",
            "Ecclesiastes", "Song of Solomon", "Isaiahus", "Jeremiah",
            "Lamentations", "Ezekiel", "Daniel", "Hosea", "Joel",
            "Amos", "Obadiah", "Jonah", "Micah", "Nahum",
            "Habakkuk", "Zephaniah", "Haggai", "Zechariah", "Malachi"
        };
    }

    public static Dictionary<string, int> AnalyzeTextForOldTestamentBooks(string text)
    {
        var bookNames = GetOldTestamentBooks();
        var regexPattern = $"\\b({"|".Join(bookNames)})\\b";
        var regex = new Regex(regexPattern, RegexOptions.IgnoreCase);
        var matches = regex.Matches(text);

        var result = new Dictionary<string, int>();
        foreach (Match match in matches)
        {
            string bookName = match.Value;
            if (result.ContainsKey(bookName))
            {
                result[bookName]++;
            }
            else
            {
                result[bookName] = 1;
            }
        }

        return result;
    }
}
