    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public override string ToString()
    {
        return $"Range: {minValue} to {maxValue}";
    }

    public bool ProcessTransaction(long transactionId, DateTime transactionTime, int weight, int priority)
    {
        if ((DateTime.Now - transactionTime).TotalSeconds > 5) return false;
        if (totalProcessedTransactionsLast10Secs >= 100 && totalProcessedTransactionsLast10Secs % 10 == 0) return false;

        lock (transactionCountPerSecond)
        {
            int currentSecond = (int)DateTime.Now.TotalSeconds;
            if (!transactionCountPerSecond.ContainsKey(currentSecond))
                transactionCountPerSecond[currentSecond] = 0;
            transactionCountPerSecond[currentSecond]++;
        }

        totalProcessedTransactionsLast10Secs++;
        // Process the transaction
        return true;
    }

    public static Dictionary<string, int> AnalyzeTextForOldTestamentBooks(string text)
    {
        Dictionary<string, string> bookRegexPatterns = new Dictionary<string, string>
        {
            { "Genesis", @"(?i)genesis" },
            { "Exodus", @"(?i)exodus" },
            // Add other Old Testament books and their regex patterns here
        };

        Dictionary<string, int> bookCount = new Dictionary<string, int>();

        foreach (var pattern in bookRegexPatterns)
        {
            MatchCollection matches = Regex.Matches(text, @"\b" + pattern.Value + @"\b", RegexOptions.IgnoreCase);
            if (matches != null)
                foreach (Match match in matches)
                    if (!bookCount.ContainsKey(match.Value))
                        bookCount[match.Value] = 0;
                    else
                        bookCount[match.Value]++;
        }

        return bookCount;
    }

    public static string AddSlashIfWithinSizeLimit(string input, int sizeLimit)
    {
        if (input.Length <= sizeLimit) return input + "/";
        return null;
    }
