import java.util.Random;
import java.util.concurrent.ConcurrentHashMap;

public class BatchProcessor {
    private int minRange;
    private int maxRange;
    private Random random;
    private ConcurrentHashMap<String, Integer> categoryCounts;
    private long itemsProcessedLastMinute;
    private long startTime;

    public BatchProcessor(int minRange, int maxRange) {
        this.minRange = minRange;
        this.maxRange = maxRange;
        this.random = new Random();
        this.categoryCounts = new ConcurrentHashMap<>();
        this.itemsProcessedLastMinute = 0;
        this.startTime = System.currentTimeMillis();
    }

    // Method to generate random integer within specified range
    public int generateRandomInteger() {
        return random.nextInt(maxRange - minRange + 1) + minRange;
    }

    @Override
    public String toString() {
        return "BatchProcessor{" +
                "minRange=" + minRange +
                ", maxRange=" + maxRange +
                '}';
    }

    // Method to process batches
    public void processBatch(int[] batch, char category) {
        if (batch.length < 100) {
            System.out.println("Batch size is less than 100.");
            return;
        }
        long currentTimestamp = System.currentTimeMillis();
        long elapsedTime = currentTimestamp - startTime;

        // Check if the average size of items in each batch is less than 100 bytes
        if (calculateAverageSize(batch) < 100) {
            categoryCounts.putIfAbsent(String.valueOf(category), 0);
            int count = categoryCounts.get(String.valueOf(category)) + 1;
            categoryCounts.put(String.valueOf(category), count);

            // Update metrics and handle edge cases
            updateMetrics(batch.length, elapsedTime);

            // Process batch and log details
            processBatchDetails(currentTimestamp, batch, category);
        } else {
            System.out.println("Average size of items in each batch is not less than 100 bytes.");
        }
    }

    private double calculateAverageSize(int[] batch) {
        long totalSize = 0;
        for (int item : batch) {
            totalSize += item; // Assuming size of item is the value itself
        }
        return (double) totalSize / batch.length;
    }

    private void updateMetrics(int batchSize, long elapsedTime) {
        itemsProcessedLastMinute += batchSize;

        // Update rolling count every millisecond
        if (elapsedTime % 1000 == 0) {
            startTime = System.currentTimeMillis();
            itemsProcessedLastMinute = 0;
        }
    }

    private void processBatchDetails(long timestamp, int[] batch, char category) {
        // Log details to audit log
        System.out.println("Batch ID: " + timestamp +
                ", Timestamp: " + timestamp +
                ", Category: " + category +
                ", Processing Status: Completed");
    }

    // Helper method to find and print the largest integer in an array
    public void findAndPrintLargestInteger() {
        int[] numbers = new int[10]; // Example input size
        for (int i = 0; i < numbers.length; i++) {
            numbers[i] = generateRandomInteger();
        }

        int largestNumber = Integer.MIN_VALUE;
        for (int number : numbers) {
            if (number > largestNumber) {
                largestNumber = number;
            }
        }

        System.out.println("Largest integer in the array: " + largestNumber);
    }
}
