import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CommandExecutor {
    private static final int MAX_RETRIES = 3;
    private static final int BACKOFF_FACTOR = 2;
    private static final int THREAD_POOL_SIZE = 10;
    private static final long TIMEOUT = 60L; // in minutes
    private static final String LOG_FILE_PATH = "execution.log";
    private static final String PROPERTIES_FILE_PATH = "config.properties";

    public static void main(String[] args) {
        ExecutorService executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        try {
            Properties properties = loadProperties(PROPERTIES_FILE_PATH);
            File fileToDelete = new File(properties.getProperty("file.path"));
            String command = properties.getProperty("command");

            for (int i = 0; i < MAX_RETRIES; i++) {
                if (!executorService.isShutdown()) {
                    executorService.submit(() -> executeCommand(fileToDelete, command));
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            executorService.shutdown();
            try {
                if (!executorService.awaitTermination(TIMEOUT, TimeUnit.MINUTES)) {
                    executorService.shutdownNow();
                }
            } catch (InterruptedException e) {
                executorService.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }
    }

    private static void executeCommand(File fileToDelete, String command) {
        int retryCount = 0;
        while (retryCount < MAX_RETRIES) {
            try {
                if (!fileToDelete.exists()) {
                    System.out.println("File does not exist: " + fileToDelete.getAbsolutePath());
                } else {
                    deleteFileWithRetry(fileToDelete);
                    Process process = Runtime.getRuntime().exec(command, null, new File(properties.getProperty("working.directory")));
                    int exitCode = process.waitFor();
                    logExecutionDetails(command, exitCode);
                }
                break;
            } catch (IOException | InterruptedException e) {
                retryCount++;
                if (retryCount >= MAX_RETRIES) {
                    handleCommandFailure(command, e);
                }
            }
        }
    }

    private static void deleteFileWithRetry(File fileToDelete) throws IOException, InterruptedException {
        int retryCount = 0;
        while (retryCount < MAX_RETRIES) {
            try {
                Files.deleteIfExists(fileToDelete.toPath());
                break;
            } catch (IOException e) {
                retryCount++;
                if (retryCount >= MAX_RETRIES) {
                    throw new IOException("Failed to delete file after " + MAX_RETRIES + " retries: " + fileToDelete.getAbsolutePath(), e);
                }
                Thread.sleep(retryCount * BACKOFF_FACTOR * 1000L);
            }
        }
    }

    private static void logExecutionDetails(String command, int exitCode) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(LOG_FILE_PATH, true))) {
            writer.write("Timestamp: " + LocalDateTime.now());
            writer.newLine();
            writer.write("Command: " + command);
            writer.newLine();
            writer.write("Exit Code: " + exitCode);
            writer.newLine();
        } catch (IOException e) {
            System.err.println("Failed to log execution details: " + e.getMessage());
        }
    }

    private static Properties loadProperties(String filePath) throws IOException {
        Properties properties = new Properties();
        try (FileInputStream fis = new FileInputStream(filePath)) {
            properties.load(fis);
        }
        return properties;
    }

    private static void handleCommandFailure(String command, Throwable cause) {
        System.err.println("Failed to execute command after " + MAX_RETRIES + " retries: " + command);
        cause.printStackTrace();
    }
}
