import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

class NetworkEvent {
    private long event_timestamp;
    private String source_ip;
    private String destination_ip;
    private int packet_count;
    private double bandwidth_usage;

    // Constructor, getters, and setters
}

class NetworkMetricsMonitor {
    private ConcurrentHashMap<String, List<NetworkEvent>> eventsBySource;
    private ConcurrentHashMap<String, List<NetworkEvent>> eventsByDestination;
    private ScheduledExecutorService scheduler;
    private long pruneThreshold;

    public NetworkMetricsMonitor(long pruneThreshold) {
        this.eventsBySource = new ConcurrentHashMap<>();
        this.eventsByDestination = new ConcurrentHashMap<>();
        this.scheduler = Executors.newScheduledThreadPool(1);
        this.pruneThreshold = pruneThreshold;
        schedulePruning();
    }

    public void addEvent(NetworkEvent event) {
        eventsBySource.computeIfAbsent(event.getSource_ip(), k -> new ArrayList<>()).add(event);
        eventsByDestination.computeIfAbsent(event.getDestination_ip(), k -> new ArrayList<>()).add(event);
    }

    public List<NetworkEvent> filterEventsBySource(String source_ip) {
        return Collections.unmodifiableList(eventsBySource.getOrDefault(source_ip, Collections.emptyList()));
    }

    public List<NetworkEvent> filterEventsByDestination(String destination_ip) {
        return Collections.unmodifiableList(eventsByDestination.getOrDefault(destination_ip, Collections.emptyList()));
    }

    public double calculateAverageBandwidthUsage(long startTime, long endTime) {
        double totalBandwidth = 0;
        int eventCount = 0;
        for (List<NetworkEvent> events : eventsBySource.values()) {
            for (NetworkEvent event : events) {
                if (event.getEvent_timestamp() >= startTime && event.getEvent_timestamp() <= endTime) {
                    totalBandwidth += event.getBandwidth_usage();
                    eventCount++;
                }
            }
        }
        return eventCount > 0 ? totalBandwidth / eventCount : 0;
    }

    private void schedulePruning() {
        scheduler.scheduleAtFixedRate(this::pruneOldEvents, pruneThreshold, pruneThreshold, TimeUnit.MILLISECONDS);
    }

    private void pruneOldEvents() {
        long now = System.currentTimeMillis();
        eventsBySource.values().removeIf(events -> events.stream().anyMatch(event -> event.getEvent_timestamp() < (now - pruneThreshold)));
        eventsByDestination.values().removeIf(events -> events.stream().anyMatch(event -> event.getEvent_timestamp() < (now - pruneThreshold)));
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, List<NetworkEvent>> entry : eventsBySource.entrySet()) {
            sb.append("Source IP: ").append(entry.getKey()).append("\n");
            for (NetworkEvent event : entry.getValue()) {
                sb.append("  Timestamp: ").append(event.getEvent_timestamp())
                  .append(", Bandwidth Usage: ").append(event.getBandwidth_usage()).append("\n");
            }
        }
        return sb.toString();
    }

    public void shutdown() {
        scheduler.shutdown();
        try {
            if (!scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
                scheduler.shutdownNow();
            }
        } catch (InterruptedException e) {
            scheduler.shutdownNow();
        }
    }
}
