import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.security.DigestException;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class DeserializationHelper {

    private static final String ALGORITHM = "AES";
    private static final String TRANSFORMATION = "AES/CBC/PKCS5Padding";
    private static final int SALT_LENGTH = 16;
    private static final int ITERATION_COUNT = 2048;
    private static final long REPLAY_PROTECTION_WINDOW = 24 * 60 * 60 * 1000; // 24 hours in milliseconds
    private static final Map<String, Long> ivCache = new ConcurrentHashMap<>();
    private static final Logger logger = LoggerFactory.getLogger(DeserializationHelper.class);

    public static MoSTState deserializeAndDecryptMoSTState(byte[] encryptedData, String password) {
        try {
            byte[] salt = generateSalt();
            SecretKeySpec keySpec = deriveKey(password.toCharArray(), salt, ITERATION_COUNT);
            IvParameterSpec ivSpec = new IvParameterSpec(generateSecureIV());

            Cipher cipher = Cipher.getInstance(TRANSFORMATION);
            cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);

            ByteArrayInputStream bis = new ByteArrayInputStream(encryptedData);
            ObjectInputStream ois = new ObjectInputStream(bis);

            Object obj = ois.readObject();
            ois.close();

            if (obj instanceof MoSTState) {
                logger.info("Deserialization successful. Version: {}", getSerializedVersion(encryptedData));
                return (MoSTState) obj;
            } else {
                logger.warn("Invalid object class deserialized.");
                return null;
            }
        } catch (IOException | ClassNotFoundException | NoSuchAlgorithmException | InvalidKeyException | InvalidAlgorithmParameterException e) {
            logger.error("Deserialization failed: {}", e.getMessage());
            throw new RuntimeException("Failed to deserialize and decrypt payload.", e);
        }
    }

    private static byte[] generateSalt() throws NoSuchAlgorithmException {
        SecureRandom random = SecureRandom.getInstanceStrong();
        byte[] salt = new byte[SALT_LENGTH];
        random.nextBytes(salt);
        return salt;
    }

    private static SecretKeySpec deriveKey(char[] password, byte[] salt, int iterationCount) throws NoSuchAlgorithmException {
        byte[] key = javax.crypto.Mac.getInstance("HmacSHA256").doFinal(password);
        for (int i = 1; i < iterationCount; i++) {
            key = javax.crypto.Mac.getInstance("HmacSHA256").doFinal(key);
        }
        return new SecretKeySpec(key, ALGORITHM);
    }

    private static byte[] generateSecureIV() throws NoSuchAlgorithmException {
        SecureRandom random = SecureRandom.getInstanceStrong();
        byte[] iv = new byte[16];
        random.nextBytes(iv);
        return iv;
    }

    private static int getSerializedVersion(byte[] encryptedData) throws IOException {
        ByteArrayInputStream bis = new ByteArrayInputStream(encryptedData);
        ObjectInputStream ois = new ObjectInputStream(bis);
        // Assuming version is the first integer in the serialized data
        int version = ois.readInt();
        ois.close();
        return version;
    }

    private static boolean isReplayAttack(byte[] iv) {
        Long lastProcessedTime = ivCache.get(iv);
        if (lastProcessedTime != null && System.currentTimeMillis() - lastProcessedTime < REPLAY_PROTECTION_WINDOW) {
            logger.warn("Replay attack detected. IV: {}", iv);
            return true;
        }
        ivCache.put(iv, System.currentTimeMillis());
        return false;
    }

    // Thread-safe method to remove old IV entries
    private static void cleanIVCache() {
        long now = System.currentTimeMillis();
        ivCache.entrySet().removeIf(entry -> entry.getValue() < now - REPLAY_PROTECTION_WINDOW);
    }
}
