    }
}

void populate_records(record** records, int min_val, int max_val) {
    *records = (record*)malloc(MAX_RECORDS * sizeof(record));
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; ++i) {
        (*records)[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
}

void persist_records_to_disk(const record* records, const char* filename, int format) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    switch (format) {
        case 0: // Binary format
            fwrite(records, sizeof(record), MAX_RECORDS, file);
            break;
        case 1: // Text format
            for (int i = 0; i < MAX_RECORDS; ++i) {
                fprintf(file, "%d\n", records[i].value);
            }
            break;
        default:
            fprintf(stderr, "Unsupported file format\n");
            fclose(file);
            return;
    }

    if (fclose(file)) {
        perror("Failed to close file after writing");
    }
}

int main() {
    long* offsets;
    int* keys;
    record* records;

    initialize_arrays(&offsets, &keys);
    populate_records(&records, 100, 1000);

    persist_records_to_disk(records, "output.bin", 0); // Binary format
    persist_records_to_disk(records, "output.txt", 1); // Text format

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
