#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

Record* allocate_records(int num_records, int max_offset, int value_range) {
    size_t record_size = sizeof(Record);
    size_t total_size = num_records * record_size;

    if (total_size > 10 * 1024 * 1024) {
        fprintf(stderr, "Error: Total memory required exceeds 10 MB limit.\n");
        return NULL;
    }

    Record* records = (Record*)malloc(total_size);
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ) {
        long offset = rand() % (max_offset + 1);
        int key = rand() % 100 + 1;
        int value = rand() % (2 * value_range + 1) - value_range;

        // Check for duplicate keys
        int is_duplicate = 0;
        for (int j = 0; j < i; j++) {
            if (records[j].key == key) {
                is_duplicate = 1;
                break;
            }
        }

        if (!is_duplicate) {
            records[i].offset = offset;
            records[i].key = key;
            records[i].value = value;
            i++;
        } else {
            free(records);
            fprintf(stderr, "Error: Duplicate key found.\n");
            return NULL;
        }
    }

    printf("Allocated %d records successfully.\n", num_records);
    return records;
}

void free_records(Record* records) {
    if (records != NULL) {
        free(records);
    }
}

int main() {
    int num_records = 1000000;
    int max_offset = 1000;
    int value_range = 50;

    Record* records = allocate_records(num_records, max_offset, value_range);
    if (records != NULL) {
        // Use the allocated records here
        free_records(records);
    }

    return 0;
}
