Record* allocate_and_init_records(int offset_count, int key_count, int value_range_start, int value_range_end, long* offsets, int* keys) {
    if (offset_count <= 0 || key_count <= 0 || value_range_start >= value_range_end) {
        return NULL;
    }

    Record* records = (Record*)malloc(key_count * sizeof(Record));
    for (int i = 0; i < key_count; ++i) {
        keys[i] = rand() % (value_range_end - value_range_start + 1) + value_range_start;
        offsets[i] = keys[i];

        records[i].value = keys[i];
        records[i].status = 0;
        init_string(&records[i].string);
    }

    // Sort the records
    for (int i = 0; i < key_count - 1; ++i) {
        for (int j = 0; j < key_count - i - 1; ++j) {
            if (records[j].value > records[j + 1].value) {
                Record temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }

    return records;
}

void free_records(Record* records, int key_count) {
