void enqueue(PriorityQueue* pq, Record* record, int priority) {
    pthread_mutex_lock(&pq->lock);
    PriorityQueueNode* new_node = (PriorityQueueNode*)malloc(sizeof(PriorityQueueNode));
    new_node->data = record;
    new_node->priority = priority;
    new_node->next = NULL;

    if (pq->front == NULL || pq->front->priority < priority) {
        new_node->next = pq->front;
        pq->front = new_node;
    } else {
        PriorityQueueNode* current = pq->front;
        while (current->next != NULL && current->next->priority >= priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pq->size++;
    pthread_mutex_unlock(&pq->lock);
}

Record* dequeue(PriorityQueue* pq) {
    pthread_mutex_lock(&pq->lock);
    if (pq->front == NULL) {
        pthread_mutex_unlock(&pq->lock);
        return NULL;
    }

    PriorityQueueNode* temp = pq->front;
    Record* record = temp->data;
    pq->front = pq->front->next;
    free(temp);
    pq->size--;
    pthread_mutex_unlock(&pq->lock);
    return record;
}

