#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_QUEUE_SIZE 100

typedef struct {
    int value;
    unsigned char status;
    char* string;
    int version;
    time_t timestamp;
} Record;

typedef struct {
    Record** records;
    int size;
    int capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} PriorityQueue;

PriorityQueue* create_priority_queue(int capacity) {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    pq->records = (Record**)malloc(capacity * sizeof(Record*));
    pq->size = 0;
    pq->capacity = capacity;
    pthread_mutex_init(&pq->lock, NULL);
    pthread_cond_init(&pq->not_full, NULL);
    pthread_cond_init(&pq->not_empty, NULL);
    return pq;
}

void destroy_priority_queue(PriorityQueue* pq) {
    for (int i = 0; i < pq->size; i++) {
        free(pq->records[i]->string);
        free(pq->records[i]);
    }
    free(pq->records);
    pthread_mutex_destroy(&pq->lock);
    pthread_cond_destroy(&pq->not_full);
    pthread_cond_destroy(&pq->not_empty);
    free(pq);
}

void enqueue(PriorityQueue* pq, Record* record) {
    pthread_mutex_lock(&pq->lock);
    while (pq->size == pq->capacity) {
        pthread_cond_wait(&pq->not_full, &pq->lock);
    }
    pq->records[pq->size++] = record;
    pthread_cond_signal(&pq->not_empty);
    pthread_mutex_unlock(&pq->lock);
}

Record* dequeue(PriorityQueue* pq) {
    pthread_mutex_lock(&pq->lock);
    while (pq->size == 0) {
        pthread_cond_wait(&pq->not_empty, &pq->lock);
    }
    Record* record = pq->records[--pq->size];
    pthread_cond_signal(&pq->not_full);
    pthread_mutex_unlock(&pq->lock);
    return record;
}

void adjust_capacity(PriorityQueue* pq, int new_capacity) {
    if (new_capacity < pq->capacity || new_capacity > MAX_QUEUE_SIZE) {
        return;
    }
    Record** new_records = (Record**)malloc(new_capacity * sizeof(Record*));
    memcpy(new_records, pq->records, pq->size * sizeof(Record*));
    free(pq->records);
    pq->records = new_records;
    pq->capacity = new_capacity;
}

void deserialize_and_manage_records_with_priority_queue(unsigned char* byte_array, size_t length, PriorityQueue* pq) {
    // Deserialize records from the byte array
    for (size_t i = 0; i < length; i += sizeof(int) + sizeof(char) + sizeof(time_t) + sizeof(int)) {
        Record* record = (Record*)malloc(sizeof(Record));
        memcpy(&record->value, &byte_array[i], sizeof(int));
        memcpy(&record->status, &byte_array[i + sizeof(int)], sizeof(char));
        int string_length;
        memcpy(&string_length, &byte_array[i + sizeof(int) + sizeof(char)], sizeof(int));
        record->string = (char*)malloc(string_length + 1);
        memcpy(record->string, &byte_array[i + sizeof(int) + sizeof(char) + sizeof(int)], string_length);
        memcpy(&record->version, &byte_array[i + sizeof(int) + sizeof(char) + sizeof(int) + string_length], sizeof(int));
        record->timestamp = *(time_t*)&byte_array[i + sizeof(int) + sizeof(char) + sizeof(int) + string_length + sizeof(int)];

        // Set random values to int fields within a given range
        int min_value = 0;
        int max_value = 100;
        if (min_value < 0 || max_value > INT_MAX) {
            printf("Invalid range for int fields\n");
            free(record->string);
            free(record);
            continue;
        }
        record->value = rand() % (max_value - min_value + 1) + min_value;

        // Sort records based on 'int' fields in ascending order
        enqueue(pq, record);
    }

    // Filter records based on specified condition
    Record* filtered_record = dequeue(pq);
    while (filtered_record != NULL && filtered_record->value < 50) {
        printf("Filtered record: value=%d, status=%hhu, string='%s', version=%d, timestamp=%ld\n",
               filtered_record->value, filtered_record->status, filtered_record->string, filtered_record->version, filtered_record->timestamp);
        free(filtered_record->string);
        free(filtered_record);
        filtered_record = dequeue(pq);
    }

    // Free all dynamically allocated memory
    while ((filtered_record = dequeue(pq)) != NULL) {
        free(filtered_record->string);
        free(filtered_record);
    }
}

int main() {
    srand(time(NULL));
