#define MAX_QUEUE_CAPACITY 1024

typedef struct Record {
    int value;
    unsigned char status;
    char* string;
    int version;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
    int priority;
} Node;

typedef struct Queue {
    Node* front;
    Node* rear;
    int size;
    int capacity;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} Queue;

Queue* create_queue(int capacity) {
    Queue* queue = (Queue*)malloc(sizeof(Queue));
    if (!queue) return NULL;

    queue->front = queue->rear = NULL;
    queue->size = 0;
    queue->capacity = capacity;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    return queue;
}

void destroy_queue(Queue* queue) {
    Node* current = queue->front;
    while (current) {
        Node* next = current->next;
        free(current->record.string);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->not_empty);
    pthread_cond_destroy(&queue->not_full);
    free(queue);
}

void enqueue(Queue* queue, Record record, int priority) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == queue->capacity) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    new_node->record = record;
    new_node->priority = priority;
    new_node->next = NULL;

    if (queue->rear == NULL) {
        queue->front = queue->rear = new_node;
    } else {
        queue->rear->next = new_node;
        queue->rear = new_node;
    }
    queue->size++;

    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->mutex);
}

Record dequeue(Queue* queue) {
    Record result;
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }

    Node* front_node = queue->front;
    result = front_node->record;

    if (queue->front == queue->rear) {
        queue->front = queue->rear = NULL;
    } else {
        queue->front = front_node->next;
    }
    free(front_node);
    queue->size--;

    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->mutex);
    return result;
}

void initialize_and_manage_records_with_queue(int record_count, int min_value, int max_value) {
    Record records[record_count];
    Queue* queue = create_queue(MAX_QUEUE_CAPACITY);

    for (int i = 0; i < record_count; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].status = (unsigned char)(rand() % 256);
        records[i].string = (char*)malloc(100 * sizeof(char));
        sprintf(records[i].string, "Record%d", i);
        records[i].version = rand() % 10;

        enqueue(queue, records[i], records[i].value); // Assuming priority is based on value
    }

    while (queue->size > 0) {
        Record record = dequeue(queue);
        printf("Dequeued: Value=%d, Status=%d, String=%s\n", record.value, record.status, record.string);
        free(record.string);
    }

    destroy_queue(queue);
}
