#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define record structure
typedef struct {
    int value;
    unsigned char status;
    char* string;
    int version;
} Record;

// Define queue node structure
typedef struct Node {
    Record data;
    int priority;
    struct Node* next;
} Node;

// Define thread-safe queue structure
typedef struct {
    Node* front;
    Node* rear;
    int capacity;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t cond_not_full;
    pthread_cond_t cond_not_empty;
} ThreadSafeQueue;

// Function to initialize a record with random values within a specified range
void init_record(Record* rec, int min_val, int max_val) {
    if (min_val < 0 || max_val > INT_MAX || min_val > max_val) {
        fprintf(stderr, "Invalid value range\n");
        exit(EXIT_FAILURE);
    }
    rec->value = rand() % (max_val - min_val + 1) + min_val;
    rec->status = (unsigned char)(rand() % 256);
    int len = rand() % 100 + 1; // Random length between 1 and 100
    rec->string = malloc(len * sizeof(char));
    if (!rec->string) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < len; ++i) {
        rec->string[i] = 'a' + rand() % 26;
    }
    rec->version = 1;
}

// Function to sort records based on a customizable condition
void sort_records(Record* records, int count, int (*compare)(const Record*, const Record*)) {
    for (int i = 0; i < count - 1; ++i) {
        for (int j = 0; j < count - i - 1; ++j) {
            if (compare(&records[j], &records[j + 1]) > 0) {
                Record temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

// Function to filter records based on customizable conditions
void filter_records(Record* records, int* count, int (*condition)(const Record*)) {
    for (int i = *count - 1; i >= 0; --i) {
        if (!condition(&records[i])) {
            free(records[i].string);
            memmove(&records[i], &records[i + 1], (*count - i - 1) * sizeof(Record));
            (*count)--;
        }
    }
}

// Function to enqueue an item into the thread-safe queue
void enqueue(ThreadSafeQueue* queue, Record data, int priority) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == queue->capacity) {
        pthread_cond_wait(&queue->cond_not_full, &queue->mutex);
    }
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->priority = priority;
    new_node->next = NULL;

    if (queue->rear == NULL) {
        queue->front = queue->rear = new_node;
    } else {
        queue->rear->next = new_node;
        queue->rear = new_node;
    }
    queue->size++;
    pthread_cond_signal(&queue->cond_not_empty);
    pthread_mutex_unlock(&queue->mutex);
}

// Function to dequeue an item from the thread-safe queue
Record dequeue(ThreadSafeQueue* queue, int timeout) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == 0 && timeout > 0) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += timeout;
        if (pthread_cond_timedwait(&queue->cond_not_empty, &queue->mutex, &ts) != 0) {
            pthread_mutex_unlock(&queue->mutex);
            fprintf(stderr, "Timeout while waiting for queue item\n");
            exit(EXIT_FAILURE);
        }
    }
    Record data = queue->front->data;
    Node* temp = queue->front;
    queue->front = queue->front->next;
    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    free(temp);
    queue->size--;
    pthread_cond_signal(&queue->cond_not_full);
    pthread_mutex_unlock(&queue->mutex);
    return data;
}

// Function to dynamically adjust the capacity of the thread-safe queue
void resize_queue(ThreadSafeQueue* queue, int new_capacity) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size > new_capacity) {
        dequeue(queue, 0); // Wait for items to be dequeued if necessary
    }
    queue->capacity = new_capacity;
    pthread_cond_signal(&queue->cond_not_full);
    pthread_mutex_unlock(&queue->mutex);
}

// Function to destroy the thread-safe queue and free resources
void destroy_queue(ThreadSafeQueue* queue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size > 0) {
        dequeue(queue, 0); // Wait for items to be dequeued if necessary
    }
    Node* temp;
    while (queue->front != NULL) {
        temp = queue->front;
        queue->front = queue->front->next;
        free(temp->data.string);
        free(temp);
    }
    pthread_mutex_unlock(&queue->mutex);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond_not_full);
    pthread_cond_destroy(&queue->cond_not_empty);
}

// Function to concatenate strings and compute MD5 hash
char* concatenate_and_hash(char** strings, int count) {
    size_t total_len = 0;
    for (int i = 0; i < count; ++i) {
        if (strings[i] != NULL) {
            total_len += strlen(strings[i]) + 1;
        }
    }

    char* result = malloc(total_len * sizeof(char));
    if (!result) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    size_t pos = 0;
    for (int i = 0; i < count; ++i) {
        if (strings[i] != NULL) {
            strcpy(result + pos, strings[i]);
            pos += strlen(strings[i]) + 1;
        }
    }

    char hash[MD5_DIGEST_LENGTH * 2];
    MD5((unsigned char*)result, total_len - 1, (unsigned char*)&hash);
    free(result);

    char* final_result = malloc(total_len + MD5_DIGEST_LENGTH * 2 + 1);
    if (!final_result) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    strcpy(final_result, result);
    strcat(final_result, hash);
    free(result);
    return final_result;
}
