#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

enum Status {
    SUCCESS,
    PARTIAL_SUCCESS,
    FAILURE
};

void* safe_malloc(size_t size, const char* description) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed for %s\n", description);
    }
    return ptr;
}

int initialize_records(long* offsets, int* keys, record** records, int num_records, int min_value, int max_value, enum Status* status) {
    if (num_records <= 0 || min_value > max_value) {
        *status = FAILURE;
        return -1;
    }

    offsets = safe_malloc(num_records * sizeof(long), "offsets");
    keys = safe_malloc(num_records * sizeof(int), "keys");
    records = safe_malloc(num_records * sizeof(record*), "records");

    if (!offsets || !keys || !records) {
        *status = FAILURE;
        return -1;
    }

    srand(time(NULL));
    int successful_allocations = 0;

    for (int i = 0; i < num_records; i++) {
        records[i] = safe_malloc(sizeof(record), "record");
        if (!records[i]) {
            *status = PARTIAL_SUCCESS;
            break;
        }
        records[i]->value = rand() % (max_value - min_value + 1) + min_value;
        successful_allocations++;
    }

    if (successful_allocations == num_records) {
        *status = SUCCESS;
    } else {
        *status = PARTIAL_SUCCESS;
    }

    return successful_allocations;
}

void free_resources(long* offsets, int* keys, record** records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        if (records[i]) {
            free(records[i]);
        }
    }
    free(records);
    free(keys);
    free(offsets);
}

int main() {
    long* offsets;
    int* keys;
    record** records;
    enum Status status;

    int num_records = 1000;
    int min_value = 1;
    int max_value = 100;

    int successful_allocations = initialize_records(offsets, keys, records, num_records, min_value, max_value, &status);

    if (successful_allocations == -1) {
        printf("Operation failed.\n");
    } else if (status == PARTIAL_SUCCESS) {
        printf("%d records initialized successfully out of %d.\n", successful_allocations, num_records);
    } else {
        printf("All %d records initialized successfully.\n", num_records);
    }

    free_resources(offsets, keys, records, num_records);

    return 0;
}
