record** allocate_records(int num_offsets, int num_keys, int num_data_points, char** error_status) {
    // Initialize error status
    *error_status = "Unknown";

    if (num_offsets <= 0 || num_keys <= 0 || num_data_points <= 0) {
        *error_status = "Invalid size parameters";
        return NULL;
    }

    record** records = malloc(num_records * sizeof(record*));
    if (!records) {
        *error_status = "Failed to allocate memory for records array";
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    int successful_allocations = 0;

    for (int i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            *error_status = "Failed to allocate memory for record";
            successful_allocations--;
        } else {
            successful_allocations++;
            records[i]->id = rand() % (num_keys + 1);
            records[i]->value = (double)rand() / RAND_MAX;
            char* identifier = malloc(10 * sizeof(char));
            if (!identifier) {
                free(records[i]);
                records[i] = NULL;
                *error_status = "Failed to allocate memory for identifier";
                successful_allocations--;
            } else {
                snprintf(identifier, 10, "ID%d", i);
                records[i]->identifier = identifier;
            }
        }
    }

    if (successful_allocations == num_records) {
        *error_status = "Operation successful";
    } else if (successful_allocations > 0) {
        *error_status = "Partial success";
    } else {
        // Clean up partial allocations
        for (int i = 0; i < num_records; i++) {
            free(records[i]);
        }
        free(records);
        records = NULL;
        *error_status = "Operation failed due to insufficient memory";
    }

    return records;
}

void deallocate_records(record** records, int num_records) {
    if (records) {
        for (int i = 0; i < num_records; i++) {
            free(records[i]->identifier);
            free(records[i]);
        }
        free(records);
    }
}
