void allocate_and_initialize_arrays(
    size_t num_offsets, size_t num_keys, size_t num_data_points, size_t num_identifiers,
    long** offsets, int** keys, double** data_points, char*** identifiers,
    record** records, char** error_msg,
    void (*log_error)(const char*), 
    void (*allocate_memory)(size_t, void**),
    void (*free_memory)(void*)
) {
    if (num_offsets == 0 || num_keys == 0 || num_data_points == 0 || num_identifiers == 0) {
        strcpy(*error_msg, "Size parameters cannot be zero.");
        return;
    }

    allocate_memory(num_offsets * sizeof(long), (void**)offsets);
    allocate_memory(num_keys * sizeof(int), (void**)keys);
    allocate_memory(num_data_points * sizeof(double), (void**)data_points);
    allocate_memory(num_identifiers * sizeof(char*), (void**)identifiers);

    if (!(*offsets) || !(*keys) || !(*data_points) || !(*identifiers)) {
        strcpy(*error_msg, "Memory allocation failed.");
        return;
    }

    allocate_memory(num_records * sizeof(record), (void**)records);
    if (!(*records)) {
        strcpy(*error_msg, "Memory allocation failed for records.");
        free_memory(*offsets);
        free_memory(*keys);
        free_memory(*data_points);
        free_memory(*identifiers);
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        (*records)[i].value = rand() % num_keys;
        (*records)[i].data = ((double)rand()) / RAND_MAX;
        (*records)[i].timestamp = time(NULL);

        size_t identifier_len = rand() % 16 + 1;
        allocate_memory((identifier_len + 1) * sizeof(char), (void**)&(*identifiers)[i]);
        if (!(*identifiers)[i]) {
            strcpy(*error_msg, "Memory allocation failed for identifier.");
            free_memory((*records));
            (*records) = NULL;
            continue;
        }
        (*identifiers)[i][identifier_len] = '\0';
        strncat((*identifiers)[i], "id", 2);
    }

    *error_msg[0] = '\0';
}

void log_error_impl(const char* msg) {
    printf("Error: %s\n", msg);
}

void allocate_memory_impl(size_t size, void** ptr) {
    *ptr = malloc(size);
}

void free_memory_impl(void* ptr) {
    if (ptr) {
        free(ptr);
    }
}
