    *error_status = (int *)malloc(sizeof(int));
    if (*error_status == NULL) {
        return -1; // Error: Failed to allocate memory for error status
    }
    **error_status = 0; // Assume success initially

    // Validate input sizes
    if (num_offsets == 0 || num_keys == 0 || num_records_per_key == 0) {
        *error_status = 1; // Error: Invalid input size
        return -1;
    }

    // Allocate memory for records array
    *records = (Record ***)malloc(num_keys * sizeof(Record **));
    if (*records == NULL) {
        *error_status = 2; // Error: Failed to allocate memory for records array
        free(*error_status);
        return -1;
    }

    size_t successful_allocations = 0;

    for (size_t key_idx = 0; key_idx < num_keys; key_idx++) {
        (*records)[key_idx] = (Record **)malloc(num_records_per_key * sizeof(Record *));
        if ((*records)[key_idx] == NULL) {
            *error_status = 2; // Error: Failed to allocate memory for sub-array
            // Free previously allocated memory and set error status
            for (size_t i = 0; i < key_idx; i++) {
                free((*records)[i]);
            }
            free(*records);
            free(*error_status);
            return -1;
        }

        for (size_t record_idx = 0; record_idx < num_records_per_key; record_idx++) {
            (*records)[key_idx][record_idx] = (Record *)malloc(sizeof(Record));
            if ((*records)[key_idx][record_idx] == NULL) {
                *error_status = 2; // Error: Failed to allocate memory for record
                // Free previously allocated memory and set error status
                for (size_t i = 0; i <= key_idx; i++) {
                    free((*records)[i]);
                }
                free(*records);
                free(*error_status);
                return -1;
            }

            (*records)[key_idx][record_idx]->value = record_idx * 10; // Example initialization
            time(&(*records)[key_idx][record_idx]->timestamp); // Record current time
            successful_allocations++;
        }
    }

    if (successful_allocations == num_offsets * num_keys * num_records_per_key) {
        return successful_allocations; // All allocations were successful
    } else {
        return -1; // Some allocations failed
    }
}

void free_records(Record ***records, size_t num_keys) {
    for (size_t key_idx = 0; key_idx < num_keys; key_idx++) {
        if (records[key_idx] != NULL) {
            for (size_t record_idx = 0; records[key_idx][record_idx] != NULL; record_idx++) {
                free(records[key_idx][record_idx]);
            }
            free(records[key_idx]);
        }
    }
    free(records);
}
