#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    TASK_PENDING,
    TASK_COMPLETED,
    TASK_FAILED
} TaskStatus;

typedef struct Task {
    char *name;
    int priority;
    TaskStatus status;
    struct Task *next;
} Task;

Task* create_task(const char *name, int priority, TaskStatus status) {
    Task *new_task = (Task *)malloc(sizeof(Task));
    new_task->name = strdup(name);
    new_task->priority = priority;
    new_task->status = status;
    new_task->next = NULL;
    return new_task;
}

void add_task(Task **head, const char *name, int priority, TaskStatus status) {
    Task *new_task = create_task(name, priority, status);
    if (*head == NULL) {
        *head = new_task;
    } else {
        Task *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_task;
    }
}

void remove_task(Task **head, int priority) {
    Task *current = *head;
    Task *prev = NULL;

    while (current != NULL) {
        if (current->priority == priority) {
            if (prev == NULL) {
                *head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->name);
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

void sort_tasks_by_priority(Task **head) {
    if (*head == NULL || (*head)->next == NULL) return;

    Task *sorted_head = NULL;
    while (*head != NULL) {
