} TaskStatus;

// Define the structure for a single task
typedef struct Task {
    char *name;
    int priority;
    TaskStatus status;
    struct Task *next;
} Task;

// Define the structure for the list of tasks
typedef struct TaskList {
    Task *head;
    int size;
} TaskList;

// Function to create a new task
Task* task_create(const char *name, int priority, TaskStatus status) {
    Task *task = (Task*)malloc(sizeof(Task));
    if (task == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    task->name = strdup(name);
    task->priority = priority;
    task->status = status;
    task->next = NULL;
    return task;
}

// Function to add a new task to the list
void task_list_add(TaskList *list, const char *name, int priority, TaskStatus status) {
    Task *new_task = task_create(name, priority, status);
    if (new_task != NULL) {
        new_task->next = list->head;
        list->head = new_task;
        list->size++;
    }
}

// Function to remove tasks based on their priority level
void task_list_remove_by_priority(TaskList *list, int priority) {
    Task *current = list->head;
    Task *prev = NULL;

    while (current != NULL) {
        if (current->priority == priority) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->name);
            free(current);
            list->size--;
            current = prev ? prev->next : list->head;
        } else {
            prev = current;
            current = current->next;
        }
    }
}

// Function to sort the tasks by priority
