    TaskList list = {NULL, 0};
    task_list_add(&list, "Task 1", 2, TASK_STATUS_PENDING);
    task_list_add(&list, "Task 2", 1, TASK_STATUS_IN_PROGRESS);
    task_list_add(&list, "Task 3", 3, TASK_STATUS_COMPLETED);

