} record;

enum status {
    SUCCESS,
    PARTIAL_SUCCESS,
    FAILURE
};

int createRecords(int num_records, long** offset_values, int** keys, double** data_points, char*** identifiers, record** records, enum status* error_status) {
    *error_status = SUCCESS;

    if (num_records <= 0) {
        return num_records; // Handle zero-sized arrays gracefully
    }

    *offset_values = (long*)malloc(num_records * sizeof(long));
    *keys = (int*)malloc(num_records * sizeof(int));
    *data_points = (double*)malloc(num_records * sizeof(double));
    *identifiers = (char**)malloc(num_records * sizeof(char*));
    *records = (record*)malloc(num_records * sizeof(record));

    if (!*offset_values || !*keys || !*data_points || !*identifiers || !*records) {
        *error_status = FAILURE;
        return -1; // Return an error code
    }

    for (int i = 0; i < num_records; i++) {
        (*offset_values)[i] = rand(); // Example initialization
        (*keys)[i] = rand() % 100; // Random value within a given range
        (*data_points)[i] = ((double)rand()) / RAND_MAX; // Random double between 0 and 1

        (*identifiers)[i] = (char*)malloc(20 * sizeof(char)); // Dynamically allocate memory for string field
        if (!(*identifiers)[i]) {
            *error_status = PARTIAL_SUCCESS;
            break;
        }

        sprintf((*identifiers)[i], "ID%d", i); // Example identifier format

        (*records)[i].key = (*keys)[i];
        (*records)[i].value = (*data_points)[i];
        (*records)[i].identifier = (*identifiers)[i];
        (*records)[i].timestamp = time(NULL);
    }

    return num_records;
}

void filterAndSortRecords(int num_records, record* records, int key_min, int key_max, double** sorted_records, int* sorted_count) {
    *sorted_records = NULL;
    *sorted_count = 0;

    for (int i = 0; i < num_records; i++) {
        if (records[i].key >= key_min && records[i].key <= key_max) {
            (*sorted_count)++;
        }
    }

    *sorted_records = (record*)malloc((*sorted_count) * sizeof(record));

    for (int i = 0, j = 0; i < num_records; i++) {
        if (records[i].key >= key_min && records[i].key <= key_max) {
            (*sorted_records)[j++] = records[i];
        }
    }

    qsort(*sorted_records, *sorted_count, sizeof(record), compareRecords);
}

int compareRecords(const void* a, const void* b) {
    record* rec1 = (record*)a;
    record* rec2 = (record*)b;
    return (rec1->value > rec2->value) - (rec1->value < rec2->value);
}

void freeAllMemory(long* offset_values, int* keys, double* data_points, char** identifiers, record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(identifiers[i]);
    }

    free(offset_values);
    free(keys);
    free(data_points);
    free(identifiers);
    free(records);
}
