typedef struct {
    unsigned long fileSize;
    time_t modificationTime;
    const char* filePath;
    unsigned short accessPermissions;
    unsigned long checksum;
} fileRecord;

int allocateFileRecords(fileRecord** records, size_t count) {
    *records = (fileRecord*)malloc(count * sizeof(fileRecord));
    if (*records == NULL) {
        return -1; // Memory allocation failed
    }
    for (size_t i = 0; i < count; ++i) {
        (*records)[i].fileSize = rand() % 1000 + 1; // Random file size between 1 and 1000
        (*records)[i].modificationTime = time(NULL) - (rand() % (365 * 24 * 60 * 60)); // Past modification time
        (*records)[i].filePath = strdup("file_path"); // Simulated file path
        (*records)[i].accessPermissions = S_IRUSR; // Read-only permission
        (*records)[i].checksum = rand() % 1000000 + 1; // Random checksum
    }
    return 0; // Success
}

void freeFileRecords(fileRecord* records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free((char*)(records[i].filePath)); // Free dynamically allocated file path strings
    }
    free(records); // Free the array of file records
}

int filterAndSortRecords(fileRecord* records, size_t count, size_t minSize, size_t maxSize, fileRecord** sortedRecords) {
    int successful = 0;
    for (size_t i = 0; i < count; ++i) {
        if (records[i].fileSize >= minSize && records[i].fileSize <= maxSize) {
            successful++;
        }
    }
    *sortedRecords = (fileRecord*)malloc(successful * sizeof(fileRecord));
    if (*sortedRecords == NULL) {
        return -1; // Memory allocation failed
    }

    for (size_t i = 0, j = 0; i < count; ++i) {
        if (records[i].fileSize >= minSize && records[i].fileSize <= maxSize) {
            (*sortedRecords)[j++] = records[i];
        }
    }

    qsort(*sortedRecords, successful, sizeof(fileRecord), [](const void* a, const void* b) {
        return ((fileRecord*)b)->modificationTime - ((fileRecord*)a)->modificationTime;
    });

    return successful; // Number of successfully filtered and sorted records
}
