typedef struct {
    char* name;
    char* value;
    time_t timestamp;
} LogEntry;

LogEntry* parseConfigFile(const char* log_file_path, const int min_entry_length, const int max_entry_length, const int value_range, const int timestamp_margin, size_t* entries_count) {
    FILE* file = fopen(log_file_path, "r");
    if (!file) {
        fprintf(stderr, "Failed to open the configuration file: %s\n", log_file_path);
        return NULL;
    }

    LogEntry* entries = NULL;
    size_t allocated_entries = 0;
    *entries_count = 0;

    while (1) {
        // Allocate more memory if needed
        if (*entries_count >= allocated_entries) {
            allocated_entries += 100; // Increase by 100 each time
            entries = realloc(entries, allocated_entries * sizeof(LogEntry));
            if (!entries) {
                fprintf(stderr, "Memory allocation failed. Exceeded the 20 MB limit.\n");
                fclose(file);
                return NULL;
            }
        }

        // Read entry from file
        LogEntry* entry = &entries[*entries_count];
        if (fscanf(file, "%ms %ms", &entry->name, &entry->value) != 2) {
            break; // End of file or read error
        }

        // Validate and initialize fields
        time_t current_time = time(NULL);
        entry->timestamp = current_time - timestamp_margin + rand() % (timestamp_margin * 2);
        if (strlen(entry->name) < min_entry_length || strlen(entry->name) > max_entry_length) {
            free(entry->name);
            free(entry->value);
            continue;
        }
        if (strlen(entry->value) > value_range) {
            free(entry->name);
            free(entry->value);
            continue;
        }

        // Ensure no duplicate names
        for (size_t i = 0; i < *entries_count; ++i) {
            if (strcmp(entries[i].name, entry->name) == 0) {
                free(entry->name);
                free(entry->value);
                continue;
            }
        }

        (*entries_count)++;
    }

    fclose(file);

    // Shrink the allocated memory
    entries = realloc(entries, *entries_count * sizeof(LogEntry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed. Exceeded the 20 MB limit.\n");
        return NULL;
    }

    return entries;
}
