    long* offsets = malloc(offset_size * sizeof(long));
    int* keys = malloc((keys_range[1] - keys_range[0] + 1) * sizeof(int));
    record* records = malloc(records_size * sizeof(record));

    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return -2; // Memory allocation failed
    }

    for (long i = 0; i < offset_size; ++i) {
        offsets[i] = i;
    }

    srand(time(NULL));
    int key_count = keys_range[1] - keys_range[0] + 1;
    for (int i = 0; i < key_count; ++i) {
        keys[i] = rand() % key_count + keys_range[0];
    }

    for (long i = 0; i < records_size; ++i) {
        records[i].value = rand() % (records_range[1] - records_range[0] + 1) + records_range[0];
        int valid_key;
        do {
            valid_key = rand() % key_count + keys_range[0];
        } while (find_key(records, i, valid_key));
        records[i].key = &keys[valid_key - keys_range[0]];
    }

    for (long i = 0; i < offset_size; ++i) {
        free(records[i].key);
    }
    free(offsets);
    free(keys);
    free(records);

    return 0; // Success
}

int find_key(record* records, long index, int key) {
    for (long i = 0; i < index; ++i) {
        if (*records[i].key == key) {
            return 1;
        }
    }
    return 0;
}
