NFAPI_CRC_INDICATION_PDU_T* manageArray(int *size, int resetFlag) {
    static NFAPI_CRC_INDICATION_PDU_T array[MAX_ELEMENTS];
    static int currentIndex = 0;

    if (*size > MAX_ELEMENTS - currentIndex) {
        printf("Error: Maximum elements limit reached.\n");
        return NULL;
