    for (int i = 0; i < *size; i++) {
        array[currentIndex + i].rx_ue_info.RX_UE_INFORMATION_TAG = rand() % MAX_ELEMENTS + 1;
        array[currentIndex + i].rx_ue_info.RNTI = rand() % 1024 + 1;
        if (resetFlag) {
            array[currentIndex + i].CRCFLAG = 0; // Reset CRCFLAG
        } else {
            array[currentIndex + i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        }
    }

    *size += currentIndex;
    currentIndex += *size;

    return array;
}

