#include <stdio.h>

typedef struct {
    unsigned char RX_UE_INFORMATION_TAG[16];
    unsigned short RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_error(const char *message) {
    // Custom error logging function
    fprintf(stderr, "Error: %s\n", message);
}

void initialize_crypto_library() {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_sha256());
    EVP_add_key_exchange(EVP_ecdh());

    EVP_add_digest_alias("sha256", "sha256-openssl");
    EVP_add_key_exchange_alias("ecdh", "ecdhe-nistp256");

    // Set custom error logging function
    ERR_set_error_string(ERR_get_error(), "Custom error message");
}

int add_crc_indication(NFAPI_CRC_INDICATION_PDU_T **array, int *size) {
    if (*size >= 1024) {
        log_error("Array size limit exceeded");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_element = realloc(*array, (*size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_element) {
        log_error("Memory allocation failed");
        return -1;
    }

    *array = new_element;

    // Populate new element with random data
    if (RAND_bytes(new_element[*size].RX_UE_INFORMATION_TAG, sizeof(new_element[*size].RX_UE_INFORMATION_TAG)) != 1 ||
        RAND_bytes((unsigned char *)&new_element[*size].RNTI, sizeof(new_element[*size].RNTI)) != 1 ||
        RAND_bytes((unsigned char *)&new_element[*size].CRC_INDICATION_REL8_TAG, sizeof(new_element[*size].CRC_INDICATION_REL8_TAG)) != 1) {
        log_error("Failed to generate random data");
        return -1;
    }

    (*size)++;
    return 0;
}

void print_crc_indications(NFAPI_CRC_INDICATION_PDU_T *array, int size, const char *file_path) {
    FILE *file = fopen(file_path, "w");
    if (!file) {
        log_error("Failed to open file for writing");
        return;
    }

    for (int i = 0; i < size; i++) {
        fprintf(file, "RX_UE_INFORMATION_TAG: ");
        for (int j = 0; j < sizeof(array[i].RX_UE_INFORMATION_TAG); j++) {
            fprintf(file, "%02x", array[i].RX_UE_INFORMATION_TAG[j]);
        }
        fprintf(file, ", RNTI: %d, CRC_INDICATION_REL8_TAG: %u\n",
                array[i].RNTI, array[i].CRC_INDICATION_REL8_TAG);
    }

    fclose(file);
}

void cleanup_crypto_library(NFAPI_CRC_INDICATION_PDU_T *array, int size) {
    if (array) {
        free(array);
    }
}
```

