#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Node {
    double data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    int size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int is_cyclic;
} LinkedList;

Node* create_node(double data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
    list->is_cyclic = 0;
    return list;
}

void add_to_list(LinkedList* list, double data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(data);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->size++;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->lock);
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
}

void* retrieve_data(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    double data;
    if (data_retrieval_function(&data)) { // Assume this function retrieves data and returns true on success
        add_to_list(list, data);
    } else {
        fprintf(stderr, "Failed to retrieve data\n");
    }
    return NULL;
}

int main() {
    LinkedList* list = create_linked_list();
    pthread_t threads[10];

    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, retrieve_data, list) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    free_list(list);

    return 0;
}
