import java.util.*;
import java.util.concurrent.*;

public class DataProcessingPipeline {
    private Map<String, Job> jobs;
    private Set<String> whitelist;
    private ExecutorService executor;
    private MetadataService metadataService;

    public DataProcessingPipeline(int maxConcurrentJobs) {
        this.jobs = new HashMap<>();
        this.whitelist = new HashSet<>();
        this.executor = Executors.newFixedThreadPool(maxConcurrentJobs);
        this.metadataService = new SimulatedMetadataService();
    }

    public void addJob(String jid, Runnable task) {
        if (whitelist.contains(jid)) {
            Job job = new Job(jid, task);
            jobs.put(jid, job);
            scheduleJob(job);
        } else {
            System.out.println("Job " + jid + " not in whitelist. Skipping.");
        }
    }

    public void addToWhitelist(String jid) {
        whitelist.add(jid);
    }

    private void scheduleJob(Job job) {
        executor.execute(new JobExecutor(job, metadataService));
    }

    private static class Job {
        String jid;
        Runnable task;

        Job(String jid, Runnable task) {
            this.jid = jid;
            this.task = task;
        }
    }

    private static class JobExecutor implements Runnable {
        Job job;
        MetadataService metadataService;

        JobExecutor(Job job, MetadataService metadataService) {
            this.job = job;
            this.metadataService = metadataService;
        }

        @Override
        public void run() {
            try {
                if (metadataService.isResourceAvailable(job.jid)) {
                    long start = System.currentTimeMillis();
                    job.task.run();
                    long end = System.currentTimeMillis();
                    System.out.println("Job " + job.jid + " completed in " + (end - start) + "ms");
                } else {
                    System.out.println("Not enough resources for Job " + job.jid);
                }
            } catch (Exception e) {
                System.err.println("Error processing Job " + job.jid + ": " + e.getMessage());
                // Retry with exponential backoff
                scheduleRetry(job);
            }
        }

        private void scheduleRetry(Job job) {
            ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
            scheduler.schedule(() -> executor.execute(new JobExecutor(job, metadataService)), 2, TimeUnit.SECONDS);
        }
    }

    public static class SimulatedMetadataService implements MetadataService {
        @Override
        public boolean isResourceAvailable(String jid) {
            // Simulate resource availability check
            return Math.random() > 0.5;
        }
    }

    public interface MetadataService {
        boolean isResourceAvailable(String jid);
    }

    public static void main(String[] args) {
        DataProcessingPipeline pipeline = new DataProcessingPipeline(1000);

        // Example jobs with custom priority
        Runnable task1 = () -> System.out.println("Executing Job 1");
        Runnable task2 = () -> System.out.println("Executing Job 2");

        pipeline.addToWhitelist("JID1");
        pipeline.addToWhitelist("JID2");

        pipeline.addJob("JID1", task1);
        pipeline.addJob("JID2", task2);

        // Simulate adding more jobs as workload increases
    }
}
