        PaymentMethod paymentMethod = paymentMethods.get(order.getPaymentMethod());
        if (paymentMethod == null) {
            loggingService.logError("Invalid payment method: " + order.getPaymentMethod());
            return;
        }

        BillingPolicy policy = billingPolicies.get(order.getBillingPolicy());
