    if (file == NULL) return ERR_FILE_OPEN;

    fseek(file, 0, SEEK_END);
    int fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    bundle->data = malloc(fileSize + 1);
    if (bundle->data == NULL) {
        fclose(file);
        return ERR_MEMORY_ALLOC;
    }

    fread(bundle->data, sizeof(char), fileSize, file);
    bundle->data[fileSize] = '\0';
    fclose(file);

    return ERR_OK;
}

// Function to parse a resource bundle
int parseResourceBundle(ResourceBundle* bundle) {
    // Implement parsing logic for JSON, XML, and YAML formats
    // This is a placeholder function
    return ERR_PARSE_JSON;
}

// Function to free a resource bundle
void freeResourceBundle(ResourceBundle* bundle) {
    if (bundle->data != NULL) {
        free(bundle->data);
        bundle->data = NULL;
        bundle->size = 0;
    }
}

// Main function to demonstrate the use of loadResourceBundle, parseResourceBundle, and freeResourceBundle
int main() {
    ResourceBundle bundle;
    int result = loadResourceBundle("example.json", &bundle);
    if (result != ERR_OK) {
        printf("Failed to load resource bundle: %d\n", result);
        return 1;
    }

    result = parseResourceBundle(&bundle);
    if (result != ERR_OK) {
        printf("Failed to parse resource bundle: %d\n", result);
        freeResourceBundle(&bundle);
        return 1;
    }

    // Process the parsed data
    printf("Resource bundle loaded and parsed successfully.\n");

    freeResourceBundle(&bundle);
    return 0;
}
