#define MAX_QUEUE_LENGTH 1500

typedef struct {
    double value;
    int timestamp;
} Transaction;

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    Transaction queue[MAX_QUEUE_LENGTH];
    int head, tail;
    int count;
} TransactionQueue;

TransactionQueue transactionQueue;

void initTransactionQueue() {
    pthread_mutex_init(&transactionQueue.lock, NULL);
    pthread_cond_init(&transactionQueue.cond, NULL);
    transactionQueue.head = 0;
    transactionQueue.tail = 0;
    transactionQueue.count = 0;
}

int enqueueTransaction(double value) {
    pthread_mutex_lock(&transactionQueue.lock);
    while (transactionQueue.count == MAX_QUEUE_LENGTH - 1) {
        pthread_cond_wait(&transactionQueue.cond, &transactionQueue.lock);
    }
    int nextTail = (transactionQueue.tail + 1) % MAX_QUEUE_LENGTH;
    transactionQueue.queue[transactionQueue.tail].value = value;
    transactionQueue.queue[transactionQueue.tail].timestamp = time(NULL);
    transactionQueue.tail = nextTail;
    transactionQueue.count++;
    pthread_mutex_unlock(&transactionQueue.lock);
    return 0;
}

int dequeueTransaction(double *value) {
    pthread_mutex_lock(&transactionQueue.lock);
    while (transactionQueue.count == 0) {
        pthread_cond_wait(&transactionQueue.cond, &transactionQueue.lock);
    }
    *value = transactionQueue.queue[transactionQueue.head].value;
    int nextHead = (transactionQueue.head + 1) % MAX_QUEUE_LENGTH;
    transactionQueue.head = nextHead;
    transactionQueue.count--;
    pthread_mutex_unlock(&transactionQueue.lock);
    return 0;
}

int isBackpressure() {
    pthread_mutex_lock(&transactionQueue.lock);
    int result = (transactionQueue.count >= (MAX_QUEUE_LENGTH * 3) / 4);
    pthread_mutex_unlock(&transactionQueue.lock);
    return result;
}

double calculateTransactionRate() {
    struct timeval now;
    gettimeofday(&now, NULL);
    double currentTime = now.tv_sec + now.tv_usec / 1000000.0;
    int transactionCount = 0;
    for (int i = 0; i < MAX_QUEUE_LENGTH; i++) {
        int index = (transactionQueue.head + i) % MAX_QUEUE_LENGTH;
        if ((currentTime - transactionQueue.queue[index].timestamp) <= 1.0) {
            transactionCount++;
        }
    }
    return transactionCount / 10.0; // Assuming 10 second window for simplicity
}

