#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 10000000

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket *packets;
    int count;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->packets = (DataPacket *)malloc(MAX_PACKETS * sizeof(DataPacket));
    if (!manager->packets) {
        // Handle memory allocation failure
        return;
    }
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_packet_manager(PacketManager *manager) {
    free(manager->packets);
    pthread_mutex_destroy(&manager->lock);
}

int add_packet(PacketManager *manager, int packet_id, time_t timestamp, size_t payload_size) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_PACKETS) {
        pthread_mutex_unlock(&manager->lock);
        // Handle max packets limit exceeded
        return -1;
    }
    for (int i = 0; i < manager->count; i++) {
        if (manager->packets[i].packet_id == packet_id) {
            pthread_mutex_unlock(&manager->lock);
            // Handle duplicate packet ID
            return -2;
        }
    }
    manager->packets[manager->count].packet_id = packet_id;
    manager->packets[manager->count].timestamp = timestamp;
    manager->packets[manager->count].payload_size = payload_size;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    // Log packet addition
    return 0;
}

int remove_packet(PacketManager *manager, int packet_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->packets[i].packet_id == packet_id) {
            // Shift elements to fill the gap
            memmove(&manager->packets[i], &manager->packets[i + 1], (manager->count - i - 1) * sizeof(DataPacket));
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            // Log packet removal
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    // Handle packet not found
    return -1;
}

int get_packet_count(PacketManager *manager) {
    int count = manager->count;
    return count;
}

void sort_packets_by_timestamp(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    qsort(manager->packets, manager->count, sizeof(DataPacket), compare_packets);
    pthread_mutex_unlock(&manager->lock);
}

int compare_packets(const void *a, const void *b) {
    DataPacket *packet_a = (DataPacket *)a;
    DataPacket *packet_b = (DataPacket *)b;
    return (packet_a->timestamp > packet_b->timestamp) - (packet_a->timestamp < packet_b->timestamp);
}
