#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int *data;
    int front, rear;
    int capacity;
    pthread_mutex_t lock;
    sem_t not_empty, not_full;
} ThreadSafeQueue;

ThreadSafeQueue* create_queue(int initial_capacity) {
    ThreadSafeQueue *queue = (ThreadSafeQueue*)malloc(sizeof(ThreadSafeQueue));
    queue->data = (int*)malloc(initial_capacity * sizeof(int));
    queue->front = queue->rear = -1;
    queue->capacity = initial_capacity;
    pthread_mutex_init(&queue->lock, NULL);
    sem_init(&queue->not_empty, 0, 0);
    sem_init(&queue->not_full, 0, initial_capacity);
    return queue;
}

void destroy_queue(ThreadSafeQueue *queue) {
    free(queue->data);
    pthread_mutex_destroy(&queue->lock);
    sem_destroy(&queue->not_empty);
    sem_destroy(&queue->not_full);
    free(queue);
}

int enqueue(ThreadSafeQueue *queue, int item) {
    pthread_mutex_lock(&queue->lock);
    while (is_full(queue)) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->data[queue->rear] = item;
    sem_post(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue(ThreadSafeQueue *queue, int *item, int timeout) {
    pthread_mutex_lock(&queue->lock);
    while (is_empty(queue)) {
        if (sem_timedwait(&queue->not_empty, get_timeout(timeout)) != 0) {
            pthread_mutex_unlock(&queue->lock);
            return -1; // Timeout
        }
    }
    *item = queue->data[queue->front];
    queue->front = (queue->front + 1) % queue->capacity;
    sem_post(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int is_empty(ThreadSafeQueue *queue) {
    return (queue->front == -1);
}

int is_full(ThreadSafeQueue *queue) {
    return ((queue->rear + 1) % queue->capacity == queue->front);
}

void adjust_capacity(ThreadSafeQueue *queue, int new_capacity) {
    pthread_mutex_lock(&queue->lock);
    int *new_data = (int*)malloc(new_capacity * sizeof(int));
    for (int i = 0; i < queue->size; i++) {
        new_data[i] = queue->data[(queue->front + i) % queue->capacity];
    }
    free(queue->data);
    queue->data = new_data;
    queue->front = 0;
    queue->rear = queue->size - 1;
    queue->capacity = new_capacity;
    sem_post(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
}

int get_timeout(int timeout_ms) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1000000;
    if (ts.tv_nsec >= 1000000000) {
        ts.tv_sec++;
        ts.tv_nsec -= 1000000000;
    }
    return ts;
}
