// LogEntryManager.h
#pragma once

#include <string>
#include <vector>
#include <unordered_map>

class LogEntry {
public:
    int entry_id;
    std::string timestamp;
    std::string log_level;
    std::string message;

    LogEntry(int id, const std::string& ts, const std::string& level, const std::string& msg)
        : entry_id(id), timestamp(ts), log_level(level), message(msg) {}
};

class LogEntryManager {
private:
    std::unordered_map<int, LogEntry> entries;
    int nextId;

public:
    LogEntryManager() : nextId(1) {}

    void addEntry(const LogEntry& entry);
    bool removeEntry(int id);
    size_t getTotalEntries() const;
    std::vector<LogEntry> getEntriesByLevel(const std::string& level);
    std::vector<LogEntry> getEntriesSinceTimestamp(const std::string& timestamp);
};

// LogEntryManager.cpp
#include "LogEntryManager.h"

void LogEntryManager::addEntry(const LogEntry& entry) {
    entries[entry.entry_id] = entry;
}

bool LogEntryManager::removeEntry(int id) {
    if (entries.find(id) != entries.end()) {
        entries.erase(id);
        return true;
    }
    return false;
}

size_t LogEntryManager::getTotalEntries() const {
    return entries.size();
}

std::vector<LogEntry> LogEntryManager::getEntriesByLevel(const std::string& level) {
    std::vector<LogEntry> result;
    for (const auto& entry : entries) {
        if (entry.second.log_level == level) {
            result.push_back(entry.second);
        }
    }
    return result;
}

std::vector<LogEntry> LogEntryManager::getEntriesSinceTimestamp(const std::string& timestamp) {
    std::vector<LogEntry> result;
    for (const auto& entry : entries) {
        if (entry.second.timestamp >= timestamp) {
            result.push_back(entry.second);
        }
    }
    return result;
}

