#define MAX_PACKETS 1024
#define RETRY_COUNT 5

typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct PacketManager {
    DataPacket packets[MAX_PACKETS];
    size_t count;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->count = 0;
}

int add_packet(PacketManager *manager, int packet_id, time_t timestamp, size_t payload_size) {
    if (manager->count >= MAX_PACKETS) return -1; // Overflow
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i].packet_id == packet_id) return -2; // Duplicate ID
    }
    manager->packets[manager->count++] = (DataPacket){packet_id, timestamp, payload_size};
    return 0;
}

int remove_packet(PacketManager *manager, int packet_id) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i].packet_id == packet_id) {
            for (; i + 1 < manager->count; ++i) {
                manager->packets[i] = manager->packets[i + 1];
            }
            --manager->count;
            return 0;
        }
    }
    return -3; // Packet not found
}

size_t get_packet_count(PacketManager *manager) {
    return manager->count;
}

void sort_packets_by_timestamp(PacketManager *manager) {
    for (size_t i = 0; i < manager->count - 1; ++i) {
        for (size_t j = 0; j < manager->count - i - 1; ++j) {
            if (manager->packets[j].timestamp > manager->packets[j + 1].timestamp) {
                DataPacket temp = manager->packets[j];
                manager->packets[j] = manager->packets[j + 1];
                manager->packets[j + 1] = temp;
            }
        }
    }
}

