    size_t new_count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i].payload_size >= min_size && manager->packets[i].payload_size <= max_size) {
            manager->packets[new_count++] = manager->packets[i];
        }
    }
    manager->count = new_count;
    return 0;
}

int main() {
    PacketManager pm;
    init_packet_manager(&pm);

    // Add packets
    add_packet(&pm, 1, time(NULL), 1024);
    add_packet(&pm, 2, time(NULL) + 3600, 2048);

    // Remove packet
    remove_packet(&pm, 1);

    // Get packet count
    printf("Packet count: %zu\n", get_packet_count(&pm));

    // Sort packets by timestamp
    sort_packets_by_timestamp(&pm);

    // Filter packets by payload size
    filter_packets_by_payload_size(&pm, 1024, 3072);

    return 0;
}
