bool verifyOAuth2Token(const char *tokenJson) {
    // Parse JSON object
    struct json_object *parsed_json;
    parsed_json = json_tokener_parse(tokenJson);

    // Check if parsing was successful
    if (parsed_json == NULL) {
        fprintf(stderr, "Error parsing JSON: %s\n", json_get_error_msg());
        return false;
    }

    // Extract required fields
    struct json_object *access_token, *expires_in, *token_type, *refresh_token;
    bool has_refresh_token = false;

    if (!json_object_object_get_ex(parsed_json, "access_token", &access_token) ||
        !json_object_object_get_ex(parsed_json, "expires_in", &expires_in) ||
        !json_object_object_get_ex(parsed_json, "token_type", &token_type)) {
        fprintf(stderr, "Missing required fields in token JSON.\n");
        json_object_put(parsed_json);
        return false;
    }

    if (json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token)) {
        has_refresh_token = true;
    }

    // Validate access_token type and expires_in
    if (strcmp(json_object_get_string(token_type), "Bearer") != 0) {
        fprintf(stderr, "Invalid token type. Expected 'Bearer'.\n");
        json_object_put(parsed_json);
        return false;
    }

    if (!json_object_is_type(expires_in, json_type_int)) {
        fprintf(stderr, "expires_in must be an integer.\n");
        json_object_put(parsed_json);
        return false;
    }

    int exp = json_object_get_int(expires_in);
    if (exp <= 0) {
        fprintf(stderr, "expires_in must be a positive integer.\n");
        json_object_put(parsed_json);
        return false;
    }

    // Perform additional checks and validations here

    // Clean up
    json_object_put(parsed_json);

    // Return true if all checks pass
    return true;
}
