void free_transaction_data(TransactionData* data) {
    for (int i = 0; i < data->count; i++) {
        free(data->transactions[i].date);
        free(data->transactions[i].type);
    }
    free(data->transactions);
}

int process_csv_file(const char* filename, TransactionData* data) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    size_t buffer_size = 0;
    char* line_buffer = NULL;
    int result = 0;

    while ((line_buffer = fgets(line_buffer, MAX_LINE_LENGTH, file)) != NULL) {
        if (data->count >= data->allocated_size) {
            data->allocated_size += 100;
            data->transactions = realloc(data->transactions, data->allocated_size * sizeof(Transaction));
            if (!data->transactions) {
                perror("Memory allocation failed");
                result = -1;
                break;
            }
        }

        Transaction* transaction = &data->transactions[data->count++];
        sscanf(line_buffer, "%s,%lf,%s", transaction->date, &transaction->amount, transaction->type);

        // Simulate payment gateway API validation
        if (simulate_api_validation(transaction->amount) != 0) {
            printf("Validation error for transaction %d\n", data->count);
        }
    }

    free(line_buffer);
    fclose(file);
    return result;
}

