    strcpy(newEntry->timestamp, timestamp);
    strcpy(newEntry->eventType, eventType);
    newEntry->metrics = (int *)malloc(numMetrics * sizeof(int));
    memcpy(newEntry->metrics, metrics, numMetrics * sizeof(int));
    newEntry->numMetrics = numMetrics;
    newEntry->next = NULL;
    return newEntry;
}

