Entry* processLogFile(const char *filename) {
    Entry *head = NULL, **tail = &head;
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return head;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Assuming the log format: timestamp,eventType,metric1,metric2,...
        char *timestamp = strtok(line, ",");
        char *eventType = strtok(NULL, ",");
        int numMetrics = 0;
        for (char *token = strtok(NULL, ","); token != NULL; token = strtok(NULL, ",")) {
            numMetrics++;
        }

        int *metrics = (int *)malloc(numMetrics * sizeof(int));
        char *metricStrs[numMetrics];
        int i = 0;
        for (char *token = strtok(line, ","); token != NULL; token = strtok(NULL, ",")) {
            metricStrs[i++] = token;
        }

        for (i = 0; i < numMetrics; i++) {
            metrics[i] = atoi(metricStrs[i]);
        }

        Entry *newEntry = createEntry(timestamp, eventType, metrics, numMetrics);
        *tail = newEntry;
        tail = &(*tail)->next;

        free(metrics);
    }

    fclose(file);
    return head;
}

