#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <curl/curl.h>

#define MAX_ENTITIES 10000

typedef struct {
    char *ticker;
    double last_price;
    int volume;
    double historical_prices[30];
} market_entity;

typedef struct {
    time_t timestamp;
    double price;
    int volume;
    char *json_response;
} data_point;

int fetch_and_store_data(market_entity entities[], size_t num_entities, const char *api_endpoints[]) {
    CURL *curl;
    CURLcode res;
    size_t num_endpoints = 0;
    while (api_endpoints[num_endpoints]) num_endpoints++;

    data_point *data_points = malloc(num_endpoints * sizeof(data_point));
    if (!data_points) return -1;

    for (size_t i = 0; i < num_endpoints; i++) {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if (curl) {
            struct MemoryStruct chunk;
            chunk.memory = malloc(1);  // will be grown as needed by the realloc above
            chunk.size = 0;    // no data at this point

            curl_easy_setopt(curl, CURLOPT_URL, api_endpoints[i]);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                free(chunk.memory);
                continue;
            }

            data_points[i].timestamp = time(NULL);
            data_points[i].price = atof(chunk.memory);  // Simplified parsing
            data_points[i].volume = atoi(strstr(chunk.memory, "Volume:") + strlen("Volume:"));
            data_points[i].json_response = strdup(chunk.memory);

            curl_easy_cleanup(curl);
        }
        free(chunk.memory);
    }

    for (size_t i = 0; i < num_entities; i++) {
        for (size_t j = 0; j < num_endpoints; j++) {
            // Update entity based on incoming data
            if (strcmp(entities[i].ticker, api_endpoints[j]) == 0) {
                entities[i].last_price = data_points[j].price;
                entities[i].volume = data_points[j].volume;
                break;
            }
        }
    }

    free(data_points);
    curl_global_cleanup();

    return 0;
}

size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        // out of memory!
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

int main() {
    market_entity entities[MAX_ENTITIES];
    // Initialize entities...

    const char *api_endpoints[] = {"http://api.example.com/stock1", "http://api.example.com/stock2", NULL};

    if (fetch_and_store_data(entities, MAX_ENTITIES, api_endpoints) != 0) {
        fprintf(stderr, "Failed to fetch and store data\n");
        return 1;
    }

    // Process entities...

    return 0;
}
