// Define subscription statuses as an enum for clarity and ease of management.
enum class SubscriptionStatus { Active, Pending, Inactive };

// Forward declaration to avoid circular dependency issues.
class UserProfileManager;

// Define a struct to hold the user profile data.
struct UserProfile {
    char* username;
    SubscriptionStatus status;
    std::vector<std::string> preferences;
};

// Define a class to manage the collection of user profiles.
class UserProfileManager {
private:
    std::vector<UserProfile*> profiles; // Vector of pointers to user profiles
    std::mutex profilesMutex;            // Mutex for thread-safe operations

public:
    ~UserProfileManager() {
        // Clean up dynamically allocated memory
        for (auto profile : profiles) {
            delete[] profile->username;
            delete profile;
        }
    }

    void addProfile(const char* username, SubscriptionStatus status, const std::vector<std::string>& preferences) {
        std::lock_guard<std::mutex> lock(profilesMutex);
        UserProfile* newProfile = new UserProfile();
        newProfile->username = strdup(username); // Duplicate the username string
        newProfile->status = status;
        newProfile->preferences = preferences;
        profiles.push_back(newProfile);
    }

    void updateStatus(const char* username, SubscriptionStatus newStatus) {
        std::lock_guard<std::mutex> lock(profilesMutex);
        for (auto profile : profiles) {
            if (strcmp(profile->username, username) == 0) {
                profile->status = newStatus;
                break;
            }
        }
    }

    void exportProfiles(const char* filename, char delimiter = ',') {
        std::lock_guard<std::mutex> lock(profilesMutex);
        std::ofstream file(filename);
        if (file.is_open()) {
            for (auto profile : profiles) {
                file << profile->username << delimiter;
                switch (profile->status) {
                    case SubscriptionStatus::Active: file << "Active"; break;
                    case SubscriptionStatus::Pending: file << "Pending"; break;
                    case SubscriptionStatus::Inactive: file << "Inactive"; break;
                }
                for (const auto& preference : profile->preferences) {
                    file << delimiter << preference;
                }
                file << std::endl;
            }
            file.close();
        } else {
            std::cerr << "Unable to open file for writing." << std::endl;
        }
    }

    // Method to handle potential out-of-memory situations gracefully
    void handleOutOfMemory() {
        try {
            throw std::bad_alloc(); // Simulate an OOM situation
        } catch (const std::bad_alloc& e) {
            std::cerr << "Out of memory error: " << e.what() << std::endl;
            // Implement your strategy here, like logging the error or retrying later
        }
    }

    // Method to safely iterate over the profiles
    void safeIterateProfiles(void (*callback)(const UserProfile*)) {
        std::lock_guard<std::mutex> lock(profilesMutex);
        for (auto profile : profiles) {
            callback(profile);
        }
    }
};

// Example usage of the class
int main() {
    UserProfileManager manager;
    manager.addProfile("user1", SubscriptionStatus::Active, {"email", "notifications"});
    manager.updateStatus("user1", SubscriptionStatus::Pending);
    manager.exportProfiles("profiles.csv");

    // Handle potential out-of-memory situation
    try {
        manager.handleOutOfMemory();
    } catch (...) {}

    // Safe iteration over profiles
    manager.safeIterateProfiles([](const UserProfile* profile) {
        std::cout << "User: " << profile->username << ", Status: ";
        switch (profile->status) {
            case SubscriptionStatus::Active: std::cout << "Active"; break;
            case SubscriptionStatus::Pending: std::cout << "Pending"; break;
            case SubscriptionStatus::Inactive: std::cout << "Inactive"; break;
        }
        std::cout << ", Preferences: ";
        for (const auto& pref : profile->preferences) {
            std::cout << pref << " ";
        }
        std::cout << std::endl;
    });

    return 0;
}
