#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} PacketManager;

void init_packet_manager(PacketManager* pm, size_t initial_capacity) {
    pm->packets = (DataPacket*)malloc(initial_capacity * sizeof(DataPacket));
    if (pm->packets == NULL) {
        fprintf(stderr, "Failed to allocate memory for packet manager\n");
        exit(EXIT_FAILURE);
    }
    pm->count = 0;
    pm->capacity = initial_capacity;
    pthread_mutex_init(&pm->lock, NULL);
    pthread_cond_init(&pm->not_full, NULL);
    pthread_cond_init(&pm->not_empty, NULL);
}

void destroy_packet_manager(PacketManager* pm) {
    free(pm->packets);
    pthread_mutex_destroy(&pm->lock);
    pthread_cond_destroy(&pm->not_full);
    pthread_cond_destroy(&pm->not_empty);
}

int add_packet(PacketManager* pm, DataPacket packet) {
    pthread_mutex_lock(&pm->lock);
    while (pm->count == pm->capacity) {
        pthread_cond_wait(&pm->not_full, &pm->lock);
    }
    pm->packets[pm->count++] = packet;
    pthread_cond_signal(&pm->not_empty);
    pthread_mutex_unlock(&pm->lock);
    return 0; // Success
}

int remove_packet(PacketManager* pm, int packet_id) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i].packet_id == packet_id) {
            memmove(&pm->packets[i], &pm->packets[i + 1], (pm->count - i - 1) * sizeof(DataPacket));
            --pm->count;
            pthread_cond_signal(&pm->not_full);
            pthread_mutex_unlock(&pm->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&pm->lock);
    return -1; // Packet not found
}

size_t get_packet_count(const PacketManager* pm) {
    return pm->count;
}

int sort_packets_by_timestamp(PacketManager* pm) {
    qsort(pm->packets, pm->count, sizeof(DataPacket), [](const void* a, const void* b) {
        return ((DataPacket*)a)->timestamp - ((DataPacket*)b)->timestamp;
    });
    return 0; // Success
}
```

This code snippet provides the basic structure for managing a dynamic array of `DataPacket` structures in a multi-threaded environment. It includes initialization, destruction, adding packets, removing packets, retrieving packet count, and sorting packets by timestamp. The implementation uses mutexes and condition variables to ensure thread safety during concurrent access.']

