import csv
from collections import defaultdict

def process_csv_file(file_path, target_columns):
    column_frequencies = {col: defaultdict(int) for col in target_columns}

    with open(file_path, mode='r', newline='') as file:
        reader = csv.DictReader(file)
        for row in reader:
            for col in target_columns:
                value = row[col]
                if value not in (None, ''):
                    column_frequencies[col][value] += 1

