import hashlib
import os
import logging
from concurrent.futures import ThreadPoolExecutor, as_completed

def calculate_hash(file_path, hash_algorithms=['md5', 'sha256'], offset=0, progress_callback=None):
    def hash_chunk(chunk):
        return {alg: getattr(hashlib, alg)().update(chunk.encode('utf-8')).hexdigest() for alg in hash_algorithms}

    def read_chunks(file_path, chunk_size=4*1024*1024):
        with open(file_path, 'rb') as f:
            f.seek(offset)
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                yield data

    hash_results = {alg: '' for alg in hash_algorithms}
    chunks_processed = 0
    total_chunks = sum(1 for _ in read_chunks(file_path))

    with ThreadPoolExecutor() as executor:
        futures = [executor.submit(hash_chunk, chunk) for chunk in read_chunks(file_path)]
        for future in as_completed(futures):
            result = future.result()
            for alg, value in result.items():
                hash_results[alg] += value
            chunks_processed += 1
            if progress_callback:
                progress_callback(chunks_processed / total_chunks)

    return hash_results

# Example usage
if __name__ == "__main__":
    file_path = 'path_to_large_file'
    known_md5_hash = 'known_md5_hash_value'
    known_sha256_hash = 'known_sha256_hash_value'

    result = calculate_hash(file_path, ['md5', 'sha256'], progress_callback=lambda x: print(f'Progress: {x*100:.2f}%'))

    if result['md5'] == known_md5_hash and result['sha256'] == known_sha256_hash:
        print('File integrity verified.')
    else:
        print('File integrity compromised.')
```

