int validate_transaction(Transaction transaction, double *converted_amount) {
    // Simulate payment gateway validation
    if (strcmp(transaction.currency, "USD") != 0) {
        return VALIDATION_ERROR;
    }
    *converted_amount = transaction.amount; // Simplified conversion for demonstration
    return SUCCESS;
}

ValidationResult process_transaction(Transaction transaction, double *total_amount) {
    double converted_amount;
    ValidationResult result = validate_transaction(transaction, &converted_amount);

    if (result == VALIDATION_ERROR) {
        log_event("Validation error: Invalid currency");
        return result;
    }

    if (result == API_FAILURE) {
        log_event("API failure: Request timed out or failed");
        return result;
    }

    *total_amount += converted_amount;
    printf("Processed transaction for %s - Amount: %.2f\n", transaction.date, converted_amount);
    return SUCCESS;
}

