    Transaction current_transaction;
    double total_transactions_by_type[10] = { 0 };
    int validation_errors = 0, api_failures = 0;

    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%[^,],%lf,%[^,],%2s", 
                   current_transaction.date,
                   &current_transaction.amount,
                   current_transaction.type,
                   current_transaction.currency) != 4) {
            log_event("Error parsing CSV line");
            continue;
        }

        ValidationResult result = process_transaction(current_transaction, &total_transactions_by_type);
        if (result == VALIDATION_ERROR) validation_errors++;
        else if (result == API_FAILURE) api_failures++;

        // Track totals by transaction type
        for (int i = 0; i < 10; i++) {
            if (strcmp(current_transaction.type, types[i]) == 0) {
                total_transactions_by_type[i] += current_transaction.amount;
                break;
            }
        }
    }

    fclose(file);
    printf("Total transactions by type:\n");
    for (int i = 0; i < 10; i++) {
        if (total_transactions_by_type[i] > 0) {
            printf("%s: %.2f\n", types[i], total_transactions_by_type[i]);
        }
    }

    printf("Validation errors: %d, API failures: %d\n", validation_errors, api_failures);

    return EXIT_SUCCESS;
}
