#define MAX_LOG_SIZE 1024

typedef struct {
    int id;
    time_t timestamp;
    char message[MAX_LOG_SIZE];
} LogEntry;

typedef struct {
    LogEntry* logs;
    size_t count;
    size_t capacity;
} LogCollection;

void initLogCollection(LogCollection* collection, size_t initial_capacity) {
    collection->logs = (LogEntry*)malloc(initial_capacity * sizeof(LogEntry));
    collection->count = 0;
    collection->capacity = initial_capacity;
}

void addLogEntry(LogCollection* collection, int id, const char* template_message, va_list args) {
    if (collection->count >= collection->capacity) {
        collection->capacity *= 2;
        collection->logs = (LogEntry*)realloc(collection->logs, collection->capacity * sizeof(LogEntry));
    }

    LogEntry new_entry;
    new_entry.id = id;
    new_entry.timestamp = time(NULL);
    vsnprintf(new_entry.message, MAX_LOG_SIZE, template_message, args);

    // Validate payload
    if (strlen(new_entry.message) < MAX_LOG_SIZE - 1) {
        collection->logs[collection->count++] = new_entry;
    }
}

void cleanupOldLogs(LogCollection* collection, time_t retention_limit, size_t max_size) {
    time_t current_time = time(NULL);

    for (size_t i = 0; i < collection->count; ) {
        if ((current_time - collection->logs[i].timestamp > retention_limit) ||
            strlen(collection->logs[i].message) * sizeof(char) > max_size) {
            for (size_t j = i + 1; j < collection->count; ++j) {
                collection->logs[j - 1] = collection->logs[j];
            }
            --collection->count;
        } else {
            ++i;
        }
    }
}

void freeLogCollection(LogCollection* collection) {
    free(collection->logs);
    collection->logs = NULL;
    collection->count = 0;
    collection->capacity = 0;
}
