#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    int payload_size;
} DataPacket;

typedef struct DynamicArray {
    DataPacket* packets;
    size_t capacity;
    size_t size;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->packets = (DataPacket*)calloc(initial_capacity, sizeof(DataPacket));
    if (!array->packets) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    free(array->packets);
    free(array);
}

int add_packet(DynamicArray* array, DataPacket packet) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        DataPacket* new_packets = (DataPacket*)realloc(array->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) return -1;
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
    array->packets[array->size++] = packet;
    return 0;
}

int remove_packet(DynamicArray* array, int packet_id) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->packets[i].packet_id == packet_id) {
            memmove(&array->packets[i], &array->packets[i + 1], (array->size - i - 1) * sizeof(DataPacket));
            array->size--;
            return 0;
        }
    }
    return -1;
}

size_t get_packet_count(DynamicArray* array) {
    return array->size;
}

int compare_packets(const void* a, const void* b) {
    time_t ts_a = ((DataPacket*)a)->timestamp;
    time_t ts_b = ((DataPacket*)b)->timestamp;
    if (ts_a < ts_b) return -1;
    if (ts_a > ts_b) return 1;
    return 0;
}

void sort_packets_by_timestamp(DynamicArray* array) {
    qsort(array->packets, array->size, sizeof(DataPacket), compare_packets);
}
