    LogLevel min_log_level;
    LogDestination** destinations;
    int num_destinations;
    int delay_ms;
    int rate_limit_per_sec;
} LoggingConfig;

// Function to log a message with conditions
void log_message_with_conditions(LoggingConfig* config, LogMessage* msg) {
    // Check if the message level is within the allowed range
    if (msg->level < config->min_log_level) {
        return;
    }

    // Lock for thread safety
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    // Iterate through all destinations and log the message
    for (int i = 0; i < config->num_destinations; i++) {
        LogDestination* dest = config->destinations[i];
        switch (dest->type) {
            case DEST_FILE:
                fprintf(dest->file, "[%s] %s\n", get_log_level_str(msg->level), msg->message);
                break;
            // Handle network logging here
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lock);

    // Apply rate limiting if necessary
    apply_rate_limiting(config);
}

// Helper function to get log level string
