#include <forward_list>
#include <limits>

void insertAfterOrAppend(std::forward_list<int>& myList, int searchValue, int newValue) {
    if (myList.size() >= std::numeric_limits<std::forward_list<int>::size_type>::max() - 1) {
        // Handle overflow or close to limit
        return;
    }

    auto it = myList.begin();
    while (it != myList.end()) {
        if (*it == searchValue) {
            // Insert after found value
            ++it;
            myList.insert(it, newValue);
            return;
        }
        ++it;
    }

    // Append if not found
    myList.push_front(newValue);
}
