    {
        if (string.IsNullOrEmpty(token))
        {
            Console.WriteLine("Token is empty.");
            return false;
        }

        var tokenParts = token.Split(' ');
        if (tokenParts.Length != 2 || tokenParts[0] != "Bearer")
        {
            Console.WriteLine("Invalid token type.");
            return false;
        }

        string accessToken = tokenParts[1];
        JObject tokenObject = EncryptionManager.ParseJson(accessToken);
        if (!tokenObject.ContainsKey("expires_in"))
        {
            Console.WriteLine("Token missing 'expires_in' field.");
            return false;
        }

        int expiresIn = (int)tokenObject["expires_in"];
        if (expiresIn <= 0)
        {
            Console.WriteLine("'expires_in' must be a positive integer.");
            return false;
        }

        // Additional validation logic can be added here

        return true;
    }
}
