from flask import Flask, request, jsonify
import requests

app = Flask(__name__)

# Simulated external data source using a dictionary
external_data_source = {
    "1": {"id": "1", "name": "Resource 1", "description": "Description 1"},
    "2": {"id": "2", "name": "Resource 2", "description": "Description 2"}
}

def fetch_resource_from_external_source(resource_id):
    try:
        response = requests.get(f"http://external-data-source.com/resources/{resource_id}")
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception("Failed to fetch resource from external data source")
    except requests.exceptions.RequestException as e:
        raise Exception(f"Network error: {e}")

def update_resource_in_external_source(resource_id, updated_data):
    try:
        response = requests.put(f"http://external-data-source.com/resources/{resource_id}", json=updated_data)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception("Failed to update resource in external data source")
    except requests.exceptions.RequestException as e:
        raise Exception(f"Network error: {e}")

@app.route('/api/resources/<resource_id>', methods=['PUT'])
def update_resource(resource_id):
    try:
        updated_data = request.get_json()
        if not updated_data:
            return jsonify({"error": "No data provided"}), 400

        external_source_data = fetch_resource_from_external_source(resource_id)
        for key, value in updated_data.items():
            external_source_data[key] = value

        updated_resource = update_resource_in_external_source(resource_id, external_source_data)
        return jsonify(updated_resource), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/resources/<resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    try:
        response = requests.delete(f"http://external-data-source.com/resources/{resource_id}")
        if response.status_code == 204:
            return "", 204
        else:
            raise Exception("Failed to delete resource from external data source")
    except requests.exceptions.RequestException as e:
        return jsonify({"error": f"Network error: {e}"}), 500

if __name__ == '__main__':
    app.run(debug=True)
