using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Xml.XPath;

public class XmlParser
{
    private static readonly Dictionary<string, XPathDocument> cache = new Dictionary<string, XPathDocument>(StringComparer.OrdinalIgnoreCase);

    public List<XmlResultItem> Parse(string xml, string xpathExpression, int maxDepth = 10)
    {
        if (string.IsNullOrEmpty(xpathExpression))
            throw new ArgumentException("XPath expression cannot be null or empty.");

        if (maxDepth < 1)
            throw new ArgumentOutOfRangeException(nameof(maxDepth), "Max depth must be greater than 0.");

        XPathDocument document;
        lock (cache)
        {
            if (!cache.TryGetValue(xml, out document))
            {
                document = new XPathDocument(new System.IO.StringReader(xml));
                cache[xml] = document;
            }
        }

        try
        {
            var navigator = document.CreateNavigator();
            var nodes = navigator.Select(xpathExpression);

            if (nodes.Count() > 1)
                throw new InvalidOperationException("More than one element matches the criteria.");

            var results = new List<XmlResultItem>();
            foreach (var node in nodes.Cast<XPathNavigator>().TakeWhile((n, i) => i < maxDepth))
            {
                var result = new XmlResultItem
                {
                    Name = node.LocalName,
                    Attributes = node.GetAttributes().Cast<XPathVariableInfo>().ToDictionary(a => a.Name, a => a.Value),
                    InnerText = node.InnerXml
                };
                results.Add(result);
            }

            return results;
        }
        catch (XPathException)
        {
            throw new InvalidOperationException("Invalid XPath expression.");
        }
        catch (XmlException)
        {
            throw new InvalidOperationException("Malformed XML.");
        }
    }
}

public class XmlResultItem
{
    public string Name { get; set; }
    public Dictionary<string, string> Attributes { get; set; } = new Dictionary<string, string>();
    public string InnerText { get; set; }
}
