    public async Task<bool> UpdateDocumentAsync(string sessionId, string documentId, string updatedContent)
    {
        // Validate user session
        if (!_sessionStore.IsValidSession(sessionId))
        {
            _logger.LogWarning("Invalid session ID provided.");
            return false;
        }

        // Validate document metadata
        var documentMetadata = await _documentMetadataRepository.GetDocumentAsync(documentId);
        if (documentMetadata == null)
        {
            _logger.LogError("Document not found for the given ID.");
            return false;
        }

        // Sanitize and validate document content
        updatedContent = SanitizeContent(updatedContent);

        // Update document in all services
        var tasks = new List<Task<bool>>();
        foreach (var serviceEndpoint in documentMetadata.ServiceEndpoints)
        {
            tasks.Add(UpdateDocumentOnServiceAsync(serviceEndpoint, documentId, updatedContent));
        }

        await Task.WhenAll(tasks);

        // Check if any service update failed
        if (tasks.Any(t => !t.Result))
        {
            _logger.LogError("Failed to update document on one or more services.");
            return false;
        }

        // Log successful update and determine if reload is needed
        _logger.LogInformation("Document updated successfully.");
        bool shouldReload = ShouldReload(documentMetadata, updatedContent);

        return shouldReload;
    }

