// Function to process and test
void processAndTest(const char* modulePath, TestCase* tests, int numTests, int maxConcurrency) {
    // Load module dynamically
    void* handle = dlopen(modulePath, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to load module: %s\n", dlerror());
        return;
    }

    // Execute tests concurrently up to maxConcurrency
    pthread_t threads[maxConcurrency];
    int thread_count = 0;

    for (int i = 0; i < numTests; i++) {
        if (thread_count >= maxConcurrency) {
            for (int j = 0; j < maxConcurrency; j++) {
                pthread_join(threads[j], NULL);
            }
            thread_count = 0;
        }

        int* test_index = malloc(sizeof(int));
        *test_index = i;

        if (pthread_create(&threads[thread_count], NULL, (void*)tests[i].f, test_index) != 0) {
            fprintf(stderr, "Failed to create thread for test %s\n", tests[i].label);
            free(test_index);
            continue;
        }

        thread_count++;
    }

    // Wait for remaining threads
    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Close module handle
    dlclose(handle);
}

