    int* index = (int*)arg;
    TestCase* tests = (TestCase*)(index + 1);

    log_start(tests[*index].label);
    mock_init();
    tests[*index].f();
    mock_reset();
    check_memory_threshold(1024 * 1024); // Example threshold
