async function handleNetworkStream(inputStream) {
    const bufferPool = new BufferPool();
    let dataBuffer = bufferPool.getBuffer();
    let totalBytesReceived = 0;

    for await (const chunk of inputStream) {
        totalBytesReceived += chunk.length;
        if (dataBuffer.length < totalBytesReceived + byteOffset + numBytes) {
            dataBuffer = bufferPool.resize(dataBuffer, Math.max(2 * dataBuffer.length, totalBytesReceived + byteOffset + numBytes));
        }
        chunk.copy(dataBuffer, byteOffset);
    }

    return dataBuffer.slice(byteOffset, byteOffset + numBytes);
}

class BufferPool {
    constructor() {
        this.buffers = [];
    }

    getBuffer(size = 1024) {
        if (this.buffers.length > 0) {
            return this.buffers.pop();
        }
        return Buffer.alloc(size);
    }

    resize(buffer, newSize) {
        const newBuffer = this.getBuffer(newSize);
        buffer.copy(newBuffer);
        this.release(buffer);
        return newBuffer;
    }

    release(buffer) {
        buffer.fill(0); // Clear the buffer
        this.buffers.push(buffer);
    }
}

