['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include "tiffio.h"

typedef struct TreeNode {
    char *path;
    struct TreeNode *left, *right;
} TreeNode;

TreeNode* createNode(char *path) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    node->path = strdup(path);
    node->left = node->right = NULL;
    return node;
}

void insertNode(TreeNode** root, char *path) {
    if (*root == NULL) {
        *root = createNode(path);
    } else if (strcmp(path, (*root)->path) < 0) {
        insertNode(&(*root)->left, path);
    } else if (strcmp(path, (*root)->path) > 0) {
        insertNode(&(*root)->right, path);
    }
}

TreeNode* searchNode(TreeNode *root, char *key) {
    if (root == NULL || strcmp(root->path, key) == 0)
        return root;
    if (strcmp(key, root->path) < 0)
        return searchNode(root->left, key);
    return searchNode(root->right, key);
}

int isBST(TreeNode* root, char* min, char* max) {
    if (root == NULL)
        return 1;
    if (min != NULL && strcmp(root->path, min) <= 0)
        return 0;
    if (max != NULL && strcmp(root->path, max) >= 0)
        return 0;
    return isBST(root->left, min, root->path) &&
           isBST(root->right, root->path, max);
}

void freeTree(TreeNode* node) {
    if (node == NULL)
        return;
    free(node->path);
    freeTree(node->left);
    freeTree(node->right);
    free(node);
}

int parseTiffAndEncrypt(const char *tiffPath, const char *operation) {
    // Parse TIFF file logic here
    FILE *file = fopen(tiffPath, "rb");
    if (!file) {
        fprintf(stderr, "Error opening TIFF file\n");
        return -1;
    }
    TIFF *tiff = TIFFOpen(tiffPath, "r");
    if (!tiff) {
        fclose(file);
        fprintf(stderr, "Error reading TIFF file\n");
        return -2;
    }

    uint32_t bitsPerSample;
    uint16_t samplesPerPixel;
    uint16_t extraSamplesCount;

    // Extract image information from TIFF
    TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);
    TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);
    TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &extraSamplesCount);

    // Validate bits per sample
    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 &&
        bitsPerSample != 8 && bitsPerSample != 16) {
        fprintf(stderr, "Unsupported bits per sample\n");
        TIFFClose(tiff);
        fclose(file);
        return -3;
    }

    // Create cipher object using OpenSSL
    EVP_CIPHER *cipher = NULL;
    if (strcmp(operation, "encrypt") == 0) {
        cipher = EVP_aes_256_cbc();
    } else if (strcmp(operation, "decrypt") == 0) {
        cipher = EVP_aes_256_cbc();
    } else {
        fprintf(stderr, "Invalid OpenSSL operation\n");
        TIFFClose(tiff);
        fclose(file);
        return -4;
    }

    // Perform encryption or decryption logic here

    // Clean up
    EVP_CIPHER_CTX_free(cipher);
    TIFFClose(tiff);
    fclose(file);

    return 0;
}
