fn create_http_client(url: &str, validate_cert: bool) -> Result<RequestBuilder, reqwest::Error> {
    let mut client = Client::builder();

    if !validate_cert {
        client = client.dangerously_disable_host_verification();
        client = client.dangerously_ignore_ssl_certificate_validation();
    }

    client.timeout(Duration::from_secs(10)).build()?;
    Ok(client.get(url))
