    2: {"id": 2, "name": "Resource 2", "version": 1}
}

# Audit log list
audit_log = []

def validate_resource_data(resource_id, data):
    # Implement your data validation logic here
    pass

def update_resource(resource_id, updated_fields, current_version):
    if resource_id not in resources:
        return None, 404
    resource = resources[resource_id]
    if resource["version"] != current_version:
        return None, 412
    for field, value in updated_fields.items():
        resource[field] = value
    resource["version"] += 1
    return resource, 200

def delete_resource(resource_id):
    if resource_id not in resources:
        return 404
    del resources[resource_id]
    return 204

@app.route('/api/resources/<int:resource_id>', methods=['PUT'])
def update_endpoint(resource_id):
    data = request.json
    current_version = data.get('version')
    updated_fields = {key: value for key, value in data.items() if key != 'id' and key != 'version'}

    # Validate the data
    validation_result = validate_resource_data(resource_id, updated_fields)
    if validation_result is not None:
        return jsonify(validation_result), 400

    resource, status_code = update_resource(resource_id, updated_fields, current_version)
    if resource is not None:
        audit_log.append({"action": "update", "user": "admin", "timestamp": time.time(), "resource_id": resource_id})
    return jsonify(resource), status_code

@app.route('/api/resources/<int:resource_id>', methods=['DELETE'])
def delete_endpoint(resource_id):
    if resource_id not in resources:
        return 404
    status_code = delete_resource(resource_id)
    audit_log.append({"action": "delete", "user": "admin", "timestamp": time.time(), "resource_id": resource_id})
    return '', status_code

if __name__ == '__main__':
    app.run(debug=True)
