#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ENTRIES 1000

typedef enum {
    SRB_TYPE_UM,
    SRB_TYPE_DM
} SRB_Type;

typedef enum {
    RELEASE_CAUSE_NORMAL,
    RELEASE_CAUSE_ERROR,
    RELEASE_CAUSE_TIMEOUT
} Release_Cause;

typedef struct NFAPI_SRB_RELEASE_REQUEST_PDU_T {
    int SRB_ID;
    SRB_Type SRB_TYPE;
    Release_Cause release_cause;
} NFAPI_SRB_RELEASE_REQUEST_PDU_T;

typedef struct HashTableNode {
    NFAPI_SRB_RELEASE_REQUEST_PDU_T data;
    struct HashTableNode *next;
} HashTableNode;

typedef struct HashTable {
    HashTableNode **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t capacity) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->capacity = capacity;
    table->size = 0;
    table->buckets = (HashTableNode**)calloc(capacity, sizeof(HashTableNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableNode *node = table->buckets[i];
        while (node) {
            HashTableNode *next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

size_t hash_function(int SRB_ID, size_t capacity) {
    return SRB_ID % capacity;
}

NFAPI_SRB_RELEASE_REQUEST_PDU_T* insert_entry(HashTable *table, NFAPI_SRB_RELEASE_REQUEST_PDU_T entry) {
    pthread_mutex_lock(&table->lock);
    if (table->size >= table->capacity) {
        pthread_mutex_unlock(&table->lock);
        return NULL;
    }
    size_t index = hash_function(entry.SRB_ID, table->capacity);
    HashTableNode *node = (HashTableNode*)malloc(sizeof(HashTableNode));
    if (!node) {
        pthread_mutex_unlock(&table->lock);
        return NULL;
    }
    node->data = entry;
    node->next = table->buckets[index];
    table->buckets[index] = node;
    ++table->size;
    pthread_mutex_unlock(&table->lock);
    return &node->data;
}

NFAPI_SRB_RELEASE_REQUEST_PDU_T* delete_entry(HashTable *table, int SRB_ID) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(SRB_ID, table->capacity);
    HashTableNode *prev = NULL;
    HashTableNode *node = table->buckets[index];
    while (node) {
        if (node->data.SRB_ID == SRB_ID) {
            if (prev) prev->next = node->next;
            else table->buckets[index] = node->next;
            NFAPI_SRB_RELEASE_REQUEST_PDU_T *entry = &node->data;
            free(node);
            --table->size;
            pthread_mutex_unlock(&table->lock);
            return entry;
        }
        prev = node;
        node = node->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void iterate_over_entries(HashTable *table, void (*callback)(NFAPI_SRB_RELEASE_REQUEST_PDU_T *)) {
    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableNode *node = table->buckets[i];
        while (node) {
            callback(node->data);
            node = node->next;
        }
    }
    pthread_mutex_unlock(&table->lock);
}

int main() {
    srand(time(NULL));
    HashTable *table = create_hash_table(MAX_ENTRIES);
    if (!table) return -1;

    for (int i = 0; i < 500; ++i) {
        NFAPI_SRB_RELEASE_REQUEST_PDU_T entry;
        entry.SRB_ID = i + 1;
        entry.SRB_TYPE = SRB_TYPE_UM;
        entry.release_cause = (Release_Cause)(rand() % 3);
        if (!insert_entry(table, entry)) break;
    }

    iterate_over_entries(table, [](NFAPI_SRB_RELEASE_REQUEST_PDU_T entry) {
        printf("SRB_ID: %d, SRB_TYPE: %d, Release Cause: %d\n", entry.SRB_ID, entry.SRB_TYPE, entry.release_cause);
    });

    destroy_hash_table(table);
    return 0;
}
