using System;
using System.Collections.Concurrent;
using System.IO;
using System.Text.RegularExpressions;

public class UserActivitySummary
{
    public string UserId { get; set; }
    public int TotalLoginAttempts { get; set; }
    public int SuccessfulLogins { get; set; }
    public double AverageSessionDuration { get; set; }
}

public class ProcessLargeCSVFile
{
    private const string LogFilePath = "activity_log.txt";

    public void Execute(string csvFilePath)
    {
        var userActivityCache = new ConcurrentDictionary<string, UserActivitySummary>();

        try
        {
            using (var reader = File.OpenText(csvFilePath))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    ProcessLine(line, userActivityCache);
                }
            }

            GenerateSummaryReport(userActivityCache);
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
        }
    }

    private void ProcessLine(string line, ConcurrentDictionary<string, UserActivitySummary> cache)
    {
        var parts = Regex.Split(line, ",", RegexOptions.Compiled).ToArray();
        if (parts.Length < 4) return; // Skip lines with insufficient data

        try
        {
            string userId = parts[0];
            int loginAttempts = int.Parse(parts[1]);
            bool successfulLogin = bool.Parse(parts[2]);
            double sessionDuration = double.Parse(parts[3]);

            UserActivitySummary summary;
            if (cache.TryGetValue(userId, out summary))
            {
                summary.TotalLoginAttempts += loginAttempts;
                summary.SuccessfulLogins += successfulLogin ? 1 : 0;
                summary.AverageSessionDuration = (summary.AverageSessionDuration * (summary.TotalLoginAttempts - loginAttempts) + sessionDuration) / summary.TotalLoginAttempts;
            }
            else
            {
                cache.TryAdd(userId, new UserActivitySummary
                {
                    UserId = userId,
                    TotalLoginAttempts = loginAttempts,
                    SuccessfulLogins = successfulLogin ? 1 : 0,
                    AverageSessionDuration = sessionDuration
                });
            }
        }
        catch (Exception ex)
        {
            LogError($"Failed to process line: {line}. Error: {ex.Message}");
        }
    }

    private void GenerateSummaryReport(ConcurrentDictionary<string, UserActivitySummary> cache)
    {
        using (var writer = File.CreateText("summary_report.txt"))
        {
            foreach (var entry in cache.Values)
            {
                writer.WriteLine($"{entry.UserId},{entry.TotalLoginAttempts},{entry.SuccessfulLogins},{entry.AverageSessionDuration}");
            }
        }
    }

    private void LogError(string message)
    {
        Console.Error.WriteLine($"[ERROR] {DateTime.Now}: {message}");
        File.AppendAllText(LogFilePath, $"[ERROR] {DateTime.Now}: {message}\n");
    }
}
