#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LOG_LEVELS 5

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} LogLevel;

typedef struct log_buffer {
    char* buffer;
    size_t size;
    pthread_mutex_t mutex;
} LogBuffer;

typedef struct logging_config {
    LogBuffer** buffers;
    size_t num_buffers;
    pthread_mutex_t config_mutex;
} LoggingConfig;

LoggingConfig* initialize_logging_system(size_t num_loggers) {
    if (num_loggers == 0) {
        return NULL;
    }

    LoggingConfig* config = malloc(sizeof(LoggingConfig));
    if (!config) {
        return NULL;
    }

    config->buffers = malloc(num_loggers * sizeof(LogBuffer*));
    if (!config->buffers) {
        free(config);
        return NULL;
    }

    for (size_t i = 0; i < num_loggers; ++i) {
        config->buffers[i] = malloc(sizeof(LogBuffer));
        if (!config->buffers[i]) {
            for (size_t j = 0; j < i; ++j) {
                free(config->buffers[j]);
            }
            free(config->buffers);
            free(config);
            return NULL;
        }

        config->buffers[i]->buffer = malloc(1024); // Initial buffer size
        if (!config->buffers[i]->buffer) {
            for (size_t j = 0; j <= i; ++j) {
                free(config->buffers[j]->buffer);
                free(config->buffers[j]);
            }
            free(config->buffers);
            free(config);
            return NULL;
        }

        config->buffers[i]->size = 1024;
        pthread_mutex_init(&config->buffers[i]->mutex, NULL);
    }

    config->num_buffers = num_loggers;
    pthread_mutex_init(&config->config_mutex, NULL);

    return config;
}

void free_logging_system(LoggingConfig* config) {
    if (config) {
        for (size_t i = 0; i < config->num_buffers; ++i) {
            free(config->buffers[i]->buffer);
            free(config->buffers[i]);
        }
        free(config->buffers);
        pthread_mutex_destroy(&config->config_mutex);
        free(config);
    }
}
