#define MAX_ENTRIES 1000

typedef enum {
    RELEASE_CAUSE_1,
    RELEASE_CAUSE_2,
    // Add more causes as needed
} SRB_Release_Cause;

typedef struct NFAPI_SRB_RELEASE_REQUEST_PDU_T {
    int SRB_ID;
    int SRB_TYPE;
    SRB_Release_Cause SRB_Release_Cause;
    struct NFAPI_SRB_RELEASE_REQUEST_PDU_T *next;
    struct NFAPI_SRB_RELEASE_REQUEST_PDU_T *prev;
} NFAPI_SRB_RELEASE_REQUEST_PDU_T;

typedef struct {
    NFAPI_SRB_RELEASE_REQUEST_PDU_T **buckets;
    size_t bucket_count;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_size) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->bucket_count = initial_size;
    table->buckets = calloc(initial_size, sizeof(NFAPI_SRB_RELEASE_REQUEST_PDU_T*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->bucket_count; ++i) {
        NFAPI_SRB_RELEASE_REQUEST_PDU_T *entry = table->buckets[i];
        while (entry) {
            NFAPI_SRB_RELEASE_REQUEST_PDU_T *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

size_t hash_function(int SRB_ID, size_t bucket_count) {
    // Simple hash function for demonstration purposes
    return (size_t)(SRB_ID % bucket_count);
}

NFAPI_SRB_RELEASE_REQUEST_PDU_T* insert_or_update(HashTable *table, int SRB_ID, int SRB_TYPE, SRB_Release_Cause SRB_Release_Cause) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(SRB_ID, table->bucket_count);
    NFAPI_SRB_RELEASE_REQUEST_PDU_T **entry_ptr = &table->buckets[index];

    while (*entry_ptr) {
        if ((*entry_ptr)->SRB_ID == SRB_ID) {
            // Update existing entry
            (*entry_ptr)->SRB_TYPE = SRB_TYPE;
            (*entry_ptr)->SRB_Release_Cause = SRB_Release_Cause;
            pthread_mutex_unlock(&table->lock);
            return *entry_ptr;
        }
        entry_ptr = &(*entry_ptr)->next;
    }

    if (table->bucket_count == MAX_ENTRIES) {
        pthread_mutex_unlock(&table->lock);
        return NULL; // Maximum capacity reached
    }

    NFAPI_SRB_RELEASE_REQUEST_PDU_T *new_entry = malloc(sizeof(NFAPI_SRB_RELEASE_REQUEST_PDU_T));
    if (!new_entry) {
        pthread_mutex_unlock(&table->lock);
        return NULL; // Memory allocation failed
    }

    new_entry->SRB_ID = SRB_ID;
    new_entry->SRB_TYPE = SRB_TYPE;
    new_entry->SRB_Release_Cause = SRB_Release_Cause;
    new_entry->next = NULL;
    new_entry->prev = NULL;

    *entry_ptr = new_entry;
    pthread_mutex_unlock(&table->lock);
    return new_entry;
}

NFAPI_SRB_RELEASE_REQUEST_PDU_T* find_entry(HashTable *table, int SRB_ID) {
    size_t index = hash_function(SRB_ID, table->bucket_count);
    NFAPI_SRB_RELEASE_REQUEST_PDU_T *entry = table->buckets[index];

    while (entry) {
        if (entry->SRB_ID == SRB_ID) return entry;
        entry = entry->next;
    }

    return NULL;
}

void iterate_forward(HashTable *table, void (*callback)(NFAPI_SRB_RELEASE_REQUEST_PDU_T*)) {
    for (size_t i = 0; i < table->bucket_count; ++i) {
        NFAPI_SRB_RELEASE_REQUEST_PDU_T *entry = table->buckets[i];
        while (entry) {
            callback(entry);
            entry = entry->next;
        }
    }
}

void iterate_backward(HashTable *table, void (*callback)(NFAPI_SRB_RELEASE_REQUEST_PDU_T*)) {
    for (size_t i = 0; i < table->bucket_count; ++i) {
        NFAPI_SRB_RELEASE_REQUEST_PDU_T *entry = table->buckets[i];
        while (entry && entry->next) {
            entry = entry->next;
        }
        while (entry) {
            callback(entry);
            if (entry->prev) entry = entry->prev;
            else break;
        }
    }
}
