import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class ConnectionPoolManager {
    private final Selector selector;
    private final ConcurrentHashMap<SocketChannel, ChannelInfo> connectionMap;
    private final int idleTimeout;
    private final AtomicInteger queueCapacity;

    public ConnectionPoolManager(int poolSize, int idleTimeout) throws IOException {
        this.selector = Selector.open();
        this.connectionMap = new ConcurrentHashMap<>(poolSize);
        this.idleTimeout = idleTimeout;
        this.queueCapacity = new AtomicInteger(poolSize);

        // Initialize the connection pool
        for (int i = 0; i < poolSize; i++) {
            SocketChannel channel = SocketChannel.open(new InetSocketAddress("example.com", 80));
            channel.configureBlocking(false);
            channel.register(selector, SelectionKey.OP_READ);
            connectionMap.put(channel, new ChannelInfo(System.currentTimeMillis()));
        }
    }

    public void validateConnections() {
        long now = System.currentTimeMillis();
        for (SocketChannel channel : connectionMap.keySet()) {
            if ((now - connectionMap.get(channel).lastAccessTime) > idleTimeout) {
                evictConnection(channel);
            }
        }
    }

    private void evictConnection(SocketChannel channel) {
        try {
            channel.close();
            connectionMap.remove(channel);
        } catch (IOException e) {
            // Handle the exception
        }
    }

    public void manageService() {
        // Implement service management logic based on queue state and random intervals
    }

    private static class ChannelInfo {
        long lastAccessTime;

        ChannelInfo(long lastAccessTime) {
            this.lastAccessTime = lastAccessTime;
        }
    }
}
```

