public class ConfigCacheManager
{
    private readonly ConcurrentDictionary<string, string> _configCache = new ConcurrentDictionary<string, string>();
    private readonly HttpClient _httpClient = new HttpClient();
    private string _defaultConfigDirectory = "defaultConfigDir";
    private static readonly Random _random = new Random();

    public ConfigCacheManager(string defaultConfigDirectory)
    {
        if (string.IsNullOrEmpty(defaultConfigDirectory))
            throw new ArgumentException("Default config directory cannot be null or empty.");
        _defaultConfigDirectory = defaultConfigDirectory;
    }

    public string GetConfig(string key)
    {
        return _configCache.GetOrAdd(key, FetchConfig);
    }

    private async Task<string> FetchConfig(string key)
    {
        try
        {
            var response = await _httpClient.GetAsync($"https://api.example.com/config/{key}");
            if (response.IsSuccessStatusCode)
                return await response.Content.ReadAsStringAsync();
            else
                throw new Exception("Failed to fetch config.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error fetching config: {ex.Message}");
            return null;
        }
    }

    public int GetRandomInt(int min, int max, bool exclusive = false)
    {
        if (exclusive) return _random.Next(min + 1, max);
        return _random.Next(min, max + 1);
    }

    public float GetRandomFloat(float min, float max)
    {
        if (min >= max)
        {
            Console.WriteLine("Invalid input: min should be less than max.");
            return 0.5f;
        }
        return (float)_random.NextDouble() * (max - min) + min;
    }

    public Vector3 GetRandomVector3(float minX, float maxX, float minY, float maxY, float minZ, float maxZ)
    {
        return new Vector3(GetRandomFloat(minX, maxX), GetRandomFloat(minY, maxY), GetRandomFloat(minZ, maxZ));
    }

    public int GetWeightedRandomInt(int[] weights, int maxValue)
    {
        if (weights == null || weights.Length == 0)
            throw new ArgumentException("Weights array cannot be null or empty.");
        int sum = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            sum += weights[i];
            if (sum > maxValue)
                throw new ArgumentException("Sum of weights should not exceed maxValue.");
        }
        int randomValue = GetRandomInt(1, sum);
        int cumulativeWeight = 0;
        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue <= cumulativeWeight)
                return i;
        }
        return -1; // Should never reach here
    }
}
