#include <stdio.h>
#include <stdlib.h>

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} LogLevel;

typedef struct LogBuffer {
    char *buffer;
    size_t size;
    size_t used;
} LogBuffer;

typedef struct LoggerConfig {
    LogLevel level;
    LogBuffer *log_buffer;
} LoggerConfig;

int initialize_logging_system(LoggerConfig *configs, int num_configs) {
    for (int i = 0; i < num_configs; i++) {
        configs[i].log_buffer = malloc(configs[i].size);
        if (!configs[i].log_buffer) {
            fprintf(stderr, "Failed to allocate memory for log buffer %d\n", i);
            // Free previously allocated buffers
            for (int j = 0; j < i; j++) {
                free(configs[j].log_buffer);
            }
            return -1;
        }
    }

    // Validate and initialize each log buffer
    for (int i = 0; i < num_configs; i++) {
        if (configs[i].size <= configs[i].used) {
            fprintf(stderr, "Log buffer %d size is less than used space\n", i);
            free(configs[i].log_buffer);
            // Free previously allocated buffers
            for (int j = 0; j < i; j++) {
                free(configs[j].log_buffer);
            }
            return -1;
        }
        configs[i].log_buffer[configs[i].used] = '\0';
    }

    return 0;
}
