use std::fs::File;
use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::mpsc;
use std::thread;
use openssl::ssl::{SslAcceptor, SslFiletype, SslMethod};

fn setup_logging_server(num_loggers: u32) -> std::io::Result<()> {
    let listener = TcpListener::bind("127.0.0.1:8080")?;
    let acceptor = SslAcceptor::mozilla_intermediate()
        .unwrap()
        .set_private_key_file("server.key", SslFiletype::PEM)
        .unwrap()
        .set_certificate_chain_file("server.crt")
        .unwrap();

    for stream in listener.incoming() {
        match stream {
            Ok(mut stream) => {
                let acceptor = acceptor.clone();
                thread::spawn(move || {
                    if let Err(e) = acceptor.accept(stream).and_then(|stream| handle_client(stream)) {
                        eprintln!("Error handling client: {}", e);
                    }
                });
            }
            Err(e) => {
                eprintln!("Failed to establish a connection: {}", e);
            }
        }
    }

    Ok(())
}

fn handle_client(mut stream: std::net::TcpStream) -> std::io::Result<()> {
    let mut ssl_stream = acceptor.accept(stream).unwrap();
    let mut buffer = [0; 512];
    loop {
        match ssl_stream.read(&mut buffer) {
            Ok(n) if n == 0 => return Ok(()),
            Ok(n) => {
                ssl_stream.write_all(&buffer[0..n]).unwrap();
            }
            Err(e) => {
                eprintln!("Error reading from client: {}", e);
                return Err(e);
            }
        }
    }
}

fn main() -> std::io::Result<()> {
    let num_loggers = 5;
    initialize_logging_system(num_loggers)?;
    setup_logging_server(num_loggers)?;
    Ok(())
}
