# Mocking a simple local database using a dictionary
local_db = {}

@lru_cache(maxsize=128)
def fetch_weather(city):
    try:
        response = requests.get(f"https://api.openweathermap.org/data/2.5/weather?q={city}&appid=your_api_key&units=metric")
        response.raise_for_status()
        data = response.json()
        temperature = data['main']['temp']
        humidity = data['main']['humidity']
        return temperature, humidity
    except requests.exceptions.RequestException as e:
        print(f"Error fetching weather for {city}: {e}")
        raise

def update_local_db(city):
    try:
        temperature, humidity = fetch_weather(city)
        local_db[city] = {'temperature': temperature, 'humidity': humidity, 'updated_at': datetime.now()}
        print(f"Successfully updated data for {city}")
    except requests.exceptions.RequestException as e:
        print(f"Failed to update data for {city}: {e}")

def main():
    cities = ["New York", "London", "Tokyo"]
    for city in cities:
        update_local_db(city)

if __name__ == "__main__":
    main()
