#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketManager;

PacketManager* pm_create() {
    PacketManager *pm = (PacketManager*)malloc(sizeof(PacketManager));
    pm->packets = NULL;
    pm->count = 0;
    pm->capacity = 0;
    pthread_mutex_init(&pm->lock, NULL);
    return pm;
}

void pm_destroy(PacketManager *pm) {
    pthread_mutex_lock(&pm->lock);
    free(pm->packets);
    pm->packets = NULL;
    pm->count = 0;
    pm->capacity = 0;
    pthread_mutex_unlock(&pm->lock);
    pthread_mutex_destroy(&pm->lock);
    free(pm);
}

int pm_add(PacketManager *pm, DataPacket packet) {
    pthread_mutex_lock(&pm->lock);
    if (pm->count >= pm->capacity) {
        size_t new_capacity = (pm->capacity == 0) ? 1 : pm->capacity * 2;
        DataPacket *new_packets = realloc(pm->packets, new_capacity * sizeof(DataPacket));
        if (new_packets == NULL) {
            pthread_mutex_unlock(&pm->lock);
            return -1; // Memory allocation failed
        }
        pm->packets = new_packets;
        pm->capacity = new_capacity;
    }
    pm->packets[pm->count] = packet;
    pm->count++;
    pthread_mutex_unlock(&pm->lock);
    return 0; // Success
}

int pm_remove(PacketManager *pm, int packet_id) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->count; i++) {
        if (pm->packets[i].packet_id == packet_id) {
            memmove(&pm->packets[i], &pm->packets[i + 1], (pm->count - i - 1) * sizeof(DataPacket));
            pm->count--;
            pthread_mutex_unlock(&pm->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&pm->lock);
    return -1; // Packet not found
}

size_t pm_get_count(PacketManager *pm) {
    size_t count;
    pthread_mutex_lock(&pm->lock);
    count = pm->count;
    pthread_mutex_unlock(&pm->lock);
    return count;
}

int pm_sort_by_timestamp(PacketManager *pm) {
    qsort(pm->packets, pm->count, sizeof(DataPacket), [](const void *a, const void *b) {
        DataPacket *pa = (DataPacket*)a;
        DataPacket *pb = (DataPacket*)b;
        return (int)(pa->timestamp - pb->timestamp);
    });
    return 0; // Success
}
