    new_node->data = packet;
    new_node->next = array->head;
    array->head = new_node;
    array->count++;
}

void remove_packet(DynamicArray* array, int packet_id) {
    Node* current = array->head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.packet_id == packet_id) {
            if (prev == NULL) {
                array->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            array->count--;
            return;
        }
        prev = current;
        current = current->next;
    }
