namespace DAO {
    class SecureRandomNumberGenerator {
    public:
        static SecureRandomNumberGenerator& getInstance() {
            static std::once_flag flag;
            std::call_once(flag, &SecureRandomNumberGenerator::init);
            return *instance;
        }

        int getNextRandomNumber() {
            std::lock_guard<std::mutex> lock(mutex_);
            if (generator_.empty()) {
                throw std::runtime_error("Queue is empty");
            }
            return generator_.front();
        }

        void enqueue(int number, int priority) {
            std::lock_guard<std::mutex> lock(mutex_);
            auto it = generator_.begin();
            while (it != generator_.end() && it->second > priority) {
                ++it;
            }
            generator_.insert(it, {number, priority});
        }

        void waitForItem(double timeout) {
            std::unique_lock<std::mutex> lock(mutex_);
            if (generator_.empty()) {
                condition_.wait_for(lock, std::chrono::duration<double>(timeout), [this] {
                    return !generator_.empty();
                });
            }
        }

    private:
        SecureRandomNumberGenerator() {}
        ~SecureRandomNumberGenerator() {}

        static void init() {
            instance = new SecureRandomNumberGenerator();
        }

        static SecureRandomNumberGenerator* instance;

        std::mutex mutex_;
        std::queue<std::pair<int, int>, std::deque<std::pair<int, int>>, std::greater<std::pair<int, int>>> generator_;
        std::condition_variable condition_;
    };

    SecureRandomNumberGenerator* SecureRandomNumberGenerator::instance = nullptr;
}
