    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket packets[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_packet(PacketManager *manager, uint32_t packet_id, time_t timestamp, size_t payload_size) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_PACKETS) {
        // Handle error or store in pending queue
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    manager->packets[manager->count].packet_id = packet_id;
    manager->packets[manager->count].timestamp = timestamp;
    manager->packets[manager->count].payload_size = payload_size;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_packet(PacketManager *manager, uint32_t packet_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->packets[i].packet_id == packet_id) {
            // Shift remaining packets
            memmove(&manager->packets[i], &manager->packets[i + 1], sizeof(DataPacket) * (manager->count - i - 1));
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int get_packet_count(PacketManager *manager) {
    int count;
    pthread_mutex_lock(&manager->lock);
    count = manager->count;
    pthread_mutex_unlock(&manager->lock);
    return count;
}

void sort_packets_by_timestamp(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    qsort(manager->packets, manager->count, sizeof(DataPacket), 
          (int (*)(const void *, const void *))compare_packets_by_timestamp);
    pthread_mutex_unlock(&manager->lock);
}

int compare_packets_by_timestamp(const DataPacket *a, const DataPacket *b) {
    return a->timestamp - b->timestamp;
}

u_char* resolve_dns(const char *hostname) {
    struct addrinfo hints, *res;
    u_char ip[INET6_ADDRSTRLEN];
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    if (res->ai_family == AF_INET) { // IPv4
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
        inet_ntop(AF_INET, &ipv4->sin_addr, ip, INET_ADDRSTRLEN);
    } else { // IPv6
        struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)res->ai_addr;
        inet_ntop(AF_INET6, &ipv6->sin6_addr, ip, INET6_ADDRSTRLEN);
    }

    freeaddrinfo(res);

    return ip;
}
