#include <iostream>
#include <vector>
#include <mutex>
#include <algorithm>
#include <fstream>
#include <string>
#include <unordered_map>

class LogEntry {
public:
    int entry_id;
    std::time_t timestamp;
    std::string log_level;
    std::string message;

    LogEntry(int id, std::time_t ts, const std::string& level, const std::string& msg)
        : entry_id(id), timestamp(ts), log_level(level), message(msg) {}
};

class DynamicLogManager {
private:
    std::vector<LogEntry> entries;
    std::mutex mutex;
    size_t max_size;
    std::unordered_map<std::string, int> level_counts;

public:
    DynamicLogManager(size_t initial_size = 1000000) : max_size(initial_size) {}

    void addLog(const LogEntry& entry) {
        std::lock_guard<std::mutex> lock(mutex);
        entries.push_back(entry);
        level_counts[entry.log_level]++;
        if (entries.size() > max_size) {
            removeOldestEntries();
        }
    }

    void removeOldestEntries() {
        std::time_t oldest_time = entries.front().timestamp;
        auto it = std::remove_if(entries.begin(), entries.end(),
                               [oldest_time](const LogEntry& entry) {
                                   return entry.timestamp == oldest_time;
                               });
        if (it != entries.end()) {
            entries.erase(it, entries.end());
            updateLevelCounts();
        }
    }

    void removeEntriesByLogLevel(const std::string& level) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = std::remove_if(entries.begin(), entries.end(),
                               [level](const LogEntry& entry) {
                                   return entry.log_level == level;
                               });
        if (it != entries.end()) {
            entries.erase(it, entries.end());
            updateLevelCounts();
        }
    }

    size_t getTotalEntries() const {
        std::lock_guard<std::mutex> lock(mutex);
        return entries.size();
    }

    void serialize(const std::string& filename) {
        std::ofstream file(filename, std::ios::binary);
        if (file.is_open()) {
            for (const auto& entry : entries) {
                file.write(reinterpret_cast<const char*>(&entry.entry_id), sizeof(int));
                file.write(reinterpret_cast<const char*>(&entry.timestamp), sizeof(std::time_t));
                size_t level_size = entry.log_level.size();
                file.write(reinterpret_cast<const char*>(&level_size), sizeof(size_t));
                file.write(entry.log_level.c_str(), level_size);
                size_t message_size = entry.message.size();
                file.write(reinterpret_cast<const char*>(&message_size), sizeof(size_t));
                file.write(entry.message.c_str(), message_size);
            }
            file.close();
        }
    }

    void deserialize(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (file.is_open()) {
            entries.clear();
            level_counts.clear();
            int entry_id;
            std::time_t timestamp;
            size_t level_size;
            while (file.read(reinterpret_cast<char*>(&entry_id), sizeof(int)) &&
                   file.read(reinterpret_cast<char*>(&timestamp), sizeof(std::time_t))) {
                file.read(reinterpret_cast<char*>(&level_size), sizeof(size_t));
                std::string log_level(level_size, '\0');
                file.read(&log_level[0], level_size);
                size_t message_size;
                file.read(reinterpret_cast<char*>(&message_size), sizeof(size_t));
                std::string message(message_size, '\0');
                file.read(&message[0], message_size);
                entries.push_back(LogEntry(entry_id, timestamp, log_level, message));
                level_counts[log_level]++;
            }
            file.close();
        }
    }

private:
    void updateLevelCounts() {
        level_counts.clear();
        for (const auto& entry : entries) {
            level_counts[entry.log_level]++;
        }
    }
};
