#include <openssl/pem.h>
#include <openssl/evp.h>
#include <openssl/bio.h>

void generate_certificate_from_oauth_request(const char* private_key_path, const char* cert_path, BIO* bio_out) {
    FILE *private_key_file = fopen(private_key_path, "r");
    if (!private_key_file) {
        // Handle error
        return;
    }

    EVP_PKEY *private_key = PEM_read_PrivateKey(private_key_file, NULL, NULL, NULL);
    fclose(private_key_file);

    if (!private_key) {
        // Handle error
        return;
    }

    FILE *cert_file = fopen(cert_path, "r");
    if (!cert_file) {
        // Handle error
        EVP_PKEY_free(private_key);
        return;
    }

    X509 *certificate = PEM_read_X509(cert_file, NULL, NULL, NULL);
    fclose(cert_file);

    if (!certificate) {
        // Handle error
        EVP_PKEY_free(private_key);
        return;
    }

    BIO* bio_private_key = BIO_new(BIO_s_mem());
    if (!bio_private_key) {
        // Handle error
        X509_free(certificate);
        EVP_PKEY_free(private_key);
        return;
    }

    BIO_write(bio_private_key, private_key, sizeof(EVP_PKEY));

    BIO* bio_cert = BIO_new(BIO_s_mem());
    if (!bio_cert) {
        // Handle error
        BIO_free_all(bio_private_key);
        X509_free(certificate);
        EVP_PKEY_free(private_key);
        return;
    }

    BIO_write(bio_cert, certificate, sizeof(X509));

    PEM_write_bio_PrivateKey(bio_out, private_key, NULL, NULL, 0, NULL, NULL);
    PEM_write_bio_X509(bio_out, certificate);

    BIO_free_all(bio_private_key);
    BIO_free_all(bio_cert);
    X509_free(certificate);
    EVP_PKEY_free(private_key);
}
