#include <iostream>
#include <thread>
#include <atomic>
#include <chrono>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>

class AttackManager {
public:
    AttackManager() : cooldowns_{12, 8, 10, 7}, fallback_times_{5, 10, 15, 20} {}

    void updateCooldowns(const std::vector<int>& new_cooldowns) {
        std::lock_guard<std::mutex> lock(mutex_);
        cooldowns_ = new_cooldowns;
        cv_.notify_all();
    }

    AttackType selectAttack() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (true) {
            for (int i = 0; i < 4; ++i) {
                if (current_time_ % cooldowns_[i] == 0) {
                    current_time_ += cooldowns_[i];
                    return static_cast<AttackType>(i);
                }
            }
            // Fallback strategy
            for (int i = 0; i < 4; ++i) {
                if (current_time_ % fallback_times_[i] == 0) {
                    current_time_ += fallback_times_[i];
                    return static_cast<AttackType>(i);
                }
            }
            cv_.wait(lock, [this]() { return current_time_ > 0; });
        }
    }

private:
    enum AttackType { A, B, C, D };

    std::vector<int> cooldowns_;
    std::vector<int> fallback_times_;
    int current_time_ = 0;
    std::mutex mutex_;
    std::condition_variable cv_;
};

int main() {
    AttackManager manager;

    // Example usage
    for (int i = 0; i < 10; ++i) {
        auto attack = manager.selectAttack();
        std::cout << "Selected Attack: " << static_cast<int>(attack) << std::endl;
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    return 0;
}
