const asyncReduce = async (array, initialValue, reducerCallback, apiClient) => {
  let result = initialValue;
  const promises = array.map(async (item, index) => {
    try {
      if (apiClient && Array.isArray(item.externalData)) {
        const externalValues = await Promise.all(
          item.externalData.map(apiId => apiClient.fetchData(apiId))
        );
        return reducerCallback(result, { ...item, externalData: externalValues });
      } else {
        return reducerCallback(result, item);
      }
    } catch (error) {
      console.error(`Error processing item at index ${index}:`, error);
      return result; // Handle error gracefully, possibly with a default value
    }
  });

  const results = await Promise.all(promises);
  return results.reduce((acc, val) => reducerCallback(acc, val), initialValue);
};

