    double value;
} Record;

typedef struct {
    Record records[MAX_DEVICES];
    pthread_mutex_t lock;
    int count;
} RecordArray;

void initialize_record_array(RecordArray *array) {
    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
}

void add_record(RecordArray *array, long offset, int key, double value) {
    pthread_mutex_lock(&array->lock);
    if (array->count < MAX_DEVICES) {
        Record *record = &array->records[array->count++];
        record->offset = offset;
        record->key = key;
        record->value = value;
    }
    pthread_mutex_unlock(&array->lock);
}

void free_record_array(RecordArray *array) {
    pthread_mutex_destroy(&array->lock);
}
