// Define NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define configuration and connection settings structures
typedef struct {
    char* password;
} ConfigStruct;

typedef struct {
    char title[256];
} ConnectionSettings;

// Define event handler function type
typedef void (*EventHandler)(void);

// Function to log information with timestamp
void logInfo(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

// Mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Authentication and memory management function
int authenticateAndAllocate(ConfigStruct* config, ConnectionSettings* connSettings, EventHandler eventHandler, int N) {
    pthread_mutex_lock(&mutex);

    // Validate inputs
    if (config->password == NULL || strlen(config->password) == 0) {
        logInfo("Invalid or empty password");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    if (connSettings->title[0] == '\0') {
        logInfo("Invalid connection settings title");
        pthread_mutex_unlock(&mutex);
        return -2;
    }

    if (eventHandler == NULL) {
        logInfo("Event handler function is not provided");
        pthread_mutex_unlock(&mutex);
        return -3;
    }

    // Log successful validation
    logInfo("Validation successful");

    // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pduArray == NULL) {
        logInfo("Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return -4;
    }

    // Initialize structures with unique RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < N; i++) {
        pduArray[i].RX_UE_INFORMATION_TAG = i + 1;
        pduArray[i].RNTI = i * 2 + 1;
        srand(time(NULL));
        pduArray[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    // Log memory allocation success
    logInfo("Memory allocation successful");

    // Call event handler
    (*eventHandler)();

    // Free allocated memory
    free(pduArray);

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}
```
