#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
} PacketArray;

void init_packet_array(PacketArray *array, size_t initial_capacity) {
    array->packets = (DataPacket *)malloc(initial_capacity * sizeof(DataPacket));
    if (!array->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = initial_capacity;
}

void free_packet_array(PacketArray *array) {
    free(array->packets);
    array->packets = NULL;
    array->count = array->capacity = 0;
}

int add_packet(PacketArray *array, int packet_id, time_t timestamp, size_t payload_size) {
    if (array->count >= array->capacity) {
        array->capacity *= 2;
        DataPacket *new_packets = (DataPacket *)realloc(array->packets, array->capacity * sizeof(DataPacket));
        if (!new_packets) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
        array->packets = new_packets;
    }
    array->packets[array->count].packet_id = packet_id;
    array->packets[array->count].timestamp = timestamp;
    array->packets[array->count].payload_size = payload_size;
    array->count++;
    return 0;
}

int remove_packet_by_id(PacketArray *array, int packet_id) {
    for (size_t i = 0; i < array->count; i++) {
        if (array->packets[i].packet_id == packet_id) {
            for (size_t j = i; j < array->count - 1; j++) {
                array->packets[j] = array->packets[j + 1];
            }
            array->count--;
            return 0;
        }
    }
    return -1;
}

size_t get_packet_count(const PacketArray *array) {
    return array->count;
}

// Function to sort packets by timestamp
void sort_packets_by_timestamp(PacketArray *array) {
    qsort(array->packets, array->count, sizeof(DataPacket), [](const void *a, const void *b) {
        return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp;
    });
}

// Function to filter packets by payload size
void filter_packets_by_payload_size(PacketArray *array, size_t min_payload, size_t max_payload) {
    PacketArray filtered_array = {0};
    init_packet_array(&filtered_array, array->capacity);
    for (size_t i = 0; i < array->count; i++) {
        if (array->packets[i].payload_size >= min_payload && array->packets[i].payload_size <= max_payload) {
            add_packet(&filtered_array, array->packets[i].packet_id, array->packets[i].timestamp, array->packets[i].payload_size);
        }
    }
    free_packet_array(array);
    *array = filtered_array;
}

// Example usage
int main() {
    PacketArray packet_array;
    init_packet_array(&packet_array, 10);

    add_packet(&packet_array, 1, time(NULL), 1024);
    add_packet(&packet_array, 2, time(NULL) + 3600, 2048);
    add_packet(&packet_array, 3, time(NULL) - 7200, 512);

    sort_packets_by_timestamp(&packet_array);
    printf("Sorted by timestamp:\n");
    for (size_t i = 0; i < packet_array.count; i++) {
        printf("Packet ID: %d, Timestamp: %ld, Payload Size: %zu\n", packet_array.packets[i].packet_id, packet_array.packets[i].timestamp, packet_array.packets[i].payload_size);
    }

    filter_packets_by_payload_size(&packet_array, 1024, 2048);
    printf("Filtered by payload size (1024-2048):\n");
    for (size_t i = 0; i < packet_array.count; i++) {
        printf("Packet ID: %d, Timestamp: %ld, Payload Size: %zu\n", packet_array.packets[i].packet_id, packet_array.packets[i].timestamp, packet_array.packets[i].payload_size);
    }

    free_packet_array(&packet_array);
    return 0;
}
