#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t size;
    size_t capacity;
} PacketManager;

void init_packet_manager(PacketManager* pm, size_t initial_capacity) {
    pm->packets = (DataPacket*)malloc(initial_capacity * sizeof(DataPacket));
    pm->size = 0;
    pm->capacity = initial_capacity;
}

void add_packet(PacketManager* pm, DataPacket packet) {
    if (pm->size == pm->capacity) {
        pm->capacity *= 2;
        pm->packets = (DataPacket*)realloc(pm->packets, pm->capacity * sizeof(DataPacket));
    }
    pm->packets[pm->size++] = packet;
}

void remove_packet(PacketManager* pm, int packet_id) {
    for (size_t i = 0; i < pm->size; ++i) {
        if (pm->packets[i].packet_id == packet_id) {
            memmove(&pm->packets[i], &pm->packets[i + 1], (pm->size - i - 1) * sizeof(DataPacket));
            --pm->size;
            break;
        }
    }
}

size_t get_packet_count(PacketManager* pm) {
    return pm->size;
}

void sort_packets_by_timestamp(PacketManager* pm) {
    qsort(pm->packets, pm->size, sizeof(DataPacket), compare_packets);
}

int compare_packets(const void* a, const void* b) {
    DataPacket pa = *(DataPacket*)a;
    DataPacket pb = *(DataPacket*)b;
    return (pa.timestamp > pb.timestamp) - (pa.timestamp < pb.timestamp);
}

void filter_packets_by_payload_size(PacketManager* pm, size_t min_size, size_t max_size) {
    PacketManager filtered_pm;
    init_packet_manager(&filtered_pm, pm->capacity);

    for (size_t i = 0; i < pm->size; ++i) {
        if (pm->packets[i].payload_size >= min_size && pm->packets[i].payload_size <= max_size) {
            add_packet(&filtered_pm, pm->packets[i]);
        }
    }

    *pm = filtered_pm;
}

void free_packet_manager(PacketManager* pm) {
    free(pm->packets);
}
