void sort_packets_by_timestamp(PacketManager *pm) {
    // Simple bubble sort for demonstration purposes
    for (size_t i = 0; i < pm->size - 1; ++i) {
        for (size_t j = 0; j < pm->size - i - 1; ++j) {
            if (pm->packets[j].timestamp > pm->packets[j + 1].timestamp) {
                DataPacket temp = pm->packets[j];
                pm->packets[j] = pm->packets[j + 1];
                pm->packets[j + 1] = temp;
