#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} memory_pool;

memory_pool *create_memory_pool(size_t capacity) {
    memory_pool *pool = (memory_pool *)malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->offsets = (long *)malloc(capacity * sizeof(long));
    pool->keys = (int *)malloc(capacity * sizeof(int));
    pool->records = (record *)malloc(capacity * sizeof(record));
    pool->capacity = capacity;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);

    if (!pool->offsets || !pool->keys || !pool->records) {
        destroy_memory_pool(pool);
        return NULL;
    }

    return pool;
}

void destroy_memory_pool(memory_pool *pool) {
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int set_random_value(record *rec, int min, int max) {
    rec->value = rand() % (max - min + 1) + min;
    return 0;
}

int allocate_record(memory_pool *pool) {
    if (pthread_mutex_lock(&pool->lock)) return -1;

    if (pool->used >= pool->capacity) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Memory pool overflow
    }

    record *rec = &pool->records[pool->used++];
    if (set_random_value(rec, 0, 100)) { // Adjust range as needed
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void clear_memory_pool(memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    pool->used = 0;
    pthread_mutex_unlock(&pool->lock);
}

int main() {
    srand(time(NULL));
    memory_pool *pool = create_memory_pool(MAX_RECORDS);
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        return 1;
    }

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (allocate_record(pool)) {
            fprintf(stderr, "Failed to allocate record at index %zu\n", i);
            break;
        }
    }

    clear_memory_pool(pool);
    destroy_memory_pool(pool);

    return 0;
}
```']

