#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <chrono>

class Transaction {
public:
    int transaction_id;
    std::string account_number;
    double transaction_amount;
    std::string transaction_date;

    Transaction(int id, const std::string& accNum, double amount, const std::string& date)
        : transaction_id(id), account_number(accNum), transaction_amount(amount), transaction_date(date) {}
};

class TransactionManager {
private:
    std::unordered_map<int, Transaction> transactions;
    std::mutex mutex_;
    std::condition_variable cv_;

public:
    void addTransaction(const Transaction& transaction) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (transactions.find(transaction.transaction_id) != transactions.end()) {
            std::cerr << "Transaction ID already exists: " << transaction.transaction_id << std::endl;
            return;
        }
        transactions[transaction.transaction_id] = transaction;
        cv_.notify_one();
    }

    bool removeTransaction(int id) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = transactions.find(id);
        if (it != transactions.end()) {
            transactions.erase(it);
            return true;
        }
        return false;
    }

    int getTotalTransactions() const {
        std::unique_lock<std::mutex> lock(mutex_);
        return transactions.size();
    }

    std::vector<Transaction> filterTransactions(double min_amount, double max_amount) const {
        std::vector<Transaction> result;
        std::unique_lock<std::mutex> lock(mutex_);
        for (const auto& pair : transactions) {
            if (pair.second.transaction_amount >= min_amount && pair.second.transaction_amount <= max_amount) {
                result.push_back(pair.second);
            }
        }
        return result;
    }

    std::unordered_map<std::string, double> aggregateTransactionsByAccount() const {
        std::unordered_map<std::string, double> aggregatedAmounts;
        std::unique_lock<std::mutex> lock(mutex_);
        for (const auto& pair : transactions) {
            aggregatedAmounts[pair.second.account_number] += pair.second.transaction_amount;
        }
        return aggregatedAmounts;
    }

    void retryFailedTransactions() {
        // Implementation of retry logic with exponential backoff
    }

    void logTransaction(const Transaction& transaction, bool success) {
        if (success) {
            std::cout << "Transaction logged: " << transaction.transaction_id << std::endl;
        } else {
            std::cerr << "Failed to log transaction: " << transaction.transaction_id << std::endl;
        }
    }

    void monitorPerformance() {
        // Implementation of monitoring logic
    }
};
