['```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <stdexcept>

class Transaction {
public:
    int transaction_id;
    int account_number;
    double transaction_amount;
    std::string transaction_date;

    Transaction(int id, int acc_num, double amount, const std::string& date)
        : transaction_id(id), account_number(acc_num), transaction_amount(amount), transaction_date(date) {}
};

class TransactionManager {
private:
    std::unordered_map<int, Transaction> transactions;
    std::vector<Transaction*> transaction_list;

public:
    void addTransaction(const Transaction& transaction);
    bool removeTransaction(int transaction_id);
    int getTotalTransactions() const;
    std::vector<Transaction> filterByAmount(double min_amount, double max_amount) const;
    std::unordered_map<int, double> aggregateByAccountNumber() const;
};

void TransactionManager::addTransaction(const Transaction& transaction) {
    if (transactions.find(transaction.transaction_id) != transactions.end()) {
        throw std::invalid_argument("Duplicate transaction ID");
    }
    transactions[transaction.transaction_id] = transaction;
    transaction_list.push_back(&transactions[transaction.transaction_id]);
}

bool TransactionManager::removeTransaction(int transaction_id) {
    auto it = transactions.find(transaction_id);
    if (it == transactions.end()) {
        return false;
    }
    for (auto& ptr : transaction_list) {
        if (ptr->transaction_id == transaction_id) {
            transaction_list.erase(std::remove(transaction_list.begin(), transaction_list.end(), ptr), transaction_list.end());
            break;
        }
    }
    transactions.erase(it);
    return true;
}

int TransactionManager::getTotalTransactions() const {
    return transaction_list.size();
}

std::vector<Transaction> TransactionManager::filterByAmount(double min_amount, double max_amount) const {
    std::vector<Transaction> filtered_transactions;
    for (const auto& ptr : transaction_list) {
        if (ptr->transaction_amount >= min_amount && ptr->transaction_amount <= max_amount) {
            filtered_transactions.push_back(*ptr);
        }
    }
    return filtered_transactions;
}

std::unordered_map<int, double> TransactionManager::aggregateByAccountNumber() const {
    std::unordered_map<int, double> aggregated_transactions;
    for (const auto& ptr : transaction_list) {
        aggregated_transactions[ptr->account_number] += ptr->transaction_amount;
    }
    return aggregated_transactions;
}
