#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef enum {
    STATUS_ACTIVE,
    STATUS_INACTIVE,
    STATUS_SUSPENDED
} Status;

typedef struct record {
    int value;
    long offset;
    int key;
    double weight;
    char name[50];
    Status status;
} Record;

int initializeRecords(int size, Record** records, long* offsets, int* keys, double* weights, char** names, Status* statuses) {
    if (size <= 0 || size > MAX_RECORDS) {
        return -1; // Invalid size
    }

    *records = malloc(size * sizeof(Record));
    *offsets = malloc(size * sizeof(long));
    *keys = malloc(size * sizeof(int));
    *weights = malloc(size * sizeof(double));
    *names = malloc(size * 50 * sizeof(char));
    *statuses = malloc(size * sizeof(Status));

    if (*records == NULL || *offsets == NULL || *keys == NULL || *weights == NULL || *names == NULL || *statuses == NULL) {
        // Handle memory allocation failure
        free(*records);
        free(*offsets);
        free(*keys);
        free(*weights);
        free(*names);
        free(*statuses);
        return -1; // Allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
