        (*offsets)[i] = rand() % 1000000 + 1;
        (*keys)[i] = rand() % 1000 + 1;
        (*weights)[i] = (double)(rand() % 1000) / 10.0;
        snprintf((*names)[i], 50, "Name%d", i);
        (*statuses)[i] = (Status)(rand() % 3); // Randomly choose a status
    }

    return size; // Successful allocation
}

int saveRecordsToFile(const char* filename, Record** records, int size) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        return -1; // Failed to open file
    }

    for (int i = 0; i < size; i++) {
        fprintf(file, "%d %ld %d %f %s %d\n", (*records)[i].value, (*records)[i].offset, (*records)[i].key, (*records)[i].weight, (*records)[i].name, (*records)[i].status);
    }

    fclose(file);
    return 0; // Success
}

int loadRecordsFromFile(const char* filename, Record** records, long** offsets, int** keys, double** weights, char*** names, Status** statuses) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        return -1; // Failed to open file
    }

    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    *records = malloc(MAX_RECORDS * sizeof(Record));
    *offsets = malloc(MAX_RECORDS * sizeof(long));
    *keys = malloc(MAX_RECORDS * sizeof(int));
    *weights = malloc(MAX_RECORDS * sizeof(double));
    *names = malloc(MAX_RECORDS * 50 * sizeof(char));
    *statuses = malloc(MAX_RECORDS * sizeof(Status));

    if (*records == NULL || *offsets == NULL || *keys == NULL || *weights == NULL || *names == NULL || *statuses == NULL) {
        free(*records);
        free(*offsets);
        free(*keys);
        free(*weights);
        free(*names);
        free(*statuses);
        fclose(file);
        return -1; // Allocation failed
    }

    int count = 0;
    while (fscanf(file, "%d %ld %d %lf %s %d", &(*records)[count].value, (*offsets)[count], &(*keys)[count], &(*weights)[count], (*names)[count], (int*)*statuses) != EOF && count < MAX_RECORDS) {
        count++;
    }

    fclose(file);
    return count; // Number of records loaded
}

void freeRecords(Record** records, long** offsets, int** keys, double** weights, char*** names, Status** statuses) {
    free(*records);
    free(*offsets);
    free(*keys);
    free(*weights);
    for (int i = 0; i < MAX_RECORDS; i++) {
        (*names)[i][0] = '\0'; // Clear the name array
    }
    free(*names);
    free(*statuses);
}
