#define MAX_NAME_LENGTH 10

typedef enum { ACTIVE, INACTIVE } Status;

typedef struct {
    int value;
    long offset;
    int key;
    double weight;
    char name[MAX_NAME_LENGTH];
    Status status;
} Record;

typedef struct {
    Record *records;
    size_t count;
} RecordSet;

void initialize_record(Record *record, int min_offset, int max_offset, int min_key, int max_key, double min_weight, double max_weight) {
    record->value = rand() % (max_value - min_value + 1) + min_value;
    record->offset = (long)(rand() % (max_offset - min_offset + 1)) + min_offset;
    record->key = rand() % (max_key - min_key + 1) + min_key;
    record->weight = ((double)rand() / RAND_MAX) * (max_weight - min_weight) + min_weight;
    for (int i = 0; i < MAX_NAME_LENGTH; ++i) {
        record->name[i] = 'a' + rand() % ('z' - 'a' + 1);
    }
    record->status = (rand() % 2 == 0) ? ACTIVE : INACTIVE;
}

void create_record_set(RecordSet *recordSet, size_t count, int min_offset, int max_offset, int min_key, int max_key, double min_weight, double max_weight) {
    if (count == 0) {
        fprintf(stderr, "Error: Count cannot be zero.\n");
        return;
    }

    recordSet->records = (Record *)malloc(count * sizeof(Record));
    if (recordSet->records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    recordSet->count = count;

    for (size_t i = 0; i < count; ++i) {
        initialize_record(&recordSet->records[i], min_offset, max_offset, min_key, max_key, min_weight, max_weight);
    }
}

void save_record_set(const RecordSet *recordSet, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        fprintf(stderr, "Error opening file for writing.\n");
        return;
    }

    fwrite(&recordSet->count, sizeof(size_t), 1, file);
    fwrite(recordSet->records, sizeof(Record), recordSet->count, file);

    fclose(file);
}

void load_record_set(RecordSet *recordSet, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening file for reading.\n");
        return;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    Record *newRecords = (Record *)realloc(recordSet->records, count * sizeof(Record));
    if (newRecords == NULL) {
        fprintf(stderr, "Memory reallocation failed.\n");
        fclose(file);
        return;
    }
    recordSet->records = newRecords;
    recordSet->count = count;

    fread(recordSet->records, sizeof(Record), recordSet->count, file);

    fclose(file);
}

void free_record_set(RecordSet *recordSet) {
    if (recordSet->records != NULL) {
        free(recordSet->records);
        recordSet->records = NULL;
        recordSet->count = 0;
    }
}

int main() {
    srand(time(NULL));

    RecordSet recordSet;
    create_record_set(&recordSet, 1000, 0, 1000, 0, 1, 10);

    save_record_set(&recordSet, "records.dat");
    free_record_set(&recordSet);

    recordSet.count = 0;
    load_record_set(&recordSet, "records.dat");

    printf("Loaded %zu records.\n", recordSet.count);

    for (size_t i = 0; i < recordSet.count; ++i) {
        printf("Record %zu: Value=%d, Offset=%ld, Key=%d, Weight=%.2f, Name=%s, Status=%s\n",
               i, recordSet.records[i].value, recordSet.records[i].offset, recordSet.records[i].key,
               recordSet.records[i].weight, recordSet.records[i].name, recordSet.records[i].status == ACTIVE ? "ACTIVE" : "INACTIVE");
    }

    free_record_set(&recordSet);

    return 0;
}
