#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define MAX_NAME_LENGTH 100

typedef enum {
    TYPE_A,
    TYPE_B,
    TYPE_C
} RecordStatus;

typedef struct {
    int value;
    long offset;
    int key;
    double weight;
    char name[MAX_NAME_LENGTH];
    RecordStatus status;
} Record;

typedef struct HashTableNode {
    Record record;
    struct HashTableNode* next;
} HashTableNode;

typedef struct {
    HashTableNode** buckets;
    size_t size;
    size_t capacity;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        return NULL;
    }
    table->buckets = (HashTableNode**)calloc(initial_capacity, sizeof(HashTableNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    table->size = 0;
    table->capacity = initial_capacity;
    return table;
}

void hash_table_insert(HashTable* table, Record record) {
    // Simple hash function (modulus)
    size_t index = record.key % table->capacity;
    HashTableNode* new_node = (HashTableNode*)malloc(sizeof(HashTableNode));
    if (!new_node) {
        return;  // Handle allocation failure
    }
    new_node->record = record;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;
    table->size++;
}

Record* hash_table_lookup(HashTable* table, int key) {
    size_t index = key % table->capacity;
    HashTableNode* node = table->buckets[index];
    while (node) {
        if (node->record.key == key) {
            return &node->record;
        }
        node = node->next;
    }
    return NULL;
}

void hash_table_free(HashTable* table) {
    for (size_t i = 0; i < table->capacity; i++) {
        HashTableNode* node = table->buckets[i];
        while (node) {
            HashTableNode* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    free(table);
}

// Function to dynamically allocate memory and initialize arrays of records
void manage_records(size_t num_records, int offset_range[2], int key_range[2], double weight_range[2]) {
    if (num_records == 0) return;

    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_records; i++) {
        records[i].value = rand() % (key_range[1] - key_range[0] + 1) + key_range[0];
        records[i].offset = rand() % (offset_range[1] - offset_range[0] + 1) + offset_range[0];
        records[i].key = records[i].value; // Assuming value and key are the same for simplicity
        records[i].weight = ((double)(rand()) / RAND_MAX) * (weight_range[1] - weight_range[0]) + weight_range[0];

        size_t name_length = rand() % MAX_NAME_LENGTH;
        for (size_t j = 0; j < name_length; j++) {
            records[i].name[j] = 'a' + (rand() % 26); // Random lowercase letter
        }
        records[i].name[name_length] = '\0';

        if ((records[i].value % 3) == 0) {  // Simulating enum type based on value modulo 3
            records[i].status = TYPE_A;
        } else if ((records[i].value % 3) == 1) {
            records[i].status = TYPE_B;
        } else {
            records[i].status = TYPE_C;
        }
    }

    // Example usage of hash table
    HashTable* record_table = create_hash_table(num_records);
    for (size_t i = 0; i < num_records; i++) {
        hash_table_insert(record_table, records[i]);
    }

    // Clean up
    free(records);
    hash_table_free(record_table);
}
