// Define DynamicArray structure
typedef struct {
    DataPacket* packets;
    size_t capacity;
    size_t size;
} DynamicArray;

// Function to initialize dynamic array
void initDynamicArray(DynamicArray* arr, size_t initial_capacity) {
    arr->packets = (DataPacket*)malloc(initial_capacity * sizeof(DataPacket));
    arr->capacity = initial_capacity;
    arr->size = 0;
}

// Function to add packet to dynamic array
int addPacket(DynamicArray* arr, DataPacket packet) {
    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        DataPacket* new_packets = (DataPacket*)realloc(arr->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) return -1;
        arr->packets = new_packets;
        arr->capacity = new_capacity;
    }
    arr->packets[arr->size++] = packet;
    return 0;
}

// Function to remove packet by packet_id
int removePacket(DynamicArray* arr, int packet_id) {
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->packets[i].packet_id == packet_id) {
            memmove(&arr->packets[i], &arr->packets[i + 1], (arr->size - i - 1) * sizeof(DataPacket));
            --arr->size;
            return 0;
        }
    }
    return -1; // Packet not found
}

// Function to retrieve packet by packet_id
DataPacket* getPacketById(DynamicArray* arr, int packet_id) {
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->packets[i].packet_id == packet_id) {
            return &arr->packets[i];
        }
    }
    return NULL; // Packet not found
}

// Function to get total number of packets
