    initDynamicArray(filtered, 10); // Initial capacity
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->packets[i].payload_size >= min_size && arr->packets[i].payload_size <= max_size) {
            addPacket(filtered, arr->packets[i]);
        }
    }
    return filtered;
}

// Function to clean up dynamic array
