void* allocate_arrays(size_t initial_size, size_t *long_array, size_t *int_array, Record **record_array) {
    *long_array = malloc(initial_size * sizeof(long));
    if (*long_array == NULL) return NULL;

    *int_array = malloc(initial_size * sizeof(int));
    if (*int_array == NULL) {
        free(*long_array);
        return NULL;
    }

    *record_array = (Record*)malloc(initial_size * sizeof(Record));
    if (*record_array == NULL) {
        free(*long_array);
        free(*int_array);
        return NULL;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        (*record_array)[i].value = i;
    }

    return NULL;
}

void process_data(size_t size, long *long_array, int *int_array, Record *record_array) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&lock);
        // Perform operation that requires access to all three arrays simultaneously
        long_array[i] += int_array[i];
        record_array[i].value *= 2;
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
}

void cleanup(size_t size, long *long_array, int *int_array, Record *record_array) {
    free(long_array);
    free(int_array);
    free(record_array);
}
