ArrayManager* create_array_manager(size_t initial_capacity) {
    ArrayManager* manager = (ArrayManager*)malloc(sizeof(ArrayManager));
    if (!manager) return NULL;

    manager->offsets = (long*)calloc(initial_capacity, sizeof(long));
    manager->keys = (int*)calloc(initial_capacity, sizeof(int));
    manager->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!manager->offsets || !manager->keys || !manager->records) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        manager->records[i].value = i;
    }

    return manager;
}

void destroy_array_manager(ArrayManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void process_data(ArrayManager* manager, int (*operation)(long, int)) {
    if (!manager || !operation) return;

    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        operation(manager->offsets[i], manager->keys[i]);
    }
    pthread_mutex_unlock(&manager->lock);
}

