using System;
using System.Collections.Concurrent;
using System.Threading;

public class ThreadSafeQueue<T>
{
    private readonly BlockingCollection<T> _queue = new();
    private const int MaxCapacity = 100;

    public void Enqueue(T item)
    {
        if (_queue.Count >= MaxCapacity)
            Monitor.Wait(_queue);

        _queue.Add(item);
        Monitor.PulseAll(_queue);
    }

    public T Dequeue()
    {
        while (true)
        {
            if (_queue.TryTake(out var item))
                return item;

            Monitor.Wait(_queue);
        }
    }

    public bool TryDequeue(out T item, int millisecondsTimeout = -1)
    {
        return _queue.TryTake(out item, millisecondsTimeout);
    }

    public int Count => _queue.Count;
}
```

