#define MAX_PACKETS 1000000000

typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct PacketNode {
    DataPacket data;
    struct PacketNode *next;
} PacketNode;

typedef struct DataStore {
    PacketNode **hash_table;
    int hash_size;
    pthread_mutex_t mutex;
} DataStore;

DataStore *data_store_init(int hash_size) {
    DataStore *store = (DataStore *)malloc(sizeof(DataStore));
    store->hash_table = (PacketNode **)calloc(hash_size, sizeof(PacketNode *));
    store->hash_size = hash_size;
    pthread_mutex_init(&store->mutex, NULL);
    return store;
}

int packet_hash(DataPacket *packet, int size) {
    return abs(packet->packet_id % size);
}

void add_packet(DataStore *store, DataPacket *packet) {
    pthread_mutex_lock(&store->mutex);
    int hash = packet_hash(packet, store->hash_size);
    PacketNode **head = &store->hash_table[hash];
    while (*head != NULL) {
        if ((*head)->data.packet_id == packet->packet_id) {
            // Duplicate packet_id handling
            pthread_mutex_unlock(&store->mutex);
            return;
        }
        head = &(*head)->next;
    }
    PacketNode *new_node = (PacketNode *)malloc(sizeof(PacketNode));
    new_node->data = *packet;
    new_node->next = *head;
    *head = new_node;
    pthread_mutex_unlock(&store->mutex);
}

void remove_packet(DataStore *store, int packet_id) {
    pthread_mutex_lock(&store->mutex);
    for (int i = 0; i < store->hash_size; i++) {
        PacketNode **head = &store->hash_table[i];
        while (*head != NULL) {
            if ((*head)->data.packet_id == packet_id) {
                PacketNode *temp = *head;
                *head = (*head)->next;
                free(temp);
                pthread_mutex_unlock(&store->mutex);
                return;
            }
            head = &(*head)->next;
        }
    }
    pthread_mutex_unlock(&store->mutex);
}

int get_packet_count(DataStore *store) {
    int count = 0;
    pthread_mutex_lock(&store->mutex);
    for (int i = 0; i < store->hash_size; i++) {
        PacketNode *head = store->hash_table[i];
        while (head != NULL) {
            count++;
            head = head->next;
        }
    }
    pthread_mutex_unlock(&store->mutex);
    return count;
}

