    manager->count = 0;
}

int add_packet(PacketManager *manager, DataPacket packet) {
    if (manager->count >= MAX_PACKETS) return -1; // Array is full
    manager->packets[manager->count++] = packet;
    return 0;
}

int remove_packet_by_id(PacketManager *manager, int packet_id) {
    for (int i = 0; i < manager->count; ++i) {
        if (manager->packets[i].packet_id == packet_id) {
            for (; i < manager->count - 1; ++i) {
                manager->packets[i] = manager->packets[i + 1];
            }
            manager->count--;
            return 0;
        }
    }
    return -1; // Packet not found
}

int get_packet_count(PacketManager *manager) {
    return manager->count;
}

void sort_packets_by_timestamp(PacketManager *manager) {
    for (int i = 0; i < manager->count - 1; ++i) {
        for (int j = 0; j < manager->count - i - 1; ++j) {
            if (manager->packets[j].timestamp > manager->packets[j + 1].timestamp) {
                DataPacket temp = manager->packets[j];
                manager->packets[j] = manager->packets[j + 1];
                manager->packets[j + 1] = temp;
            }
        }
    }
}

