import java.util.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.spark.sql.Dataset;
import org.apache.spark.sql.Row;
import org.apache.spark.sql.SparkSession;
import org.apache.spark.streaming.Durations;
import org.apache.spark.streaming.api.functions.ForeachBatchFunction;
import org.apache.spark.streaming.api.java.JavaDStream;
import org.apache.spark.streaming.api.java.JavaInputDStream;
import org.apache.spark.streaming.kafka010.ConsumerStrategies.Subscribe;
import org.apache.spark.streaming.kafka010.KafkaUtils;
import org.apache.spark.streaming.kafka010.LocationStrategies.PreferConsistent;

public class HFTTransactionProcessor {

    public static void main(String[] args) {
        SparkSession spark = SparkSession.builder()
                .appName("HFT Transaction Processor")
                .config("spark.master", "local[*]")
                .getOrCreate();

        Map<String, Object> kafkaParams = new HashMap<>();
        kafkaParams.put("bootstrap.servers", "localhost:9092");
        kafkaParams.put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        kafkaParams.put("value.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        kafkaParams.put("group.id", "hft-transaction-group");
        kafkaParams.put("auto.offset.reset", "latest");
        kafkaParams.put("enable.auto.commit", false);

        Set<String> topics = Collections.singleton("hft-transactions");

        JavaInputDStream<ConsumerRecord<String, String>> stream = KafkaUtils.createDirectStream(
                spark.sparkContext(),
                PreferConsistent,
                Subscribe.topics(topics),
                kafkaParams
        );

        JavaDStream<JSONObject> jsonObjects = stream.map(record -> new JSONObject(record.value()));

        Dataset<Row> transactions = spark.read().json(jsonObjects.rdd());

        transactions.filter("transaction_id IS NOT NULL")
                .groupBy("asset_type")
                .agg(sum("transaction_amount").as("total_volume"))
                .writeStream()
                .outputMode("complete")
                .format("kafka")
                .option("kafka.bootstrap.servers", "localhost:9092")
                .option("topic", "hft-transaction-volume")
                .start()
                .awaitTermination();
    }
}
```

This code snippet demonstrates a basic implementation of the HFT transaction processor using Apache Spark and Kafka. It reads JSON objects from a Kafka topic, filters out duplicate transactions based on `transaction_id`, calculates the total transaction volume for each unique asset type, and writes the aggregated data back to Kafka. The system can be scaled by adding more nodes to the Spark cluster or by configuring Kafka with multiple brokers. Error handling and performance monitoring would need to be added in a production environment.']

