    private readonly Dictionary<string, object> _config = new Dictionary<string, object>();
    private readonly Dictionary<Type, JsonSerializerSettings> _serializerSettings = new Dictionary<Type, JsonSerializerSettings>();

    public ConfigurationManager()
    {
        LoadConfiguration();
    }

    private void LoadConfiguration()
    {
        LoadJsonFile("config.json");
        LoadEnvironmentVariables();
        LoadCommandLineArguments();

        ValidateAndFixConfig();
    }

    private void LoadJsonFile(string filePath)
    {
        if (File.Exists(filePath))
        {
            var json = File.ReadAllText(filePath);
            var settings = new JsonSerializerSettings
            {
                NullValueHandling = NullValueHandling.Ignore,
                MissingMemberHandling = MissingMemberHandling.Ignore
            };
            _config = JsonConvert.DeserializeObject<Dictionary<string, object>>(json, settings);
            _serializerSettings[typeof(Dictionary<string, object>)] = settings;
        }
    }

    private void LoadEnvironmentVariables()
    {
        foreach (var envVar in Environment.GetEnvironmentVariables())
        {
            var key = envVar.ToString();
            if (_config.ContainsKey(key))
                _config[key] = Environment.GetEnvironmentVariable(key);
        }
    }

    private void LoadCommandLineArguments()
    {
        var args = Environment.GetCommandLineArgs();
        for (int i = 1; i < args.Length; i += 2)
        {
            var key = args[i];
            if (_config.ContainsKey(key))
                _config[key] = args[i + 1];
        }
    }

    private void ValidateAndFixConfig()
    {
        // Implement validation and fixing logic here
    }

