int execute_shell_command(const char* command, int* output_size, char** output_buffer) {
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        perror("pipe");
        return -1;
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        close(pipefd[0]);
        close(pipefd[1]);
        return -1;
    } else if (pid == 0) {
        close(pipefd[0]);

        dup2(pipefd[1], STDOUT_FILENO);
        close(pipefd[1]);

        execl("/bin/sh", "sh", "-c", command, NULL);

        perror("exec");
        exit(EXIT_FAILURE);
    }

    close(pipefd[1]);

    *output_size = read(pipefd[0], output_buffer, 4096);
    if (*output_size == -1) {
        perror("read");
        close(pipefd[0]);
        return -1;
    }

    close(pipefd[0]);
    waitpid(pid, NULL, 0);

    return 0;
}

