import csv
from collections import defaultdict
import random

class DataProcessor:
    def __init__(self, minValue=0, maxValue=0):
        self.minValue = minValue if minValue <= maxValue else maxValue - 1
        self.maxValue = maxValue

    def processAndTransformData(self, filePath, columnsToTransform):
        frequencyDict = defaultdict(int)
        with open(filePath, mode='r') as file:
            reader = csv.DictReader(file)
            for row in reader:
                for column in columnsToTransform:
                    value = row[column]
                    if isinstance(value, str) and value.strip():
                        frequencyDict[value] += 1
        return dict(frequencyDict)

    def GetRandomFloat(self):
        return random.uniform(self.minValue, self.maxValue)

    def GetRandomInt(self):
        return random.randint(self.minValue, self.maxValue)

    def GetExclusiveRandomInt(self):
        if self.minValue == self.maxValue - 1:
            raise ValueError("Range is too small to generate exclusive random integers.")
        return random.randint(self.minValue + 1, self.maxValue)

    def ToString(self):
        return f"Range: [{self.minValue}, {self.maxValue}]"

# Example usage
processor = DataProcessor(10, 20)
print(processor.processAndTransformData('data.csv', ['ColumnA', 'ColumnB']))
print(processor.GetRandomFloat())
print(processor.GetRandomInt())
print(processor.GetExclusiveRandomInt())
print(processor.ToString())
