pthread_cond_t packets_cond = PTHREAD_COND_INITIALIZER;

u_char* resolve_hostname(const char* hostname) {
    struct addrinfo hints, *res, *p;
    u_char* ip_address = (u_char*)malloc(INET_ADDRSTRLEN);

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in* h = (struct sockaddr_in*)p->ai_addr;
        strcpy((char*)ip_address, inet_ntoa(h->sin_addr));
    }

    freeaddrinfo(res);
    return ip_address;
}

void add_packet(DataPacket packet) {
    pthread_mutex_lock(&packets_lock);
    if (packet_count < MAX_PACKETS) {
        packets[packet_count++] = packet;
        pthread_cond_signal(&packets_cond);
    } else {
        // Add to pending queue or disk storage
    }
    pthread_mutex_unlock(&packets_lock);
}

void remove_packet(int packet_id) {
    pthread_mutex_lock(&packets_lock);
    for (int i = 0; i < packet_count; i++) {
        if (packets[i].packet_id == packet_id) {
            memmove(&packets[i], &packets[i + 1], sizeof(DataPacket) * (packet_count - i - 1));
            packet_count--;
            pthread_cond_signal(&packets_cond);
            break;
        }
    }
    pthread_mutex_unlock(&packets_lock);
}

