        while (packet_count < MAX_ACTIVE_PACKETS && packet_count > 0) {
            DataPacket packet = packets[--packet_count];
            // Process packet
        }
        if (packet_count == 0) {
            pthread_cond_wait(&packets_cond, &packets_lock);
        }
        pthread_mutex_unlock(&packets_lock);
    }
    return NULL;
}

int main() {
    pthread_t threads[10];

    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, worker_thread, NULL);
    }

    // Add packets and perform operations

