typedef struct UserSession {
    int session_id;
    char user_email[100];
    time_t last_active_time;
    int session_duration;
} UserSession;

typedef struct SessionList {
    UserSession *sessions;
    size_t count;
    size_t capacity;
} SessionList;

SessionList* create_session_list() {
    SessionList *list = (SessionList*)malloc(sizeof(SessionList));
    list->sessions = NULL;
    list->count = 0;
    list->capacity = 0;
    return list;
}

void destroy_session_list(SessionList *list) {
    if (list != NULL) {
        free(list->sessions);
        free(list);
    }
}

int add_user_session(SessionList *list, int session_id, const char *user_email, time_t last_active_time, int session_duration) {
    if (session_id < 0 || user_email == NULL || strlen(user_email) >= sizeof(list->sessions[0].user_email)) {
        return -1; // Invalid input
    }
    if (list->count >= list->capacity) {
        size_t new_capacity = (list->capacity == 0 ? 4 : list->capacity * 2);
        UserSession *new_sessions = realloc(list->sessions, new_capacity * sizeof(UserSession));
        if (new_sessions == NULL) {
            return -1; // Memory allocation failed
        }
        list->sessions = new_sessions;
        list->capacity = new_capacity;
    }
    list->sessions[list->count].session_id = session_id;
    strcpy(list->sessions[list->count].user_email, user_email);
    list->sessions[list->count].last_active_time = last_active_time;
    list->sessions[list->count].session_duration = session_duration;
    list->count++;
    return 0;
}

int remove_user_session(SessionList *list, int session_id) {
    for (size_t i = 0; i < list->count; i++) {
        if (list->sessions[i].session_id == session_id) {
            memmove(&list->sessions[i], &list->sessions[i + 1], (list->count - i - 1) * sizeof(UserSession));
            list->count--;
            return 0;
        }
    }
    return -1; // Session not found
}

size_t get_active_sessions_count(SessionList *list, time_t threshold_time) {
    size_t count = 0;
    for (size_t i = 0; i < list->count; i++) {
        if (difftime(time(NULL), list->sessions[i].last_active_time) > threshold_time) {
            count++;
        }
    }
    return count;
}

int main() {
    SessionList *session_list = create_session_list();
    add_user_session(session_list, 1, "user1@example.com", time(NULL), 3600);
    add_user_session(session_list, 2, "user2@example.com", time(NULL) - 3601, 7200);

    printf("Active sessions count: %zu\n", get_active_sessions_count(session_list, 3600));

    remove_user_session(session_list, 2);
    printf("Active sessions count after removal: %zu\n", get_active_sessions_count(session_list, 3600));

    destroy_session_list(session_list);
    return 0;
}
