struct DataPacket {
    int packet_id;
    long timestamp;
    int payload_size;
};

class DynamicDataManager {
private:
    std::vector<DataPacket> packets;
    std::mutex mtx;
    int min_value;
    int max_value;
    double interval;

public:
    DynamicDataManager(int min_val, int max_val) : min_value(min_val), max_value(max_val) {
        if (min_value > max_value) {
            throw std::invalid_argument("Invalid range: Min value must be less than or equal to max value.");
        }
        time_t now = time(nullptr);
        interval = difftime(now, 1970) * 1000; // Convert to milliseconds since epoch
    }

    ~DynamicDataManager() {}

    void addPacket(const DataPacket& packet) {
        std::lock_guard<std::mutex> lock(mtx);
        packets.push_back(packet);
    }

    bool removePacket(int packet_id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::find_if(packets.begin(), packets.end(), [packet_id](const DataPacket& p) { return p.packet_id == packet_id; });
        if (it != packets.end()) {
            packets.erase(it);
            return true;
        }
        return false;
    }

    int getPacketCount() const {
        std::lock_guard<std::mutex> lock(mtx);
        return packets.size();
    }

    void sortPacketsByTimestamp() {
        std::lock_guard<std::mutex> lock(mtx);
        std::sort(packets.begin(), packets.end(), [](const DataPacket& a, const DataPacket& b) { return a.timestamp < b.timestamp; });
    }

    float getRandomFloat(float min, float max) {
        return static_cast<float>(rand()) / (static_cast<float>(RAND_MAX / (max - min))) + min;
    }

    int getRandomInt(int min, int max) {
        return rand() % (max - min) + min;
    }

    void randomValueInterval(float frequency) {
        double now = difftime(time(nullptr), 1970) * 1000;
        if (now - interval > 1 / frequency) {
            // Generate and use random value
            interval = now; // Reset interval for the next time-based request
        }
    }

    std::string toString() const {
        return "DynamicDataManager: min_value=" + std::to_string(min_value) + ", max_value=" + std::to_string(max_value);
    }

    void serialize(const std::string& filename) const {
        std::ofstream ofs(filename, std::ios::binary);
        if (ofs.is_open()) {
            size_t size = packets.size();
            ofs.write(reinterpret_cast<const char*>(&size), sizeof(size));
            for (const auto& packet : packets) {
                ofs.write(reinterpret_cast<const char*>(&packet.packet_id), sizeof(packet.packet_id));
                ofs.write(reinterpret_cast<const char*>(&packet.timestamp), sizeof(packet.timestamp));
                ofs.write(reinterpret_cast<const char*>(&packet.payload_size), sizeof(packet.payload_size));
            }
            ofs.close();
        } else {
            std::cerr << "Failed to open file for writing: " << filename << std::endl;
        }
    }

    void deserialize(const std::string& filename) {
        std::ifstream ifs(filename, std::ios::binary);
        if (ifs.is_open()) {
            size_t size;
            ifs.read(reinterpret_cast<char*>(&size), sizeof(size));
            packets.resize(size);
            for (auto& packet : packets) {
                ifs.read(reinterpret_cast<char*>(&packet.packet_id), sizeof(packet.packet_id));
                ifs.read(reinterpret_cast<char*>(&packet.timestamp), sizeof(packet.timestamp));
                ifs.read(reinterpret_cast<char*>(&packet.payload_size), sizeof(packet.payload_size));
            }
            ifs.close();
        } else {
            std::cerr << "Failed to open file for reading: " << filename << std::endl;
        }
    }
};
