};

class DynamicDataProcessor {
private:
    std::vector<DataPacket> packets;
    std::mutex mutex;
    int minValue;
    int maxValue;
    double interval;
    std::mt19937 generator;

public:
    DynamicDataProcessor(int min, int max, double interval)
        : minValue(min), maxValue(max), interval(interval), generator(std::random_device()()) {
        if (min > max) throw std::invalid_argument("Invalid range");
    }

    void addPacket() {
        std::lock_guard<std::mutex> lock(mutex);
        DataPacket packet;
        packet.packet_id = packets.size();
        packet.timestamp = time(nullptr);
        packet.payload_size = generateRandomValueInRange(minValue, maxValue);
        packets.push_back(packet);
    }

    bool removePacket(int id) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = std::find_if(packets.begin(), packets.end(),
                               [id](const DataPacket& p) { return p.packet_id == id; });
        if (it != packets.end()) {
            packets.erase(it);
            return true;
        }
        return false;
    }

    size_t getPacketCount() const {
        std::lock_guard<std::mutex> lock(mutex);
        return packets.size();
    }

    void sortPacketsByTimestamp() {
        std::lock_guard<std::mutex> lock(mutex);
        std::sort(packets.begin(), packets.end(),
                 [](const DataPacket& a, const DataPacket& b) { return a.timestamp < b.timestamp; });
    }

    float generateRandomFloatInRange(float min, float max) {
        std::uniform_real_distribution<> dis(min, max);
        return dis(generator);
    }

    int generateRandomValueInRange(int min, int max) {
        std::uniform_int_distribution<> dis(min, max - 1);
        return dis(generator);
    }

    template <typename T>
    T generateRandomValueAtInterval(T currentValue, double frequency) {
        static time_t lastTime = time(nullptr);
        time_t currentTime = time(nullptr);
        if (currentTime - lastTime >= interval / frequency) {
            lastTime = currentTime;
            return generateRandomValueInRange(minValue, maxValue);
        }
        return currentValue;
    }

    std::string ToString() const {
        std::lock_guard<std::mutex> lock(mutex);
        std::ostringstream oss;
        oss << "Range: [" << minValue << ", " << maxValue << "]";
        return oss.str();
    }

    // Serialization and deserialization methods (not shown for brevity)
};

