        return timestamp < other.timestamp;
    }
};

class DynamicDataProcessor {
private:
    std::vector<DataPacket> packets;
    std::mutex mtx;
    std::condition_variable cv;
    int min_value;
    int max_value;
    size_t interval;

public:
    DynamicDataProcessor(int minValue, int maxValue, size_t interval)
        : min_value(minValue), max_value(maxValue), interval(interval) {
        if (min_value > max_value) throw std::invalid_argument("Invalid value range");
    }

    void addPacket(const DataPacket& packet) {
        std::lock_guard<std::mutex> lock(mtx);
        packets.push_back(packet);
        cv.notify_one();
    }

    bool removePacket(int packetId) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = std::find_if(packets.begin(), packets.end(), [packetId](const DataPacket& p) { return p.packet_id == packetId; });
        if (it != packets.end()) {
            packets.erase(it);
            cv.notify_one();
            return true;
        }
        return false;
    }

    size_t getPacketCount() const {
        std::lock_guard<std::mutex> lock(mtx);
        return packets.size();
    }

    void sortPacketsByTimestamp() {
        std::sort(packets.begin(), packets.end());
    }

