#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define DataPacket structure
typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

// Define the dynamic array structure
typedef struct {
    DataPacket *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} PacketArray;

// Function prototypes
void init_packet_array(PacketArray *array, size_t initial_capacity);
void add_packet(PacketArray *array, int packet_id, time_t timestamp, size_t payload_size);
void remove_packet(PacketArray *array, int packet_id);
size_t get_packet_count(const PacketArray *array);
void sort_packets_by_timestamp(PacketArray *array);
int compare_packets_by_timestamp(const void *a, const void *b);
void log_operation(const char *operation, int packet_id, time_t timestamp, size_t payload_size);
void limit_array_size(PacketArray *array, size_t max_size);
void free_packet_array(PacketArray *array);

// Initialize the dynamic array
void init_packet_array(PacketArray *array, size_t initial_capacity) {
    array->data = malloc(initial_capacity * sizeof(DataPacket));
    if (array->data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
}

// Add a new packet to the dynamic array
void add_packet(PacketArray *array, int packet_id, time_t timestamp, size_t payload_size) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        limit_array_size(array, array->capacity * 2);
    }
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].packet_id == packet_id) {
            array->data[i].payload_size = payload_size;
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }
    array->data[array->size++] = (DataPacket){packet_id, timestamp, payload_size};
    pthread_mutex_unlock(&array->lock);
}

// Remove a packet by packet_id
void remove_packet(PacketArray *array, int packet_id) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].packet_id == packet_id) {
            memmove(array->data + i, array->data + i + 1, (array->size - i - 1) * sizeof(DataPacket));
            array->size--;
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

// Get the total number of packets
size_t get_packet_count(const PacketArray *array) {
    return array->size;
}

// Sort packets by timestamp in ascending order
void sort_packets_by_timestamp(PacketArray *array) {
    pthread_mutex_lock(&array->lock);
    qsort(array->data, array->size, sizeof(DataPacket), compare_packets_by_timestamp);
    pthread_mutex_unlock(&array->lock);
}

// Custom comparator function for sorting by timestamp
int compare_packets_by_timestamp(const void *a, const void *b) {
    return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp;
}

// Log an operation to a file
void log_operation(const char *operation, int packet_id, time_t timestamp, size_t payload_size) {
    FILE *log_file = fopen("packet_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    fprintf(log_file, "%s %d %ld %zu\n", operation, packet_id, timestamp, payload_size);
    fclose(log_file);
}

// Limit the array size and remove the least recently used packet if necessary
void limit_array_size(PacketArray *array, size_t max_size) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= max_size) {
        // Sort by timestamp to find the least recently used packet
        sort_packets_by_timestamp(array);
        remove_packet(array, array->data[0].packet_id);
    }
    array->capacity = max_size;
    pthread_mutex_unlock(&array->lock);
}

// Free the memory allocated for the dynamic array
void free_packet_array(PacketArray *array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
}
