#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct UserSession {
    int session_id;
    char user_name[100];
    time_t session_start_time;
    time_t last_activity_time;
    struct UserSession *next;
} UserSession;

typedef struct SessionManager {
    pthread_mutex_t lock;
    UserSession *head;
    int max_sessions_per_user;
    void (*expire_session)(int session_id);
} SessionManager;

UserSession* create_session(int session_id, const char *user_name, time_t start_time) {
    UserSession *session = (UserSession*)malloc(sizeof(UserSession));
    if (session) {
        session->session_id = session_id;
        strcpy(session->user_name, user_name);
        session->session_start_time = start_time;
        session->last_activity_time = start_time;
        session->next = NULL;
    }
    return session;
}

void add_session(SessionManager *manager, int session_id, const char *user_name) {
    pthread_mutex_lock(&manager->lock);
    UserSession *current = manager->head;
    while (current) {
        if (current->session_id == session_id) {
            current->last_activity_time = time(NULL);
            pthread_mutex_unlock(&manager->lock);
            return; // Update existing session
        }
        current = current->next;
    }

    UserSession *new_session = create_session(session_id, user_name, time(NULL));
    if (new_session) {
        new_session->next = manager->head;
        manager->head = new_session;

        int session_count = 0;
        current = manager->head;
        while (current) {
            session_count++;
            if (session_count > manager->max_sessions_per_user) {
                // Handle max sessions per user limit
                break;
            }
            current = current->next;
        }

        pthread_mutex_unlock(&manager->lock);
    } else {
        pthread_mutex_unlock(&manager->lock);
        printf("Failed to allocate memory for session.\n");
    }
}

void remove_session(SessionManager *manager, int session_id) {
    pthread_mutex_lock(&manager->lock);
    UserSession *current = manager->head;
    UserSession *prev = NULL;

    while (current) {
        if (current->session_id == session_id) {
            if (prev) {
                prev->next = current->next;
            } else {
                manager->head = current->next;
            }
            free(current);
            pthread_mutex_unlock(&manager->lock);
            return; // Session removed
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    printf("Session with id %d not found.\n", session_id);
}

int get_active_sessions_count(SessionManager *manager) {
    int count = 0;
    UserSession *current = manager->head;
    while (current) {
        count++;
        current = current->next;
    }
    return count;
}

void expire_inactive_sessions(SessionManager *manager, time_t timeout) {
    pthread_mutex_lock(&manager->lock);
    UserSession *current = manager->head;
    UserSession *prev = NULL;

    while (current) {
        if ((time(NULL) - current->last_activity_time) > timeout) {
            manager->expire_session(current->session_id);
            if (prev) {
                prev->next = current->next;
            } else {
                manager->head = current->next;
            }
            free(current);
            current = prev->next; // Move to the next node after removing
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void notify_session_expiry(int session_id) {
    printf("Session %d has expired.\n", session_id); // Replace with actual notification logic
