    struct UserSession *next;
    pthread_mutex_t lock; // Mutex for concurrent access
} UserSession;

typedef struct SessionList {
    UserSession *head;
    pthread_mutex_t list_lock; // Mutex for the session list
} SessionList;

// Function to create a new UserSession
UserSession* create_session(int id, const char* user, time_t login_time) {
    UserSession *session = (UserSession*)malloc(sizeof(UserSession));
    if (session == NULL) return NULL;

    pthread_mutex_init(&session->lock, NULL);
    session->session_id = id;
    strncpy(session->user_name, user, 100);
    session->login_time = login_time;
    session->last_activity_time = login_time;
    session->next = NULL;

    return session;
}

// Function to add a new session
void add_session(SessionList *list, UserSession *session) {
    pthread_mutex_lock(&list->list_lock);
    if (list->head == NULL) {
        list->head = session;
    } else {
        UserSession *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = session;
    }
    pthread_mutex_unlock(&list->list_lock);
}

// Function to remove a session by session_id
void remove_session(SessionList *list, int id) {
    pthread_mutex_lock(&list->list_lock);
    UserSession *current = list->head;
    UserSession *previous = NULL;

    while (current != NULL) {
        if (current->session_id == id) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            pthread_mutex_destroy(&current->lock);
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->list_lock);
}

// Function to get the total number of active sessions
int get_active_sessions(SessionList *list) {
    int count = 0;
    pthread_mutex_lock(&list->list_lock);
    UserSession *current = list->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&list->list_lock);
    return count;
}

