    add_session(&session_list, session1);

    UserSession *session2 = create_session(2, "user2", time(NULL) - 3600);
    add_session(&session_list, session2);

    printf("Active sessions: %d\n", get_active_sessions(&session_list));

    remove_session(&session_list, 1);

    printf("Active sessions after removal: %d\n", get_active_sessions(&session_list));

