} SessionManager;

void add_session(SessionManager *manager, int session_id, const char *user_agent, int session_duration) {
    UserSession *new_session = (UserSession *)malloc(sizeof(UserSession));
    new_session->session_id = session_id;
    new_session->last_active_time = time(NULL);
    new_session->user_agent = strdup(user_agent);
    new_session->session_duration = session_duration;
    new_session->next = manager->head;
    manager->head = new_session;
    manager->count++;
}

void remove_session(SessionManager *manager, int session_id) {
    UserSession *current = manager->head;
    UserSession *previous = NULL;

    while (current != NULL) {
        if (current->session_id == session_id) {
            if (previous == NULL)
                manager->head = current->next;
            else
                previous->next = current->next;
            free(current->user_agent);
            free(current);
            manager->count--;
            return;
        }
        previous = current;
        current = current->next;
    }
}

