typedef struct SessionList {
    UserSession *head;
    pthread_mutex_t lock;
} SessionList;

void init_session_list(SessionList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void add_session(SessionList *list, const char *session_id, const char *user_name, time_t start_time, time_t activity_time) {
    pthread_mutex_lock(&list->lock);
    UserSession *new_session = (UserSession *)malloc(sizeof(UserSession));
    strcpy(new_session->session_id, session_id);
    strcpy(new_session->user_name, user_name);
    new_session->session_start_time = start_time;
    new_session->last_activity_time = activity_time;
    new_session->next = list->head;
    list->head = new_session;
    pthread_mutex_unlock(&list->lock);
}

void remove_session(SessionList *list, const char *session_id) {
    pthread_mutex_lock(&list->lock);
    UserSession *current = list->head;
    UserSession *prev = NULL;

    while (current != NULL) {
        if (strcmp(current->session_id, session_id) == 0) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

int get_active_sessions(SessionList *list) {
    int count = 0;
    pthread_mutex_lock(&list->lock);
    UserSession *current = list->head;

    while (current != NULL) {
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return count;
}

void expire_sessions(SessionList *list, time_t timeout) {
    pthread_mutex_lock(&list->lock);
    UserSession *current = list->head;
    UserSession *prev = NULL;

    while (current != NULL) {
        if ((time(NULL) - current->last_activity_time) > timeout) {
            remove_session(list, current->session_id);
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}
