#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS_PER_USER 5

typedef struct UserSession {
    int session_id;
    char user_name[100];
    time_t session_start_time;
    time_t last_activity_time;
    struct UserSession* next;
} UserSession;

typedef struct SessionManager {
    UserSession** sessions_by_id;
    int max_sessions_per_user;
    void (*notify_session_expiry)(int session_id);
    // Add any additional fields as needed
} SessionManager;

UserSession* createSession(int session_id, const char* user_name) {
    UserSession* session = (UserSession*)malloc(sizeof(UserSession));
    if (session != NULL) {
        session->session_id = session_id;
        strncpy(session->user_name, user_name, sizeof(session->user_name) - 1);
        time(&session->session_start_time);
        time(&session->last_activity_time);
        session->next = NULL;
    }
    return session;
}

void addSession(SessionManager* manager, int session_id, const char* user_name) {
    if (manager == NULL || user_name == NULL) {
        return;
    }

    UserSession* new_session = createSession(session_id, user_name);
    if (new_session == NULL) {
        return;
    }

    // Add to sessions_by_id
    if (manager->sessions_by_id[session_id % MAX_USER_IDS] == NULL) {
        manager->sessions_by_id[session_id % MAX_USER_IDS] = new_session;
    } else {
        UserSession* current = manager->sessions_by_id[session_id % MAX_USER_IDS];
        while (current->next != NULL) {
            if (current->session_id == session_id) {
                // Update existing session
                time(&new_session->last_activity_time);
                free(current);
                new_session->next = current->next;
                manager->sessions_by_id[session_id % MAX_USER_IDS] = new_session;
                return;
            }
            current = current->next;
        }
        current->next = new_session;
    }
}

void removeSession(SessionManager* manager, int session_id) {
    if (manager == NULL || manager->sessions_by_id == NULL) {
        return;
    }

    UserSession** head_ptr = &manager->sessions_by_id[session_id % MAX_USER_IDS];
    while (*head_ptr != NULL) {
        if ((*head_ptr)->session_id == session_id) {
            UserSession* temp = *head_ptr;
            *head_ptr = (*head_ptr)->next;
            free(temp);
            return;
        }
        head_ptr = &(*head_ptr)->next;
    }
}

int getActiveSessionsCount(SessionManager* manager) {
    int count = 0;
    for (int i = 0; i < MAX_USER_IDS; ++i) {
        UserSession* current = manager->sessions_by_id[i];
        while (current != NULL) {
            count++;
            current = current->next;
        }
    }
    return count;
}

void notifySessionsExpiry(SessionManager* manager, time_t now, int timeout) {
    for (int i = 0; i < MAX_USER_IDS; ++i) {
        UserSession* current = manager->sessions_by_id[i];
        while (current != NULL) {
            if ((now - current->last_activity_time) > timeout) {
                manager->notify_session_expiry(current->session_id);
                removeSession(manager, current->session_id);
            }
            current = current->next;
        }
    }
}

void initializeWorld(SessionManager* manager, int max_sessions_per_user, void (*notify_expiry)(int)) {
    if (manager == NULL) {
        return;
    }

    manager->sessions_by_id = (UserSession**)calloc(MAX_USER_IDS, sizeof(UserSession*));
    manager->max_sessions_per_user = max_sessions_per_user;
    manager->notify_session_expiry = notify_expiry;

    // Initialize any other fields as needed
}

void cleanupWorld(SessionManager* manager) {
    if (manager == NULL || manager->sessions_by_id == NULL) {
        return;
    }

    for (int i = 0; i < MAX_USER_IDS; ++i) {
        UserSession* current = manager->sessions_by_id[i];
        while (current != NULL) {
            UserSession* next = current->next;
            free(current);
            current = next;
        }
    }
    free(manager->sessions_by_id);

    // Clean up any other fields as needed
}
