typedef struct ResourceRequest {
    int request_id;
    char resource_type[100];
    time_t requested_time;
    int status;
    int current_priority;
} ResourceRequest;

// Function prototypes
void add_request(ResourceRequest **requests, int *count, int id, const char *type, int priority);
void update_request(ResourceRequest *requests, int count, int id, int new_status, int new_priority);
int get_pending_requests_count(ResourceRequest *requests, int count);
void sort_requests_by_time(ResourceRequest *requests, int count);

// Main function to demonstrate the request manager
int main() {
    ResourceRequest *requests = NULL;
    int count = 0;

    add_request(&requests, &count, 1, "CPU", 5);
    add_request(&requests, &count, 2, "Memory", 3);
    update_request(requests, count, 1, 2, 7);

    sort_requests_by_time(requests, count);

    printf("Total pending requests: %d\n", get_pending_requests_count(requests, count));

    free(requests);
    return 0;
}

// Function to add a new request
void add_request(ResourceRequest **requests, int *count, int id, const char *type, int priority) {
    ResourceRequest *new_request = (ResourceRequest *)malloc(sizeof(ResourceRequest));
    new_request->request_id = id;
    strcpy(new_request->resource_type, type);
    new_request->requested_time = time(NULL);
    new_request->status = 1; // Assuming status 1 is pending
    new_request->current_priority = priority;

    *requests = realloc(*requests, (*count + 1) * sizeof(ResourceRequest));
    (*requests)[*count] = *new_request;
    (*count)++;
}

// Function to update an existing request
void update_request(ResourceRequest *requests, int count, int id, int new_status, int new_priority) {
    for (int i = 0; i < count; i++) {
        if (requests[i].request_id == id) {
            requests[i].status = new_status;
            requests[i].current_priority = new_priority;
            return;
        }
    }
}

// Function to get the total number of pending requests
int get_pending_requests_count(ResourceRequest *requests, int count) {
    int pending_count = 0;
    for (int i = 0; i < count; i++) {
        if (requests[i].status == 1) { // Assuming status 1 is pending
            pending_count++;
        }
    }
    return pending_count;
}

// Function to sort requests by requested time in descending order
void sort_requests_by_time(ResourceRequest *requests, int count) {
    for (int i = 0; i < count - 1; i++) {
        for (int j = 0; j < count - i - 1; j++) {
            if (requests[j].requested_time < requests[j + 1].requested_time) {
                ResourceRequest temp = requests[j];
                requests[j] = requests[j + 1];
                requests[j + 1] = temp;
            }
        }
    }
}
