    let mut parsed_nodes = Vec::new();

    for line in reader.lines() {
        let line = line.map_err(|e| format!("Failed to read line: {}", e))?;
        // Parse each line and add nodes to the vector
        parsed_nodes.push(Node::parse(&line));
    }

    if let Err(e) = generate_ir_code(parsed_nodes) {
        println!("Error generating IR code for file {}: {}", file_path.display(), e);
    } else {
        println!("Successfully generated IR code for file: {}", file_path.display());
    }

    let elapsed_time = start_time.elapsed();
    println!("Processing time for file {}: {:?}", file_path.display(), elapsed_time);

    if let Some(parent) = file_path.parent() {
        fs::create_dir_all(parent).unwrap();
    }
}

