    let processed_files: ProcessedFiles = Arc::new(Mutex::new(HashMap::new()));

    for entry in fs::read_dir(&directory_path) {
        let entry = entry.map_err(|e| format!("Failed to read directory entry: {}", e))?;
        if let Some(file_name) = entry.file_name().to_str() {
            if file_name.ends_with(".grammar") {
                file_queue.lock().unwrap().push_back(entry.path());
            }
        }
    }

    let mut handles = vec![];

    while !file_queue.lock().unwrap().is_empty() && handles.len() < max_threads {
        if let Some(file_path) = file_queue.lock().unwrap().pop_front() {
