#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_PACKETS 1000
#define SLIDING_WINDOW_SIZE 100

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket *packets[MAX_PACKETS];
    size_t count;
    size_t total_payload_size;
    pthread_mutex_t lock;
    FILE *log_file;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->count = 0;
    manager->total_payload_size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->log_file = fopen("packet_manager.log", "a");
}

void log_operation(PacketManager *manager, const char *operation) {
    time_t now = time(NULL);
    fprintf(manager->log_file, "[%s] %s\n", ctime(&now), operation);
}

int add_packet(PacketManager *manager, int packet_id, time_t timestamp, size_t payload_size) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_PACKETS) {
        log_operation(manager, "Add failed: Packet manager is full.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    DataPacket *packet = malloc(sizeof(DataPacket));
    packet->packet_id = packet_id;
    packet->timestamp = timestamp;
    packet->payload_size = payload_size;
    manager->packets[manager->count++] = packet;
    manager->total_payload_size += payload_size;
    log_operation(manager, "Packet added.");
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_packet(PacketManager *manager, int packet_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i]->packet_id == packet_id) {
            free(manager->packets[i]);
            memmove(&manager->packets[i], &manager->packets[i + 1], (manager->count - i - 1) * sizeof(DataPacket *));
            manager->count--;
            manager->total_payload_size -= manager->packets[i]->payload_size;
            log_operation(manager, "Packet removed.");
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    log_operation(manager, "Remove failed: Packet not found.");
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

void sort_packets(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    // Implement a sorting algorithm (e.g., quicksort)
    qsort(manager->packets, manager->count, sizeof(DataPacket *), 
          [](const void *a, const void *b) -> int {
              return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp;
          });
    log_operation(manager, "Packets sorted.");
    pthread_mutex_unlock(&manager->lock);
}

size_t get_packet_count(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    size_t count = manager->count;
    pthread_mutex_unlock(&manager->lock);
    return count;
}

void expire_packets(PacketManager *manager, time_t grace_period) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count;) {
        if (time(NULL) - manager->packets[i]->timestamp > grace_period) {
            free(manager->packets[i]);
            memmove(&manager->packets[i], &manager->packets[i + 1], (manager->count - i - 1) * sizeof(DataPacket *));
            manager->count--;
            manager->total_payload_size -= manager->packets[i]->payload_size;
        } else {
            break;
        }
    }
    log_operation(manager, "Expired packets removed.");
    pthread_mutex_unlock(&manager->lock);
}

size_t get_total_payload_size(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    size_t total_size = manager->total_payload_size;
    pthread_mutex_unlock(&manager->lock);
    return total_size;
}
