import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

public class DistributedDataProcessingPipeline {
    private final Map<String, String> whitelist;
    private final ExecutorService executorService;
    private final Random random;

    public DistributedDataProcessingPipeline() {
        this.whitelist = new ConcurrentHashMap<>();
        this.executorService = Executors.newFixedThreadPool(1000);
        this.random = new Random();
    }

    public void addJob(String jid, Runnable job) {
        if (whitelist.containsKey(jid)) {
            executorService.submit(job);
        }
    }

    public void addToWhitelist(String jid) {
        whitelist.put(jid, "approved");
    }

    public void removeFromWhitelist(String jid) {
        whitelist.remove(jid);
    }

    public void simulateMetadataService() {
        // Simulated metadata service
        IntStream.range(0, 10).forEach(i -> addToWhitelist("job" + i));
    }

    public static void main(String[] args) throws InterruptedException {
        DistributedDataProcessingPipeline pipeline = new DistributedDataProcessingPipeline();
        pipeline.simulateMetadataService();

        for (int i = 0; i < 5; i++) {
            String jid = "job" + i;
            pipeline.addJob(jid, () -> {
                System.out.println("Executing job " + jid);
                try {
                    Thread.sleep(1000 * pipeline.random.nextInt(3) + 2); // Simulate varying job execution times
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
        }

        executorService.shutdown();
        executorService.awaitTermination(1, TimeUnit.HOURS);
    }
}
```

