#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 1024
#define SLIDING_WINDOW_SIZE 32

typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char source_ip[16];
    char destination_ip[16];
    // Additional metadata fields can be added here
} DataPacket;

typedef struct PacketStorage {
    DataPacket packets[MAX_PACKETS];
    int count;
    size_t total_payload_size;
    pthread_mutex_t lock;
    time_t grace_period;
    pthread_cond_t cond;
} PacketStorage;

void init_packet_storage(PacketStorage *storage, time_t grace_period) {
    memset(storage, 0, sizeof(PacketStorage));
    storage->grace_period = grace_period;
    pthread_mutex_init(&storage->lock, NULL);
    pthread_cond_init(&storage->cond, NULL);
}

int add_packet(PacketStorage *storage, DataPacket *packet) {
    pthread_mutex_lock(&storage->lock);
    if (storage->count >= MAX_PACKETS) {
        pthread_mutex_unlock(&storage->lock);
        return -1; // Storage full
    }
    storage->packets[storage->count] = *packet;
    storage->total_payload_size += packet->payload_size;
    storage->count++;
    pthread_cond_signal(&storage->cond);
    pthread_mutex_unlock(&storage->lock);
    return 0;
}

int remove_packet(PacketStorage *storage, int packet_id) {
    pthread_mutex_lock(&storage->lock);
    for (int i = 0; i < storage->count; i++) {
        if (storage->packets[i].packet_id == packet_id) {
            for (; i < storage->count - 1; i++) {
                storage->packets[i] = storage->packets[i + 1];
            }
            storage->total_payload_size -= storage->packets[storage->count - 1].payload_size;
            storage->count--;
            pthread_cond_signal(&storage->cond);
            pthread_mutex_unlock(&storage->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&storage->lock);
    return -1; // Packet not found
}

int get_packet_count(PacketStorage *storage) {
    int count;
    pthread_mutex_lock(&storage->lock);
    count = storage->count;
    pthread_mutex_unlock(&storage->lock);
    return count;
}

void sort_packets_by_timestamp(PacketStorage *storage) {
    pthread_mutex_lock(&storage->lock);
    qsort(storage->packets, storage->count, sizeof(DataPacket), compare_packets);
    pthread_mutex_unlock(&storage->lock);
}

int compare_packets(const void *a, const void *b) {
    return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp;
}

void remove_old_packets(PacketStorage *storage) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&storage->lock);
    for (int i = 0; i < storage->count;) {
        if (difftime(current_time, storage->packets[i].timestamp) > storage->grace_period) {
            for (; i < storage->count - 1; i++) {
                storage->packets[i] = storage->packets[i + 1];
            }
            storage->total_payload_size -= storage->packets[storage->count - 1].payload_size;
            storage->count--;
        } else {
            break;
        }
    }
    pthread_mutex_unlock(&storage->lock);
}

void* packet_storage_monitor(void *arg) {
    PacketStorage *storage = (PacketStorage *)arg;
    while (1) {
        remove_old_packets(storage);
        sleep(60); // Check every minute
    }
    return NULL;
}
