#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char source_ip[16];
    char destination_ip[16];
} DataPacket;

typedef struct PacketNode {
    DataPacket data;
    struct PacketNode* next;
} PacketNode;

void addPacket(PacketNode** head, DataPacket packet) {
    PacketNode* newNode = (PacketNode*)malloc(sizeof(PacketNode));
    newNode->data = packet;
    newNode->next = *head;
    *head = newNode;
}

void removePacketById(PacketNode** head, int packet_id) {
    PacketNode* current = *head;
    PacketNode* prev = NULL;

    while (current != NULL && current->data.packet_id != packet_id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL)
        return;

    if (prev == NULL)
        *head = current->next;
    else
        prev->next = current->next;

    free(current);
}

int getPacketCount(PacketNode* head) {
    int count = 0;
    PacketNode* temp = head;
    while (temp != NULL) {
        count++;
        temp = temp->next;
    }
    return count;
}

void sortPacketsByTimestamp(PacketNode** head) {
    if (*head == NULL || (*head)->next == NULL)
        return;

    int swapped;
    PacketNode* ptr1;
    PacketNode* lptr = NULL;

    do {
        swapped = 0;
        ptr1 = *head;

        while (ptr1->next != lptr) {
            if (ptr1->data.timestamp > ptr1->next->data.timestamp) {
                DataPacket temp = ptr1->data;
                ptr1->data = ptr1->next->data;
                ptr1->next->data = temp;
                swapped = 1;
            }
            ptr1 = ptr1->next;
        }

        lptr = ptr1;
    } while (swapped);
}

void removeOldPackets(PacketNode** head, time_t grace_period) {
    PacketNode* current = *head;
    PacketNode* prev = NULL;

    while (current != NULL) {
        if (difftime(time(NULL), current->data.timestamp) > grace_period) {
            if (prev == NULL)
                *head = current->next;
            else
                prev->next = current->next;

            free(current);
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }
}

// Additional functions for logging, configuration, compression,
// monitoring, concurrency handling, distributed cache integration,
// self-healing mechanism, rate-limiting, export functionality,
// and memory fragmentation optimization would be implemented here.

