    DataPacket packet1 = {1, time(NULL), 1024, "192.168.1.1", "192.168.1.2"};
    addPacket(&packetList, packet1);

    removeOldPackets(&packetList, 3600); // Remove packets older than 1 hour

    printf("Number of packets: %d\n", getPacketCount(packetList));

    return 0;
}
