    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, ",");
        int field_count = 0;
        double sum = 0;

        while (token) {
            if (field_count > 1 && field_count <= 3) {
                sum += atof(token);
            }
            token = strtok(NULL, ",");
            field_count++;
        }

        if (field_count > 1) {
            double average = sum / (field_count - 2);
            printf("%s%.2f\n", line, average);
        } else {
            printf("%s\n", line);
        }
    }

