#include <string.h>

typedef struct ResourceRequest {
    int request_id;
    char resource_type[50];
    time_t requested_time;
    char status[20];
    int current_priority;
} ResourceRequest;

// Function to add a new request to the list
void add_request(ResourceRequest **list, int *size, ResourceRequest req) {
    *list = realloc(*list, (*size + 1) * sizeof(ResourceRequest));
    if (*list == NULL) {
        perror("Memory allocation failed");
        exit(1);
    }
    (*list)[*size] = req;
    (*size)++;
}

// Function to update the status and priority of an existing request
void update_request(ResourceRequest *list, int size, int request_id, char *new_status, int new_priority) {
    for (int i = 0; i < size; i++) {
        if (list[i].request_id == request_id) {
            strcpy(list[i].status, new_status);
            list[i].current_priority = new_priority;
            break;
        }
    }
}

// Function to retrieve the total number of pending requests
int get_pending_requests(ResourceRequest *list, int size, char *pending_status) {
    int count = 0;
    for (int i = 0; i < size; i++) {
        if (strcmp(list[i].status, pending_status) == 0) {
            count++;
        }
    }
    return count;
}

// Function to sort the requests based on their requested_time in descending order
void sort_requests(ResourceRequest *list, int size) {
    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - i - 1; j++) {
            if (list[j].requested_time < list[j + 1].requested_time) {
                ResourceRequest temp = list[j];
                list[j] = list[j + 1];
                list[j + 1] = temp;
            }
        }
    }
}

int main() {
    ResourceRequest *requests = NULL;
    int size = 0;

    // Example usage
    ResourceRequest new_request = {1, "CPU", time(NULL), "Pending", 5};
    add_request(&requests, &size, new_request);

    update_request(requests, size, 1, "Processing", 3);

    printf("Pending requests: %d\n", get_pending_requests(requests, size, "Pending"));

    sort_requests(requests, size);

    free(requests);
    return 0;
}
```

