#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct DataPacket {
    int packet_id;
    long timestamp;
    size_t payload_size;
    char source_ip[16];
    char destination_ip[16];
} DataPacket;

typedef struct DynamicArray {
    DataPacket* packets;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->packets = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    free(array->packets);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_packet(DynamicArray* array, DataPacket packet) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity > 0 ? array->capacity * 2 : 1;
        DataPacket* new_packets = (DataPacket*)realloc(array->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
    array->packets[array->size++] = packet;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int remove_packet(DynamicArray* array, int packet_id) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->packets[i].packet_id == packet_id) {
            memmove(&array->packets[i], &array->packets[i + 1], (array->size - i - 1) * sizeof(DataPacket));
            array->size--;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // Packet not found
}

size_t get_packet_count(DynamicArray* array) {
    size_t count = 0;
    pthread_mutex_lock(&array->lock);
    count = array->size;
    pthread_mutex_unlock(&array->lock);
    return count;
}

void sort_packets_by_timestamp(DynamicArray* array) {
    qsort(array->packets, array->size, sizeof(DataPacket), [](const void* a, const void* b) {
        const DataPacket* pa = (const DataPacket*)a;
        const DataPacket* pb = (const DataPacket*)b;
        return (pa->timestamp < pb->timestamp) ? -1 : ((pa->timestamp > pb->timestamp) ? 1 : 0);
    });
}

int main() {
    DynamicArray* array = create_dynamic_array();
    if (!array) {
        fprintf(stderr, "Failed to create dynamic array\n");
        return EXIT_FAILURE;
    }

    DataPacket packet1 = {1, time(NULL), 1024, "192.168.1.1", "10.0.0.1"};
    add_packet(array, packet1);

    DataPacket packet2 = {2, time(NULL) + 3600, 2048, "192.168.1.2", "10.0.0.2"};
    add_packet(array, packet2);

    sort_packets_by_timestamp(array);

    size_t count = get_packet_count(array);
    printf("Number of packets: %zu\n", count);

    destroy_dynamic_array(array);
    return EXIT_SUCCESS;
}
```

