    int signalStrength;
    PduSessionUpdate* pduUpdates;
    int updateCount;
} UEConnectionStatus;

typedef struct UeList {
    UEConnectionStatus** connections;
    int count;
    int capacity;
} UeList;

UEConnectionStatus* createUeConnection(char* ueId, int signalStrength) {
    UEConnectionStatus* newUe = (UEConnectionStatus*)malloc(sizeof(UEConnectionStatus));
    strcpy(newUe->ueId, ueId);
    newUe->signalStrength = signalStrength;
    newUe->pduUpdates = NULL;
    newUe->updateCount = 0;
    return newUe;
}

void addOrUpdateUe(UeList* list, char* ueId, int signalStrength) {
    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->connections[i]->ueId, ueId) == 0) {
            free(list->connections[i]->pduUpdates);
            list->connections[i] = createUeConnection(ueId, signalStrength);
            return;
        }
    }
    if (list->count >= list->capacity) {
        list->capacity *= 2;
        list->connections = (UEConnectionStatus**)realloc(list->connections, list->capacity * sizeof(UEConnectionStatus*));
    }
    list->connections[list->count++] = createUeConnection(ueId, signalStrength);
}

