    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->connections[i]->ueId, ueId) == 0) {
            PduSessionUpdate* newUpdate = (PduSessionUpdate*)malloc(sizeof(PduSessionUpdate));
            strcpy(newUpdate->sessionId, sessionId);
            newUpdate->timeStamp = timeStamp;
            list->connections[i]->pduUpdates = realloc(list->connections[i]->pduUpdates, (list->connections[i]->updateCount + 1) * sizeof(PduSessionUpdate));
            list->connections[i]->pduUpdates[list->connections[i]->updateCount++] = *newUpdate;
            return;
        }
    }
}

PduSessionUpdate* getLatestPduUpdate(UeList* list, char* ueId) {
    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->connections[i]->ueId, ueId) == 0) {
            if (list->connections[i]->updateCount > 0) {
                return &list->connections[i]->pduUpdates[list->connections[i]->updateCount - 1];
            }
        }
    }
    return NULL;
}

void freeUeList(UeList* list) {
    for (int i = 0; i < list->count; i++) {
        free(list->connections[i]->pduUpdates);
        free(list->connections[i]);
    }
    free(list->connections);
    free(list);
}
