import java.util.*;
import java.util.concurrent.*;

public class DistributedDataProcessingPipeline {
    private final Set<String> whitelistedJIDs;
    private final Map<String, Job> jobMap;
    private final ExecutorService scheduler;
    private final MetadataService metadataService;
    private final HealthMonitor healthMonitor;

    public DistributedDataProcessingPipeline(Set<String> whitelistedJIDs) {
        this.whitelistedJIDs = whitelistedJIDs;
        this.jobMap = new HashMap<>();
        this.scheduler = Executors.newFixedThreadPool(1000);
        this.metadataService = new MockMetadataService();
        this.healthMonitor = new HealthMonitor();
    }

    public void submitJob(String jid, Job job) {
        if (whitelistedJIDs.contains(jid)) {
            jobMap.put(jid, job);
            scheduler.submit(() -> executeJob(jid));
        } else {
            System.out.println("Job ID not whitelisted: " + jid);
        }
    }

    private void executeJob(String jid) {
        Job job = jobMap.get(jid);
        if (job == null) return;

        try {
            if (metadataService.isNodeAvailable(job.getNode())) {
                // Execute job logic
                System.out.println("Executing job: " + jid);
                Thread.sleep(100); // Simulate job execution time
                metadataService.updateJobStatus(jid, Job.Status.SUCCESS);
            } else {
                healthMonitor.triggerAlert("Node not available for job: " + jid);
            }
        } catch (Exception e) {
            handleJobFailure(jid, e);
        }
    }

    private void handleJobFailure(String jid, Exception e) {
        System.out.println("Failed to execute job: " + jid + ", retrying...");
        scheduler.schedule(() -> executeJob(jid), 2 * (int)Math.pow(2, jobMap.size()), TimeUnit.SECONDS);
    }

    public void adjustQueueSize(int newSize) {
        ((ThreadPoolExecutor)scheduler).setCorePoolSize(newSize);
    }

    public void startHealthMonitoring() {
        new Thread(() -> {
            while (true) {
                healthMonitor.checkStatus();
                try {
                    Thread.sleep(60000); // Check every minute
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }).start();
    }

    public static void main(String[] args) {
        Set<String> whitelistedJIDs = new HashSet<>(Arrays.asList("JID1", "JID2", "JID3"));
        DistributedDataProcessingPipeline pipeline = new DistributedDataProcessingPipeline(whitelistedJIDs);
        pipeline.startHealthMonitoring();

        Job job1 = new Job("JID1", "NodeA");
        Job job2 = new Job("JID2", "NodeB");
        Job job3 = new Job("JID3", "NodeC");

        job1.addDependency(job2);
        job2.addDependency(job3);

        pipeline.submitJob("JID1", job1);
    }
}

class Job {
    enum Status { PENDING, RUNNING, SUCCESS, FAILURE };
    private String jid;
    private String node;
    private List<Job> dependencies = new ArrayList<>();
    private Status status;

    public Job(String jid, String node) {
        this.jid = jid;
        this.node = node;
        this.status = Status.PENDING;
    }

    public void addDependency(Job job) {
        dependencies.add(job);
    }

    public boolean hasDependencies() {
        return !dependencies.isEmpty();
    }

    public String getJid() {
        return jid;
    }

    public String getNode() {
        return node;
    }

    public Status getStatus() {
        return status;
    }

    public void setStatus(Status status) {
        this.status = status;
    }
}

interface MetadataService {
    boolean isNodeAvailable(String nodeId);
    void updateJobStatus(String jid, Job.Status status);
}

class MockMetadataService implements MetadataService {
    @Override
    public boolean isNodeAvailable(String nodeId) {
        return true; // Simulated always available for demonstration
    }

    @Override
    public void updateJobStatus(String jid, Job.Status status) {
        System.out.println("Updated job " + jid + " to " + status);
    }
}

class HealthMonitor {
    public void triggerAlert(String message) {
        System.out.println("Health alert: " + message);
    }

    public void checkStatus() {
        // Simulated health check
        System.out.println("Checking system health...");
    }
}
