import java.util.*;
import java.util.concurrent.*;

public class DistributedDataProcessingPipeline {

    private static final int MAX_CONCURRENT_JOBS = 1000;
    private static final long MIN_JOB_INTERVAL = 5 * 60 * 1000; // 5 minutes in milliseconds

    private Set<String> jobWhitelist = new HashSet<>();
    private Map<String, Job> jobs = new HashMap<>();
    private ExecutorService executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_JOBS);
    private MetadataService metadataService;
    private HealthMonitor healthMonitor;
    private CustomMetricsDashboard metricsDashboard;

    public DistributedDataProcessingPipeline(MetadataService metadataService, HealthMonitor healthMonitor) {
        this.metadataService = metadataService;
        this.healthMonitor = healthMonitor;
        this.metricsDashboard = new CustomMetricsDashboard();
    }

    public void addJob(Job job) {
        if (jobWhitelist.contains(job.getJID())) {
            jobs.put(job.getJID(), job);
            scheduleJob(job);
        } else {
            throw new IllegalArgumentException("Job ID not in whitelist");
        }
    }

    private void scheduleJob(Job job) {
        executorService.submit(() -> {
            long lastRun = System.currentTimeMillis() - MIN_JOB_INTERVAL;
            if (System.currentTimeMillis() - lastRun > MIN_JOB_INTERVAL || jobs.size() < MAX_CONCURRENT_JOBS) {
                try {
                    job.execute();
                    metricsDashboard.logSuccess(job);
                } catch (Exception e) {
                    handleJobFailure(job, e);
                }
            }
        });
    }

    private void handleJobFailure(Job job, Exception e) {
        int retries = 0;
        while (retries < job.getMaxRetries()) {
            try {
                Thread.sleep((long) Math.pow(2, retries) * 1000); // Exponential backoff
                job.execute();
                metricsDashboard.logSuccess(job);
                return;
            } catch (Exception ex) {
                retries++;
            }
        }
        metricsDashboard.logFailure(job);
    }

