#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct UserSession {
    int session_id;
    char user_name[256];
    time_t login_time;
    time_t last_activity_time;
    int is_active;
} UserSession;

typedef struct SessionNode {
    UserSession session;
    struct SessionNode *next;
} SessionNode;

typedef struct SessionList {
    SessionNode *head;
    size_t count;
    pthread_mutex_t lock;
} SessionList;

void init_session_list(SessionList *list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void add_session(SessionList *list, UserSession session) {
    pthread_mutex_lock(&list->lock);
    SessionNode *new_node = (SessionNode *)malloc(sizeof(SessionNode));
    new_node->session = session;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void remove_session_by_id(SessionList *list, int session_id) {
    pthread_mutex_lock(&list->lock);
    SessionNode *current = list->head;
    SessionNode *prev = NULL;

    while (current != NULL) {
        if (current->session.session_id == session_id) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->count--;
            break;
        }
        prev = current;
        current = current->next;
    }
