    time_t last_activity_time;
    struct UserSession* next;
} UserSession;

typedef struct {
    UserSession* head;
    int max_sessions_per_user;
} SessionManager;

UserSession* create_session(int session_id, const char* user_name) {
    UserSession* new_session = (UserSession*)malloc(sizeof(UserSession));
    new_session->session_id = session_id;
    strncpy(new_session->user_name, user_name, sizeof(new_session->user_name));
    time(&new_session->session_start_time);
    time(&new_session->last_activity_time);
    new_session->next = NULL;
    return new_session;
}

void initializeWorld(SessionManager* manager, int max_sessions_per_user) {
    manager->head = NULL;
    manager->max_sessions_per_user = max_sessions_per_user;
}

void add_session(SessionManager* manager, UserSession* session) {
    // Add the session to the linked list
    if (manager->head == NULL || manager->head->session_id > session->session_id) {
        session->next = manager->head;
        manager->head = session;
    } else {
        UserSession* current = manager->head;
        while (current->next != NULL && current->next->session_id < session->session_id) {
            current = current->next;
        }
        session->next = current->next;
        current->next = session;
    }
}

void remove_session(SessionManager* manager, int session_id) {
    // Remove the session from the linked list
    UserSession* current = manager->head;
    UserSession* prev = NULL;
    while (current != NULL && current->session_id != session_id) {
        prev = current;
        current = current->next;
    }
    if (current != NULL) {
        if (prev == NULL) {
            manager->head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
    }
}

int get_active_sessions(SessionManager* manager) {
    // Return the total number of active sessions
    int count = 0;
    UserSession* current = manager->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count;
}
