        this.maxConcurrentJobsPerNode = maxConcurrentJobsPerNode;
    }

    // Getters and setters
}

class HealthMonitor implements Runnable {
    private DistributedDataProcessingPipeline pipeline;

    public HealthMonitor(DistributedDataProcessingPipeline pipeline) {
        this.pipeline = pipeline;
    }

    @Override
    public void run() {
        while (true) {
            monitorServices();
            try {
                Thread.sleep(60 * 1000); // Check every minute
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }

    private void monitorServices() {
        List<String> failedNodes = new ArrayList<>();
        for (String node : pipeline.jobMap.keySet()) {
            if (!pipeline.metadataService.getResourceAvailability().isNodeAvailable(node)) {
                failedNodes.add(node);
            }
        }
        for (String node : failedNodes) {
            retryJobsForNode(node);
        }
    }

    private void retryJobsForNode(String node) {
        // Implement retry logic for jobs associated with the failed node
    }

    public void start() {
        new Thread(this).start();
    }
}
