// Define the DataPacket structure
class DataPacket {
    public $packet_id;
    public $timestamp;
    public $payload_size;

    public function __construct($packet_id, $timestamp, $payload_size) {
        $this->packet_id = $packet_id;
        $this->timestamp = $timestamp;
        $this->payload_size = $payload_size;
    }
}

// Define the DynamicDataProcessor class
class DataPacketManager {
    private $dataPackets;
    private $minValue;
    private $maxValue;

    public function __construct($minValue, $maxValue) {
        $this->dataPackets = [];
        $this->minValue = $minValue;
        $this->maxValue = $maxValue;
    }

    public function addPacket(DataPacket $packet) {
        $this->dataPackets[] = $packet;
    }

    public function removePacket($packet_id) {
        foreach ($this->dataPackets as $key => $packet) {
            if ($packet->packet_id == $packet_id) {
                unset($this->dataPackets[$key]);
                return true;
            }
        }
        return false;
    }

    public function getTotalPackets() {
        return count($this->dataPackets);
    }

    public function sortPacketsByTimestamp() {
        usort($this->dataPackets, function($a, $b) {
            return $a->timestamp - $b->timestamp;
        });
    }
}

// Define the EnvironmentConfigurator class
class EnvironmentConfigurator {
    private $dataPacketManager;

    public function __construct($minValue, $maxValue) {
        $this->dataPacketManager = new DataPacketManager($minValue, $maxValue);
    }

    public function addDataPacket($packet_id, $timestamp, $payload_size) {
        $this->dataPacketManager->addPacket(new DataPacket($packet_id, $timestamp, $payload_size));
    }

    public function removeDataPacket($packet_id) {
        return $this->dataPacketManager->removePacket($packet_id);
    }

    public function getTotalPackets() {
        return $this->dataPacketManager->getTotalPackets();
    }

    public function sortPacketsByTimestamp() {
        $this->dataPacketManager->sortPacketsByTimestamp();
    }
}

// Example usage
$envConfigurator = new EnvironmentConfigurator(1, 100);
$envConfigurator->addDataPacket(1, time(), 1024);
$envConfigurator->addDataPacket(2, time() + 60, 2048);
$envConfigurator->sortPacketsByTimestamp();
echo "Total packets: " . $envConfigurator->getTotalPackets();

