typedef struct {
    DataPacket* packets;
    size_t count;
    size_t capacity;
} PacketArray;

void init_packet_array(PacketArray* array) {
    array->packets = NULL;
    array->count = 0;
    array->capacity = 0;
}

void resize_packet_array(PacketArray* array, size_t new_capacity) {
    if (new_capacity > array->capacity) {
        DataPacket* new_packets = realloc(array->packets, new_capacity * sizeof(DataPacket));
        if (new_packets != NULL) {
            array->packets = new_packets;
            array->capacity = new_capacity;
        } else {
            // Handle memory allocation failure
        }
    }
}

void add_packet(PacketArray* array, DataPacket packet) {
    if (array->count >= array->capacity) {
        resize_packet_array(array, array->capacity * 2);
    }
    array->packets[array->count++] = packet;
}

void remove_packet_by_id(PacketArray* array, int packet_id) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->packets[i].packet_id == packet_id) {
            // Shift elements to fill the gap
            memmove(&array->packets[i], &array->packets[i + 1], (array->count - i - 1) * sizeof(DataPacket));
            array->count--;
            break;
        }
    }
}

DataPacket* get_packet_by_id(PacketArray* array, int packet_id) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->packets[i].packet_id == packet_id) {
