    NetworkSession* current = manager->head;
    NetworkSession* previous = NULL;

    while (current != NULL) {
        if (current->session_id == session_id) {
            if (previous == NULL) {
                manager->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

int get_active_sessions(SessionManager* manager, time_t duration_threshold) {
    int count = 0;
