#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SESSIONS 1000000

typedef struct {
    int session_id;
    char client_ip[20];
    time_t start_time;
    time_t duration;
} NetworkSession;

typedef struct {
    NetworkSession *sessions;
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

void init_session_manager(SessionManager *manager) {
    manager->sessions = (NetworkSession *)malloc(MAX_SESSIONS * sizeof(NetworkSession));
    if (!manager->sessions) {
        fprintf(stderr, "Failed to allocate memory for session manager\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_session(SessionManager *manager, NetworkSession session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_SESSIONS) {
        fprintf(stderr, "Maximum number of sessions reached\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    manager->sessions[manager->count++] = session;
    pthread_mutex_unlock(&manager->lock);
}

void remove_session_by_id(SessionManager *manager, int session_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].session_id == session_id) {
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->count - i - 1) * sizeof(NetworkSession));
            --manager->count;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

size_t get_active_session_count(SessionManager *manager) {
    size_t count;
    pthread_mutex_lock(&manager->lock);
    count = manager->count;
    pthread_mutex_unlock(&manager->lock);
    return count;
}

void filter_sessions_by_duration(SessionManager *manager, time_t duration_threshold) {
    NetworkSession *filtered_sessions = (NetworkSession *)malloc(MAX_SESSIONS * sizeof(NetworkSession));
    if (!filtered_sessions) {
        fprintf(stderr, "Failed to allocate memory for filtered sessions\n");
        exit(EXIT_FAILURE);
    }
    size_t filtered_count = 0;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (difftime(manager->sessions[i].start_time + manager->sessions[i].duration, time(NULL)) > duration_threshold) {
            filtered_sessions[filtered_count++] = manager->sessions[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    // TODO: Handle the filtered sessions
    free(filtered_sessions);
}

void save_sessions_to_disk(SessionManager *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    pthread_mutex_lock(&manager->lock);
    fwrite(manager->sessions, sizeof(NetworkSession), manager->count, file);
    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

void load_sessions_from_disk(SessionManager *manager, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }
    pthread_mutex_lock(&manager->lock);
    size_t count = fread(manager->sessions, sizeof(NetworkSession), MAX_SESSIONS, file);
    manager->count = count;
    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

void cleanup_session_manager(SessionManager *manager) {
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}
