#define MAX_LINE_LENGTH 1024

typedef struct {
    int session_id;
    time_t last_active_time;
    char user_agent[256];
    int session_duration;
    time_t session_start_time;
} UserSession;

UserSession** sessions = NULL;
int session_count = 0;

void add_session(int session_id, time_t last_active_time, const char* user_agent, int session_duration, time_t session_start_time) {
    sessions = realloc(sessions, (session_count + 1) * sizeof(UserSession*));
    sessions[session_count] = malloc(sizeof(UserSession));
    sessions[session_count]->session_id = session_id;
    sessions[session_count]->last_active_time = last_active_time;
    strcpy(sessions[session_count]->user_agent, user_agent);
    sessions[session_count]->session_duration = session_duration;
    sessions[session_count]->session_start_time = session_start_time;
    session_count++;
}

void remove_session(int session_id) {
    for (int i = 0; i < session_count; i++) {
        if (sessions[i]->session_id == session_id) {
            free(sessions[i]);
            for (int j = i; j < session_count - 1; j++) {
                sessions[j] = sessions[j + 1];
            }
            sessions = realloc(sessions, (session_count - 1) * sizeof(UserSession*));
            session_count--;
            return;
        }
    }
}

int get_active_sessions() {
    return session_count;
}

void process_text_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

