#include <iostream>
#include <forward_list>
#include <random>
#include <mutex>
#include <stdexcept>

class DynamicValueGenerator {
private:
    int minVal;
    int maxVal;
    std::mt19937 generator;
    static const size_t MAX_CAPACITY = 1000; // Predefined size limit for the forward list
    std::mutex mtx;

public:
    DynamicValueGenerator(int min, int max) : minVal(min), maxVal(max), generator(std::random_device{}()) {
        if (min > max) {
            throw std::invalid_argument("Invalid range: minimum value should be less than or equal to maximum.");
        }
    }

    float generateRandomFloat() {
        std::lock_guard<std::mutex> lock(mtx);
        std::uniform_real_distribution<float> distribution(minVal, maxVal);
        return distribution(generator);
    }

    int generateRandomInt() {
        std::lock_guard<std::mutex> lock(mtx);
        std::uniform_int_distribution<int> distribution(minVal, maxVal);
        return distribution(generator);
    }

    void insertAfterOrAppend(std::forward_list<int>& list, int key, int value) {
        std::lock_guard<std::mutex> lock(mtx);
        if (list.size() >= MAX_CAPACITY - 1) { // Check for potential overflow
            throw std::overflow_error("Cannot insert more elements: list is接近maximum capacity.");
        }
        auto it = list.begin();
        while (it != list.end()) {
            if (*it == key) {
                it = list.insert_after(it, value);
                return;
            }
            ++it;
        }
        list.push_back(value);
    }

    std::string ToString() const {
        std::lock_guard<std::mutex> lock(mtx);
        std::ostringstream oss;
        oss << "Range: [" << minVal << ", " << maxVal << "]";
        return oss.str();
    }
};
