#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the DataPacket structure
typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char *source_ip;
    char *destination_ip;
} DataPacket;

// Function to add a new packet to the DFS
void addPacket(DataPacket **packets, int *count, DataPacket new_packet) {
    (*count)++;
    DataPacket *new_packets = realloc(*packets, (*count) * sizeof(DataPacket));
    if (new_packets == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    (*packets) = new_packets;
    (*packets)[*count - 1] = new_packet;
}

// Function to remove a packet by packet_id
void removePacket(DataPacket **packets, int *count, int packet_id) {
    for (int i = 0; i < *count; i++) {
        if ((*packets)[i].packet_id == packet_id) {
            memmove(&(*packets)[i], &(*packets)[i + 1], (*count - i - 1) * sizeof(DataPacket));
            (*count)--;
            DataPacket *new_packets = realloc(*packets, (*count) * sizeof(DataPacket));
            if (new_packets == NULL) {
                perror("Failed to allocate memory");
                exit(EXIT_FAILURE);
            }
            (*packets) = new_packets;
            return;
        }
    }
}

// Function to get the total number of packets
int getTotalPackets(DataPacket *packets, int count) {
    return count;
}

// Function to sort packets by timestamp
void sortPacketsByTimestamp(DataPacket *packets, int count) {
    // Use a sorting algorithm like qsort
    qsort(packets, count, sizeof(DataPacket), compareTimestamps);
}

int compareTimestamps(const void *a, const void *b) {
    DataPacket *packet_a = (DataPacket *)a;
    DataPacket *packet_b = (DataPacket *)b;
    return (int)(packet_a->timestamp - packet_b->timestamp);
}

// Function to remove packets older than the grace period
void removeOldPackets(DataPacket **packets, int *count, time_t grace_period) {
    time_t current_time = time(NULL);
    for (int i = 0; i < *count; i++) {
        if ((*packets)[i].timestamp + grace_period < current_time) {
            memmove(&(*packets)[i], &(*packets)[i + 1], (*count - i - 1) * sizeof(DataPacket));
            (*count)--;
            DataPacket *new_packets = realloc(*packets, (*count) * sizeof(DataPacket));
            if (new_packets == NULL) {
                perror("Failed to allocate memory");
                exit(EXIT_FAILURE);
            }
            (*packets) = new_packets;
        } else {
            break; // No need to check further
        }
    }
}

// Function to export the packet storage state
void exportPacketStorage(DataPacket *packets, int count, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    for (int i = 0; i < count; i++) {
        fprintf(file, "%d %ld %zu %s %s\n", packets[i].packet_id, packets[i].timestamp, packets[i].payload_size, packets[i].source_ip, packets[i].destination_ip);
    }
    fclose(file);
}

// Function to compute MD5 hash of a large file
void computeMD5Hash(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }

    // Use an external library like OpenSSL to compute the MD5 hash
    unsigned char hash[16];
    MD5_CTX md5;
    MD5_Init(&md5);
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, BUFSIZ, file)) > 0) {
        MD5_Update(&md5, buffer, bytes_read);
    }
    MD5_Final(hash, &md5);

    fclose(file);

    // Convert the hash to a string and print it
    char md5_str[33];
    for (int i = 0; i < 16; i++) {
        snprintf(md5_str + (i * 2), 3, "%02x", hash[i]);
    }
    printf("MD5 hash: %s\n", md5_str);
}
