using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

public class HttpRequestProcessor
{
    private readonly HttpClient _httpClient;
    private readonly Dictionary<string, AuthenticationHeaderValue> _authenticationHeaders;
    private int _maxConcurrentConnections = 10;

    public HttpRequestProcessor(IEnumerable<string> endpoints, string defaultApiKey)
    {
        _httpClient = new HttpClient();
        _authenticationHeaders = endpoints.ToDictionary(
            endpoint => endpoint,
            endpoint => new AuthenticationHeaderValue("Bearer", defaultApiKey));
    }

    public async Task<RequestSummary> ProcessRequestsAsync(List<HttpRequestMessage> requests, int? defaultTimeout = null, RetryPolicy retryPolicy = null)
    {
        var summary = new RequestSummary();
        var tasks = requests.Select(request => ProcessRequestAsync(request, defaultTimeout ?? 15000, retryPolicy));
        var results = await Task.WhenAll(tasks);

        foreach (var result in results)
        {
            summary.Success += result.Success;
            summary.Failed += result.Failed;
            summary.Retried += result.Retried;
        }

        return summary;
    }

    private async Task<RequestResult> ProcessRequestAsync(HttpRequestMessage request, int timeout, RetryPolicy retryPolicy)
    {
        var result = new RequestResult();
        var attemptCount = 0;

        while (attemptCount < 3)
        {
            try
            {
                request.Headers.Authorization = _authenticationHeaders[request.RequestUri.ToString()];
                request.Timeout = TimeSpan.FromMilliseconds(timeout);

                using (var response = await _httpClient.SendAsync(request))
                {
                    if (response.IsSuccessStatusCode)
                    {
                        result.Success++;
                        break;
                    }
                    else
                    {
                        result.Failed++;
                    }
                }
            }
            catch (TaskCanceledException)
            {
                if (attemptCount == 0)
                {
                    attemptCount++; // Retry on timeout
                }
                else
                {
                    result.Failed++;
                    break;
                }
            }
            catch
            {
                result.Failed++;
                break;
            }

            await Task.Delay(100); // Small delay before retry
        }

        if (attemptCount > 1)
        {
            result.Retried = attemptCount - 1;
        }

        return result;
    }

    public void SetMaxConcurrentConnections(int maxConnections)
    {
        _maxConcurrentConnections = Math.Max(1, maxConnections);
    }
}

public class RequestSummary
{
    public int Success { get; set; }
    public int Failed { get; set; }
    public int Retried { get; set; }

    public void Log()
    {
        Console.WriteLine($"Success: {Success}, Failed: {Failed}, Retried: {Retried}");
    }
}

public class RequestResult
{
    public int Success { get; set; } = 0;
    public int Failed { get; set; } = 0;
    public int Retried { get; set; } = 0;
}

public enum RetryPolicy
{
    Default,
    Custom
}
