    size_t array_size;
    size_t element_size;
    unsigned int max_size;
    CRCFLAG_TYPE (*crc_flag_generator)();
} CrcIndicationPduManager;

void initialize_crc_indication_pdu_manager(CrcIndicationPduManager *manager, size_t initial_size, unsigned int max_size, CRCFLAG_TYPE (*crc_flag_gen)()) {
    manager->array_size = initial_size;
    manager->max_size = max_size;
    manager->element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    manager->pdu_array = malloc(manager->array_size * manager->element_size);

    if (manager->pdu_array == NULL) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    memset(manager->pdu_array, 0, manager->array_size * manager->element_size);
}

void expand_crc_indication_pdu_manager(CrcIndicationPduManager *manager) {
    if (manager->array_size >= manager->max_size) {
        // Handle max size exceeded
        fprintf(stderr, "Max array size exceeded\n");
        exit(EXIT_FAILURE);
    }

    size_t new_size = manager->array_size * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->pdu_array, new_size * manager->element_size);

    if (new_array == NULL) {
        // Handle memory allocation failure
