#include <Python.h>
#include <openssl/md5.h>

static PyObject* compute_md5_hash(PyObject* self, PyObject* args) {
    const char* file_path;
    if (!PyArg_ParseTuple(args, "s", &file_path)) {
        return NULL;
    }
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        PyErr_SetString(PyExc_FileNotFoundError, "File not found.");
        return NULL;
    }
    MD5_CTX md5_context;
    MD5_Init(&md5_context);
    char buffer[4096];
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        MD5_Update(&md5_context, buffer, bytes_read);
    }
    fclose(file);
    unsigned char hash_value[MD5_DIGEST_LENGTH];
    MD5_Final(hash_value, &md5_context);
    PyObject* result = PyBytes_FromStringAndSize((const char*)hash_value, MD5_DIGEST_LENGTH * 2);
    return result;
}

static PyMethodDef DfsMethods[] = {
    {"compute_md5_hash", compute_md5_hash, METH_VARARGS, "Compute the MD5 hash of a large DFS file"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef dfsmodule = {
    PyModuleDef_HEAD_INIT,
    "dfs",
    NULL,
    -1,
    DfsMethods
};

PyMODINIT_FUNC PyInit_dfs(void) {
    return PyModule_Create(&dfsmodule);
}
