using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Diagnostics;
using System.Linq;
using System.Threading.Tasks;

public class SqlBatchExecutor
{
    private readonly int _maxConcurrentConnections = 50;
    private readonly TimeSpan _defaultTimeout = TimeSpan.FromSeconds(60);
    private readonly int _retryLimit = 3;
    private readonly Dictionary<Type, Func<Exception, bool>> _customRetryPolicies;

    public SqlBatchExecutor(Dictionary<Type, Func<Exception, bool>> customRetryPolicies)
    {
        _customRetryPolicies = customRetryPolicies;
    }

    public async Task<BatchExecutionSummary> ExecuteAsync(List<string> sqlCommands, SqlConnection connection, bool useTransaction, CancellationToken cancellationToken = default)
    {
        var summary = new BatchExecutionSummary();
        using (var transaction = useTransaction ? await connection.BeginTransactionAsync(cancellationToken) : null)
        {
            try
            {
                var tasks = sqlCommands.Select((sql, index) => ExecuteCommandAsync(sql, connection, transaction, index, cancellationToken)).ToList();
                await Task.WhenAll(tasks);
                summary.SuccessCount = tasks.Count(task => task.Result.Success);
                summary.FailureCount = tasks.Count(task => task.Result.Failure);
                summary.RetryCount = tasks.Count(task => task.Result.Retry);
            }
            catch (Exception ex)
            {
                summary.AddFailure(ex);
            }
            finally
            {
                if (useTransaction && transaction != null)
                {
                    await transaction.CommitAsync(cancellationToken);
                }
            }
        }
        return summary;
    }

    private async Task<CommandExecutionResult> ExecuteCommandAsync(string sql, SqlConnection connection, SqlTransaction transaction, int index, CancellationToken cancellationToken)
    {
        var result = new CommandExecutionResult();
        int retryCount = 0;
        while (retryCount <= _retryLimit)
        {
            try
            {
                using (var command = new SqlCommand(sql, connection, transaction))
                {
                    command.CommandTimeout = GetCommandTimeout(index);
                    await command.ExecuteNonQueryAsync(cancellationToken);
                    result.Success = true;
                    break;
                }
            }
            catch (Exception ex)
            {
                if (IsRetryable(ex) && retryCount < _retryLimit)
                {
                    retryCount++;
                    await Task.Delay(100 * retryCount, cancellationToken); // Exponential backoff
                }
                else
                {
                    result.Failure = true;
                    if (ex is SqlException sqlEx && sqlEx.Number == -2) // Timeout exception
                    {
                        result.Retry = true;
                    }
                    break;
                }
            }
        }
        return result;
    }

    private bool IsRetryable(Exception ex)
    {
        var customPolicy = _customRetryPolicies.FirstOrDefault(p => p.Key.IsInstanceOfType(ex)).Value;
        if (customPolicy != null)
        {
            return customPolicy(ex);
        }
        return true; // Default retry policy
    }

    private int GetCommandTimeout(int index)
    {
        // Custom logic to determine command timeout based on index or other criteria
        return _defaultTimeout.TotalSeconds;
    }
}

public class BatchExecutionSummary
{
    public int SuccessCount { get; set; }
    public int FailureCount { get; set; }
    public int RetryCount { get; private set; }

    public void AddFailure(Exception ex)
    {
        // Log failure and increment failure count
        FailureCount++;
    }
}

public class CommandExecutionResult
{
    public bool Success { get; set; }
    public bool Failure { get; set; }
    public bool Retry { get; set; }
}
```

