// Function to initialize DFS
void init_DFS(DFS *dfs) {
    dfs->packets = NULL;
    dfs->size = 0;
    dfs->capacity = 0;
    pthread_mutex_init(&dfs->lock, NULL);
}

// Function to add a new packet to the DFS
int add_packet(DFS *dfs, DataPacket *packet) {
    pthread_mutex_lock(&dfs->lock);
    // Resize the array if necessary
    if (dfs->size == dfs->capacity) {
        size_t new_capacity = dfs->capacity ? dfs->capacity * 2 : 1;
        dfs->packets = realloc(dfs->packets, new_capacity * sizeof(DataPacket));
        dfs->capacity = new_capacity;
    }
    // Add the packet
    memcpy(&dfs->packets[dfs->size], packet, sizeof(DataPacket));
    dfs->size++;
    pthread_mutex_unlock(&dfs->lock);
    return 0; // Success
}

// Function to remove a packet by packet_id
int remove_packet(DFS *dfs, int packet_id) {
    pthread_mutex_lock(&dfs->lock);
    for (size_t i = 0; i < dfs->size; i++) {
        if (dfs->packets[i].packet_id == packet_id) {
            // Shift elements to fill the gap
            memmove(&dfs->packets[i], &dfs->packets[i + 1], (dfs->size - i - 1) * sizeof(DataPacket));
            dfs->size--;
            pthread_mutex_unlock(&dfs->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&dfs->lock);
    return -1; // Packet not found
}

