#define MAX_RECORDS 1024

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int count;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool *pool) {
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

Record* allocate_record(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= MAX_RECORDS) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is full
    }
    Record *record = &pool->records[pool->count++];
    pthread_mutex_unlock(&pool->lock);
    return record;
}

void free_memory_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    pool->count = 0;
    pthread_mutex_unlock(&pool->lock);
}

int populate_linked_list(LTE_PHY_RX_FRAME_INFO **head, int num_frames, MemoryPool *pool) {
    srand(time(NULL));
    for (int i = 0; i < num_frames; ++i) {
        LTE_PHY_RX_FRAME_INFO *frame = malloc(sizeof(*frame));
        if (!frame) {
            free_memory_pool(pool);
            return -1; // Memory allocation failed
        }

        frame->lte_dl_ccch_message = malloc(sizeof(LTE_DL_CCCH_MESSAGE));
        if (!frame->lte_dl_ccch_message) {
            free(frame);
            free_memory_pool(pool);
            return -2; // Memory allocation failed
        }

        frame->lte_rrc_ue_context = malloc(sizeof(LTE_RRC_UE_CONTEXT));
        if (!frame->lte_rrc_ue_context) {
            free(frame->lte_dl_ccch_message);
