        if (!record) {
            free(frame->lte_rrc_ue_context);
            free(frame->lte_dl_ccch_message);
            free(frame);
            return -4; // Memory pool overflow
        }
        record->key = rand() % 100;

        frame->next = *head;
        *head = frame;
    }
    return 0; // Success
}

