memory_pool* create_memory_pool(size_t size) {
    memory_pool* mp = (memory_pool*)malloc(sizeof(memory_pool));
    mp->pool = malloc(size);
    mp->size = size;
    mp->used = 0;
    return mp;
}

void destroy_memory_pool(memory_pool* mp) {
    free(mp->pool);
    free(mp);
}

void* allocate_from_pool(memory_pool* mp, size_t size) {
    if (mp->used + size > mp->size) {
        fprintf(stderr, "Memory pool overflow\n");
        return NULL;
    }
    void* ptr = (char*)mp->pool + mp->used;
    mp->used += size;
    return ptr;
}

