#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 1000
#define GRACE_PERIOD 3600 // in seconds

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char source_ip[16];
    char destination_ip[16];
} DataPacket;

typedef struct {
    DataPacket packets[MAX_PACKETS];
    int count;
} PacketManager;

void init_packet_manager(PacketManager *pm) {
    pm->count = 0;
}

int add_packet(PacketManager *pm, DataPacket packet) {
    if (pm->count >= MAX_PACKETS) return -1; // Full array
    for (int i = 0; i < pm->count; i++) {
        if (pm->packets[i].packet_id == packet.packet_id) return -2; // Duplicate ID
    }
    memcpy(&pm->packets[pm->count], &packet, sizeof(DataPacket));
    pm->count++;
    return 0;
}

int remove_packet(PacketManager *pm, int packet_id) {
    for (int i = 0; i < pm->count; i++) {
        if (pm->packets[i].packet_id == packet_id) {
            for (int j = i; j < pm->count - 1; j++) {
                pm->packets[j] = pm->packets[j + 1];
            }
            pm->count--;
            return 0;
        }
    }
    return -1; // Packet not found
}

void sort_packets(PacketManager *pm) {
    for (int i = 0; i < pm->count - 1; i++) {
        for (int j = i + 1; j < pm->count; j++) {
            if (pm->packets[i].timestamp > pm->packets[j].timestamp) {
                DataPacket temp = pm->packets[i];
                pm->packets[i] = pm->packets[j];
                pm->packets[j] = temp;
            }
        }
    }
}

int get_packet_count(PacketManager *pm) {
    return pm->count;
}

void check_and_remove_old_packets(PacketManager *pm) {
    time_t current_time = time(NULL);
    for (int i = 0; i < pm->count; i++) {
        if ((current_time - pm->packets[i].timestamp) > GRACE_PERIOD) {
            remove_packet(pm, pm->packets[i].packet_id);
            i--; // Adjust index after removal
        }
    }
}

void log_operation(const char *operation) {
    printf("Log: %s\n", operation); // Simplified logging for demonstration
}
