#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNECTIONS 1000
#define MAX_EVENTS 500
#define RETRY_COUNT 5

typedef struct {
    int id;
    size_t bytes_sent;
    size_t bytes_received;
    double packet_loss_rate;
    double latency_ms;
} TCP_CONNECTION_STATS;

typedef struct {
    time_t timestamp;
    char anomaly_type[100];
} connection_event;

typedef struct {
    pthread_mutex_t lock;
    TCP_CONNECTION_STATS *connections[MAX_CONNECTIONS];
    int connection_count;
    connection_event *events[MAX_EVENTS];
    int event_count;
    int max_events;
} network_stats_pool;

network_stats_pool *initialize_network_stats_pool(int max_events) {
    network_stats_pool *pool = malloc(sizeof(network_stats_pool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->connection_count = 0;
    pool->event_count = 0;
    pool->max_events = max_events;

    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        pool->connections[i] = NULL;
    }

    for (int i = 0; i < MAX_EVENTS; i++) {
        pool->events[i] = malloc(sizeof(connection_event));
        if (!pool->events[i]) {
            free_network_stats_pool(pool);
            return NULL;
        }
    }

    return pool;
}

void free_network_stats_pool(network_stats_pool *pool) {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (pool->connections[i]) free(pool->connections[i]);
    }
    for (int i = 0; i < MAX_EVENTS; i++) {
        free(pool->events[i]);
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int add_connection(network_stats_pool *pool, int id, size_t bytes_sent, size_t bytes_received, double packet_loss_rate, double latency_ms) {
    pthread_mutex_lock(&pool->lock);

    if (pool->connection_count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    pool->connections[pool->connection_count] = malloc(sizeof(TCP_CONNECTION_STATS));
    if (!pool->connections[pool->connection_count]) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    pool->connections[pool->connection_count]->id = id;
    pool->connections[pool->connection_count]->bytes_sent = bytes_sent;
    pool->connections[pool->connection_count]->bytes_received = bytes_received;
    pool->connections[pool->connection_count]->packet_loss_rate = packet_loss_rate;
    pool->connections[pool->connection_count]->latency_ms = latency_ms;

    pool->connection_count++;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int add_event(network_stats_pool *pool, time_t timestamp, char *anomaly_type) {
    pthread_mutex_lock(&pool->lock);

    if (pool->event_count >= MAX_EVENTS) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    pool->events[pool->event_count]->timestamp = timestamp;
    strncpy(pool->events[pool->event_count]->anomaly_type, anomaly_type, sizeof(connection_event.anomaly_type));

    pool->event_count++;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

double get_average_packet_loss_rate(network_stats_pool *pool) {
    double total = 0.0;
    int count = 0;

    pthread_mutex_lock(&pool->lock);

    for (int i = 0; i < pool->connection_count; i++) {
        total += pool->connections[i]->packet_loss_rate;
        count++;
    }

    pthread_mutex_unlock(&pool->lock);

    if (count == 0) return 0.0;

    return total / count;
}

int main() {
    network_stats_pool *pool = initialize_network_stats_pool(MAX_EVENTS);
    if (!pool) {
        fprintf(stderr, "Failed to initialize network stats pool\n");
        return EXIT_FAILURE;
    }

    // Add connections and events here

    double avg_packet_loss = get_average_packet_loss_rate(pool);
    printf("Average packet loss rate: %.2f\n", avg_packet_loss);

    free_network_stats_pool(pool);
    return EXIT_SUCCESS;
}
