NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_nfas(N, int *error_code) {
    if (N <= 0) {
        *error_code = -1; // Invalid input
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* nfa_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_array) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    RX_UE_INFORMATION_TAG unique_tag;
    uint16_t used_rntis[1000] = {0}; // Assuming a maximum of 1000 RNTIs
    int rnti_count = 0;

    for (int i = 0; i < N; i++) {
        if (rnti_count >= 1000) {
            *error_code = -3; // Too many unique RNTIs required
            free(nfa_array);
            return NULL;
        }

        while (used_rntis[rnti_count]) {
            rnti_count++;
        }
        used_rntis[rnti_count] = 1;

        nfa_array[i].RNTI = ++rnti_count;
        nfa_array[i].RX_UE_INFORMATION_TAG = unique_tag;
        nfa_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = CRCFLAG;
    }

    *error_code = 0; // Success
    return nfa_array;
}

int main() {
    int error_code;
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_and_initialize_nfas(10, &error_code);
    if (array) {
        printf("Memory allocation and initialization successful.\n");
        free(array);
    } else {
        switch (error_code) {
            case -1:
                printf("Invalid input parameter.\n");
                break;
            case -2:
                printf("Memory allocation failed.\n");
                break;
            case -3:
                printf("Too many unique RNTIs required.\n");
                break;
        }
    }

    return 0;
}
