#include <stdlib.h>
#include <stdio.h>

// Define the structures
typedef struct PDCP_PDU {
    int data;
} PDCP_PDU;

typedef struct RLC_PDU {
    char info[256];
} RLC_PDU;

typedef struct PHY_PDU {
    double frequency;
} PHY_PDU;

typedef struct MAC_PDU {
    PDCP_PDU *pdcppdu;
    RLC_PDU *rlcpdu;
    PHY_PDU *physdu;
    struct MAC_PDU *prev, *next;
} MAC_PDU;

// Function to initialize MAC_PDU structure
void init_mac_pdu(MAC_PDU *mac_pdu) {
    mac_pdu->pdcppdu = (PDCP_PDU *)malloc(sizeof(PDCP_PDU));
    if (!mac_pdu->pdcppdu) {
        fprintf(stderr, "Memory allocation failed for PDCP_PDU\n");
        return;
    }

    mac_pdu->rlcpdu = (RLC_PDU *)malloc(sizeof(RLC_PDU));
    if (!mac_pdu->rlcpdu) {
        free(mac_pdu->pdcppdu);
        fprintf(stderr, "Memory allocation failed for RLC_PDU\n");
        return;
    }

    mac_pdu->physdu = (PHY_PDU *)malloc(sizeof(PHY_PDU));
    if (!mac_pdu->physdu) {
        free(mac_pdu->rlcpdu);
        free(mac_pdu->pdcppdu);
        fprintf(stderr, "Memory allocation failed for PHY_PDU\n");
        return;
    }

    // Initialize the fields
    mac_pdu->pdcppdu->data = 0;
    snprintf(mac_pdu->rlcpdu->info, sizeof(mac_pdu->rlcpdu->info), "Initial Info");
    mac_pdu->physdu->frequency = 2.4e9;
}

// Function to allocate and initialize MAC_PDU structures
MAC_PDU *allocate_mac_pdus(int N) {
    if (N <= 0) return NULL;

    // Allocate memory for the array of MAC_PDU pointers
    MAC_PDU **mac_pdu_array = (MAC_PDU **)malloc(N * sizeof(MAC_PDU *));
    if (!mac_pdu_array) {
        fprintf(stderr, "Memory allocation failed for MAC_PDU array\n");
        return NULL;
    }

    // Allocate memory and initialize each MAC_PDU structure
    int i;
    for (i = 0; i < N; ++i) {
        mac_pdu_array[i] = (MAC_PDU *)malloc(sizeof(MAC_PDU));
        if (!mac_pdu_array[i]) {
            fprintf(stderr, "Memory allocation failed for MAC_PDU at index %d\n", i);

            // Free previously allocated resources
            while (--i >= 0) {
                free(mac_pdu_array[i]->physdu);
                free(mac_pdu_array[i]->rlcpdu);
                free(mac_pdu_array[i]->pdcppdu);
                free(mac_pdu_array[i]);
            }
            free(mac_pdu_array);

            return NULL;
        }

        // Initialize the structure
        init_mac_pdu(mac_pdu_array[i]);

        // Link the structures in a doubly linked list
        if (i > 0) {
            mac_pdu_array[i-1]->next = mac_pdu_array[i];
            mac_pdu_array[i]->prev = mac_pdu_array[i-1];
        }
    }

    return mac_pdu_array[0]; // Return the head of the linked list
}
