void add_session(SessionManager* manager, const char* session_id, time_t last_active_time, const char* user_agent, int session_duration, time_t session_start_time) {
    if (manager->count >= manager->capacity) {
        manager->capacity *= 2;
        manager->sessions = realloc(manager->sessions, manager->capacity * sizeof(UserSession*));
    }
    UserSession* new_session = malloc(sizeof(UserSession));
    strcpy(new_session->session_id, session_id);
    new_session->last_active_time = last_active_time;
    strcpy(new_session->user_agent, user_agent);
    new_session->session_duration = session_duration;
    new_session->session_start_time = session_start_time;
    manager->sessions[manager->count++] = new_session;
}

void remove_session(SessionManager* manager, const char* session_id) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i]->session_id, session_id) == 0) {
            free(manager->sessions[i]);
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->count - i - 1) * sizeof(UserSession*));
