#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NetworkSession {
    int session_id;
    char client_ip[16];
    time_t start_time;
    time_t duration;
} NetworkSession;

typedef struct DynamicArray {
    NetworkSession* sessions;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->sessions = (NetworkSession*)malloc(initial_capacity * sizeof(NetworkSession));
    if (!array->sessions) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);
    free(array->sessions);
    pthread_mutex_unlock(&array->lock);
    free(array);
}

int add_session(DynamicArray* array, NetworkSession session) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NetworkSession* new_sessions = realloc(array->sessions, new_capacity * sizeof(NetworkSession));
        if (!new_sessions) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->sessions = new_sessions;
        array->capacity = new_capacity;
    }
    array->sessions[array->size++] = session;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int remove_session(DynamicArray* array, int session_id) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->sessions[i].session_id == session_id) {
            memmove(&array->sessions[i], &array->sessions[i + 1], (array->size - i - 1) * sizeof(NetworkSession));
            --array->size;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // Session not found
}

size_t get_active_sessions(DynamicArray* array, time_t duration_threshold) {
    size_t count = 0;
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (difftime(time(NULL), array->sessions[i].start_time) > duration_threshold) {
            ++count;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return count;
}

NetworkSession* filter_sessions(DynamicArray* array, time_t duration_threshold, size_t* result_size) {
    *result_size = get_active_sessions(array, duration_threshold);
    NetworkSession* filtered_sessions = (NetworkSession*)malloc(*result_size * sizeof(NetworkSession));
    if (!filtered_sessions) return NULL;

    pthread_mutex_lock(&array->lock);
    size_t j = 0;
    for (size_t i = 0; i < array->size; ++i) {
        if (difftime(time(NULL), array->sessions[i].start_time) > duration_threshold) {
            filtered_sessions[j++] = array->sessions[i];
        }
    }
    pthread_mutex_unlock(&array->lock);

    return filtered_sessions;
}

void save_to_disk(DynamicArray* array, const char* filename) {
