#include <boost/log/trivial.hpp>
#include <boost/log/sources/severity_logger.hpp>
#include <boost/log/sources/logger.hpp>
#include <boost/log/utility/setup/file.hpp>
#include <boost/log/utility/setup/console.hpp>
#include <boost/log/expressions.hpp>

namespace logging = boost::log;
namespace src = boost::log::sources;
namespace expr = boost::log::expressions;

void init_logging() {
    // Initialize the logger
    src::severity_logger<logging::trivial::severity_level> lg;

    // Set up file logging with custom format and severity filter
    logging::add_file_log(
        keywords::file_name = "sample_%N.log",
        keywords::rotation_size = 1073741824, // 1GB
        keywords::time_based_rotation = expr::placeholders::_n % 10,
        keywords::format = "[%TimeStamp%] [%Severity%]: %Message%"
    );

    // Set up console logging with custom format and severity filter
    logging::add_console_log(
        std::cout,
        keywords::format = "[%TimeStamp%] [%Severity%]: %Message%"
    );

    // Set the minimum log level (e.g., debug)
    lg.set_filter(expr::severity >= logging::trivial::debug);
}

void log_message(logging::trivial::severity_level level, const std::string& message) {
    src::severity_logger<logging::trivial::severity_level> lg;
    BOOST_LOG_SEV(lg, level) << message;
}
