#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SESSIONS 10000000

typedef struct NetworkSession {
    int session_id;
    char client_ip[16];
    time_t start_time;
    time_t duration;
} NetworkSession;

typedef struct SessionManager {
    NetworkSession *sessions[MAX_SESSIONS];
    int count;
    pthread_mutex_t lock;
} SessionManager;

void init_session_manager(SessionManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_session(SessionManager *manager, NetworkSession *session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_SESSIONS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Max sessions reached
    }
    manager->sessions[manager->count++] = session;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_session_by_id(SessionManager *manager, int session_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]->session_id == session_id) {
            free(manager->sessions[i]);
            for (; i < manager->count - 1; ++i) {
                manager->sessions[i] = manager->sessions[i + 1];
            }
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

int get_active_sessions_count(SessionManager *manager) {
    pthread_mutex_lock(&manager->lock);
    int count = manager->count;
    pthread_mutex_unlock(&manager->lock);
    return count;
}

int filter_sessions_by_duration(SessionManager *manager, time_t duration_threshold) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; ++i) {
        if ((time(NULL) - manager->sessions[i]->start_time) > duration_threshold) {
            free(manager->sessions[i]);
            for (; i < manager->count - 1; ++i) {
                manager->sessions[i] = manager->sessions[i + 1];
            }
            manager->count--;
            --i;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void destroy_session_manager(SessionManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; ++i) {
        free(manager->sessions[i]);
    }
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
```

This code provides a basic implementation of the `SessionManager` data structure and functions to manage network sessions. It includes thread safety using mutexes, memory management for session allocation and deallocation, and concurrency control mechanisms. The implementation also handles error conditions gracefully and includes a mechanism for resource cleanup.']

