using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class AsyncHttpService : IAsyncHttpService
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, int> _retryCounters;
    private readonly ILogger _logger;

    public AsyncHttpService(HttpClient httpClient, ILogger logger)
    {
        _httpClient = httpClient;
        _retryCounters = new ConcurrentDictionary<string, int>();
        _logger = logger;
    }

    public async Task ProcessRequestsAsync(List<RequestInfo> requestInfos, RateLimitConfig rateLimitConfig, RetryPolicy retryPolicy)
    {
        var tasks = new List<Task>();

        foreach (var requestInfo in requestInfos)
        {
            var task = ProcessRequestAsync(requestInfo, rateLimitConfig, retryPolicy);
            tasks.Add(task);

            if (tasks.Count >= Environment.ProcessorCount) // Adjust concurrency based on system load
            {
                await Task.WhenAll(tasks);
                tasks.Clear();
            }
        }

        await Task.WhenAll(tasks); // Ensure all requests are processed
    }

    private async Task ProcessRequestAsync(RequestInfo requestInfo, RateLimitConfig rateLimitConfig, RetryPolicy retryPolicy)
    {
        var uri = new Uri(requestInfo.Url);
        var authHeader = new AuthenticationHeaderValue("Bearer", requestInfo.AuthToken);

        using (var requestMessage = new HttpRequestMessage(HttpMethod.Get, uri))
        {
            requestMessage.Headers.Authorization = authHeader;
            requestMessage.Timeout = TimeSpan.FromSeconds(requestInfo.RequestTimeoutSeconds);

            try
            {
                while (true)
                {
                    var response = await _httpClient.SendAsync(requestMessage);
                    if (response.IsSuccessStatusCode)
                    {
                        _logger.LogSuccess(uri, requestInfo.AuthToken, requestInfo.RequestTimeoutSeconds, retryPolicy.MaxRetries - _retryCounters.GetOrAdd(uri.ToString(), 0));
                        break;
                    }
                    else
                    {
                        var retryCount = _retryCounters.AddOrUpdate(uri.ToString(), 1, (k, v) => v + 1);
                        if (retryCount > retryPolicy.MaxRetries)
                        {
                            _logger.LogFailure(uri, requestInfo.AuthToken, requestInfo.RequestTimeoutSeconds, retryCount);
                            break;
                        }

                        await Task.Delay(retryPolicy.RetryDelayMilliseconds * (int)Math.Pow(2, retryCount - 1));
                    }
                }
            }
            catch (HttpRequestException ex)
            {
                _logger.LogException(uri, requestInfo.AuthToken, requestInfo.RequestTimeoutSeconds, ex);
            }
        }
    }
}

public interface IAsyncHttpService
{
    Task ProcessRequestsAsync(List<RequestInfo> requestInfos, RateLimitConfig rateLimitConfig, RetryPolicy retryPolicy);
}

public class RequestInfo
{
    public string Url { get; set; }
    public string AuthToken { get; set; }
    public int RequestTimeoutSeconds { get; set; }
}

public class RateLimitConfig
{
    public int MaxRequestsPerSecond { get; set; }
}

public class RetryPolicy
{
    public int MaxRetries { get; set; }
    public int RetryDelayMilliseconds { get; set; }
}

public interface ILogger
{
    void LogSuccess(Uri uri, string authToken, int requestTimeoutSeconds, int retryCount);
    void LogFailure(Uri uri, string authToken, int requestTimeoutSeconds, int retryCount);
    void LogException(Uri uri, string authToken, int requestTimeoutSeconds, Exception ex);
}
