#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum { active, inactive, errored } Status;

typedef struct DataPacket {
    int packet_id;
    long timestamp;
    int payload_size;
    Status status;
    struct DataPacket* next;
} DataPacket;

typedef struct DynamicArray {
    DataPacket* head;
    size_t count;
} DynamicArray;

void addPacket(DynamicArray* array, int id, long timestamp, int payload_size, Status status) {
    DataPacket* newPacket = (DataPacket*)malloc(sizeof(DataPacket));
    newPacket->packet_id = id;
    newPacket->timestamp = timestamp;
    newPacket->payload_size = payload_size;
    newPacket->status = status;
    newPacket->next = array->head;
    array->head = newPacket;
    array->count++;
}

void removePacket(DynamicArray* array, int id) {
    DataPacket** current = &(array->head);
    while (*current != NULL) {
        if ((*current)->packet_id == id) {
            DataPacket* temp = *current;
            *current = (*current)->next;
            free(temp);
            array->count--;
            break;
        }
        current = &((*current)->next);
    }
}

size_t getPacketCount(const DynamicArray* array) {
    return array->count;
}

void sortPacketsByTimestamp(DynamicArray* array) {
    // Implement sorting logic using a stable algorithm
    // ...
}

void updatePacketStatus(DynamicArray* array, int id, Status newStatus) {
    DataPacket* current = array->head;
    while (current != NULL) {
        if (current->packet_id == id) {
            current->status = newStatus;
            break;
        }
        current = current->next;
    }
}

void exportPacketsToFile(const DynamicArray* array, const char* filename, const char* format) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    if (strcmp(format, "csv") == 0) {
        fprintf(file, "packet_id,timestamp,payload_size,status\n");
        DataPacket* current = array->head;
        while (current != NULL) {
            fprintf(file, "%d,%ld,%d,", current->packet_id, current->timestamp, current->payload_size);
            switch(current->status) {
                case active: fprintf(file, "active"); break;
                case inactive: fprintf(file, "inactive"); break;
                case errored: fprintf(file, "errored"); break;
            }
            fprintf(file, "\n");
            current = current->next;
        }
    } else if (strcmp(format, "json") == 0) {
        fprintf(file, "[\n");
        DataPacket* current = array->head;
        while (current != NULL) {
            fprintf(file, "  {\n");
            fprintf(file, "    \"packet_id\": %d,\n", current->packet_id);
            fprintf(file, "    \"timestamp\": %ld,\n", current->timestamp);
            fprintf(file, "    \"payload_size\": %d,\n", current->payload_size);
            fprintf(file, "    \"status\": \"%s\"\n", current->status == active ? "active" : current->status == inactive ? "inactive" : "errored");
            if (current->next != NULL) {
                fprintf(file, "  },\n");
            } else {
                fprintf(file, "  }\n");
            }
            current = current->next;
        }
        fprintf(file, "]\n");
    }

    fclose(file);
}

void freeDynamicArray(DynamicArray* array) {
    DataPacket* current = array->head;
    while (current != NULL) {
        DataPacket* temp = current;
        current = current->next;
        free(temp);
    }
    array->head = NULL;
    array->count = 0;
}
