#define RX_UE_INFORMATION_TAG 0x12345678
#define RNTI 10

typedef struct {
    int tag;
    int rnti;
} RX_UE_INFORMATION;

typedef struct {
    RX_UE_INFORMATION rx_ue_information;
    int crc_flag;
} CRC_INDICATION_REL8;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8 REL8[CRC_INDICATION_REL8_TAG];
} NFAPI_CRC_INDICATION_PDU;

NFAPI_CRC_INDICATION_PDU* allocate_nfa_crc_pdu(int N) {
    NFAPI_CRC_INDICATION_PDU *pdu_array = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (pthread_mutex_lock(&mutex) != 0) {
        return NULL; // Mutex lock failed
    }

    pdu_array = (NFAPI_CRC_INDICATION_PDU *)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU));
    if (pdu_array == NULL) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < N; i++) {
        pdu_array[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu_array[i].RNTI = RNTI;
        for (int j = 0; j < CRC_INDICATION_REL8_TAG; j++) {
            pdu_array[i].REL8[j].crc_flag = rand() % 2; // Randomly set CRCFLAG
        }
    }

    pthread_mutex_unlock(&mutex);
    return pdu_array;
}

void free_nfa_crc_pdu(NFAPI_CRC_INDICATION_PDU *pdu_array, int N) {
    if (pthread_mutex_lock(&mutex) != 0) {
        return; // Mutex lock failed
    }

    free(pdu_array);

    pthread_mutex_unlock(&mutex);
}
