#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_ID 10000000
#define STATUS_ACTIVE "active"
#define STATUS_INACTIVE "inactive"
#define STATUS_ERRORED "errored"

typedef enum { CSV, JSON } Format;

typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char status[20];
    struct DataPacket *next;
} DataPacket;

typedef struct PacketManager {
    DataPacket *head;
    size_t count;
    pthread_mutex_t lock;
} PacketManager;

PacketManager* create_packet_manager() {
    PacketManager *manager = malloc(sizeof(PacketManager));
    manager->head = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void add_packet(PacketManager *manager, int packet_id, time_t timestamp, size_t payload_size, const char *status) {
    pthread_mutex_lock(&manager->lock);
    DataPacket *new_packet = malloc(sizeof(DataPacket));
    new_packet->packet_id = packet_id;
    new_packet->timestamp = timestamp;
    new_packet->payload_size = payload_size;
    strcpy(new_packet->status, status);
    new_packet->next = manager->head;
    manager->head = new_packet;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

void remove_packet(PacketManager *manager, int packet_id) {
    pthread_mutex_lock(&manager->lock);
    DataPacket *current = manager->head;
    DataPacket *previous = NULL;

    while (current != NULL) {
        if (current->packet_id == packet_id) {
            if (previous == NULL) {
                manager->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void update_status(PacketManager *manager, int packet_id, const char *new_status) {
    pthread_mutex_lock(&manager->lock);
    DataPacket *current = manager->head;

    while (current != NULL) {
        if (current->packet_id == packet_id) {
            strcpy(current->status, new_status);
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

size_t get_packet_count(PacketManager *manager) {
    size_t count;
    pthread_mutex_lock(&manager->lock);
    count = manager->count;
    pthread_mutex_unlock(&manager->lock);
    return count;
}

void sort_packets_by_timestamp(PacketManager *manager) {
    // Implement sorting logic here
}

void export_packets(PacketManager *manager, Format format, const char *filename) {
    // Implement export logic here
}

void destroy_packet_manager(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    DataPacket *current = manager->head;
    while (current != NULL) {
        DataPacket *temp = current;
        current = current->next;
        free(temp);
    }
    manager->head = NULL;
    manager->count = 0;
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
