using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json;

public class ConfigModifier
{
    private const string ConfigFile = "config.txt";
    private const string JsonDataFile = "data.json";
    private const string LogFile = "log.txt";

    public void ModifyConfig()
    {
        try
        {
            var jsonData = File.ReadAllText(JsonDataFile);
            var data = JsonConvert.DeserializeObject<Dictionary<string, string>>(jsonData);

            var newConfigFileName = $"{DateTime.Now:yyyyMMddHHmmss}_config.txt";
            File.Copy(ConfigFile, newConfigFileName, true);

            using (var reader = new StreamReader(newConfigFileName))
            using (var writer = new StreamWriter($"{newConfigFileName}.tmp"))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    foreach (var pair in data)
                    {
                        if (line.Contains(pair.Key))
                        {
                            line = line.Replace(pair.Key, pair.Value);
                        }
                    }
                    writer.WriteLine(line);
                }
            }

            File.Move($"{newConfigFileName}.tmp", newConfigFileName);
            LogOperation($"Configuration updated and saved as {newConfigFileName}");
        }
        catch (Exception ex)
        {
            HandleError(ex);
        }
    }

    private void HandleError(Exception ex)
    {
        LogOperation($"Error: {ex.Message}", isError: true);
        Console.WriteLine($"An error occurred: {ex.Message}");
    }

    private void LogOperation(string message, bool isError = false)
    {
        var logEntry = $"{DateTime.Now:yyyy-MM-dd HH:mm:ss} - {message}";
        File.AppendAllText(LogFile, logEntry + Environment.NewLine);

        if (isError)
        {
            File.AppendAllText("error_log.txt", logEntry + Environment.NewLine);
        }
    }

    public string GetPokemonWeaknesses(string pokemonType)
    {
        var typeWeaknesses = new Dictionary<string, List<string>>
        {
            { "Fire", new List<string> { "Water", "Ground", "Rock" } },
            { "Water", new List<string> { "Fire", "Electric", "Grass" } }
            // Add more types and their weaknesses as needed
        };

        if (!typeWeaknesses.ContainsKey(pokemonType))
        {
            LogOperation($"Unknown or inconsistent Pokemon type: {pokemonType}", isError: true);
            throw new ArgumentException("Invalid Pokemon type");
        }

        return $"Weaknesses for {pokemonType}: {string.Join(", ", typeWeaknesses[pokemonType])}";
    }
}

public class Program
{
    public static void Main()
    {
        var configModifier = new ConfigModifier();
        configModifier.ModifyConfig();

        // Example usage of GetPokemonWeaknesses
        try
        {
            string weaknesses = configModifier.GetPokemonWeaknesses("Fire");
            Console.WriteLine(weaknesses);
        }
        catch (ArgumentException ex)
        {
            Console.WriteLine(ex.Message);
        }
    }
}
