NFAPI_CRC_INDICATION_PDU_T* create_list(int N) {
    if (N <= 0) return NULL;

    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* head = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!head) {
        fprintf(stderr, "Memory allocation failed for head node.\n");
        return NULL;
    }

    head->RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
    head->RNTI = rand() % 256; // Example initialization
    head->CRCFLAG = rand() % 2; // Randomly set CRCFLAG for the first node
    head->next = NULL;

    NFAPI_CRC_INDICATION_PDU_T* current = head;
    int last_crcflag = head->CRCFLAG;
    for (int i = 1; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed for node %d.\n", i);
            // Clean up allocated nodes
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        new_node->RX_UE_INFORMATION_TAG = rand() % 1000; // Example initialization
        new_node->RNTI = rand() % 256; // Example initialization

        do {
            new_node->CRCFLAG = rand() % 2;
        } while (new_node->CRCFLAG == last_crcflag);

        current->next = new_node;
        current = new_node;
        last_crcflag = new_node->CRCFLAG;
    }

    return head;
}

void update_crcflags(NFAPI_CRC_INDICATION_PDU_T* head) {
    if (!head) return;

    NFAPI_CRC_INDICATION_PDU_T* current = head;
    int sum_rnti = 0;

    while (current != NULL) {
        current->CRCFLAG = (current->RNTI + sum_rnti) % 2; // Update CRCFLAG based on sum of RNTI
        sum_rnti += current->RNTI;
        current = current->next;
    }
}

void print_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;

    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               current->RX_UE_INFORMATION_TAG, current->RNTI, current->CRCFLAG);
        current = current->next;
    }
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;

    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    int N = 10; // Number of nodes in the list
    NFAPI_CRC_INDICATION_PDU_T* list = create_list(N);
    if (list) {
        update_crcflags(list);
        print_list(list);
        free_list(list);
    }

    return 0;
}
