pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_doubly_linked_list(int N) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;
    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            perror("Memory allocation failed");
            return head;
        }
        pthread_mutex_lock(&list_mutex);
        new_node->rx_ue_info_tag = generate_rx_ue_information_tag(); // Assume function defined elsewhere
        new_node->rnti = i; // Example RNTI assignment for demonstration
        new_node->crc_indication_rel8_tag.CRCFLAG = (rand() % 2) ? 0 : 1; // Randomly set CRCFLAG

        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
        pthread_mutex_unlock(&list_mutex);
    }
    return head;
}

void update_crc_flags(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    int sum_rnti = 0;

    while (current != NULL) {
        pthread_mutex_lock(&list_mutex);
        current->crc_indication_rel8_tag.CRCFLAG = (sum_rnti % 2) ? 0 : 1; // Update based on sum of RNTI
        sum_rnti += current->rnti;
        pthread_mutex_unlock(&list_mutex);
        current = current->next;
    }
}

void serialize_list(NFAPI_CRC_INDICATION_PDU_T *head, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
