    while (current != NULL) {
        fwrite(&current->rx_ue_info_tag, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        fwrite(&current->rnti, sizeof(RNTI), 1, file);
        fwrite(&current->crc_indication_rel8_tag.CRCFLAG, sizeof(uint8_t), 1, file);
        current = current->next;
    }

    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_list(const char *filename) {
    FILE *file = fopen(filename, "rb");
