#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define N 10 // Number of nodes to create

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* create_node(RX_UE_INFORMATION_TAG ue_info, RNTI rnti) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        return NULL; // Handle memory allocation failure
    }
    memset(node, 0, sizeof(Node));
    // Populate the data structure with valid values
    node->data.ue_info = ue_info;
    node->data.rnti = rnti;
    node->crc_flag = rand() % 2; // Randomly set CRCFLAG
    return node;
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

Node* insert_node(Node* head, RX_UE_INFORMATION_TAG ue_info, RNTI rnti) {
    Node* new_node = create_node(ue_info, rnti);
    if (!new_node) {
        return head; // Handle memory allocation failure
    }
    if (head == NULL) {
        head = new_node;
    } else {
        Node* last = head;
        while (last->next != NULL) {
            last = last->next;
        }
        last->next = new_node;
        new_node->prev = last;
    }
    return head;
}

void update_crc_flags(Node* head) {
    if (head == NULL) {
        return;
    }
    Node* current = head;
    RNTI sum_rnti = 0;
    while (current != NULL) {
        current->data.crc_indication_rel8_tag.CRCFLAG = (sum_rnti % 2); // Update CRCFLAG based on sum of previous RNTI
        sum_rnti += current->data.rnti;
        current = current->next;
    }
}

void* thread_function(void* arg) {
    Node** head = (Node**)arg;
    for (int i = 0; i < N; i++) {
        *head = insert_node(*head, generate_ue_info(), generate_rnti());
        pthread_yield(); // Yield to other threads
    }
    return NULL;
}

void serialize_list(Node* head, FILE* file) {
    if (!file) {
        return;
    }
    Node* current = head;
    while (current != NULL) {
        // Serialize each node's data and CRCFLAG
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        fwrite(&current->crc_flag, sizeof(int), 1, file);
        current = current->next;
    }
}

Node* deserialize_list(FILE* file) {
    if (!file) {
        return NULL;
    }
    Node* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T data;
    int crc_flag;
    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1 && fread(&crc_flag, sizeof(int), 1, file) == 1) {
        head = insert_node(head, data.ue_info, data.rnti);
        if (!head) {
            free_list(head);
            return NULL; // Handle memory allocation failure
        }
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->crc_flag = crc_flag; // Set the CRCFLAG read from file
    }
    return head;
}

void log_operation(char* operation, double duration) {
    FILE* log_file = fopen("operation_log.txt", "a");
    if (!log_file) {
        return;
    }
    fprintf(log_file, "%s took %.2f seconds\n", operation, duration);
    fclose(log_file);
}

int main() {
    srand(time(NULL));
    Node* head = NULL;

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, thread_function, &head);
    pthread_join(thread_id, NULL);

    update_crc_flags(head);

    FILE* file = fopen("list_data.bin", "wb");
    if (file) {
        serialize_list(head, file);
        fclose(file);
    }

    free_list(head);

    return 0;
}
