#include <iostream>
#include <unordered_map>
#include <vector>
#include <string>
#include <fstream>
#include <json/json.h> // Include JSON library

class Transaction {
public:
    int transaction_id;
    double amount;
    std::string currency;
    std::time_t timestamp;
    std::string status;

    Transaction(int id, double amt, std::string curr, std::time_t ts, std::string stat)
        : transaction_id(id), amount(amt), currency(curr), timestamp(ts), status(stat) {}
};

class TransactionManager {
private:
    std::unordered_map<int, Transaction*> transactions;
    size_t capacity;

public:
    TransactionManager(size_t initial_capacity = 1000) : capacity(initial_capacity) {}

    ~TransactionManager() {
        for (auto& pair : transactions) {
            delete pair.second;
        }
    }

    bool addTransaction(Transaction* transaction) {
        if (transactions.size() >= capacity) {
            return false; // Handle capacity limit
        }
        transactions[transaction->transaction_id] = transaction;
        return true;
    }

    bool removeTransaction(int id) {
        auto it = transactions.find(id);
        if (it == transactions.end()) {
            return false; // Transaction not found
        }
        delete it->second;
        transactions.erase(it);
        return true;
    }

    void updateStatus(int id, std::string status) {
        auto it = transactions.find(id);
        if (it != transactions.end()) {
            it->second->status = status;
        }
    }

    size_t getTotalTransactions() const {
        return transactions.size();
    }

    // Filter by timestamp range and currency
    std::vector<Transaction*> filterTransactions(std::time_t start, std::time_t end, std::string currency) {
        std::vector<Transaction*> filtered;
        for (auto& pair : transactions) {
            if (pair.second->currency == currency && pair.second->timestamp >= start && pair.second->timestamp <= end) {
                filtered.push_back(pair.second);
            }
        }
        return filtered;
    }

    // Export to JSON
    void exportToJSON(const std::string& filename) const {
        Json::Value root;
        for (auto& pair : transactions) {
            Json::Value transactionJson;
            transactionJson["id"] = pair.second->transaction_id;
            transactionJson["amount"] = pair.second->amount;
            transactionJson["currency"] = pair.second->currency;
            transactionJson["timestamp"] = static_cast<int>(pair.second->timestamp);
            transactionJson["status"] = pair.second->status;
            root.append(transactionJson);
        }

        std::ofstream file(filename);
        if (file.is_open()) {
            file << root.toStyledString();
            file.close();
        } else {
            std::cerr << "Unable to open file for export." << std::endl;
        }
    }
};
