#define INITIAL_CAPACITY 10

typedef struct {
    int entry_id;
    int user_id;
    char log_timestamp[20];
    char event_type[50];
} LogEntry;

typedef struct {
    LogEntry *entries;
    size_t count;
    size_t capacity;
} LogArray;

LogArray* create_log_array() {
    LogArray *array = (LogArray *)malloc(sizeof(LogArray));
    array->entries = (LogEntry *)malloc(INITIAL_CAPACITY * sizeof(LogEntry));
    array->count = 0;
    array->capacity = INITIAL_CAPACITY;
    return array;
}

void add_log_entry(LogArray *array, int entry_id, int user_id, const char *log_timestamp, const char *event_type) {
    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->entries = (LogEntry *)realloc(array->entries, array->capacity * sizeof(LogEntry));
    }
    LogEntry new_entry = {entry_id, user_id, strcpy((char *)malloc(strlen(log_timestamp) + 1), log_timestamp), strcpy((char *)malloc(strlen(event_type) + 1), event_type)};
    array->entries[array->count++] = new_entry;
}

void remove_log_entry(LogArray *array, int entry_id) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->entries[i].entry_id == entry_id) {
            free(array->entries[i].log_timestamp);
            free(array->entries[i].event_type);
            for (size_t j = i; j < array->count - 1; ++j) {
                array->entries[j] = array->entries[j + 1];
            }
            --array->count;
            break;
        }
    }
}

int get_log_count(LogArray *array) {
    return array->count;
}

LogEntry* filter_logs(LogArray *array, int user_id, const char *event_type) {
    LogEntry *filtered_entries = (LogEntry *)malloc(array->count * sizeof(LogEntry));
    size_t filtered_count = 0;

    for (size_t i = 0; i < array->count; ++i) {
        if (array->entries[i].user_id == user_id && strcmp(array->entries[i].event_type, event_type) == 0) {
            filtered_entries[filtered_count++] = array->entries[i];
        }
    }

    filtered_entries = realloc(filtered_entries, filtered_count * sizeof(LogEntry));
    return filtered_entries;
}

void free_log_array(LogArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->entries[i].log_timestamp);
        free(array->entries[i].event_type);
    }
    free(array->entries);
    free(array);
}
