#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 10000000

typedef struct {
    int entry_id;
    int user_id;
    char event_type[50];
    char message[256];
} LogEntry;

typedef struct {
    LogEntry entries[MAX_ENTRIES];
    int count;
    pthread_mutex_t lock;
} LogSystem;

void init_log_system(LogSystem *sys) {
    sys->count = 0;
    pthread_mutex_init(&sys->lock, NULL);
}

void add_log_entry(LogSystem *sys, LogEntry entry) {
    pthread_mutex_lock(&sys->lock);
    if (sys->count < MAX_ENTRIES) {
        sys->entries[sys->count++] = entry;
    }
    pthread_mutex_unlock(&sys->lock);
}

int remove_log_entry(LogSystem *sys, int entry_id) {
    pthread_mutex_lock(&sys->lock);
    for (int i = 0; i < sys->count; i++) {
        if (sys->entries[i].entry_id == entry_id) {
            for (int j = i; j < sys->count - 1; j++) {
                sys->entries[j] = sys->entries[j + 1];
            }
            sys->count--;
            pthread_mutex_unlock(&sys->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&sys->lock);
    return -1;
}

int get_log_count(LogSystem *sys) {
    pthread_mutex_lock(&sys->lock);
    int count = sys->count;
    pthread_mutex_unlock(&sys->lock);
    return count;
}

LogEntry* filter_logs(LogSystem *sys, int user_id, const char* event_type) {
    static LogEntry filtered[MAX_ENTRIES];
    int filtered_count = 0;

    pthread_mutex_lock(&sys->lock);
    for (int i = 0; i < sys->count; i++) {
        if (sys->entries[i].user_id == user_id && strcmp(sys->entries[i].event_type, event_type) == 0) {
            filtered[filtered_count++] = sys->entries[i];
        }
    }
    pthread_mutex_unlock(&sys->lock);

    static int index = 0;
    if (index >= filtered_count) {
        index = 0;
    }
    return &filtered[index++];
}
```

This code snippet provides a basic implementation of a C-based logging system. The `LogSystem` structure manages an array of log entries with a mutex for thread safety. Functions are provided to initialize the system, add entries, remove entries by ID, get the total count of entries, and filter logs based on user ID and event type. Note that this example does not include error handling or advanced optimizations that would be necessary for a high-traffic system, such as asynchronous processing, external analytics integration, or persistent storage.']

