#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int task_id;
    int priority_level;
    char due_date[20];
    char status[20];
    char description[100];
} Task;

typedef struct Node {
    Task data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} TaskList;

void initTaskList(TaskList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addTask(TaskList* list, int task_id, int priority_level, const char* due_date, const char* status, const char* description) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data.task_id = task_id;
    newNode->data.priority_level = priority_level;
    strcpy(newNode->data.due_date, due_date);
    strcpy(newNode->data.status, status);
    strcpy(newNode->data.description, description);
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void markTaskCompleted(TaskList* list, int task_id) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.task_id == task_id) {
            strcpy(current->data.status, "completed");
            break;
        }
        current = current->next;
    }
}

int getIncompleteTasksCount(TaskList* list) {
    int count = 0;
    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(current->data.status, "incomplete") == 0) {
            count++;
        }
        current = current->next;
    }
    return count;
}

Node* filterTasks(TaskList* list, int priority_level, const char* status) {
    Node* resultHead = NULL;
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.priority_level == priority_level && strcmp(current->data.status, status) == 0) {
            Node* newNode = (Node*)malloc(sizeof(Node));
            newNode->data = current->data;
            newNode->next = resultHead;
            resultHead = newNode;
        }
        current = current->next;
    }
    return resultHead;
}

void freeTaskList(TaskList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    TaskList taskList;
    initTaskList(&taskList);

    addTask(&taskList, 1, 1, "2023-10-01", "incomplete", "Write code");
    addTask(&taskList, 2, 2, "2023-10-15", "incomplete", "Review code");

    markTaskCompleted(&taskList, 1);

    int incompleteCount = getIncompleteTasksCount(&taskList);
    printf("Number of incomplete tasks: %d\n", incompleteCount);

    Node* filteredTasks = filterTasks(&taskList, 2, "incomplete");
    while (filteredTasks != NULL) {
        printf("Task ID: %d, Priority: %d, Status: %s\n",
               filteredTasks->data.task_id,
               filteredTasks->data.priority_level,
               filteredTasks->data.status);
        Node* temp = filteredTasks;
        filteredTasks = filteredTasks->next;
        free(temp);
    }

    freeTaskList(&taskList);

    return 0;
}
