DataPacket* create_packet(int id, time_t ts, int size, const char* status) {
    DataPacket* new_packet = (DataPacket*)malloc(sizeof(DataPacket));
    if (!new_packet) return NULL;
    new_packet->packet_id = id;
    new_packet->timestamp = ts;
    new_packet->payload_size = size;
    strcpy(new_packet->status, status);
    new_packet->next = NULL;
    return new_packet;
}

void add_packet(DataPacket** head, int id, time_t ts, int size, const char* status) {
    DataPacket* new_packet = create_packet(id, ts, size, status);
    if (!new_packet) return;
    new_packet->next = *head;
    *head = new_packet;
}

int remove_packet(DataPacket** head, int id) {
    DataPacket* current = *head;
    DataPacket* prev = NULL;

    while (current != NULL && current->packet_id != id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) return 0; // Packet not found

    if (prev == NULL) {
        *head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    return 1;
}

