// Function to add a new DataPacket to the linked list
void addDataPacket(Node** head, int id) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data.id = id;
    newNode->data.timestamp = time(NULL);
    strcpy(newNode->data.status, "Pending");
    newNode->next = *head;
    *head = newNode;
}

// Function to update an existing DataPacket in the linked list
void updateDataPacket(Node** head, int id, char* newStatus) {
    Node* current = *head;
    while (current != NULL) {
        if (current->data.id == id) {
            strcpy(current->data.status, newStatus);
            return;
        }
        current = current->next;
    }
}

// Function to remove a DataPacket from the linked list
void removeDataPacket(Node** head, int id) {
    Node* current = *head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.id == id) {
            if (prev == NULL)
                *head = current->next;
            else
                prev->next = current->next;
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

// Function to sort the linked list of DataPacket by timestamp in ascending order
void sortDataPackets(Node** head) {
    // Sorting algorithm (e.g., Bubble Sort)
    Node* current;
    Node* index;
    DataPacket temp;

    if (*head == NULL) return;
    do {
        current = *head;
        while (current->next != NULL) {
            if (current->data.timestamp > current->next->data.timestamp) {
                temp = current->data;
                current->data = current->next->data;
                current->next->data = temp;
            }
            current = current->next;
        }
        index = *head;
    } while (index->next != NULL);
}

