#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct DataPacket {
    int packet_id;
    long timestamp;
    size_t payload_size;
} DataPacket;

typedef struct PacketNode {
    DataPacket *packet;
    struct PacketNode *next;
} PacketNode;

typedef struct PacketManager {
    PacketNode *head;
    pthread_mutex_t lock;
} PacketManager;

void initialize_manager(PacketManager *manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_packet(PacketManager *manager, DataPacket *packet) {
    pthread_mutex_lock(&manager->lock);
    PacketNode *new_node = (PacketNode *)malloc(sizeof(PacketNode));
    new_node->packet = packet;
    new_node->next = manager->head;
    manager->head = new_node;
    pthread_mutex_unlock(&manager->lock);
}

void remove_packet(PacketManager *manager, int packet_id) {
    pthread_mutex_lock(&manager->lock);
    PacketNode *current = manager->head;
    PacketNode *previous = NULL;

    while (current != NULL) {
        if (current->packet->packet_id == packet_id) {
            if (previous == NULL) {
                manager->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

int get_packet_count(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    int count = 0;
    PacketNode *current = manager->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return count;
}

void sort_packets(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    // Implement a sorting algorithm here, e.g., quicksort or mergesort
    // This example uses a simple bubble sort for demonstration purposes
    PacketNode *current = manager->head;
    while (current != NULL) {
        PacketNode *next = current->next;
        while (next != NULL) {
            if (current->packet->timestamp > next->packet->timestamp) {
                DataPacket *temp = current->packet;
                current->packet = next->packet;
                next->packet = temp;
            }
            next = next->next;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void free_manager(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    PacketNode *current = manager->head;
    while (current != NULL) {
        PacketNode *temp = current;
        current = current->next;
        free(temp->packet); // Assuming memory for DataPacket is allocated separately
        free(temp);
    }
    manager->head = NULL;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
