#include <stdatomic.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    atomic_int ref_count;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list(size_t initial_capacity) {
    NFAPI_CRC_LIST_T* list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    atomic_init(&list->ref_count, 1);
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T* list) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);
    atomic_fetch_sub(&list->ref_count, 1);
    if (atomic_load(&list->ref_count) > 0) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    pthread_mutex_unlock(&list->mutex);

    free(list->data);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void add_crc_to_list(NFAPI_CRC_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || list->size >= list->capacity) {
        // Handle error or resize the list
        return;
    }

    pthread_mutex_lock(&list->mutex);
    list->data[list->size++] = pdu;
    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_crc_from_list(NFAPI_CRC_LIST_T* list, size_t index) {
    if (!list || index >= list->size) return NULL;

    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[index];
    pthread_mutex_unlock(&list->mutex);

    return pdu;
}
