#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct DataPacket {
    int packet_id;
    long timestamp;
    size_t payload_size;
} DataPacket;

typedef struct DynamicArray {
    DataPacket *data;
    size_t size;
    size_t capacity;
} DynamicArray;

void dynamic_array_init(DynamicArray *array, size_t initial_capacity) {
    array->data = (DataPacket *)malloc(initial_capacity * sizeof(DataPacket));
    if (!array->data) {
        fprintf(stderr, "Failed to allocate memory for the dynamic array\n");
        exit(EXIT_FAILURE);
    }
    array->size = 0;
    array->capacity = initial_capacity;
}

void dynamic_array_add(DynamicArray *array, DataPacket packet) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        array->data = (DataPacket *)realloc(array->data, new_capacity * sizeof(DataPacket));
        if (!array->data) {
            fprintf(stderr, "Failed to reallocate memory for the dynamic array\n");
            exit(EXIT_FAILURE);
        }
        array->capacity = new_capacity;
    }
    array->data[array->size++] = packet;
}

void dynamic_array_remove(DynamicArray *array, int packet_id) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].packet_id == packet_id) {
            memmove(&array->data[i], &array->data[i + 1], (array->size - i - 1) * sizeof(DataPacket));
            array->size--;
            break;
        }
    }
}

size_t dynamic_array_size(DynamicArray *array) {
    return array->size;
}

void dynamic_array_sort_by_timestamp(DynamicArray *array) {
    for (size_t i = 0; i < array->size - 1; ++i) {
        for (size_t j = i + 1; j < array->size; ++j) {
            if (array->data[i].timestamp > array->data[j].timestamp) {
                DataPacket temp = array->data[i];
                array->data[i] = array->data[j];
                array->data[j] = temp;
            }
        }
    }
}

void dynamic_array_free(DynamicArray *array) {
    free(array->data);
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
}
