#include <stdlib.h>
#include <string.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t count;
    size_t capacity;
} PacketArray;

void initPacketArray(PacketArray* array, size_t initial_capacity) {
    array->packets = (DataPacket*)malloc(initial_capacity * sizeof(DataPacket));
    array->count = 0;
    array->capacity = initial_capacity;
}

void freePacketArray(PacketArray* array) {
    free(array->packets);
    array->packets = NULL;
    array->count = 0;
    array->capacity = 0;
}

int addPacket(PacketArray* array, DataPacket packet) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 16;
        DataPacket* new_packets = (DataPacket*)realloc(array->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) return -1; // Memory allocation failed
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
    array->packets[array->count++] = packet;
    return 0;
}

int removePacketById(PacketArray* array, int packet_id) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->packets[i].packet_id == packet_id) {
            memmove(&array->packets[i], &array->packets[i + 1], (array->count - i - 1) * sizeof(DataPacket));
            array->count--;
            return 0;
        }
    }
    return -1; // Packet not found
}

size_t getPacketCount(PacketArray* array) {
    return array->count;
}

void sortPacketsByTimestamp(PacketArray* array) {
    qsort(array->packets, array->count, sizeof(DataPacket), (int (*)(const void*, const void*))comparePackets);
}

int comparePackets(const void* a, const void* b) {
    DataPacket packet_a = *(DataPacket*)a;
    DataPacket packet_b = *(DataPacket*)b;
    return (packet_a.timestamp > packet_b.timestamp) - (packet_a.timestamp < packet_b.timestamp);
}
