// Python function for MD5 hash computation
#include <Python.h>
#include <openssl/md5.h>

static PyObject* md5_hash(PyObject *self, PyObject *args) {
    const char *path;
    if (!PyArg_ParseTuple(args, "s", &path)) return NULL;

    FILE *file = fopen(path, "rb");
    if (!file) {
        PyErr_SetString(PyExc_FileNotFoundError, "File not found");
        return NULL;
    }

    MD5_CTX md5;
    unsigned char digest[MD5_DIGEST_LENGTH];
    int ch;
    while ((ch = fgetc(file)) != EOF) {
        MD5_Update(&md5, &ch, 1);
    }
    fclose(file);

    PyObject *result = Py_BuildValue("3s", digest, MD5_DIGEST_LENGTH);
    return result;
}

static PyMethodDef DfsMethods[] = {
    {"md5_hash", md5_hash, METH_VARARGS, "Compute MD5 hash of a file"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef dfsmodule = {
    PyModuleDef_HEAD_INIT,
    "dfs",
    NULL,
    -1,
    DfsMethods
};

PyMODINIT_FUNC PyInit_dfs(void) {
    return PyModule_Create(&dfsmodule);
}
