#include <iostream>
#include <vector>
#include <algorithm>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <atomic>
#include <memory>
#include <openssl/evp.h>

struct DataPacket {
    int packet_id;
    long timestamp;
    size_t payload_size;
};

class PacketManager {
private:
    std::vector<DataPacket> packets;
    std::mutex mutex;
    std::condition_variable cv;
    std::atomic<int> total_packets{0};
    std::string cipher_name;
    std::string digest_name;

public:
    PacketManager(const std::string& cipher, const std::string& digest) : cipher_name(cipher), digest_name(digest) {
        EVP_add_cipher(EVP_aes_256_cbc());
        EVP_add_digest(EVP_sha256());
        EVP_add_digest_alias("sha-256", "SHA256");
    }

    void addPacket(const DataPacket& packet) {
        std::lock_guard<std::mutex> lock(mutex);
        packets.push_back(packet);
        total_packets++;
        cv.notify_all();
    }

    bool removePacket(int packet_id) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = std::remove_if(packets.begin(), packets.end(), [packet_id](const DataPacket& p){ return p.packet_id == packet_id; });
        if (it != packets.end()) {
            packets.erase(it, packets.end());
            total_packets--;
            cv.notify_all();
            return true;
        }
        return false;
    }

    size_t getTotalPackets() const {
        std::lock_guard<std::mutex> lock(mutex);
        return total_packets.load();
    }

    void sortPacketsByTimestamp() {
        std::lock_guard<std::mutex> lock(mutex);
        std::sort(packets.begin(), packets.end(), [](const DataPacket& a, const DataPacket& b){ return a.timestamp < b.timestamp; });
        cv.notify_all();
    }
};

int main() {
    PacketManager pm("aes-256-cbc", "sha-256");
    DataPacket packet1 = {1, 1633072800, 1024};
    DataPacket packet2 = {2, 1633072900, 2048};
    pm.addPacket(packet1);
    pm.addPacket(packet2);
    std::cout << "Total packets: " << pm.getTotalPackets() << std::endl;
    pm.sortPacketsByTimestamp();
    return 0;
}
