    private static final String DEFAULT_AUTH_TOKEN = "default_token";
    private static final int MAX_TITLE_LENGTH = 256;

    public String generateReportTitle(List<String> inputs, Locale locale) throws Exception {
        String apiResponse = fetchMetadataFromAPI(locale);
        Metadata metadata = parseMetadata(apiResponse);

        List<String> cleanedInputs = cleanInputStrings(inputs);
        String title = constructTitle(cleanedInputs, metadata);

        logOperation(title.length(), metadata.getApiCallTime());

