    private String fetchMetadataFromAPI(Locale locale) throws Exception {
        HttpURLConnection connection = (HttpURLConnection) new URL(DEFAULT_API_URL).openConnection();
        connection.setRequestMethod("GET");
        connection.setRequestProperty("Authorization", "Bearer " + DEFAULT_AUTH_TOKEN);

        int responseCode = connection.getResponseCode();
        long startTime = System.currentTimeMillis();

        if (responseCode == HttpURLConnection.HTTP_OK) {
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String inputLine;
            StringBuilder response = new StringBuilder();
            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
            in.close();
            long endTime = System.currentTimeMillis();
            connection.disconnect();
            return response.toString();
        } else {
