    void addPacket(const DataPacket& packet) {
        packets.push_back(packet);
        std::sort(packets.begin(), packets.end(), [](const DataPacket& a, const DataPacket& b) {
            return a.timestamp < b.timestamp;
        });
    }

    bool removePacket(int packetId) {
        auto it = std::find_if(packets.begin(), packets.end(), [packetId](const DataPacket& p) {
            return p.packet_id == packetId;
        });
        if (it != packets.end()) {
            packets.erase(it);
            return true;
        }
        return false;
    }

