        std::sort(packets.begin(), packets.end(), [](const DataPacket& a, const DataPacket& b) {
            return a.timestamp < b.timestamp;
        });
    }

    float getRandomFloat(float minVal, float maxVal) {
        std::uniform_real_distribution<float> dist(minVal, maxVal);
        return dist(rng);
    }

    int getRandomInt(int minVal, int maxVal) {
        std::uniform_int_distribution<int> dist(minVal, maxVal - 1);
        return dist(rng);
    }

    double getRandomDouble(double minVal, double maxVal) {
        std::uniform_real_distribution<double> dist(minVal, maxVal);
        return dist(rng);
    }

    DataPacket getRandomColor(int rMin, int rMax, int gMin, int gMax, int bMin, int bMax) {
        int r = getRandomInt(rMin, rMax);
        int g = getRandomInt(gMin, gMax);
        int b = getRandomInt(bMin, bMax);
        return DataPacket{getRandomInt(1000000, 9999999), 0, (size_t)(r + g * 256 + b * 65536)};
    }

    std::string toString() const {
        std::ostringstream oss;
        oss << "Range: [" << min_val << ", " << max_val << "), Seed: " << rng.seed();
        return oss.str();
    }
};
