#define MAX_UE_CONTEXTS 500

typedef struct {
    int ue_id;
    uint32_t stmsi;
    char nas_message_tag[64];
} LTE_Ue_Context;

typedef struct {
    LTE_Ue_Context *contexts[MAX_UE_CONTEXTS];
    int count;
    pthread_mutex_t lock;
} LTE_Ue_List;

int lte_ue_list_init(LTE_Ue_List *list) {
    list->count = 0;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        return -1; // Error initializing mutex
    }
    return 0;
}

void lte_ue_list_free(LTE_Ue_List *list) {
    for (int i = 0; i < list->count; ++i) {
        free(list->contexts[i]);
    }
    pthread_mutex_destroy(&list->lock);
}

int lte_ue_list_add(LTE_Ue_List *list, uint32_t stmsi, const char *nas_message_tag) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_UE_CONTEXTS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Insufficient capacity
    }
    LTE_Ue_Context *new_context = malloc(sizeof(LTE_Ue_Context));
    if (!new_context) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }
    new_context->ue_id = list->count + 1;
    new_context->stmsi = stmsi;
    strncpy(new_context->nas_message_tag, nas_message_tag, sizeof(new_context->nas_message_tag) - 1);
    new_context->nas_message_tag[sizeof(new_context->nas_message_tag) - 1] = '\0';
    list->contexts[list->count++] = new_context;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

