typedef struct NetworkEvent {
    int event_id;
    char source_ip[16];
    char destination_ip[16];
    time_t timestamp;
    char event_type[50];
} NetworkEvent;

typedef struct EventManager {
    NetworkEvent *events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EventManager;

EventManager* create_event_manager() {
    EventManager *manager = (EventManager*)malloc(sizeof(EventManager));
    manager->events = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_event_manager(EventManager *manager) {
    free(manager->events);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_event(EventManager *manager, NetworkEvent event) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        manager->capacity = (manager->capacity > 0) ? manager->capacity * 2 : 1;
        manager->events = (NetworkEvent*)realloc(manager->events, manager->capacity * sizeof(NetworkEvent));
    }
    manager->events[manager->count++] = event;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_event(EventManager *manager, int event_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i].event_id == event_id) {
            memmove(&manager->events[i], &manager->events[i + 1], (manager->count - i - 1) * sizeof(NetworkEvent));
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

size_t get_event_count(EventManager *manager) {
    return manager->count;
}

