public class TileProperties
{
    public bool Walkable { get; set; }
    public float Friction { get; set; }

    public TileProperties(bool walkable, float friction)
    {
        Walkable = walkable;
        Friction = friction;
    }
}

public class ConfigLoader
{
    public static GameConfig LoadConfig(string xmlFilePath)
    {
        XDocument xmlDoc = XDocument.Load(xmlFilePath);
        GameConfig config = new GameConfig();

        // Load tile size, world dimensions, and camera speed from XML
        config.TileSize = (int)xmlDoc.Root.Element("TileSize").Value;
        config.WorldWidth = (int)xmlDoc.Root.Element("WorldWidth").Value;
        config.WorldHeight = (int)xmlDoc.Root.Element("WorldHeight").Value;
        config.CameraSpeed = (float)xmlDoc.Root.Element("CameraSpeed").Value;

        // Load tile types and their properties from XML
        var tileTypesElement = xmlDoc.Root.Element("TileTypes");
        foreach (var tileType in tileTypesElement.Elements())
        {
            string name = tileType.Attribute("name").Value;
            bool walkable = (bool)tileType.Attribute("walkable").Value;
            float friction = (float)tileType.Attribute("friction").Value;

            config.TileTypes[name] = new TileProperties(walkable, friction);
        }

        return config;
    }
}

