    size_t capacity;
    pthread_mutex_t lock;
} SessionManager;

void init_session_manager(SessionManager *manager) {
    manager->sessions = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_session_manager(SessionManager *manager) {
    free(manager->sessions);
    manager->sessions = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_destroy(&manager->lock);
}

int add_session(SessionManager *manager, UserSession session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        UserSession *new_sessions = realloc(manager->sessions, new_capacity * sizeof(UserSession));
        if (!new_sessions) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }
    manager->sessions[manager->count++] = session;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_session(SessionManager *manager, int session_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].session_id == session_id) {
            for (size_t j = i; j < manager->count - 1; ++j) {
                manager->sessions[j] = manager->sessions[j + 1];
            }
            --manager->count;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

int get_active_sessions_count(SessionManager *manager) {
    int count = 0;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i].session_status, "active") == 0) {
            ++count;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return count;
}

int filter_and_sort_sessions(SessionManager *manager, int user_id, int device_id, UserSession **filtered_sessions) {
    pthread_mutex_lock(&manager->lock);
    size_t filtered_count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].user_id == user_id && manager->sessions[i].device_id == device_id) {
            filtered_sessions[filtered_count++] = &manager->sessions[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    qsort(filtered_sessions, filtered_count, sizeof(UserSession *), 
          [](const void *a, const void *b) {
              return ((UserSession *)*a)->login_time - ((UserSession *)*b)->login_time;
          });
    return filtered_count;
}
```

This code defines a `SessionManager` structure to manage a dynamic array of `UserSession` structures. It includes functions to initialize and destroy the session manager, add new sessions, remove sessions by `session_id`, get the count of active sessions, and filter and sort sessions based on `user_id` and `device_id`. The functions are thread-safe using mutexes to minimize lock contention and ensure data integrity during concurrent access.']

