// Define DataPacket structure
typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char source_ip[16];
    char destination_ip[16];
    unsigned char *payload;
} DataPacket;

// Define DFS structure
typedef struct {
    DataPacket **packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DFS;

// Function to initialize DFS
void dfs_init(DFS *dfs, size_t initial_capacity) {
    dfs->packets = (DataPacket **)malloc(initial_capacity * sizeof(DataPacket *));
    dfs->count = 0;
    dfs->capacity = initial_capacity;
    pthread_mutex_init(&dfs->lock, NULL);
}

// Function to add packet to DFS
void dfs_add_packet(DFS *dfs, DataPacket *packet) {
    pthread_mutex_lock(&dfs->lock);
    if (dfs->count == dfs->capacity) {
        dfs->capacity *= 2;
        dfs->packets = (DataPacket **)realloc(dfs->packets, dfs->capacity * sizeof(DataPacket *));
    }
    dfs->packets[dfs->count++] = packet;
    pthread_mutex_unlock(&dfs->lock);
}

// Function to remove packet from DFS by packet_id
void dfs_remove_packet(DFS *dfs, int packet_id) {
    pthread_mutex_lock(&dfs->lock);
    for (size_t i = 0; i < dfs->count; ++i) {
        if (dfs->packets[i]->packet_id == packet_id) {
            free(dfs->packets[i]->payload);
            free(dfs->packets[i]);
            memmove(dfs->packets + i, dfs->packets + i + 1, (dfs->count - i - 1) * sizeof(DataPacket *));
            --dfs->count;
            break;
        }
    }
    pthread_mutex_unlock(&dfs->lock);
}

// Function to get the total number of packets
size_t dfs_get_count(DFS *dfs) {
    return dfs->count;
}

// Function to sort packets by timestamp
void dfs_sort_packets_by_timestamp(DFS *dfs) {
    qsort(dfs->packets, dfs->count, sizeof(DataPacket *), [](const void *a, const void *b) {
        return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp;
    });
}

// Function to clean up DFS
void dfs_cleanup(DFS *dfs) {
    for (size_t i = 0; i < dfs->count; ++i) {
        free(dfs->packets[i]->payload);
        free(dfs->packets[i]);
    }
    free(dfs->packets);
    pthread_mutex_destroy(&dfs->lock);
}

// Python function to compute MD5 hash of a large DFS file
#include <Python.h>
#include <fcntl.h>
#include <unistd.h>

static PyObject* compute_md5(const char* path) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        PyErr_SetFromErrno(PyExc_IOError);
        return NULL;
    }

    unsigned char buffer[4096];
    MD5_CTX md5;
    MD5_Init(&md5);

    ssize_t bytes_read;
    while ((bytes_read = read(fd, buffer, sizeof(buffer))) > 0) {
        MD5_Update(&md5, buffer, (unsigned int)bytes_read);
    }

    close(fd);

    if (bytes_read == -1) {
        PyErr_SetFromErrno(PyExc_IOError);
        return NULL;
    }

    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_Final(hash, &md5);

    PyObject *result = PyUnicode_FromFormat("%02x%02x%02x%02x%02x%02x%02x%02x"
                                           "%02x%02x%02x%02x%02x%02x%02x%02x",
                                           hash[0], hash[1], hash[2], hash[3],
                                           hash[4], hash[5], hash[6], hash[7],
                                           hash[8], hash[9], hash[10], hash[11],
                                           hash[12], hash[13], hash[14], hash[15]);
    return result;
}

static PyMethodDef methods[] = {
    {"compute_md5", compute_md5, METH_O, "Compute MD5 hash of a large file"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef mod = {
    PyModuleDef_HEAD_INIT,
    "md5hash",
    NULL,
    -1,
    methods
};

PyMODINIT_FUNC PyInit_md5hash(void) {
    return PyModule_Create(&mod);
}

