struct DataPacket {
    int packet_id;
    long timestamp;
    size_t payload_size;
};

class DynamicDataManager {
private:
    std::vector<DataPacket> packets;
    std::mt19937 randomGenerator;
    int minRange, maxRange;

public:
    DynamicDataManager(int minVal, int maxVal) : minRange(minVal), maxRange(maxVal), randomGenerator(std::random_device()()) {}

    void addPacket(const DataPacket& packet) {
        packets.push_back(packet);
        std::sort(packets.begin(), packets.end(), [](const DataPacket& a, const DataPacket& b) { return a.timestamp < b.timestamp; });
    }

    bool removePacket(int packetId) {
        auto it = std::find_if(packets.begin(), packets.end(), [packetId](const DataPacket& packet) { return packet.packet_id == packetId; });
        if (it != packets.end()) {
            packets.erase(it);
            return true;
        }
        return false;
    }

    size_t getNumberOfPackets() const {
        return packets.size();
    }

    void sortPacketsByTimestamp() {
        std::sort(packets.begin(), packets.end(), [](const DataPacket& a, const DataPacket& b) { return a.timestamp < b.timestamp; });
    }

    float getRandomFloat(float minVal, float maxVal) {
        std::uniform_real_distribution<float> distribution(minVal, maxVal);
        return distribution(randomGenerator);
    }

    int getRandomInt(int minVal, int maxVal) {
        if (minVal >= maxVal) throw std::invalid_argument("Invalid range");
        std::uniform_int_distribution<int> distribution(minVal, maxVal - 1);
        return distribution(randomGenerator);
    }

    double getRandomDouble(double minVal, double maxVal) {
        std::uniform_real_distribution<double> distribution(minVal, maxVal);
        return distribution(randomGenerator);
    }

    void getRandomColor(int& r, int& g, int& b) {
        r = getRandomInt(0, 256);
        g = getRandomInt(0, 256);
        b = getRandomInt(0, 256);
    }

    std::string ToString() const {
        std::ostringstream oss;
        oss << "DynamicDataManager with " << packets.size() << " packets. Range: [" << minRange << ", " << maxRange << "]";
        return oss.str();
    }

    void exportToFile(const std::string& filename) {
        std::ofstream file(filename, std::ios::binary);
        if (!file.is_open()) throw std::runtime_error("Failed to open file for writing");
        size_t size = packets.size();
        file.write(reinterpret_cast<char*>(&size), sizeof(size));
        file.write(reinterpret_cast<const char*>(packets.data()), size * sizeof(DataPacket));
        if (!file) throw std::runtime_error("Error writing to file");
    }

    void importFromFile(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file.is_open()) throw std::runtime_error("Failed to open file for reading");
        size_t size;
        file.read(reinterpret_cast<char*>(&size), sizeof(size));
        packets.resize(size);
        file.read(reinterpret_cast<char*>(packets.data()), size * sizeof(DataPacket));
        if (!file) throw std::runtime_error("Error reading from file");
    }

    void serializeToJson(std::ostream& os) const {
        os << "{";
        os << "\"packet_count\":" << packets.size() << ",";
        os << "\"min_range\":" << minRange << ",";
        os << "\"max_range\":" << maxRange;
        os << "}";
    }
};
