#include <iostream>
#include <unordered_map>
#include <list>
#include <fstream>
#include <string>
#include <json/json.h>

struct UserSession {
    std::string session_id;
    std::string user_name;
    time_t login_time;
    time_t last_activity_time;
    enum class Status { active, inactive, expired };
    Status status;

    UserSession(const std::string& id, const std::string& name, time_t login, time_t activity, Status s)
        : session_id(id), user_name(name), login_time(login), last_activity_time(activity), status(s) {}
};

class SessionManager {
private:
    std::unordered_map<std::string, UserSession*> sessions;
    std::list<UserSession*> orderedSessions;
    int maxSessions;
    time_t inactivityTimeout;

public:
    SessionManager(int maxSess, time_t timeout)
        : maxSessions(maxSess), inactivityTimeout(timeout) {}

    ~SessionManager() {
        for (auto session : orderedSessions) {
            delete session;
        }
    }

    void addSession(const UserSession& session) {
        if (sessions.size() >= maxSessions) {
            removeOldestInactiveSession();
        }
        sessions[session.session_id] = new UserSession(session);
        orderedSessions.push_back(sessions[session.session_id]);
    }

    bool removeSession(const std::string& sessionId) {
        auto it = sessions.find(sessionId);
        if (it != sessions.end()) {
            for (auto pos = orderedSessions.begin(); pos != orderedSessions.end(); ++pos) {
                if (*pos == it->second) {
                    orderedSessions.erase(pos);
                    break;
                }
            }
            delete it->second;
            sessions.erase(it);
            return true;
        }
        return false;
    }

    void updateSessionStatus(const std::string& sessionId, UserSession::Status newStatus) {
        auto it = sessions.find(sessionId);
        if (it != sessions.end()) {
            it->second->status = newStatus;
        }
    }

    int getTotalSessions() const {
        return orderedSessions.size();
    }

    void sortSessionsByLastActivity() {
        orderedSessions.sort([](const UserSession* a, const UserSession* b) {
            return a->last_activity_time > b->last_activity_time;
        });
    }

    void exportSessions(const std::string& filename, const std::string& format) {
        std::ofstream file(filename);
        if (format == "csv") {
            // Implement CSV export
        } else if (format == "json") {
            Json::Value root;
            for (auto session : orderedSessions) {
                Json::Value s;
                s["session_id"] = session->session_id;
                s["user_name"] = session->user_name;
                s["login_time"] = ctime(&session->login_time);
                s["last_activity_time"] = ctime(&session->last_activity_time);
                s["status"] = static_cast<int>(session->status);
                root.append(s);
            }
            file << Json::StreamWriterBuilder().newStreamWriter()->write(root);
        }
    }

private:
    void removeOldestInactiveSession() {
        auto now = time(nullptr);
        for (auto pos = orderedSessions.begin(); pos != orderedSessions.end(); ++pos) {
            if ((*pos)->status == UserSession::Status::inactive && difftime(now, (*pos)->last_activity_time) > inactivityTimeout) {
                removeSession((*pos)->session_id);
                break;
            }
        }
    }
};
