void log_memory_allocation(time_t timestamp, size_t allocated_size, int RNTI) {
    // Implementation of logging memory allocation to a centralized service
}

int allocate_NFAPI_CRC_INDICATION_PDU(int N, pthread_mutex_t *mutex) {
    if (N <= 0) {
        return -1; // Error: Zero or negative size
    }

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (array == NULL) {
        log_memory_allocation(time(NULL), 0, 0); // Log failed allocation
        return -2; // Error: Memory allocation failure
    }

    pthread_mutex_lock(mutex);

    time_t current_time = time(NULL);
    size_t total_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (total_size > MAX_MEMORY_USAGE_KB) {
        free(array);
        log_memory_allocation(current_time, 0, 0); // Log exceeded memory usage
        pthread_mutex_unlock(mutex);
        return -3; // Error: Exceeded maximum memory usage
    }

    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i].CRCFLAG = rand() % 2;

        log_memory_allocation(current_time, sizeof(NFAPI_CRC_INDICATION_PDU_T), array[i].RNTI);
    }

    pthread_mutex_unlock(mutex);

    return (int)array; // Return pointer to allocated memory
}

