        pdus[i].rnti = rand() % 65536; // Random RNTI
        pdus[i].crc_indication.CRCFLAG = rand() % 2; // Random CRC flag
    }

    return pdus;
}

void free_crc_pdus(NFAPI_CRC_INDICATION_PDU_T* pdus, size_t N) {
    if (pdus != NULL && N > 0) {
        free(pdus);
    }
