}

void *bulk_delete_old_logs(void *args) {
    time_t current_time = time(NULL);
    time_t retention_cutoff = current_time - RETENTION_PERIOD * 24 * 3600;
    pthread_mutex_lock(&log_mutex);
    for (int i = log_count - 1; i >= 0; i--) {
        if (logs[i].timestamp < retention_cutoff) {
            memmove(&logs[i], &logs[i + 1], sizeof(LogEntry) * (log_count - i - 1));
            log_count--;
        }
    }
    pthread_mutex_unlock(&log_mutex);
    pthread_exit(NULL);
}

