typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char source_ip[16];
    char destination_ip[16];
} DataPacket;

typedef struct PacketManager {
    DataPacket *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *manager) {
    manager->packets = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_packet(PacketManager *manager, DataPacket packet) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        manager->capacity = (manager->capacity > 0) ? manager->capacity * 2 : 1;
        manager->packets = realloc(manager->packets, manager->capacity * sizeof(DataPacket));
    }
    manager->packets[manager->count++] = packet;
    pthread_mutex_unlock(&manager->lock);
}

void remove_packet(PacketManager *manager, int packet_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->packets[i].packet_id == packet_id) {
            memmove(&manager->packets[i], &manager->packets[i + 1], (manager->count - i - 1) * sizeof(DataPacket));
            --manager->count;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

size_t get_packet_count(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    size_t count = manager->count;
    pthread_mutex_unlock(&manager->lock);
    return count;
}

void sort_packets_by_timestamp(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);
    qsort(manager->packets, manager->count, sizeof(DataPacket), [](const void *a, const void *b) {
        return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp;
    });
    pthread_mutex_unlock(&manager->lock);
}

void prune_old_packets(PacketManager *manager, time_t grace_period) {
    pthread_mutex_lock(&manager->lock);
    size_t i = 0;
    while (i < manager->count && manager->packets[i].timestamp + grace_period < time(NULL)) {
        ++i;
    }
    if (i > 0) {
        memmove(manager->packets, &manager->packets[i], (manager->count - i) * sizeof(DataPacket));
        manager->count -= i;
    }
    pthread_mutex_unlock(&manager->lock);
}

