    void addSegment(const StreamSegment& segment) {
        std::lock_guard<std::mutex> lock(queueMutex);
        segmentQueue.push(segment);
        mergeSegments();
    }

    bool removeSegment(int segment_id) {
        std::lock_guard<std::mutex> lock(queueMutex);
        auto it = std::find_if(segmentQueue.begin(), segmentQueue.end(),
                               [segment_id](const StreamSegment& seg) { return seg.segment_id == segment_id; });
        if (it != segmentQueue.end()) {
            segmentQueue.erase(it);
            mergeSegments();
            return true;
        }
        return false;
    }

    int getSegmentCount() const {
