class TransactionPacket {
public:
    int transaction_id;
    std::chrono::steady_clock::time_point timestamp;
    double weight;

    TransactionPacket(int id, std::chrono::steady_clock::time_point ts, double w)
        : transaction_id(id), timestamp(ts), weight(w) {}
};

class DynamicTransactionManager {
private:
    struct TransactionInfo {
        TransactionPacket packet;
        int countInLast10Secs = 0;
        double sumWeightOlderThan1Sec = 0.0;
    };

    std::vector<TransactionInfo> transactions;
    std::mutex mtx;
    std::condition_variable cv;
    std::chrono::steady_clock::time_point startTimestamp;

    void updateTransactionCounts() {
        auto now = std::chrono::steady_clock::now();
        for (auto& info : transactions) {
            if (info.packet.timestamp < now - std::chrono::seconds(1)) {
                info.sumWeightOlderThan1Sec += info.packet.weight;
            }
            if (info.packet.timestamp < now - std::chrono::seconds(5)) {
                info.countInLast10Secs++;
            } else {
                info.countInLast10Secs = 0;
            }
        }
    }

public:
    DynamicTransactionManager() : startTimestamp(std::chrono::steady_clock::now()) {}

    void addTransaction(int id, double weight) {
        std::lock_guard<std::mutex> lock(mtx);
        auto now = std::chrono::steady_clock::now();
        transactions.emplace_back(id, now, weight);
        cv.notify_one();
    }

    bool removeTransaction(int id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::remove_if(transactions.begin(), transactions.end(),
                                 [id](const TransactionInfo& info) { return info.packet.transaction_id == id; });
        if (it != transactions.end()) {
            transactions.erase(it, transactions.end());
            cv.notify_one();
            return true;
        }
        return false;
    }

    int getTransactionCount() const {
        std::lock_guard<std::mutex> lock(mtx);
        return transactions.size();
    }

    bool processTransactions() {
        std::unique_lock<std::mutex> lock(mtx);
        if (cv.wait_for(lock, std::chrono::milliseconds(1), [this] { return !transactions.empty(); })) {
            updateTransactionCounts();
            // Process transactions based on criteria
            // ...
            return true;
        }
        return false;
    }

    void reportHealthStatus() const {
        // Report health status
        // ...
    }

    void exportState(const std::string& filename) {
        std::ofstream ofs(filename, std::ios::binary);
        if (ofs.is_open()) {
            nlohmann::json j = transactions;
            ofs.write(j.dump().c_str(), j.dump().size());
            ofs.close();
        } else {
            throw std::runtime_error("Failed to open file for writing");
        }
    }

    void importState(const std::string& filename) {
        std::ifstream ifs(filename, std::ios::binary);
        if (ifs.is_open()) {
            nlohmann::json j;
            ifs >> j;
            transactions = j.get<std::vector<TransactionInfo>>();
            ifs.close();
        } else {
            throw std::runtime_error("Failed to open file for reading");
        }
    }

    int getRandomValue(int min, int max) const {
        // Use System.Random class for generating random values
        // ...
    }

    void serializeToJson() const {
        // Serialize internal state to JSON format
        // ...
    }
};
