#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define node and edge structures
typedef struct {
    int node_id;
    time_t timestamp;
    void* attributes;
    void* metadata;
} Node;

typedef struct {
    int edge_id;
    int source_node_id;
    int destination_node_id;
    char relationship_type[50];
    float weight;
} Edge;

// Define graph structure
typedef struct {
    Node** nodes;
    Edge** edges;
    int node_count;
    int edge_count;
    pthread_mutex_t lock;
} Graph;

// Initialize a new graph
Graph* init_graph() {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->nodes = NULL;
    graph->edges = NULL;
    graph->node_count = 0;
    graph->edge_count = 0;
    pthread_mutex_init(&graph->lock, NULL);
    return graph;
}

// Add a node to the graph
void add_node(Graph* graph, Node* node) {
    pthread_mutex_lock(&graph->lock);
    graph->nodes = realloc(graph->nodes, (graph->node_count + 1) * sizeof(Node*));
    graph->nodes[graph->node_count++] = node;
    pthread_mutex_unlock(&graph->lock);
}

// Add an edge to the graph
void add_edge(Graph* graph, Edge* edge) {
    pthread_mutex_lock(&graph->lock);
    graph->edges = realloc(graph->edges, (graph->edge_count + 1) * sizeof(Edge*));
    graph->edges[graph->edge_count++] = edge;
    pthread_mutex_unlock(&graph->lock);
}

// Update a node in the graph
void update_node(Graph* graph, int node_id, Node* new_node) {
    pthread_mutex_lock(&graph->lock);
    for (int i = 0; i < graph->node_count; i++) {
        if (graph->nodes[i]->node_id == node_id) {
            *graph->nodes[i] = *new_node;
            break;
        }
    }
    pthread_mutex_unlock(&graph->lock);
}

// Update an edge in the graph
void update_edge(Graph* graph, int edge_id, Edge* new_edge) {
    pthread_mutex_lock(&graph->lock);
    for (int i = 0; i < graph->edge_count; i++) {
        if (graph->edges[i]->edge_id == edge_id) {
            *graph->edges[i] = *new_edge;
            break;
        }
    }
    pthread_mutex_unlock(&graph->lock);
}

// Delete a node from the graph
void delete_node(Graph* graph, int node_id) {
    pthread_mutex_lock(&graph->lock);
    for (int i = 0; i < graph->node_count; i++) {
        if (graph->nodes[i]->node_id == node_id) {
            free(graph->nodes[i]);
            for (int j = i; j < graph->node_count - 1; j++) {
                graph->nodes[j] = graph->nodes[j + 1];
            }
            graph->node_count--;
            break;
        }
    }
    pthread_mutex_unlock(&graph->lock);
}

// Delete an edge from the graph
void delete_edge(Graph* graph, int edge_id) {
    pthread_mutex_lock(&graph->lock);
    for (int i = 0; i < graph->edge_count; i++) {
        if (graph->edges[i]->edge_id == edge_id) {
            free(graph->edges[i]);
            for (int j = i; j < graph->edge_count - 1; j++) {
                graph->edges[j] = graph->edges[j + 1];
            }
            graph->edge_count--;
            break;
        }
    }
    pthread_mutex_unlock(&graph->lock);
}

// Free the memory allocated for the graph
void free_graph(Graph* graph) {
    pthread_mutex_lock(&graph->lock);
    for (int i = 0; i < graph->node_count; i++) {
        free(graph->nodes[i]);
    }
    for (int i = 0; i < graph->edge_count; i++) {
        free(graph->edges[i]);
    }
    free(graph->nodes);
    free(graph->edges);
    pthread_mutex_unlock(&graph->lock);
    pthread_mutex_destroy(&graph->lock);
    free(graph);
}
