public class ReportTitleGenerator {

    private static final Logger logger = LoggerFactory.getLogger(ReportTitleGenerator.class);

    public String generateReportTitle(String[] inputs) {
        // Log input details
        logger.info("Input count: {}", inputs.length);

        StringBuilder titleBuilder = new StringBuilder();
        int totalLength = 0;

        for (String input : inputs) {
            if (input != null && !input.isEmpty()) {
                titleBuilder.append(input).append(" ");
                totalLength += input.length() + 1;
            }
        }

        // Fetch additional metadata from external API
        long startTime = System.currentTimeMillis();
        ExternalAPIClient apiClient = new ExternalAPIClient();
        Metadata metadata = apiClient.fetchMetadata();
        long endTime = System.currentTimeMillis();
        logger.info("External API response time: {}ms", endTime - startTime);

        if (metadata == null) {
            metadata = new Metadata();
            metadata.setDepartmentCode("UNKNOWN");
            metadata.setVersionNumber("1.0");
            metadata.setRegionalSettings("EN_US");
        }

        // Construct final title
        String departmentCode = metadata.getDepartmentCode();
        String versionNumber = metadata.getVersionNumber();
        String regionalSettings = metadata.getRegionalSettings();

        titleBuilder.append("- Dept: ").append(departmentCode)
                     .append(", Ver: ").append(versionNumber)
                     .append(", Reg: ").append(regionalSettings);

        // Add timestamp and total length
        titleBuilder.append(" [").append(new Date()).append("], Length: ")
                     .append(totalLength);

        String finalTitle = titleBuilder.toString();

        // Log final title details
        logger.info("Final title length: {}", finalTitle.length());

        return finalTitle;
    }
}
