typedef struct {
    uint8_t header[16];
    uint8_t payload[PDU_SIZE - 16];
    uint32_t checksum;
} MAC_PDU;

typedef struct {
    uint16_t id;
    MAC_PDU *pdus;
    size_t pdu_count;
} MAC_Entity_Config;

MAC_Entity_Config* initialize_mac_entities(size_t entity_count) {
    if (entity_count > MAX_MAC_ENTITIES) {
        return NULL; // Handle overflow scenario
    }

    MAC_Entity_Config* configs = (MAC_Entity_Config*)malloc(entity_count * sizeof(MAC_Entity_Config));
    if (!configs) {
        return NULL; // Handle memory allocation failure
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < entity_count; ++i) {
        configs[i].id = i + 1;
        configs[i].pdu_count = rand() % 10 + 1; // Random number of PDUs per entity
        configs[i].pdus = (MAC_PDU*)malloc(configs[i].pdu_count * sizeof(MAC_PDU));
        if (!configs[i].pdus) {
            // Handle memory allocation failure for individual PDUs
            for (size_t j = 0; j < i; ++j) {
                free(configs[j].pdus);
            }
            free(configs);
            return NULL;
        }

        for (size_t j = 0; j < configs[i].pdu_count; ++j) {
            // Generate random data for header and payload
            for (int k = 0; k < 16; ++k) {
                configs[i].pdus[j].header[k] = rand();
            }
            for (int k = 0; k < PDU_SIZE - 16; ++k) {
                configs[i].pdus[j].payload[k] = rand();
            }

            // Calculate checksum
            uint32_t sum = 0;
            for (size_t k = 0; k < 16 + PDU_SIZE - 16; ++k) {
                sum += (uint8_t*)&configs[i].pdus[j]->payload[k];
            }
            configs[i].pdus[j].checksum = sum;
        }
    }

    return configs;
}

void free_mac_entities(MAC_Entity_Config* configs, size_t entity_count) {
    for (size_t i = 0; i < entity_count; ++i) {
        free(configs[i].pdus);
    }
    free(configs);
}
