    uint8_t payload[1500]; // Maximum Ethernet frame payload size
} DownlinkMacPdu;

typedef struct MacEntityConfig {
    uint64_t entityId;
    DownlinkMacPdu *pdus;
    int pduCount;
} MacEntityConfig;

MacEntityConfig* initializeMacEntityConfigs(const char* configFilePath) {
    MacEntityConfig* macEntities = (MacEntityConfig*)malloc(MAX_MAC_ENTITIES * sizeof(MacEntityConfig));
    if (!macEntities) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Simulate reading from configuration file
    FILE* configFile = fopen(configFilePath, "r");
    if (!configFile) {
        fprintf(stderr, "Failed to open configuration file: %s\n", configFilePath);
        free(macEntities);
        return NULL;
    }

    int entityCount = 0;
    while (entityCount < MAX_MAC_ENTITIES && fscanf(configFile, "%lu", &macEntities[entityCount].entityId) == 1) {
        macEntities[entityCount].pdus = (DownlinkMacPdu*)malloc(5 * sizeof(DownlinkMacPdu)); // Example: 5 PDUs per entity
        if (!macEntities[entityCount].pdus) {
            fprintf(stderr, "Memory allocation failed for entity ID: %lu\n", macEntities[entityCount].entityId);
            // Clean up previously allocated entities
            for (int i = 0; i < entityCount; ++i) {
                free(macEntities[i].pdus);
            }
            free(macEntities);
            fclose(configFile);
            return NULL;
        }

        // Simulate PDU initialization with random data and checksum
        for (int i = 0; i < 5; ++i) {
            // Fill header with dummy values
            memset(macEntities[entityCount].pdus[i].header, 0x12, 14);
            // Fill payload with random data
            srand(time(NULL));
            for (int j = 0; j < 1500; ++j) {
                macEntities[entityCount].pdus[i].payload[j] = rand() % 0xFF;
            }
            // Calculate checksum (example: simple sum of all bytes)
            uint16_t checksum = 0;
            for (int j = 0; j < 1514; ++j) {
                checksum += macEntities[entityCount].pdus[i].payload[j];
            }
            // Store checksum in a reserved space or handle as needed
        }

        macEntities[entityCount].pduCount = 5;
        entityCount++;
    }

    fclose(configFile);
    return macEntities;
}

void freeMacEntityConfigs(MacEntityConfig* macEntities) {
    if (macEntities) {
        for (int i = 0; i < MAX_MAC_ENTITIES && macEntities[i].entityId != 0; ++i) {
            free(macEntities[i].pdus);
        }
        free(macEntities);
    }
}

int main() {
    MacEntityConfig* configs = initializeMacEntityConfigs("config.txt");
    if (configs) {
        // Use the initialized configurations
        freeMacEntityConfigs(configs);
    }
    return 0;
}
