use actix_web::{web, App, HttpServer, Responder};
use std::env;
use std::sync::Arc;
use tokio::task;

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let server_port = env::var("SERVER_PORT").unwrap_or_else(|_| "8080".to_string());
    let health_check_url = env::var("HEALTH_CHECK_URL").unwrap_or_else(|_| "http://healthcheck.example.com".to_string());

    HttpServer::new(move || {
        App::new()
            .wrap(HealthCheckMiddleware { url: health_check_url.clone() })
            .route("/{path:.*}", web::get().to(|| async { "Hello world" }))
    })
    .bind(format!("0.0.0.0:{}", server_port))?
    .run()
    .await
}

struct HealthCheckMiddleware {
    url: String,
}

impl<Body> actix_web::middleware::Middleware<Body> for HealthCheckMiddleware {
    type Response = Body;
    type Error = std::convert::Infallible;

    fn start(&self, req: &actix_http::HttpRequest) -> Result<Self::Response, Self::Error> {
        // Perform health check
        let response = reqwest::get(&self.url).await.unwrap();
        if response.status().is_success() {
            println!("Health check passed");
        } else {
            println!("Health check failed");
        }
        Ok(req.into_body())
    }

    fn handle(
        &self,
        req: actix_http::HttpRequest,
        body: Body,
        service: &mut actix_web::dev::Service<actix_web::dev::Request, Response = self::Response>,
    ) -> Self::Future {
        // Call the next middleware or handler
        let future = service.call(req);
        async move {
            let response = future.await?;
            Ok(response)
        }
    }

    type Future = std::future::Ready<Result<Self::Response, Self::Error>>;
}
