import json
from collections import defaultdict
import asyncio

class JSONHandler:
    _factory_registry = {}

    @classmethod
    def register_factory(cls, type_id, factory_function):
        if type_id in cls._factory_registry:
            raise ValueError(f"Type ID {type_id} already registered.")
        cls._factory_registry[type_id] = factory_function

    @classmethod
    async def parse_json(cls, json_str, max_entries=10_000_000):
        data = json.loads(json_str)
        results = []
        for entry in data:
            type_id = entry.get('type')
            if type_id not in cls._factory_registry:
                raise ValueError(f"Unknown type ID: {type_id}")
            factory = cls._factory_registry[type_id]
            instance = await factory(entry)
            results.append(instance)
            if len(results) >= max_entries:
                break
        return results

    async def serialize_json(self, obj):
        return json.dumps(obj)

# Example subclass
class User:
    def __init__(self, name=None, age=None):
        self.name = name
        self.age = age

    @classmethod
    async def from_json(cls, data):
        if 'name' not in data or 'age' not in data:
            return cls(name=data.get('name', None), age=data.get('age', 0))
        return cls(**data)

    def to_json(self):
        return {'type': self.__class__.__name__, 'name': self.name, 'age': self.age}

# Register factory
JSONHandler.register_factory('User', User.from_json)

# Example usage
json_str = '[{"type": "User", "name": "Alice", "age": 30}]'
users = asyncio.run(JSONHandler.parse_json(json_str))
print([user.name for user in users])
