    pthread_mutex_lock(&mutex);

    if (N > MAX_STRUCTS || N <= 0) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Memory allocation failed
    }

    srand(time(NULL) + thread_id); // Seed for different threads

    for (int i = 0; i < N; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu_list[i].RNTI = rand() % 256;
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        pdu_list[i].CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }

    pthread_mutex_unlock(&mutex);
    return pdu_list;
}

void free_NFAPdu(NFAPI_CRC_INDICATION_PDU_T* p) {
    if (p) {
        free(p);
    }
}
