#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 10000

typedef struct {
    RX_UE_INFORMATION_TAG ue_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** structures;
int current_count = 0;
pthread_mutex_t mutex;

void init_structures() {
    pthread_mutex_init(&mutex, NULL);
    structures = (NFAPI_CRC_INDICATION_PDU_T**)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
}

void destroy_structures() {
    for (int i = 0; i < current_count; i++) {
        free(structures[i]);
    }
    free(structures);
    pthread_mutex_destroy(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T* create_structure(RX_UE_INFORMATION_TAG ue_tag, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* new_struct = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_struct) return NULL;

    pthread_mutex_lock(&mutex);
    if (current_count >= MAX_STRUCTURES) {
        free(new_struct);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    structures[current_count++] = new_struct;
    pthread_mutex_unlock(&mutex);

    new_struct->ue_tag = ue_tag;
    new_struct->rnti = rnti;
    new_struct->crc_tag.CRCFLAG = rand() % 2;

    return new_struct;
}

void destroy_structure(NFAPI_CRC_INDICATION_PDU_T* struct_ptr) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < current_count; i++) {
        if (structures[i] == struct_ptr) {
            free(struct_ptr);
            structures[i] = structures[--current_count];
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void* allocate_memory(void* arg) {
    int count = *(int*)arg;
    for (int i = 0; i < count; i++) {
        create_structure((RX_UE_INFORMATION_TAG)(i % 100), (uint16_t)i);
    }
    return NULL;
}

void* deallocate_memory(void* arg) {
    int count = *(int*)arg;
    for (int i = current_count - 1; i >= 0 && i >= current_count - count; i--) {
