using System;
using System.Diagnostics;
using System.IO;

public class WebsiteManager {
    public static Process AddSite(string directoryPath, string siteName) {
        if (!Directory.Exists(directoryPath)) {
            Console.WriteLine("Directory does not exist");
            return null;
        }

        string webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath)) {
            Console.WriteLine("Web.config file does not exist");
            return null;
        }

        ProcessStartInfo startInfo = new ProcessStartInfo();
        startInfo.FileName = "website.exe";
        startInfo.Arguments = $"-directory {directoryPath} -site {siteName}";
        startInfo.RedirectStandardOutput = true;
        startInfo.UseShellExecute = false;

        try {
            Process process = Process.Start(startInfo);
            return process;
        } catch (Exception ex) {
            Console.WriteLine($"Failed to start website: {ex.Message}");
            return null;
        }
    }

    public static void Main() {
        string directoryPath = @"C:\path\to\directory";
        string siteName = "MyWebsite";
        Process process = AddSite(directoryPath, siteName);
        if (process != null) {
            Console.WriteLine("Website started successfully");
        } else {
            Console.WriteLine("Failed to start website");
        }
    }
}
