#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char source_ip[16];
    char destination_ip[16];
} DataPacket;

typedef struct PacketManager {
    DataPacket* packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager* pm) {
    pm->packets = NULL;
    pm->count = 0;
    pm->capacity = 0;
    pthread_mutex_init(&pm->lock, NULL);
}

void add_packet(PacketManager* pm, DataPacket packet) {
    pthread_mutex_lock(&pm->lock);
    if (pm->count >= pm->capacity) {
        size_t new_capacity = (pm->capacity == 0) ? 1 : pm->capacity * 2;
        DataPacket* new_packets = realloc(pm->packets, new_capacity * sizeof(DataPacket));
        if (new_packets == NULL) {
            pthread_mutex_unlock(&pm->lock);
            return; // Handle error
        }
        pm->packets = new_packets;
        pm->capacity = new_capacity;
    }
    pm->packets[pm->count++] = packet;
    pthread_mutex_unlock(&pm->lock);
}

void remove_packet(PacketManager* pm, int packet_id) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i].packet_id == packet_id) {
            memmove(&pm->packets[i], &pm->packets[i + 1], (pm->count - i - 1) * sizeof(DataPacket));
            --pm->count;
            break;
        }
    }
    pthread_mutex_unlock(&pm->lock);
}

size_t get_packet_count(PacketManager* pm) {
    return pm->count;
}

void sort_packets_by_timestamp(PacketManager* pm) {
    qsort(pm->packets, pm->count, sizeof(DataPacket), [](const void* a, const void* b) {
        return ((DataPacket*)a)->timestamp - ((DataPacket*)b)->timestamp;
    });
}

void cleanup_packet_manager(PacketManager* pm) {
    pthread_mutex_lock(&pm->lock);
    free(pm->packets);
    pm->packets = NULL;
    pm->count = 0;
    pm->capacity = 0;
    pthread_mutex_unlock(&pm->lock);
    pthread_mutex_destroy(&pm->lock);
}

// Python function to compute MD5 hash of a large DFS file
#include <openssl/md5.h>
#include <fcntl.h>
#include <unistd.h>

void compute_md5_of_file(const char* file_path) {
    int fd = open(file_path, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return; // Handle error
    }

    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX md5;
    MD5_Init(&md5);

    const size_t BUFFER_SIZE = 4096;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    while ((bytes_read = read(fd, buffer, BUFFER_SIZE)) > 0) {
        MD5_Update(&md5, buffer, bytes_read);
    }

    if (bytes_read == -1) {
        perror("Failed to read file");
        close(fd);
        return; // Handle error
    }

    MD5_Final(hash, &md5);

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        printf("%02x", hash[i]);
    }
    printf("\n");

    close(fd);
}
