using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class DynamicSQLExecutor
{
    public async Task<IDataReader> ExecuteDynamicQueryAsync(
        List<object> values,
        SqlConnection connection,
        string commandTemplate,
        Func<List<object>, bool> filterFunction = null,
        Dictionary<string, object> context = null)
    {
        // Validate and sanitize inputs
        if (values == null || connection == null || string.IsNullOrEmpty(commandTemplate))
            throw new ArgumentException("Invalid input parameters.");

        if (context != null)
        {
            foreach (var item in context)
            {
                if (item.Key.Contains("'") || item.Value.ToString().Contains("'"))
                    throw new ArgumentException("Context contains invalid characters.");
            }
        }

        // Apply filter function if provided
        if (filterFunction != null && !filterFunction(values))
            return null;

        // Construct SQL query dynamically
        string sqlQuery = commandTemplate;
        for (int i = 0; i < values.Count; i++)
        {
            sqlQuery = sqlQuery.Replace($"{{{i}}}", $"@Param{i}");
        }

        using (SqlCommand command = new SqlCommand(sqlQuery, connection))
        {
            // Add parameters to the command
            for (int i = 0; i < values.Count; i++)
            {
                command.Parameters.AddWithValue($"@Param{i}", values[i]);
            }

            // Execute query and return data reader
            await connection.OpenAsync();
            return await command.ExecuteReaderAsync(CommandBehavior.CloseConnection);
        }
    }
}
