#define MAX_PACKETS 1024
#define GRACE_PERIOD 3600 // 1 hour in seconds

typedef struct {
    unsigned int packet_id;
    time_t timestamp;
    size_t payload_size;
    char source_ip[16];
    char destination_ip[16];
} DataPacket;

DataPacket packets[MAX_PACKETS];
int packet_count = 0;

void add_packet(DataPacket *packet) {
    if (packet_count < MAX_PACKETS) {
        memcpy(&packets[packet_count], packet, sizeof(DataPacket));
        packet_count++;
    } else {
        printf("Error: Packet array is full\n");
    }
}

void remove_packet(unsigned int packet_id) {
    for (int i = 0; i < packet_count; i++) {
        if (packets[i].packet_id == packet_id) {
            memmove(&packets[i], &packets[i + 1], sizeof(DataPacket) * (packet_count - i - 1));
            packet_count--;
            break;
        }
    }
}

int get_packet_count() {
    return packet_count;
}

void sort_packets_by_timestamp() {
    for (int i = 0; i < packet_count - 1; i++) {
        for (int j = 0; j < packet_count - i - 1; j++) {
            if (packets[j].timestamp > packets[j + 1].timestamp) {
                DataPacket temp = packets[j];
                packets[j] = packets[j + 1];
                packets[j + 1] = temp;
            }
        }
    }
}

void remove_old_packets() {
    time_t current_time = time(NULL);
    for (int i = packet_count - 1; i >= 0; i--) {
        if (current_time - packets[i].timestamp > GRACE_PERIOD) {
            remove_packet(packets[i].packet_id);
        }
    }
}

void log_operation(const char *operation) {
    // Integrate with an external logging service
    printf("Logged: %s\n", operation);
}
