from flask import Flask, request, jsonify
import redis

app = Flask(__name__)
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)

@app.route('/register', methods=['POST'])
def register_service():
    service_id = request.json['service_id']
    instances = request.json.get('instances', [])

    for instance in instances:
        key = f'service:{service_id}:{instance}'
        redis_client.set(key, 'up')

    return jsonify({'message': 'Service registered successfully'}), 200

@app.route('/deregister/<service_id>', methods=['POST'])
def deregister_service(service_id):
    instances = request.json.get('instances', [])

    for instance in instances:
        key = f'service:{service_id}:{instance}'
        redis_client.delete(key)

    return jsonify({'message': 'Service deregistered successfully'}), 200

@app.route('/health/<service_id>', methods=['GET'])
def check_service_health(service_id):
    instances = request.args.getlist('instances[]')
    healthy_instances = []

    for instance in instances:
        key = f'service:{service_id}:{instance}'
        status = redis_client.get(key)
        if status and status.decode('utf-8') == 'up':
            healthy_instances.append(instance)

    return jsonify({'healthy_instances': healthy_instances}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

