void StreamingMediaProcessor::addSegment(const StreamSegment& segment) {
    std::lock_guard<std::mutex> lock(mutex);
    segmentsQueue.push(segment);
    segmentMap[segment.segment_id] = &segmentsQueue.back();
}

bool StreamingMediaProcessor::removeSegment(int segment_id) {
    std::lock_guard<std::mutex> lock(mutex);
    if (segmentMap.find(segment_id) == segmentMap.end()) return false;
    segmentsQueue.erase(std::find_if(segmentsQueue.begin(), segmentsQueue.end(),
                                     [segment_id](const StreamSegment& s) { return s.segment_id == segment_id; }));
    segmentMap.erase(segment_id);
    return true;
}

