#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024
#define BUFFER_SIZE 1048576 // 1 MB

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} IntArray;

void init_int_array(IntArray *arr) {
    arr->data = NULL;
    arr->size = 0;
    arr->capacity = 0;
}

void free_int_array(IntArray *arr) {
    free(arr->data);
    arr->data = NULL;
    arr->size = arr->capacity = 0;
}

int grow_int_array(IntArray *arr, size_t new_capacity) {
    int *new_data = realloc(arr->data, new_capacity * sizeof(int));
    if (new_data == NULL) {
        return -1; // Memory allocation failed
    }
    arr->data = new_data;
    arr->capacity = new_capacity;
    return 0;
}

int process_line(const char *line, IntArray *arr) {
    char *token = strtok((char *)line, " ");
    while (token != NULL) {
        long num = strtol(token, NULL, 10);
        if ((num == LONG_MAX || num == LONG_MIN) && errno == ERANGE) {
            return -1; // Invalid integer
        }
        if (arr->size >= arr->capacity) {
            if (grow_int_array(arr, arr->capacity ? arr->capacity * 2 : 4) != 0) {
                return -1; // Memory allocation failed
            }
        }
        arr->data[arr->size++] = (int)num;
        token = strtok(NULL, " ");
    }
    return 0;
}

void *process_file_thread(void *arg) {
    const char *filename = (const char *)arg;
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return NULL;
    }

    IntArray arr;
    init_int_array(&arr);

    char buffer[BUFFER_SIZE];
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, file)) > 0) {
        for (size_t i = 0; i < bytes_read; ) {
            size_t line_end = i + strcspn(buffer + i, "\n");
            if (line_end == i) {
                break;
            }
            buffer[line_end] = '\0';
            if (process_line(buffer + i, &arr) != 0) {
                printf("Invalid input detected\n");
            }
            i = line_end + 1;
        }
    }

    if (feof(file)) {
        fclose(file);
        pthread_exit((void *)&arr);
    } else {
        fclose(file);
        return NULL;
    }
}

void find_and_print_max(IntArray *arr) {
    if (arr->size == 0) {
        printf("No integers provided.\n");
        return;
    }

    int max_value = arr->data[0];
    for (size_t i = 1; i < arr->size; i++) {
        if (arr->data[i] > max_value) {
            max_value = arr->data[i];
        }
    }

    printf("Maximum value: %d\n", max_value);
    printf("Occurrences:");
    for (size_t i = 0; i < arr->size; i++) {
        if (arr->data[i] == max_value) {
            printf(" %zu", i + 1);
        }
    }
    printf("\n");
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, process_file_thread, argv[1]) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    IntArray *result_arr = (IntArray *)pthread_join(thread_id, NULL);
    if (result_arr != NULL) {
        find_and_print_max(result_arr);
        free_int_array(result_arr);
    } else {
        printf("Thread execution failed.\n");
    }

    return 0;
}
