#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct UserSession {
    int session_id;
    char user_name[256];
    time_t session_start_time;
    time_t last_activity_time;
    struct UserSession *next;
} UserSession;

typedef struct SessionManager {
    UserSession *head;
    int max_sessions_per_user;
} SessionManager;

void init_session_manager(SessionManager *manager, int max_sessions_per_user) {
    manager->head = NULL;
    manager->max_sessions_per_user = max_sessions_per_user;
}

UserSession* create_session(int session_id, const char *user_name) {
    UserSession *session = (UserSession *)malloc(sizeof(UserSession));
    if (session == NULL) return NULL;

    session->session_id = session_id;
    strcpy(session->user_name, user_name);
    session->session_start_time = time(NULL);
    session->last_activity_time = session->session_start_time;
    session->next = NULL;

    return session;
}

void add_session(SessionManager *manager, int session_id, const char *user_name) {
    if (is_user_overloaded(manager, user_name)) {
        // Handle session limit exceeded
        return;
    }

    UserSession *new_session = create_session(session_id, user_name);
    if (new_session == NULL) return;

    new_session->next = manager->head;
    manager->head = new_session;
}

void remove_session(SessionManager *manager, int session_id) {
    UserSession **current = &manager->head;
    while (*current != NULL) {
        if ((*current)->session_id == session_id) {
            UserSession *temp = *current;
            *current = (*current)->next;
            free(temp);
            return;
        }
        current = &(*current)->next;
    }
}

int get_active_sessions_count(SessionManager *manager) {
    int count = 0;
    UserSession *current = manager->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count;
}

void expire_inactive_sessions(SessionManager *manager, time_t timeout, void (*notify_user)(const char *)) {
    time_t now = time(NULL);
    UserSession **current = &manager->head;
    while (*current != NULL) {
        if (now - (*current)->last_activity_time > timeout) {
            notify_user((*current)->user_name);
            UserSession *temp = *current;
            *current = (*current)->next;
            free(temp);
        } else {
            current = &(*current)->next;
        }
    }
}

int is_user_overloaded(SessionManager *manager, const char *user_name) {
    int count = 0;
    UserSession *current = manager->head;
    while (current != NULL) {
        if (strcmp(current->user_name, user_name) == 0) {
            count++;
        }
        if (count >= manager->max_sessions_per_user) return 1;
        current = current->next;
    }
    return 0;
}

void notify_user(const char *user_name) {
    // Implement notification logic here
    printf("Session expired for user: %s\n", user_name);
}
