struct LogEntry {
    int log_id;
    std::string timestamp;
    std::string message;
    std::string severity_level;
};

class LogCollection {
public:
    void addLog(const LogEntry& entry);
    bool updateLog(int log_id, const LogEntry& updatedEntry);
    LogEntry getLog(int log_id) const;
    int getTotalLogs() const;

private:
    std::vector<LogEntry> logs;
    std::unordered_map<int, size_t> idToIndexMap;
    mutable std::mutex mutex_;
};

void LogCollection::addLog(const LogEntry& entry) {
    std::lock_guard<std::mutex> lock(mutex_);
    logs.push_back(entry);
    idToIndexMap[entry.log_id] = logs.size() - 1;
}

bool LogCollection::updateLog(int log_id, const LogEntry& updatedEntry) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (idToIndexMap.find(log_id) != idToIndexMap.end()) {
        size_t index = idToIndexMap[log_id];
        logs[index] = updatedEntry;
        return true;
    }
    return false;
}

LogEntry LogCollection::getLog(int log_id) const {
    std::lock_guard<std::mutex> lock(mutex_);
    if (idToIndexMap.find(log_id) != idToIndexMap.end()) {
        size_t index = idToIndexMap[log_id];
        return logs[index];
    }
    throw std::runtime_error("Log entry not found");
}

int LogCollection::getTotalLogs() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return logs.size();
}
