    int count;
    int capacity;
    pthread_mutex_t lock;
} SessionList;

void init_session_list(SessionList *list, int initial_capacity) {
    list->sessions = malloc(initial_capacity * sizeof(UserSession));
    if (!list->sessions) exit(1);
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
}

void add_session(SessionList *list, UserSession session) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        int new_capacity = list->capacity * 2;
        list->sessions = realloc(list->sessions, new_capacity * sizeof(UserSession));
        if (!list->sessions) exit(1);
        list->capacity = new_capacity;
    }
    memcpy(&list->sessions[list->count], &session, sizeof(UserSession));
    pthread_mutex_unlock(&list->lock);
}

void remove_session(SessionList *list, int session_id) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->sessions[i].session_id == session_id) {
            memmove(&list->sessions[i], &list->sessions[i + 1], (list->count - i - 1) * sizeof(UserSession));
            list->count--;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

int get_session_count(SessionList *list) {
    return list->count;
}

void sort_sessions_by_activity_time(SessionList *list) {
    pthread_mutex_lock(&list->lock);
    qsort(list->sessions, list->count, sizeof(UserSession), compare_last_activity_time);
    pthread_mutex_unlock(&list->lock);
}

int compare_last_activity_time(const void *a, const void *b) {
    UserSession *session_a = (UserSession *)a;
    UserSession *session_b = (UserSession *)b;
