#include <iostream>
#include <unordered_map>
#include <list>
#include <fstream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

enum class Status { active, inactive, expired };

struct DataPacket {
    int packet_id;
    std::chrono::system_clock::time_point timestamp;
    size_t payload_size;
    Status status;

    bool operator==(const DataPacket& other) const {
        return packet_id == other.packet_id;
    }
};

namespace std {
    template <>
    struct hash<DataPacket> {
        size_t operator()(const DataPacket& dp) const {
            return std::hash<int>()(dp.packet_id);
        }
    };
}

class PacketManager {
private:
    using PacketMap = std::unordered_map<DataPacket, DataPacket>;
    using PacketList = std::list<DataPacket>;
    PacketMap packetMap;
    PacketList packetList;
    std::mutex mutex;
    std::condition_variable cv;
    size_t maxSize;
    size_t currentSize;

public:
    PacketManager(size_t max_size) : maxSize(max_size), currentSize(0) {}

    void addPacket(const DataPacket& packet) {
        std::unique_lock<std::mutex> lock(mutex);
        if (currentSize >= maxSize) {
            cv.wait(lock, [this]() { return currentSize < maxSize; });
        }
        packetMap[packet] = packet;
        packetList.push_back(packet);
        ++currentSize;
    }

    bool removePacket(int packet_id) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = packetMap.find({packet_id, {}, 0, Status::active});
        if (it == packetMap.end()) return false;
        packetMap.erase(it);
        packetList.remove_if([packet_id](const DataPacket& dp) { return dp.packet_id == packet_id; });
        --currentSize;
        cv.notify_one();
        return true;
    }

    size_t getSize() const {
        std::lock_guard<std::mutex> lock(mutex);
        return currentSize;
    }

