} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PacketStorage;

void packet_storage_init(PacketStorage* storage, size_t initial_capacity) {
    storage->packets = malloc(initial_capacity * sizeof(DataPacket));
    storage->count = 0;
    storage->capacity = initial_capacity;
    pthread_mutex_init(&storage->lock, NULL);
}

void packet_storage_add(PacketStorage* storage, DataPacket packet) {
    pthread_mutex_lock(&storage->lock);
    if (storage->count >= storage->capacity) {
        size_t new_capacity = storage->capacity * 2;
        storage->packets = realloc(storage->packets, new_capacity * sizeof(DataPacket));
        storage->capacity = new_capacity;
    }
    storage->packets[storage->count++] = packet;
    pthread_mutex_unlock(&storage->lock);
}

// Add other functions as needed (remove, retrieve, sort, etc.)

void packet_storage_cleanup(PacketStorage* storage) {
    free(storage->packets);
    pthread_mutex_destroy(&storage->lock);
}
