using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

public class AsyncHttpService
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentQueue<HttpRequestInfo> _requestQueue;
    private readonly int _maxConcurrentRequests;
    private readonly int _rateLimit;
    private readonly int _retryAttempts;
    private readonly TimeSpan _timeout;
    private readonly ILogger _logger;

    public AsyncHttpService(HttpClient httpClient, int maxConcurrentRequests, int rateLimit, int retryAttempts, TimeSpan timeout, ILogger logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _requestQueue = new ConcurrentQueue<HttpRequestInfo>();
        _maxConcurrentRequests = maxConcurrentRequests;
        _rateLimit = rateLimit;
        _retryAttempts = retryAttempts;
        _timeout = timeout;
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public void EnqueueRequest(string url, string authCredentials, Configuration config)
    {
        _requestQueue.Enqueue(new HttpRequestInfo
        {
            Url = url,
            AuthCredentials = authCredentials,
            Config = config
        });
    }

    public async Task ProcessRequestsAsync()
    {
        while (_requestQueue.Any())
        {
            var taskList = new List<Task>();
            int concurrentCount = 0;

            while (concurrentCount < _maxConcurrentRequests && _requestQueue.TryDequeue(out var requestInfo))
            {
                var task = ProcessRequestAsync(requestInfo);
                taskList.Add(task);
                concurrentCount++;
            }

            await Task.WhenAll(taskList);

            // Simulate rate limiting
            await Task.Delay(_rateLimit);
        }
    }

    private async Task ProcessRequestAsync(HttpRequestInfo requestInfo)
    {
        for (int attempt = 0; attempt <= _retryAttempts; attempt++)
        {
            var stopwatch = Stopwatch.StartNew();
            try
            {
                using (var response = await _httpClient.GetAsync(requestInfo.Url, HttpCompletionOption.ResponseHeadersRead, _timeout))
                {
                    if (!response.IsSuccessStatusCode)
                    {
                        throw new HttpRequestException($"Request failed with status code: {response.StatusCode}");
                    }

                    var content = await response.Content.ReadAsStringAsync();
                    // Process the response content
                    _logger.LogInformation($"Request successful: {requestInfo.Url}, Retry count: {attempt}, Duration: {stopwatch.Elapsed.TotalMilliseconds} ms");
                }
                return;
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, $"Request failed: {requestInfo.Url}, Retry count: {attempt}");
                if (attempt == _retryAttempts)
                {
                    throw;
                }
                await Task.Delay(100 * attempt); // Exponential backoff
            }
        }
    }

    public class Configuration
    {
        // Define configuration properties here
    }

    public class HttpRequestInfo
    {
        public string Url { get; set; }
        public string AuthCredentials { get; set; }
        public Configuration Config { get; set; }
    }
}

// Example usage:
public class Program
{
    public static async Task Main(string[] args)
    {
        var httpClient = new HttpClient();
        var logger = new ConsoleLogger(); // Implement your own ILogger interface

        var service = new AsyncHttpService(httpClient, 10, 500, 3, TimeSpan.FromSeconds(10), logger);
        service.EnqueueRequest("https://api.example.com/data", "Bearer token", new Configuration { /* Configure settings */ });

        await service.ProcessRequestsAsync();
    }
}
