typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

Node* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->data.CRCFLAG = rand() % 2; // Randomly assign CRCFLAG
    new_node->next = NULL;
    new_node->prev = NULL;
    return new_node;
}

void insert_at_head(Node** head, Node* new_node) {
    if (*head != NULL) {
        (*head)->prev = new_node;
    }
    new_node->next = *head;
    *head = new_node;
}

int find_largest_integer(Node* head) {
    int max_value = INT_MIN;
    while (head != NULL) {
        if (head->data.RX_UE_INFORMATION_TAG > max_value) {
            max_value = head->data.RX_UE_INFORMATION_TAG;
        }
        head = head->next;
    }
    return max_value;
}

// Additional functions for error handling, thread safety, caching, sliding window,
// serialization/deserialization, logging, compression, and packet processing go here

