        if (new_node == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        insert_at_head(&head, new_node);
    }

    int largest = find_largest_integer(head);
    printf("Largest integer: %d\n", largest);

    // Clean up memory and other resources

    return 0;
}
