#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 1024
#define GRACE_PERIOD 3600 // 1 hour in seconds

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char source_ip[INET_ADDRSTRLEN];
    char destination_ip[INET_ADDRSTRLEN];
    unsigned char *payload;
} DataPacket;

typedef struct {
    DataPacket packets[MAX_PACKETS];
    int count;
    pthread_mutex_t lock;
} PacketManager;

void init_packet_manager(PacketManager *pm) {
    pm->count = 0;
    pthread_mutex_init(&pm->lock, NULL);
}

int add_packet(PacketManager *pm, DataPacket packet) {
    pthread_mutex_lock(&pm->lock);
    if (pm->count >= MAX_PACKETS) {
        pthread_mutex_unlock(&pm->lock);
        return -1; // Error: No space
    }
    pm->packets[pm->count++] = packet;
    pthread_mutex_unlock(&pm->lock);
    return 0; // Success
}

int remove_packet_by_id(PacketManager *pm, int packet_id) {
    pthread_mutex_lock(&pm->lock);
    for (int i = 0; i < pm->count; ++i) {
        if (pm->packets[i].packet_id == packet_id) {
            memmove(&pm->packets[i], &pm->packets[i + 1], sizeof(DataPacket) * (pm->count - i - 1));
            --pm->count;
            pthread_mutex_unlock(&pm->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&pm->lock);
    return -1; // Error: Packet not found
}

int get_packet_count(PacketManager *pm) {
    return pm->count;
}

void sort_packets_by_timestamp(PacketManager *pm) {
    pthread_mutex_lock(&pm->lock);
    for (int i = 0; i < pm->count - 1; ++i) {
        for (int j = i + 1; j < pm->count; ++j) {
            if (pm->packets[i].timestamp > pm->packets[j].timestamp) {
                DataPacket temp = pm->packets[i];
                pm->packets[i] = pm->packets[j];
                pm->packets[j] = temp;
            }
        }
    }
    pthread_mutex_unlock(&pm->lock);
}

void remove_old_packets(PacketManager *pm, time_t current_time) {
    pthread_mutex_lock(&pm->lock);
    for (int i = 0; i < pm->count; ++i) {
        if (current_time - pm->packets[i].timestamp > GRACE_PERIOD) {
            memmove(&pm->packets[i], &pm->packets[i + 1], sizeof(DataPacket) * (pm->count - i - 1));
            --pm->count;
            --i; // Adjust index after removal
        }
    }
    pthread_mutex_unlock(&pm->lock);
}

void log_operation(const char *operation, int packet_id) {
    // External logging service integration code here
}

void update_grace_period(int new_grace_period) {
    GRACE_PERIOD = new_grace_period;
}

void* periodic_check(void *arg) {
    PacketManager *pm = (PacketManager *)arg;
    time_t current_time;
    while (1) {
        sleep(60); // Check every minute
        time(&current_time);
        remove_old_packets(pm, current_time);
    }
    return NULL;
}

void* monitor_memory(void *arg) {
    PacketManager *pm = (PacketManager *)arg;
    // Memory usage monitoring and alert code here
    return NULL;
}
