#define MAX_EMAIL_LENGTH 100

typedef struct UserProfile {
    int user_id;
    char email[MAX_EMAIL_LENGTH];
    time_t registration_date;
    time_t last_login;
    int activity_points;
} UserProfile;

typedef struct DynamicArray {
    UserProfile* data;
    size_t count;
    size_t capacity;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->data = (UserProfile*)malloc(INITIAL_CAPACITY * sizeof(UserProfile));
    array->count = 0;
    array->capacity = INITIAL_CAPACITY;
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    free(array->data);
    free(array);
}

int add_profile(DynamicArray* array, UserProfile profile) {
    if (array->count >= array->capacity) {
        array->capacity *= 2;
        array->data = (UserProfile*)realloc(array->data, array->capacity * sizeof(UserProfile));
    }
    array->data[array->count++] = profile;
    return 0;
}

int update_profile(DynamicArray* array, int user_id, UserProfile new_profile) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->data[i].user_id == user_id) {
            array->data[i] = new_profile;
            return 0;
        }
    }
    return -1;
}

int get_active_profiles_count(DynamicArray* array, int min_activity_points) {
    int count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->data[i].activity_points >= min_activity_points) {
            ++count;
        }
    }
    return count;
}

int filter_profiles_by_registration_date(DynamicArray* array, time_t start_date, time_t end_date, UserProfile** filtered_profiles, size_t* filtered_count) {
    *filtered_count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->data[i].registration_date >= start_date && array->data[i].registration_date <= end_date) {
            (*filtered_profiles)[(*filtered_count)++] = array->data[i];
        }
    }
    return 0;
}

int main() {
    DynamicArray* users = create_dynamic_array();

    UserProfile user1 = {1, "user1@example.com", time(NULL), time(NULL), 150};
    add_profile(users, user1);

    UserProfile updated_user = {1, "user1@example.com", time(NULL), time(NULL) + 86400, 200};
    update_profile(users, 1, updated_user);

    int active_count = get_active_profiles_count(users, 100);
    printf("Active profiles with at least 100 points: %d\n", active_count);

    time_t start_date = time(NULL) - 31536000; // One year ago
    time_t end_date = time(NULL);
    UserProfile* filtered_users;
    size_t filtered_count;
    filter_profiles_by_registration_date(users, start_date, end_date, &filtered_users, &filtered_count);

    printf("Filtered profiles by registration date:\n");
    for (size_t i = 0; i < filtered_count; ++i) {
        printf("User ID: %d, Email: %s\n", filtered_users[i].user_id, filtered_users[i].email);
    }

    free(filtered_users);
    destroy_dynamic_array(users);

    return 0;
}
