import os
import gzip
from collections import defaultdict
from threading import Thread, Lock

# Custom logging mechanism
class CustomLogger:
    def __init__(self):
        self.log = defaultdict(int)

    def log_request(self, status):
        self.log['requests'] += 1
        if status == 'success':
            self.log['successful_requests'] += 1
        elif status == 'proxy_session_initiated':
            self.log['proxy_sessions'] += 1

    def log_error(self):
        self.log['errors'] += 1

    def get_logs(self):
        return dict(self.log)

# Hash table for NFAPI_SRB_RELEASE_REQUEST_PDU_T structures
class SRBHashTable:
    def __init__(self, size=1000, load_factor=0.75):
        self.size = size
        self.load_factor = load_factor
        self.table = [None] * self.size
        self.lock = Lock()

    def hash_function(self, srb_id):
        return hash(srb_id) % self.size

    def resize(self):
        new_size = self.size * 2
        new_table = [None] * new_size
        for entry in self.table:
            if entry is not None:
                new_index = self.hash_function(entry['SRB_ID'])
                while new_table[new_index] is not None:
                    new_index = (new_index + 1) % new_size
                new_table[new_index] = entry
        self.size = new_size
        self.table = new_table

    def insert(self, srb_id, srb_type, release_cause):
        with self.lock:
            if len([entry for entry in self.table if entry is not None]) / self.size > self.load_factor:
                self.resize()
            index = self.hash_function(srb_id)
            while self.table[index] is not None and self.table[index]['SRB_ID'] != srb_id:
                index = (index + 1) % self.size
            if self.table[index] is not None:
                raise ValueError("SRB_ID already exists")
            self.table[index] = {'SRB_ID': srb_id, 'SRB_TYPE': srb_type, 'Release_Cause': release_cause}

    def delete(self, srb_id):
        with self.lock:
            index = self.hash_function(srb_id)
            while self.table[index] is not None and self.table[index]['SRB_ID'] != srb_id:
                index = (index + 1) % self.size
            if self.table[index] is None:
                raise ValueError("SRB_ID not found")
            self.table[index] = None

    def iterate(self):
        for entry in self.table:
            if entry is not None:
                yield entry

# Main function to process log files and manage SRB hash table
def process_log_files(directory, keywords, timeout):
    logger = CustomLogger()
    srb_hash_table = SRBHashTable()

    def process_file(file_path):
        try:
            with gzip.open(file_path, 'rt') as file:
                for line in file:
                    if any(keyword in line for keyword in keywords):
                        # Process the line
                        logger.log_request('success')
                    else:
                        logger.log_request('proxy_session_initiated')
                # Simulate processing SRB structures
                srb_id = os.getpid() % 1000
                srb_type = 'example'
                release_cause = 'random_cause'
                srb_hash_table.insert(srb_id, srb_type, release_cause)
        except Exception as e:
            logger.log_error()
            print(f"Error processing file {file_path}: {e}")

    threads = []
    for filename in os.listdir(directory):
        if filename.endswith('.gz'):
            file_path = os.path.join(directory, filename)
            thread = Thread(target=process_file, args=(file_path,))
            threads.append(thread)
            thread.start()

    for thread in threads:
        thread.join()

    # Gracefully shut down connections after timeout
    import time
    start_time = time.time()
    while any(thread.is_alive() for thread in threads) and (time.time() - start_time < timeout):
        time.sleep(1)

    logger_logs = logger.get_logs()
    srb_entries = list(srb_hash_table.iterate())

    return logger_logs, srb_entries

# Example usage
directory_path = 'path_to_log_directory'
keywords_list = ['error', 'warning']
shutdown_timeout = 60  # in seconds
logs, srb_entries = process_log_files(directory_path, keywords_list, shutdown_timeout)
print("Logs:", logs)
print("SRB Entries:", srb_entries)
