public class ApiGateway {

    private CircuitBreaker circuitBreaker;
    private RateLimiter rateLimiter;
    private Retry retry;
    private Bulkhead bulkhead;

    public ApiGateway() {
        CircuitBreakerConfig circuitBreakerConfig = CircuitBreakerConfig.custom()
            .failureRateThreshold(50)
            .waitDurationInOpenState(Duration.ofSeconds(10))
            .build();
        this.circuitBreaker = CircuitBreakerRegistry.of(circuitBreakerConfig).circuitBreaker("serviceA");

        RateLimiterConfig rateLimiterConfig = RateLimiterConfig.custom()
            .limitForPeriod(10)
            .limitRefreshPeriod(Duration.ofSeconds(1))
            .timeoutDuration(Duration.ofMillis(500))
            .build();
        this.rateLimiter = RateLimiterRegistry.of(rateLimiterConfig).rateLimiter("serviceA");

        RetryConfig retryConfig = RetryConfig.custom()
            .maxAttempts(3)
            .waitDuration(Duration.ofSeconds(1))
            .build();
        this.retry = RetryRegistry.of(retryConfig).retry("serviceA");

        BulkheadConfig bulkheadConfig = BulkheadConfig.custom()
            .maxConcurrentCalls(10)
            .maxWaitDuration(Duration.ofMillis(500))
            .build();
        this.bulkhead = BulkheadRegistry.of(bulkheadConfig).bulkhead("serviceA");
    }

    public void handleRequest(String service, String path) {
        circuitBreaker.executeSupplier(() -> {
            rateLimiter.acquirePermission();
            retry.executeRunnable(() -> bulkhead.executeRunnable(() -> {
                // Call backend service here
            }));
        });
    }
}
