typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char source_ip[16];
    char destination_ip[16];
    void* payload;
} DataPacket;

typedef struct DFSStorage {
    DataPacket** packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DFSStorage;

DFSStorage* dfs_create() {
    DFSStorage* storage = malloc(sizeof(DFSStorage));
    storage->packets = NULL;
    storage->count = 0;
    storage->capacity = 0;
    pthread_mutex_init(&storage->lock, NULL);
    return storage;
}

void dfs_destroy(DFSStorage* storage) {
    for (size_t i = 0; i < storage->count; ++i) {
        free(storage->packets[i]->payload);
        free(storage->packets[i]);
    }
    free(storage->packets);
    pthread_mutex_destroy(&storage->lock);
    free(storage);
}

void dfs_add_packet(DFSStorage* storage, DataPacket* packet) {
    pthread_mutex_lock(&storage->lock);
    if (storage->count == storage->capacity) {
        size_t new_capacity = storage->capacity > 0 ? storage->capacity * 2 : 1;
        DataPacket** new_packets = realloc(storage->packets, new_capacity * sizeof(DataPacket*));
        if (!new_packets) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&storage->lock);
            return;
        }
        storage->packets = new_packets;
        storage->capacity = new_capacity;
    }
    storage->packets[storage->count++] = packet;
    pthread_mutex_unlock(&storage->lock);
}

void dfs_remove_packet(DFSStorage* storage, int packet_id) {
    pthread_mutex_lock(&storage->lock);
    for (size_t i = 0; i < storage->count; ++i) {
        if (storage->packets[i]->packet_id == packet_id) {
            free(storage->packets[i]->payload);
            free(storage->packets[i]);
            for (; i + 1 < storage->count; ++i) {
                storage->packets[i] = storage->packets[i + 1];
            }
            --storage->count;
            break;
        }
    }
    pthread_mutex_unlock(&storage->lock);
}

size_t dfs_get_packet_count(DFSStorage* storage) {
    return storage->count;
}

