using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading.Tasks;

public interface ICachingService
{
    Task<bool> TryPersistAsync(Dictionary<string, object> data);
}

public class CachingService : ICachingService
{
    private readonly ConcurrentDictionary<string, Dictionary<string, object>> _cache = new ConcurrentDictionary<string, Dictionary<string, object>>();

    public async Task<bool> TryPersistAsync(Dictionary<string, object> data)
    {
        return await Task.FromResult(_cache.TryAdd(data["key"].ToString(), data));
    }
}

public class JsonProcessor
{
    private readonly ICachingService _cachingService;

    public JsonProcessor(ICachingService cachingService)
    {
        _cachingService = cachingService;
    }

    public IAsyncEnumerable<Dictionary<string, object>> ProcessAndPersistJsonData(string jsonData)
    {
        try
        {
            var data = Newtonsoft.Json.JsonConvert.DeserializeObject<Dictionary<string, object>>(jsonData);
            yield return data;

            if (data != null && _cachingService != null)
            {
                await _cachingService.TryPersistAsync(data);
            }
        }
        catch (Exception ex)
        {
            // Log the exception
            Console.WriteLine($"Error processing JSON data: {ex.Message}");
        }
    }
}
