#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int user_id;
    time_t login_timestamp;
    char* ip_address;
    time_t expiration_time;
} UserSession;

int create_user_sessions(int session_count, UserSession** sessions, int* error_status, const char* filter_ip) {
    if (session_count <= 0 || !sessions || !error_status) {
        *error_status = -1; // Invalid parameters
        return 0;
    }

    *sessions = (UserSession*)malloc(session_count * sizeof(UserSession));
    if (!(*sessions)) {
        *error_status = -2; // Memory allocation failed
        return 0;
    }

    int successful_allocations = 0;
    for (int i = 0; i < session_count; ++i) {
        (*sessions)[i].user_id = i + 1;
        (*sessions)[i].login_timestamp = time(NULL);
        (*sessions)[i].ip_address = (char*)malloc(16 * sizeof(char)); // Assuming IPv4
        if (!(*sessions)[i].ip_address) {
            fprintf(stderr, "Failed to allocate memory for IP address of session %d\n", i + 1);
            continue;
        }
        snprintf((*sessions)[i].ip_address, 16, "%s", filter_ip ? filter_ip : "0.0.0.0");
        (*sessions)[i].expiration_time = (*sessions)[i].login_timestamp + 3600; // Default expiration time

        successful_allocations++;
    }

    *error_status = successful_allocations == session_count ? 1 : (successful_allocations > 0 ? 2 : -2);
    return successful_allocations;
}

void free_user_sessions(UserSession* sessions, int count) {
    if (!sessions || count <= 0) {
        return;
    }

    for (int i = 0; i < count; ++i) {
        free(sessions[i].ip_address);
    }
    free(sessions);
}
