        weights[i] = (double)(rand() % 100) / 10.0;

        printf("Record %d: Value=%d, Offset=%ld, Key=%d, Weight=%.2f\n", i, (*records)[i].value, offsets[i], keys[i], weights[i]);
    }

    (*success_count)++;
}

int main() {
    int num_records = 5;
    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));
    double *weights = (double *)malloc(num_records * sizeof(double));
    record *records = (record *)malloc(num_records * sizeof(record));
    int success_count = 0, failure_count = 0;

    if (offsets == NULL || keys == NULL || weights == NULL || records == NULL) {
        printf("Initial allocation failed.\n");
        return 1;
    }

    initialize_records(num_records, offsets, keys, weights, &records, &success_count, &failure_count);

    free(offsets);
    free(keys);
    free(weights);
    if (records != NULL) {
        free(records);
    }

    printf("Total Successful Allocations: %d\n", success_count);
    printf("Total Failures Due to Insufficient Memory: %d\n", failure_count);

