#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/ecdsa.h>
#include <openssl/sha.h>
#include <unistd.h>

#define MAX_KEYS 100

typedef struct {
    EC_KEY *private_key;
    EC_POINT *public_key;
    unsigned char iv[16];
} Key;

typedef struct {
    const EVP_CIPHER *cipher;
    const EVP_MD *digest;
    Key keys[MAX_KEYS];
    int num_keys;
} Config;

int initialize_library(const Config *config, int *error_status) {
    if (!config || !error_status) {
        *error_status = 1; // Invalid configuration
        return -1;
    }

    for (int i = 0; i < config->num_keys; i++) {
        Key *key = &config->keys[i];
        key->private_key = EC_KEY_new_by_curve_name(NID_X9_62_prime256v1);
        if (!key->private_key) {
            *error_status = 2; // Memory allocation failure
            return -1;
        }

        key->public_key = EC_POINT_new(EC_KEY_get0_group(key->private_key));
        if (!key->public_key) {
            *error_status = 3; // Memory allocation failure
            EC_KEY_free(key->private_key);
            return -1;
        }

        int res = EC_KEY_generate_key(key->private_key);
        if (!res) {
            *error_status = 4; // Key generation failed
            EC_POINT_free(key->public_key);
            EC_KEY_free(key->private_key);
            return -1;
        }

        memcpy(key->iv, "0123456789abcdef", 16);
    }

    *error_status = 0; // Success
    return 0;
}

void free_library(Config *config) {
    if (!config) {
        return;
    }

    for (int i = 0; i < config->num_keys; i++) {
        Key *key = &config->keys[i];
        EC_POINT_free(key->public_key);
        EC_KEY_free(key->private_key);
    }
}

int main() {
    Config config = {
        .cipher = EVP_aes_256_cbc(),
        .digest = EVP_sha256(),
        .num_keys = 1
    };

    int error_status;
    if (initialize_library(&config, &error_status) == -1) {
        printf("Error code: %d\n", error_status);
    } else {
        free_library(&config);
        printf("Library initialized successfully.\n");
    }

    return 0;
}
