import redis.clients.jedis.*;
import java.io.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;

@SpringBootApplication
public class DistributedCacheApplication {

    @Bean
    public JedisPool jedisPool() {
        return new JedisPool("localhost", 6379);
    }

    @Bean
    public ObjectMapper objectMapper() {
        return new ObjectMapper();
    }

    public static void main(String[] args) {
        SpringApplication.run(DistributedCacheApplication.class, args);
    }
}

@Service
public class CacheService {

    private final JedisPool jedisPool;
    private final ObjectMapper objectMapper;

    @Autowired
    public CacheService(JedisPool jedisPool, ObjectMapper objectMapper) {
        this.jedisPool = jedisPool;
        this.objectMapper = objectMapper;
    }

    public <T> void set(String key, T value, long expireTime) throws IOException {
        try (Jedis jedis = jedisPool.getResource()) {
            String serializedValue = objectMapper.writeValueAsString(value);
            jedis.setex(key.getBytes(), expireTime, serializedValue.getBytes());
        }
    }

    public <T> T get(String key, Class<T> valueType) throws IOException {
        try (Jedis jedis = jedisPool.getResource()) {
            byte[] serializedValue = jedis.get(key.getBytes());
            if (serializedValue != null) {
                return objectMapper.readValue(serializedValue, valueType);
            }
        }
        return null;
    }

    // Add methods for other data types and operations as required
}
```

