using System;
using UnityEngine;

public class AdvancedRandom
{
    private float minValue;
    private float maxValue;
    private long seed;

    public AdvancedRandom(float minValue = 0f, float maxValue = 1f, long seed = 0)
    {
        InitializeSeeds(seed);
        SetRange(minValue, maxValue);
    }

    public void SetRange(float minValue, float maxValue)
    {
        if (minValue > maxValue)
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
            Debug.LogWarning("Min value is greater than max value. Adjusting.");
        }
        else
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range((long)Math.Ceiling(minValue), (long)Math.Floor(maxValue) + 1);
    }

    public int GetExclusiveRandomInt()
    {
        if (minValue + 1 < maxValue)
        {
            return (int)UnityEngine.Random.Range((long)Math.Ceiling(minValue + 1), (long)Math.Floor(maxValue));
        }
        else
        {
            Debug.LogWarning("Invalid range for exclusive random integer generation.");
            return -1;
        }
    }

    public Vector3 GetRandomVector3()
    {
        float x = UnityEngine.Random.Range(minValue, maxValue);
        float y = UnityEngine.Random.Range(minValue, maxValue);
        float z = UnityEngine.Random.Range(minValue, maxValue);

        if (maxValue <= 0)
        {
            // Handle negative or zero maxValue
            x = -x;
            y = -y;
            z = -z;
        }

        return new Vector3(x, y, z);
    }

    public static void InitializeSeeds(long seed)
    {
        UnityEngine.Random.InitState((int)seed);
    }

    public int GetRandomWeightedInt(int[] weights)
    {
        if (weights == null || weights.Length == 0)
        {
            Debug.LogError("Weights array is empty.");
            throw new ArgumentException("Weights array cannot be empty.");
        }

        float totalWeight = Array.Sum(weights);

        if (!totalWeight.Equals(1.0f))
        {
            Debug.LogError("Sum of weights does not equal 1.0.");
            throw new InvalidOperationException("Sum of weights must equal 1.0 for weighted random selection.");
        }

        float randomValue = UnityEngine.Random.value;
        float cumulativeWeight = 0.0f;

        for (int i = 0; i < weights.Length; i++)
        {
            cumulativeWeight += weights[i];
            if (randomValue <= cumulativeWeight)
                return i;
        }

        Debug.LogError("Failed to select a weighted integer.");
        return -1;
    }

    public override string ToString()
    {
        return $"AdvancedRandom with range [{minValue}, {maxValue}]";
    }
}
