using System;
using System.Collections.Generic;
using System.Linq;

public enum DistributionType
{
    Uniform,
    Normal
}

public class CustomRandom
{
    private double min;
    private double max;
    private DistributionType distributionType;
    private List<double> lastGeneratedValues = new List<double>();

    public CustomRandom(double min, double max, DistributionType distributionType)
    {
        if (min >= max)
        {
            throw new ArgumentException("Min must be less than Max");
        }
        this.min = min;
        this.max = max;
        this.distributionType = distributionType;
    }

    public double GenerateValue()
    {
        switch (distributionType)
        {
            case DistributionType.Uniform:
                return GenerateUniformRandom();
            case DistributionType.Normal:
                return GenerateNormalRandom();
            default:
                throw new ArgumentException("Unsupported distribution type");
        }
    }

    private double GenerateUniformRandom()
    {
        Random rand = new Random();
        return min + (max - min) * rand.NextDouble();
    }

    private double GenerateNormalRandom()
    {
        // Use Box-Muller transform to generate a normally distributed random number
        Random rand = new Random();
        double u1 = rand.NextDouble();
        double u2 = rand.NextDouble();
        double z0 = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Cos(2.0 * Math.PI * u2);
        return min + (max - min) * (z0 / 3); // Adjusting for the mean and standard deviation
    }

    public List<double> Sample(int count)
    {
        if (count <= 0)
        {
            throw new ArgumentException("Count must be greater than zero");
        }
        List<double> samples = new List<double>();
        for (int i = 0; i < count; i++)
        {
            samples.Add(GenerateValue());
        }
        lastGeneratedValues = samples;
        return samples;
    }

    public override string ToString()
    {
        string distributionSummary = distributionType == DistributionType.Normal ? $"Normal Distribution" : "Uniform Distribution";
        if (lastGeneratedValues.Count > 0)
        {
            distributionSummary += $"\nLast Generated Values: {string.Join(", ", lastGeneratedValues)}";
        }
        return $"Range: [{min}, {max}], {distributionSummary}";
    }
}
