using System;
using System.Collections.Generic;
using System.IO;

public enum DistributionType { Uniform, Normal }

public class CustomRandom
{
    private int minValue;
    private int maxValue;
    private DistributionType distributionType;
    private string fileContent;

    public CustomRandom(int minValue, int maxValue, DistributionType distributionType)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Min value must be less than max value.");

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.distributionType = distributionType;
    }

    public string ReadFileContents(string filePath)
    {
        try
        {
            fileContent = File.ReadAllText(filePath);
            return fileContent;
        }
        catch (FileNotFoundException)
        {
            throw new FileNotFoundException("The specified file was not found.");
        }
        catch (IOException ex)
        {
            throw new IOException("An error occurred while reading the file.", ex);
        }
    }

    public List<int> SampleRandomValues(int count)
    {
        Random random = new Random();
        List<int> samples = new List<int>();

        for (int i = 0; i < count; i++)
        {
            if (distributionType == DistributionType.Normal)
            {
                // Generate normally distributed values
                double mu = (minValue + maxValue) / 2.0;
                double sigma = (maxValue - minValue) / 6.0;
                int value = Convert.ToInt32(mu + sigma * random.NextDouble() * Math.Sqrt(-2.0 * Math.Log(random.NextDouble())));
                samples.Add(value);
            }
            else
            {
                // Generate uniformly distributed values
                samples.Add(random.Next(minValue, maxValue));
            }
        }

        return samples;
    }

    public override string ToString()
    {
        return $"Range: {minValue}-{maxValue}, Distribution: {distributionType}, File Content: {fileContent}";
    }
}
