using System;
using System.Collections.Generic;
using System.IO;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

public class FileDataProcessor
{
    private string filePath;
    private string fileContent;
    private List<string> processedData;
    private string lastSummary;

    public FileDataProcessor(string filePath)
    {
        this.filePath = filePath;
        this.fileContent = string.Empty;
        this.processedData = new List<string>();
        this.lastSummary = string.Empty;
    }

    public async Task ReadFileAsync()
    {
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException("The file does not exist at the specified path.");
        }

        try
        {
            using (StreamReader reader = File.OpenText(filePath))
            {
                fileContent = await reader.ReadToEndAsync();
            }
        }
        catch (IOException ex)
        {
            throw new IOException("An error occurred while reading the file.", ex);
        }
    }

    public void ReadFileSync()
    {
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException("The file does not exist at the specified path.");
        }

        try
        {
            fileContent = File.ReadAllText(filePath);
        }
        catch (IOException ex)
        {
            throw new IOException("An error occurred while reading the file.", ex);
        }
    }

    public List<string> ProcessData(Func<string, bool> filterCriteria)
    {
        processedData.Clear();
        foreach (string line in fileContent.Split(new[] { '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries))
        {
            if (filterCriteria(line))
            {
                processedData.Add(line);
            }
        }

        lastSummary = $"Processed {processedData.Count} records.";
        return processedData;
    }

    public List<string> SampleRecords(int numberOfRecords)
    {
        Random random = new Random();
        int sampleSize = Math.Min(numberOfRecords, processedData.Count);
        List<string> sampledData = new List<string>(sampleSize);

        for (int i = 0; i < sampleSize; i++)
        {
            int index = random.Next(processedData.Count);
            sampledData.Add(processedData[index]);
        }

        return sampledData;
    }

    public override string ToString()
    {
        return $"File Path: {filePath}, File Content Length: {fileContent.Length}, Processed Data Count: {processedData.Count}, Last Summary: {lastSummary}";
    }
}
