using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

public class FileDataProcessor
{
    private string filePath;
    private string fileContent;
    private List<string> processedData;
    private string summary;

    public FileDataProcessor(string filePath)
    {
        this.filePath = filePath;
        this.fileContent = string.Empty;
        this.processedData = new List<string>();
        this.summary = string.Empty;
    }

    // Asynchronous method to read file content
    public async Task ReadFileAsync()
    {
        try
        {
            if (!File.Exists(filePath))
            {
                throw new FileNotFoundException("File does not exist", filePath);
            }
            fileContent = await File.ReadAllTextAsync(filePath);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error reading file: {ex.Message}");
        }
    }

    // Synchronous method to read file content
    public void ReadFileSync()
    {
        try
        {
            if (!File.Exists(filePath))
            {
                throw new FileNotFoundException("File does not exist", filePath);
            }
            fileContent = File.ReadAllText(filePath);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error reading file: {ex.Message}");
        }
    }

    // Method to parse file content into structured format
    public void ParseData()
    {
        processedData = Regex.Split(fileContent, @"\r\n|\n").ToList();
    }

    // Method to filter data based on custom criteria
    public List<string> FilterData(Func<string, bool> predicate)
    {
        return processedData.Where(predicate).ToList();
    }

    // Method to sample a fixed number of records from the processed data
    public void SampleData(int count)
    {
        if (count > processedData.Count)
        {
            throw new ArgumentException("Sample size exceeds the available data");
        }
        processedData = processedData.OrderBy(x => Guid.NewGuid()).Take(count).ToList();
    }

    // Override ToString method to display relevant information
    public override string ToString()
    {
        return $"File Path: {filePath}, File Content Length: {fileContent.Length}, Processed Data Count: {processedData.Count}, Summary: {summary}";
    }
}
