public class StreamingDataProcessor {
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);

    public void processStream(String sourceId, StreamConsumer consumer) {
        executorService.submit(() -> {
            try {
                // Simulate data ingestion and processing
                while (true) {
                    String data = consumeFromSource(sourceId);
                    if (data == null) break; // End of stream
                    consumer.accept(data);
                }
            } catch (Exception e) {
                System.err.println("Error processing stream from " + sourceId + ": " + e.getMessage());
                handleFailure(sourceId, e);
            }
        });
    }

    private String consumeFromSource(String sourceId) {
        // Simulate data consumption
        return "Data for " + sourceId;
    }

    private void handleFailure(String sourceId, Exception e) {
        // Implement failure handling logic here
    }

    public interface StreamConsumer extends Consumer<String> {
        @Override
        default void accept(String data) {
            try {
                process(data);
            } catch (Exception e) {
                System.err.println("Error processing data: " + e.getMessage());
            }
        }

        void process(String data) throws Exception;
    }

    public static void main(String[] args) {
        StreamingDataProcessor processor = new StreamingDataProcessor();
        processor.processStream("source1", data -> {
            // Process data
        });
        processor.processStream("source2", data -> {
            // Process data
        });

        // Shutdown executor service gracefully
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            try {
                processor.executorService.shutdown();
                if (!processor.executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                    processor.executorService.shutdownNow();
                }
            } catch (InterruptedException e) {
                processor.executorService.shutdownNow();
            }
        }));
    }
}
