public class RandomValueGenerator
{
    private Random _random;
    private float _minValue;
    private float _maxValue;

    public RandomValueGenerator(float minValue, float maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Invalid range. Min value must be less than max value.");

        _minValue = minValue;
        _maxValue = maxValue;
        _random = new Random();
    }

    public void SeedRandom(int seed)
    {
        _random = new Random(seed);
    }

    public float GenerateRandomFloat(float frequency = 1f)
    {
        return (float)(_random.NextDouble() * (frequency * (_maxValue - _minValue) + _minValue));
    }

    public int GenerateRandomInt(int frequency = 1)
    {
        return (int)(GenerateRandomFloat(frequency));
    }

    public float CalculateMean(List<float> values)
    {
        if (values == null || !values.Any())
            throw new ArgumentException("Sample size for mean calculation is insufficient.");

        return values.Average();
    }

    public float CalculateVariance(List<float> values, float mean)
    {
        if (values == null || !values.Any())
            throw new ArgumentException("Sample size for variance calculation is insufficient.");

        float sumOfSquares = values.Sum(value => (value - mean) * (value - mean));
        return sumOfSquares / values.Count;
    }

    public float CalculateStandardDeviation(float variance)
    {
        if (variance < 0)
            throw new ArgumentException("Variance cannot be negative.");

        return (float)Math.Sqrt(variance);
    }

    public void GenerateHistogram(List<float> values, string outputPath)
    {
        Bitmap bitmap = new Bitmap(800, 600);
        Graphics graphics = Graphics.FromImage(bitmap);

        // Draw histogram logic here

        bitmap.Save(outputPath);
    }
