        return CR_FILE_READ_ERROR;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *content = malloc(size + 1);
    if (*content == NULL) {
        fclose(file);
        return CR_MEMORY_FAILURE;
    }

    fread(*content, sizeof(char), size, file);
    fclose(file);
    (*content)[size] = '\0';

