    newNode->message = strdup(message);
    newNode->id = id;
    newNode->next = NULL;

    if (queue->head == NULL) {
        queue->head = newNode;
    } else {
        MessageQueueNode* current = queue->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&queue->lock);
}

int removeMessageFromQueue(MessageQueue* queue, int id) {
    pthread_mutex_lock(&queue->lock);

    MessageQueueNode* current = queue->head;
    MessageQueueNode* previous = NULL;

    while (current != NULL) {
        if (current->id == id) {
            if (previous == NULL) {
                queue->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current->message);
            free(current);
            pthread_mutex_unlock(&queue->lock);
            return 0; // Message removed successfully
        }
        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&queue->lock);
    return -1; // Message not found
}

int getMessageQueueSize(MessageQueue* queue) {
    int size = 0;
    pthread_mutex_lock(&queue->lock);

    MessageQueueNode* current = queue->head;
    while (current != NULL) {
        size++;
        current = current->next;
    }

    pthread_mutex_unlock(&queue->lock);
    return size;
}
