#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <fstream>
#include <sstream>
#include <queue>
#include <unordered_map>
#include <chrono>

class RealTimeDataAggregator {
public:
    struct DataPacket {
        int sensor_id;
        std::time_t timestamp;
        double latitude;
        double longitude;
        double temperature;
    };

    void addData(const DataPacket& packet);
    std::vector<DataPacket> filterByGeographicalBounds(double minLat, double maxLat, double minLon, double maxLon);
    std::vector<DataPacket> filterByTemperatureThreshold(double minTemp, double maxTemp);
    void setTemperatureThreshold(double threshold);
    double getRollingAverageTemperature(std::chrono::seconds window);
    bool detectAnomalies();
    void reportHealthStatus();
    void exportToCSV(const std::string& filename);
    DataPacket getNextDataPacket();
    void prioritizeData(int sensor_id, int priority);

private:
    std::queue<DataPacket> dataQueue;
    std::mutex queueMutex;
    std::condition_variable dataCondVar;
    double temperatureThreshold = 25.0;
    double rollingAverageTemperature = 0.0;
    std::chrono::time_point<std::chrono::steady_clock> lastRollingAvgTime;
    std::unordered_map<int, int> sensorPriorities;

    void processData();
};

void RealTimeDataAggregator::addData(const DataPacket& packet) {
    std::lock_guard<std::mutex> lock(queueMutex);
    dataQueue.push(packet);
    dataCondVar.notify_one();
}

std::vector<RealTimeDataAggregator::DataPacket> RealTimeDataAggregator::filterByGeographicalBounds(double minLat, double maxLat, double minLon, double maxLon) {
    std::vector<DataPacket> filteredData;
    std::lock_guard<std::mutex> lock(queueMutex);
    for (const auto& packet : dataQueue) {
        if (packet.latitude >= minLat && packet.latitude <= maxLat &&
            packet.longitude >= minLon && packet.longitude <= maxLon) {
            filteredData.push_back(packet);
        }
    }
    return filteredData;
}

std::vector<RealTimeDataAggregator::DataPacket> RealTimeDataAggregator::filterByTemperatureThreshold(double minTemp, double maxTemp) {
    std::vector<DataPacket> filteredData;
    std::lock_guard<std::mutex> lock(queueMutex);
    for (const auto& packet : dataQueue) {
        if (packet.temperature >= minTemp && packet.temperature <= maxTemp) {
            filteredData.push_back(packet);
        }
    }
    return filteredData;
}

void RealTimeDataAggregator::setTemperatureThreshold(double threshold) {
    temperatureThreshold = threshold;
}

double RealTimeDataAggregator::getRollingAverageTemperature(std::chrono::seconds window) {
    auto now = std::chrono::steady_clock::now();
    if (now - lastRollingAvgTime < window) {
        return rollingAverageTemperature;
    }
    // Calculate rolling average
    double sum = 0.0;
    int count = 0;
    std::lock_guard<std::mutex> lock(queueMutex);
    for (const auto& packet : dataQueue) {
        if (now - std::chrono::system_clock::from_time_t(packet.timestamp) < window) {
            sum += packet.temperature;
            ++count;
        }
    }
    rollingAverageTemperature = count > 0 ? sum / count : 0.0;
    lastRollingAvgTime = now;
    return rollingAverageTemperature;
}

bool RealTimeDataAggregator::detectAnomalies() {
    double avgTemp = getRollingAverageTemperature(std::chrono::seconds(60));
    std::lock_guard<std::mutex> lock(queueMutex);
    for (const auto& packet : dataQueue) {
        if (std::abs(packet.temperature - avgTemp) > temperatureThreshold * 2.0) {
            return true;
        }
    }
    return false;
}

void RealTimeDataAggregator::reportHealthStatus() {
    std::cout << "Current Data Ingestion Rate: " << dataQueue.size() << "/s" << std::endl;
    // Add more health metrics here
}

void RealTimeDataAggregator::exportToCSV(const std::string& filename) {
    try {
        std::ofstream file(filename);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file for writing");
        }
        std::lock_guard<std::mutex> lock(queueMutex);
        for (const auto& packet : dataQueue) {
            file << packet.sensor_id << "," << packet.timestamp << "," << packet.latitude << "," << packet.longitude << "," << packet.temperature << "\n";
        }
    } catch (const std::exception& e) {
        std::cerr << "Error exporting to CSV: " << e.what() << std::endl;
    }
}

RealTimeDataAggregator::DataPacket RealTimeDataAggregator::getNextDataPacket() {
    std::unique_lock<std::mutex> lock(queueMutex);
    dataCondVar.wait(lock, [this]{ return !dataQueue.empty(); });
    DataPacket packet = dataQueue.front();
    dataQueue.pop();
    return packet;
}

void RealTimeDataAggregator::prioritizeData(int sensor_id, int priority) {
    std::lock_guard<std::mutex> lock(queueMutex);
    sensorPriorities[sensor_id] = priority;
}
```']

