void initLogList(LogList* list) {
    list->entries = NULL;
    list->count = 0;
    list->capacity = 0;
}

void addLog(LogList* list, LogEntry* entry) {
    if (list->count >= list->capacity) {
        list->capacity += 10;
        list->entries = realloc(list->entries, list->capacity * sizeof(LogEntry*));
    }
    list->entries[list->count++] = entry;
}

