    for (int i = 0; i < list->count; ) {
        if (list->entries[i]->severity < minSeverity) {
            free(list->entries[i]);
            for (int j = i; j < list->count - 1; j++) {
                list->entries[j] = list->entries[j + 1];
            }
            list->count--;
        } else {
            i++;
