    if (*str == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void free_string(char** str) {
    if (*str != NULL) {
        free(*str);
        *str = NULL;
    }
}

int compare_records(const void* a, const void* b) {
    return ((record*)a)->value - ((record*)b)->value;
}

void initializeWorld(const char* config_file, long** offset_values, int** keys, record** records,
                     size_t* num_records, int* tile_size, int* world_width, int* world_height, double* camera_speed) {
    // Load configuration settings from XML file
    FILE* fp = fopen(config_file, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open config file: %s\n", config_file);
        exit(EXIT_FAILURE);
    }

    // Parse XML and populate variables
    // ...

    // Validate configuration settings
    // ...

    // Allocate memory for arrays
    *offset_values = (long*)malloc(*num_records * sizeof(long));
    *keys = (int*)malloc(*num_records * sizeof(int));
    *records = (record*)malloc(*num_records * sizeof(record));

    if (*offset_values == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize records
    srand(time(NULL));
    for (size_t i = 0; i < *num_records; ++i) {
        (*offset_values)[i] = rand() % 1000;
        (*keys)[i] = rand() % 100;
        init_string(&(*records)[i].metadata);

        // Set other fields of record structure
        // ...
    }

    // Sort records by int field
    qsort(*records, *num_records, sizeof(record), compare_records);

    // Free dynamically allocated memory
    for (size_t i = 0; i < *num_records; ++i) {
        free_string(&(*records)[i].metadata);
    }
    free(*offset_values);
    free(*keys);
    free(*records);
}
