#define MAX_NAME_LENGTH 100
#define MAX_EMAIL_LENGTH 256

typedef struct UserProfile {
    char name[MAX_NAME_LENGTH];
    char email[MAX_EMAIL_LENGTH];
    int age;
    bool isMember;
    struct UserProfile *next;
} UserProfile;

bool isValidEmail(const char *email) {
    // Basic validation for an email format
    if (strchr(email, '@') == NULL || strchr(email, '.') == NULL) return false;
    return true;
}

bool isValidName(const char *name) {
    // Check if name is non-empty and contains only alphanumeric characters and spaces
    if (*name == '\0') return false;
    for (int i = 0; name[i] != '\0'; i++) {
        if (!isalnum(name[i]) && name[i] != ' ') return false;
    }
    return true;
}

UserProfile* createUserProfile(const char *name, const char *email, int age) {
    if (!isValidName(name) || !isValidEmail(email)) {
        fprintf(stderr, "Invalid user profile data.\n");
        return NULL;
    }

    UserProfile *user = (UserProfile *)malloc(sizeof(UserProfile));
    if (user == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }
    strcpy(user->name, name);
    strcpy(user->email, email);
    user->age = age;
    user->isMember = false;
    user->next = NULL;

    return user;
}

void addUserProfile(UserProfile **head, UserProfile *user) {
    if (*head == NULL) {
        *head = user;
    } else {
        UserProfile *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = user;
    }
}

UserProfile* searchUserByEmail(UserProfile *head, const char *email) {
    UserProfile *current = head;
    while (current != NULL) {
        if (strcmp(current->email, email) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void updateUserMembershipByName(UserProfile **head, const char *name, bool isMember) {
    UserProfile *user = head;
    while (user != NULL) {
        if (strcmp(user->name, name) == 0) {
            user->isMember = isMember;
            break;
        }
        user = user->next;
    }
}

void sortUserProfilesByAge(UserProfile **head) {
    // Bubble sort for simplicity, not optimal for large datasets
    bool swapped;
    UserProfile *ptr1;
    UserProfile *lptr = NULL;

    if (*head == NULL || (*head)->next == NULL) return;

    do {
        swapped = false;
        ptr1 = *head;

        while (ptr1->next != lptr) {
            if (ptr1->age > ptr1->next->age) {
                // Swap the nodes
                UserProfile temp = *ptr1;
                *ptr1 = *ptr1->next;
                *ptr1->next = temp;
                swapped = true;
            }
            ptr1 = ptr1->next;
        }
        lptr = ptr1;
    } while (swapped);
}

void freeUserProfiles(UserProfile **head) {
    UserProfile *current = *head;
    UserProfile *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL;
}
