typedef struct UserSession {
    int session_id;
    char user_name[50];
    time_t session_start_time;
    time_t last_activity_time;
    struct UserSession* next;
} UserSession;

typedef struct SessionManager {
    UserSession* head;
    pthread_mutex_t mutex;
    int max_sessions_per_user;
    void (*expiry_callback)(int, const char*);
} SessionManager;

void init_session_manager(SessionManager* manager, int max_sessions_per_user, void (*expiry_callback)(int, const char*)) {
    manager->head = NULL;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->max_sessions_per_user = max_sessions_per_user;
    manager->expiry_callback = expiry_callback;
}

void add_session(SessionManager* manager, int session_id, const char* user_name, time_t start_time) {
    pthread_mutex_lock(&manager->mutex);
    UserSession* current = manager->head;
    while (current != NULL) {
        if (current->session_id == session_id) {
            current->last_activity_time = start_time;
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
        current = current->next;
    }

    if (get_user_session_count(manager, user_name) >= manager->max_sessions_per_user) {
        pthread_mutex_unlock(&manager->mutex);
        printf("User limit reached.\n");
        return;
    }

    UserSession* new_session = (UserSession*)malloc(sizeof(UserSession));
    new_session->session_id = session_id;
    strncpy(new_session->user_name, user_name, 49);
    new_session->session_start_time = start_time;
    new_session->last_activity_time = start_time;
    new_session->next = manager->head;
    manager->head = new_session;
    pthread_mutex_unlock(&manager->mutex);
}

void remove_session(SessionManager* manager, int session_id) {
    pthread_mutex_lock(&manager->mutex);
    UserSession* current = manager->head;
    UserSession* prev = NULL;

    while (current != NULL) {
        if (current->session_id == session_id) {
            if (prev == NULL) {
                manager->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->mutex);
}

int get_user_session_count(SessionManager* manager, const char* user_name) {
    int count = 0;
    pthread_mutex_lock(&manager->mutex);
    UserSession* current = manager->head;
    while (current != NULL) {
        if (strcmp(current->user_name, user_name) == 0) {
            count++;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->mutex);
    return count;
}

void expire_inactive_sessions(SessionManager* manager, time_t timeout) {
    pthread_mutex_lock(&manager->mutex);
    UserSession* current = manager->head;
    while (current != NULL) {
        if (time(NULL) - current->last_activity_time > timeout) {
            manager->expiry_callback(current->session_id, current->user_name);
            UserSession* to_remove = current;
            current = current->next;
            free(to_remove);
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

void session_expiry_notification(int session_id, const char* user_name) {
    // External notification code here
    printf("Session expired: %d, User: %s\n", session_id, user_name);
}
