class DynamicLogManager {
private:
    std::map<int, std::shared_ptr<LogEntry>> entries;
    std::mutex mutex;

public:
    void addEntry(int id, const LogEntry& entry) {
        std::lock_guard<std::mutex> lock(mutex);
        entries[id] = std::make_shared<LogEntry>(entry);
    }

    bool updateEntry(int id, const LogEntry& newEntry) {
        std::lock_guard<std::mutex> lock(mutex);
        if (entries.find(id) != entries.end()) {
            entries[id] = std::make_shared<LogEntry>(newEntry);
            return true;
        }
        return false;
    }

    std::shared_ptr<LogEntry> getEntry(int id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (entries.find(id) != entries.end()) {
            return entries[id];
        }
        return nullptr;
