@app.route('/register', methods=['POST'])
def register_service():
    data = request.json
    service_name = data['service_name']
    instance_id = data['instance_id']
    health_url = data['health_url']

    if service_name not in service_registry:
        service_registry[service_name] = []

    service_registry[service_name].append({'id': instance_id, 'status': 'UP', 'health_url': health_url})

    # Start health-check thread for this new service
    threading.Thread(target=monitor_service_health, args=(service_name, instance_id, health_url)).start()

    return jsonify({"message": "Service registered successfully"}), 201

# Route to deregister a service
@app.route('/deregister', methods=['POST'])
def deregister_service():
    data = request.json
    service_name = data['service_name']
    instance_id = data['instance_id']

    if service_name in service_registry:
        service_registry[service_name] = [s for s in service_registry[service_name] if s['id'] != instance_id]

        # Ensure all instances of this service are deregistered
        if not service_registry[service_name]:
