using UnityEngine;

public class HighPerformanceDataFilter
{
    private float minValue;
    private float maxValue;

    public HighPerformanceDataFilter(float min, float max)
    {
        minValue = min;
        maxValue = max;
    }

    public override string ToString()
    {
        return $"Range: {minValue} to {maxValue}";
    }

    // Method to generate random float within the specified range
    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    // Method to generate random integer within the specified range
    public int GenerateRandomInt(int min, int max)
    {
        return UnityEngine.Random.Range(min, max + 1);
    }

    // Method to categorize log entries based on HTTP status codes
    public Dictionary<string, List<string>> CategorizeLogEntries(List<string> logEntries)
    {
        Dictionary<string, List<string>> categories = new Dictionary<string, List<string>>();
        string[] successCodes = { "200", "201", "204" };
        string[] infoCodes = { "301", "302", "307" };
        string[] warningCodes = { "400", "401", "403" };
        string[] errorCodes = { "500", "502", "503" };

        foreach (var entry in logEntries)
        {
            string[] parts = entry.Split(' ');
            if (parts.Length > 8 && int.TryParse(parts[8], out int statusCode))
            {
                if (Array.Exists(successCodes, code => code == statusCode.ToString()))
                {
                    categories.TryGetValue("Success", out List<string> successList);
                    successList?.Add(entry);
                    categories["Success"] = successList ?? new List<string> { entry };
                }
                else if (Array.Exists(infoCodes, code => code == statusCode.ToString()))
                {
                    categories.TryGetValue("Informational", out List<string> infoList);
                    infoList?.Add(entry);
                    categories["Informational"] = infoList ?? new List<string> { entry };
                }
                else if (Array.Exists(warningCodes, code => code == statusCode.ToString()))
                {
                    categories.TryGetValue("Warning", out List<string> warningList);
                    warningList?.Add(entry);
                    categories["Warning"] = warningList ?? new List<string> { entry };
                }
                else if (Array.Exists(errorCodes, code => code == statusCode.ToString()))
                {
                    categories.TryGetValue("Error", out List<string> errorList);
                    errorList?.Add(entry);
                    categories["Error"] = errorList ?? new List<string> { entry };
                }
            }
        }

        return categories;
    }

    // Method to append a period to the end of a string if it does not exceed the size limit
    public string AppendPeriodIfWithinSize(string input, int sizeLimit)
    {
        if (input.Length <= sizeLimit)
        {
            return input + ".";
        }
        else
        {
            return "";
        }
    }
}
