using System;
using System.Threading;

public static class RandomValueGenerator
{
    private static readonly ThreadLocal<Random> _random = new ThreadLocal<Random>(() => new Random());

    public static int GenerateInt(int min, int max, bool inclusive)
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        }

        return inclusive ? _random.Value.Next(min, max + 1) : _random.Value.Next(min + 1, max);
    }

    public static float GenerateFloat(float min, float max, bool inclusive)
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        }

        return inclusive ? (float)_random.Value.NextDouble() * (max - min) + min : (float)(_random.Value.NextDouble() * (max - min) + min);
    }
}
