    int id;
    long timestamp;
    char status[50];
    // Other attributes
} ResourceRequest;

typedef struct DataNode {
    DataPacket data;
    struct DataNode* next;
} DataNode;

typedef struct RequestNode {
    ResourceRequest request;
    pthread_t validation_thread;
    // Other attributes
} RequestNode;

DataNode* data_head = NULL;
pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t data_cond = PTHREAD_COND_INITIALIZER;

RequestNode* request_head = NULL;
pthread_mutex_t request_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t request_cond = PTHREAD_COND_INITIALIZER;

void addDataPacket(DataPacket packet) {
    pthread_mutex_lock(&data_mutex);
    DataNode* new_node = (DataNode*)malloc(sizeof(DataNode));
    new_node->data = packet;
    new_node->next = data_head;
    data_head = new_node;
    pthread_cond_signal(&data_cond);
    pthread_mutex_unlock(&data_mutex);
}

void addResourceRequest(ResourceRequest request) {
    pthread_mutex_lock(&request_mutex);
    RequestNode* new_node = (RequestNode*)malloc(sizeof(RequestNode));
    new_node->request = request;
    new_node->next = request_head;
    request_head = new_node;
    pthread_cond_signal(&request_cond);
    pthread_mutex_unlock(&request_mutex);
}

// Additional functions for updating, removing, sorting, exporting, and handling concurrency

