typedef struct {
    int intValue;
    double doubleValue;
    char* identifier;
} record;

void logError(const char* message) {
    // Implementation of error logging
}

int createSemaphoreAndInitializeRecords(long numRecords, long initialValue, sem_t** semaphore, record** records, int* errorStatus) {
    *errorStatus = 0; // Success

    // Create semaphore
    *semaphore = sem_open("/my_semaphore", O_CREAT, 0644, initialValue);
    if (*semaphore == SEM_FAILED) {
        logError("Failed to create semaphore");
        return -1;
    }

    // Allocate memory for records
    *records = (record*)malloc(numRecords * sizeof(record));
    if (*records == NULL) {
        logError("Failed to allocate memory for records");
        sem_close(*semaphore);
        sem_unlink("/my_semaphore");
        *errorStatus = -1;
        return -1;
    }

    // Initialize records
    int successfulAllocations = 0;
    for (long i = 0; i < numRecords; ++i) {
        (*records)[i].intValue = rand() % 100; // Random value between 0 and 99
        (*records)[i].doubleValue = ((double)rand()) / RAND_MAX; // Random value between 0 and 1
        (*records)[i].identifier = (char*)malloc(20 * sizeof(char)); // Allocate memory for identifier string
        if ((*records)[i].identifier == NULL) {
            logError("Failed to allocate memory for identifier");
            for (long j = 0; j < i; ++j) {
                free((*records)[j].identifier);
            }
            free(*records);
            sem_close(*semaphore);
            sem_unlink("/my_semaphore");
            *errorStatus = -1;
            return -1;
        }
        sprintf((*records)[i].identifier, "ID%d", i); // Initialize identifier
        successfulAllocations++;
    }

    if (successfulAllocations < numRecords) {
        *errorStatus = 1; // Partial success
    }

    return successfulAllocations;
}
