    if (newResource == NULL) {
        logMemoryAllocation(0);
        return NULL;
    }
    newResource->id = 0;
    newResource->value = 0.0;
    newResource->uniqueId = (char*)malloc(20 * sizeof(char));
    if (newResource->uniqueId == NULL) {
        free(newResource);
        logMemoryAllocation(0);
        return NULL;
    }
    strcpy(newResource->uniqueId, "DefaultID");
    logMemoryAllocation(1);
    return newResource;
}

// Function to update a resource
ErrorStatus updateResource(int resourceId, const char* requestBody) {
    Resource* res = createResource(resourceId);
    if (res == NULL) {
        logConcurrencyError();
        return ERROR_INSUFFICIENT_MEMORY;
    }
    // Parse requestBody and update res accordingly
    free(res->uniqueId);
    free(res);
    logMemoryDeallocation(2);
    return ERROR_NONE;
}

// Function to delete a resource
