#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int id;
    double value;
    char* unique_id;
} Resource;

typedef enum {
    SUCCESS,
    PARTIAL_SUCCESS,
    FAILURE
} ErrorStatus;

ErrorStatus resourceManager(int operation, int* resourceId, char* requestBody, Resource** result) {
    static Resource* resources = NULL;
    static size_t allocatedSize = 0;
    static size_t usedSize = 0;
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (operation == PUT) {
        pthread_mutex_lock(&mutex);
        if (*resourceId >= allocatedSize) {
            // Double the allocated size
            allocatedSize *= 2;
            resources = realloc(resources, allocatedSize * sizeof(Resource));
            if (!resources) {
                pthread_mutex_unlock(&mutex);
                return FAILURE;
            }
        }
        Resource* resource = &resources[*resourceId];
        if (sscanf(requestBody, "%d %lf %m[^\n]", &resource->id, &resource->value, &resource->unique_id) != 3) {
            pthread_mutex_unlock(&mutex);
            return FAILURE;
        }
        usedSize++;
        pthread_mutex_unlock(&mutex);
    } else if (operation == DELETE) {
        pthread_mutex_lock(&mutex);
        *result = malloc(sizeof(Resource));
        if (!*result) {
            pthread_mutex_unlock(&mutex);
            return FAILURE;
        }
        (*result)->id = rand() % 1000;
        (*result)->value = drand48();
        (*result)->unique_id = strdup("default");
        usedSize++;
        pthread_mutex_unlock(&mutex);
    }

    // Log successful allocations and failures
    if (operation == PUT) {
        printf("%zu/%zu resources allocated\n", usedSize, allocatedSize);
    } else if (operation == DELETE) {
        printf("New resource created with ID %d\n", (*result)->id);
    }

    return SUCCESS;
}
