public class DynamicSqlExecutor
{
    public IDataReader ExecuteQuery(List<object> parameters, SqlConnection connection, string commandTemplate, Func<Dictionary<string, object>, bool> filter = null, Dictionary<string, object> context = null)
    {
        // Validate and sanitize input parameters and context
        ValidateParameters(parameters);
        ValidateContext(context);

        try
        {
            using (SqlCommand command = new SqlCommand(commandTemplate, connection))
            {
                // Apply filter conditions dynamically if provided
                if (filter != null)
                {
                    command.CommandText += " WHERE 1=1";
                    foreach (var key in context.Keys)
                    {
                        if (filter(new Dictionary<string, object> { { key, context[key] } }))
                        {
                            command.CommandText += $" AND [{key}] = @{key}";
                            command.Parameters.AddWithValue($"@{key}", context[key]);
                        }
                    }
                }

                // Set parameters for the SQL query
                foreach (var param in parameters)
                {
                    command.Parameters.AddWithValue(param);
                }

                // Execute the SQL query and return the result set as an IDataReader
                connection.Open();
                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
        }
        catch (Exception ex)
