#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MESSAGE_SIZE 256

typedef struct {
    int SenderId;
    int RecipientId;
    char Timestamp[30];
    char MessageContent[MAX_MESSAGE_SIZE];
} Message;

typedef struct {
    Message* messages;
    size_t count;
    size_t capacity;
} MessageCollection;

void initMessageCollection(MessageCollection* collection) {
    collection->messages = NULL;
    collection->count = 0;
    collection->capacity = 0;
}

void freeMessageCollection(MessageCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        // Assuming no need to free individual message content as it's static size
    }
    free(collection->messages);
    collection->messages = NULL;
    collection->count = 0;
    collection->capacity = 0;
}

int addMessage(MessageCollection* collection, const Message* newMessage) {
    if (collection->count >= collection->capacity) {
        size_t newCapacity = (collection->capacity == 0) ? 1 : collection->capacity * 2;
        Message* newMessages = realloc(collection->messages, newCapacity * sizeof(Message));
        if (!newMessages) return -1; // Memory allocation failed
        collection->messages = newMessages;
        collection->capacity = newCapacity;
    }
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->messages[i].SenderId == newMessage->SenderId && 
            collection->messages[i].RecipientId == newMessage->RecipientId) {
            return -2; // Duplicate message
        }
    }
    memcpy(&collection->messages[collection->count], newMessage, sizeof(Message));
    ++collection->count;
    return 0;
}

int serializeMessageCollection(const MessageCollection* collection, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1; // File opening failed
    fwrite(&collection->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < collection->count; ++i) {
        fwrite(&collection->messages[i], sizeof(Message), 1, file);
    }
    fclose(file);
    return 0;
}

int deserializeMessageCollection(MessageCollection* collection, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1; // File opening failed
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    Message* newMessages = realloc(collection->messages, count * sizeof(Message));
    if (!newMessages) {
        fclose(file);
        return -2; // Memory allocation failed
    }
    collection->messages = newMessages;
    collection->capacity = count;
    for (size_t i = 0; i < count; ++i) {
        fread(&collection->messages[i], sizeof(Message), 1, file);
    }
    fclose(file);
    collection->count = count;
    return 0;
}
