        do {
            records[i].offset = min_offset + rand() % (max_offset - min_offset + 1);
        } while (offsets[records[i].offset + max_offset] != 0);

        offsets[records[i].offset + max_offset] = 1;

        do {
            records[i].key = 1 + rand() % 100;
        } while (keys[records[i].key] != 0);

        keys[records[i].key] = 1;

        records[i].value = rand() % 201 - 100;
