pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

enum error_status {
    SUCCESS,
    PARTIAL_SUCCESS,
    FAILURE
};

enum error_status update_resource(int id, const char* body) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < allocated_count; i++) {
        if (resources[i].id == id) {
            // Parse the body to update resource data
            // Example: sscanf(body, "%lf", &resources[i].value);
            resources[i].value = atof(body);
            pthread_mutex_unlock(&mutex);
            return SUCCESS;
        }
    }
    pthread_mutex_unlock(&mutex);
    return FAILURE;
}

enum error_status delete_resource(int id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < allocated_count; i++) {
        if (resources[i].id == id) {
            free(resources[i].unique_id);
            memmove(&resources[i], &resources[i + 1], sizeof(resource) * (allocated_count - i - 1));
            allocated_count--;
            pthread_mutex_unlock(&mutex);
            return SUCCESS;
        }
    }
    pthread_mutex_unlock(&mutex);
    return FAILURE;
}

enum error_status resourceManager(int id, const char* body, enum request_type type) {
    if (type == UPDATE) {
        return update_resource(id, body);
    } else if (type == DELETE) {
        return delete_resource(id);
    }
    return FAILURE;
}

int main() {
    // Example usage
