    pthread_create(&thread1, NULL, resourceManager, (void*)1, "5.0", UPDATE);
    pthread_create(&thread2, NULL, resourceManager, (void*)2, NULL, DELETE);
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);
    return 0;
}
