import java.io.FileInputStream;
import java.io.IOException;
import java.util.Properties;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ServiceLifecycleManager {
    private static final int MAX_CONCURRENT_INSTANCES = 10;
    private static final long SHUTDOWN_GRACE_PERIOD = 10000;
    private static final String MESSAGE_FORMAT = "{\"timestamp\":\"%s\",\"duration\":%d,\"id\":\"%s\"}";
    private ExecutorService executorService;
    private Properties configProperties;

    public ServiceLifecycleManager(String configFilePath) throws IOException {
        configProperties = new Properties();
        try (FileInputStream fis = new FileInputStream(configFilePath)) {
            configProperties.load(fis);
        }
        executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_INSTANCES);
    }

    public void start() {
        for (int i = 0; i < MAX_CONCURRENT_INSTANCES; i++) {
            int serviceId = i + 1;
            executorService.submit(() -> runService(serviceId));
        }
    }

    private void runService(int serviceId) {
        while (!Thread.currentThread().isInterrupted()) {
            try {
                long startDelay = generateRandomDelay(5, 30);
                TimeUnit.SECONDS.sleep(startDelay);

                long startTime = System.currentTimeMillis();
                // Simulate service work
                Thread.sleep(generateRandomDelay(1, 10));
                long endTime = System.currentTimeMillis();

                long duration = endTime - startTime;
                String message = String.format(MESSAGE_FORMAT, new java.util.Date(), duration, "ID" + serviceId);
                sendMessage(message);

                long stopDelay = generateRandomDelay(30, 60);
                TimeUnit.SECONDS.sleep(stopDelay);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void sendMessage(String message) {
        // Simulate sending message to external messaging system
        System.out.println("Sending message: " + message);
    }

    private long generateRandomDelay(long min, long max) {
        return (long) (min + Math.random() * (max - min));
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        if (!executorService.awaitTermination(SHUTDOWN_GRACE_PERIOD, TimeUnit.MILLISECONDS)) {
            executorService.shutdownNow();
        }
    }

    public static void main(String[] args) {
        try {
            ServiceLifecycleManager manager = new ServiceLifecycleManager("config.properties");
            Runtime.getRuntime().addShutdownHook(new Thread(manager::shutdown));
            manager.start();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
