package com.example.dataprocessor;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.apache.avro.generic.GenericRecord;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.spark.api.java.JavaRDD;
import org.apache.spark.streaming.api.java.JavaInputDStream;
import org.apache.spark.streaming.api.java.JavaPairInputDStream;
import scala.Tuple2;

public class DataProcessor {
    private Map<String, SchemaValidator> schemaValidators = new ConcurrentHashMap<>();
    private Map<String, DataTransformer> dataTransformers = new ConcurrentHashMap<>();

    public void addSchemaValidator(String dataSource, SchemaValidator validator) {
        schemaValidators.put(dataSource, validator);
    }

    public void addDataTransformer(String dataSource, DataTransformer transformer) {
        dataTransformers.put(dataSource, transformer);
    }

    public <T> void processRealTimeStream(JavaInputDStream<ConsumerRecord<String, T>> stream) {
        stream.foreachRDD(rdd -> rdd.foreachPartition(partition -> {
            for (ConsumerRecord<String, T> record : partition) {
                String dataSource = record.topic();
                SchemaValidator validator = schemaValidators.get(dataSource);
                if (validator != null && !validator.validate(record.value())) {
                    throw new RuntimeException("Schema validation failed");
                }
                DataTransformer transformer = dataTransformers.get(dataSource);
                if (transformer != null) {
                    T transformedData = transformer.transform(record.value());
                    processTransformedData(transformedData);
                } else {
                    processRawData(record.value());
                }
            }
        }));
    }

    public void processBatch(JavaRDD<GenericRecord> rdd) {
        rdd.foreachPartition(partition -> {
            for (GenericRecord record : partition) {
                String dataSource = record.getSchema().getName();
                SchemaValidator validator = schemaValidators.get(dataSource);
                if (validator != null && !validator.validate(record)) {
                    throw new RuntimeException("Schema validation failed");
                }
                DataTransformer transformer = dataTransformers.get(dataSource);
                if (transformer != null) {
                    GenericRecord transformedData = transformer.transform(record);
                    processTransformedData(transformedData);
                } else {
                    processRawData(record);
                }
            }
        });
    }

    private void processTransformedData(Object data) {
        // Implement logic to process transformed data
    }

    private void processRawData(Object data) {
        // Implement logic to process raw data
    }

    public static interface SchemaValidator {
        boolean validate(Object data);
    }

    public static interface DataTransformer {
        Object transform(Object data);
    }
}
```

