    char ip[MAX_IP_LENGTH];
    char subnet_mask[MAX_IP_LENGTH];
    char gateway[MAX_IP_LENGTH];
} NetworkInterface;

NetworkInterface* network_interfaces[MAX_INTERFACES];
int interface_count = 0;

void initialize_interface(NetworkInterface** interfaces, int* count) {
    *interfaces = (NetworkInterface*)calloc(MAX_INTERFACES, sizeof(NetworkInterface));
    if (*interfaces == NULL) {
        perror("Failed to allocate memory for network interfaces");
        exit(EXIT_FAILURE);
    }
    *count = MAX_INTERFACES;
}

int validate_ip(const char* ip) {
    // Simple IP validation logic
    if (strlen(ip) != 15 || ip[3] != '.' || ip[7] != '.' || ip[11] != '.') return -1;
    return 0;
}

int add_interface(NetworkInterface* interface) {
    if (validate_ip(interface->ip)) {
        printf("Invalid IP address: %s\n", interface->ip);
        return -1;
    }
    for (int i = 0; i < interface_count; i++) {
        // Check for overlapping subnets
        if (strcmp(interface->subnet_mask, network_interfaces[i]->subnet_mask) == 0) {
            printf("Subnet overlap detected with interface ID %d\n", network_interfaces[i]->id);
            return -1;
        }
    }
    network_interfaces[interface_count++] = interface;
    return 0;
}

void serialize_config(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(&interface_count, sizeof(int), 1, file);
    for (int i = 0; i < interface_count; i++) {
        fwrite(network_interfaces[i], sizeof(NetworkInterface), 1, file);
    }
    fclose(file);
}

void deserialize_config(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }
    int count;
    fread(&count, sizeof(int), 1, file);
    interface_count = count;
    network_interfaces[interface_count] = realloc(network_interfaces, interface_count * sizeof(NetworkInterface));
    if (network_interfaces == NULL) {
        perror("Failed to reallocate memory for network interfaces");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < interface_count; i++) {
        fread(network_interfaces[i], sizeof(NetworkInterface), 1, file);
    }
    fclose(file);
}

void log_config_change(int id, const char* ip, const char* subnet_mask, const char* gateway) {
    printf("Config change: ID=%d, IP=%s, Subnet Mask=%s, Gateway=%s\n", id, ip, subnet_mask, gateway);
}

int apply_network_config() {
    // Placeholder for applying network configurations to live interfaces
    return 0;
}

void test_add_interface() {
    NetworkInterface iface = {1, "192.168.1.1", "255.255.255.0", "192.168.1.254"};
    if (add_interface(&iface) == 0) {
        printf("Interface added successfully\n");
    }
}

void test_serialize_deserialize() {
    serialize_config("config.dat");
    deserialize_config("config.dat");
    printf("Configuration deserialized successfully\n");
}

int main() {
    initialize_interface(network_interfaces, &interface_count);
    test_add_interface();
    test_serialize_deserialize();
    return 0;
}
