#define MAX_UE_HANDOVERS 100

typedef struct {
    int UeId;
    // Define S-TMSI and NAS message fields here
} LTE_UESRVCC_INFO_NAS_T;

typedef struct {
    LTE_UESRVCC_INFO_NAS_T *ueInfoList;
    int listSize;
    int successfulHandovers[MAX_UE_HANDOVERS];
    pthread_mutex_t handoverMutex;
    int handoverCount;
} HandoverData;

void initializeHandoverData(HandoverData *handoverData, int numUes) {
    handoverData->ueInfoList = (LTE_UESRVCC_INFO_NAS_T *)malloc(numUes * sizeof(LTE_UESRVCC_INFO_NAS_T));
    handoverData->listSize = numUes;
    for (int i = 0; i < MAX_UE_HANDOVERS; i++) {
        handoverData->successfulHandovers[i] = 0;
    }
    pthread_mutex_init(&handoverData->handoverMutex, NULL);
    handoverData->handoverCount = 0;
}

void updateHandoverStatus(HandoverData *handoverData, int UeId, int successful) {
    pthread_mutex_lock(&handoverData->handoverMutex);
    for (int i = 0; i < handoverData->listSize; i++) {
        if (handoverData->ueInfoList[i].UeId == UeId) {
            if (successful) {
                handoverData->successfulHandovers[UeId]++;
            }
            handoverData->handoverCount++;
            break;
        }
    }
    pthread_mutex_unlock(&handoverData->handoverMutex);
}

void cleanupHandoverData(HandoverData *handoverData) {
    free(handoverData->ueInfoList);
    pthread_mutex_destroy(&handoverData->handoverMutex);
}
