#define MAX_HANDOVER_ATTEMPTS 10000

typedef struct {
    uint32_t UeId;
    uint64_t S_TMSI;
    char NAS_message[256];
} LTE_UESRVCC_INFO_NAS_T;

typedef struct {
    LTE_UESRVCC_INFO_NAS_T data[MAX_HANDOVER_ATTEMPTS];
    int count;
    pthread_mutex_t lock;
    time_t last_activity;
} Handover_List_T;

void init_handover_list(Handover_List_T *list) {
    memset(list, 0, sizeof(*list));
    pthread_mutex_init(&list->lock, NULL);
}

int add_handover_attempt(Handover_List_T *list, LTE_UESRVCC_INFO_NAS_T info, time_t expiration_time) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_HANDOVER_ATTEMPTS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->data[list->count++] = info;
    list->last_activity = time(NULL);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void log_handover_attempt(Handover_List_T *list, LTE_UESRVCC_INFO_NAS_T info) {
    // Code to log the handover attempt to an external system
    printf("Logging UeId: %u, S-TMSI: %lu, NAS message: %s\n", info.UeId, info.S_TMSI, info.NAS_message);
}

void clean_up_handover_list(Handover_List_T *list) {
    pthread_mutex_lock(&list->lock);
    memset(list, 0, sizeof(*list));
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
}

int main() {
    Handover_List_T handover_list;
    init_handover_list(&handover_list);

    LTE_UESRVCC_INFO_NAS_T new_attempt = {12345, 67890123456789, "NAS message example"};
    if (add_handover_attempt(&handover_list, new_attempt, time(NULL) + 60)) {
        printf("Failed to add handover attempt.\n");
    }

    log_handover_attempt(&handover_list, new_attempt);

    clean_up_handover_list(&handover_list);

    return 0;
}
