char* generate_new_filename(const char* original_filename, int max_digits) {
    // Allocate memory for the new filename
    size_t len = strlen(original_filename);
    if (len > 255 - max_digits - 20) { // Assuming additional space for digits, timestamp, and file type extension
        return NULL;
    }
    char* new_filename = malloc(len + max_digits + 20);
    if (!new_filename) {
        return NULL; // Handle memory allocation failure
    }

    // Extract the file type extension from the original filename
    const char* file_extension = strrchr(original_filename, '.');
    if (file_extension && strlen(file_extension) <= 4) { // Assuming maximum 3 characters for file type
        snprintf(new_filename, len + max_digits + 20, "%.*s_%s.%s",
                 (int)(file_extension - original_filename), original_filename,
                 generate_random_string(max_digits),
                 file_extension + 1);
    } else {
        snprintf(new_filename, len + max_digits + 20, "%.*s_%s_XXX",
                 (int)len, original_filename,
                 generate_random_string(max_digits));
    }

    // Append a timestamp to the new filename
    time_t now = time(NULL);
    strftime(strrchr(new_filename, '\0'), 20, "_%Y%m%d%H%M%S", localtime(&now));

    return new_filename;
}

// Function to generate a random string of a given length
char* generate_random_string(int length) {
    static const char characters[] = "0123456789";
    char* result = malloc(length + 1);
    if (!result) {
        return NULL; // Handle memory allocation failure
    }
    for (int i = 0; i < length; ++i) {
        result[i] = characters[rand() % sizeof(characters)];
    }
    result[length] = '\0';
    return result;
}

// Function to normalize a filename to a safe format
