#define MAX_FILE_SIZE (10 * 1024 * 1024 * 1024) // 10 GB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void signal_handler(int signum) {
    if (signum == SIGSEGV) {
        fprintf(stderr, "Segmentation fault detected\n");
    } else if (signum == SIGXFSZ) {
        fprintf(stderr, "File size limit exceeded\n");
    }
    exit(EXIT_FAILURE);
}

int main(int argc, char* argv[]) {
    // Parse command-line arguments
    int N = 1000; // Default number of structures
    const char* input_file = "input.txt";
    const char* output_file = "output.txt";
    char delimiter[256] = "#";

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            // Display man page
            printf("Man page content...\n");
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0 && i + 1 < argc) {
            N = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else if (strncmp(argv[i], "--delimiter", 11) == 0) {
            strncpy(delimiter, argv[i] + 12, sizeof(delimiter) - 1);
        }
    }

    // Set up signal handlers
    signal(SIGSEGV, signal_handler);
    signal(SIGXFSZ, signal_handler);

    // Open input and output files
    FILE* fp_in = fopen(input_file, "r");
    if (fp_in == NULL) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }
    FILE* fp_out = fopen(output_file, "w");
    if (fp_out == NULL) {
        perror("Failed to open output file");
        fclose(fp_in);
        return EXIT_FAILURE;
    }

    // Allocate memory for array
    NFAPI_CRC_INDICATION_PDU_T* pdus = safe_malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Populate array with random data
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = rand();
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    // Write data to output file
    for (int i = 0; i < N; i++) {
        fprintf(fp_out, "%d,%d,%d\n", pdus[i].RX_UE_INFORMATION_TAG, pdus[i].RNTI, pdus[i].CRC_INDICATION_REL8_TAG);
    }

    // Free allocated memory
    free(pdus);

    // Close files
    fclose(fp_in);
    fclose(fp_out);

    return 0;
}
