typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char source_ip[16];
    char destination_ip[16];
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
} PacketStorage;

void init_packet_storage(PacketStorage *storage, size_t initial_capacity) {
    storage->packets = malloc(initial_capacity * sizeof(DataPacket));
    if (storage->packets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    storage->count = 0;
    storage->capacity = initial_capacity;
}

void add_packet(PacketStorage *storage, DataPacket packet) {
    if (storage->count >= storage->capacity) {
        storage->capacity *= 2;
        storage->packets = realloc(storage->packets, storage->capacity * sizeof(DataPacket));
        if (storage->packets == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
    storage->packets[storage->count++] = packet;
}

void remove_packet(PacketStorage *storage, int packet_id) {
    for (size_t i = 0; i < storage->count; ++i) {
        if (storage->packets[i].packet_id == packet_id) {
            memmove(&storage->packets[i], &storage->packets[i + 1], (storage->count - i - 1) * sizeof(DataPacket));
            --storage->count;
            break;
        }
    }
}

size_t get_packet_count(PacketStorage *storage) {
    return storage->count;
}

void sort_packets_by_timestamp(PacketStorage *storage) {
    qsort(storage->packets, storage->count, sizeof(DataPacket), [](const void *a, const void *b) {
        return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp;
    });
}

void compact_storage(PacketStorage *storage) {
    // Implement memory compaction logic here
}

size_t get_total_memory_usage() {
    // Implement memory usage tracking logic here
    return 0;
}

void add_packet_with_priority(PacketStorage *storage, DataPacket packet, int priority) {
    if (priority > 1 || priority < -1) {
        fprintf(stderr, "Invalid priority level\n");
        return;
    }
    // Add logic to handle priority based on the priority flag
    add_packet(storage, packet);
}

int main() {
    PacketStorage storage;
    init_packet_storage(&storage, 10);

    DataPacket packet = {1, time(NULL), 1024, "192.168.1.1", "192.168.1.2"};
    add_packet(&storage, packet);

    printf("Total packets: %zu\n", get_packet_count(&storage));

    remove_packet(&storage, 1);
    printf("Total packets after removal: %zu\n", get_packet_count(&storage));

