using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

public class HttpRequestProcessor
{
    private readonly HttpClient _httpClient;
    private readonly Dictionary<string, string> _cache;
    private readonly object _lock = new object();

    public HttpRequestProcessor(HttpClient client, Dictionary<string, string> cache)
    {
        _httpClient = client ?? throw new ArgumentNullException(nameof(client));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
    }

    public async Task<RequestSummary> ProcessRequestsAsync(List<string> urls, HttpClientHandler handler, bool useCache)
    {
        var summary = new RequestSummary();
        foreach (var url in urls)
        {
            try
            {
                if (useCache && _cache.ContainsKey(url))
                {
                    // Retrieve from cache
                    summary.SuccessCount++;
                }
                else
                {
                    var response = await SendRequestAsync(url, handler);
                    if (response.IsSuccessStatusCode)
                    {
                        // Store in cache if needed
                        if (useCache) _cache[url] = await response.Content.ReadAsStringAsync();
                        summary.SuccessCount++;
                    }
                    else
                    {
                        summary.FailedCount++;
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing request: {ex.Message}");
                summary.FailedCount++;
            }
        }

        return summary;
    }

    private async Task<HttpResponseMessage> SendRequestAsync(string url, HttpClientHandler handler)
    {
