typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    char source_ip[16];
    char destination_ip[16];
    // Add more fields as needed
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DFSStorage;

void initDFSStorage(DFSStorage *storage, size_t initial_capacity) {
    storage->packets = (DataPacket *)malloc(initial_capacity * sizeof(DataPacket));
    storage->count = 0;
    storage->capacity = initial_capacity;
    pthread_mutex_init(&storage->lock, NULL);
}

void destroyDFSStorage(DFSStorage *storage) {
    free(storage->packets);
    pthread_mutex_destroy(&storage->lock);
}

int addPacket(DFSStorage *storage, DataPacket packet) {
    pthread_mutex_lock(&storage->lock);
    if (storage->count >= storage->capacity) {
        size_t new_capacity = storage->capacity ? storage->capacity * 2 : 1;
        storage->packets = (DataPacket *)realloc(storage->packets, new_capacity * sizeof(DataPacket));
        storage->capacity = new_capacity;
    }
    memcpy(&storage->packets[storage->count], &packet, sizeof(DataPacket));
    storage->count++;
    pthread_mutex_unlock(&storage->lock);
    return 0;
}

int removePacket(DFSStorage *storage, int packet_id) {
    pthread_mutex_lock(&storage->lock);
    for (size_t i = 0; i < storage->count; i++) {
        if (storage->packets[i].packet_id == packet_id) {
            memmove(&storage->packets[i], &storage->packets[i + 1], (storage->count - i - 1) * sizeof(DataPacket));
            storage->count--;
            pthread_mutex_unlock(&storage->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&storage->lock);
    return -1;
}

size_t getPacketCount(DFSStorage *storage) {
    pthread_mutex_lock(&storage->lock);
    size_t count = storage->count;
    pthread_mutex_unlock(&storage->lock);
    return count;
}

void sortPacketsByTimestamp(DFSStorage *storage, time_t grace_period) {
    // Implement sorting logic based on timestamp and grace period
}

int computeMD5Hash(const char *file_path, unsigned char *digest) {
    FILE *file = fopen(file_path, "rb");
    if (!file) return -1;

    MD5_CTX md5;
    MD5_Init(&md5);

    const size_t buffer_size = 4096;
    char buffer[buffer_size];
    while (size_t bytes_read = fread(buffer, 1, buffer_size, file)) {
        MD5_Update(&md5, buffer, bytes_read);
    }
    fclose(file);

    MD5_Final(digest, &md5);
    return 0;
}
