using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;

public class SqlBatchExecutor
{
    private readonly string _connectionString;

    public SqlBatchExecutor(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task<ExecutionSummary> ExecuteBatchAsync(List<string> sqlCommands, bool atomicTransactions, int maxRetries = 3, IsolationLevel isolationLevel = IsolationLevel.ReadCommitted)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();

            if (atomicTransactions)
                await connection.BeginTransactionAsync(isolationLevel);

            var executionResults = new List<CommandResult>();

            foreach (var command in sqlCommands)
            {
                for (int retryCount = 0; retryCount <= maxRetries; retryCount++)
                {
                    try
                    {
                        using (var cmd = new SqlCommand(command, connection))
                        {
                            if (atomicTransactions && retryCount > 0)
                                cmd.Transaction = await connection.BeginTransactionAsync(isolationLevel);

                            var startTime = DateTime.UtcNow;
                            var result = await cmd.ExecuteNonQueryAsync();
                            executionResults.Add(new CommandResult
                            {
                                CommandText = command,
                                Result = result,
                                StartTime = startTime,
                                EndTime = DateTime.UtcNow
                            });

                            if (atomicTransactions)
                                await cmd.Transaction.CommitAsync();

                            break; // Exit the retry loop on success
                        }
                    }
                    catch (SqlException ex)
                    {
                        if (ex.Number == -2) // Timeout
                        {
                            continue; // Retry on timeout
                        }

                        // Handle other SQL exceptions or log and rethrow
                        throw;
                    }
                    catch (Exception ex)
                    {
                        // Log and rethrow non-SQL exceptions
                        throw;
                    }
                }
            }

            if (atomicTransactions)
                await connection.CommitAsync();

            return new ExecutionSummary { Results = executionResults };
        }
    }
}

public class CommandResult
{
    public string CommandText { get; set; }
    public int Result { get; set; }
    public DateTime StartTime { get; set; }
    public DateTime EndTime { get; set; }
}

public class ExecutionSummary
{
    public List<CommandResult> Results { get; set; }
}
```

This code provides a basic implementation of an asynchronous SQL batch executor with support for atomic transactions, error handling with retries, and logging the execution results. The method is designed to be thread-safe and capable of processing multiple commands concurrently while managing resource utilization efficiently.']

