typedef struct {
    int entry_id;
    time_t timestamp;
    char *message;
    int priority_level;
    char *source_identifier;
} LogEntry;

typedef struct {
    LogEntry **entries;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} LogSystem;

LogSystem* log_system_init() {
    LogSystem *ls = malloc(sizeof(LogSystem));
    ls->entries = NULL;
    ls->size = 0;
    ls->capacity = 0;
    pthread_mutex_init(&ls->lock, NULL);
    return ls;
}

void log_system_add(LogSystem *ls, int entry_id, time_t timestamp, const char *message, int priority_level, const char *source_identifier) {
    pthread_mutex_lock(&ls->lock);
    if (ls->size == ls->capacity) {
        size_t new_capacity = (ls->capacity == 0) ? 1 : ls->capacity * 2;
        LogEntry **new_entries = realloc(ls->entries, new_capacity * sizeof(LogEntry*));
        if (!new_entries) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&ls->lock);
            return;
        }
        ls->entries = new_entries;
        ls->capacity = new_capacity;
    }
    LogEntry *entry = malloc(sizeof(LogEntry));
    entry->entry_id = entry_id;
    entry->timestamp = timestamp;
    entry->message = strdup(message);
    entry->priority_level = priority_level;
    entry->source_identifier = strdup(source_identifier);
    ls->entries[ls->size++] = entry;
    pthread_mutex_unlock(&ls->lock);
}

void log_system_filter_and_remove(LogSystem *ls, int min_priority) {
    pthread_mutex_lock(&ls->lock);
    size_t i = 0, j = 0;
    while (i < ls->size) {
        if (ls->entries[i]->priority_level >= min_priority) {
            LogEntry *entry = ls->entries[i];
            free(entry->message);
            free(entry->source_identifier);
            free(entry);
            i++;
        } else {
            ls->entries[j++] = ls->entries[i++];
        }
    }
    if (j != ls->size) {
        ls->entries = realloc(ls->entries, j * sizeof(LogEntry*));
        ls->size = j;
    }
    pthread_mutex_unlock(&ls->lock);
}

size_t log_system_count_entries(LogSystem *ls) {
    pthread_mutex_lock(&ls->lock);
    size_t count = ls->size;
    pthread_mutex_unlock(&ls->lock);
    return count;
}

void log_system_rotate_logs(LogSystem *ls, const char *archive_dir) {
