#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key_id;
    char timestamp[20];
    char value[1024];
    char metadata[512];
} KeyValue;

typedef struct Node {
    KeyValue data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addKeyValue(int key_id, const char* timestamp, const char* value, const char* metadata) {
    pthread_mutex_lock(&lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data.key_id = key_id;
    strncpy(newNode->data.timestamp, timestamp, sizeof(newNode->data.timestamp) - 1);
    strncpy(newNode->data.value, value, sizeof(newNode->data.value) - 1);
    strncpy(newNode->data.metadata, metadata, sizeof(newNode->data.metadata) - 1);
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&lock);
}

void updateKeyValue(int key_id, const char* timestamp, const char* value, const char* metadata) {
    pthread_mutex_lock(&lock);
    Node* current = head;
    while (current != NULL) {
        if (current->data.key_id == key_id) {
            strncpy(current->data.timestamp, timestamp, sizeof(current->data.timestamp) - 1);
            strncpy(current->data.value, value, sizeof(current->data.value) - 1);
            strncpy(current->data.metadata, metadata, sizeof(current->data.metadata) - 1);
            pthread_mutex_unlock(&lock);
            return;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

void deleteKeyValue(int key_id) {
    pthread_mutex_lock(&lock);
    Node* current = head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->data.key_id == key_id) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&lock);
            return;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

void printKeyValueStore() {
    pthread_mutex_lock(&lock);
    Node* current = head;
    while (current != NULL) {
        printf("Key ID: %d, Timestamp: %s, Value: %s, Metadata: %s\n",
               current->data.key_id,
               current->data.timestamp,
               current->data.value,
               current->data.metadata);
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    addKeyValue(1, "2023-04-01T12:00:00Z", "Value1", "Metadata1");
    updateKeyValue(1, "2023-04-01T12:01:00Z", "UpdatedValue1", "UpdatedMetadata1");
    deleteKeyValue(1);
    printKeyValueStore();
    return 0;
}
