#include <string.h>
#include <openssl/md5.h>

#define MAX_NFAPI_STRUCTS 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generateMD5Hash(unsigned short rnti, unsigned char *hash) {
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, &rnti, sizeof(rnti));
    MD5_Final(hash, &md5);
}

NFAPI_CRC_INDICATION_PDU_T* generateNFAPCRIIndications(int numElements, unsigned int seed) {
    if (numElements <= 0 || numElements > MAX_NFAPI_STRUCTS) {
        return NULL; // Handle invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T *indicationArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (indicationArray == NULL) {
        return NULL; // Handle memory allocation failure
    }

    srand(seed);
    for (int i = 0; i < numElements; ++i) {
        indicationArray[i].RX_UE_INFORMATION_TAG = rand();
        indicationArray[i].RNTI = rand() % 65536;
        generateMD5Hash(indicationArray[i].RNTI, &indicationArray[i].CRC_INDICATION_REL8_TAG);
    }

    return indicationArray;
}
