class TransactionProcessor {
private:
    std::mt19937 rng;
    std::uniform_int_distribution<int> int_dist;
    std::uniform_real_distribution<float> float_dist;

    std::queue<std::pair<int, float>> transaction_queue;
    std::mutex queue_mutex;
    std::condition_variable cv;
    bool running;

    void worker_thread() {
        while (running) {
            std::unique_lock<std::mutex> lock(queue_mutex);
            cv.wait(lock, [this] { return !transaction_queue.empty() || !running; });
            if (!running && transaction_queue.empty()) break;

            auto transaction = transaction_queue.front();
            transaction_queue.pop();

            // Process the transaction
            process_transaction(transaction.first, transaction.second);
        }
    }

public:
    TransactionProcessor(int seed) : rng(seed), int_dist(1, 5), float_dist(0.0f, 1.0f), running(false) {}

    ~TransactionProcessor() {
        stop();
    }

    void start() {
        running = true;
        std::thread(&TransactionProcessor::worker_thread, this).detach();
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            running = false;
        }
        cv.notify_all();
    }

    bool add_transaction(int priority, float weight) {
        if (priority < 1 || priority > 5) return false;

        // Check transaction criteria
        auto now = std::chrono::system_clock::now();
        if (std::chrono::duration_cast<std::chrono::seconds>(now - last_processed_time).count() >= 5) {
            total_transactions_last_10s = 0;
        }
        if (total_transactions_last_10s > 100) return false;

        // Add transaction to queue
        std::lock_guard<std::mutex> lock(queue_mutex);
        transaction_queue.push({priority, weight});
        cv.notify_one();

        return true;
    }

    void process_transaction(int priority, float weight) {
        // Simulate processing time
        std::this_thread::sleep_for(std::chrono::milliseconds(10));

        // Update metrics and audit log
        update_metrics(priority, weight);
        log_transaction(priority);
    }

private:
    void update_metrics(int priority, float weight) {
        // Update rolling count of transactions per second
        current_transactions_per_second[priority]++;

        // Update cumulative metrics over 5-second intervals
        if (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now() - last_update_time).count() >= 1) {
            last_update_time = std::chrono::system_clock::now();
            total_transactions_last_5s += current_transactions_per_second;
            for (int i = 1; i <= 5; ++i) current_transactions_per_second[i] = 0;
        }

        // Dynamically adjust transaction rate limit
        if (total_transactions_last_10s > 200) {
            // Adjust rate limit based on system load
        }
    }

    void log_transaction(int priority) {
        // Log transaction details in a secure, persistent storage system
    }

    std::chrono::time_point<std::chrono::system_clock> last_processed_time;
    std::chrono::time_point<std::chrono::system_clock> last_update_time;
    std::vector<int> current_transactions_per_second(6, 0);
    int total_transactions_last_10s = 0;
    int total_transactions_last_5s = 0;
};
