        if (cache->cache[i] != NULL) {
            free(cache->cache[i]);
        }
    }
    free(cache->cache);
    free(cache->last_used);
    pthread_mutex_unlock(&cache->mutex);
    pthread_mutex_destroy(&cache->mutex);
    free(cache);
}

