#include <string.h>

typedef struct Event {
    char type[50];
    int timestamp;
    double value;
} Event;

Event* parse_log_file(const char* filename, int* count) {
    FILE* file = fopen(filename, "r");
    if (!file) return NULL;

    Event* events = (Event*)malloc(sizeof(Event));
    *count = 0;

    while (fscanf(file, "%s %d %lf", events[*count].type, &events[*count].timestamp, &events[*count].value) == 3) {
        (*count)++;
        if (*count % 100 == 0) {
            events = realloc(events, (*count + 1) * sizeof(Event));
        }
    }

    fclose(file);
    return events;
}

void generate_summary(const char* filename, Event* events, int count, const char* filter, int include_timestamps) {
    FILE* file = fopen(filename, "w");
    if (!file) return;

    for (int i = 0; i < count; i++) {
        if (strstr(events[i].type, filter)) {
            fprintf(file, "%s", events[i].type);
            if (include_timestamps) fprintf(file, " %d", events[i].timestamp);
            fprintf(file, " %.2f\n", events[i].value);
        }
    }

    fclose(file);
}

int main(int argc, char* argv[]) {
    if (argc != 5) {
        printf("Usage: %s <input_log_file> <output_summary_file> <filter_criteria> <include_timestamps>\n", argv[0]);
        return 1;
    }

    const char* input_log_file = argv[1];
    const char* output_summary_file = argv[2];
    const char* filter_criteria = argv[3];
    int include_timestamps = (strcmp(argv[4], "true") == 0);

    int event_count = 0;
    Event* events = parse_log_file(input_log_file, &event_count);
    if (!events) {
        printf("Error parsing log file.\n");
        return 1;
    }

    generate_summary(output_summary_file, events, event_count, filter_criteria, include_timestamps);

    free(events);
    return 0;
}
