void add_resource_record(ResourceConsumption* record) {
    pthread_mutex_lock(&records_mutex);
    while (record_count >= MAX_RESOURCE_RECORDS) {
        pthread_cond_wait(&records_cv, &records_mutex);
    }
    resource_records[record_count++] = record;
    pthread_cond_signal(&records_cv);
    pthread_mutex_unlock(&records_mutex);
}

void remove_resource_record(int resource_id) {
    pthread_mutex_lock(&records_mutex);
    for (int i = 0; i < record_count; ++i) {
        if (resource_records[i]->resource_id == resource_id) {
            free(resource_records[i]);
            for (int j = i; j < record_count - 1; ++j) {
                resource_records[j] = resource_records[j + 1];
            }
            record_count--;
            pthread_cond_signal(&records_cv);
            break;
        }
    }
    pthread_mutex_unlock(&records_mutex);
}

