typedef struct {
    char timestamp[20];
    double metric;
} LogEntry;

// Function to parse the input file and extract log entries
LogEntry* parseLogFile(const char* filename, int* count) {
    FILE* file = fopen(filename, "r");
    if (!file) return NULL;

    // Estimate initial size of log entry array
    *count = 100;
    LogEntry* logs = (LogEntry*)malloc(*count * sizeof(LogEntry));
    if (!logs) {
        fclose(file);
        return NULL;
    }

    int index = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Parse the log entry
        sscanf(line, "%19[^ ] %lf", logs[index].timestamp, &logs[index].metric);
        if (++index == *count) {
            *count *= 2;
            logs = (LogEntry*)realloc(logs, *count * sizeof(LogEntry));
            if (!logs) {
                fclose(file);
                return NULL;
            }
        }
    }

    fclose(file);
    return logs;
}

