    pthread_mutex_unlock(&task_manager.lock);
    return 0;
}

void update_task_status(int task_id, TaskStatus status) {
    pthread_mutex_lock(&task_manager.lock);
    for (int i = 0; i < task_manager.count; i++) {
        if (task_manager.tasks[i].task_id == task_id) {
            task_manager.tasks[i].status = status;
            break;
        }
    }
    pthread_mutex_unlock(&task_manager.lock);
}

int get_ongoing_task_count() {
