}

void cache_task(TaskLog *task) {
    pthread_mutex_lock(&cache.lock);
    if (cache.size < CACHE_SIZE) {
        int index = (cache.tail + 1) % CACHE_SIZE;
        cache.entries[index].task = task;
        cache.entries[index].timestamp = time(NULL);
        if (cache.size == 0) {
            cache.head = cache.tail = index;
        } else {
            cache.tail = index;
        }
        cache.size++;
    } else {
        int oldest_index = cache.head;
        cache.head = (cache.head + 1) % CACHE_SIZE;
        // Free memory for the oldest task
    }
    pthread_mutex_unlock(&cache.lock);
}

TaskLog* get_cached_task(int task_id) {
    TaskLog *task = NULL;
    pthread_mutex_lock(&cache.lock);
    for (int i = cache.head; i != cache.tail;) {
        if (cache.entries[i].task->task_id == task_id) {
            task = cache.entries[i].task;
            // Move the accessed entry to the end of the cache
            int temp = cache.tail;
            cache.tail = i;
            i = temp;
            break;
        }
        i = (i + 1) % CACHE_SIZE;
    }
    pthread_mutex_unlock(&cache.lock);
    return task;
}

void batch_add_tasks(TaskLog tasks[], int count) {
    pthread_mutex_lock(&task_manager.lock);
    for (int i = 0; i < count; i++) {
        add_task(tasks[i]);
    }
    pthread_mutex_unlock(&task_manager.lock);
}

void purge_completed_tasks() {
    pthread_mutex_lock(&task_manager.lock);
    int new_count = 0;
    for (int i = 0; i < task_manager.count; i++) {
        if (task_manager.tasks[i].status != STATUS_COMPLETED) {
            task_manager.tasks[new_count++] = task_manager.tasks[i];
        }
    }
    task_manager.count = new_count;
    pthread_mutex_unlock(&task_manager.lock);
}

