from collections import Counter

def read_and_analyze_log_file(file_path):
    priority_level_counts = Counter()
    total_message_length = 0

    if file_path.endswith('.gz'):
        with gzip.open(file_path, 'rt') as file:
            for line in file:
                log_entry = line.strip().split('\t')
                priority_level = int(log_entry[3])
                message = log_entry[2]
                priority_level_counts[priority_level] += 1
                total_message_length += len(message)
    else:
        with open(file_path, 'rt') as file:
            for line in file:
                log_entry = line.strip().split('\t')
                priority_level = int(log_entry[3])
                message = log_entry[2]
                priority_level_counts[priority_level] += 1
                total_message_length += len(message)

    average_message_length = total_message_length / len(priority_level_counts) if priority_level_counts else 0

    return priority_level_counts, average_message_length

