    char task_name[256];
    int executor_id;
    time_t start_time;
    time_t end_time;
    char status[50];
} TaskLog;

TaskLog task_list[MAX_TASKS];
int task_count = 0;

typedef struct CacheEntry {
    int task_id;
    time_t start_time;
    int last_accessed;
} CacheEntry;

CacheEntry cache[CACHE_SIZE];
int cache_head = 0, cache_tail = 0, cache_size = 0;

void add_task(TaskLog task) {
    if (task_count >= MAX_TASKS) return;
    task_list[task_count++] = task;
}

void update_status(int task_id, char* new_status) {
    for (int i = 0; i < task_count; i++) {
        if (task_list[i].task_id == task_id) {
            strcpy(task_list[i].status, new_status);
            break;
        }
    }
}

int get_ongoing_tasks() {
    int count = 0;
    for (int i = 0; i < task_count; i++) {
        if (strcmp(task_list[i].status, "pending") == 0) count++;
    }
    return count;
}

void sort_tasks_by_start_time() {
    qsort(task_list, task_count, sizeof(TaskLog), compare_start_time);
}

int compare_start_time(const void* a, const void* b) {
    TaskLog* taskA = (TaskLog*)a;
    TaskLog* taskB = (TaskLog*)b;
    return (taskA->start_time > taskB->start_time) - (taskA->start_time < taskB->start_time);
}

void add_to_cache(int task_id, time_t start_time) {
    if (cache_size == CACHE_SIZE) {
        cache[cache_head].task_id = 0;
        cache[cache_head].start_time = 0;
        cache[cache_head].last_accessed = 0;
        cache_head = (cache_head + 1) % CACHE_SIZE;
    }
    CacheEntry new_entry = {task_id, start_time, time(NULL)};
    cache[cache_tail] = new_entry;
    cache_size++;
    cache_tail = (cache_tail + 1) % CACHE_SIZE;
}

void update_cache(int task_id, time_t start_time) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].task_id == task_id) {
            cache[i].start_time = start_time;
            cache[i].last_accessed = time(NULL);
            return;
        }
    }
}

void remove_from_cache(int task_id) {
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].task_id == task_id) {
            cache[i].task_id = 0;
            cache[i].start_time = 0;
            cache[i].last_accessed = 0;
            return;
        }
    }
}

void batch_add_tasks(TaskLog tasks[], int count) {
    for (int i = 0; i < count; i++) {
        add_task(tasks[i]);
    }
}

void purge_completed_tasks() {
    for (int i = task_count - 1; i >= 0; i--) {
        if (strcmp(task_list[i].status, "completed") == 0) {
            memmove(&task_list[i], &task_list[i + 1], sizeof(TaskLog) * (task_count - i - 1));
            task_count--;
            remove_from_cache(task_list[i].task_id);
        }
    }
}

