fn main() {
    let path = Path::new("directory_with_files");
    let grammar = "your_grammar_here";
    process_directory(path, grammar);
}

fn process_directory(path: &Path, grammar: &str) {
    let (tx, rx): (mpsc::Sender<FileTask>, mpsc::Receiver<FileTask>) = mpsc::channel();
    let mut worker_threads = vec![];

    for entry in fs::read_dir(path).unwrap() {
        let task = FileTask::new(entry.unwrap().path(), grammar.to_string());
        tx.send(task).unwrap();
    }

    for _ in 0..num_cpus::get() {
        let rx = rx.clone();
        worker_threads.push(thread::spawn(move || {
            while let Ok(task) = rx.recv() {
                process_file(&task);
            }
        }));
    }

    drop(tx);

    for handle in worker_threads {
        handle.join().unwrap();
    }

    println!("All files processed.");
}

struct FileTask {
    path: PathBuf,
    grammar: String,
}

impl FileTask {
    fn new(path: PathBuf, grammar: String) -> Self {
        FileTask { path, grammar }
    }
}

