import hashlib

def calculate_md5(file_path, chunk_size=4096, known_hash=None):
    md5 = hashlib.md5()
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            md5.update(data)

    current_hash = md5.hexdigest()

    if known_hash and current_hash != known_hash:
        raise ValueError("File hash does not match known hash.")

    return current_hash

def verify_md5(file_path, known_hash):
    try:
        calculated_hash = calculate_md5(file_path, known_hash=known_hash)
        print(f"Hash verified. File: {file_path}, Hash: {calculated_hash}")
    except ValueError as e:
        print(e)

# Example usage
file_path = "path_to_large_file"
known_hash = "expected_md5_hash"
verify_md5(file_path, known_hash)
