} ResourceConsumption;

typedef struct Node {
    ResourceConsumption data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} List;

void init_list(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_to_list(List* list, ResourceConsumption data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1; // Memory allocation failed

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_lock(&list->mutex);
    // Update your LRU cache here
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

int remove_from_list(List* list, int resource_id) {
    Node* current = list->head;
    Node* previous = NULL;
    pthread_mutex_lock(&list->mutex);

    while (current != NULL) {
        if (current->data.resource_id == resource_id) {
            if (previous == NULL)
                list->head = current->next;
            else
                previous->next = current->next;

            free(current);
            pthread_mutex_unlock(&list->mutex);
            // Update your LRU cache here
            return 0;
        }
        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return -1; // Resource not found
}

ResourceConsumption* get_from_list(List* list, int resource_id) {
    Node* current = list->head;
    pthread_mutex_lock(&list->mutex);

    while (current != NULL) {
        if (current->data.resource_id == resource_id) {
            pthread_mutex_unlock(&list->mutex);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL; // Resource not found
}

void sort_list(List* list) {
    Node** nodes;
    int size = 0, i;

    pthread_mutex_lock(&list->mutex);
    for (Node* temp = list->head; temp != NULL; temp = temp->next)
        size++;

    nodes = (Node**)malloc(size * sizeof(Node*));
    if (!nodes) {
        pthread_mutex_unlock(&list->mutex);
        return; // Memory allocation failed
    }

    i = 0;
    for (Node* current = list->head; current != NULL; current = current->next)
        nodes[i++] = current;

    for (i = 1; i < size; i++) {
        int j, k;
        Node* temp = nodes[j];
        for (k = j - 1; k >= 0 && nodes[k]->data.consumption_date < temp->data.consumption_date; k--)
            nodes[k + 1] = nodes[k];
        nodes[k + 1] = temp;
    }

    list->head = nodes[0];
    for (i = 1; i < size; i++)
        nodes[i - 1]->next = nodes[i];
    nodes[size - 1]->next = NULL;

    free(nodes);
    pthread_mutex_unlock(&list->mutex);
}

void free_list(List* list) {
    Node* current, *temp;
    pthread_mutex_lock(&list->mutex);

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t capacity, size;
    pthread_mutex_t mutex;
} NfaPduArray;

void init_nfa_pdu_array(NfaPduArray* array, size_t capacity) {
    array->capacity = capacity;
    array->size = 0;
    array->pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->pdus) {
        // Handle memory allocation failure
        return;
    }
    pthread_mutex_init(&array->mutex, NULL);
}

int add_to_nfa_pdu_array(NfaPduArray* array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        // Handle capacity exceeded
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    array->pdus[array->size++] = pdu;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void free_nfa_pdu_array(NfaPduArray* array) {
    pthread_mutex_lock(&array->mutex);
    free(array->pdus);
    array->pdus = NULL;
    array->capacity = array->size = 0;
    pthread_mutex_unlock(&array->mutex);
}
