#include <stdlib.h>
#include <pthread.h>

typedef struct DataPacket {
    int packet_id;
    long timestamp;
    size_t payload_size;
    int priority_level;
    struct DataPacket* next;
} DataPacket;

typedef struct PacketManager {
    DataPacket* head;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
} PacketManager;

void initialize_manager(PacketManager* manager, size_t max_packets) {
    manager->head = NULL;
    manager->count = 0;
    manager->max_size = max_packets;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_packet(PacketManager* manager, int packet_id, long timestamp, size_t payload_size, int priority_level) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->max_size) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Maximum number of packets reached
    }

    DataPacket* new_packet = (DataPacket*)malloc(sizeof(DataPacket));
    if (!new_packet) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Memory allocation failed
    }

    new_packet->packet_id = packet_id;
    new_packet->timestamp = timestamp;
    new_packet->payload_size = payload_size;
    new_packet->priority_level = priority_level;
    new_packet->next = manager->head;
    manager->head = new_packet;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_packet(PacketManager* manager, int packet_id) {
    pthread_mutex_lock(&manager->lock);
    DataPacket** current = &manager->head;
    while (*current != NULL) {
        if ((*current)->packet_id == packet_id) {
            DataPacket* temp = *current;
            *current = (*current)->next;
            free(temp);
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Packet removed successfully
        }
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Packet not found
}

int update_timestamp(PacketManager* manager, int packet_id, long new_timestamp) {
    pthread_mutex_lock(&manager->lock);
    DataPacket* current = manager->head;
    while (current != NULL) {
        if (current->packet_id == packet_id) {
            current->timestamp = new_timestamp;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Timestamp updated successfully
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Packet not found
}

size_t get_packet_count(PacketManager* manager) {
    pthread_mutex_lock(&manager->lock);
    size_t count = manager->count;
    pthread_mutex_unlock(&manager->lock);
    return count;
}

void sort_packets_by_priority_and_timestamp(PacketManager* manager) {
    pthread_mutex_lock(&manager->lock);
    // Implement sorting algorithm here (e.g., merge sort)
    // For simplicity, we'll just reverse the list for demonstration
    DataPacket* prev = NULL;
    DataPacket* current = manager->head;
    while (current != NULL) {
        DataPacket* next_temp = current->next;
        current->next = prev;
        prev = current;
        current = next_temp;
    }
    manager->head = prev;

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_manager(PacketManager* manager) {
    pthread_mutex_lock(&manager->lock);
    DataPacket* current = manager->head;
    while (current != NULL) {
        DataPacket* temp = current;
        current = current->next;
        free(temp);
    }
    manager->head = NULL;
    manager->count = 0;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
