typedef struct DataPacket {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    int priority_level;
} DataPacket;

typedef struct Node {
    DataPacket packet;
    struct Node* next;
} Node;

typedef struct DynamicArray {
    Node* head;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t max_size) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array)
        return NULL;
    array->head = NULL;
    array->count = 0;
    array->max_size = max_size;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);
    Node* current = array->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_packet(DynamicArray* array, DataPacket packet) {
    if (pthread_mutex_lock(&array->lock))
        return -1;
    if (array->count >= array->max_size) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }
    new_node->packet = packet;
    new_node->next = array->head;
    array->head = new_node;
    array->count++;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int remove_packet(DynamicArray* array, int packet_id) {
    if (pthread_mutex_lock(&array->lock))
        return -1;
    Node* current = array->head;
    Node* prev = NULL;
    while (current) {
        if (current->packet.packet_id == packet_id) {
            if (prev)
                prev->next = current->next;
            else
                array->head = current->next;
            free(current);
            array->count--;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&array->lock);
    return -1;
}

int update_timestamp(DynamicArray* array, int packet_id, time_t new_timestamp) {
    if (pthread_mutex_lock(&array->lock))
        return -1;
    Node* current = array->head;
    while (current) {
        if (current->packet.packet_id == packet_id) {
            current->packet.timestamp = new_timestamp;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&array->lock);
    return -1;
}

size_t get_packet_count(DynamicArray* array) {
    size_t count;
    pthread_mutex_lock(&array->lock);
    count = array->count;
    pthread_mutex_unlock(&array->lock);
    return count;
}

void sort_packets(DynamicArray* array) {
    if (pthread_mutex_lock(&array->lock))
        return;
    // Implement a stable sorting algorithm here
    // Use qsort or bubble sort with a custom comparator that first compares priority_level, then timestamp
    pthread_mutex_unlock(&array->lock);
}

int batch_process_packets(DynamicArray* array, int threshold, size_t (*transform_payload)(size_t), time_t (*transform_timestamp)(time_t)) {
    if (pthread_mutex_lock(&array->lock))
        return -1;
    Node* current = array->head;
    while (current) {
        if (current->packet.priority_level > threshold) {
            current->packet.payload_size = transform_payload(current->packet.payload_size);
            current->packet.timestamp = transform_timestamp(current->packet.timestamp);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&array->lock);
    return 0;
}
