typedef struct {
    int packet_id;
    long timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    size_t total_memory_usage;
} PacketManager;

void init_packet_manager(PacketManager *pm, size_t initial_capacity) {
    pm->packets = malloc(initial_capacity * sizeof(DataPacket));
    pm->count = 0;
    pm->capacity = initial_capacity;
    pthread_mutex_init(&pm->lock, NULL);
    pm->total_memory_usage = 0;
}

void destroy_packet_manager(PacketManager *pm) {
    free(pm->packets);
    pthread_mutex_destroy(&pm->lock);
}

int add_packet(PacketManager *pm, DataPacket packet) {
    pthread_mutex_lock(&pm->lock);
    if (pm->count == pm->capacity) {
        size_t new_capacity = pm->capacity * 2;
        pm->packets = realloc(pm->packets, new_capacity * sizeof(DataPacket));
        pm->capacity = new_capacity;
    }
    pm->packets[pm->count++] = packet;
    pm->total_memory_usage += sizeof(DataPacket) + packet.payload_size;
    pthread_mutex_unlock(&pm->lock);
    return 0;
}

int remove_packet(PacketManager *pm, int packet_id) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i].packet_id == packet_id) {
            memmove(pm->packets + i, pm->packets + i + 1, (pm->count - i - 1) * sizeof(DataPacket));
            pm->total_memory_usage -= sizeof(DataPacket) + pm->packets[pm->count - 1].payload_size;
            --pm->count;
            pthread_mutex_unlock(&pm->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&pm->lock);
    return -1;
}

size_t get_packet_count(PacketManager *pm) {
    return pm->count;
}

int compare_packets(const void *a, const void *b) {
    DataPacket packet_a = *(DataPacket *)a;
    DataPacket packet_b = *(DataPacket *)b;
    if (packet_a.timestamp < packet_b.timestamp) return -1;
    if (packet_a.timestamp > packet_b.timestamp) return 1;
    return 0;
}

void sort_packets_by_timestamp(PacketManager *pm) {
    pthread_mutex_lock(&pm->lock);
    qsort(pm->packets, pm->count, sizeof(DataPacket), compare_packets);
    pthread_mutex_unlock(&pm->lock);
}

DataPacket* find_packet_with_max_payload_size(PacketManager *pm) {
    DataPacket *max_payload = NULL;
    size_t max_size = 0;
    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i].payload_size > max_size) {
            max_size = pm->packets[i].payload_size;
            max_payload = &pm->packets[i];
        }
    }
    return max_payload;
}

void report_memory_usage(PacketManager *pm) {
    printf("Total memory usage: %zu bytes\n", pm->total_memory_usage);
}
