#include <iostream>
#include <vector>
#include <unordered_map>
#include <string>
#include <algorithm>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <openssl/md5.h>

struct DataPacket {
    int packet_id;
    long timestamp;
    int payload_size;
    bool status;
};

class PacketManager {
private:
    std::vector<DataPacket> packets;
    std::unordered_map<int, size_t> id_to_index;
    std::mutex mutex;
    std::condition_variable cond;

public:
    void addPacket(const DataPacket& packet) {
        std::lock_guard<std::mutex> lock(mutex);
        packets.push_back(packet);
        id_to_index[packet.packet_id] = packets.size() - 1;
        cond.notify_one();
    }

    bool removePacket(int packet_id) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = id_to_index.find(packet_id);
        if (it == id_to_index.end()) return false;

        size_t index = it->second;
        packets[index] = packets.back();
        id_to_index[packets[index].packet_id] = index;
        packets.pop_back();
        id_to_index.erase(it);

        cond.notify_one();
        return true;
    }

    void updateStatus(int packet_id, bool status) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = id_to_index.find(packet_id);
        if (it != id_to_index.end()) {
            packets[it->second].status = status;
        }
    }

    size_t getTotalPackets() const {
        return packets.size();
    }

    void sortPacketsByTimestamp() {
        std::lock_guard<std::mutex> lock(mutex);
        std::sort(packets.begin(), packets.end(), [](const DataPacket& a, const DataPacket& b) {
            return a.timestamp < b.timestamp;
        });
    }
};

void hashFile(const std::string& filePath, size_t chunkSize = 1024 * 1024) {
    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file");
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX md5;
    MD5_Init(&md5);

    while (file.good() && !file.eof()) {
        char buffer[chunkSize];
        file.read(buffer, chunkSize);
        size_t bytesRead = file.gcount();
        MD5_Update(&md5, buffer, bytesRead);
    }
    file.close();

    MD5_Final(digest, &md5);

    std::cout << "MD5: ";
    for (unsigned char i : digest) {
        printf("%02x", i);
    }
    std::cout << std::endl;
}

int main() {
    PacketManager manager;
    // Example usage
    DataPacket packet = {1, 1633072800, 1024, false};
    manager.addPacket(packet);

    hashFile("path_to_your_file.txt");

    return 0;
}
