#include <pthread.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket* packets;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    size_t total_memory_usage;
} PacketManager;

void init_packet_manager(PacketManager* pm) {
    pthread_mutex_init(&pm->lock, NULL);
    pm->packets = NULL;
    pm->size = 0;
    pm->capacity = 0;
    pm->total_memory_usage = 0;
}

void add_packet(PacketManager* pm, DataPacket packet) {
    pthread_mutex_lock(&pm->lock);
    if (pm->size == pm->capacity) {
        size_t new_capacity = pm->capacity ? pm->capacity * 2 : 1;
        DataPacket* new_packets = realloc(pm->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) {
            perror("realloc failed");
            pthread_mutex_unlock(&pm->lock);
            return;
        }
        pm->packets = new_packets;
        pm->capacity = new_capacity;
    }
    pm->packets[pm->size++] = packet;
    pm->total_memory_usage += sizeof(DataPacket);
    pthread_mutex_unlock(&pm->lock);
}

void remove_packet(PacketManager* pm, int packet_id) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->size; ++i) {
        if (pm->packets[i].packet_id == packet_id) {
            memmove(&pm->packets[i], &pm->packets[i + 1], (pm->size - i - 1) * sizeof(DataPacket));
            pm->total_memory_usage -= sizeof(DataPacket);
            --pm->size;
            break;
        }
    }
    pthread_mutex_unlock(&pm->lock);
}

size_t get_packet_count(PacketManager* pm) {
    return pm->size;
}

