struct DataPacket {
    int packet_id;
    std::time_t timestamp;
    size_t payload_size;
    bool status;
};

class DistributedFileSystemManager {
private:
    std::vector<DataPacket> packets;
    std::unordered_map<int, size_t> packetMap;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void addPacket(const DataPacket& packet) {
        std::lock_guard<std::mutex> lock(mtx);
        packets.push_back(packet);
        packetMap[packet.packet_id] = packets.size() - 1;
        cv.notify_one();
    }

    bool removePacket(int packet_id) {
        std::lock_guard<std::mutex> lock(mtx);
        if (packetMap.find(packet_id) != packetMap.end()) {
            size_t index = packetMap[packet_id];
            packets[index] = packets.back();
            packets.pop_back();
            packetMap.erase(packet_id);
            for (auto& pair : packetMap) {
                if (pair.second > index) {
                    pair.second--;
                }
            }
            return true;
        }
        return false;
    }

    bool updateStatus(int packet_id, bool new_status) {
        std::lock_guard<std::mutex> lock(mtx);
        if (packetMap.find(packet_id) != packetMap.end()) {
            packets[packetMap[packet_id]].status = new_status;
            return true;
        }
        return false;
    }

    size_t getTotalPackets() const {
        std::lock_guard<std::mutex> lock(mtx);
        return packets.size();
    }

    void sortPacketsByTimestamp() {
        std::sort(packets.begin(), packets.end(), [](const DataPacket& a, const DataPacket& b) {
            return a.timestamp < b.timestamp;
        });
    }
};

