#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <queue>
#include <mutex>
#include <thread>
#include <openssl/md5.h>

struct DataPacket {
    int packet_id;
    long timestamp;
    size_t payload_size;
    bool status;
};

class DistributedFileSystemManager {
public:
    void addPacket(const DataPacket& packet);
    bool removePacket(int packet_id);
    void updateStatus(int packet_id, bool new_status);
    int getTotalPackets() const;
    void sortPacketsByTimestamp();

private:
    std::map<int, DataPacket> packets;
    std::mutex mutex;
};

void DistributedFileSystemManager::addPacket(const DataPacket& packet) {
    std::lock_guard<std::mutex> lock(mutex);
    packets[packet.packet_id] = packet;
}

bool DistributedFileSystemManager::removePacket(int packet_id) {
    std::lock_guard<std::mutex> lock(mutex);
    if (packets.find(packet_id) != packets.end()) {
        packets.erase(packet_id);
        return true;
    }
    return false;
}

void DistributedFileSystemManager::updateStatus(int packet_id, bool new_status) {
    std::lock_guard<std::mutex> lock(mutex);
    if (packets.find(packet_id) != packets.end()) {
        packets[packet_id].status = new_status;
    }
}

int DistributedFileSystemManager::getTotalPackets() const {
    std::lock_guard<std::mutex> lock(mutex);
    return packets.size();
}

void DistributedFileSystemManager::sortPacketsByTimestamp() {
    std::lock_guard<std::mutex> lock(mutex);
    std::vector<DataPacket> sorted_packets;
    for (const auto& pair : packets) {
        sorted_packets.push_back(pair.second);
    }
    std::sort(sorted_packets.begin(), sorted_packets.end(), [](const DataPacket& a, const DataPacket& b) {
        return a.timestamp < b.timestamp;
    });
    packets.clear();
    for (const auto& packet : sorted_packets) {
        packets[packet.packet_id] = packet;
    }
}

#include <fstream>
#include <cmath>

std::string calculateMD5Hash(const std::string& filePath) {
    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file");
    }

    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5_CTX md5;
    MD5_Init(&md5);

    const size_t bufferSize = 1024 * 1024; // 1MB buffer
    std::vector<char> buffer(bufferSize);
    while (file.read(buffer.data(), bufferSize)) {
        MD5_Update(&md5, buffer.data(), file.gcount());
    }
    if (!file.eof()) {
        throw std::runtime_error("Failed to read file");
    }

    MD5_Final(hash, &md5);

    std::stringstream ss;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
    }

    return ss.str();
}

#include <chrono>
#include <atomic>

void calculateMD5HashWithProgress(const std::string& filePath, std::atomic<bool>& cancel) {
    std::string hash = calculateMD5Hash(filePath);
    if (!cancel.load()) {
        std::cout << "MD5 Hash: " << hash << std::endl;
    }
}

int main() {
    DistributedFileSystemManager dfs_manager;

    // Example usage
    DataPacket packet1{1, 1633072800, 1024, true};
    dfs_manager.addPacket(packet1);

    dfs_manager.sortPacketsByTimestamp();
    std::cout << "Total packets: " << dfs_manager.getTotalPackets() << std::endl;

    return 0;
}
