// Function to process and store CRC indications
int process_and_store_nfa_crc_indications(int N, NFAPI_CRC_INDICATION_PDU_T** indicationArray, int* totalAllocations, int maxElements) {
    if (N > maxElements || N <= 0) {
        return -1; // Invalid input size
    }

    *indicationArray = realloc(*indicationArray, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*indicationArray == NULL) {
        // Handle memory allocation failure
        perror("Memory allocation failed for CRC indications");
        return -2;
    }
    *totalAllocations += N;

    for (int i = 0; i < N; ++i) {
        (*indicationArray)[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        (*indicationArray)[i].RNTI = rand() % 256; // Example range
        (*indicationArray)[i].CRC_INDICATION_REL8_TAG = rand() % 100; // Example range

        // Calculate CRCFLAG based on a checksum of relevant fields
        int checksum = (*indicationArray)[i].RX_UE_INFORMATION_TAG ^ (*indicationArray)[i].RNTI ^ (*indicationArray)[i].CRC_INDICATION_REL8_TAG;
        (*indicationArray)[i].CRCFLAG = (checksum & 0xFF); // Simplified example
    }

    return N; // Return the number of elements stored
}

// Function to modify and allocate a string
char* modify_and_allocate_string(const char* input, int sizeLimit, char* buffer, size_t bufferSize) {
    if (strlen(input) > sizeLimit) {
        return NULL; // String too long
    }

    size_t newLength = strlen(input) + 2; // +1 for slash and +1 for null terminator

    char* resultBuffer;
    if (buffer && bufferSize >= newLength) {
        resultBuffer = buffer;
    } else {
        resultBuffer = realloc(buffer, newLength);
        if (!resultBuffer) {
            perror("Memory allocation failed for string modification");
            return NULL;
        }
    }

    snprintf(resultBuffer, newLength, "%s/", input); // Append slash

    return resultBuffer;
}

// Function to free the allocated buffer
void free_allocated_string(char* buffer) {
    if (buffer) {
        free(buffer);
    }
}
