    if (N <= 0 || start_frame < 0 || end_frame < start_frame || end_frame > INT_MAX) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&lock);
        pdu[i].ue_info[0].tag = rand() % MAX_UE_INFO;
        pdu[i].rnti = malloc(sizeof(RNTI));
        if (pdu[i].rnti == NULL) {
            fprintf(stderr, "Memory allocation failed for rnti.\n");
            free(pdu);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        pdu[i].rnti->rnti = rand() % 1024;
        pdu[i].crc_indication[0].crc_flag = rand() % 2;
        pdu[i].frame_number = start_frame + (rand() % (end_frame - start_frame + 1));
        pthread_mutex_unlock(&lock);
    }

    return pdu;
}

void free_crc_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int N) {
    for (int i = 0; i < N; i++) {
        if (pdu[i].rnti != NULL) {
            free(pdu[i].rnti);
        }
    }
    free(pdu);
}

// Example usage
int main() {
    int N = 100;
    int start_frame = 0;
    int end_frame = 1000;

    NFAPI_CRC_INDICATION_PDU_T *pdu = create_and_populate_crc_pdu(N, start_frame, end_frame);
    if (pdu != NULL) {
        // Use the pdu here
        free_crc_pdu(pdu, N);
    }

    return 0;
}
