typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *items;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    int enable_logging;
} DynamicListT;

void dynamic_list_init(DynamicListT *list, size_t initial_capacity, int enable_logging) {
    list->items = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->items) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
    list->enable_logging = enable_logging;
}

void dynamic_list_add(DynamicListT *list) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 16;
        NFAPI_CRC_INDICATION_PDU_T *new_items = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_items) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        list->items = new_items;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *item = &list->items[list->count++];
    item->RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag generation
    item->RNTI = (rand() % 65535) + 1;
    while (dynamic_list_contains(list, item->RNTI)) {
        item->RNTI = (rand() % 65535) + 1;
    }
    item->CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG

    if (list->enable_logging) {
        log_item_added(item);
    }

    pthread_mutex_unlock(&list->mutex);
}

int dynamic_list_contains(DynamicListT *list, unsigned short rnti) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->items[i].RNTI == rnti) {
            return 1;
        }
    }
    return 0;
}

void dynamic_list_serialize(DynamicListT *list, FILE *file) {
    fwrite(&list->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->count; ++i) {
        fwrite(&list->items[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
}

void dynamic_list_deserialize(DynamicListT *list, FILE *file) {
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_items = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->items, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_items) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        list->items = new_items;
        list->capacity = count;
    }
    list->count = count;

    for (size_t i = 0; i < list->count; ++i) {
        fread(&list->items[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (dynamic_list_contains(list, list->items[i].RNTI)) {
            fprintf(stderr, "Duplicate RNTI detected during deserialization\n");
            exit(EXIT_FAILURE);
        }
    }
}

void dynamic_list_free(DynamicListT *list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->items);
}
