#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1024

typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list[MAX_LIST_SIZE];
    int count;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_list() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_list(DynamicList *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->list[i]);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(uint64_t ue_tag, uint32_t rnti, uint8_t crcflag) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;
    pdu->RX_UE_INFORMATION_TAG = ue_tag;
    pdu->RNTI = rnti;
    pdu->CRCFLAG = crcflag;
    return pdu;
}

void add_pdu(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->count < MAX_LIST_SIZE) {
        list->list[list->count++] = pdu;
    } else {
        printf("Error: List is full\n");
    }
    pthread_mutex_unlock(&list->mutex);
}

void serialize_list(DynamicList *list, FILE *file) {
    fwrite(&list->count, sizeof(int), 1, file);
    for (int i = 0; i < list->count; i++) {
        fwrite(list->list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
}

void deserialize_list(DynamicList *list, FILE *file) {
    int count;
    fread(&count, sizeof(int), 1, file);
    if (count > MAX_LIST_SIZE) {
        printf("Error: List size exceeds maximum\n");
        return;
    }
    for (int i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) continue;
        fread(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        list->list[list->count++] = pdu;
    }
}

int main() {
    DynamicList *list = create_list();
    NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu(0x123456789ABCDEF0, 0xABCD, 0xFF);
    add_pdu(list, pdu);

    FILE *file = fopen("data.bin", "wb");
    if (file) {
        serialize_list(list, file);
        fclose(file);
    }

    destroy_list(list);
    return 0;
}
