typedef struct {
    int session_id;
    char client_ip[16];
    int port;
    int duration;
} NetworkSession;

typedef struct {
    NetworkSession *sessions;
    int count;
    pthread_mutex_t mutex;
    int bandwidth;
} SessionManager;

void init_session_manager(SessionManager *manager) {
    manager->sessions = (NetworkSession *)malloc(sizeof(NetworkSession) * MAX_SESSIONS);
    if (!manager->sessions) {
        perror("Failed to allocate memory for sessions");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->bandwidth = 0;
}

void add_session(SessionManager *manager, NetworkSession session) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count < MAX_SESSIONS) {
        manager->sessions[manager->count++] = session;
    } else {
        fprintf(stderr, "Maximum number of sessions reached\n");
    }
    pthread_mutex_unlock(&manager->mutex);
}

void remove_session(SessionManager *manager, int session_id) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].session_id == session_id) {
            while (i + 1 < manager->count) {
                manager->sessions[i] = manager->sessions[i + 1];
                ++i;
            }
            --manager->count;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

int get_active_sessions(SessionManager *manager, int duration_threshold) {
    pthread_mutex_lock(&manager->mutex);
    int count = 0;
    for (int i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].duration > duration_threshold) {
            ++count;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return count;
}

NetworkSession find_longest_session(SessionManager *manager) {
    NetworkSession longest = {0};
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].duration > longest.duration) {
            longest = manager->sessions[i];
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return longest;
}

void update_bandwidth(SessionManager *manager, int additional_bandwidth) {
    pthread_mutex_lock(&manager->mutex);
    manager->bandwidth += additional_bandwidth;
    pthread_mutex_unlock(&manager->mutex);
}

int get_total_bandwidth(SessionManager *manager) {
    int bandwidth;
    pthread_mutex_lock(&manager->mutex);
    bandwidth = manager->bandwidth;
    pthread_mutex_unlock(&manager->mutex);
    return bandwidth;
}

void destroy_session_manager(SessionManager *manager) {
    pthread_mutex_destroy(&manager->mutex);
    free(manager->sessions);
}
