#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKETS 10000

typedef struct {
    int packet_id;
    long timestamp;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t count;
    size_t capacity;
} PacketManager;

void init_packet_manager(PacketManager *pm) {
    pm->packets = malloc(MAX_PACKETS * sizeof(DataPacket));
    pm->count = 0;
    pm->capacity = MAX_PACKETS;
}

void free_packet_manager(PacketManager *pm) {
    free(pm->packets);
    pm->packets = NULL;
    pm->count = 0;
    pm->capacity = 0;
}

int add_packet(PacketManager *pm, int packet_id, long timestamp, size_t payload_size) {
    if (pm->count >= MAX_PACKETS) return -1; // Packet limit reached
    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i].packet_id == packet_id) return -2; // Duplicate ID
    }
    if (payload_size < 0) return -3; // Negative payload size

    pm->packets[pm->count] = (DataPacket){packet_id, timestamp, payload_size};
    ++pm->count;
    return 0;
}

int remove_packet(PacketManager *pm, int packet_id) {
    for (size_t i = 0; i < pm->count; ++i) {
        if (pm->packets[i].packet_id == packet_id) {
            memmove(&pm->packets[i], &pm->packets[i + 1], (pm->count - i - 1) * sizeof(DataPacket));
            --pm->count;
            return 0;
        }
    }
    return -1; // Packet ID not found
}

size_t get_packet_count(const PacketManager *pm) {
    return pm->count;
}

void sort_packets_by_timestamp(PacketManager *pm) {
    qsort(pm->packets, pm->count, sizeof(DataPacket), [](const void *a, const void *b) {
        return ((DataPacket *)a)->timestamp - ((DataPacket *)b)->timestamp;
    });
}

int main() {
    PacketManager pm;
    init_packet_manager(&pm);

    add_packet(&pm, 1, 123456789, 100);
    add_packet(&pm, 2, 987654321, 200);

    sort_packets_by_timestamp(&pm);

    free_packet_manager(&pm);
    return 0;
}
