            // Handle error or log warning
            pthread_mutex_unlock(&pm->lock);
            return;
        }
    }
    if (pm->count >= pm->capacity) {
        size_t new_capacity = pm->capacity * 2;
        DataPacket* new_packets = realloc(pm->packets, new_capacity * sizeof(DataPacket));
        if (!new_packets) {
            // Handle error or log warning
            pthread_mutex_unlock(&pm->lock);
            return;
        }
        pm->packets = new_packets;
        pm->capacity = new_capacity;
    }
    pm->packets[pm->count++] = packet;
    // Log addition
    pthread_mutex_unlock(&pm->lock);
}

// Implement remove_packet, get_count, sort_packets, limit_packets, and other functions similarly

void destroy_packet_manager(PacketManager* pm) {
    free(pm->packets);
    pthread_mutex_destroy(&pm->lock);
}
