['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct UserSession {
    int session_id;
    char user_name[100];
    time_t last_activity_time;
    int active_status;
    struct UserSession* next;
} UserSession;

typedef struct {
    pthread_mutex_t lock;
    UserSession** buckets;
    size_t bucket_count;
    size_t session_count;
    int max_sessions;
} SessionManager;

void init_session_manager(SessionManager* manager, size_t initial_bucket_count, int max_sessions) {
    manager->bucket_count = initial_bucket_count;
    manager->buckets = (UserSession**)calloc(initial_bucket_count, sizeof(UserSession*));
    manager->session_count = 0;
    manager->max_sessions = max_sessions;
    pthread_mutex_init(&manager->lock, NULL);
}

void insert_session(SessionManager* manager, UserSession* session) {
    pthread_mutex_lock(&manager->lock);

    // Check for uniqueness and active status
    if (manager->session_count >= manager->max_sessions) {
        printf("Maximum number of sessions reached.\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    // Hashing logic to find the bucket index
    size_t hash = session->session_id % manager->bucket_count;
    UserSession* current = manager->buckets[hash];
    while (current) {
        if (current->session_id == session->session_id) {
            printf("Session ID already exists.\n");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        current = current->next;
    }

    // Insert the new session
    session->next = manager->buckets[hash];
    manager->buckets[hash] = session;
    manager->session_count++;

    pthread_mutex_unlock(&manager->lock);
}

void update_session_last_activity(SessionManager* manager, int session_id) {
    pthread_mutex_lock(&manager->lock);

    size_t hash = session_id % manager->bucket_count;
    UserSession* current = manager->buckets[hash];
    while (current) {
        if (current->session_id == session_id) {
            current->last_activity_time = time(NULL);
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

int get_active_session_count(SessionManager* manager) {
    return manager->session_count;
}

void remove_session(SessionManager* manager, int session_id) {
    pthread_mutex_lock(&manager->lock);

    size_t hash = session_id % manager->bucket_count;
    UserSession* current = manager->buckets[hash];
    UserSession* prev = NULL;

    while (current) {
        if (current->session_id == session_id) {
            if (prev) {
                prev->next = current->next;
            } else {
                manager->buckets[hash] = current->next;
            }
            free(current);
            manager->session_count--;
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

void list_active_sessions(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);

    UserSession* all_sessions[1000]; // Assuming max 1000 sessions for simplicity
    size_t count = 0;

    for (size_t i = 0; i < manager->bucket_count; i++) {
        UserSession* current = manager->buckets[i];
        while (current) {
            all_sessions[count++] = current;
            current = current->next;
        }
    }

    qsort(all_sessions, count, sizeof(UserSession*), compare_last_activity_time);

    for (size_t i = 0; i < count; i++) {
        printf("Session ID: %d, User Name: %s, Last Activity Time: %ld\n", 
               all_sessions[i]->session_id, all_sessions[i]->user_name, 
               all_sessions[i]->last_activity_time);
    }

    pthread_mutex_unlock(&manager->lock);
}

int compare_last_activity_time(const void* a, const void* b) {
    UserSession** session_a = (UserSession**)a;
    UserSession** session_b = (UserSession**)b;

    if ((*session_a)->last_activity_time > (*session_b)->last_activity_time) return -1;
    if ((*session_a)->last_activity_time < (*session_b)->last_activity_time) return 1;
    return 0;
}

void destroy_session_manager(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->bucket_count; i++) {
        UserSession* current = manager->buckets[i];
        while (current) {
            UserSession* next = current->next;
            free(current);
            current = next;
        }
    }

    pthread_mutex_destroy(&manager->lock);
    free(manager->buckets);
}

int main() {
    SessionManager manager;
    init_session_manager(&manager, 100, 500);

    // Example usage
    UserSession* session = (UserSession*)malloc(sizeof(UserSession));
    session->session_id = 12345;
    strcpy(session->user_name, "john_doe");
    session->last_activity_time = time(NULL);
    session->active_status = 1;

    insert_session(&manager, session);

    update_session_last_activity(&manager, 12345);

    printf("Active Sessions: %d\n", get_active_session_count(&manager));

    remove_session(&manager, 12345);

    destroy_session_manager(&manager);

    free(session);
    return 0;
}
```']

