#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_SESSIONS 500

typedef struct UserSession {
    int session_id;
    char user_name[100];
    time_t last_activity_time;
    int active_status;
} UserSession;

UserSession* hash_table[MAX_SESSIONS];
int session_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_session(int session_id, const char* user_name, int active_status) {
    pthread_mutex_lock(&lock);
    if (session_count >= MAX_SESSIONS || find_session(session_id)) {
        pthread_mutex_unlock(&lock);
        return;
    }
    UserSession* new_session = (UserSession*)malloc(sizeof(UserSession));
    new_session->session_id = session_id;
    strcpy(new_session->user_name, user_name);
    new_session->last_activity_time = time(NULL);
    new_session->active_status = active_status;
    hash_table[session_id % MAX_SESSIONS] = new_session;
    session_count++;
    pthread_mutex_unlock(&lock);
}

void update_last_activity(int session_id) {
    pthread_mutex_lock(&lock);
    UserSession* session = find_session(session_id);
    if (session) {
        session->last_activity_time = time(NULL);
    }
    pthread_mutex_unlock(&lock);
}

UserSession* find_session(int session_id) {
    return hash_table[session_id % MAX_SESSIONS];
}

void remove_session(int session_id) {
    pthread_mutex_lock(&lock);
    UserSession* session = find_session(session_id);
    if (session) {
        free(session);
        hash_table[session_id % MAX_SESSIONS] = NULL;
        session_count--;
    }
    pthread_mutex_unlock(&lock);
}

void list_sessions() {
    pthread_mutex_lock(&lock);
    // Sort sessions by last_activity_time in descending order
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (hash_table[i]) {
            printf("Session ID: %d, User Name: %s, Last Activity Time: %ld\n", hash_table[i]->session_id, hash_table[i]->user_name, hash_table[i]->last_activity_time);
        }
    }
    pthread_mutex_unlock(&lock);
}

int get_active_session_count() {
    return session_count;
}

void limit_sessions(int max_sessions) {
    while (session_count > max_sessions) {
        // Find and remove the least recently active session
        time_t oldest_time = time(NULL);
        int oldest_id = -1;
        for (int i = 0; i < MAX_SESSIONS; i++) {
            if (hash_table[i] && hash_table[i]->last_activity_time < oldest_time) {
                oldest_time = hash_table[i]->last_activity_time;
                oldest_id = i;
            }
        }
        if (oldest_id != -1) {
            remove_session(oldest_id);
        } else {
            break; // No sessions to remove
        }
    }
}

void* external_notification(void* session) {
    UserSession* s = (UserSession*)session;
    // Send alert to external notification service
    return NULL;
}
