class ResourceRequest {
public:
    int request_id;
    std::string resource_type;
    std::chrono::time_point<std::chrono::system_clock> request_timestamp;
    std::string status;

    ResourceRequest(int id, const std::string& type, std::string status)
        : request_id(id), resource_type(type), status(status) {
        request_timestamp = std::chrono::system_clock::now();
    }
};

class RequestCache {
