    std::condition_variable cv;
    std::atomic<int> active_requests{0};
    static const int max_active_requests = 1000;

public:
    bool add_request(int id, const std::string& type, std::string status) {
        std::unique_lock<std::mutex> lock(mtx);
        if (cache.find(id) != cache.end()) return false; // Check for uniqueness
        if (active_requests >= max_active_requests) return false; // Check for max limit

        ResourceRequest new_request(id, type, status);
        // Simulate rate-limiting check
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        cache[id] = new_request;
        active_requests++;
        cv.notify_one();
        return true;
    }

    bool update_status(int id, const std::string& new_status) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = cache.find(id);
        if (it == cache.end()) return false;

        // Check for outdated request
        auto now = std::chrono::system_clock::now();
        if ((now - it->second.request_timestamp) > std::chrono::seconds(10)) {
            return false;
        }

        it->second.status = new_status;
        cv.notify_one();
        return true;
    }

    int get_active_request_count() const {
        std::lock_guard<std::mutex> lock(mtx);
        return active_requests.load();
    }

    bool remove_request(int id) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = cache.find(id);
        if (it == cache.end()) return false;

        cache.erase(it);
        active_requests--;
        cv.notify_one();
        return true;
    }

    std::vector<ResourceRequest> list_all_active_requests() {
        std::unique_lock<std::mutex> lock(mtx);
        std::vector<ResourceRequest> requests(cache.begin(), cache.end());
        std::sort(requests.begin(), requests.end(),
                  [](const ResourceRequest& a, const ResourceRequest& b) {
                      return a.request_timestamp < b.request_timestamp;
                  });
        return requests;
    }

    void track_and_limit_active_requests() {
        std::unique_lock<std::mutex> lock(mtx);
        while (active_requests > max_active_requests) {
            cv.wait(lock, [this] { return active_requests <= max_active_requests; });
        }
    }

    void log_request_completion(int id, const std::string& result) {
        // Simulate logging to an external service
        std::cout << "Request " << id << " completed with status: " << result << std::endl;
    }
};
