    pm->capacity = initial_capacity;
    pthread_mutex_init(&pm->lock, NULL);
    atomic_init(&pm->total_memory_usage, 0);
}

void add_packet(PacketManager *pm, DataPacket packet) {
    pthread_mutex_lock(&pm->lock);
    if (pm->size >= pm->capacity) {
        size_t new_capacity = pm->capacity == 0 ? 1 : pm->capacity * 2;
        pm->packets = realloc(pm->packets, new_capacity * sizeof(DataPacket));
        if (pm->packets == NULL) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        pm->capacity = new_capacity;
    }
    pm->packets[pm->size++] = packet;
    atomic_fetch_add(&pm->total_memory_usage, sizeof(DataPacket));
    pthread_mutex_unlock(&pm->lock);
}

void remove_packet_by_id(PacketManager *pm, int packet_id) {
    pthread_mutex_lock(&pm->lock);
    for (size_t i = 0; i < pm->size; ++i) {
        if (pm->packets[i].packet_id == packet_id) {
            memmove(&pm->packets[i], &pm->packets[i + 1], (pm->size - i - 1) * sizeof(DataPacket));
            --pm->size;
            atomic_fetch_sub(&pm->total_memory_usage, sizeof(DataPacket));
            break;
        }
    }
    pthread_mutex_unlock(&pm->lock);
}

