    DataPacket(int id, time_t ts, size_t ps, bool stat)
        : packet_id(id), timestamp(ts), payload_size(ps), status(stat) {}
};

class DistributedFileSystemManager {
private:
    std::vector<DataPacket> packets;
    std::unordered_map<int, size_t> packet_index;
    std::mutex mutex;

public:
    void addPacket(const DataPacket& packet) {
        std::lock_guard<std::mutex> lock(mutex);
        packets.push_back(packet);
        packet_index[packet.packet_id] = packets.size() - 1;
    }

    bool removePacket(int packet_id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (packet_index.find(packet_id) == packet_index.end()) return false;

        size_t index = packet_index[packet_id];
        packets[index] = packets.back();
        packet_index[packets[index].packet_id] = index;
        packets.pop_back();
        packet_index.erase(packet_id);
        return true;
    }

    bool updateStatus(int packet_id, bool new_status) {
        std::lock_guard<std::mutex> lock(mutex);
        if (packet_index.find(packet_id) == packet_index.end()) return false;

        size_t index = packet_index[packet_id];
        packets[index].status = new_status;
        return true;
    }

    size_t getTotalPackets() const {
        return packets.size();
    }

    void sortPacketsByTimestamp() {
        std::lock_guard<std::mutex> lock(mutex);
        std::sort(packets.begin(), packets.end(),
                  [](const DataPacket& a, const DataPacket& b) {
                      return a.timestamp < b.timestamp;
                  });
    }
};

