    DistributedFileSystemManager manager;
    manager.addPacket(DataPacket(1, time(nullptr), 1024, true));
    manager.addPacket(DataPacket(2, time(nullptr) + 60, 512, false));

    manager.sortPacketsByTimestamp();
    for (const auto& packet : manager.packets) {
        std::cout << "Packet ID: " << packet.packet_id << ", Timestamp: " << packet.timestamp
                  << ", Payload Size: " << packet.payload_size << ", Status: " << packet.status << std::endl;
    }

    computeMD5("path/to/large/file");

    return 0;
}
