#include <iostream>
#include <vector>
#include <string>
#include <openssl/md5.h>
#include <fstream>
#include <thread>
#include <mutex>

struct DataPacket {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
    bool status;
};

class DistributedFileSystemManager {
private:
    std::vector<DataPacket> packets;
    std::mutex mtx;

public:
    void addPacket(const DataPacket& packet) {
        std::lock_guard<std::mutex> lock(mtx);
        packets.push_back(packet);
    }

    bool removePacket(int packet_id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::remove_if(packets.begin(), packets.end(),
                                 [packet_id](const DataPacket& p){ return p.packet_id == packet_id; });
        if (it != packets.end()) {
            packets.erase(it, packets.end());
            return true;
        }
        return false;
    }

    bool updateStatus(int packet_id, bool status) {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& p : packets) {
            if (p.packet_id == packet_id) {
                p.status = status;
                return true;
            }
        }
        return false;
    }

    size_t getPacketCount() const {
        return packets.size();
    }

    void sortPacketsByTimestamp() {
        std::sort(packets.begin(), packets.end(),
                  [](const DataPacket& a, const DataPacket& b) { return a.timestamp < b.timestamp; });
    }
};

void computeMD5(const std::string& filePath) {
    std::ifstream file(filePath, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filePath << std::endl;
        return;
    }

    MD5_CTX md5;
    MD5_Init(&md5);

    char buffer[4096];
    size_t bytesRead;
    while ((bytesRead = file.read(buffer, sizeof(buffer)).gcount()) > 0) {
        MD5_Update(&md5, buffer, bytesRead);
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &md5);

    std::cout << "MD5 hash: ";
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        printf("%02x", digest[i]);
    }
    std::cout << std::endl;
}

void computeMD5Async(const std::string& filePath, std::function<void()> callback) {
    std::thread([filePath, callback]() {
        computeMD5(filePath);
        callback();
    }).detach();
}
