        : request_id(id), resource_type(type), request_timestamp(timestamp), status(stat) {}
};

class RequestCache {
private:
    std::mutex cache_mutex;
    std::unordered_map<int, ResourceRequest> requests;
    int max_active_requests = 1000;

public:
    void addRequest(int id, const std::string& type, long timestamp, const std::string& stat) {
        std::lock_guard<std::mutex> lock(cache_mutex);
        if (requests.size() >= max_active_requests) return;
        if (requests.find(id) != requests.end()) return;
        requests[id] = ResourceRequest(id, type, timestamp, stat);
    }

    bool updateStatus(int id, const std::string& new_status) {
        std::lock_guard<std::mutex> lock(cache_mutex);
        auto it = requests.find(id);
        if (it == requests.end()) return false;
        it->second.status = new_status;
        return true;
    }

    int getActiveRequestCount() {
        std::lock_guard<std::mutex> lock(cache_mutex);
        return requests.size();
    }

    bool removeRequest(int id) {
        std::lock_guard<std::mutex> lock(cache_mutex);
        auto it = requests.find(id);
        if (it == requests.end()) return false;
        requests.erase(it);
        return true;
    }

    std::vector<ResourceRequest> listAllRequests() {
        std::lock_guard<std::mutex> lock(cache_mutex);
        std::vector<ResourceRequest> sorted_requests(requests.begin(), requests.end());
        std::sort(sorted_requests.begin(), sorted_requests.end(),
                  [](const ResourceRequest& a, const ResourceRequest& b) {
                      return a.request_timestamp < b.request_timestamp;
                  });
        return sorted_requests;
    }

    void limitActiveRequests(int new_limit) {
        std::lock_guard<std::mutex> lock(cache_mutex);
        while (requests.size() > new_limit) {
            auto it = requests.begin();
            requests.erase(it);
        }
        max_active_requests = new_limit;
    }
};
