typedef struct {
    int session_id;
    char client_ip[16];
    int port;
    int duration;
} NetworkSession;

typedef struct {
    NetworkSession *sessions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SessionManager;

void init_session_manager(SessionManager *manager) {
    manager->sessions = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_session(SessionManager *manager, NetworkSession session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        NetworkSession *new_sessions = realloc(manager->sessions, new_capacity * sizeof(NetworkSession));
        if (!new_sessions) {
            pthread_mutex_unlock(&manager->lock);
            return; // Handle error
        }
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }
    manager->sessions[manager->count++] = session;
    pthread_mutex_unlock(&manager->lock);
}

void remove_session(SessionManager *manager, int session_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].session_id == session_id) {
            memmove(&manager->sessions[i], &manager->sessions[i + 1], (manager->count - i - 1) * sizeof(NetworkSession));
            --manager->count;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

size_t get_active_session_count(SessionManager *manager) {
    size_t count = 0;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i].duration > 0) {
            ++count;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return count;
}

NetworkSession *find_longest_session(SessionManager *manager) {
    NetworkSession *longest = NULL;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (!longest || manager->sessions[i].duration > longest->duration) {
            longest = &manager->sessions[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return longest;
}

void destroy_session_manager(SessionManager *manager) {
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}
