LinkedListNode* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    LinkedListNode* node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (node != NULL) {
        memcpy(&node->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        node->next = NULL;
    }
    return node;
}

void free_list(LinkedListNode** head) {
    LinkedListNode* current = *head;
    while (current != NULL) {
        LinkedListNode* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int add_node_safely(LinkedListNode** head, NFAPI_CRC_INDICATION_PDU_T data) {
    static int count = 0;
    if (count >= MAX_RECORDS) {
        log_error("Maximum record limit reached.");
        return -1;
