    while (fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1) {
        if (current == NULL) {
            add_node_safely(head, data);
        } else {
            LinkedListNode* new_node = create_node(data);
            if (new_node != NULL) {
                current->next = new_node;
                current = new_node;
            }
        }
    }
}

