    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to add a new node with random values
Node* addRandomNode(Node** head) {
    // Allocate memory for the new node
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Generate random values for fields within specified ranges
    srand(time(NULL));  // Seed for random number generation
    newNode->data.RX_UE_INFORMATION_TAG = rand() % 1000;  // Example range
    newNode->data.RNTI = rand() % 65536;  // Example range
    newNode->data.CRC_INDICATION_REL8_TAG = rand() % 2;
    newNode->data.CRCFLAG = rand() % 2;

    // Ensure RNTI uniqueness
    Node* current = *head;
    while (current != NULL) {
        if (current->data.RNTI == newNode->data.RNTI) {
            free(newNode);
            return addRandomNode(head);  // Recursively call to re-generate
        }
        current = current->next;
    }

    // Set the next pointer and update head
    newNode->next = *head;
    *head = newNode;

    return newNode;
}

// Function to save the linked list state to a file
void saveLinkedList(Node* head, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

