    while (current != NULL) {
        fprintf(file, "%d %d %d\n", current->data.RX_UE_INFORMATION_TAG,
                current->data.RNTI, current->data.CRCFLAG);
        current = current->next;
    }

    fclose(file);
}

// Function to periodically save the linked list state
void periodicSave(Node* head, const char* filename, int interval) {
    while (1) {
        sleep(interval);  // Sleep for specified interval
        saveLinkedList(head, filename);
    }
}

