    Node* head = NULL;

    // Add random nodes to the linked list
    for (int i = 0; i < 10000; i++) {
        addRandomNode(&head);
    }

    // Save the linked list state periodically
    periodicSave(head, "nfa_pi_crc_indication_pdu_list.txt", 60);  // Save every minute

    return 0;
}
