['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_size;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} PacketList;

void init_packet_list(PacketList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void add_packet(PacketList* list, DataPacket packet) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = packet;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
}

void remove_packet(PacketList* list, int packet_id) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL && current->data.packet_id != packet_id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return; // Packet not found
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->mutex);
}

size_t get_packet_count(PacketList* list) {
    size_t count = 0;
    Node* current = list->head;

    while (current != NULL) {
        count++;
        current = current->next;
    }

    return count;
}

void sort_packets_by_timestamp(PacketList* list) {
    pthread_mutex_lock(&list->mutex);
    // Bubble sort for simplicity, not ideal for large datasets
    int swapped;
    Node* ptr1;
    Node* lptr = NULL;

    do {
        swapped = 0;
        ptr1 = list->head;

        while (ptr1->next != lptr) {
            if (ptr1->data.timestamp > ptr1->next->data.timestamp) {
                DataPacket temp = ptr1->data;
                ptr1->data = ptr1->next->data;
                ptr1->next->data = temp;
                swapped = 1;
            }
            ptr1 = ptr1->next;
        }
        lptr = ptr1;
    } while (swapped);

    pthread_mutex_unlock(&list->mutex);
}

void free_packet_list(PacketList* list) {
    Node* current = list->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);
}
```

