#include <iostream>
#include <vector>
#include <unordered_map>
#include <string>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <random>
#include <atomic>
#include <future>

struct UEConnectionStatus {
    int ueID;
    float signalStrength;
    std::vector<std::string> pduUpdates;
};

class UEConnectionManager {
private:
    std::unordered_map<int, UEConnectionStatus> connections;
    std::queue<std::string> configFetchQueue;
    std::mutex configMutex;
    std::condition_variable configCV;
    bool isConfiguring = false;
    int defaultConfigDir;

    std::random_device rd;
    std::mt19937 gen;
    std::uniform_int_distribution<> intDist;
    std::uniform_real_distribution<float> floatDist;

public:
    UEConnectionManager(int defaultDir) : defaultConfigDir(defaultDir), gen(rd()), intDist(0, 100), floatDist(0.0f, 1.0f) {}

    void addOrUpdateConnection(const UEConnectionStatus& status) {
        std::lock_guard<std::mutex> lock(configMutex);
        connections[status.ueID] = status;
    }

    std::vector<std::string> getLatestPDUUpdates(int ueID) {
        std::lock_guard<std::mutex> lock(configMutex);
        if (connections.find(ueID) != connections.end()) {
            return connections[ueID].pduUpdates;
        }
        return {};
    }

    void fetchConfigurations() {
        while (true) {
            std::unique_lock<std::mutex> lock(configMutex);
            configCV.wait(lock, [this] { return !configFetchQueue.empty() || isConfiguring; });
            if (!isConfiguring && configFetchQueue.empty()) break;
            isConfiguring = true;
            lock.unlock();

            while (!configFetchQueue.empty()) {
                std::string url = configFetchQueue.front();
                configFetchQueue.pop();
                fetchConfiguration(url);
            }

            lock.lock();
            isConfiguring = false;
        }
    }

    void enqueueConfigFetch(const std::string& url) {
        std::lock_guard<std::mutex> lock(configMutex);
        configFetchQueue.push(url);
        configCV.notify_one();
    }

    int getRandomInt(int min, bool inclusive = true) {
        if (inclusive) return intDist(gen);
        return inclusive ? intDist(gen) - 1 : intDist(gen);
    }

    float getRandomFloat(float min, float max) {
        return min + (max - min) * floatDist(gen);
    }

    std::vector<float> getRandomVector3(float minX, float maxX, float minY, float maxY, float minZ, float maxZ) {
        return {getRandomFloat(minX, maxX), getRandomFloat(minY, maxY), getRandomFloat(minZ, maxZ)};
    }

    int getWeightedRandomInt(const std::vector<int>& weights, int maxValue) {
        int totalWeight = 0;
        for (int weight : weights) {
            totalWeight += weight;
        }
        if (totalWeight > maxValue) throw std::invalid_argument("Total weight exceeds max value");

        int randomValue = getRandomInt(1, false);
        int cumulativeWeight = 0;

        for (size_t i = 0; i < weights.size(); ++i) {
            cumulativeWeight += weights[i];
            if (randomValue <= cumulativeWeight) return static_cast<int>(i);
        }

        throw std::runtime_error("Failed to select a weighted random integer");
    }
};
