    size_t capacity;
    size_t size;
} NodeList;

NodeList* init_node_list(size_t initial_capacity, const char* default_str, int min_value, int max_value, int log_level) {
    NodeList* list = malloc(sizeof(NodeList));
    if (!list) {
        perror("Failed to allocate memory for NodeList");
        return NULL;
    }

    list->nodes = malloc(initial_capacity * sizeof(Node));
    if (!list->nodes) {
        free(list);
        perror("Failed to allocate memory for Node array");
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < initial_capacity; ++i) {
        list->nodes[i].str = strdup(default_str);
        if (!list->nodes[i].str) {
            perror("Failed to allocate memory for string");
            free_node_list(list);
            return NULL;
        }

        int value_range = max_value - min_value + 1;
        list->nodes[i].value = rand() % value_range + min_value;

        if (log_level >= 1) {
            printf("Node created: str='%s', value=%d\n", list->nodes[i].str, list->nodes[i].value);
        }
    }

    return list;
}

void free_node_list(NodeList* list) {
    for (size_t i = 0; i < list->capacity; ++i) {
        free(list->nodes[i].str);
    }
    free(list->nodes);
    free(list);
}

int main() {
    NodeList* list = init_node_list(10, "default", 100, 200, 1);
    if (list) {
        // Use the list here...

