#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define DEFAULT_STRING "Default"
#define MIN_INT 10
#define MAX_INT 100
#define MIN_DOUBLE 0.1
#define MAX_DOUBLE 10.0

typedef struct Node {
    char* str;
    int value;
    double precision;
} Node;

typedef struct NodeList {
    Node* nodes;
    size_t capacity;
    size_t size;
} NodeList;

NodeList* create_node_list(size_t initial_capacity) {
    NodeList* list = (NodeList*)malloc(sizeof(NodeList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    list->nodes = (Node*)calloc(initial_capacity, sizeof(Node));
    if (!list->nodes) {
        free(list);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    list->capacity = initial_capacity;
    list->size = 0;
    for (size_t i = 0; i < initial_capacity; ++i) {
        list->nodes[i].str = strdup(DEFAULT_STRING);
        if (!list->nodes[i].str) {
            fprintf(stderr, "Memory allocation failed\n");
            free_node_list(list);
            return NULL;
        }
        list->nodes[i].value = rand() % (MAX_INT - MIN_INT + 1) + MIN_INT;
        list->nodes[i].precision = (double)(rand()) / RAND_MAX * (MAX_DOUBLE - MIN_DOUBLE) + MIN_DOUBLE;
    }
    return list;
}

void free_node_list(NodeList* list) {
    if (!list) return;
    for (size_t i = 0; i < list->size; ++i) {
        free(list->nodes[i].str);
    }
    free(list->nodes);
    free(list);
}

NodeList* resize_node_list(NodeList* list, size_t new_capacity) {
    if (!list || new_capacity <= list->capacity) return list;
    Node* new_nodes = (Node*)realloc(list->nodes, new_capacity * sizeof(Node));
    if (!new_nodes) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (size_t i = list->size; i < new_capacity; ++i) {
        new_nodes[i].str = strdup(DEFAULT_STRING);
        if (!new_nodes[i].str) {
            fprintf(stderr, "Memory allocation failed\n");
            free_node_list(list);
            return NULL;
        }
        new_nodes[i].value = rand() % (MAX_INT - MIN_INT + 1) + MIN_INT;
        new_nodes[i].precision = (double)(rand()) / RAND_MAX * (MAX_DOUBLE - MIN_DOUBLE) + MIN_DOUBLE;
    }
    list->nodes = new_nodes;
    list->capacity = new_capacity;
    return list;
}

void add_node(NodeList* list, const char* str, int value, double precision) {
    if (!list || list->size >= list->capacity) {
        list = resize_node_list(list, list ? 2 * list->capacity : 1);
        if (!list) return;
    }
    list->nodes[list->size].str = strdup(str);
    list->nodes[list->size].value = value;
    list->nodes[list->size].precision = precision;
    ++list->size;
}

void print_node_list(NodeList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        printf("Node %zu: str=%s, value=%d, precision=%.2f\n", i, list->nodes[i].str, list->nodes[i].value, list->nodes[i].precision);
    }
}

int main() {
    srand(time(NULL));
