List* create_list(size_t initial_capacity) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->nodes = (Node*)calloc(initial_capacity, NODE_SIZE);
    if (!list->nodes) {
        free(list);
        return NULL;
    }

    list->initial_capacity = initial_capacity;
    list->capacity = initial_capacity;
    list->count = 0;

    for (size_t i = 0; i < initial_capacity; ++i) {
        list->nodes[i].str = strdup(DEFAULT_STRING);
        if (!list->nodes[i].str) {
            free(list->nodes);
            free(list);
            return NULL;
        }
        list->nodes[i].value = rand() % 100;
        list->nodes[i].dbl_value = (double)(rand() % 10000) / 100.0;
    }

