#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define DEFAULT_NODE_COUNT 10
#define MAX_NODE_NAME_LENGTH 50
#define INITIAL_EDGE_LIST_SIZE 5

typedef struct Node {
    uint64_t id;
    char name[MAX_NODE_NAME_LENGTH];
    struct Edge* relationships;
    int relationship_count;
    int max_relationships;
} Node;

typedef struct Edge {
    Node* target;
} Edge;

Node* create_node(uint64_t id, const char* name) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        return NULL; // Memory allocation failed
    }
    node->id = id;
    strncpy(node->name, name, MAX_NODE_NAME_LENGTH);
    node->relationships = (Edge*)malloc(INITIAL_EDGE_LIST_SIZE * sizeof(Edge));
    if (!node->relationships) {
        free(node);
        return NULL; // Memory allocation failed
    }
    node->relationship_count = 0;
    node->max_relationships = INITIAL_EDGE_LIST_SIZE;
    return node;
}

void add_edge(Node* source, Node* target) {
    if (source->relationship_count == source->max_relationships) {
        Edge* new_edges = (Edge*)realloc(source->relationships, source->max_relationships * 2 * sizeof(Edge));
        if (!new_edges) {
            return; // Memory reallocation failed
        }
        source->relationships = new_edges;
        source->max_relationships *= 2;
    }
    source->relationships[source->relationship_count].target = target;
    source->relationship_count++;
}

void initialize_graph(Node** graph, int* node_count, uint64_t min_id, uint64_t max_id) {
    *node_count = DEFAULT_NODE_COUNT;
    *graph = (Node**)malloc(*node_count * sizeof(Node*));
    if (!*graph) {
        *node_count = 0; // Set to zero on error
        return; // Memory allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < *node_count; i++) {
        uint64_t id;
        do {
            id = min_id + rand() % (max_id - min_id + 1);
        } while (id == (*graph)[i-1]->id); // Ensure unique ID

        (*graph)[i] = create_node(id, "Person");
        if (!(*graph)[i]) {
            for (int j = 0; j < i; j++) {
                free((*graph)[j]->relationships);
                free((*graph)[j]);
            }
            free(*graph);
            *node_count = i;
            return; // Memory allocation failed
        }
    }
}

void traverse_graph(Node** graph, int node_count) {
    for (int i = 0; i < node_count; i++) {
        printf("Node ID: %llu, Name: %s\n", graph[i]->id, graph[i]->name);
        for (int j = 0; j < graph[i]->relationship_count; j++) {
            printf("  Relationship to Node ID: %llu\n", graph[i]->relationships[j].target->id);
        }
    }
}

void free_graph(Node** graph, int node_count) {
    for (int i = 0; i < node_count; i++) {
        free(graph[i]->relationships);
        free(graph[i]);
    }
    free(*graph);
}

int main() {
    Node** graph;
    int node_count;
    initialize_graph(&graph, &node_count, 1000, 9999);

    if (node_count > 0) {
        traverse_graph(graph, node_count);
        free_graph(graph, node_count);
    } else {
        printf("Failed to initialize graph.\n");
    }

    return 0;
}
