    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* init_list(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->nodes = (Node**)malloc(initial_capacity * sizeof(Node*));
    if (!list->nodes) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            free_nodes(list);
            pthread_mutex_destroy(&list->lock);
            free(list);
            return NULL;
        }
        list->nodes[i] = node;
        node->str = strdup("default");
        if (!node->str) {
            free_node(node);
            free_nodes(list);
            pthread_mutex_destroy(&list->lock);
            free(list);
            return NULL;
        }
        node->value = 0;
    }

    return list;
}

void resize_list(DynamicList* list, size_t new_capacity) {
    Node** new_nodes = (Node**)realloc(list->nodes, new_capacity * sizeof(Node*));
    if (!new_nodes) return;

    for (size_t i = list->capacity; i < new_capacity; ++i) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) continue;
        list->nodes[i] = node;
        node->str = strdup("default");
        if (!node->str) {
            free_node(node);
            break;
        }
        node->value = 0;
    }

    list->nodes = new_nodes;
    list->capacity = new_capacity;
}

void add_node(DynamicList* list, const char* text) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity - 1) resize_list(list, list->capacity * 2);

    Node* node = list->nodes[list->size];
    free(node->str);
    size_t length = strlen(text);
    if (length > 10) length = 10;
    node->str = strndup(text + length * list->size % length, length);
    node->value = rand();
    while (list->size > 0 && list->nodes[list->size - 1]->value == node->value)
        node->value = rand();

    ++list->size;
    pthread_mutex_unlock(&list->lock);
}

void free_nodes(DynamicList* list) {
    for (size_t i = 0; i < list->capacity; ++i) {
        free_node(list->nodes[i]);
    }
}

void free_node(Node* node) {
    free(node->str);
    free(node);
}

void destroy_list(DynamicList* list, int free_memory) {
    pthread_mutex_lock(&list->lock);
    free_nodes(list);
    free(list->nodes);
    pthread_mutex_destroy(&list->lock);
    free(list);

    if (free_memory) {
        // Implement memory freeing logic here
    }
}
