#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct Node {
    uint64_t id;
    char* name;
    struct Edge* relationships;
} Node;

typedef struct Edge {
    Node* node;
    struct Edge* next;
} Edge;

typedef struct Graph {
    Node** nodes;
    size_t capacity;
    size_t size;
} Graph;

Graph* create_graph(size_t initial_capacity) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    if (!graph) return NULL;

    graph->nodes = (Node**)calloc(initial_capacity, sizeof(Node*));
    if (!graph->nodes) {
        free(graph);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; ++i) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            for (size_t j = 0; j < i; ++j) free(graph->nodes[j]);
            free(graph->nodes);
            free(graph);
            return NULL;
        }
        graph->nodes[i] = node;
    }

    graph->capacity = initial_capacity;
    graph->size = 0;

    return graph;
}

void resize_graph(Graph* graph, size_t new_capacity) {
    Node** new_nodes = (Node**)realloc(graph->nodes, new_capacity * sizeof(Node*));
    if (!new_nodes) {
        return; // Handle error or use existing nodes
    }
    graph->nodes = new_nodes;
    graph->capacity = new_capacity;

    for (size_t i = graph->size; i < new_capacity; ++i) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            // Handle error or use existing nodes
            break;
        }
        graph->nodes[i] = node;
    }
}

void add_node(Graph* graph, uint64_t id, const char* name) {
    if (graph->size >= graph->capacity) resize_graph(graph, graph->capacity * 2);

    Node* new_node = graph->nodes[graph->size++];
    new_node->id = id;
    new_node->name = strdup(name);
    new_node->relationships = NULL;
}

void free_graph(Graph* graph) {
    for (size_t i = 0; i < graph->size; ++i) {
        Node* node = graph->nodes[i];
        Edge* edge = node->relationships;
        while (edge) {
            Edge* next_edge = edge->next;
            free(edge);
            edge = next_edge;
        }
        free(node->name);
        free(node);
    }
    free(graph->nodes);
    free(graph);
}
