typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t next_index;
    pthread_mutex_t lock;
} MemoryPool_T;

MemoryPool_T* create_memory_pool(size_t initial_size) {
    MemoryPool_T *pool = (MemoryPool_T*)malloc(sizeof(MemoryPool_T));
    if (!pool) return NULL;

    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pool->pool_size = initial_size;
    pool->next_index = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool_T *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->pool);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* get_memory_block(MemoryPool_T *pool) {
    NFAPI_CRC_INDICATION_PDU_T *block = NULL;

    pthread_mutex_lock(&pool->lock);
    if (pool->next_index < pool->pool_size) {
        block = &pool->pool[pool->next_index++];
    }
    pthread_mutex_unlock(&pool->lock);

    return block;
}

void return_memory_block(MemoryPool_T *pool, NFAPI_CRC_INDICATION_PDU_T *block) {
    pthread_mutex_lock(&pool->lock);
    // Logic to handle memory reuse while maintaining thread safety
    pthread_mutex_unlock(&pool->lock);
}

int generate_crc_indications(MemoryPool_T *pool, size_t N, int (*crc_func)(NFAPI_CRC_INDICATION_PDU_T*), void *userdata) {
